-- ############################################################
-- ##  001_base.sql
-- ############################################################

-- ============================================================
-- ORDEN · Gestión financiera
-- Esquema completo para Supabase (PostgreSQL)
-- Ejecutar entero en: Supabase → SQL Editor → New query → Run
-- Es idempotente: se puede volver a ejecutar sin romper nada.
-- ============================================================

create extension if not exists "pgcrypto";

-- ------------------------------------------------------------
-- TIPOS
-- ------------------------------------------------------------
do $$ begin
  create type rol_miembro as enum ('propietario', 'admin', 'vendedor');
exception when duplicate_object then null; end $$;

do $$ begin
  create type tipo_movimiento as enum ('venta', 'gasto', 'ingreso');
exception when duplicate_object then null; end $$;

do $$ begin
  create type origen_captura as enum ('manual', 'texto', 'audio', 'foto');
exception when duplicate_object then null; end $$;

do $$ begin
  create type tipo_meta as enum ('ventas', 'ganancia');
exception when duplicate_object then null; end $$;

-- ------------------------------------------------------------
-- EMPRESAS
-- ------------------------------------------------------------
create table if not exists public.empresas (
  id            uuid primary key default gen_random_uuid(),
  nombre        text not null check (char_length(trim(nombre)) between 2 and 80),
  moneda        text not null default 'PYG' check (moneda in ('PYG', 'USD', 'ARS', 'BRL', 'EUR')),
  codigo_acceso text not null unique,
  plan          text not null default 'gratis' check (plan in ('gratis', 'pro')),
  creada_por    uuid not null references auth.users (id) on delete restrict,
  created_at    timestamptz not null default now()
);

-- ------------------------------------------------------------
-- MIEMBROS (relación usuario ↔ empresa)
-- ------------------------------------------------------------
create table if not exists public.miembros (
  id         uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas (id) on delete cascade,
  user_id    uuid not null references auth.users (id) on delete cascade,
  nombre     text not null default 'Sin nombre',
  rol        rol_miembro not null default 'vendedor',
  created_at timestamptz not null default now(),
  unique (empresa_id, user_id)
);

create index if not exists miembros_user_idx on public.miembros (user_id);

-- ------------------------------------------------------------
-- PRODUCTOS
-- ------------------------------------------------------------
create table if not exists public.productos (
  id             uuid primary key default gen_random_uuid(),
  empresa_id     uuid not null references public.empresas (id) on delete cascade,
  nombre         text not null check (char_length(trim(nombre)) between 1 and 120),
  categoria      text not null default 'General',
  costo          numeric(14,2) not null default 0 check (costo >= 0),
  precio         numeric(14,2) not null default 0 check (precio >= 0),
  stock          numeric(14,2) not null default 0,
  stock_minimo   numeric(14,2) not null default 0 check (stock_minimo >= 0),
  controla_stock boolean not null default true,
  activo         boolean not null default true,
  created_at     timestamptz not null default now(),
  unique (empresa_id, nombre)
);

create index if not exists productos_empresa_idx on public.productos (empresa_id) where activo;

-- ------------------------------------------------------------
-- MOVIMIENTOS (ventas, gastos, otros ingresos)
-- ------------------------------------------------------------
create table if not exists public.movimientos (
  id          uuid primary key default gen_random_uuid(),
  empresa_id  uuid not null references public.empresas (id) on delete cascade,
  tipo        tipo_movimiento not null,
  fecha       date not null default (now() at time zone 'America/Asuncion')::date,
  descripcion text not null default '',
  categoria   text not null default 'General',
  monto       numeric(14,2) not null check (monto >= 0),
  costo_total numeric(14,2) not null default 0 check (costo_total >= 0),
  metodo_pago text not null default 'efectivo',
  contraparte text default '',
  notas       text default '',
  origen      origen_captura not null default 'manual',
  creado_por  uuid references auth.users (id) on delete set null,
  created_at  timestamptz not null default now()
);

create index if not exists movimientos_empresa_fecha_idx on public.movimientos (empresa_id, fecha desc);
create index if not exists movimientos_empresa_tipo_idx on public.movimientos (empresa_id, tipo, fecha desc);

-- ------------------------------------------------------------
-- ITEMS DE MOVIMIENTO (detalle por producto en una venta)
-- Guardamos nombre/costo/precio como "foto del momento" para que
-- el margen histórico no cambie si después editás el producto.
-- ------------------------------------------------------------
create table if not exists public.movimiento_items (
  id              uuid primary key default gen_random_uuid(),
  movimiento_id   uuid not null references public.movimientos (id) on delete cascade,
  empresa_id      uuid not null references public.empresas (id) on delete cascade,
  producto_id     uuid references public.productos (id) on delete set null,
  nombre          text not null,
  cantidad        numeric(14,2) not null check (cantidad > 0),
  precio_unitario numeric(14,2) not null default 0 check (precio_unitario >= 0),
  costo_unitario  numeric(14,2) not null default 0 check (costo_unitario >= 0)
);

create index if not exists items_movimiento_idx on public.movimiento_items (movimiento_id);
create index if not exists items_empresa_idx on public.movimiento_items (empresa_id);

-- ------------------------------------------------------------
-- RETOS / METAS
-- ------------------------------------------------------------
create table if not exists public.retos (
  id           uuid primary key default gen_random_uuid(),
  empresa_id   uuid not null references public.empresas (id) on delete cascade,
  nombre       text not null default 'Mi reto',
  meta         numeric(14,2) not null check (meta > 0),
  medida       tipo_meta not null default 'ventas',
  fecha_inicio date not null,
  fecha_fin    date not null,
  activo       boolean not null default true,
  created_at   timestamptz not null default now(),
  check (fecha_fin >= fecha_inicio)
);

create index if not exists retos_empresa_idx on public.retos (empresa_id) where activo;

-- ------------------------------------------------------------
-- HELPERS DE SEGURIDAD
-- security definer para evitar recursión infinita en las policies
-- ------------------------------------------------------------
create or replace function public.es_miembro(p_empresa uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.miembros m
    where m.empresa_id = p_empresa and m.user_id = auth.uid()
  );
$$;

create or replace function public.es_admin(p_empresa uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.miembros m
    where m.empresa_id = p_empresa
      and m.user_id = auth.uid()
      and m.rol in ('propietario', 'admin')
  );
$$;

-- ------------------------------------------------------------
-- CREAR EMPRESA (genera código y deja al creador como propietario)
-- ------------------------------------------------------------
create or replace function public.crear_empresa(
  p_nombre text,
  p_moneda text default 'PYG',
  p_nombre_usuario text default null
)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_id uuid;
  v_codigo text;
  v_intentos int := 0;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.';
  end if;

  loop
    v_codigo := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
    exit when not exists (select 1 from public.empresas where codigo_acceso = v_codigo);
    v_intentos := v_intentos + 1;
    if v_intentos > 12 then
      raise exception 'No se pudo generar un código de acceso.';
    end if;
  end loop;

  insert into public.empresas (nombre, moneda, codigo_acceso, creada_por)
  values (trim(p_nombre), coalesce(p_moneda, 'PYG'), v_codigo, auth.uid())
  returning id into v_id;

  insert into public.miembros (empresa_id, user_id, nombre, rol)
  values (v_id, auth.uid(), coalesce(nullif(trim(p_nombre_usuario), ''), 'Propietario'), 'propietario');

  return v_id;
end;
$$;

-- ------------------------------------------------------------
-- UNIRSE A EMPRESA CON CÓDIGO
-- ------------------------------------------------------------
create or replace function public.unirse_empresa(
  p_codigo text,
  p_nombre_usuario text default null
)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.';
  end if;

  select id into v_id from public.empresas
  where codigo_acceso = upper(trim(p_codigo));

  if v_id is null then
    raise exception 'El código no corresponde a ninguna empresa.';
  end if;

  insert into public.miembros (empresa_id, user_id, nombre, rol)
  values (v_id, auth.uid(), coalesce(nullif(trim(p_nombre_usuario), ''), 'Colaborador'), 'vendedor')
  on conflict (empresa_id, user_id) do nothing;

  return v_id;
end;
$$;

-- ------------------------------------------------------------
-- REGISTRAR UNA VENTA COMPLETA (movimiento + items + descuento de stock)
-- Todo en una transacción: o entra todo, o no entra nada.
-- p_items: [{"producto_id": uuid|null, "nombre": text, "cantidad": num,
--            "precio_unitario": num, "costo_unitario": num|null}]
-- ------------------------------------------------------------
create or replace function public.registrar_venta(
  p_empresa uuid,
  p_items jsonb,
  p_fecha date default null,
  p_descripcion text default '',
  p_metodo_pago text default 'efectivo',
  p_contraparte text default '',
  p_notas text default '',
  p_origen origen_captura default 'manual',
  p_descuento numeric default 0
)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_mov uuid;
  v_item jsonb;
  v_prod public.productos%rowtype;
  v_total numeric(14,2) := 0;
  v_costo numeric(14,2) := 0;
  v_cant numeric(14,2);
  v_precio numeric(14,2);
  v_costo_u numeric(14,2);
  v_nombre text;
  v_desc numeric(14,2) := greatest(coalesce(p_descuento, 0), 0);
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.';
  end if;

  if p_items is null or jsonb_array_length(p_items) = 0 then
    raise exception 'La venta necesita al menos un producto.';
  end if;

  insert into public.movimientos (empresa_id, tipo, fecha, descripcion, categoria, monto, costo_total, metodo_pago, contraparte, notas, origen, creado_por)
  values (
    p_empresa, 'venta',
    coalesce(p_fecha, (now() at time zone 'America/Asuncion')::date),
    coalesce(p_descripcion, ''), 'Ventas', 0, 0,
    coalesce(nullif(p_metodo_pago, ''), 'efectivo'),
    coalesce(p_contraparte, ''), coalesce(p_notas, ''), p_origen, auth.uid()
  )
  returning id into v_mov;

  for v_item in select * from jsonb_array_elements(p_items) loop
    v_cant := coalesce((v_item ->> 'cantidad')::numeric, 0);
    if v_cant <= 0 then
      raise exception 'La cantidad debe ser mayor a cero.';
    end if;

    v_prod := null;
    if (v_item ->> 'producto_id') is not null and (v_item ->> 'producto_id') <> '' then
      select * into v_prod from public.productos
      where id = (v_item ->> 'producto_id')::uuid and empresa_id = p_empresa;
    end if;

    v_nombre  := coalesce(nullif(trim(v_item ->> 'nombre'), ''), v_prod.nombre, 'Producto');
    v_precio  := coalesce((v_item ->> 'precio_unitario')::numeric, v_prod.precio, 0);
    v_costo_u := coalesce((v_item ->> 'costo_unitario')::numeric, v_prod.costo, 0);

    insert into public.movimiento_items (movimiento_id, empresa_id, producto_id, nombre, cantidad, precio_unitario, costo_unitario)
    values (v_mov, p_empresa, v_prod.id, v_nombre, v_cant, v_precio, v_costo_u);

    v_total := v_total + (v_cant * v_precio);
    v_costo := v_costo + (v_cant * v_costo_u);

    if v_prod.id is not null and v_prod.controla_stock then
      update public.productos set stock = stock - v_cant where id = v_prod.id;
    end if;
  end loop;

  v_desc := least(v_desc, v_total);

  update public.movimientos
  set monto = v_total - v_desc,
      costo_total = v_costo,
      descripcion = case
        when coalesce(trim(descripcion), '') <> '' then descripcion
        else (select string_agg(nombre || ' x' || trim(to_char(cantidad, 'FM999999990.##')), ', ')
              from public.movimiento_items where movimiento_id = v_mov)
      end
  where id = v_mov;

  return v_mov;
end;
$$;

-- ------------------------------------------------------------
-- RLS
-- ------------------------------------------------------------
alter table public.empresas         enable row level security;
alter table public.miembros         enable row level security;
alter table public.productos        enable row level security;
alter table public.movimientos      enable row level security;
alter table public.movimiento_items enable row level security;
alter table public.retos            enable row level security;

-- EMPRESAS: solo ves las tuyas. Se crean vía función crear_empresa().
drop policy if exists empresas_select on public.empresas;
create policy empresas_select on public.empresas
  for select using (public.es_miembro(id));

drop policy if exists empresas_update on public.empresas;
create policy empresas_update on public.empresas
  for update using (public.es_admin(id)) with check (public.es_admin(id));

-- MIEMBROS
drop policy if exists miembros_select on public.miembros;
create policy miembros_select on public.miembros
  for select using (user_id = auth.uid() or public.es_miembro(empresa_id));

drop policy if exists miembros_update on public.miembros;
create policy miembros_update on public.miembros
  for update using (public.es_admin(empresa_id)) with check (public.es_admin(empresa_id));

drop policy if exists miembros_delete on public.miembros;
create policy miembros_delete on public.miembros
  for delete using (public.es_admin(empresa_id) and rol <> 'propietario');

-- PRODUCTOS
drop policy if exists productos_select on public.productos;
create policy productos_select on public.productos
  for select using (public.es_miembro(empresa_id));

drop policy if exists productos_insert on public.productos;
create policy productos_insert on public.productos
  for insert with check (public.es_miembro(empresa_id));

drop policy if exists productos_update on public.productos;
create policy productos_update on public.productos
  for update using (public.es_miembro(empresa_id)) with check (public.es_miembro(empresa_id));

drop policy if exists productos_delete on public.productos;
create policy productos_delete on public.productos
  for delete using (public.es_admin(empresa_id));

-- MOVIMIENTOS
drop policy if exists movimientos_select on public.movimientos;
create policy movimientos_select on public.movimientos
  for select using (public.es_miembro(empresa_id));

drop policy if exists movimientos_insert on public.movimientos;
create policy movimientos_insert on public.movimientos
  for insert with check (public.es_miembro(empresa_id));

drop policy if exists movimientos_update on public.movimientos;
create policy movimientos_update on public.movimientos
  for update using (public.es_admin(empresa_id) or creado_por = auth.uid())
  with check (public.es_miembro(empresa_id));

drop policy if exists movimientos_delete on public.movimientos;
create policy movimientos_delete on public.movimientos
  for delete using (public.es_admin(empresa_id) or creado_por = auth.uid());

-- ITEMS
drop policy if exists items_select on public.movimiento_items;
create policy items_select on public.movimiento_items
  for select using (public.es_miembro(empresa_id));

drop policy if exists items_insert on public.movimiento_items;
create policy items_insert on public.movimiento_items
  for insert with check (public.es_miembro(empresa_id));

drop policy if exists items_delete on public.movimiento_items;
create policy items_delete on public.movimiento_items
  for delete using (public.es_miembro(empresa_id));

-- RETOS
drop policy if exists retos_select on public.retos;
create policy retos_select on public.retos
  for select using (public.es_miembro(empresa_id));

drop policy if exists retos_write on public.retos;
create policy retos_write on public.retos
  for all using (public.es_miembro(empresa_id)) with check (public.es_miembro(empresa_id));

-- ------------------------------------------------------------
-- PERMISOS DE EJECUCIÓN
-- ------------------------------------------------------------
grant execute on function public.crear_empresa(text, text, text) to authenticated;
grant execute on function public.unirse_empresa(text, text)      to authenticated;
grant execute on function public.es_miembro(uuid)                to authenticated;
grant execute on function public.es_admin(uuid)                  to authenticated;
grant execute on function public.registrar_venta(uuid, jsonb, date, text, text, text, text, origen_captura, numeric) to authenticated;


-- ############################################################
-- ##  002_integridad_financiera.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 002 · Integridad financiera
--
-- Objetivo: que los números sean confiables aunque alguien
-- llame a Supabase directamente desde la consola del navegador.
--
-- Cambios principales:
--   1. Las ventas solo se pueden crear/anular con funciones transaccionales.
--   2. El costo de un producto del catálogo lo pone la base, nunca el cliente.
--   3. Las ventas se anulan (con devolución de stock), no se borran.
--   4. subtotal / descuento / total quedan explícitos y coherentes.
--   5. Un vendedor no puede tocar costos, precios, stock ni roles.
--   6. El plan de suscripción no se puede elevar desde el cliente.
--
-- Es idempotente y no borra datos. Se puede ejecutar sobre una
-- instalación existente que ya tenga movimientos cargados.
-- ============================================================

-- ------------------------------------------------------------
-- 1. TIPOS NUEVOS
-- ------------------------------------------------------------
do $$ begin
  create type estado_movimiento as enum ('activo', 'anulado');
exception when duplicate_object then null; end $$;

-- ------------------------------------------------------------
-- 2. EMPRESAS · bandera de stock y protección de campos
-- ------------------------------------------------------------
alter table public.empresas
  add column if not exists permitir_stock_negativo boolean not null default true;

comment on column public.empresas.permitir_stock_negativo is
  'true = se puede vender aunque no haya stock cargado (modo flexible, por defecto). '
  'false = la venta se rechaza si dejaría stock negativo. Preparado para exponerse en Ajustes.';

-- ------------------------------------------------------------
-- 3. SUSCRIPCIONES · la autoridad sobre el plan pasa al backend
-- ------------------------------------------------------------
create table if not exists public.suscripciones (
  id                     uuid primary key default gen_random_uuid(),
  empresa_id             uuid not null unique references public.empresas (id) on delete cascade,
  plan                   text not null default 'gratis' check (plan in ('gratis', 'pro')),
  estado                 text not null default 'activa' check (estado in ('activa', 'prueba', 'vencida', 'cancelada')),
  periodo_inicio         timestamptz,
  periodo_fin            timestamptz,
  proveedor_pago         text,
  customer_id_externo    text,
  subscription_id_externo text,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now()
);

create index if not exists suscripciones_empresa_idx on public.suscripciones (empresa_id);

-- Toda empresa existente arranca con su suscripción espejo del plan actual.
insert into public.suscripciones (empresa_id, plan)
select e.id, e.plan from public.empresas e
on conflict (empresa_id) do nothing;

-- ------------------------------------------------------------
-- 4. MOVIMIENTOS · estado, descuento explícito y auditoría
-- ------------------------------------------------------------
alter table public.movimientos
  add column if not exists estado           estado_movimiento not null default 'activo',
  add column if not exists subtotal         numeric(14,2),
  add column if not exists descuento        numeric(14,2) not null default 0,
  add column if not exists anulado_por      uuid references auth.users (id) on delete set null,
  add column if not exists anulado_at       timestamptz,
  add column if not exists motivo_anulacion text,
  add column if not exists actualizado_por  uuid references auth.users (id) on delete set null,
  add column if not exists updated_at       timestamptz;

-- creado_por se completa solo: así la policy puede exigir que sea el usuario real.
alter table public.movimientos alter column creado_por set default auth.uid();

-- Backfill del subtotal en instalaciones existentes.
-- Antes de esta migración, `monto` ya venía neto de descuento y los items
-- guardaban el precio bruto, así que el subtotal se puede reconstruir.
update public.movimientos m
set subtotal  = greatest(m.monto, coalesce(i.bruto, m.monto)),
    descuento = greatest(coalesce(i.bruto, m.monto) - m.monto, 0)
from (
  select movimiento_id, sum(cantidad * precio_unitario) as bruto
  from public.movimiento_items group by movimiento_id
) i
where i.movimiento_id = m.id and m.subtotal is null;

update public.movimientos
set subtotal = monto, descuento = 0
where subtotal is null;

alter table public.movimientos alter column subtotal set default 0;
alter table public.movimientos alter column subtotal set not null;

-- ------------------------------------------------------------
-- 5. RESTRICCIONES DE COHERENCIA
-- ------------------------------------------------------------
do $$ begin
  alter table public.movimientos
    add constraint movimientos_descuento_valido check (descuento >= 0 and descuento <= subtotal);
exception when duplicate_object then null; end $$;

do $$ begin
  alter table public.movimientos
    add constraint movimientos_total_coherente check (monto = subtotal - descuento);
exception when duplicate_object then null; end $$;

-- Solo una venta puede tener descuento o costo de mercadería.
do $$ begin
  alter table public.movimientos
    add constraint movimientos_solo_venta_descuenta
    check (tipo = 'venta' or (descuento = 0 and costo_total = 0));
exception when duplicate_object then null; end $$;

-- Una anulación siempre deja constancia de quién y cuándo.
do $$ begin
  alter table public.movimientos
    add constraint movimientos_anulacion_auditada
    check (estado = 'activo' or (anulado_por is not null and anulado_at is not null));
exception when duplicate_object then null; end $$;

-- Fechas razonables. El CHECK usa límites fijos porque una restricción no puede
-- depender de current_date (no es inmutable); el margen fino lo aplican la RPC y la policy.
do $$ begin
  alter table public.movimientos
    add constraint movimientos_fecha_razonable
    check (fecha >= date '2000-01-01' and fecha <= date '2100-01-01');
exception when duplicate_object then null; end $$;

-- El item recuerda si realmente movió stock, para devolver exactamente eso al anular.
alter table public.movimiento_items
  add column if not exists afecto_stock boolean not null default false;

-- Backfill imprescindible: las ventas cargadas ANTES de esta migración sí
-- descontaron stock, pero la columna nace en false. Sin esto, anular una venta
-- vieja no devolvería nada al inventario.
--
-- La versión anterior descontaba cuando el item apuntaba a un producto y ese
-- producto controlaba stock, así que reconstruimos con ese mismo criterio.
-- Se ejecuta una sola vez: si ya hay algún item marcado, la migración ya corrió.
do $$
begin
  if not exists (select 1 from public.movimiento_items where afecto_stock) then
    update public.movimiento_items i
    set afecto_stock = true
    from public.productos p, public.movimientos m
    where i.producto_id = p.id
      and i.movimiento_id = m.id
      and m.tipo = 'venta'
      and p.controla_stock;
  end if;
end $$;

do $$ begin
  alter table public.movimiento_items
    add constraint items_precio_valido check (precio_unitario >= 0 and costo_unitario >= 0);
exception when duplicate_object then null; end $$;

create index if not exists movimientos_empresa_estado_idx
  on public.movimientos (empresa_id, estado, fecha desc);

create index if not exists items_producto_idx
  on public.movimiento_items (producto_id) where producto_id is not null;

-- ------------------------------------------------------------
-- 6. TRIGGERS DE CAMPOS PROTEGIDOS
--    Se aplican incluso a los administradores y a las funciones
--    SECURITY DEFINER, así que son la última línea de defensa.
-- ------------------------------------------------------------

-- 6.1 EMPRESAS: identidad y plan intocables desde el cliente.
create or replace function public.proteger_empresa()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.id is distinct from old.id
     or new.creada_por is distinct from old.creada_por
     or new.codigo_acceso is distinct from old.codigo_acceso then
    raise exception 'No se pueden cambiar los datos de identidad de la empresa.' using errcode = '42501';
  end if;

  if new.plan is distinct from old.plan
     and coalesce(current_setting('orden.suscripcion_confiable', true), '') <> '1' then
    raise exception 'El plan solo lo puede cambiar el sistema de suscripciones.' using errcode = '42501';
  end if;

  return new;
end $$;

drop trigger if exists empresas_proteger on public.empresas;
create trigger empresas_proteger
  before update on public.empresas
  for each row execute function public.proteger_empresa();

-- 6.2 MIEMBROS: nadie se asciende a sí mismo ni se muda de empresa.
create or replace function public.proteger_miembro()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.empresa_id is distinct from old.empresa_id or new.user_id is distinct from old.user_id then
    raise exception 'No se puede mover un miembro de empresa ni de usuario.' using errcode = '42501';
  end if;

  if new.rol is distinct from old.rol then
    if old.user_id = auth.uid() then
      raise exception 'No podés cambiar tu propio rol.' using errcode = '42501';
    end if;
    if new.rol = 'propietario' then
      raise exception 'La propiedad de la empresa no se transfiere desde la aplicación.' using errcode = '42501';
    end if;
    if old.rol = 'propietario' then
      raise exception 'No se puede quitar el rol al propietario.' using errcode = '42501';
    end if;
  end if;

  return new;
end $$;

drop trigger if exists miembros_proteger on public.miembros;
create trigger miembros_proteger
  before update on public.miembros
  for each row execute function public.proteger_miembro();

-- 6.3 MOVIMIENTOS y ITEMS: no pueden cambiar de empresa nunca.
create or replace function public.proteger_movimiento()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.empresa_id is distinct from old.empresa_id then
    raise exception 'Un movimiento no puede cambiar de empresa.' using errcode = '42501';
  end if;
  if new.tipo is distinct from old.tipo then
    raise exception 'Un movimiento no puede cambiar de tipo.' using errcode = '42501';
  end if;
  if old.estado = 'anulado' and new.estado = 'activo' then
    raise exception 'Un movimiento anulado no se puede reactivar.' using errcode = '42501';
  end if;
  return new;
end $$;

drop trigger if exists movimientos_proteger on public.movimientos;
create trigger movimientos_proteger
  before update on public.movimientos
  for each row execute function public.proteger_movimiento();

-- 6.4 PRODUCTOS: el producto no cambia de empresa.
create or replace function public.proteger_producto()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.empresa_id is distinct from old.empresa_id then
    raise exception 'Un producto no puede cambiar de empresa.' using errcode = '42501';
  end if;
  return new;
end $$;

drop trigger if exists productos_proteger on public.productos;
create trigger productos_proteger
  before update on public.productos
  for each row execute function public.proteger_producto();

-- ------------------------------------------------------------
-- 7. REGISTRAR VENTA (reescrita)
--
--    Reglas duras:
--    · el costo de un producto del catálogo SIEMPRE sale de productos.costo;
--    · el producto tiene que ser de la misma empresa;
--    · el descuento no puede superar el subtotal (se rechaza, no se recorta);
--    · el stock se mueve con aritmética relativa dentro de la transacción.
-- ------------------------------------------------------------
-- Helper: recorre un array jsonb conservando el orden.
create or replace function public.jsonb_elements_ordenados(p jsonb)
returns setof jsonb language sql immutable as $$
  select valor from jsonb_array_elements(p) with ordinality as t(valor, orden) order by orden;
$$;

create or replace function public.registrar_venta(
  p_empresa uuid,
  p_items jsonb,
  p_fecha date default null,
  p_descripcion text default '',
  p_metodo_pago text default 'efectivo',
  p_contraparte text default '',
  p_notas text default '',
  p_origen origen_captura default 'manual',
  p_descuento numeric default 0
)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_mov       uuid;
  v_item      jsonb;
  v_prod      public.productos%rowtype;
  v_norm      jsonb := '[]'::jsonb;
  v_subtotal  numeric(14,2) := 0;
  v_costo     numeric(14,2) := 0;
  v_desc      numeric(14,2);
  v_cant      numeric(14,2);
  v_precio    numeric(14,2);
  v_costo_u   numeric(14,2);
  v_nombre    text;
  v_pid       uuid;
  v_fecha     date;
  v_permitir  boolean;
  v_stock     numeric(14,2);
  v_metodo    text;
begin
  ------------------------------------------------ autenticación y pertenencia
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  select permitir_stock_negativo into v_permitir from public.empresas where id = p_empresa;
  if not found then
    raise exception 'La empresa no existe.' using errcode = '42501';
  end if;

  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  ------------------------------------------------ validaciones generales
  if p_items is null or jsonb_typeof(p_items) <> 'array' then
    raise exception 'La venta necesita una lista de productos.' using errcode = '22023';
  end if;

  if jsonb_array_length(p_items) = 0 then
    raise exception 'La venta necesita al menos un producto.' using errcode = '22023';
  end if;

  if jsonb_array_length(p_items) > 200 then
    raise exception 'Una venta no puede tener más de 200 líneas.' using errcode = '22023';
  end if;

  v_fecha := coalesce(p_fecha, (now() at time zone 'America/Asuncion')::date);
  if v_fecha < date '2000-01-01' or v_fecha > (now() at time zone 'America/Asuncion')::date + 1 then
    raise exception 'La fecha de la venta no es válida.' using errcode = '22007';
  end if;

  v_metodo := lower(coalesce(nullif(trim(p_metodo_pago), ''), 'efectivo'));
  if v_metodo not in ('efectivo', 'transferencia', 'tarjeta', 'credito', 'otro') then
    raise exception 'La forma de cobro no es válida.' using errcode = '22023';
  end if;

  ------------------------------------------------ primera pasada: validar y normalizar
  for v_item in select * from jsonb_array_elements(p_items) loop
    if jsonb_typeof(v_item) <> 'object' then
      raise exception 'Cada línea de la venta tiene que ser un objeto.' using errcode = '22023';
    end if;

    begin
      v_cant := (v_item ->> 'cantidad')::numeric;
    exception when others then
      raise exception 'La cantidad tiene que ser un número.' using errcode = '22023';
    end;

    if v_cant is null or v_cant <= 0 then
      raise exception 'La cantidad tiene que ser mayor a cero.' using errcode = '22023';
    end if;
    if v_cant > 1000000 then
      raise exception 'La cantidad es demasiado grande.' using errcode = '22023';
    end if;

    v_pid := null;
    if nullif(trim(coalesce(v_item ->> 'producto_id', '')), '') is not null then
      begin
        v_pid := (v_item ->> 'producto_id')::uuid;
      exception when others then
        raise exception 'El identificador del producto no es válido.' using errcode = '22023';
      end;
    end if;

    if v_pid is not null then
      -- El producto tiene que existir Y ser de esta empresa.
      select * into v_prod from public.productos where id = v_pid and empresa_id = p_empresa;
      if not found then
        raise exception 'Ese producto no pertenece a esta empresa.' using errcode = '42501';
      end if;

      v_nombre  := v_prod.nombre;
      -- El precio SÍ puede ser distinto al del catálogo (rebaja puntual, acuerdo con el cliente).
      v_precio  := coalesce(nullif(v_item ->> 'precio_unitario', '')::numeric, v_prod.precio);
      -- El costo NO: siempre el del catálogo. Lo que mande el cliente se descarta.
      v_costo_u := v_prod.costo;
    else
      v_nombre := nullif(trim(coalesce(v_item ->> 'nombre', '')), '');
      if v_nombre is null then
        raise exception 'Cada producto suelto necesita un nombre.' using errcode = '22023';
      end if;
      v_nombre  := left(v_nombre, 120);
      v_precio  := coalesce(nullif(v_item ->> 'precio_unitario', '')::numeric, 0);
      v_costo_u := coalesce(nullif(v_item ->> 'costo_unitario', '')::numeric, 0);
    end if;

    if v_precio is null or v_precio < 0 then
      raise exception 'El precio no puede ser negativo.' using errcode = '22023';
    end if;
    if v_costo_u is null or v_costo_u < 0 then
      raise exception 'El costo no puede ser negativo.' using errcode = '22023';
    end if;

    v_subtotal := v_subtotal + (v_cant * v_precio);
    v_costo    := v_costo + (v_cant * v_costo_u);

    v_norm := v_norm || jsonb_build_object(
      'producto_id', v_pid,
      'nombre', v_nombre,
      'cantidad', v_cant,
      'precio_unitario', v_precio,
      'costo_unitario', v_costo_u,
      'controla_stock', coalesce(v_pid is not null and v_prod.controla_stock, false)
    );
  end loop;

  ------------------------------------------------ descuento
  v_desc := coalesce(p_descuento, 0);
  if v_desc < 0 then
    raise exception 'El descuento no puede ser negativo.' using errcode = '22023';
  end if;
  if v_desc > v_subtotal then
    raise exception 'El descuento no puede ser mayor que el subtotal de la venta.' using errcode = '22023';
  end if;

  ------------------------------------------------ cabecera
  insert into public.movimientos (
    empresa_id, tipo, estado, fecha, descripcion, categoria,
    subtotal, descuento, monto, costo_total,
    metodo_pago, contraparte, notas, origen, creado_por
  )
  values (
    p_empresa, 'venta', 'activo', v_fecha,
    left(coalesce(trim(p_descripcion), ''), 200), 'Ventas',
    v_subtotal, v_desc, v_subtotal - v_desc, v_costo,
    v_metodo, left(coalesce(trim(p_contraparte), ''), 80), left(coalesce(p_notas, ''), 500),
    coalesce(p_origen, 'manual'), auth.uid()
  )
  returning id into v_mov;

  ------------------------------------------------ items y stock
  for v_item in select * from jsonb_elements_ordenados(v_norm) loop
    v_cant := (v_item ->> 'cantidad')::numeric;
    v_pid  := nullif(v_item ->> 'producto_id', '')::uuid;

    if v_pid is not null and (v_item ->> 'controla_stock')::boolean then
      -- Aritmética relativa: dos ventas simultáneas no se pisan.
      update public.productos
        set stock = stock - v_cant
        where id = v_pid
        returning stock into v_stock;

      if not v_permitir and v_stock < 0 then
        raise exception 'No hay stock suficiente de %.', v_item ->> 'nombre' using errcode = '23514';
      end if;
    end if;

    insert into public.movimiento_items (
      movimiento_id, empresa_id, producto_id, nombre, cantidad,
      precio_unitario, costo_unitario, afecto_stock
    )
    values (
      v_mov, p_empresa, v_pid, v_item ->> 'nombre', v_cant,
      (v_item ->> 'precio_unitario')::numeric,
      (v_item ->> 'costo_unitario')::numeric,
      coalesce(v_pid is not null and (v_item ->> 'controla_stock')::boolean, false)
    );
  end loop;

  ------------------------------------------------ descripción automática
  update public.movimientos
  set descripcion = (
    select string_agg(nombre || ' x' || trim(to_char(cantidad, 'FM999999990.##')), ', ')
    from public.movimiento_items where movimiento_id = v_mov
  )
  where id = v_mov and coalesce(trim(descripcion), '') = '';

  return v_mov;
end $$;

-- ------------------------------------------------------------
-- 8. ANULAR MOVIMIENTO
--    Reemplaza al borrado. Devuelve el stock exactamente una vez.
-- ------------------------------------------------------------
create or replace function public.anular_movimiento(
  p_movimiento uuid,
  p_motivo text default null
)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_mov     public.movimientos%rowtype;
  v_item    public.movimiento_items%rowtype;
  v_hoy     date := (now() at time zone 'America/Asuncion')::date;
  v_filas   integer;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  -- El FOR UPDATE serializa dos anulaciones simultáneas del mismo movimiento.
  select * into v_mov from public.movimientos where id = p_movimiento for update;
  if not found then
    raise exception 'El movimiento no existe.' using errcode = '42501';
  end if;

  if not public.es_miembro(v_mov.empresa_id) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if v_mov.estado = 'anulado' then
    raise exception 'Este movimiento ya estaba anulado.' using errcode = '23505';
  end if;

  -- Un vendedor solo anula lo que cargó él y solo el mismo día.
  if not public.es_admin(v_mov.empresa_id)
     and not (v_mov.creado_por = auth.uid() and v_mov.fecha = v_hoy) then
    raise exception 'Solo un administrador puede anular movimientos de otra persona o de días anteriores.'
      using errcode = '42501';
  end if;

  -- Marcamos primero, con guarda de estado: si otra transacción ganó la carrera,
  -- v_filas = 0 y salimos sin tocar el stock.
  update public.movimientos
  set estado = 'anulado',
      anulado_por = auth.uid(),
      anulado_at = now(),
      motivo_anulacion = left(nullif(trim(coalesce(p_motivo, '')), ''), 200)
  where id = v_mov.id and estado = 'activo';

  get diagnostics v_filas = row_count;
  if v_filas = 0 then
    raise exception 'Este movimiento ya estaba anulado.' using errcode = '23505';
  end if;

  -- Devolvemos exactamente el stock que la venta descontó.
  if v_mov.tipo = 'venta' then
    for v_item in
      select * from public.movimiento_items
      where movimiento_id = v_mov.id and afecto_stock and producto_id is not null
    loop
      update public.productos
        set stock = stock + v_item.cantidad
        where id = v_item.producto_id;
    end loop;
  end if;

  return v_mov.id;
end $$;

-- ------------------------------------------------------------
-- 9. REEMPLAZAR VENTA (la "edición" segura)
--    Anula la original y crea una nueva, todo en una transacción.
-- ------------------------------------------------------------
create or replace function public.reemplazar_venta(
  p_movimiento uuid,
  p_items jsonb,
  p_fecha date default null,
  p_descripcion text default '',
  p_metodo_pago text default 'efectivo',
  p_contraparte text default '',
  p_notas text default '',
  p_descuento numeric default 0
)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_orig  public.movimientos%rowtype;
  v_nueva uuid;
begin
  select * into v_orig from public.movimientos where id = p_movimiento;
  if not found or v_orig.tipo <> 'venta' then
    raise exception 'La venta que querés corregir no existe.' using errcode = '42501';
  end if;

  perform public.anular_movimiento(p_movimiento, 'Reemplazada por una corrección');

  v_nueva := public.registrar_venta(
    v_orig.empresa_id, p_items,
    coalesce(p_fecha, v_orig.fecha),
    p_descripcion, p_metodo_pago, p_contraparte, p_notas,
    v_orig.origen, p_descuento
  );

  update public.movimientos
  set actualizado_por = auth.uid(), updated_at = now()
  where id = v_nueva;

  return v_nueva;
end $$;

-- ------------------------------------------------------------
-- 10. APLICAR SUSCRIPCIÓN (solo backend)
--     Única puerta para cambiar el plan. No se otorga a `authenticated`.
-- ------------------------------------------------------------
create or replace function public.aplicar_suscripcion(
  p_empresa uuid,
  p_plan text,
  p_estado text default 'activa',
  p_periodo_inicio timestamptz default null,
  p_periodo_fin timestamptz default null,
  p_proveedor text default null,
  p_customer_id text default null,
  p_subscription_id text default null
)
returns void language plpgsql security definer set search_path = public as $$
begin
  if p_plan not in ('gratis', 'pro') then
    raise exception 'Plan desconocido: %', p_plan using errcode = '22023';
  end if;

  insert into public.suscripciones (
    empresa_id, plan, estado, periodo_inicio, periodo_fin,
    proveedor_pago, customer_id_externo, subscription_id_externo, updated_at
  )
  values (p_empresa, p_plan, p_estado, p_periodo_inicio, p_periodo_fin,
          p_proveedor, p_customer_id, p_subscription_id, now())
  on conflict (empresa_id) do update set
    plan = excluded.plan,
    estado = excluded.estado,
    periodo_inicio = excluded.periodo_inicio,
    periodo_fin = excluded.periodo_fin,
    proveedor_pago = coalesce(excluded.proveedor_pago, public.suscripciones.proveedor_pago),
    customer_id_externo = coalesce(excluded.customer_id_externo, public.suscripciones.customer_id_externo),
    subscription_id_externo = coalesce(excluded.subscription_id_externo, public.suscripciones.subscription_id_externo),
    updated_at = now();

  -- Espejo en empresas.plan para no romper las lecturas existentes.
  perform set_config('orden.suscripcion_confiable', '1', true);
  update public.empresas set plan = p_plan where id = p_empresa;
  perform set_config('orden.suscripcion_confiable', '0', true);
end $$;

-- ------------------------------------------------------------
-- 11. RLS · reconstrucción completa
-- ------------------------------------------------------------
alter table public.suscripciones enable row level security;

-- ---------- EMPRESAS ----------
drop policy if exists empresas_select on public.empresas;
create policy empresas_select on public.empresas
  for select using (public.es_miembro(id));

-- El trigger `empresas_proteger` bloquea plan / código / propiedad.
drop policy if exists empresas_update on public.empresas;
create policy empresas_update on public.empresas
  for update using (public.es_admin(id)) with check (public.es_admin(id));

-- ---------- MIEMBROS ----------
drop policy if exists miembros_select on public.miembros;
create policy miembros_select on public.miembros
  for select using (user_id = auth.uid() or public.es_miembro(empresa_id));

drop policy if exists miembros_update on public.miembros;
create policy miembros_update on public.miembros
  for update using (public.es_admin(empresa_id)) with check (public.es_admin(empresa_id));

drop policy if exists miembros_delete on public.miembros;
create policy miembros_delete on public.miembros
  for delete using (public.es_admin(empresa_id) and rol <> 'propietario' and user_id <> auth.uid());

-- ---------- PRODUCTOS ----------
-- Todos leen; solo propietario/admin escriben. El vendedor nunca toca costo,
-- precio ni stock: el stock lo mueven las RPC de venta y anulación.
drop policy if exists productos_select on public.productos;
create policy productos_select on public.productos
  for select using (public.es_miembro(empresa_id));

drop policy if exists productos_insert on public.productos;
create policy productos_insert on public.productos
  for insert with check (public.es_admin(empresa_id));

drop policy if exists productos_update on public.productos;
create policy productos_update on public.productos
  for update using (public.es_admin(empresa_id)) with check (public.es_admin(empresa_id));

drop policy if exists productos_delete on public.productos;
create policy productos_delete on public.productos
  for delete using (public.es_admin(empresa_id));

-- ---------- MOVIMIENTOS ----------
drop policy if exists movimientos_select on public.movimientos;
create policy movimientos_select on public.movimientos
  for select using (public.es_miembro(empresa_id));

-- Solo gastos y otros ingresos se insertan directo. Las ventas van por RPC.
drop policy if exists movimientos_insert on public.movimientos;
create policy movimientos_insert on public.movimientos
  for insert with check (
    public.es_miembro(empresa_id)
    and tipo <> 'venta'
    and estado = 'activo'
    and creado_por = auth.uid()
    and descuento = 0
    and costo_total = 0
    and subtotal = monto
    and anulado_por is null
    and anulado_at is null
    and fecha >= date '2000-01-01'
    and fecha <= ((now() at time zone 'America/Asuncion')::date + 1)
  );

-- Sin UPDATE ni DELETE desde el cliente: se anula con anular_movimiento().
drop policy if exists movimientos_update on public.movimientos;
drop policy if exists movimientos_delete on public.movimientos;

-- ---------- MOVIMIENTO_ITEMS ----------
-- Solo lectura. Se crean y se borran únicamente dentro de las RPC.
drop policy if exists items_select on public.movimiento_items;
create policy items_select on public.movimiento_items
  for select using (public.es_miembro(empresa_id));

drop policy if exists items_insert on public.movimiento_items;
drop policy if exists items_delete on public.movimiento_items;
drop policy if exists items_update on public.movimiento_items;

-- ---------- RETOS ----------
-- Todos ven la meta; solo propietario/admin la definen.
drop policy if exists retos_write on public.retos;
drop policy if exists retos_select on public.retos;
create policy retos_select on public.retos
  for select using (public.es_miembro(empresa_id));

drop policy if exists retos_insert on public.retos;
create policy retos_insert on public.retos
  for insert with check (public.es_admin(empresa_id));

drop policy if exists retos_update on public.retos;
create policy retos_update on public.retos
  for update using (public.es_admin(empresa_id)) with check (public.es_admin(empresa_id));

drop policy if exists retos_delete on public.retos;
create policy retos_delete on public.retos
  for delete using (public.es_admin(empresa_id));

-- ---------- SUSCRIPCIONES ----------
-- Se leen para saber el plan; no hay ninguna política de escritura,
-- así que `authenticated` no puede insertar ni actualizar nunca.
drop policy if exists suscripciones_select on public.suscripciones;
create policy suscripciones_select on public.suscripciones
  for select using (public.es_miembro(empresa_id));

-- ------------------------------------------------------------
-- 12. PERMISOS DE TABLA Y DE FUNCIÓN
-- ------------------------------------------------------------
revoke all on public.suscripciones from anon, authenticated;
grant select on public.suscripciones to authenticated;

revoke update, delete on public.movimientos from anon, authenticated;
grant select, insert on public.movimientos to authenticated;

revoke insert, update, delete on public.movimiento_items from anon, authenticated;
grant select on public.movimiento_items to authenticated;

grant execute on function public.registrar_venta(uuid, jsonb, date, text, text, text, text, origen_captura, numeric) to authenticated;
grant execute on function public.anular_movimiento(uuid, text) to authenticated;
grant execute on function public.reemplazar_venta(uuid, jsonb, date, text, text, text, text, numeric) to authenticated;
grant execute on function public.jsonb_elements_ordenados(jsonb) to authenticated;

-- El plan solo lo mueve el backend con la clave de servicio.
revoke all on function public.aplicar_suscripcion(uuid, text, text, timestamptz, timestamptz, text, text, text) from public, anon, authenticated;

-- Los triggers no se llaman a mano.
revoke all on function public.proteger_empresa() from public, anon, authenticated;
revoke all on function public.proteger_miembro() from public, anon, authenticated;
revoke all on function public.proteger_movimiento() from public, anon, authenticated;
revoke all on function public.proteger_producto() from public, anon, authenticated;


-- ############################################################
-- ##  003_cierre_permisos.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 003 · Cierre de permisos e información sensible
--
-- Cierra seis huecos que quedaron abiertos después de la 002:
--   1. Las empresas nuevas no creaban su suscripción.
--   2. `service_role` no tenía permiso explícito sobre aplicar_suscripcion().
--   3. El código de acceso viajaba en la fila de `empresas`, o sea que un
--      vendedor podía leerlo aunque la pantalla no se lo mostrara.
--   4. Un vendedor podía leer `productos.costo`, `movimientos.costo_total`
--      y `movimiento_items.costo_unitario` con una consulta directa.
--   5. No existía el concepto de "plan efectivo" (plan + estado + periodo).
--   6. `empresas.plan` era la única lectura posible del plan.
--
-- Idempotente. No borra empresas, movimientos, productos ni usuarios.
--
-- ATENCIÓN — orden de despliegue:
-- Esta migración ELIMINA la columna `empresas.codigo_acceso` (después de
-- copiarla a `empresa_accesos`). Aplicala junto con el código de esta versión,
-- no antes: la versión anterior de la app leía esa columna.
-- ============================================================

-- ------------------------------------------------------------
-- 1. EMPRESA_ACCESOS · el código de invitación sale de `empresas`
--
--    RLS filtra filas, no columnas. Mientras el código viviera en la misma
--    fila que el nombre de la empresa, cualquier miembro que pudiera ver su
--    empresa podía leerlo. Moverlo a su propia tabla permite una policy propia.
-- ------------------------------------------------------------
create table if not exists public.empresa_accesos (
  id         uuid primary key default gen_random_uuid(),
  empresa_id uuid not null unique references public.empresas (id) on delete cascade,
  codigo     text not null unique check (char_length(codigo) between 6 and 24),
  activo     boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists empresa_accesos_codigo_idx on public.empresa_accesos (codigo) where activo;

-- Copiamos los códigos existentes antes de tocar nada.
do $$
begin
  if exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'empresas' and column_name = 'codigo_acceso'
  ) then
    execute $sql$
      insert into public.empresa_accesos (empresa_id, codigo)
      select e.id, e.codigo_acceso from public.empresas e
      where e.codigo_acceso is not null
      on conflict (empresa_id) do nothing
    $sql$;
  end if;
end $$;

-- Cualquier empresa sin código (no debería haber) recibe uno.
insert into public.empresa_accesos (empresa_id, codigo)
select e.id, upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8))
from public.empresas e
where not exists (select 1 from public.empresa_accesos a where a.empresa_id = e.id)
on conflict do nothing;

-- ------------------------------------------------------------
-- 2. SUSCRIPCIÓN PARA TODA EMPRESA (incluidas las que falten)
-- ------------------------------------------------------------
insert into public.suscripciones (empresa_id, plan, estado)
select e.id, coalesce(e.plan, 'gratis'), 'activa'
from public.empresas e
on conflict (empresa_id) do nothing;

-- ------------------------------------------------------------
-- 3. CREAR EMPRESA · ahora crea empresa + miembro + acceso + suscripción
--    Todo en la misma transacción: o entra todo, o no entra nada.
-- ------------------------------------------------------------
create or replace function public.crear_empresa(
  p_nombre text,
  p_moneda text default 'PYG',
  p_nombre_usuario text default null
)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_id uuid;
  v_codigo text;
  v_intentos int := 0;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  if char_length(trim(coalesce(p_nombre, ''))) < 2 then
    raise exception 'El nombre del negocio es muy corto.' using errcode = '22023';
  end if;

  loop
    v_codigo := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
    exit when not exists (select 1 from public.empresa_accesos where codigo = v_codigo);
    v_intentos := v_intentos + 1;
    if v_intentos > 12 then
      raise exception 'No se pudo generar un código de acceso.' using errcode = '55000';
    end if;
  end loop;

  insert into public.empresas (nombre, moneda, creada_por)
  values (trim(p_nombre), coalesce(p_moneda, 'PYG'), auth.uid())
  returning id into v_id;

  insert into public.miembros (empresa_id, user_id, nombre, rol)
  values (v_id, auth.uid(), coalesce(nullif(trim(p_nombre_usuario), ''), 'Propietario'), 'propietario');

  insert into public.empresa_accesos (empresa_id, codigo)
  values (v_id, v_codigo);

  -- Toda empresa nace con su suscripción gratis activa. Sin esto,
  -- plan_efectivo() tendría que adivinar y los pagos futuros tendrían
  -- que crear la fila desde el cliente, que es justo lo que no queremos.
  insert into public.suscripciones (empresa_id, plan, estado)
  values (v_id, 'gratis', 'activa');

  return v_id;
end $$;

-- ------------------------------------------------------------
-- 4. UNIRSE CON CÓDIGO · busca en empresa_accesos
--    Es SECURITY DEFINER, así que funciona sin que el usuario tenga
--    permiso de lectura sobre la tabla. Nadie necesita poder listar
--    códigos para poder usar el que le pasaron.
-- ------------------------------------------------------------
create or replace function public.unirse_empresa(
  p_codigo text,
  p_nombre_usuario text default null
)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  select a.empresa_id into v_id
  from public.empresa_accesos a
  where a.codigo = upper(trim(coalesce(p_codigo, ''))) and a.activo;

  if v_id is null then
    raise exception 'El código no corresponde a ninguna empresa.' using errcode = '42501';
  end if;

  insert into public.miembros (empresa_id, user_id, nombre, rol)
  values (v_id, auth.uid(), coalesce(nullif(trim(p_nombre_usuario), ''), 'Colaborador'), 'vendedor')
  on conflict (empresa_id, user_id) do nothing;

  return v_id;
end $$;

-- ------------------------------------------------------------
-- 5. Recién ahora sacamos la columna vieja.
--    Ya está copiada a empresa_accesos y ninguna función la usa.
-- ------------------------------------------------------------
alter table public.empresas drop column if exists codigo_acceso;

-- El trigger de la 002 controlaba `codigo_acceso` dentro de `empresas`.
-- Si no lo redefinimos, cualquier UPDATE sobre empresas falla con
-- "record new has no field codigo_acceso". La identidad ahora son `id` y
-- `creada_por`; el código está en empresa_accesos, que no tiene ninguna
-- policy de escritura, así que sigue igual de protegido.
create or replace function public.proteger_empresa()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.id is distinct from old.id
     or new.creada_por is distinct from old.creada_por then
    raise exception 'No se pueden cambiar los datos de identidad de la empresa.' using errcode = '42501';
  end if;

  if new.plan is distinct from old.plan
     and coalesce(current_setting('orden.suscripcion_confiable', true), '') <> '1' then
    raise exception 'El plan solo lo puede cambiar el sistema de suscripciones.' using errcode = '42501';
  end if;

  return new;
end $$;

-- ------------------------------------------------------------
-- 6. PLAN EFECTIVO · la única fuente de verdad sobre el acceso Pro
--
--    Regla:
--      · plan 'gratis'                                    → gratis
--      · plan 'pro' + estado 'activa'  y periodo vigente  → pro
--      · plan 'pro' + estado 'prueba'  y periodo vigente  → pro
--      · plan 'pro' + estado 'cancelada' con periodo_fin en el futuro → pro
--        (lo pagado se respeta hasta que termine; al vencer cae a gratis)
--      · plan 'pro' + estado 'vencida'                    → gratis
--      · cualquier plan con periodo_fin ya pasado         → gratis
--      · sin fila de suscripción                          → gratis
--
--    periodo_fin NULL significa "sin vencimiento" (no vence).
-- ------------------------------------------------------------
-- Devuelve SIEMPRE un valor. Si no hay fila de suscripción, la respuesta es
-- 'gratis', nunca NULL: un null podría romper una comparación y regalar acceso.
create or replace function public.plan_efectivo(p_empresa uuid)
returns text language sql stable security definer set search_path = public as $$
  select coalesce((
    select case
      when s.plan <> 'pro' then 'gratis'
      when s.periodo_fin is not null and s.periodo_fin <= now() then 'gratis'
      when s.estado in ('activa', 'prueba') then 'pro'
      when s.estado = 'cancelada' and s.periodo_fin is not null and s.periodo_fin > now() then 'pro'
      else 'gratis'
    end
    from public.suscripciones s
    where s.empresa_id = p_empresa
  ), 'gratis');
$$;

create or replace function public.empresa_es_pro(p_empresa uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(public.plan_efectivo(p_empresa), 'gratis') = 'pro';
$$;

comment on function public.plan_efectivo(uuid) is
  'Única fuente de verdad sobre el plan. empresas.plan es solo un espejo de lectura '
  'rápida y NO debe usarse para habilitar funciones.';

-- Dejamos claro en el esquema que empresas.plan es legado.
comment on column public.empresas.plan is
  'ESPEJO / LEGADO. La autoridad es suscripciones + plan_efectivo(). No usar para dar acceso.';

-- ------------------------------------------------------------
-- 7. COLUMNAS SENSIBLES · el costo no sale de la base para un vendedor
--
--    RLS no filtra columnas, así que usamos privilegios por columna:
--    `authenticated` pierde el SELECT sobre las tres columnas de costo.
--    Ni siquiera un administrador las lee por consulta directa: los costos
--    se sirven por las funciones listar_productos() y listar_movimientos(),
--    que deciden según el rol.
--
--    Esto es lo que hace que ocultarlo en React deje de ser la protección.
-- ------------------------------------------------------------
revoke select on public.productos        from anon, authenticated;
revoke select on public.movimientos      from anon, authenticated;
revoke select on public.movimiento_items from anon, authenticated;

grant select (
  id, empresa_id, nombre, categoria, precio, stock, stock_minimo,
  controla_stock, activo, created_at
) on public.productos to authenticated;

grant select (
  id, empresa_id, tipo, estado, fecha, descripcion, categoria,
  subtotal, descuento, monto, metodo_pago, contraparte, notas, origen,
  creado_por, created_at, anulado_por, anulado_at, motivo_anulacion,
  actualizado_por, updated_at
) on public.movimientos to authenticated;

grant select (
  id, movimiento_id, empresa_id, producto_id, nombre, cantidad,
  precio_unitario, afecto_stock
) on public.movimiento_items to authenticated;

-- El INSERT de gastos e ingresos sigue igual (la policy ya exige costo_total = 0).
grant insert on public.movimientos to authenticated;

-- ------------------------------------------------------------
-- 8. LECTURAS SEGURAS · una sola puerta que decide según el rol
--
--    El frontend deja de hacer `select *` y de ignorar columnas.
--    Estas funciones devuelven exactamente lo que la persona puede ver:
--    los costos vienen en NULL para un vendedor.
-- ------------------------------------------------------------
create or replace function public.listar_productos(
  p_empresa uuid,
  p_incluir_pausados boolean default false
)
returns setof jsonb language plpgsql stable security definer set search_path = public as $$
declare v_admin boolean;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  v_admin := public.es_admin(p_empresa);

  return query
  select to_jsonb(x) from (
    select
      p.id, p.empresa_id, p.nombre, p.categoria,
      case when v_admin then p.costo else null end as costo,
      p.precio, p.stock, p.stock_minimo, p.controla_stock, p.activo, p.created_at
    from public.productos p
    where p.empresa_id = p_empresa
      and (p_incluir_pausados or p.activo)
    order by p.nombre
  ) x;
end $$;

create or replace function public.listar_movimientos(
  p_empresa uuid,
  p_desde date,
  p_hasta date
)
returns setof jsonb language plpgsql stable security definer set search_path = public as $$
declare v_admin boolean;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  v_admin := public.es_admin(p_empresa);

  return query
  select to_jsonb(x) from (
    select
      m.id, m.empresa_id, m.tipo, m.estado, m.fecha, m.descripcion, m.categoria,
      m.subtotal, m.descuento, m.monto,
      case when v_admin then m.costo_total else null end as costo_total,
      m.metodo_pago, m.contraparte, m.notas, m.origen, m.creado_por, m.created_at,
      m.anulado_por, m.anulado_at, m.motivo_anulacion, m.actualizado_por, m.updated_at,
      coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id', i.id,
            'movimiento_id', i.movimiento_id,
            'empresa_id', i.empresa_id,
            'producto_id', i.producto_id,
            'nombre', i.nombre,
            'cantidad', i.cantidad,
            'precio_unitario', i.precio_unitario,
            'costo_unitario', case when v_admin then i.costo_unitario else null end,
            'afecto_stock', i.afecto_stock
          ) order by i.nombre
        )
        from public.movimiento_items i where i.movimiento_id = m.id
      ), '[]'::jsonb) as movimiento_items
    from public.movimientos m
    where m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
    order by m.fecha desc, m.created_at desc
    limit 5000
  ) x;
end $$;

-- Datos de la empresa activa + su plan efectivo, en una sola llamada.
create or replace function public.datos_empresa(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v_res jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'id', e.id,
    'nombre', e.nombre,
    'moneda', e.moneda,
    'plan_efectivo', public.plan_efectivo(e.id),
    'permitir_stock_negativo', e.permitir_stock_negativo,
    -- El código solo viaja si quien pregunta puede administrarlo.
    'codigo_acceso', case
      when public.es_admin(e.id) then (select a.codigo from public.empresa_accesos a where a.empresa_id = e.id and a.activo)
      else null
    end
  ) into v_res
  from public.empresas e where e.id = p_empresa;

  return v_res;
end $$;

-- ------------------------------------------------------------
-- 9. RLS DE LAS TABLAS NUEVAS
-- ------------------------------------------------------------
alter table public.empresa_accesos enable row level security;

-- Solo propietario y admin ven el código. El vendedor no, ni por consulta directa.
drop policy if exists empresa_accesos_select on public.empresa_accesos;
create policy empresa_accesos_select on public.empresa_accesos
  for select using (public.es_admin(empresa_id));

-- Sin policies de escritura: el código lo crea crear_empresa().
revoke all on public.empresa_accesos from anon, authenticated;
grant select on public.empresa_accesos to authenticated;

-- ------------------------------------------------------------
-- 10. PERMISOS DE FUNCIÓN
-- ------------------------------------------------------------
grant execute on function public.listar_productos(uuid, boolean)   to authenticated;
grant execute on function public.listar_movimientos(uuid, date, date) to authenticated;
grant execute on function public.datos_empresa(uuid)               to authenticated;
grant execute on function public.plan_efectivo(uuid)               to authenticated;
grant execute on function public.empresa_es_pro(uuid)              to authenticated;
grant execute on function public.crear_empresa(text, text, text)   to authenticated;
grant execute on function public.unirse_empresa(text, text)        to authenticated;

-- El plan lo mueve únicamente el backend con la clave de servicio.
-- `revoke from public` no alcanza: hay que otorgárselo explícitamente a service_role.
revoke all on function public.aplicar_suscripcion(uuid, text, text, timestamptz, timestamptz, text, text, text)
  from public, anon, authenticated;
grant execute on function public.aplicar_suscripcion(uuid, text, text, timestamptz, timestamptz, text, text, text)
  to service_role;

-- service_role también necesita poder leer/escribir las tablas de suscripción
-- para tareas de mantenimiento (vencer periodos, conciliar). Las funciones
-- SECURITY DEFINER no lo requieren, pero un job del backend sí.
grant select, insert, update on public.suscripciones to service_role;
grant select on public.empresas to service_role;


-- ############################################################
-- ##  004_lecturas_consistentes.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 004 · Consistencia final de lecturas
--
-- Dos correcciones sobre la 003:
--
--   1. `listar_movimientos()` tenía `limit 5000`. Si un negocio superaba esa
--      cantidad en el periodo consultado, el panel, los reportes, el reto y el
--      Excel mostraban totales incompletos SIN avisar. Un número financiero
--      incorrecto y silencioso es peor que un error.
--
--   2. `plan_efectivo()` y `empresa_es_pro()` estaban otorgadas a
--      `authenticated` sin comprobar pertenencia: cualquier usuario con sesión
--      podía averiguar el plan de cualquier empresa pasando su UUID.
--
-- Idempotente. No toca datos.
-- ============================================================

-- ------------------------------------------------------------
-- 1. PLAN EFECTIVO · separar el cálculo del control de acceso
--
--    La lógica pasa a una función interna que NO se otorga a nadie.
--    Las funciones públicas comprueban pertenencia antes de responder.
-- ------------------------------------------------------------
create or replace function public.plan_efectivo_calculado(p_empresa uuid)
returns text language sql stable security definer set search_path = public as $$
  select coalesce((
    select case
      when s.plan <> 'pro' then 'gratis'
      when s.periodo_fin is not null and s.periodo_fin <= now() then 'gratis'
      when s.estado in ('activa', 'prueba') then 'pro'
      when s.estado = 'cancelada' and s.periodo_fin is not null and s.periodo_fin > now() then 'pro'
      else 'gratis'
    end
    from public.suscripciones s
    where s.empresa_id = p_empresa
  ), 'gratis');
$$;

comment on function public.plan_efectivo_calculado(uuid) is
  'Cálculo puro del plan, SIN control de acceso. No se otorga a authenticated: '
  'la usan plan_efectivo() y datos_empresa(), que ya comprobaron pertenencia.';

-- Versión pública: primero verifica que quien pregunta sea de la empresa.
create or replace function public.plan_efectivo(p_empresa uuid)
returns text language plpgsql stable security definer set search_path = public as $$
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  return public.plan_efectivo_calculado(p_empresa);
end $$;

create or replace function public.empresa_es_pro(p_empresa uuid)
returns boolean language plpgsql stable security definer set search_path = public as $$
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  return public.plan_efectivo_calculado(p_empresa) = 'pro';
end $$;

-- datos_empresa() ya comprobó pertenencia, así que usa el cálculo directo.
create or replace function public.datos_empresa(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v_res jsonb;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'id', e.id,
    'nombre', e.nombre,
    'moneda', e.moneda,
    'plan_efectivo', public.plan_efectivo_calculado(e.id),
    'permitir_stock_negativo', e.permitir_stock_negativo,
    -- El código solo viaja si quien pregunta puede administrarlo.
    'codigo_acceso', case
      when public.es_admin(e.id) then (select a.codigo from public.empresa_accesos a where a.empresa_id = e.id and a.activo)
      else null
    end
  ) into v_res
  from public.empresas e where e.id = p_empresa;

  return v_res;
end $$;

-- ------------------------------------------------------------
-- 2. LISTAR MOVIMIENTOS · nunca truncar en silencio
--
--    Si el periodo tiene más movimientos de los que se pueden devolver de una
--    vez, la función FALLA con un mensaje claro en vez de entregar totales
--    incompletos. El tope es alto (20.000): un negocio chico no lo alcanza ni
--    con un año entero, y quien lo alcance recibe una instrucción concreta.
-- ------------------------------------------------------------
create or replace function public.listar_movimientos(
  p_empresa uuid,
  p_desde date,
  p_hasta date
)
returns setof jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_admin boolean;
  v_total bigint;
  v_tope  constant integer := 20000;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  -- Contamos ANTES de devolver nada. Si no entra, avisamos en vez de recortar:
  -- un total incompleto sin aviso es un número equivocado.
  select count(*) into v_total
  from public.movimientos m
  where m.empresa_id = p_empresa and m.fecha between p_desde and p_hasta;

  if v_total > v_tope then
    raise exception
      'El periodo elegido tiene % movimientos y el máximo por consulta es %. Elegí un rango más corto para que los totales sean exactos.',
      v_total, v_tope
      using errcode = '54000';
  end if;

  v_admin := public.es_admin(p_empresa);

  return query
  select to_jsonb(x) from (
    select
      m.id, m.empresa_id, m.tipo, m.estado, m.fecha, m.descripcion, m.categoria,
      m.subtotal, m.descuento, m.monto,
      case when v_admin then m.costo_total else null end as costo_total,
      m.metodo_pago, m.contraparte, m.notas, m.origen, m.creado_por, m.created_at,
      m.anulado_por, m.anulado_at, m.motivo_anulacion, m.actualizado_por, m.updated_at,
      coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id', i.id,
            'movimiento_id', i.movimiento_id,
            'empresa_id', i.empresa_id,
            'producto_id', i.producto_id,
            'nombre', i.nombre,
            'cantidad', i.cantidad,
            'precio_unitario', i.precio_unitario,
            'costo_unitario', case when v_admin then i.costo_unitario else null end,
            'afecto_stock', i.afecto_stock
          ) order by i.nombre
        )
        from public.movimiento_items i where i.movimiento_id = m.id
      ), '[]'::jsonb) as movimiento_items
    from public.movimientos m
    where m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
    order by m.fecha desc, m.created_at desc
  ) x;
end $$;

-- ------------------------------------------------------------
-- 3. PERMISOS
-- ------------------------------------------------------------
-- El cálculo interno no se expone: solo lo usan funciones que ya controlaron acceso.
revoke all on function public.plan_efectivo_calculado(uuid) from public, anon, authenticated;

grant execute on function public.plan_efectivo(uuid)                  to authenticated;
grant execute on function public.empresa_es_pro(uuid)                 to authenticated;
grant execute on function public.datos_empresa(uuid)                  to authenticated;
grant execute on function public.listar_movimientos(uuid, date, date) to authenticated;

-- El backend sí puede consultar el plan de cualquier empresa (jobs de
-- vencimiento, conciliación de pagos): para eso usa el cálculo directo.
grant execute on function public.plan_efectivo_calculado(uuid) to service_role;


-- ############################################################
-- ##  005_lecturas_escalables.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 005 · Lecturas escalables
--
-- Problema: hasta acá, panel, reportes, reto y Excel pedían TODOS los
-- movimientos del periodo y sumaban en JavaScript. La 004 evitó que
-- PostgreSQL truncara en silencio, pero entre PostgreSQL y el navegador hay
-- otra capa —PostgREST / Data API— que aplica su propio máximo de filas
-- (`db-max-rows`, típicamente 1.000). Si ese tope se activa, el cliente
-- recibe menos filas de las que hay y suma un total incompleto sin enterarse.
--
-- Solución: separar mostrar de calcular.
--   · CALCULAR  → agregaciones en PostgreSQL que devuelven pocas filas.
--                 Un tope de 1.000 filas no puede afectar a algo que
--                 devuelve 1 objeto o 30 categorías.
--   · MOSTRAR   → historial paginado con cursor estable.
--
-- Las reglas financieras son exactamente las mismas que en calculos.ts:
--   ventas = monto (neto de descuento) · anuladas no suman ·
--   ganancia bruta = ventas − costo histórico ·
--   ganancia neta = bruta + otros ingresos − gastos ·
--   descuento prorrateado por peso de cada línea.
--
-- Idempotente. No toca datos.
-- ============================================================

-- ------------------------------------------------------------
-- 1. RESUMEN FINANCIERO · un solo objeto, sin importar el volumen
--
--    Los campos sensibles (costo, ganancias, márgenes) vienen en NULL para
--    quien no puede verlos. Nunca en cero: null no es cero.
-- ------------------------------------------------------------
create or replace function public.resumen_financiero(
  p_empresa uuid,
  p_desde date,
  p_hasta date
)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_admin boolean;
  v_res   jsonb;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  v_admin := public.es_admin(p_empresa);

  with base as (
    select m.tipo, m.estado, m.monto, m.subtotal, m.costo_total, m.id
    from public.movimientos m
    where m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
  ),
  totales as (
    select
      coalesce(sum(monto)       filter (where estado = 'activo' and tipo = 'venta'),   0)::numeric as ventas,
      coalesce(sum(subtotal)    filter (where estado = 'activo' and tipo = 'venta'),   0)::numeric as ventas_brutas,
      coalesce(sum(costo_total) filter (where estado = 'activo' and tipo = 'venta'),   0)::numeric as costo_mercaderia,
      coalesce(sum(monto)       filter (where estado = 'activo' and tipo = 'ingreso'), 0)::numeric as otros_ingresos,
      coalesce(sum(monto)       filter (where estado = 'activo' and tipo = 'gasto'),   0)::numeric as gastos,
      coalesce(count(*)         filter (where estado = 'activo' and tipo = 'venta'),   0)::bigint  as cantidad_ventas,
      coalesce(count(*)         filter (where estado = 'anulado' and tipo = 'venta'),  0)::bigint  as ventas_anuladas,
      coalesce(sum(monto)       filter (where estado = 'anulado' and tipo = 'venta'),  0)::numeric as monto_ventas_anuladas,
      coalesce(count(*)         filter (where estado = 'anulado'),                     0)::bigint  as movimientos_anulados,
      coalesce(sum(monto)       filter (where estado = 'anulado'),                     0)::numeric as monto_movimientos_anulados
    from base
  ),
  unidades as (
    -- Solo de ventas válidas. Se cuenta acá y no en `base` para no multiplicar
    -- los montos de la cabecera por la cantidad de líneas.
    select coalesce(sum(i.cantidad), 0)::numeric as unidades
    from public.movimiento_items i
    join public.movimientos m on m.id = i.movimiento_id
    -- El filtro por empresa va también sobre los items. Es redundante (un item
    -- siempre pertenece a la misma empresa que su movimiento, y hay una prueba
    -- que lo verifica), pero le permite al planificador entrar por el índice
    -- de items en vez de recorrer la tabla entera. Medido: 7 veces más rápido.
    where i.empresa_id = p_empresa
      and m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
      and m.estado = 'activo'
      and m.tipo = 'venta'
  ),
  derivados as (
    select
      t.*,
      u.unidades,
      (t.ventas + t.otros_ingresos) as ingresos_totales,
      (t.ventas - t.costo_mercaderia) as ganancia_bruta,
      (t.ventas - t.costo_mercaderia + t.otros_ingresos - t.gastos) as ganancia_neta
    from totales t cross join unidades u
  )
  select jsonb_build_object(
    'ventas',                     d.ventas,
    'ventas_brutas',              d.ventas_brutas,
    'descuentos',                 d.ventas_brutas - d.ventas,
    'otros_ingresos',             d.otros_ingresos,
    'ingresos_totales',           d.ingresos_totales,
    'gastos',                     d.gastos,
    'cantidad_ventas',            d.cantidad_ventas,
    'unidades_vendidas',          d.unidades,
    'ticket_promedio',            case when d.cantidad_ventas > 0 then d.ventas / d.cantidad_ventas else 0 end,
    'ventas_anuladas',            d.ventas_anuladas,
    'monto_ventas_anuladas',      d.monto_ventas_anuladas,
    'movimientos_anulados',       d.movimientos_anulados,
    'monto_movimientos_anulados', d.monto_movimientos_anulados,
    -- A partir de acá, solo para quien puede ver rentabilidad.
    'costo_mercaderia', case when v_admin then d.costo_mercaderia else null end,
    'ganancia_bruta',   case when v_admin then d.ganancia_bruta   else null end,
    'ganancia_neta',    case when v_admin then d.ganancia_neta    else null end,
    'margen_bruto',     case when v_admin and d.ventas > 0
                             then (d.ganancia_bruta / d.ventas) * 100 else null end,
    'margen_neto',      case when v_admin and d.ingresos_totales > 0
                             then (d.ganancia_neta / d.ingresos_totales) * 100 else null end,
    'con_costos',       v_admin
  ) into v_res
  from derivados d;

  return v_res;
end $$;

-- ------------------------------------------------------------
-- 2. RANKING DE PRODUCTOS · agregado sobre todas las ventas válidas
--
--    El descuento se reparte proporcionalmente al peso de cada línea dentro
--    del subtotal de su venta: exactamente la misma política que calculos.ts.
--    Por eso la suma de `ingresos` reconcilia con `resumen.ventas`.
-- ------------------------------------------------------------
create or replace function public.ranking_productos(
  p_empresa uuid,
  p_desde date,
  p_hasta date,
  p_limite integer default null
)
returns setof jsonb language plpgsql stable security definer set search_path = public as $$
declare v_admin boolean;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  v_admin := public.es_admin(p_empresa);

  return query
  with lineas as (
    select
      -- Misma clave de agrupación que calculos.ts: por producto del catálogo,
      -- o por nombre normalizado si fue una venta suelta.
      coalesce(i.producto_id::text, 'libre:' || lower(trim(i.nombre))) as clave,
      i.producto_id,
      i.nombre,
      i.cantidad,
      i.cantidad * i.precio_unitario as bruto,
      i.cantidad * i.precio_unitario * coalesce(m.monto / nullif(m.subtotal, 0), 1) as neto,
      i.cantidad * i.costo_unitario as costo,
      m.fecha,
      m.created_at
    from public.movimiento_items i
    join public.movimientos m on m.id = i.movimiento_id
    -- Mismo motivo que en resumen_financiero: filtrar los items por empresa
    -- evita un recorrido completo de movimiento_items.
    where i.empresa_id = p_empresa
      and m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
      and m.estado = 'activo'
      and m.tipo = 'venta'
  ),
  agrupado as (
    select
      clave,
      -- El nombre de la línea más reciente, igual que hace la versión de
      -- TypeScript recorriendo los movimientos en orden descendente.
      (array_agg(nombre order by fecha desc, created_at desc))[1] as nombre,
      (array_agg(producto_id order by fecha desc, created_at desc))[1] as producto_id,
      sum(cantidad)::numeric as unidades,
      sum(bruto)::numeric    as ingresos_brutos,
      sum(neto)::numeric     as ingresos,
      sum(costo)::numeric    as costo,
      count(*)::bigint       as operaciones
    from lineas
    group by clave
  ),
  con_total as (
    select a.*, sum(a.ingresos) over () as total_ingresos
    from agrupado a
  )
  select jsonb_build_object(
    'producto_id',     c.producto_id,
    'nombre',          c.nombre,
    'unidades',        c.unidades,
    'ingresos_brutos', c.ingresos_brutos,
    'descuento',       c.ingresos_brutos - c.ingresos,
    'ingresos',        c.ingresos,
    'operaciones',     c.operaciones,
    'participacion',   case when c.total_ingresos > 0 then (c.ingresos / c.total_ingresos) * 100 else 0 end,
    'costo',    case when v_admin then c.costo else null end,
    'ganancia', case when v_admin then c.ingresos - c.costo else null end,
    'margen',   case when v_admin and c.ingresos > 0
                     then ((c.ingresos - c.costo) / c.ingresos) * 100 else null end
  )
  from con_total c
  order by c.ingresos desc
  limit case when p_limite is null or p_limite <= 0 then null else p_limite end;
end $$;

-- ------------------------------------------------------------
-- 3. SERIE DIARIA · una fila por día, con o sin ganancia según el rol
-- ------------------------------------------------------------
create or replace function public.serie_financiera_diaria(
  p_empresa uuid,
  p_desde date,
  p_hasta date
)
returns setof jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_admin boolean;
  v_dias  integer;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  v_dias := (p_hasta - p_desde) + 1;
  if v_dias > 1100 then
    raise exception 'El rango no puede superar los 3 años para la serie diaria.' using errcode = '22023';
  end if;

  v_admin := public.es_admin(p_empresa);

  return query
  with dias as (
    select generate_series(p_desde, p_hasta, interval '1 day')::date as fecha
  ),
  porDia as (
    select
      m.fecha,
      coalesce(sum(m.monto)       filter (where m.tipo = 'venta'), 0)::numeric   as ventas,
      coalesce(sum(m.monto)       filter (where m.tipo = 'gasto'), 0)::numeric   as gastos,
      coalesce(sum(m.monto)       filter (where m.tipo = 'ingreso'), 0)::numeric as otros_ingresos,
      coalesce(sum(m.costo_total) filter (where m.tipo = 'venta'), 0)::numeric   as costo
    from public.movimientos m
    where m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
      and m.estado = 'activo'
    group by m.fecha
  )
  select jsonb_build_object(
    'fecha',          to_char(d.fecha, 'YYYY-MM-DD'),
    'ventas',         coalesce(p.ventas, 0),
    'gastos',         coalesce(p.gastos, 0),
    'otros_ingresos', coalesce(p.otros_ingresos, 0),
    'ganancia', case
      when v_admin then coalesce(p.ventas, 0) - coalesce(p.costo, 0)
                      + coalesce(p.otros_ingresos, 0) - coalesce(p.gastos, 0)
      else null
    end
  )
  from dias d
  left join porDia p on p.fecha = d.fecha
  order by d.fecha;
end $$;

-- ------------------------------------------------------------
-- 4. GASTOS POR CATEGORÍA
-- ------------------------------------------------------------
create or replace function public.gastos_por_categoria(
  p_empresa uuid,
  p_desde date,
  p_hasta date
)
returns setof jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  return query
  with porCategoria as (
    select
      trim(coalesce(nullif(trim(m.categoria), ''), 'General')) as nombre,
      sum(m.monto)::numeric as monto,
      count(*)::bigint      as operaciones
    from public.movimientos m
    where m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
      and m.estado = 'activo'
      and m.tipo = 'gasto'
    group by 1
  ),
  con_total as (
    select c.*, sum(c.monto) over () as total from porCategoria c
  )
  select jsonb_build_object(
    'nombre',        c.nombre,
    'monto',         c.monto,
    'operaciones',   c.operaciones,
    'participacion', case when c.total > 0 then (c.monto / c.total) * 100 else 0 end
  )
  from con_total c
  order by c.monto desc;
end $$;

-- ------------------------------------------------------------
-- 5. COBROS POR MÉTODO · todo lo que entró (ventas y otros ingresos)
-- ------------------------------------------------------------
create or replace function public.cobros_por_metodo(
  p_empresa uuid,
  p_desde date,
  p_hasta date
)
returns setof jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  return query
  with porMetodo as (
    select m.metodo_pago as metodo, sum(m.monto)::numeric as monto
    from public.movimientos m
    where m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
      and m.estado = 'activo'
      and m.tipo <> 'gasto'
    group by m.metodo_pago
  ),
  con_total as (
    select p.*, sum(p.monto) over () as total from porMetodo p
  )
  select jsonb_build_object(
    'metodo',        c.metodo,
    'monto',         c.monto,
    'participacion', case when c.total > 0 then (c.monto / c.total) * 100 else 0 end
  )
  from con_total c
  order by c.monto desc;
end $$;

-- ------------------------------------------------------------
-- 6. HISTORIAL PAGINADO · cursor estable (fecha, created_at, id)
--
--    Se usa comparación de tuplas para que el keyset no salte ni repita
--    filas cuando hay varias operaciones en el mismo instante.
--    El orden es siempre descendente: lo más nuevo primero.
-- ------------------------------------------------------------
create or replace function public.pagina_movimientos(
  p_empresa uuid,
  p_desde date,
  p_hasta date,
  p_tamano integer default 100,
  p_cursor_fecha date default null,
  p_cursor_created timestamptz default null,
  p_cursor_id uuid default null,
  p_tipo tipo_movimiento default null,
  p_incluir_anuladas boolean default true,
  p_busqueda text default null
)
returns setof jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_admin  boolean;
  v_tamano integer;
  v_busca  text;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  -- Tope duro: nadie pide más de 500 por página, ni siquiera el generador
  -- de Excel. Así ninguna respuesta se acerca al máximo de filas de la API.
  v_tamano := least(greatest(coalesce(p_tamano, 100), 1), 500);
  v_admin  := public.es_admin(p_empresa);
  v_busca  := nullif(lower(trim(coalesce(p_busqueda, ''))), '');

  return query
  select to_jsonb(x) from (
    select
      m.id, m.empresa_id, m.tipo, m.estado, m.fecha, m.descripcion, m.categoria,
      m.subtotal, m.descuento, m.monto,
      case when v_admin then m.costo_total else null end as costo_total,
      m.metodo_pago, m.contraparte, m.notas, m.origen, m.creado_por, m.created_at,
      m.anulado_por, m.anulado_at, m.motivo_anulacion, m.actualizado_por, m.updated_at,
      coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id', i.id,
            'movimiento_id', i.movimiento_id,
            'empresa_id', i.empresa_id,
            'producto_id', i.producto_id,
            'nombre', i.nombre,
            'cantidad', i.cantidad,
            'precio_unitario', i.precio_unitario,
            'costo_unitario', case when v_admin then i.costo_unitario else null end,
            'afecto_stock', i.afecto_stock
          ) order by i.nombre
        )
        from public.movimiento_items i where i.movimiento_id = m.id
      ), '[]'::jsonb) as movimiento_items
    from public.movimientos m
    where m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
      and (p_tipo is null or m.tipo = p_tipo)
      and (p_incluir_anuladas or m.estado = 'activo')
      and (
        p_cursor_id is null
        or (m.fecha, m.created_at, m.id) < (p_cursor_fecha, p_cursor_created, p_cursor_id)
      )
      and (
        v_busca is null
        or lower(m.descripcion) like '%' || v_busca || '%'
        or lower(m.categoria)   like '%' || v_busca || '%'
        or lower(coalesce(m.contraparte, '')) like '%' || v_busca || '%'
        or exists (
          select 1 from public.movimiento_items i2
          where i2.movimiento_id = m.id and lower(i2.nombre) like '%' || v_busca || '%'
        )
      )
    order by m.fecha desc, m.created_at desc, m.id desc
    limit v_tamano
  ) x;
end $$;

-- Cuántos movimientos hay en el periodo, para saber si vale la pena paginar.
create or replace function public.contar_movimientos(
  p_empresa uuid,
  p_desde date,
  p_hasta date
)
returns bigint language plpgsql stable security definer set search_path = public as $$
declare v_total bigint;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select count(*) into v_total
  from public.movimientos m
  where m.empresa_id = p_empresa and m.fecha between p_desde and p_hasta;

  return v_total;
end $$;

-- ------------------------------------------------------------
-- 7. ÍNDICES
--
--    Comprobado con EXPLAIN ANALYZE sobre 36.500 movimientos en 20 empresas.
--
--    Los agregados ya entran por movimientos_empresa_fecha_idx (001):
--      resumen de un día  → Bitmap Index Scan ... 0,39 ms
--      resumen de un mes  → Bitmap Index Scan ... 0,41 ms
--      serie de un mes    → Bitmap Index Scan ... 0,41 ms
--    No hace falta ningún índice nuevo para ellos.
--
--    Lo que sí faltaba es el orden exacto de la paginación por cursor:
--    (empresa_id, fecha desc, created_at desc, id desc). Con él la primera
--    página resuelve por Index Only Scan en 0,59 ms; sin él habría que
--    ordenar en memoria todo el periodo en cada página.
-- ------------------------------------------------------------
create index if not exists movimientos_cursor_idx
  on public.movimientos (empresa_id, fecha desc, created_at desc, id desc);

-- El ranking agrupa items por producto dentro de una empresa. Con este índice
-- y el filtro `i.empresa_id = ...` de arriba, el plan pasa de recorrer toda la
-- tabla de items a un Bitmap Index Scan.
--
-- Medido con 18.100 items de 10 empresas, ranking de un mes:
--   sin el filtro → Seq Scan de 18.100 filas ... 18,9 ms
--   con el filtro → Bitmap Index Scan de 1.810 ...  2,5 ms
create index if not exists items_empresa_producto_idx
  on public.movimiento_items (empresa_id, producto_id);

-- ------------------------------------------------------------
-- 8. PERMISOS
-- ------------------------------------------------------------
revoke all on function public.resumen_financiero(uuid, date, date)          from public, anon;
revoke all on function public.ranking_productos(uuid, date, date, integer)  from public, anon;
revoke all on function public.serie_financiera_diaria(uuid, date, date)     from public, anon;
revoke all on function public.gastos_por_categoria(uuid, date, date)        from public, anon;
revoke all on function public.cobros_por_metodo(uuid, date, date)           from public, anon;
revoke all on function public.contar_movimientos(uuid, date, date)          from public, anon;
revoke all on function public.pagina_movimientos(uuid, date, date, integer, date, timestamptz, uuid, tipo_movimiento, boolean, text)
  from public, anon;

grant execute on function public.resumen_financiero(uuid, date, date)         to authenticated;
grant execute on function public.ranking_productos(uuid, date, date, integer) to authenticated;
grant execute on function public.serie_financiera_diaria(uuid, date, date)    to authenticated;
grant execute on function public.gastos_por_categoria(uuid, date, date)       to authenticated;
grant execute on function public.cobros_por_metodo(uuid, date, date)          to authenticated;
grant execute on function public.contar_movimientos(uuid, date, date)         to authenticated;
grant execute on function public.pagina_movimientos(uuid, date, date, integer, date, timestamptz, uuid, tipo_movimiento, boolean, text)
  to authenticated;

-- ------------------------------------------------------------
-- 9. listar_movimientos() · qué pasa con la función de la 003/004
--
--    DECISIÓN: queda como helper acotado del lado del SERVIDOR y deja de ser
--    la fuente de los totales. Ya no la usa ninguna pantalla.
--
--    Se conserva porque su tope de 20.000 con error explícito sigue siendo
--    útil para procesos internos que necesitan el periodo entero de una vez,
--    y porque quitarla rompería instalaciones que la tengan cacheada.
--    Para el navegador, el camino correcto es siempre:
--      · números  → resumen_financiero / ranking_productos / serie / gastos / cobros
--      · historial → pagina_movimientos
-- ------------------------------------------------------------
comment on function public.listar_movimientos(uuid, date, date) is
  'HELPER ACOTADO. Devuelve el periodo completo (máx. 20.000, falla si se pasa). '
  'No usar para totales ni desde el navegador: para números usar resumen_financiero() '
  'y para historial pagina_movimientos(). Se mantiene para procesos de servidor.';


-- ############################################################
-- ##  006_confiabilidad_lecturas.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 006 · Confiabilidad de lecturas
--
-- La 005 movió los cálculos a PostgreSQL, pero dejó una grieta: las funciones
-- que devuelven `setof jsonb` siguen siendo, para PostgREST, un conjunto de
-- FILAS. Y PostgREST recorta conjuntos de filas según `db-max-rows`, sin avisar.
--
-- En la práctica eso significaba que:
--   · un catálogo con más de 1.000 productos podía llegar recortado;
--   · un ranking con más de 1.000 productos distintos, también;
--   · una serie diaria de más de 1.000 días (se permitían hasta 1.100), también;
--   · y si `db-max-rows` estuviera configurado bajo (100, 50), hasta una
--     página del historial de 500 podía perder filas.
--
-- Mientras exista una respuesta que PUEDA superar el tope, la afirmación
-- "el tope no afecta los reportes" es una suposición, no una garantía.
--
-- Esta migración la convierte en garantía: TODA función que la aplicación
-- llama devuelve **exactamente una fila** con un único valor jsonb dentro.
-- Un array adentro de un jsonb es un valor, no un conjunto de filas: no hay
-- nada que recortar. El tope puede ser 1.000, 100 o 10; da igual.
--
-- Las reglas de negocio, los permisos y el prorrateo de descuentos NO cambian:
-- el cuerpo de cada consulta es el mismo, solo cambia el envoltorio.
--
-- Idempotente. No toca datos.
-- ============================================================

-- Cambiar el tipo de retorno exige eliminar primero: `create or replace` no
-- puede pasar de `setof jsonb` a `jsonb`.
drop function if exists public.listar_productos(uuid, boolean);
drop function if exists public.listar_movimientos(uuid, date, date);
drop function if exists public.ranking_productos(uuid, date, date, integer);
drop function if exists public.serie_financiera_diaria(uuid, date, date);
drop function if exists public.gastos_por_categoria(uuid, date, date);
drop function if exists public.cobros_por_metodo(uuid, date, date);
drop function if exists public.pagina_movimientos(
  uuid, date, date, integer, date, timestamptz, uuid, tipo_movimiento, boolean, text);

-- ------------------------------------------------------------
-- 1. CATÁLOGO DE PRODUCTOS · un array, no mil filas
-- ------------------------------------------------------------
create or replace function public.listar_productos(
  p_empresa uuid,
  p_incluir_pausados boolean default false
)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_admin boolean;
  v_res   jsonb;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  v_admin := public.es_admin(p_empresa);

  select coalesce(jsonb_agg(to_jsonb(x) order by x.nombre), '[]'::jsonb) into v_res
  from (
    select
      p.id, p.empresa_id, p.nombre, p.categoria,
      case when v_admin then p.costo else null end as costo,
      p.precio, p.stock, p.stock_minimo, p.controla_stock, p.activo, p.created_at
    from public.productos p
    where p.empresa_id = p_empresa
      and (p_incluir_pausados or p.activo)
  ) x;

  return v_res;
end $$;

-- ------------------------------------------------------------
-- 2. RANKING DE PRODUCTOS · el reporte completo, en un solo valor
-- ------------------------------------------------------------
create or replace function public.ranking_productos(
  p_empresa uuid,
  p_desde date,
  p_hasta date,
  p_limite integer default null
)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_admin boolean;
  v_res   jsonb;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  v_admin := public.es_admin(p_empresa);

  with lineas as (
    select
      -- Misma clave de agrupación que calculos.ts: por producto del catálogo,
      -- o por nombre normalizado si fue una venta suelta.
      coalesce(i.producto_id::text, 'libre:' || lower(trim(i.nombre))) as clave,
      i.producto_id,
      i.nombre,
      i.cantidad,
      i.cantidad * i.precio_unitario as bruto,
      -- Descuento prorrateado por el peso de la línea dentro de su venta.
      i.cantidad * i.precio_unitario * coalesce(m.monto / nullif(m.subtotal, 0), 1) as neto,
      i.cantidad * i.costo_unitario as costo,
      m.fecha,
      m.created_at
    from public.movimiento_items i
    join public.movimientos m on m.id = i.movimiento_id
    -- El filtro por empresa sobre los items es redundante pero le permite al
    -- planificador entrar por índice en vez de recorrer la tabla entera.
    where i.empresa_id = p_empresa
      and m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
      and m.estado = 'activo'
      and m.tipo = 'venta'
  ),
  agrupado as (
    select
      clave,
      (array_agg(nombre order by fecha desc, created_at desc))[1] as nombre,
      (array_agg(producto_id order by fecha desc, created_at desc))[1] as producto_id,
      sum(cantidad)::numeric as unidades,
      sum(bruto)::numeric    as ingresos_brutos,
      sum(neto)::numeric     as ingresos,
      sum(costo)::numeric    as costo,
      count(*)::bigint       as operaciones
    from lineas
    group by clave
  ),
  con_total as (
    select a.*, sum(a.ingresos) over () as total_ingresos from agrupado a
  ),
  recortado as (
    select * from con_total
    order by ingresos desc
    limit case when p_limite is null or p_limite <= 0 then null else p_limite end
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'producto_id',     c.producto_id,
      'nombre',          c.nombre,
      'unidades',        c.unidades,
      'ingresos_brutos', c.ingresos_brutos,
      'descuento',       c.ingresos_brutos - c.ingresos,
      'ingresos',        c.ingresos,
      'operaciones',     c.operaciones,
      'participacion',   case when c.total_ingresos > 0 then (c.ingresos / c.total_ingresos) * 100 else 0 end,
      'costo',    case when v_admin then c.costo else null end,
      'ganancia', case when v_admin then c.ingresos - c.costo else null end,
      'margen',   case when v_admin and c.ingresos > 0
                       then ((c.ingresos - c.costo) / c.ingresos) * 100 else null end
    ) order by c.ingresos desc
  ), '[]'::jsonb) into v_res
  from recortado c;

  return v_res;
end $$;

-- ------------------------------------------------------------
-- 3. SERIE DIARIA · un array con todos los días del rango
-- ------------------------------------------------------------
create or replace function public.serie_financiera_diaria(
  p_empresa uuid,
  p_desde date,
  p_hasta date
)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_admin boolean;
  v_dias  integer;
  v_res   jsonb;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  v_dias := (p_hasta - p_desde) + 1;
  if v_dias > 1100 then
    raise exception 'El rango no puede superar los 3 años para la serie diaria.' using errcode = '22023';
  end if;

  v_admin := public.es_admin(p_empresa);

  with dias as (
    select generate_series(p_desde, p_hasta, interval '1 day')::date as fecha
  ),
  porDia as (
    select
      m.fecha,
      coalesce(sum(m.monto)       filter (where m.tipo = 'venta'), 0)::numeric   as ventas,
      coalesce(sum(m.monto)       filter (where m.tipo = 'gasto'), 0)::numeric   as gastos,
      coalesce(sum(m.monto)       filter (where m.tipo = 'ingreso'), 0)::numeric as otros_ingresos,
      coalesce(sum(m.costo_total) filter (where m.tipo = 'venta'), 0)::numeric   as costo
    from public.movimientos m
    where m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
      and m.estado = 'activo'
    group by m.fecha
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'fecha',          to_char(d.fecha, 'YYYY-MM-DD'),
      'ventas',         coalesce(p.ventas, 0),
      'gastos',         coalesce(p.gastos, 0),
      'otros_ingresos', coalesce(p.otros_ingresos, 0),
      'ganancia', case
        when v_admin then coalesce(p.ventas, 0) - coalesce(p.costo, 0)
                        + coalesce(p.otros_ingresos, 0) - coalesce(p.gastos, 0)
        else null
      end
    ) order by d.fecha
  ), '[]'::jsonb) into v_res
  from dias d
  left join porDia p on p.fecha = d.fecha;

  return v_res;
end $$;

-- ------------------------------------------------------------
-- 4. GASTOS POR CATEGORÍA
-- ------------------------------------------------------------
create or replace function public.gastos_por_categoria(
  p_empresa uuid,
  p_desde date,
  p_hasta date
)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v_res jsonb;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  with porCategoria as (
    select
      trim(coalesce(nullif(trim(m.categoria), ''), 'General')) as nombre,
      sum(m.monto)::numeric as monto,
      count(*)::bigint      as operaciones
    from public.movimientos m
    where m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
      and m.estado = 'activo'
      and m.tipo = 'gasto'
    group by 1
  ),
  con_total as (
    select c.*, sum(c.monto) over () as total from porCategoria c
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'nombre',        c.nombre,
      'monto',         c.monto,
      'operaciones',   c.operaciones,
      'participacion', case when c.total > 0 then (c.monto / c.total) * 100 else 0 end
    ) order by c.monto desc
  ), '[]'::jsonb) into v_res
  from con_total c;

  return v_res;
end $$;

-- ------------------------------------------------------------
-- 5. COBROS POR MÉTODO
-- ------------------------------------------------------------
create or replace function public.cobros_por_metodo(
  p_empresa uuid,
  p_desde date,
  p_hasta date
)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare v_res jsonb;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  with porMetodo as (
    select m.metodo_pago as metodo, sum(m.monto)::numeric as monto
    from public.movimientos m
    where m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
      and m.estado = 'activo'
      and m.tipo <> 'gasto'
    group by m.metodo_pago
  ),
  con_total as (
    select p.*, sum(p.monto) over () as total from porMetodo p
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'metodo',        c.metodo,
      'monto',         c.monto,
      'participacion', case when c.total > 0 then (c.monto / c.total) * 100 else 0 end
    ) order by c.monto desc
  ), '[]'::jsonb) into v_res
  from con_total c;

  return v_res;
end $$;

-- ------------------------------------------------------------
-- 6. PÁGINA DEL HISTORIAL · un objeto con la página y el cursor
--
--    Además de blindar el tamaño de la respuesta, ahora el cursor lo calcula
--    el servidor. Antes lo derivaba el cliente de la última fila recibida: si
--    esa lista venía recortada, el cursor apuntaba al lugar equivocado y la
--    paginación se salteaba movimientos en silencio.
-- ------------------------------------------------------------
create or replace function public.pagina_movimientos(
  p_empresa uuid,
  p_desde date,
  p_hasta date,
  p_tamano integer default 100,
  p_cursor_fecha date default null,
  p_cursor_created timestamptz default null,
  p_cursor_id uuid default null,
  p_tipo tipo_movimiento default null,
  p_incluir_anuladas boolean default true,
  p_busqueda text default null
)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_admin   boolean;
  v_tamano  integer;
  v_busca   text;
  v_filas   jsonb;
  v_cuantas integer;
  v_ultima  jsonb;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  v_tamano := least(greatest(coalesce(p_tamano, 100), 1), 500);
  v_admin  := public.es_admin(p_empresa);
  v_busca  := nullif(lower(trim(coalesce(p_busqueda, ''))), '');

  select coalesce(jsonb_agg(to_jsonb(x) order by x.fecha desc, x.created_at desc, x.id desc), '[]'::jsonb)
  into v_filas
  from (
    select
      m.id, m.empresa_id, m.tipo, m.estado, m.fecha, m.descripcion, m.categoria,
      m.subtotal, m.descuento, m.monto,
      case when v_admin then m.costo_total else null end as costo_total,
      m.metodo_pago, m.contraparte, m.notas, m.origen, m.creado_por, m.created_at,
      m.anulado_por, m.anulado_at, m.motivo_anulacion, m.actualizado_por, m.updated_at,
      coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id', i.id,
            'movimiento_id', i.movimiento_id,
            'empresa_id', i.empresa_id,
            'producto_id', i.producto_id,
            'nombre', i.nombre,
            'cantidad', i.cantidad,
            'precio_unitario', i.precio_unitario,
            'costo_unitario', case when v_admin then i.costo_unitario else null end,
            'afecto_stock', i.afecto_stock
          ) order by i.nombre
        )
        from public.movimiento_items i where i.movimiento_id = m.id
      ), '[]'::jsonb) as movimiento_items
    from public.movimientos m
    where m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
      and (p_tipo is null or m.tipo = p_tipo)
      and (p_incluir_anuladas or m.estado = 'activo')
      and (
        p_cursor_id is null
        or (m.fecha, m.created_at, m.id) < (p_cursor_fecha, p_cursor_created, p_cursor_id)
      )
      and (
        v_busca is null
        or lower(m.descripcion) like '%' || v_busca || '%'
        or lower(m.categoria)   like '%' || v_busca || '%'
        or lower(coalesce(m.contraparte, '')) like '%' || v_busca || '%'
        or exists (
          select 1 from public.movimiento_items i2
          where i2.movimiento_id = m.id and lower(i2.nombre) like '%' || v_busca || '%'
        )
      )
    order by m.fecha desc, m.created_at desc, m.id desc
    limit v_tamano
  ) x;

  v_cuantas := jsonb_array_length(v_filas);
  v_ultima  := case when v_cuantas > 0 then v_filas -> (v_cuantas - 1) else null end;

  return jsonb_build_object(
    'movimientos', v_filas,
    -- Si la página vino completa puede haber más; si vino incompleta, terminó.
    'siguiente', case
      when v_cuantas = v_tamano and v_ultima is not null then jsonb_build_object(
        'fecha',      v_ultima ->> 'fecha',
        'created_at', v_ultima ->> 'created_at',
        'id',         v_ultima ->> 'id'
      )
      else null
    end,
    'tamano', v_tamano
  );
end $$;

-- ------------------------------------------------------------
-- 7. HELPER DE SERVIDOR · también devuelve un solo valor
--
--    No lo usa ninguna pantalla (ver el comentario de la 005), pero mientras
--    exista con `setof` es un camino que alguien podría tomar y que el tope
--    de filas podría recortar. Con esto ya no queda ningún camino truncable.
-- ------------------------------------------------------------
create or replace function public.listar_movimientos(
  p_empresa uuid,
  p_desde date,
  p_hasta date
)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_admin boolean;
  v_total bigint;
  v_tope  constant integer := 20000;
  v_res   jsonb;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  select count(*) into v_total
  from public.movimientos m
  where m.empresa_id = p_empresa and m.fecha between p_desde and p_hasta;

  if v_total > v_tope then
    raise exception
      'El periodo elegido tiene % movimientos y el máximo por consulta es %. Elegí un rango más corto para que los totales sean exactos.',
      v_total, v_tope
      using errcode = '54000';
  end if;

  v_admin := public.es_admin(p_empresa);

  select coalesce(jsonb_agg(to_jsonb(x) order by x.fecha desc, x.created_at desc), '[]'::jsonb)
  into v_res
  from (
    select
      m.id, m.empresa_id, m.tipo, m.estado, m.fecha, m.descripcion, m.categoria,
      m.subtotal, m.descuento, m.monto,
      case when v_admin then m.costo_total else null end as costo_total,
      m.metodo_pago, m.contraparte, m.notas, m.origen, m.creado_por, m.created_at,
      m.anulado_por, m.anulado_at, m.motivo_anulacion, m.actualizado_por, m.updated_at,
      coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id', i.id,
            'movimiento_id', i.movimiento_id,
            'empresa_id', i.empresa_id,
            'producto_id', i.producto_id,
            'nombre', i.nombre,
            'cantidad', i.cantidad,
            'precio_unitario', i.precio_unitario,
            'costo_unitario', case when v_admin then i.costo_unitario else null end,
            'afecto_stock', i.afecto_stock
          ) order by i.nombre
        )
        from public.movimiento_items i where i.movimiento_id = m.id
      ), '[]'::jsonb) as movimiento_items
    from public.movimientos m
    where m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
  ) x;

  return v_res;
end $$;

comment on function public.listar_movimientos(uuid, date, date) is
  'HELPER ACOTADO DE SERVIDOR. Devuelve el periodo completo en un solo jsonb '
  '(máx. 20.000, falla si se pasa). No usar desde el navegador: para números '
  'usar resumen_financiero() y para historial pagina_movimientos().';

-- ------------------------------------------------------------
-- 8. PERMISOS · los mismos de siempre, sobre las firmas nuevas
-- ------------------------------------------------------------
revoke all on function public.listar_productos(uuid, boolean)               from public, anon;
revoke all on function public.listar_movimientos(uuid, date, date)          from public, anon;
revoke all on function public.ranking_productos(uuid, date, date, integer)  from public, anon;
revoke all on function public.serie_financiera_diaria(uuid, date, date)     from public, anon;
revoke all on function public.gastos_por_categoria(uuid, date, date)        from public, anon;
revoke all on function public.cobros_por_metodo(uuid, date, date)           from public, anon;
revoke all on function public.pagina_movimientos(
  uuid, date, date, integer, date, timestamptz, uuid, tipo_movimiento, boolean, text) from public, anon;

grant execute on function public.listar_productos(uuid, boolean)              to authenticated;
grant execute on function public.listar_movimientos(uuid, date, date)         to authenticated;
grant execute on function public.ranking_productos(uuid, date, date, integer) to authenticated;
grant execute on function public.serie_financiera_diaria(uuid, date, date)    to authenticated;
grant execute on function public.gastos_por_categoria(uuid, date, date)       to authenticated;
grant execute on function public.cobros_por_metodo(uuid, date, date)          to authenticated;
grant execute on function public.pagina_movimientos(
  uuid, date, date, integer, date, timestamptz, uuid, tipo_movimiento, boolean, text) to authenticated;


-- ############################################################
-- ##  007_adjuntos.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 007 · Adjuntos (comprobantes y transcripciones)
--
-- Hasta acá, la foto de un comprobante se mandaba a la IA, se interpretaba
-- y se tiraba. Lo mismo el audio. Eso convertía a Orden en un anotador:
-- el número quedaba, la prueba no.
--
-- Esta migración le da respaldo al movimiento. Dos decisiones que conviene
-- entender antes de leer el SQL:
--
--   1. LA FOTO SE GUARDA, EL AUDIO NO. De un audio lo único que sirve
--      después es lo que se dijo, y eso ya lo tenemos transcripto. Guardar
--      el archivo costaría storage todos los meses para que nadie lo vuelva
--      a escuchar nunca. Por eso `audio` guarda texto y ruta en null.
--
--   2. LOS ARCHIVOS NO VIVEN EN ESTA TABLA. Viven en Storage, bucket
--      privado `comprobantes`, con la ruta empresa_id/movimiento_id/archivo.
--      La primera carpeta es el empresa_id justamente para que la policy de
--      storage.objects pueda decidir con es_miembro() sin consultar nada más.
--
-- Idempotente. No toca datos existentes.
-- ============================================================

do $$ begin
  create type tipo_adjunto as enum ('foto', 'audio');
exception when duplicate_object then null; end $$;

-- ------------------------------------------------------------
-- 1. TABLA
--
--    `movimiento_id` es NOT NULL a propósito: un adjunto suelto no le
--    sirve a nadie y nos dejaría huérfanos imposibles de encontrar. El
--    orden del flujo es: se guarda el movimiento, se sube el archivo,
--    se crea esta fila.
-- ------------------------------------------------------------
create table if not exists public.adjuntos (
  id            uuid primary key default gen_random_uuid(),
  empresa_id    uuid not null references public.empresas (id) on delete cascade,
  movimiento_id uuid not null references public.movimientos (id) on delete cascade,
  tipo          tipo_adjunto not null,
  -- Ruta dentro del bucket. null cuando el adjunto es solo texto (audio).
  ruta          text,
  mime          text,
  bytes         integer not null default 0 check (bytes >= 0),
  -- Transcripción del audio, o lo que la IA leyó de la foto.
  texto         text not null default '',
  creado_por    uuid references auth.users (id) on delete set null,
  created_at    timestamptz not null default now(),

  -- Una foto sin archivo no es una foto. Un audio con archivo no lo guardamos.
  constraint adjunto_coherente check (
    (tipo = 'foto'  and ruta is not null and char_length(ruta) > 0) or
    (tipo = 'audio' and ruta is null)
  )
);

create index if not exists adjuntos_movimiento_idx on public.adjuntos (movimiento_id);
create index if not exists adjuntos_empresa_idx    on public.adjuntos (empresa_id, created_at desc);

-- La ruta es única: dos filas apuntando al mismo archivo harían que borrar
-- una deje a la otra apuntando a la nada.
create unique index if not exists adjuntos_ruta_idx on public.adjuntos (ruta) where ruta is not null;

comment on table public.adjuntos is
  'Respaldo de un movimiento: foto del comprobante (archivo en Storage) o transcripción de la nota de voz (solo texto, sin archivo).';

-- ------------------------------------------------------------
-- 2. TOPES
--
--    No son de seguridad, son de costo. Storage se paga todos los meses;
--    un usuario subiendo veinte fotos de 4 MB por venta sale más caro que
--    lo que paga. El cliente ya comprime a ~150 KB antes de subir, así que
--    estos topes solo atrapan a quien esquive la interfaz.
-- ------------------------------------------------------------
create or replace function public.limite_adjuntos_movimiento() returns integer
  language sql immutable as $fn$ select 8 $fn$;

create or replace function public.limite_bytes_adjunto() returns integer
  language sql immutable as $fn$ select 5 * 1024 * 1024 $fn$;

-- ------------------------------------------------------------
-- 3. BUCKET PRIVADO Y PERMISOS SOBRE LOS ARCHIVOS
--
--    Todo este bloque está guardado detrás de "¿existe storage.objects?".
--    En Supabase existe siempre. En un PostgreSQL pelado —el que levantan
--    las pruebas— no, y sin la guarda la migración entera fallaría por algo
--    que no tiene nada que ver con las reglas de negocio.
--
--    `public = false`: nadie llega por URL adivinada. La app pide una URL
--    firmada de corta vida, y para que se la den tiene que pasar la policy.
--
--    storage.foldername(name) parte la ruta: [1] es el empresa_id. Con eso
--    es_miembro() decide sin tocar la tabla adjuntos, que puede todavía no
--    tener la fila (el archivo se sube antes de registrarlo).
--
--    Nadie puede ACTUALIZAR un objeto: un comprobante que se puede
--    reemplazar en su lugar no es un comprobante. Se borra y se sube otro.
-- ------------------------------------------------------------
do $bloque$
begin
  if to_regclass('storage.objects') is null then
    raise notice 'Sin esquema storage: se omiten bucket y policies de comprobantes.';
    return;
  end if;

  execute format($sql$
    insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    values ('comprobantes', 'comprobantes', false, %s,
            array['image/webp', 'image/jpeg', 'image/png', 'image/heic'])
    on conflict (id) do update
      set public             = false,
          file_size_limit    = excluded.file_size_limit,
          allowed_mime_types = excluded.allowed_mime_types
  $sql$, public.limite_bytes_adjunto());

  execute 'drop policy if exists comprobantes_ver    on storage.objects';
  execute 'drop policy if exists comprobantes_subir  on storage.objects';
  execute 'drop policy if exists comprobantes_borrar on storage.objects';

  execute $sql$
    create policy comprobantes_ver on storage.objects
      for select to authenticated
      using (
        bucket_id = 'comprobantes'
        and public.es_miembro(nullif((storage.foldername(name))[1], '')::uuid)
      )
  $sql$;

  execute $sql$
    create policy comprobantes_subir on storage.objects
      for insert to authenticated
      with check (
        bucket_id = 'comprobantes'
        and public.es_miembro(nullif((storage.foldername(name))[1], '')::uuid)
      )
  $sql$;

  execute $sql$
    create policy comprobantes_borrar on storage.objects
      for delete to authenticated
      using (
        bucket_id = 'comprobantes'
        and public.es_miembro(nullif((storage.foldername(name))[1], '')::uuid)
      )
  $sql$;

exception
  -- En algunos proyectos de Supabase el rol que corre el SQL Editor no es
  -- dueño de storage.objects y no puede crear policies ahí. No es motivo
  -- para que falle la migración entera: todo lo demás (la tabla `adjuntos`,
  -- las funciones, los topes) queda perfecto, y las tres policies se pueden
  -- cargar a mano desde Storage → Policies con estas mismas condiciones.
  --
  -- Se avisa fuerte porque, hasta que existan, subir un comprobante va a
  -- fallar con "new row violates row-level security policy".
  when insufficient_privilege then
    raise warning 'No se pudieron crear las policies de storage (falta ser dueño de storage.objects). Crealas a mano en Storage → Policies del bucket "comprobantes". El resto de la migración se aplicó bien.';
end $bloque$;

-- ------------------------------------------------------------
-- 5. RLS DE LA TABLA
--
--    Lectura: cualquier miembro. Escritura: NADIE por la puerta directa.
--    Se entra por adjuntar() y borrar_adjunto(), que validan empresa,
--    movimiento, tipo y topes. Si dejáramos el insert abierto, un cliente
--    podría crear una fila que apunta a la ruta de otra empresa.
-- ------------------------------------------------------------
alter table public.adjuntos enable row level security;

drop policy if exists adjuntos_select on public.adjuntos;
create policy adjuntos_select on public.adjuntos
  for select to authenticated
  using (public.es_miembro(empresa_id));

revoke all on public.adjuntos from anon, authenticated;
grant select on public.adjuntos to authenticated;

-- ------------------------------------------------------------
-- 6. ADJUNTAR · la única puerta de entrada
--
--    Valida en este orden: sesión, movimiento visible, coherencia del tipo,
--    tope por movimiento y tope de bytes. Devuelve el id creado.
--
--    Para 'foto' exige que la ruta empiece con "<empresa_id>/<movimiento_id>/".
--    Sin eso, alguien podría registrar como propio un archivo que subió en
--    la carpeta de otro movimiento de su misma empresa y confundir el
--    respaldo de una venta con el de otra.
-- ------------------------------------------------------------
create or replace function public.adjuntar(
  p_movimiento uuid,
  p_tipo       text,
  p_ruta       text default null,
  p_mime       text default null,
  p_bytes      integer default 0,
  p_texto      text default ''
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_empresa uuid;
  v_estado  text;
  v_cuantos integer;
  v_id      uuid;
  v_prefijo text;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  if p_tipo not in ('foto', 'audio') then
    raise exception 'Tipo de adjunto no reconocido.' using errcode = '22023';
  end if;

  select m.empresa_id, m.estado::text into v_empresa, v_estado
  from public.movimientos m where m.id = p_movimiento;

  if v_empresa is null then
    raise exception 'Ese movimiento no existe.' using errcode = 'P0002';
  end if;
  if not public.es_miembro(v_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if v_estado = 'anulado' then
    raise exception 'No se le pueden agregar comprobantes a un movimiento anulado.' using errcode = '42501';
  end if;

  select count(*) into v_cuantos from public.adjuntos where movimiento_id = p_movimiento;
  if v_cuantos >= public.limite_adjuntos_movimiento() then
    raise exception 'Este movimiento ya tiene % comprobantes, que es el máximo.',
      public.limite_adjuntos_movimiento() using errcode = '54000';
  end if;

  if p_tipo = 'foto' then
    if p_ruta is null or char_length(trim(p_ruta)) = 0 then
      raise exception 'Falta la ruta del archivo.' using errcode = '22023';
    end if;
    if coalesce(p_bytes, 0) > public.limite_bytes_adjunto() then
      raise exception 'La foto pesa demasiado.' using errcode = '54000';
    end if;

    v_prefijo := v_empresa::text || '/' || p_movimiento::text || '/';
    if position(v_prefijo in p_ruta) <> 1 then
      raise exception 'La ruta no corresponde a este movimiento.' using errcode = '42501';
    end if;

    insert into public.adjuntos (empresa_id, movimiento_id, tipo, ruta, mime, bytes, texto, creado_por)
    values (v_empresa, p_movimiento, 'foto', p_ruta, p_mime, coalesce(p_bytes, 0),
            coalesce(left(p_texto, 2000), ''), auth.uid())
    returning id into v_id;
  else
    if coalesce(trim(p_texto), '') = '' then
      raise exception 'Una nota de voz sin transcripción no se guarda.' using errcode = '22023';
    end if;

    insert into public.adjuntos (empresa_id, movimiento_id, tipo, ruta, mime, bytes, texto, creado_por)
    values (v_empresa, p_movimiento, 'audio', null, null, 0, left(p_texto, 2000), auth.uid())
    returning id into v_id;
  end if;

  return v_id;
end $fn$;

-- ------------------------------------------------------------
-- 7. BORRAR
--
--    Solo borra la FILA. El archivo lo borra el cliente contra Storage, que
--    tiene su propia policy. Se hace en ese orden a propósito: si el borrado
--    del archivo falla, queda un archivo sin fila (invisible, se limpia
--    después) y no una fila sin archivo (un comprobante roto en pantalla).
--
--    Quien no administra solo puede borrar lo que subió él.
-- ------------------------------------------------------------
create or replace function public.borrar_adjunto(p_adjunto uuid)
returns text language plpgsql security definer set search_path = public as $fn$
declare v_fila public.adjuntos;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  select * into v_fila from public.adjuntos where id = p_adjunto;
  if v_fila.id is null then
    raise exception 'Ese comprobante no existe.' using errcode = 'P0002';
  end if;
  if not public.es_miembro(v_fila.empresa_id) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if not public.es_admin(v_fila.empresa_id) and v_fila.creado_por is distinct from auth.uid() then
    raise exception 'Solo podés borrar los comprobantes que subiste vos.' using errcode = '42501';
  end if;

  delete from public.adjuntos where id = p_adjunto;
  return v_fila.ruta;  -- para que el cliente sepa qué archivo borrar
end $fn$;

-- ------------------------------------------------------------
-- 8. LISTAR · una sola fila jsonb
--
--    Mismo criterio que la 006: nada que PostgREST pueda recortar.
-- ------------------------------------------------------------
create or replace function public.adjuntos_de(p_movimiento uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_empresa uuid;
  v_res     jsonb;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  select m.empresa_id into v_empresa from public.movimientos m where m.id = p_movimiento;
  if v_empresa is null or not public.es_miembro(v_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(x order by x->>'created_at'), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'id', a.id, 'tipo', a.tipo, 'ruta', a.ruta, 'mime', a.mime,
      'bytes', a.bytes, 'texto', a.texto, 'creado_por', a.creado_por,
      'created_at', a.created_at
    ) as x
    from public.adjuntos a where a.movimiento_id = p_movimiento
  ) s;

  return v_res;
end $fn$;

-- ------------------------------------------------------------
-- 9. CUÁNTOS TIENE CADA MOVIMIENTO · para el listado
--
--    El historial necesita mostrar el clip sin traer los adjuntos de cada
--    fila. Esto devuelve solo el conteo, de a un lote de movimientos.
-- ------------------------------------------------------------
create or replace function public.conteo_adjuntos(p_empresa uuid, p_movimientos uuid[])
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_res jsonb;
begin
  if auth.uid() is null or not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select coalesce(jsonb_object_agg(movimiento_id::text, n), '{}'::jsonb) into v_res
  from (
    select a.movimiento_id, count(*)::int as n
    from public.adjuntos a
    where a.empresa_id = p_empresa
      and a.movimiento_id = any(coalesce(p_movimientos, '{}'::uuid[]))
    group by a.movimiento_id
  ) s;

  return v_res;
end $fn$;

revoke all on function public.adjuntar(uuid, text, text, text, integer, text) from public, anon;
revoke all on function public.borrar_adjunto(uuid) from public, anon;
revoke all on function public.adjuntos_de(uuid) from public, anon;
revoke all on function public.conteo_adjuntos(uuid, uuid[]) from public, anon;

grant execute on function public.adjuntar(uuid, text, text, text, integer, text) to authenticated;
grant execute on function public.borrar_adjunto(uuid) to authenticated;
grant execute on function public.adjuntos_de(uuid) to authenticated;
grant execute on function public.conteo_adjuntos(uuid, uuid[]) to authenticated;


-- ############################################################
-- ##  008_habito.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 008 · El hábito (cierre del día y racha)
--
-- Las notificaciones no crean la costumbre: traen de vuelta a quien ya la
-- tenía. Lo que la crea es un ritual corto que cierra el día y algo que se
-- pierde si se falta. Eso es lo que agrega esta migración.
--
--   · CIERRE DEL DÍA — una lectura de diez segundos: cuánto entró, cuánto
--     salió, cuánto quedó, y contra qué se compara. Todo calculado en la
--     base, reusando resumen_financiero() para no tener dos definiciones
--     distintas de "ganancia" en el sistema.
--
--   · RACHA — días seguidos con al menos un movimiento cargado. La racha
--     NO se rompe porque hoy todavía no cargaste: se rompe cuando el día
--     termina vacío. Por eso se cuenta hasta ayer y hoy marca "en riesgo".
--     Un contador que te castiga a las 8 de la mañana no motiva a nadie.
--
-- Y de paso: ZONA HORARIA POR EMPRESA. Hasta acá "hoy" era siempre
-- America/Asuncion, clavado. Si Orden sale de Paraguay, un cierre del día
-- calculado en la zona equivocada le muestra a la persona el día de otro.
--
-- Idempotente. No toca datos existentes.
-- ============================================================

-- ------------------------------------------------------------
-- 1. ZONA HORARIA POR EMPRESA
--
--    El check contra pg_timezone_names evita guardar una zona inventada,
--    que después haría fallar el `at time zone` de todas las lecturas.
-- ------------------------------------------------------------
alter table public.empresas
  add column if not exists zona_horaria text not null default 'America/Asuncion';

do $$ begin
  alter table public.empresas add constraint empresas_zona_valida
    check (zona_horaria in (select name from pg_timezone_names));
exception when duplicate_object then null;
          when others then null;  -- si el catálogo no está disponible, no bloquea la migración
end $$;

comment on column public.empresas.zona_horaria is
  'Zona en la que se decide qué día es "hoy" para este negocio. El cierre del día y la racha dependen de esto.';

create or replace function public.hoy_empresa(p_empresa uuid)
returns date language sql stable security definer set search_path = public as $fn$
  select (now() at time zone coalesce(
    (select e.zona_horaria from public.empresas e where e.id = p_empresa),
    'America/Asuncion'
  ))::date;
$fn$;

-- ------------------------------------------------------------
-- 2. CIERRES · el gesto de cerrar el día
--
--    Guardamos que la persona MIRÓ el cierre, no un total. Los totales se
--    recalculan siempre: si mañana se anula una venta de hoy, el cierre de
--    hoy tiene que reflejarlo. Una foto congelada mentiría.
--
--    Es por usuario y no por empresa: en un negocio con tres vendedores,
--    que uno haya mirado el cierre no significa que los otros lo vieron.
-- ------------------------------------------------------------
create table if not exists public.cierres (
  id         uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas (id) on delete cascade,
  user_id    uuid not null references auth.users (id) on delete cascade,
  fecha      date not null,
  visto_at   timestamptz not null default now(),
  unique (empresa_id, user_id, fecha)
);

create index if not exists cierres_empresa_fecha_idx on public.cierres (empresa_id, fecha desc);

alter table public.cierres enable row level security;

drop policy if exists cierres_select on public.cierres;
create policy cierres_select on public.cierres
  for select to authenticated
  using (user_id = auth.uid() and public.es_miembro(empresa_id));

revoke all on public.cierres from anon, authenticated;
grant select on public.cierres to authenticated;

create or replace function public.marcar_cierre(p_empresa uuid, p_fecha date default null)
returns date language plpgsql security definer set search_path = public as $fn$
declare v_fecha date;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  v_fecha := coalesce(p_fecha, public.hoy_empresa(p_empresa));

  -- Un cierre del futuro no existe. Uno muy viejo tampoco sirve de nada.
  if v_fecha > public.hoy_empresa(p_empresa) then
    raise exception 'No se puede cerrar un día que todavía no pasó.' using errcode = '22007';
  end if;

  insert into public.cierres (empresa_id, user_id, fecha)
  values (p_empresa, auth.uid(), v_fecha)
  on conflict (empresa_id, user_id, fecha) do update set visto_at = now();

  return v_fecha;
end $fn$;

-- ------------------------------------------------------------
-- 3. RACHA · días seguidos cargando
--
--    Islas y huecos: a cada día con actividad le restamos su número de
--    orden. Los días consecutivos dan todos el mismo resultado, así que
--    agrupar por ese valor separa las rachas sin recorrer nada dos veces.
--
--    `dias` cuenta la racha vigente; `en_riesgo` es true cuando la racha
--    viene de ayer y hoy todavía está vacío. Ese es el único momento en
--    que tiene sentido empujar con un aviso.
-- ------------------------------------------------------------
create or replace function public.racha_empresa(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_hoy   date;
  v_ayer  date;
  v_res   jsonb;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  v_hoy  := public.hoy_empresa(p_empresa);
  v_ayer := v_hoy - 1;

  with dias as (
    select distinct m.fecha
    from public.movimientos m
    where m.empresa_id = p_empresa
      and m.estado = 'activo'
      and m.fecha <= v_hoy
  ),
  numeradas as (
    select fecha, (fecha - (row_number() over (order by fecha))::int) as isla
    from dias
  ),
  rachas as (
    select isla, count(*)::int as largo, min(fecha) as desde, max(fecha) as hasta
    from numeradas group by isla
  ),
  vigente as (
    select * from rachas where hasta in (v_hoy, v_ayer) order by hasta desc limit 1
  )
  select jsonb_build_object(
    'hoy',           v_hoy,
    'dias',          coalesce((select largo from vigente), 0),
    'desde',         (select desde from vigente),
    'hoy_cargado',   exists (select 1 from dias where fecha = v_hoy),
    -- Solo está en riesgo si HAY algo que perder.
    'en_riesgo',     coalesce((select hasta from vigente), v_ayer - 1) = v_ayer,
    'mejor',         coalesce((select max(largo) from rachas), 0),
    'dias_activos',  (select count(*)::int from dias)
  ) into v_res;

  return v_res;
end $fn$;

-- ------------------------------------------------------------
-- 4. CIERRE DEL DÍA
--
--    Reusa resumen_financiero() tres veces: el día, el mismo día de la
--    semana pasada, y los siete días previos. No reimplementa ni una suma,
--    así que "ganancia neta" quiere decir exactamente lo mismo acá que en
--    el panel y que en el Excel. Los permisos también viajan solos: si
--    quien pregunta es vendedor, la ganancia ya llega en null desde
--    adentro y no hay que acordarse de taparla acá.
-- ------------------------------------------------------------
create or replace function public.cierre_del_dia(p_empresa uuid, p_fecha date default null)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_fecha    date;
  v_previo   date;
  v_hoy_r    jsonb;
  v_prev_r   jsonb;
  v_sem_r    jsonb;
  v_top      jsonb;
  v_res      jsonb;
  v_admin    boolean;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  v_fecha  := coalesce(p_fecha, public.hoy_empresa(p_empresa));
  v_previo := v_fecha - 7;
  v_admin  := public.es_admin(p_empresa);

  v_hoy_r  := public.resumen_financiero(p_empresa, v_fecha, v_fecha);
  v_prev_r := public.resumen_financiero(p_empresa, v_previo, v_previo);
  -- Los siete días ANTERIORES, sin incluir el que se está cerrando: si lo
  -- incluyéramos, el día se estaría comparando en parte contra sí mismo.
  v_sem_r  := public.resumen_financiero(p_empresa, v_fecha - 7, v_fecha - 1);

  select jsonb_build_object('nombre', r->>'nombre', 'unidades', r->'unidades', 'ingresos', r->'ingresos')
  into v_top
  from jsonb_array_elements(
    coalesce(public.ranking_productos(p_empresa, v_fecha, v_fecha, 1), '[]'::jsonb)
  ) as r
  limit 1;

  select jsonb_build_object(
    'fecha',              v_fecha,
    'es_hoy',             v_fecha = public.hoy_empresa(p_empresa),
    'hubo_actividad',     coalesce((v_hoy_r->>'cantidad_ventas')::numeric, 0) > 0
                          or coalesce((v_hoy_r->>'gastos')::numeric, 0) > 0
                          or coalesce((v_hoy_r->>'otros_ingresos')::numeric, 0) > 0,
    'resumen',            v_hoy_r,
    'misma_dia_semana_pasada', v_prev_r,
    -- Promedio diario de la semana previa, para decir "hoy vendiste más que
    -- un día normal tuyo" sin que un lunes flojo arruine la comparación.
    'promedio_semana',    jsonb_build_object(
                            'ventas',  round(coalesce((v_sem_r->>'ventas')::numeric, 0) / 7, 2),
                            'gastos',  round(coalesce((v_sem_r->>'gastos')::numeric, 0) / 7, 2),
                            'ganancia_neta', case when v_admin
                              then round(coalesce((v_sem_r->>'ganancia_neta')::numeric, 0) / 7, 2)
                              else null end
                          ),
    'producto_estrella',  v_top,
    'racha',              public.racha_empresa(p_empresa),
    'ya_cerrado',         exists (
                            select 1 from public.cierres c
                            where c.empresa_id = p_empresa
                              and c.user_id = auth.uid()
                              and c.fecha = v_fecha
                          )
  ) into v_res;

  return v_res;
end $fn$;

-- ------------------------------------------------------------
-- 5. NEGOCIOS QUE HOY NO CARGARON NADA
--
--    La usa la tarea programada que manda el aviso de la noche. Devuelve
--    solo lo necesario para armar el mensaje, y solo de quien tiene una
--    racha viva que perder: avisarle a alguien que hace tres semanas no
--    entra no es un recordatorio, es spam.
--
--    Es para service_role: corre sin sesión de usuario, desde el cron.
-- ------------------------------------------------------------
create or replace function public.empresas_sin_cargar_hoy(p_racha_minima integer default 2)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_res jsonb;
begin
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'empresa_id', e.id,
      'nombre',     e.nombre,
      'zona',       e.zona_horaria,
      'racha',      r.largo
    ) as x
    from public.empresas e
    join lateral (
      with dias as (
        select distinct m.fecha from public.movimientos m
        where m.empresa_id = e.id and m.estado = 'activo'
          and m.fecha <= (now() at time zone e.zona_horaria)::date
      ),
      numeradas as (
        select fecha, (fecha - (row_number() over (order by fecha))::int) as isla from dias
      ),
      rachas as (
        select count(*)::int as largo, max(fecha) as hasta from numeradas group by isla
      )
      select largo, hasta from rachas order by hasta desc limit 1
    ) r on true
    where r.hasta = (now() at time zone e.zona_horaria)::date - 1
      and r.largo >= greatest(p_racha_minima, 1)
  ) s;

  return v_res;
end $fn$;

revoke all on function public.marcar_cierre(uuid, date)      from public, anon;
revoke all on function public.racha_empresa(uuid)            from public, anon;
revoke all on function public.cierre_del_dia(uuid, date)     from public, anon;
revoke all on function public.hoy_empresa(uuid)              from public, anon;
revoke all on function public.empresas_sin_cargar_hoy(integer) from public, anon, authenticated;

grant execute on function public.marcar_cierre(uuid, date)   to authenticated;
grant execute on function public.racha_empresa(uuid)         to authenticated;
grant execute on function public.cierre_del_dia(uuid, date)  to authenticated;
grant execute on function public.hoy_empresa(uuid)           to authenticated;
grant execute on function public.empresas_sin_cargar_hoy(integer) to service_role;


-- ############################################################
-- ##  009_planes_precios.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 009 · Planes, precios y prueba gratis
--
-- Tres cosas que hasta acá no existían:
--
--   1. UN TERCER PLAN. Orden ya tenía construido lo caro: roles, empleados,
--      costos ocultos para el vendedor, código de invitación. Eso no vale
--      lo mismo que una persona sola cargando sus ventas. `negocio` cobra
--      por lo que ya está hecho.
--
--   2. PRECIOS EN UNA TABLA, NO EN EL CÓDIGO. Guaraníes para Paraguay,
--      dólares para el resto, y el día que entres a Brasil se agrega una
--      fila. Cambiar un precio no puede requerir un despliegue.
--
--   3. PRUEBA DE 14 DÍAS, SIN TARJETA. Tres días no alcanzan: el valor de
--      Orden aparece cuando hay datos acumulados, y a los tres días el
--      panel está casi vacío. Catorce días son dos cierres de semana y un
--      resumen semanal por email.
--
--      Al vencer NO se bloquean los datos. Se cae a `gratis`: sigue viendo
--      todo su historial y cargando a mano, y pierde la captura ilimitada,
--      los comprobantes y el Excel. Quitarle los datos genera bronca;
--      quitarle la magia genera compras.
--
-- Idempotente. No toca datos existentes.
-- ============================================================

-- ------------------------------------------------------------
-- 1. ABRIR LOS CHECKS AL PLAN `negocio`
--
--    Los checks viejos solo conocían gratis/pro. Se reemplazan por nombre
--    para que la migración sea repetible.
-- ------------------------------------------------------------
alter table public.empresas       drop constraint if exists empresas_plan_check;
alter table public.suscripciones  drop constraint if exists suscripciones_plan_check;
alter table public.suscripciones  drop constraint if exists suscripciones_estado_check;

alter table public.empresas
  add constraint empresas_plan_check check (plan in ('gratis', 'pro', 'negocio'));

alter table public.suscripciones
  add constraint suscripciones_plan_check check (plan in ('gratis', 'pro', 'negocio'));

alter table public.suscripciones
  add constraint suscripciones_estado_check
  check (estado in ('activa', 'prueba', 'vencida', 'cancelada', 'morosa'));

-- Datos del cobro. `importe` y `moneda` se guardan tal como se cobró: si
-- mañana sube el precio, la suscripción vieja tiene que seguir mostrando
-- lo que esa persona realmente paga.
alter table public.suscripciones
  add column if not exists periodo            text not null default 'mensual',
  add column if not exists moneda             text,
  add column if not exists importe            numeric(14,2),
  add column if not exists prueba_fin         timestamptz,
  add column if not exists cancela_al_vencer  boolean not null default false;

do $$ begin
  alter table public.suscripciones add constraint suscripciones_periodo_check
    check (periodo in ('mensual', 'anual'));
exception when duplicate_object then null; end $$;

-- ------------------------------------------------------------
-- 2. PRECIOS
--
--    Clave (plan, moneda, periodo). `activo` permite dejar de ofrecer un
--    precio sin borrarlo, para que las suscripciones que ya lo usan sigan
--    teniendo a qué apuntar.
-- ------------------------------------------------------------
create table if not exists public.precios (
  id          uuid primary key default gen_random_uuid(),
  plan        text not null check (plan in ('pro', 'negocio')),
  moneda      text not null check (moneda in ('PYG', 'USD', 'ARS', 'BRL', 'EUR')),
  periodo     text not null check (periodo in ('mensual', 'anual')),
  importe     numeric(14,2) not null check (importe > 0),
  -- Identificador del precio en la pasarela (price_id de Stripe, etc.).
  referencia_externa text,
  activo      boolean not null default true,
  created_at  timestamptz not null default now(),
  unique (plan, moneda, periodo)
);

comment on table public.precios is
  'Precio de venta por plan, moneda y periodo. Cambiar un precio acá no requiere desplegar la app.';

-- Precios de arranque. El anual da dos meses gratis: a cinco dólares, la
-- comisión fija de la pasarela se lleva cerca del 10% todos los meses;
-- cobrando una vez al año se paga una sola vez.
insert into public.precios (plan, moneda, periodo, importe) values
  ('pro',     'PYG', 'mensual',   35000),
  ('pro',     'PYG', 'anual',    350000),
  ('pro',     'USD', 'mensual',    4.99),
  ('pro',     'USD', 'anual',     49.00),
  ('negocio', 'PYG', 'mensual',   79000),
  ('negocio', 'PYG', 'anual',    790000),
  ('negocio', 'USD', 'mensual',    8.99),
  ('negocio', 'USD', 'anual',      89.00)
on conflict (plan, moneda, periodo) do nothing;

alter table public.precios enable row level security;

-- La lista de precios es pública: la pantalla de planes tiene que poder
-- mostrarla antes de que la persona se registre.
drop policy if exists precios_select on public.precios;
create policy precios_select on public.precios for select using (activo);

revoke all on public.precios from anon, authenticated;
grant select on public.precios to anon, authenticated;

create or replace function public.lista_precios(p_moneda text default null)
returns jsonb language sql stable security definer set search_path = public as $fn$
  select coalesce(jsonb_agg(jsonb_build_object(
    'plan', p.plan, 'moneda', p.moneda, 'periodo', p.periodo,
    'importe', p.importe, 'referencia_externa', p.referencia_externa
  ) order by p.plan, p.periodo), '[]'::jsonb)
  from public.precios p
  where p.activo and (p_moneda is null or p.moneda = p_moneda);
$fn$;

grant execute on function public.lista_precios(text) to anon, authenticated;

-- ------------------------------------------------------------
-- 3. QUÉ DA CADA PLAN
--
--    Una sola definición, en la base. Si estuviera en TypeScript habría que
--    confiar en el navegador para saber si alguien puede subir un
--    comprobante, y el navegador es de quien lo abre.
-- ------------------------------------------------------------
create or replace function public.limites_plan(p_plan text)
returns jsonb language sql immutable set search_path = public as $fn$
  select case coalesce(p_plan, 'gratis')
    when 'negocio' then jsonb_build_object(
      'capturas_mes', 3000, 'miembros', 15,
      'adjuntos', true, 'excel', true, 'avisos', true)
    -- Tres personas: el dueño y un par de ayudantes. Una despensa chica no
    -- tiene por qué pagar el plan de una cadena, y si la apretamos termina
    -- compartiendo un solo login — que es peor para todos, porque perdemos
    -- el registro de quién cargó cada venta.
    when 'pro' then jsonb_build_object(
      'capturas_mes', 600, 'miembros', 3,
      'adjuntos', true, 'excel', true, 'avisos', true)
    else jsonb_build_object(
      -- Veinte capturas alcanzan para que la magia se entienda y no para
      -- vivir del plan gratis. Cargar a mano nunca se limita: los datos
      -- son de la persona, no nuestros.
      'capturas_mes', 20, 'miembros', 1,
      'adjuntos', false, 'excel', false, 'avisos', true)
  end;
$fn$;

grant execute on function public.limites_plan(text) to anon, authenticated;

-- ------------------------------------------------------------
-- 4. PLAN EFECTIVO · ahora con tres planes y prueba
--
--    Reemplaza al de la 003, que asumía que todo lo que no era 'pro' era
--    'gratis'. El orden de las ramas importa: primero lo que vence, después
--    lo que está vigente.
-- ------------------------------------------------------------
create or replace function public.plan_efectivo_calculado(p_empresa uuid)
returns text language sql stable security definer set search_path = public as $fn$
  select coalesce((
    select case
      when s.plan = 'gratis' then 'gratis'
      -- Vencida por fecha: no importa qué diga el estado.
      when s.periodo_fin is not null and s.periodo_fin <= now() then 'gratis'
      when s.estado in ('activa', 'prueba') then s.plan
      -- Canceló pero pagó hasta fin de mes: conserva lo que compró.
      when s.estado = 'cancelada' and s.periodo_fin is not null and s.periodo_fin > now() then s.plan
      else 'gratis'
    end
    from public.suscripciones s
    where s.empresa_id = p_empresa
  ), 'gratis');
$fn$;

-- `empresa_es_pro` existía cuando pro era el único plan pago. Ahora la
-- pregunta útil es "¿paga?", y negocio también paga.
create or replace function public.empresa_es_pro(p_empresa uuid)
returns boolean language plpgsql stable security definer set search_path = public as $fn$
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  return public.plan_efectivo_calculado(p_empresa) in ('pro', 'negocio');
end $fn$;

-- ------------------------------------------------------------
-- 5. CONSUMO DE IA
--
--    Se cuenta por empresa y por mes calendario. Nada de borrar filas
--    viejas: sirven para ver cuánto usa realmente la gente antes de
--    decidir si el tope está bien puesto.
-- ------------------------------------------------------------
create table if not exists public.uso_ia (
  empresa_id uuid not null references public.empresas (id) on delete cascade,
  periodo    text not null,           -- 'YYYY-MM'
  usados     integer not null default 0 check (usados >= 0),
  updated_at timestamptz not null default now(),
  primary key (empresa_id, periodo)
);

alter table public.uso_ia enable row level security;

drop policy if exists uso_ia_select on public.uso_ia;
create policy uso_ia_select on public.uso_ia
  for select to authenticated using (public.es_miembro(empresa_id));

revoke all on public.uso_ia from anon, authenticated;
grant select on public.uso_ia to authenticated;

-- ------------------------------------------------------------
-- 6. CONSUMIR UN CRÉDITO
--
--    Devuelve si se permitió, cuántos van y cuál es el tope. Es la única
--    forma de gastar un crédito: la ruta /api/capturar la llama ANTES de
--    hablar con OpenAI, así un plan gratis no puede quemarnos la cuenta.
--
--    El `where` dentro del `on conflict` es lo que lo hace seguro con dos
--    pedidos simultáneos: si el cupo está lleno, la actualización no se
--    aplica y no devuelve fila. Sin eso, dos capturas al mismo tiempo
--    podrían pasar las dos por encima del tope.
-- ------------------------------------------------------------
create or replace function public.consumir_credito_ia(p_empresa uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_periodo text;
  v_tope    integer;
  v_usados  integer;
  v_plan    text;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  v_plan    := public.plan_efectivo_calculado(p_empresa);
  v_tope    := (public.limites_plan(v_plan)->>'capturas_mes')::integer;
  v_periodo := to_char(public.hoy_empresa(p_empresa), 'YYYY-MM');

  insert into public.uso_ia (empresa_id, periodo, usados)
  values (p_empresa, v_periodo, 1)
  on conflict (empresa_id, periodo) do update
    set usados = public.uso_ia.usados + 1, updated_at = now()
    where public.uso_ia.usados < v_tope
  returning usados into v_usados;

  if v_usados is null then
    select usados into v_usados from public.uso_ia
    where empresa_id = p_empresa and periodo = v_periodo;

    return jsonb_build_object(
      'permitido', false, 'usados', coalesce(v_usados, v_tope),
      'tope', v_tope, 'plan', v_plan);
  end if;

  return jsonb_build_object(
    'permitido', true, 'usados', v_usados, 'tope', v_tope, 'plan', v_plan);
end $fn$;

-- Cuánto va usado, sin gastar nada. Para mostrarlo en pantalla.
create or replace function public.uso_ia_actual(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_plan text;
  v_tope integer;
  v_usados integer;
begin
  if auth.uid() is null or not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  v_plan := public.plan_efectivo_calculado(p_empresa);
  v_tope := (public.limites_plan(v_plan)->>'capturas_mes')::integer;

  select usados into v_usados from public.uso_ia
  where empresa_id = p_empresa and periodo = to_char(public.hoy_empresa(p_empresa), 'YYYY-MM');

  return jsonb_build_object('usados', coalesce(v_usados, 0), 'tope', v_tope, 'plan', v_plan);
end $fn$;

-- ------------------------------------------------------------
-- 7. APLICAR SUSCRIPCIÓN · ahora acepta los tres planes y guarda el cobro
--
--    Sigue siendo exclusiva de service_role: la llama el webhook de la
--    pasarela, nunca el navegador.
-- ------------------------------------------------------------
create or replace function public.aplicar_suscripcion(
  p_empresa uuid,
  p_plan text,
  p_estado text default 'activa',
  p_periodo_inicio timestamptz default null,
  p_periodo_fin timestamptz default null,
  p_proveedor text default null,
  p_customer_id text default null,
  p_subscription_id text default null,
  p_periodo text default 'mensual',
  p_moneda text default null,
  p_importe numeric default null
)
returns void language plpgsql security definer set search_path = public as $fn$
begin
  if p_plan not in ('gratis', 'pro', 'negocio') then
    raise exception 'Plan desconocido: %', p_plan using errcode = '22023';
  end if;
  if p_estado not in ('activa', 'prueba', 'vencida', 'cancelada', 'morosa') then
    raise exception 'Estado desconocido: %', p_estado using errcode = '22023';
  end if;

  insert into public.suscripciones (
    empresa_id, plan, estado, periodo_inicio, periodo_fin,
    proveedor_pago, customer_id_externo, subscription_id_externo,
    periodo, moneda, importe, updated_at
  )
  values (p_empresa, p_plan, p_estado, p_periodo_inicio, p_periodo_fin,
          p_proveedor, p_customer_id, p_subscription_id,
          coalesce(p_periodo, 'mensual'), p_moneda, p_importe, now())
  on conflict (empresa_id) do update set
    plan = excluded.plan,
    estado = excluded.estado,
    periodo_inicio = excluded.periodo_inicio,
    periodo_fin = excluded.periodo_fin,
    proveedor_pago = coalesce(excluded.proveedor_pago, public.suscripciones.proveedor_pago),
    customer_id_externo = coalesce(excluded.customer_id_externo, public.suscripciones.customer_id_externo),
    subscription_id_externo = coalesce(excluded.subscription_id_externo, public.suscripciones.subscription_id_externo),
    periodo = coalesce(excluded.periodo, public.suscripciones.periodo),
    moneda = coalesce(excluded.moneda, public.suscripciones.moneda),
    importe = coalesce(excluded.importe, public.suscripciones.importe),
    cancela_al_vencer = (excluded.estado = 'cancelada'),
    updated_at = now();

  perform set_config('orden.suscripcion_confiable', '1', true);
  update public.empresas set plan = p_plan where id = p_empresa;
  perform set_config('orden.suscripcion_confiable', '0', true);
end $fn$;

-- La firma vieja de 8 argumentos tiene que morir. Si conviven las dos,
-- cualquier llamada con menos argumentos que los que ambas aceptan por
-- defecto es ambigua y PostgreSQL la rechaza con "is not unique" — el
-- webhook de pago fallaría justo cuando hay plata de por medio.
drop function if exists public.aplicar_suscripcion(
  uuid, text, text, timestamptz, timestamptz, text, text, text);

revoke all on function public.aplicar_suscripcion(
  uuid, text, text, timestamptz, timestamptz, text, text, text, text, text, numeric)
  from public, anon, authenticated;
grant execute on function public.aplicar_suscripcion(
  uuid, text, text, timestamptz, timestamptz, text, text, text, text, text, numeric)
  to service_role;

-- ------------------------------------------------------------
-- 8. PRUEBA GRATIS
--
--    Se otorga una sola vez por empresa: `prueba_fin` queda escrito para
--    siempre, así que borrar la suscripción y volver a crearla no sirve
--    (la empresa es la misma fila). Se llama al crear la empresa.
-- ------------------------------------------------------------
create or replace function public.iniciar_prueba(p_empresa uuid, p_dias integer default 14)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_sus public.suscripciones;
  v_fin timestamptz;
begin
  select * into v_sus from public.suscripciones where empresa_id = p_empresa;

  if v_sus.empresa_id is null then
    raise exception 'Esa empresa no tiene suscripción.' using errcode = 'P0002';
  end if;
  if v_sus.prueba_fin is not null then
    return jsonb_build_object('otorgada', false, 'motivo', 'ya_usada', 'prueba_fin', v_sus.prueba_fin);
  end if;
  if v_sus.plan <> 'gratis' then
    return jsonb_build_object('otorgada', false, 'motivo', 'ya_paga', 'prueba_fin', null);
  end if;

  v_fin := now() + make_interval(days => greatest(coalesce(p_dias, 14), 1));

  update public.suscripciones
  set plan = 'pro', estado = 'prueba',
      periodo_inicio = now(), periodo_fin = v_fin, prueba_fin = v_fin,
      updated_at = now()
  where empresa_id = p_empresa;

  perform set_config('orden.suscripcion_confiable', '1', true);
  update public.empresas set plan = 'pro' where id = p_empresa;
  perform set_config('orden.suscripcion_confiable', '0', true);

  return jsonb_build_object('otorgada', true, 'motivo', null, 'prueba_fin', v_fin);
end $fn$;

revoke all on function public.iniciar_prueba(uuid, integer) from public, anon, authenticated;
grant execute on function public.iniciar_prueba(uuid, integer) to service_role;

-- ------------------------------------------------------------
-- 9. CREAR EMPRESA · ahora nace con la prueba andando
--
--    Redefinición completa de la versión de la 003. Lo único que cambia es
--    el bloque final: en vez de dejar la suscripción en gratis, arranca la
--    prueba de 14 días. Que la primera experiencia sea la buena.
-- ------------------------------------------------------------
create or replace function public.crear_empresa(
  p_nombre text,
  p_moneda text default 'PYG',
  p_nombre_usuario text default null,
  p_zona text default 'America/Asuncion'
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_id uuid;
  v_codigo text;
  v_intentos int := 0;
  v_fin timestamptz;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  if char_length(trim(coalesce(p_nombre, ''))) < 2 then
    raise exception 'El nombre del negocio es muy corto.' using errcode = '22023';
  end if;

  loop
    v_codigo := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
    exit when not exists (select 1 from public.empresa_accesos where codigo = v_codigo);
    v_intentos := v_intentos + 1;
    if v_intentos > 12 then
      raise exception 'No se pudo generar un código de acceso.' using errcode = '55000';
    end if;
  end loop;

  insert into public.empresas (nombre, moneda, creada_por, zona_horaria)
  values (trim(p_nombre), coalesce(p_moneda, 'PYG'), auth.uid(),
          coalesce(nullif(trim(p_zona), ''), 'America/Asuncion'))
  returning id into v_id;

  insert into public.miembros (empresa_id, user_id, nombre, rol)
  values (v_id, auth.uid(), coalesce(nullif(trim(p_nombre_usuario), ''), 'Propietario'), 'propietario');

  insert into public.empresa_accesos (empresa_id, codigo)
  values (v_id, v_codigo);

  -- La prueba se escribe acá directamente y no llamando a iniciar_prueba()
  -- porque esa función es de service_role: quien crea la empresa es un
  -- usuario común, y no queremos otorgarle ese permiso para esto.
  v_fin := now() + interval '14 days';
  insert into public.suscripciones (empresa_id, plan, estado, periodo_inicio, periodo_fin, prueba_fin)
  values (v_id, 'pro', 'prueba', now(), v_fin, v_fin);

  perform set_config('orden.suscripcion_confiable', '1', true);
  update public.empresas set plan = 'pro' where id = v_id;
  perform set_config('orden.suscripcion_confiable', '0', true);

  return v_id;
end $fn$;

-- La firma vieja (3 argumentos) queda muerta: si no la borramos, PostgREST
-- ve dos funciones con el mismo nombre y no sabe cuál llamar.
drop function if exists public.crear_empresa(text, text, text);

revoke all on function public.crear_empresa(text, text, text, text) from public, anon;
grant execute on function public.crear_empresa(text, text, text, text) to authenticated;

revoke all on function public.consumir_credito_ia(uuid) from public, anon;
revoke all on function public.uso_ia_actual(uuid)       from public, anon;
grant execute on function public.consumir_credito_ia(uuid) to authenticated;
grant execute on function public.uso_ia_actual(uuid)       to authenticated;

-- ------------------------------------------------------------
-- 10. TOPE DE MIEMBROS POR PLAN
--
--    Se controla al ENTRAR, no de forma retroactiva: si una empresa ya
--    tiene cinco personas y su plan pasa a permitir dos, nadie queda
--    afuera. Echar gente que ya trabajaba adentro por un cambio de precio
--    sería romperle el negocio a alguien.
-- ------------------------------------------------------------
create or replace function public.unirse_empresa(
  p_codigo text,
  p_nombre_usuario text default null
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_id      uuid;
  v_cuantos integer;
  v_tope    integer;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  select a.empresa_id into v_id
  from public.empresa_accesos a
  where a.codigo = upper(trim(coalesce(p_codigo, ''))) and a.activo;

  if v_id is null then
    raise exception 'El código no corresponde a ninguna empresa.' using errcode = '42501';
  end if;

  -- Ya es miembro: no es un error, simplemente devolvemos la empresa.
  if exists (select 1 from public.miembros where empresa_id = v_id and user_id = auth.uid()) then
    return v_id;
  end if;

  select count(*)::int into v_cuantos from public.miembros where empresa_id = v_id;
  v_tope := (public.limites_plan(public.plan_efectivo_calculado(v_id))->>'miembros')::integer;

  if v_cuantos >= v_tope then
    raise exception 'Este negocio llegó al máximo de % personas de su plan. El plan Negocio permite más.', v_tope
      using errcode = '54000';
  end if;

  insert into public.miembros (empresa_id, user_id, nombre, rol)
  values (v_id, auth.uid(), coalesce(nullif(trim(p_nombre_usuario), ''), 'Colaborador'), 'vendedor')
  on conflict (empresa_id, user_id) do nothing;

  return v_id;
end $fn$;

revoke all on function public.unirse_empresa(text, text) from public, anon;
grant execute on function public.unirse_empresa(text, text) to authenticated;


-- ############################################################
-- ##  010_preferencias_avisos.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 010 · Preferencias, avisos y datos del plan
--
--   · PREFERENCIAS son del USUARIO, no de la empresa. El idioma lo elige la
--     persona: en un negocio pueden convivir alguien que lee español y
--     alguien que lee portugués, y la empresa es una sola.
--
--   · DISPOSITIVOS PUSH: una persona puede tener el celular y la compu. Cada
--     navegador es un endpoint distinto, y el endpoint es la identidad.
--
--   · ENVÍOS: para que el resumen semanal no llegue dos veces si el cron se
--     dispara de más. La clave única es la garantía, no un `if` en el código.
--
-- Y cierra el círculo del plan: datos_empresa() pasa a devolver también qué
-- permite el plan y cuánto va usado, para que la app no tenga que adivinarlo
-- ni pedirlo aparte en cada pantalla.
--
-- Idempotente. No toca datos existentes.
-- ============================================================

-- ------------------------------------------------------------
-- 1. PREFERENCIAS
--
--    `idioma` no tiene check contra una lista cerrada a propósito: agregar
--    un idioma nuevo no debería requerir una migración. Si llega uno que la
--    app no conoce, el diccionario cae a inglés y no se rompe nada.
-- ------------------------------------------------------------
create table if not exists public.preferencias (
  user_id       uuid primary key references auth.users (id) on delete cascade,
  idioma        text not null default 'es',
  -- Aviso de la noche: "todavía no cargaste nada hoy".
  aviso_cierre  boolean not null default true,
  -- Resumen del lunes por email.
  aviso_semanal boolean not null default true,
  -- A qué hora, en la zona del negocio, tiene sentido recordarle.
  hora_cierre   smallint not null default 20 check (hora_cierre between 0 and 23),
  updated_at    timestamptz not null default now()
);

alter table public.preferencias enable row level security;

drop policy if exists preferencias_select on public.preferencias;
create policy preferencias_select on public.preferencias
  for select to authenticated using (user_id = auth.uid());

revoke all on public.preferencias from anon, authenticated;
grant select on public.preferencias to authenticated;

create or replace function public.mis_preferencias()
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_res jsonb;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'idioma', p.idioma, 'aviso_cierre', p.aviso_cierre,
    'aviso_semanal', p.aviso_semanal, 'hora_cierre', p.hora_cierre
  ) into v_res
  from public.preferencias p where p.user_id = auth.uid();

  -- Sin fila todavía: devolvemos los valores por defecto en vez de null,
  -- así la pantalla no tiene que distinguir "no eligió" de "no existe".
  return coalesce(v_res, jsonb_build_object(
    'idioma', 'es', 'aviso_cierre', true, 'aviso_semanal', true, 'hora_cierre', 20));
end $fn$;

create or replace function public.guardar_preferencias(
  p_idioma text default null,
  p_aviso_cierre boolean default null,
  p_aviso_semanal boolean default null,
  p_hora_cierre smallint default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  insert into public.preferencias as p (user_id, idioma, aviso_cierre, aviso_semanal, hora_cierre)
  values (
    auth.uid(),
    coalesce(nullif(lower(trim(p_idioma)), ''), 'es'),
    coalesce(p_aviso_cierre, true),
    coalesce(p_aviso_semanal, true),
    coalesce(p_hora_cierre, 20::smallint)
  )
  on conflict (user_id) do update set
    -- coalesce con el valor viejo: mandar un solo campo no borra los otros.
    idioma        = coalesce(nullif(lower(trim(p_idioma)), ''), p.idioma),
    aviso_cierre  = coalesce(p_aviso_cierre,  p.aviso_cierre),
    aviso_semanal = coalesce(p_aviso_semanal, p.aviso_semanal),
    hora_cierre   = coalesce(p_hora_cierre,   p.hora_cierre),
    updated_at    = now();

  return public.mis_preferencias();
end $fn$;

-- ------------------------------------------------------------
-- 2. DISPOSITIVOS PUSH
--
--    El endpoint es único en todo el sistema, no por usuario: si alguien
--    cierra sesión y entra otra persona en el mismo navegador, la
--    suscripción tiene que cambiar de dueño, no duplicarse. Por eso el
--    upsert pisa `user_id`.
-- ------------------------------------------------------------
create table if not exists public.push_dispositivos (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references auth.users (id) on delete cascade,
  endpoint    text not null unique,
  p256dh      text not null,
  auth_clave  text not null,
  navegador   text,
  created_at  timestamptz not null default now(),
  ultimo_uso  timestamptz
);

create index if not exists push_user_idx on public.push_dispositivos (user_id);

alter table public.push_dispositivos enable row level security;

drop policy if exists push_select on public.push_dispositivos;
create policy push_select on public.push_dispositivos
  for select to authenticated using (user_id = auth.uid());

revoke all on public.push_dispositivos from anon, authenticated;
grant select on public.push_dispositivos to authenticated;

create or replace function public.registrar_dispositivo(
  p_endpoint text, p_p256dh text, p_auth text, p_navegador text default null
)
returns void language plpgsql security definer set search_path = public as $fn$
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if coalesce(trim(p_endpoint), '') = '' or coalesce(trim(p_p256dh), '') = ''
     or coalesce(trim(p_auth), '') = '' then
    raise exception 'Faltan datos de la suscripción push.' using errcode = '22023';
  end if;

  insert into public.push_dispositivos (user_id, endpoint, p256dh, auth_clave, navegador)
  values (auth.uid(), p_endpoint, p_p256dh, p_auth, left(coalesce(p_navegador, ''), 200))
  on conflict (endpoint) do update set
    user_id    = auth.uid(),
    p256dh     = excluded.p256dh,
    auth_clave = excluded.auth_clave,
    navegador  = excluded.navegador;
end $fn$;

create or replace function public.borrar_dispositivo(p_endpoint text)
returns void language plpgsql security definer set search_path = public as $fn$
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  delete from public.push_dispositivos where endpoint = p_endpoint and user_id = auth.uid();
end $fn$;

-- Baja desde el servidor: cuando el proveedor push responde 404/410, esa
-- suscripción está muerta y hay que sacarla o se reintenta para siempre.
create or replace function public.purgar_dispositivo(p_endpoint text)
returns void language sql security definer set search_path = public as $fn$
  delete from public.push_dispositivos where endpoint = p_endpoint;
$fn$;

-- ------------------------------------------------------------
-- 3. ENVÍOS · idempotencia de los avisos
--
--    `clave` incluye el periodo: 'semanal:<empresa>:2026-W34'. Si el cron
--    corre dos veces, el segundo insert choca contra el índice único y no
--    se manda nada. La garantía es de la base, no del código que la llama.
-- ------------------------------------------------------------
create table if not exists public.envios (
  id         uuid primary key default gen_random_uuid(),
  tipo       text not null,
  clave      text not null unique,
  user_id    uuid references auth.users (id) on delete set null,
  empresa_id uuid references public.empresas (id) on delete cascade,
  canal      text not null default 'email',
  enviado_at timestamptz not null default now()
);

create index if not exists envios_empresa_idx on public.envios (empresa_id, enviado_at desc);

alter table public.envios enable row level security;
revoke all on public.envios from anon, authenticated;

-- Reserva el envío. Devuelve true solo la primera vez.
create or replace function public.reservar_envio(
  p_tipo text, p_clave text, p_user uuid default null,
  p_empresa uuid default null, p_canal text default 'email'
)
returns boolean language plpgsql security definer set search_path = public as $fn$
begin
  insert into public.envios (tipo, clave, user_id, empresa_id, canal)
  values (p_tipo, p_clave, p_user, p_empresa, coalesce(p_canal, 'email'));
  return true;
exception when unique_violation then
  return false;
end $fn$;

-- ------------------------------------------------------------
-- 4. DESTINATARIOS DEL RESUMEN SEMANAL
--
--    Solo propietarios y administradores: el resumen trae ganancia y
--    márgenes, que un vendedor no puede ver. Mandárselo por email sería
--    saltarse por la puerta de atrás el permiso por columna que la 003
--    puso con tanto cuidado.
--
--    Y solo negocios con actividad en los últimos 30 días: escribirle a
--    quien abandonó hace meses es spam, no retención.
-- ------------------------------------------------------------
create or replace function public.destinatarios_resumen_semanal()
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_res jsonb;
begin
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'user_id',    u.id,
      'email',      u.email,
      'nombre',     mi.nombre,
      'empresa_id', e.id,
      'empresa',    e.nombre,
      'moneda',     e.moneda,
      'zona',       e.zona_horaria,
      'idioma',     coalesce(p.idioma, 'es')
    ) as x
    from public.miembros mi
    join public.empresas e on e.id = mi.empresa_id
    join auth.users u      on u.id = mi.user_id
    left join public.preferencias p on p.user_id = mi.user_id
    where mi.rol in ('propietario', 'admin')
      and u.email is not null
      and coalesce(p.aviso_semanal, true)
      and exists (
        select 1 from public.movimientos m
        where m.empresa_id = e.id and m.estado = 'activo'
          and m.fecha >= (now() at time zone e.zona_horaria)::date - 30
      )
  ) s;

  return v_res;
end $fn$;

-- ------------------------------------------------------------
-- 5. DATOS DE LA EMPRESA · ahora también dice qué permite el plan
--
--    Una sola llamada por carga de página ya traía nombre, moneda y plan.
--    Sumarle límites y uso evita dos viajes más y, sobre todo, evita que
--    cada pantalla decida por su cuenta qué significa "pro".
-- ------------------------------------------------------------
create or replace function public.datos_empresa(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_res   jsonb;
  v_plan  text;
  v_sus   public.suscripciones;
  v_usados integer;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  v_plan := public.plan_efectivo_calculado(p_empresa);
  select * into v_sus from public.suscripciones where empresa_id = p_empresa;

  select usados into v_usados from public.uso_ia
  where empresa_id = p_empresa and periodo = to_char(public.hoy_empresa(p_empresa), 'YYYY-MM');

  select jsonb_build_object(
    'id', e.id,
    'nombre', e.nombre,
    'moneda', e.moneda,
    'zona_horaria', e.zona_horaria,
    'plan_efectivo', v_plan,
    'permitir_stock_negativo', e.permitir_stock_negativo,
    'codigo_acceso', case
      when public.es_admin(e.id) then (select a.codigo from public.empresa_accesos a where a.empresa_id = e.id and a.activo)
      else null
    end,
    'limites', public.limites_plan(v_plan),
    'uso_ia', jsonb_build_object('usados', coalesce(v_usados, 0),
                                 'tope', (public.limites_plan(v_plan)->>'capturas_mes')::integer),
    'suscripcion', jsonb_build_object(
      'estado',      coalesce(v_sus.estado, 'activa'),
      'plan',        coalesce(v_sus.plan, 'gratis'),
      'periodo',     coalesce(v_sus.periodo, 'mensual'),
      'periodo_fin', v_sus.periodo_fin,
      'en_prueba',   coalesce(v_sus.estado, '') = 'prueba'
                     and v_sus.periodo_fin is not null and v_sus.periodo_fin > now(),
      -- Días enteros que faltan. Se redondea hacia arriba: mientras quede
      -- una hora, todavía es "un día", no "cero días".
      'dias_restantes', case
        when v_sus.periodo_fin is null or v_sus.periodo_fin <= now() then 0
        else ceil(extract(epoch from (v_sus.periodo_fin - now())) / 86400)::int
      end,
      'ya_uso_prueba', v_sus.prueba_fin is not null,
      'cancela_al_vencer', coalesce(v_sus.cancela_al_vencer, false)
    ),
    'miembros', (select count(*)::int from public.miembros mm where mm.empresa_id = e.id)
  ) into v_res
  from public.empresas e where e.id = p_empresa;

  return v_res;
end $fn$;

-- ------------------------------------------------------------
-- 6. ZONA HORARIA · quien administra puede corregirla
--
--    Va por función y no por update directo porque el trigger
--    `empresas_proteger` bloquea la escritura sobre empresas.
-- ------------------------------------------------------------
create or replace function public.actualizar_zona(p_empresa uuid, p_zona text)
returns text language plpgsql security definer set search_path = public as $fn$
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el propietario o un administrador puede cambiar la zona horaria.' using errcode = '42501';
  end if;
  if not exists (select 1 from pg_timezone_names where name = p_zona) then
    raise exception 'Esa zona horaria no existe.' using errcode = '22023';
  end if;

  update public.empresas set zona_horaria = p_zona where id = p_empresa;
  return p_zona;
end $fn$;

revoke all on function public.mis_preferencias()                                    from public, anon;
revoke all on function public.guardar_preferencias(text, boolean, boolean, smallint) from public, anon;
revoke all on function public.registrar_dispositivo(text, text, text, text)         from public, anon;
revoke all on function public.borrar_dispositivo(text)                              from public, anon;
revoke all on function public.actualizar_zona(uuid, text)                           from public, anon;
revoke all on function public.purgar_dispositivo(text)             from public, anon, authenticated;
revoke all on function public.reservar_envio(text, text, uuid, uuid, text) from public, anon, authenticated;
revoke all on function public.destinatarios_resumen_semanal()      from public, anon, authenticated;

grant execute on function public.mis_preferencias()                                    to authenticated;
grant execute on function public.guardar_preferencias(text, boolean, boolean, smallint) to authenticated;
grant execute on function public.registrar_dispositivo(text, text, text, text)         to authenticated;
grant execute on function public.borrar_dispositivo(text)                              to authenticated;
grant execute on function public.actualizar_zona(uuid, text)                           to authenticated;
grant execute on function public.purgar_dispositivo(text)                              to service_role;
grant execute on function public.reservar_envio(text, text, uuid, uuid, text)          to service_role;
grant execute on function public.destinatarios_resumen_semanal()                       to service_role;

-- El cron necesita leer para armar los mensajes.
grant select on public.push_dispositivos to service_role;
grant select, insert on public.envios    to service_role;
grant select on public.preferencias      to service_role;


-- ############################################################
-- ##  011_baja_de_miembros.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 011 · Dar de baja a alguien del equipo
--
-- La policy `miembros_delete` de la 002 ya dejaba a un administrador borrar
-- filas de `miembros`, pero por la puerta cruda: sin mensajes claros, sin
-- impedir que alguien se borre a sí mismo y sin jerarquía entre roles.
-- Esta migración pone la puerta oficial.
--
-- QUÉ PASA CON LO QUE ESA PERSONA CARGÓ: nada. Sus ventas y gastos quedan
-- exactamente donde están, con su nombre. `movimientos.creado_por` apunta a
-- `auth.users`, no a `miembros`, así que sacarla del equipo no toca ni un
-- número. Borrar el historial de alguien porque dejó de trabajar ahí sería
-- destruir la contabilidad del negocio.
--
-- Y SE ROTA EL CÓDIGO. Sacar a alguien que puede volver a entrar con el
-- mismo código de invitación es media baja. Por eso va también
-- `rotar_codigo_acceso()`: el propietario genera uno nuevo y el viejo deja
-- de servir para siempre.
--
-- Idempotente. No toca datos existentes.
-- ============================================================

-- ------------------------------------------------------------
-- 1. QUITAR A ALGUIEN DEL EQUIPO
--
--    Jerarquía, de arriba abajo:
--      · el propietario puede sacar a cualquiera menos a sí mismo;
--      · un administrador solo puede sacar vendedores;
--      · nadie puede sacarse a sí mismo (no existe "irse" y hacerlo por
--        accidente dejaría al negocio sin dueño).
--
--    Devuelve el nombre de quien salió, para poder confirmarlo en pantalla
--    sin tener que volver a consultar.
-- ------------------------------------------------------------
create or replace function public.quitar_miembro(p_empresa uuid, p_user uuid)
returns text language plpgsql security definer set search_path = public as $fn$
declare
  v_fila     public.miembros;
  v_mi_rol   rol_miembro;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el propietario o un administrador puede sacar gente del equipo.' using errcode = '42501';
  end if;

  select * into v_fila
  from public.miembros where empresa_id = p_empresa and user_id = p_user;

  if v_fila.id is null then
    raise exception 'Esa persona no está en el equipo.' using errcode = 'P0002';
  end if;

  if v_fila.user_id = auth.uid() then
    raise exception 'No podés sacarte a vos mismo del equipo.' using errcode = '42501';
  end if;

  if v_fila.rol = 'propietario' then
    raise exception 'Al propietario del negocio no se lo puede sacar.' using errcode = '42501';
  end if;

  select rol into v_mi_rol
  from public.miembros where empresa_id = p_empresa and user_id = auth.uid();

  if v_mi_rol = 'admin' and v_fila.rol = 'admin' then
    raise exception 'Un administrador no puede sacar a otro administrador. Pedíselo al propietario.'
      using errcode = '42501';
  end if;

  -- Solo se borra la membresía. Los movimientos que cargó quedan intactos.
  delete from public.miembros where id = v_fila.id;

  return v_fila.nombre;
end $fn$;

-- ------------------------------------------------------------
-- 2. ROTAR EL CÓDIGO DE INVITACIÓN
--
--    Solo el propietario. Un administrador puede VER el código para pasarlo,
--    pero cambiarlo deja afuera a todo el que lo tuviera anotado, y esa es
--    una decisión del dueño del negocio.
-- ------------------------------------------------------------
create or replace function public.rotar_codigo_acceso(p_empresa uuid)
returns text language plpgsql security definer set search_path = public as $fn$
declare
  v_codigo   text;
  v_intentos int := 0;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.miembros
    where empresa_id = p_empresa and user_id = auth.uid() and rol = 'propietario'
  ) then
    raise exception 'Solo el propietario puede cambiar el código de invitación.' using errcode = '42501';
  end if;

  loop
    v_codigo := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
    exit when not exists (select 1 from public.empresa_accesos where codigo = v_codigo);
    v_intentos := v_intentos + 1;
    if v_intentos > 12 then
      raise exception 'No se pudo generar un código nuevo.' using errcode = '55000';
    end if;
  end loop;

  update public.empresa_accesos
  set codigo = v_codigo, updated_at = now()
  where empresa_id = p_empresa;

  return v_codigo;
end $fn$;

-- ------------------------------------------------------------
-- 3. CERRAR LA PUERTA CRUDA
--
--    La policy de la 002 permitía a un administrador borrar cualquier fila
--    que no fuera del propietario, incluida la suya. Se le agrega la misma
--    guarda que tiene la función: nadie se borra a sí mismo por accidente
--    desde la consola del navegador.
-- ------------------------------------------------------------
drop policy if exists miembros_delete on public.miembros;
create policy miembros_delete on public.miembros
  for delete using (
    public.es_admin(empresa_id)
    and rol <> 'propietario'
    and user_id <> auth.uid()
  );

revoke all on function public.quitar_miembro(uuid, uuid)   from public, anon;
revoke all on function public.rotar_codigo_acceso(uuid)    from public, anon;
grant execute on function public.quitar_miembro(uuid, uuid) to authenticated;
grant execute on function public.rotar_codigo_acceso(uuid)  to authenticated;


-- ############################################################
-- ##  012_cerrar_anon.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 012 · Cerrarle la puerta a `anon`
--
-- Dos hallazgos del linter de Supabase, los dos reales.
--
-- 1. NUEVE FUNCIONES SEGUÍAN OTORGADAS A `anon`, el rol de quien NO inició
--    sesión. Entre ellas `registrar_venta`, `anular_movimiento` y
--    `reemplazar_venta`, que escriben.
--
--    ¿Se podía hacer daño? No: las tres arrancan con
--    `if auth.uid() is null then raise`. Alguien sin sesión que las llamara
--    recibía un error, no una venta.
--
--    Entonces, ¿por qué se toca? Porque esa defensa está a UNA línea de
--    distancia de desaparecer. El día que alguien edite una de esas
--    funciones y mueva o borre esa guarda sin darse cuenta, una ruta pública
--    de internet queda escribiendo en la base. El permiso no debería
--    depender de que nadie se equivoque nunca dentro del cuerpo de la
--    función.
--
--    Vienen de la 001: Supabase otorga EXECUTE a `anon` y `authenticated`
--    por defecto sobre todo lo que se crea en `public`, y las migraciones
--    posteriores revocaron caso por caso, pero estas quedaron afuera.
--
--    `lista_precios` SÍ se queda: la pantalla de planes tiene que poder
--    mostrar los precios antes de que la persona se registre.
--
-- 2. TRES FUNCIONES SIN `search_path` FIJO. Dos son de la 007 y las
--    escribimos nosotros. En estas tres el riesgo es teórico —devuelven
--    constantes o no tocan tablas— pero dejar la excepción invita a
--    copiarla en la próxima función, que sí va a tocar tablas.
--
-- Idempotente. No toca datos.
-- ============================================================

-- ------------------------------------------------------------
-- 1. FUERA `anon`
--
--    Se usa `do` con `to_regprocedure` para no fallar si alguna firma no
--    existe en una instalación vieja: revocar algo que no está no debería
--    tirar abajo la migración.
-- ------------------------------------------------------------
--    OJO CON CÓMO SE REVOCA. `revoke ... from anon` NO alcanza y no da
--    ningún error: PostgreSQL otorga EXECUTE sobre toda función nueva al
--    pseudo-rol PUBLIC, y `anon` lo hereda de ahí. Revocarle a `anon` un
--    permiso que nunca tuvo en forma directa no cambia nada; hay que
--    quitárselo a PUBLIC y volver a otorgárselo explícitamente a quien sí
--    lo necesita.
do $bloque$
declare
  v_firma text;
  v_firmas text[] := array[
    'public.registrar_venta(uuid, jsonb, date, text, text, text, text, origen_captura, numeric)',
    'public.reemplazar_venta(uuid, jsonb, date, text, text, text, text, numeric)',
    'public.anular_movimiento(uuid, text)',
    'public.datos_empresa(uuid)',
    'public.empresa_es_pro(uuid)',
    'public.es_admin(uuid)',
    'public.es_miembro(uuid)',
    'public.plan_efectivo(uuid)'
  ];
begin
  foreach v_firma in array v_firmas loop
    if to_regprocedure(v_firma) is not null then
      execute format('revoke all on function %s from public, anon', v_firma);
      execute format('grant execute on function %s to authenticated', v_firma);
    else
      raise notice 'No existe %, se omite.', v_firma;
    end if;
  end loop;
end $bloque$;

-- `lista_precios` es la excepción y se deja explícita, para que se vea que
-- es una decisión y no un olvido: la pantalla de planes muestra los precios
-- antes de que la persona tenga cuenta.
grant execute on function public.lista_precios(text) to anon, authenticated;

-- ------------------------------------------------------------
-- 2. `search_path` FIJO EN LAS TRES QUE FALTABAN
--
--    `alter function ... set search_path` no reescribe el cuerpo: solo le
--    clava el esquema. Es la forma más chica de cerrarlo.
-- ------------------------------------------------------------
do $bloque$
declare
  v_firma text;
  v_firmas text[] := array[
    'public.jsonb_elements_ordenados(jsonb)',
    'public.limite_adjuntos_movimiento()',
    'public.limite_bytes_adjunto()'
  ];
begin
  foreach v_firma in array v_firmas loop
    if to_regprocedure(v_firma) is not null then
      execute format('alter function %s set search_path = public', v_firma);
    end if;
  end loop;
end $bloque$;


-- ############################################################
-- ##  013_borrar_usuario.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 013 · Que se pueda borrar un usuario
--
-- EL PROBLEMA, tal como apareció en producción:
--
--   ERROR: update or delete on table "users" violates foreign key constraint
--   "empresas_creada_por_fkey" on table "empresas"
--
-- `empresas.creada_por` apuntaba a `auth.users` con ON DELETE RESTRICT. La
-- intención era buena —no perder el registro de quién fundó el negocio— pero
-- el efecto era que **una persona que creó una empresa no se podía borrar
-- nunca**. Ni para limpiar una cuenta de prueba, ni el día que alguien pida
-- que se borren sus datos.
--
-- LA SOLUCIÓN: ON DELETE SET NULL. Si se borra la persona, la empresa sigue
-- entera —con sus ventas, su stock y su equipo— y lo único que se pierde es
-- el dato de quién la creó. Borrar el negocio de un local que sigue
-- funcionando porque se dio de baja una cuenta sería mucho peor.
--
-- LA TRAMPA: `ON DELETE SET NULL` ejecuta un UPDATE sobre `empresas`, y el
-- trigger `proteger_empresa` bloquea cualquier cambio de `creada_por`. O sea
-- que sin tocar el trigger, cambiar la clave foránea no arregla nada: el
-- borrado seguiría fallando, ahora con otro mensaje. Por eso van las dos
-- cosas juntas en esta migración.
--
-- Idempotente. No toca datos.
-- ============================================================

-- ------------------------------------------------------------
-- 1. LA COLUMNA ADMITE NULL Y LA CLAVE PASA A SET NULL
-- ------------------------------------------------------------
alter table public.empresas alter column creada_por drop not null;

alter table public.empresas drop constraint if exists empresas_creada_por_fkey;

alter table public.empresas
  add constraint empresas_creada_por_fkey
  foreign key (creada_por) references auth.users (id) on delete set null;

comment on column public.empresas.creada_por is
  'Quién fundó el negocio. Queda en null si esa cuenta se borra: la empresa y toda su contabilidad sobreviven.';

-- ------------------------------------------------------------
-- 2. EL TRIGGER DEJA PASAR EL BORRADO, PERO NADA MÁS
--
--    Se permite exactamente una transición: de "alguien" a "nadie", que es
--    la que hace la clave foránea al borrarse la cuenta.
--
--    Lo que se sigue bloqueando es lo que importaba: **apropiarse** de una
--    empresa poniéndose como creador. De null a alguien, o de una persona a
--    otra, sigue siendo imposible.
-- ------------------------------------------------------------
create or replace function public.proteger_empresa()
returns trigger language plpgsql security definer set search_path = public as $fn$
begin
  if new.id is distinct from old.id then
    raise exception 'No se pueden cambiar los datos de identidad de la empresa.' using errcode = '42501';
  end if;

  if new.creada_por is distinct from old.creada_por
     and not (new.creada_por is null and old.creada_por is not null) then
    raise exception 'No se puede cambiar quién creó la empresa.' using errcode = '42501';
  end if;

  if new.plan is distinct from old.plan
     and coalesce(current_setting('orden.suscripcion_confiable', true), '') <> '1' then
    raise exception 'El plan solo lo puede cambiar el sistema de suscripciones.' using errcode = '42501';
  end if;

  return new;
end $fn$;


-- ############################################################
-- ##  014_borrar_mi_cuenta.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 014 · Que cada uno pueda borrar su propia cuenta
--
-- No es solo un requisito legal: los datos son de la persona, y una app que
-- no te deja irte es una app que te tiene de rehén. Si alguien quiere borrar
-- todo, tiene que poder hacerlo solo, sin escribirle a nadie.
--
-- LA PREGUNTA DIFÍCIL: ¿qué pasa con el negocio?
--
--   · Si sos el ÚNICO en tu empresa → se borra entera. Es tuya y nadie más
--     la usa.
--   · Si sos propietario Y HAY MÁS GENTE ADENTRO → NO se borra nada. Sería
--     dejar sin sistema a personas que están trabajando, y borrarles la
--     contabilidad de su negocio. Se avisa y se pide que primero saque a los
--     demás (o que no se vaya).
--   · Si sos vendedor o admin de la empresa de otro → solo se va tu
--     membresía. La empresa y todo lo que cargaste quedan intactos: esos
--     movimientos son del negocio, no tuyos.
--
-- SE BORRA DE VERDAD. No hay "marcado como borrado": las filas desaparecen y
-- el borrado en cascada se lleva movimientos, productos, comprobantes,
-- suscripción y códigos. Lo único que queda afuera son los ARCHIVOS de
-- Storage, que no entienden de claves foráneas y los borra la ruta que llama
-- a esto (ver src/app/api/cuenta/borrar/route.ts).
--
-- Idempotente. No toca datos existentes.
-- ============================================================

-- ------------------------------------------------------------
-- 1. QUÉ VA A PASAR SI ME BORRO
--
--    Se lo pide la pantalla ANTES de mostrar el botón, para que nadie
--    confirme sin saber qué está por perder. Es de solo lectura: no borra
--    nada, solo cuenta.
-- ------------------------------------------------------------
create or replace function public.resumen_borrado_cuenta()
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_uid  uuid := auth.uid();
  v_res  jsonb;
begin
  if v_uid is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  with mias as (
    select
      e.id,
      e.nombre,
      m.rol,
      (select count(*)::int from public.miembros mm where mm.empresa_id = e.id) as gente,
      (select count(*)::int from public.movimientos mv where mv.empresa_id = e.id) as movimientos
    from public.miembros m
    join public.empresas e on e.id = m.empresa_id
    where m.user_id = v_uid
  )
  select jsonb_build_object(
    -- Empresas que desaparecen: soy propietario y estoy solo.
    'se_borran', coalesce((
      select jsonb_agg(jsonb_build_object('nombre', nombre, 'movimientos', movimientos))
      from mias where rol = 'propietario' and gente = 1
    ), '[]'::jsonb),
    -- Empresas de las que solo me voy.
    'me_voy_de', coalesce((
      select jsonb_agg(jsonb_build_object('nombre', nombre))
      from mias where rol <> 'propietario'
    ), '[]'::jsonb),
    -- Lo que bloquea: soy propietario y hay más gente adentro.
    'bloqueadas', coalesce((
      select jsonb_agg(jsonb_build_object('nombre', nombre, 'gente', gente))
      from mias where rol = 'propietario' and gente > 1
    ), '[]'::jsonb),
    'movimientos_que_se_pierden', coalesce((
      select sum(movimientos)::int from mias where rol = 'propietario' and gente = 1
    ), 0)
  ) into v_res;

  return v_res;
end $fn$;

-- ------------------------------------------------------------
-- 2. LAS RUTAS DE LOS ARCHIVOS QUE HAY QUE LIMPIAR
--
--    Storage no tiene claves foráneas: borrar la empresa se lleva las filas
--    de `adjuntos`, pero los archivos quedan ocupando lugar para siempre.
--    Esta función devuelve qué borrar, y la ruta lo hace ANTES de borrar los
--    datos (después ya no habría cómo saber cuáles eran).
-- ------------------------------------------------------------
create or replace function public.archivos_a_borrar(p_user uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_res jsonb;
begin
  select coalesce(jsonb_agg(a.ruta), '[]'::jsonb) into v_res
  from public.adjuntos a
  where a.ruta is not null
    and a.empresa_id in (
      select m.empresa_id
      from public.miembros m
      where m.user_id = p_user
        and m.rol = 'propietario'
        and (select count(*) from public.miembros mm where mm.empresa_id = m.empresa_id) = 1
    );

  return v_res;
end $fn$;

-- ------------------------------------------------------------
-- 3. BORRAR
--
--    Solo `service_role`: la llama la ruta del servidor después de comprobar
--    la sesión. No se le otorga a `authenticated` a propósito — un borrado
--    irreversible no se dispara desde el navegador sin que el servidor haya
--    verificado quién es y que confirmó.
--
--    Devuelve qué se hizo, para poder registrarlo.
-- ------------------------------------------------------------
create or replace function public.borrar_datos_de_usuario(p_user uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_bloqueadas int;
  v_borradas   int := 0;
  v_salidas    int := 0;
begin
  if p_user is null then
    raise exception 'Falta el usuario.' using errcode = '22023';
  end if;

  -- Si es propietario de una empresa con más gente, no se toca NADA.
  -- Se comprueba de nuevo acá y no solo en la pantalla: entre que alguien
  -- confirma y se ejecuta esto, pudo entrar un vendedor con el código.
  select count(*) into v_bloqueadas
  from public.miembros m
  where m.user_id = p_user
    and m.rol = 'propietario'
    and (select count(*) from public.miembros mm where mm.empresa_id = m.empresa_id) > 1;

  if v_bloqueadas > 0 then
    raise exception 'Todavía hay gente trabajando en % de tus negocios. Sacalos del equipo antes de borrar tu cuenta.', v_bloqueadas
      using errcode = '54000';
  end if;

  -- Empresas donde estoy solo: se van enteras. El cascade se lleva
  -- movimientos, items, productos, adjuntos, retos, suscripción y accesos.
  with a_borrar as (
    select m.empresa_id
    from public.miembros m
    where m.user_id = p_user and m.rol = 'propietario'
  ), borradas as (
    delete from public.empresas e
    where e.id in (select empresa_id from a_borrar)
    returning 1
  )
  select count(*) into v_borradas from borradas;

  -- De las demás, solo me voy.
  with salidas as (
    delete from public.miembros m where m.user_id = p_user returning 1
  )
  select count(*) into v_salidas from salidas;

  -- Lo que es de la persona y no del negocio.
  delete from public.preferencias      where user_id = p_user;
  delete from public.push_dispositivos where user_id = p_user;
  delete from public.cierres           where user_id = p_user;

  return jsonb_build_object(
    'empresas_borradas', v_borradas,
    'membresias_cerradas', v_salidas
  );
end $fn$;

revoke all on function public.resumen_borrado_cuenta()          from public, anon;
revoke all on function public.archivos_a_borrar(uuid)           from public, anon, authenticated;
revoke all on function public.borrar_datos_de_usuario(uuid)     from public, anon, authenticated;

grant execute on function public.resumen_borrado_cuenta()       to authenticated;
grant execute on function public.archivos_a_borrar(uuid)        to service_role;
grant execute on function public.borrar_datos_de_usuario(uuid)  to service_role;

-- El borrado necesita poder eliminar filas de estas tablas desde el cron/API.
grant delete on public.empresas          to service_role;
grant delete on public.miembros          to service_role;
grant delete on public.preferencias      to service_role;
grant delete on public.push_dispositivos to service_role;
grant delete on public.cierres           to service_role;

-- ============================================================
-- EMPEZAR DE CERO
--
-- Distinto de borrar la cuenta: acá la persona SE QUEDA. Vacía el negocio
-- para arrancar limpio —después de probar el sistema, después de un año
-- cerrado, después de cargar todo mal la primera vez.
--
-- Es la única puerta por la que un movimiento se borra de verdad. La policy
-- `movimientos_delete` no existe justamente para que no se pueda: lo normal
-- es ANULAR, que deja el rastro. Vaciar es otra cosa y por eso pide escribir
-- el nombre del negocio: nadie lo hace sin querer.
--
-- QUÉ SE VA: movimientos (y con ellos sus líneas y comprobantes), productos,
-- retos y los cierres marcados.
--
-- QUÉ SE QUEDA: la empresa, el equipo, la suscripción y el código de
-- invitación. Y el CONSUMO DE IA DEL MES, a propósito: si vaciar reseteara
-- el contador, sería una forma de tener capturas gratis infinitas vaciando
-- el negocio cada vez que se acaban.
-- ============================================================
create or replace function public.vaciar_empresa(p_empresa uuid, p_confirmacion text)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_nombre     text;
  v_rutas      jsonb;
  v_movs       int := 0;
  v_prods      int := 0;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  -- Solo el propietario. Un administrador maneja el día a día, pero borrar
  -- la historia entera del negocio es decisión del dueño.
  if not exists (
    select 1 from public.miembros
    where empresa_id = p_empresa and user_id = auth.uid() and rol = 'propietario'
  ) then
    raise exception 'Solo el propietario puede vaciar el negocio.' using errcode = '42501';
  end if;

  select nombre into v_nombre from public.empresas where id = p_empresa;
  if v_nombre is null then
    raise exception 'Esa empresa no existe.' using errcode = 'P0002';
  end if;

  -- La confirmación es escribir el nombre exacto. Un "¿estás seguro?" se
  -- toca sin leer; esto no.
  if trim(coalesce(p_confirmacion, '')) is distinct from v_nombre then
    raise exception 'Para vaciar el negocio hay que escribir su nombre exacto: %', v_nombre
      using errcode = '22023';
  end if;

  -- Las rutas de los archivos ANTES de borrar: después no hay forma de
  -- saber cuáles eran, y quedarían ocupando storage para siempre.
  select coalesce(jsonb_agg(a.ruta), '[]'::jsonb) into v_rutas
  from public.adjuntos a where a.empresa_id = p_empresa and a.ruta is not null;

  -- Los movimientos primero: arrastran líneas y comprobantes.
  with borrados as (
    delete from public.movimientos where empresa_id = p_empresa returning 1
  )
  select count(*) into v_movs from borrados;

  with borrados as (
    delete from public.productos where empresa_id = p_empresa returning 1
  )
  select count(*) into v_prods from borrados;

  delete from public.retos   where empresa_id = p_empresa;
  delete from public.cierres where empresa_id = p_empresa;

  return jsonb_build_object(
    'movimientos', v_movs,
    'productos', v_prods,
    -- Que las borre quien llamó: la policy de storage ya le da permiso
    -- sobre la carpeta de su empresa.
    'archivos', v_rutas
  );
end $fn$;

revoke all on function public.vaciar_empresa(uuid, text) from public, anon;
grant execute on function public.vaciar_empresa(uuid, text) to authenticated;


-- ############################################################
-- ##  015_deudas.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 015 · Deudas
--
-- Tarjetas, préstamos y lo que se le debe al proveedor.
--
-- POR QUÉ ESTO NO ES UNA FUNCIÓN "PERSONAL"
--
-- Apareció pidiéndolo alguien que quería llevar sus gastos personales, pero
-- el comerciante debe plata igual o más: la cuota del préstamo con el que
-- compró la mercadería, la tarjeta, lo que le fía el proveedor. Un almacenero
-- que sabe que el 15 le vence una cuota de 800.000 toma decisiones distintas
-- que uno que se entera cuando le rebota el débito.
--
-- Por eso va adentro de Orden y no en otro sistema.
--
-- LA DECISIÓN QUE MÁS SE DISCUTE: ¿pagar una cuota es un gasto?
--
-- En contabilidad estricta, no del todo: devolver capital baja una deuda, no
-- es un gasto del período. Pero Orden no le habla a un contador, le habla a
-- alguien que quiere saber cuánta plata le queda. Y para esa persona, los
-- 800.000 de la cuota SALIERON de su bolsillo.
--
-- Solución: al registrar el pago se crea también el gasto, **y se puede
-- desactivar**. Quien lleva la contabilidad fina lo apaga; el resto ve la
-- plata salir, que es lo que espera.
--
-- Idempotente. No toca datos existentes.
-- ============================================================

do $$ begin
  create type tipo_deuda as enum ('tarjeta', 'prestamo', 'proveedor', 'otro');
exception when duplicate_object then null; end $$;

-- ------------------------------------------------------------
-- 1. LA DEUDA
--
--    `saldo` es lo que FALTA pagar y es el número que manda: se recalcula
--    con cada pago y nunca se toca a mano desde afuera. `monto_original`
--    queda como referencia histórica.
--
--    Las cuotas son opcionales: una tarjeta no tiene «12 cuotas», un
--    préstamo sí.
-- ------------------------------------------------------------
create table if not exists public.deudas (
  id              uuid primary key default gen_random_uuid(),
  empresa_id      uuid not null references public.empresas (id) on delete cascade,
  tipo            tipo_deuda not null default 'otro',
  nombre          text not null check (char_length(trim(nombre)) between 1 and 80),
  -- A quién se le debe: el banco, la financiera, el proveedor.
  acreedor        text not null default '',
  monto_original  numeric(14,2) not null check (monto_original >= 0),
  saldo           numeric(14,2) not null check (saldo >= 0),
  cuotas_totales  integer check (cuotas_totales is null or cuotas_totales > 0),
  cuotas_pagadas  integer not null default 0 check (cuotas_pagadas >= 0),
  -- Cuánto sale cada cuota, si son fijas.
  monto_cuota     numeric(14,2) check (monto_cuota is null or monto_cuota > 0),
  -- Próximo vencimiento. Se corre solo al registrar un pago.
  vence_el        date,
  notas           text not null default '',
  activa          boolean not null default true,
  creada_por      uuid references auth.users (id) on delete set null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),

  -- El saldo nunca puede pasar lo que se pidió: sería deber más de lo que
  -- se debía nunca.
  constraint deuda_saldo_coherente check (saldo <= monto_original),
  constraint deuda_cuotas_coherentes check (
    cuotas_totales is null or cuotas_pagadas <= cuotas_totales
  )
);

create index if not exists deudas_empresa_idx on public.deudas (empresa_id) where activa;
create index if not exists deudas_vence_idx   on public.deudas (empresa_id, vence_el) where activa and saldo > 0;

comment on table public.deudas is
  'Lo que el negocio debe: tarjetas, préstamos y proveedores. `saldo` es lo que falta pagar y solo lo cambia registrar_pago_deuda().';

-- ------------------------------------------------------------
-- 2. LOS PAGOS
--
--    Cada pago queda registrado con su fecha. Sin esto, el saldo sería un
--    número sin historia: no habría forma de saber si bajó porque se pagó o
--    porque alguien lo editó.
--
--    `movimiento_id` enlaza con el gasto que generó, si se generó. Al anular
--    ese gasto NO se deshace el pago: son dos cosas distintas y deshacer una
--    a espaldas de la otra dejaría los números peor.
-- ------------------------------------------------------------
create table if not exists public.pagos_deuda (
  id            uuid primary key default gen_random_uuid(),
  deuda_id      uuid not null references public.deudas (id) on delete cascade,
  empresa_id    uuid not null references public.empresas (id) on delete cascade,
  monto         numeric(14,2) not null check (monto > 0),
  fecha         date not null,
  movimiento_id uuid references public.movimientos (id) on delete set null,
  nota          text not null default '',
  creado_por    uuid references auth.users (id) on delete set null,
  created_at    timestamptz not null default now()
);

create index if not exists pagos_deuda_idx    on public.pagos_deuda (deuda_id, fecha desc);
create index if not exists pagos_empresa_idx  on public.pagos_deuda (empresa_id, fecha desc);

-- ------------------------------------------------------------
-- 3. RLS · lectura para el equipo, escritura solo por las funciones
--
--    Igual que con las ventas: si el insert estuviera abierto, cualquiera
--    podría bajarse el saldo de una deuda sin dejar rastro del pago.
-- ------------------------------------------------------------
alter table public.deudas      enable row level security;
alter table public.pagos_deuda enable row level security;

drop policy if exists deudas_select on public.deudas;
create policy deudas_select on public.deudas
  for select to authenticated using (public.es_miembro(empresa_id));

drop policy if exists pagos_deuda_select on public.pagos_deuda;
create policy pagos_deuda_select on public.pagos_deuda
  for select to authenticated using (public.es_miembro(empresa_id));

revoke all on public.deudas      from anon, authenticated;
revoke all on public.pagos_deuda from anon, authenticated;
grant select on public.deudas      to authenticated;
grant select on public.pagos_deuda to authenticated;

-- ------------------------------------------------------------
-- 4. CREAR
--
--    Solo administración: cuánto debe el negocio es información sensible,
--    del mismo orden que los costos. Un vendedor no la carga ni la cambia.
-- ------------------------------------------------------------
create or replace function public.crear_deuda(
  p_empresa         uuid,
  p_nombre          text,
  p_tipo            text default 'otro',
  p_acreedor        text default '',
  p_monto           numeric default 0,
  p_saldo           numeric default null,
  p_cuotas_totales  integer default null,
  p_monto_cuota     numeric default null,
  p_vence_el        date default null,
  p_notas           text default ''
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_id    uuid;
  v_saldo numeric;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el propietario o un administrador puede cargar deudas.' using errcode = '42501';
  end if;
  if p_tipo not in ('tarjeta', 'prestamo', 'proveedor', 'otro') then
    raise exception 'Tipo de deuda no reconocido.' using errcode = '22023';
  end if;
  if coalesce(p_monto, 0) <= 0 then
    raise exception 'La deuda tiene que tener un monto.' using errcode = '22023';
  end if;

  -- Sin saldo explícito se asume que todavía no se pagó nada. Es lo normal
  -- al cargar una deuda nueva, y evita que alguien la deje en cero sin querer.
  v_saldo := coalesce(p_saldo, p_monto);
  if v_saldo > p_monto then
    raise exception 'El saldo no puede ser mayor que el monto original.' using errcode = '22023';
  end if;

  insert into public.deudas (
    empresa_id, tipo, nombre, acreedor, monto_original, saldo,
    cuotas_totales, monto_cuota, vence_el, notas, creada_por
  ) values (
    p_empresa, p_tipo::tipo_deuda, trim(p_nombre), coalesce(trim(p_acreedor), ''),
    p_monto, v_saldo, p_cuotas_totales, p_monto_cuota, p_vence_el,
    coalesce(left(p_notas, 500), ''), auth.uid()
  )
  returning id into v_id;

  return v_id;
end $fn$;

-- ------------------------------------------------------------
-- 5. REGISTRAR UN PAGO
--
--    Todo en una transacción: baja el saldo, suma la cuota, corre el
--    vencimiento al mes siguiente, deja el pago registrado y —si se pide—
--    crea el gasto correspondiente.
--
--    No se puede pagar más de lo que se debe: el `least` recorta y avisa en
--    el resultado. Sin eso, un dedo de más dejaría un saldo negativo, que es
--    un estado que no existe en la vida real.
-- ------------------------------------------------------------
create or replace function public.registrar_pago_deuda(
  p_deuda       uuid,
  p_monto       numeric,
  p_fecha       date default null,
  p_crear_gasto boolean default true,
  p_metodo      text default 'efectivo',
  p_nota        text default ''
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_deuda      public.deudas;
  v_fecha      date;
  v_aplicado   numeric;
  v_movimiento uuid;
  v_pago       uuid;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  select * into v_deuda from public.deudas where id = p_deuda;
  if v_deuda.id is null then
    raise exception 'Esa deuda no existe.' using errcode = 'P0002';
  end if;
  if not public.es_admin(v_deuda.empresa_id) then
    raise exception 'Solo el propietario o un administrador puede registrar pagos.' using errcode = '42501';
  end if;
  if coalesce(p_monto, 0) <= 0 then
    raise exception 'El pago tiene que ser mayor que cero.' using errcode = '22023';
  end if;
  if v_deuda.saldo <= 0 then
    raise exception 'Esa deuda ya está saldada.' using errcode = '22023';
  end if;

  v_fecha := coalesce(p_fecha, public.hoy_empresa(v_deuda.empresa_id));

  -- Nunca más de lo que falta.
  v_aplicado := least(p_monto, v_deuda.saldo);

  -- El gasto primero: si falla, no queremos haber bajado el saldo.
  if p_crear_gasto then
    insert into public.movimientos (
      empresa_id, tipo, fecha, descripcion, categoria,
      subtotal, descuento, monto, costo_total, metodo_pago, creado_por
    ) values (
      v_deuda.empresa_id, 'gasto', v_fecha,
      'Pago ' || v_deuda.nombre, 'Deudas',
      v_aplicado, 0, v_aplicado, 0, coalesce(p_metodo, 'efectivo'), auth.uid()
    )
    returning id into v_movimiento;
  end if;

  insert into public.pagos_deuda (deuda_id, empresa_id, monto, fecha, movimiento_id, nota, creado_por)
  values (p_deuda, v_deuda.empresa_id, v_aplicado, v_fecha, v_movimiento,
          coalesce(left(p_nota, 300), ''), auth.uid())
  returning id into v_pago;

  update public.deudas
  set saldo = saldo - v_aplicado,
      cuotas_pagadas = case
        -- Solo cuenta como cuota si hay cuotas y todavía faltan.
        when cuotas_totales is not null and cuotas_pagadas < cuotas_totales
          then cuotas_pagadas + 1
        else cuotas_pagadas
      end,
      vence_el = case
        -- El próximo vencimiento se corre un mes. Si con esto queda saldada,
        -- se limpia: una deuda pagada no vence nunca más.
        when saldo - v_aplicado <= 0 then null
        when vence_el is not null then vence_el + interval '1 month'
        else null
      end,
      updated_at = now()
  where id = p_deuda;

  return jsonb_build_object(
    'pago_id', v_pago,
    'aplicado', v_aplicado,
    -- Si intentó pagar de más, la pantalla lo puede avisar.
    'sobrante', greatest(p_monto - v_aplicado, 0),
    'saldo', v_deuda.saldo - v_aplicado,
    'saldada', (v_deuda.saldo - v_aplicado) <= 0,
    'movimiento_id', v_movimiento
  );
end $fn$;

-- ------------------------------------------------------------
-- 6. EDITAR Y DAR DE BAJA
--
--    El saldo NO se puede editar por acá: para eso están los pagos. Si se
--    pudiera, el historial de pagos dejaría de explicar el saldo y no habría
--    forma de saber cuál de los dos miente.
-- ------------------------------------------------------------
create or replace function public.editar_deuda(
  p_deuda      uuid,
  p_nombre     text default null,
  p_acreedor   text default null,
  p_monto_cuota numeric default null,
  p_vence_el   date default null,
  p_notas      text default null
)
returns void language plpgsql security definer set search_path = public as $fn$
declare v_empresa uuid;
begin
  select empresa_id into v_empresa from public.deudas where id = p_deuda;
  if v_empresa is null then
    raise exception 'Esa deuda no existe.' using errcode = 'P0002';
  end if;
  if not public.es_admin(v_empresa) then
    raise exception 'Solo el propietario o un administrador puede editar deudas.' using errcode = '42501';
  end if;

  update public.deudas
  set nombre      = coalesce(nullif(trim(p_nombre), ''), nombre),
      acreedor    = coalesce(p_acreedor, acreedor),
      monto_cuota = coalesce(p_monto_cuota, monto_cuota),
      vence_el    = coalesce(p_vence_el, vence_el),
      notas       = coalesce(left(p_notas, 500), notas),
      updated_at  = now()
  where id = p_deuda;
end $fn$;

create or replace function public.archivar_deuda(p_deuda uuid, p_activa boolean default false)
returns void language plpgsql security definer set search_path = public as $fn$
declare v_empresa uuid;
begin
  select empresa_id into v_empresa from public.deudas where id = p_deuda;
  if v_empresa is null then
    raise exception 'Esa deuda no existe.' using errcode = 'P0002';
  end if;
  if not public.es_admin(v_empresa) then
    raise exception 'Solo el propietario o un administrador puede archivar deudas.' using errcode = '42501';
  end if;

  update public.deudas set activa = coalesce(p_activa, false), updated_at = now() where id = p_deuda;
end $fn$;

-- ------------------------------------------------------------
-- 7. LISTAR · una sola fila jsonb, como todo desde la 006
-- ------------------------------------------------------------
create or replace function public.listar_deudas(p_empresa uuid, p_incluir_saldadas boolean default false)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_res jsonb;
  v_hoy date;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  -- Cuánto debe el negocio es del mismo orden que los costos: no sale del
  -- servidor para un vendedor.
  if not public.es_admin(p_empresa) then
    raise exception 'No tenés permiso para ver las deudas del negocio.' using errcode = '42501';
  end if;

  v_hoy := public.hoy_empresa(p_empresa);

  select coalesce(jsonb_agg(x order by x->>'orden'), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'id', d.id,
      'tipo', d.tipo,
      'nombre', d.nombre,
      'acreedor', d.acreedor,
      'monto_original', d.monto_original,
      'saldo', d.saldo,
      'pagado', d.monto_original - d.saldo,
      'avance', case when d.monto_original > 0
                     then round(((d.monto_original - d.saldo) / d.monto_original) * 100, 1)
                     else 0 end,
      'cuotas_totales', d.cuotas_totales,
      'cuotas_pagadas', d.cuotas_pagadas,
      'monto_cuota', d.monto_cuota,
      'vence_el', d.vence_el,
      -- Días que faltan. Negativo = ya venció, y eso es lo primero que hay
      -- que ver al abrir la pantalla.
      'dias_para_vencer', case when d.vence_el is null then null else (d.vence_el - v_hoy) end,
      'vencida', d.vence_el is not null and d.vence_el < v_hoy and d.saldo > 0,
      'saldada', d.saldo <= 0,
      'activa', d.activa,
      'notas', d.notas,
      -- Orden de la lista: primero lo vencido, después lo que vence antes,
      -- y lo saldado al final.
      'orden', case
        when d.saldo <= 0 then '3'
        when d.vence_el is null then '2'
        else '1' || to_char(d.vence_el, 'YYYYMMDD')
      end
    ) as x
    from public.deudas d
    where d.empresa_id = p_empresa
      and (p_incluir_saldadas or (d.activa and d.saldo > 0))
  ) s;

  return v_res;
end $fn$;

-- ------------------------------------------------------------
-- 8. RESUMEN · el número que va en el panel
-- ------------------------------------------------------------
create or replace function public.resumen_deudas(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_hoy date;
  v_res jsonb;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_admin(p_empresa) then
    raise exception 'No tenés permiso para ver las deudas del negocio.' using errcode = '42501';
  end if;

  v_hoy := public.hoy_empresa(p_empresa);

  select jsonb_build_object(
    'total_debido', coalesce(sum(saldo), 0),
    'cuantas', count(*),
    'vencidas', count(*) filter (where vence_el is not null and vence_el < v_hoy),
    'monto_vencido', coalesce(sum(saldo) filter (where vence_el is not null and vence_el < v_hoy), 0),
    -- Lo que vence dentro de los próximos siete días: es el aviso útil.
    'vence_pronto', count(*) filter (where vence_el between v_hoy and v_hoy + 7),
    'monto_pronto', coalesce(sum(coalesce(monto_cuota, saldo))
                     filter (where vence_el between v_hoy and v_hoy + 7), 0),
    'proximo_vencimiento', min(vence_el) filter (where vence_el >= v_hoy)
  ) into v_res
  from public.deudas
  where empresa_id = p_empresa and activa and saldo > 0;

  return v_res;
end $fn$;

-- ------------------------------------------------------------
-- 9. HISTORIAL DE PAGOS DE UNA DEUDA
-- ------------------------------------------------------------
create or replace function public.pagos_de_deuda(p_deuda uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_empresa uuid;
  v_res     jsonb;
begin
  select empresa_id into v_empresa from public.deudas where id = p_deuda;
  if v_empresa is null or not public.es_admin(v_empresa) then
    raise exception 'No tenés permiso para ver esta deuda.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', p.id, 'monto', p.monto, 'fecha', p.fecha,
    'movimiento_id', p.movimiento_id, 'nota', p.nota, 'created_at', p.created_at
  ) order by p.fecha desc, p.created_at desc), '[]'::jsonb) into v_res
  from public.pagos_deuda p where p.deuda_id = p_deuda;

  return v_res;
end $fn$;

revoke all on function public.crear_deuda(uuid, text, text, text, numeric, numeric, integer, numeric, date, text) from public, anon;
revoke all on function public.registrar_pago_deuda(uuid, numeric, date, boolean, text, text) from public, anon;
revoke all on function public.editar_deuda(uuid, text, text, numeric, date, text) from public, anon;
revoke all on function public.archivar_deuda(uuid, boolean)          from public, anon;
revoke all on function public.listar_deudas(uuid, boolean)           from public, anon;
revoke all on function public.resumen_deudas(uuid)                   from public, anon;
revoke all on function public.pagos_de_deuda(uuid)                   from public, anon;

grant execute on function public.crear_deuda(uuid, text, text, text, numeric, numeric, integer, numeric, date, text) to authenticated;
grant execute on function public.registrar_pago_deuda(uuid, numeric, date, boolean, text, text) to authenticated;
grant execute on function public.editar_deuda(uuid, text, text, numeric, date, text) to authenticated;
grant execute on function public.archivar_deuda(uuid, boolean)       to authenticated;
grant execute on function public.listar_deudas(uuid, boolean)        to authenticated;
grant execute on function public.resumen_deudas(uuid)                to authenticated;
grant execute on function public.pagos_de_deuda(uuid)                to authenticated;


-- ############################################################
-- ##  016_panel_admin.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 016 · Tipo de cuenta y panel del dueño del sistema
--
-- Dos cosas que van juntas porque una no sirve sin la otra:
--
--   1. TIPO DE CUENTA. Orden pasa a atender dos públicos: alguien que lleva
--      sus finanzas personales (deudas, sueldo, gastos) y un comerciante
--      (todo lo anterior más ventas, productos y vendedores). No son dos
--      sistemas: el personal es el comercial MENOS ventas y productos.
--      De este campo cuelgan el largo de la prueba, los planes que se le
--      muestran y las pantallas que ve.
--
--   2. EL PANEL DEL DUEÑO DEL SISTEMA. Mientras el cobro sea por
--      transferencia y WhatsApp, alguien tiene que poder activar la cuenta
--      a mano después de recibir el pago. Sin esto no se le puede cobrar a
--      nadie.
--
-- LA REGLA QUE MANDA EN TODO ESTE ARCHIVO
--
-- El panel ve CUENTAS, no PLATA.
--
-- Para activarle el plan a alguien hace falta saber su nombre, su correo,
-- qué plan tiene y cuándo vence. NO hace falta saber cuánto vendió, qué
-- compró ni a quién le debe. Por eso ninguna función de acá devuelve un
-- monto, una descripción, un producto ni una deuda. Ni una.
--
-- Sí devuelven señales de USO —cuántos movimientos, cuándo fue el último,
-- cuántas capturas de IA consumió—, porque sin eso es imposible saber si
-- una cuenta está viva o si alguien está consumiendo de más. Un conteo y
-- una fecha no dicen nada del negocio de nadie.
--
-- Esto no es cosmética: es lo que permite prometerle a un comerciante que
-- sus números no los mira nadie, y que sea verdad.
--
-- LO QUE ESTA MIGRACIÓN NO PUEDE EVITAR
--
-- Quien administra la base de datos siempre puede leerla. Eso no lo cambia
-- ninguna función. Lo que sí se logra acá es que el panel no tenga forma de
-- mostrarlo, ni por accidente ni por comodidad.
--
-- Idempotente. No toca datos existentes.
-- ============================================================

-- ------------------------------------------------------------
-- 1. TIPO DE CUENTA
--
--    Las empresas que ya existen son todas comercios: nacieron cuando
--    Orden era solo para comerciantes. Por eso el default y el relleno
--    son 'emprendedor'.
-- ------------------------------------------------------------
alter table public.empresas
  add column if not exists tipo_cuenta text not null default 'emprendedor';

do $$ begin
  alter table public.empresas
    add constraint empresas_tipo_cuenta_check
    check (tipo_cuenta in ('personal', 'emprendedor'));
exception when duplicate_object then null; end $$;

comment on column public.empresas.tipo_cuenta is
  'personal = finanzas propias (sin ventas ni productos). emprendedor = negocio completo.';

-- ------------------------------------------------------------
-- 2. LARGO DE LA PRUEBA, POR TIPO
--
--    Distintos a propósito. Una persona que anota sus gastos sabe en pocos
--    días si le sirve. Un comerciante necesita ver un pedazo de mes suyo
--    —una quincena con su cobro, sus cuotas y sus días flojos— antes de
--    decidir si vale 190.000 al mes.
--
--    Y hay algo más de fondo: Orden se apoya en el hábito (la racha, el
--    cierre del día). El hábito no se forma en una semana. Cortar la
--    prueba antes de que se forme es apagar el propio motor.
-- ------------------------------------------------------------
create or replace function public.dias_de_prueba(p_tipo text)
returns integer language sql immutable set search_path = public as $fn$
  select case coalesce(p_tipo, 'emprendedor')
    when 'personal' then 14
    else 20
  end;
$fn$;

grant execute on function public.dias_de_prueba(text) to anon, authenticated;

-- ------------------------------------------------------------
-- 3. QUIÉN ADMINISTRA EL SISTEMA
--
--    Una tabla y no una columna en `miembros` porque no es un rol dentro
--    de una empresa: es un rol por ENCIMA de todas. Mezclarlo con los roles
--    de empresa haría que un error en una consulta de permisos de negocio
--    pudiera, en el peor caso, dar permisos de sistema.
--
--    Nadie se puede agregar solo. La tabla no tiene política de INSERT para
--    usuarios: se carga desde el editor SQL de Supabase o con service_role.
--    Un panel que se pudiera auto-otorgar sería una puerta abierta.
-- ------------------------------------------------------------
create table if not exists public.superadmins (
  usuario_id uuid primary key references auth.users (id) on delete cascade,
  nota       text not null default '',
  created_at timestamptz not null default now()
);

alter table public.superadmins enable row level security;

-- Solo se ve a sí mismo. Sirve para que la interfaz sepa si mostrar el
-- acceso al panel, sin revelar quiénes más lo son.
drop policy if exists superadmins_select on public.superadmins;
create policy superadmins_select on public.superadmins
  for select to authenticated
  using (usuario_id = auth.uid());

-- Sin políticas de insert, update ni delete. Y además, revocado a nivel de
-- privilegio: Supabase le otorga por defecto todos los permisos de tabla a
-- `authenticated` sobre lo nuevo que aparece en `public`, así que confiar
-- solo en "no hay policy" sería confiar en una configuración de la nube que
-- no controlamos. Dos cerrojos, no uno.
revoke all on public.superadmins from anon, authenticated;
grant select on public.superadmins to authenticated;

create or replace function public.es_superadmin()
returns boolean language sql stable security definer set search_path = public as $fn$
  select exists (
    select 1 from public.superadmins s where s.usuario_id = auth.uid()
  );
$fn$;

-- Se revoca de PUBLIC, no solo de anon. Es la misma trampa de la migración
-- 012: PostgreSQL le da EXECUTE a PUBLIC sobre toda función nueva, y `anon`
-- hereda de PUBLIC. Revocarle solo a anon deja la puerta igual de abierta.
-- Acá el daño sería chico —para un anónimo siempre devuelve falso— pero la
-- regla no admite excepciones «inofensivas»: la próxima no lo sería.
revoke all on function public.es_superadmin() from public, anon;
grant execute on function public.es_superadmin() to authenticated;

-- ------------------------------------------------------------
-- 4. REGISTRO DE LO QUE HACE EL PANEL
--
--    Todo lo que el panel modifica queda anotado, con quién, cuándo y qué
--    había antes.
--
--    No es burocracia. El día que alguien diga «me desactivaste la cuenta
--    sin avisar» o «yo pagué y no me activaste», la única forma de saber
--    quién tiene razón es esto. Y como el panel puede cambiar el plan de
--    cualquiera, sin registro no habría forma de auditar un error propio.
-- ------------------------------------------------------------
create table if not exists public.registro_admin (
  id         uuid primary key default gen_random_uuid(),
  actor_id   uuid references auth.users (id) on delete set null,
  empresa_id uuid references public.empresas (id) on delete set null,
  accion     text not null,
  detalle    jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index if not exists registro_admin_empresa_idx
  on public.registro_admin (empresa_id, created_at desc);
create index if not exists registro_admin_fecha_idx
  on public.registro_admin (created_at desc);

alter table public.registro_admin enable row level security;

drop policy if exists registro_admin_select on public.registro_admin;
create policy registro_admin_select on public.registro_admin
  for select to authenticated
  using (public.es_superadmin());

-- Se escribe solo desde las funciones de abajo, que son security definer.
-- Nadie puede insertar a mano: un registro de auditoría en el que cualquiera
-- puede escribir no sirve para auditar nada.
revoke all on public.registro_admin from anon, authenticated;
grant select on public.registro_admin to authenticated;

-- ------------------------------------------------------------
-- 5. LISTAR CUENTAS
--
--    El corazón del panel. Devuelve una fila por empresa con lo necesario
--    para administrarla y NADA de lo que pasa adentro.
--
--    `dias_restantes` es lo que convierte esta lista en una herramienta de
--    trabajo: ordenada por ese número, arriba quedan los que están por
--    vencer, que son a quienes hay que escribirles hoy.
-- ------------------------------------------------------------
create or replace function public.listar_cuentas(
  p_busqueda text default null,
  p_estado   text default null,
  p_limite   integer default 200
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_res jsonb;
  v_periodo text;
begin
  if not public.es_superadmin() then
    raise exception 'Este panel es solo para la administración de Orden.' using errcode = '42501';
  end if;

  v_periodo := to_char(now(), 'YYYY-MM');

  select coalesce(jsonb_agg(x order by x->>'orden'), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'empresa_id',   e.id,
      'nombre',       e.nombre,
      'tipo_cuenta',  e.tipo_cuenta,
      'moneda',       e.moneda,
      'creada',       e.created_at,

      -- Con quién hablar. Es dato de contacto, no dato del negocio.
      'propietario',  coalesce(prop.nombre, 'Sin nombre'),
      'correo',       coalesce(u.email, ''),

      'plan',         public.plan_efectivo_calculado(e.id),
      'plan_guardado', s.plan,
      'estado',       s.estado,
      'periodo_fin',  s.periodo_fin,
      'prueba_fin',   s.prueba_fin,

      -- Negativo = ya venció. Es el número por el que se ordena.
      'dias_restantes', case
        when s.periodo_fin is null then null
        else floor(extract(epoch from (s.periodo_fin - now())) / 86400)::integer
      end,

      'miembros', (select count(*) from public.miembros m where m.empresa_id = e.id),

      -- Señales de vida. Un conteo y una fecha: cuántas veces se usó el
      -- sistema y cuándo fue la última. Sin montos: no se puede deducir
      -- de acá cuánto factura nadie.
      'movimientos', (select count(*) from public.movimientos mv where mv.empresa_id = e.id),
      'ultima_actividad', (select max(mv.created_at) from public.movimientos mv where mv.empresa_id = e.id),

      -- Cuánta IA consumió este mes. Lo que permite ver al raro antes de
      -- que la factura de OpenAI lo muestre.
      'ia_usada', coalesce((
        select ui.usados from public.uso_ia ui
        where ui.empresa_id = e.id and ui.periodo = v_periodo
      ), 0),
      'ia_tope', (public.limites_plan(public.plan_efectivo_calculado(e.id))->>'capturas_mes')::integer,

      -- Ordena: primero lo vencido y lo que vence pronto, después el resto
      -- por fecha de creación. Se arma como texto con relleno de ceros
      -- porque jsonb_agg ordena por el valor de la clave, no numéricamente.
      'orden', lpad(
        greatest(0, coalesce(
          floor(extract(epoch from (s.periodo_fin - now())) / 86400)::integer + 1000,
          9999))::text, 5, '0')
    ) as x
    from public.empresas e
    join public.suscripciones s on s.empresa_id = e.id
    left join public.miembros prop
      on prop.empresa_id = e.id and prop.rol = 'propietario'
    left join auth.users u on u.id = prop.user_id
    where (
        p_busqueda is null
        or trim(p_busqueda) = ''
        or e.nombre ilike '%' || trim(p_busqueda) || '%'
        or coalesce(u.email, '') ilike '%' || trim(p_busqueda) || '%'
      )
      and (p_estado is null or trim(p_estado) = '' or s.estado = p_estado)
    limit greatest(1, least(coalesce(p_limite, 200), 500))
  ) t;

  return v_res;
end $fn$;

-- ------------------------------------------------------------
-- 6. RESUMEN DEL PANEL
--
--    Los cuatro números que hay que ver al abrir: cuántas cuentas hay,
--    cuántas están probando, cuántas pagan y —el importante— cuántas
--    vencen esta semana, que es la lista de a quiénes escribir.
-- ------------------------------------------------------------
create or replace function public.resumen_panel()
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_res jsonb;
begin
  if not public.es_superadmin() then
    raise exception 'Este panel es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'cuentas',      count(*),
    'personales',   count(*) filter (where e.tipo_cuenta = 'personal'),
    'comercios',    count(*) filter (where e.tipo_cuenta = 'emprendedor'),
    'en_prueba',    count(*) filter (where s.estado = 'prueba' and s.periodo_fin > now()),
    'pagando',      count(*) filter (where s.estado = 'activa' and s.plan <> 'gratis'),
    'vencidas',     count(*) filter (where s.periodo_fin is not null and s.periodo_fin <= now()),
    'vencen_semana', count(*) filter (
      where s.periodo_fin between now() and now() + interval '7 days'
    ),
    -- Cuánta IA se consumió este mes entre todos. Es el número que hay que
    -- mirar para saber si la factura de OpenAI va a sorprender.
    'ia_mes', coalesce((
      select sum(ui.usados) from public.uso_ia ui
      where ui.periodo = to_char(now(), 'YYYY-MM')
    ), 0)
  ) into v_res
  from public.empresas e
  join public.suscripciones s on s.empresa_id = e.id;

  return v_res;
end $fn$;

-- ------------------------------------------------------------
-- 7. CAMBIAR EL PLAN DE UNA CUENTA
--
--    Esto es lo que se aprieta cuando entra una transferencia.
--
--    Está separado de `aplicar_suscripcion()` —la que usa el webhook de
--    Stripe— aunque hagan algo parecido. El motivo: aquella confía en una
--    firma criptográfica, esta confía en una persona. Mezclarlas obligaría
--    a que la de la firma acepte también llamadas de un humano, y ahí se
--    pierde la garantía de que el plan solo cambia con un pago verificado.
-- ------------------------------------------------------------
create or replace function public.cambiar_plan_cuenta(
  p_empresa uuid,
  p_plan    text,
  p_meses   integer default 1,
  p_nota    text default ''
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_antes  public.suscripciones;
  v_fin    timestamptz;
  v_estado text;
begin
  if not public.es_superadmin() then
    raise exception 'Este panel es solo para la administración de Orden.' using errcode = '42501';
  end if;

  if p_plan not in ('gratis', 'pro', 'negocio') then
    raise exception 'Plan desconocido: %', p_plan using errcode = '22023';
  end if;

  select * into v_antes from public.suscripciones where empresa_id = p_empresa;
  if v_antes.empresa_id is null then
    raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
  end if;

  if p_plan = 'gratis' then
    -- Bajar a gratis es cortar el servicio: vence ya.
    v_estado := 'vencida';
    v_fin := now();
  else
    v_estado := 'activa';
    -- Si todavía le queda tiempo pago, se le suma; si no, arranca hoy.
    -- Sin esto, activarle el mes a alguien que pagó antes de tiempo le
    -- comería los días que ya tenía.
    v_fin := greatest(coalesce(v_antes.periodo_fin, now()), now())
             + make_interval(months => greatest(1, coalesce(p_meses, 1)));
  end if;

  update public.suscripciones
  set plan = p_plan,
      estado = v_estado,
      periodo_inicio = case when p_plan = 'gratis' then periodo_inicio else now() end,
      periodo_fin = v_fin,
      proveedor_pago = case when p_plan = 'gratis' then proveedor_pago else 'transferencia' end,
      updated_at = now()
  where empresa_id = p_empresa;

  -- El espejo en `empresas.plan` solo acepta 'gratis' o 'pro'; 'negocio'
  -- se guarda como 'pro' porque para esa columna lo único que importa es
  -- si paga o no. La autoridad es `suscripciones`.
  perform set_config('orden.suscripcion_confiable', '1', true);
  update public.empresas
  set plan = case when p_plan = 'gratis' then 'gratis' else 'pro' end
  where id = p_empresa;
  perform set_config('orden.suscripcion_confiable', '0', true);

  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (auth.uid(), p_empresa, 'cambiar_plan', jsonb_build_object(
    'plan_antes', v_antes.plan, 'plan_despues', p_plan,
    'estado_antes', v_antes.estado, 'estado_despues', v_estado,
    'vence_antes', v_antes.periodo_fin, 'vence_despues', v_fin,
    'meses', greatest(1, coalesce(p_meses, 1)),
    'nota', left(coalesce(p_nota, ''), 300)
  ));

  return jsonb_build_object('plan', p_plan, 'estado', v_estado, 'periodo_fin', v_fin);
end $fn$;

-- ------------------------------------------------------------
-- 8. ESTIRAR LA PRUEBA
--
--    Para el caso real: alguien está por vencer, dice «mañana te
--    transfiero», y no se le va a cortar el servicio por 24 horas.
--
--    Solo estira, nunca acorta. Recortarle la prueba a alguien que ya la
--    está usando es de las cosas que no deberían poder hacerse de un clic.
-- ------------------------------------------------------------
create or replace function public.extender_prueba(
  p_empresa uuid,
  p_dias    integer default 7,
  p_nota    text default ''
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_antes public.suscripciones;
  v_fin   timestamptz;
  v_dias  integer;
begin
  if not public.es_superadmin() then
    raise exception 'Este panel es solo para la administración de Orden.' using errcode = '42501';
  end if;

  v_dias := greatest(1, least(coalesce(p_dias, 7), 90));

  select * into v_antes from public.suscripciones where empresa_id = p_empresa;
  if v_antes.empresa_id is null then
    raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
  end if;

  -- Desde hoy si ya venció, desde el vencimiento si todavía corre.
  v_fin := greatest(coalesce(v_antes.periodo_fin, now()), now())
           + make_interval(days => v_dias);

  update public.suscripciones
  set estado = 'prueba', plan = case when plan = 'gratis' then 'pro' else plan end,
      periodo_fin = v_fin, prueba_fin = v_fin, updated_at = now()
  where empresa_id = p_empresa;

  perform set_config('orden.suscripcion_confiable', '1', true);
  update public.empresas set plan = 'pro' where id = p_empresa;
  perform set_config('orden.suscripcion_confiable', '0', true);

  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (auth.uid(), p_empresa, 'extender_prueba', jsonb_build_object(
    'dias', v_dias, 'vence_antes', v_antes.periodo_fin, 'vence_despues', v_fin,
    'nota', left(coalesce(p_nota, ''), 300)
  ));

  return jsonb_build_object('periodo_fin', v_fin, 'dias', v_dias);
end $fn$;

-- ------------------------------------------------------------
-- 9. CAMBIAR EL TIPO DE CUENTA
--
--    Para el que se registró como personal y abrió un negocio. Al revés
--    también, aunque casi no va a pasar.
--
--    Importante: NO borra nada. Una cuenta que pasa de emprendedor a
--    personal deja de ver ventas y productos, pero los datos quedan donde
--    están. Si vuelve a comercio, los encuentra intactos.
-- ------------------------------------------------------------
create or replace function public.cambiar_tipo_cuenta(
  p_empresa uuid,
  p_tipo    text
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_antes text;
begin
  if not public.es_superadmin() then
    raise exception 'Este panel es solo para la administración de Orden.' using errcode = '42501';
  end if;

  if p_tipo not in ('personal', 'emprendedor') then
    raise exception 'Tipo de cuenta desconocido: %', p_tipo using errcode = '22023';
  end if;

  select tipo_cuenta into v_antes from public.empresas where id = p_empresa;
  if v_antes is null then
    raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
  end if;

  update public.empresas set tipo_cuenta = p_tipo where id = p_empresa;

  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (auth.uid(), p_empresa, 'cambiar_tipo', jsonb_build_object(
    'antes', v_antes, 'despues', p_tipo
  ));

  return jsonb_build_object('tipo_cuenta', p_tipo);
end $fn$;

-- ------------------------------------------------------------
-- 10. HISTORIAL DE UNA CUENTA
--
--     Todo lo que se le hizo a una cuenta desde el panel. Es lo que se
--     mira cuando alguien reclama.
-- ------------------------------------------------------------
create or replace function public.historial_cuenta(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_res jsonb;
begin
  if not public.es_superadmin() then
    raise exception 'Este panel es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'accion', r.accion,
    'detalle', r.detalle,
    'cuando', r.created_at,
    'quien', coalesce(u.email, 'sistema')
  ) order by r.created_at desc), '[]'::jsonb) into v_res
  from public.registro_admin r
  left join auth.users u on u.id = r.actor_id
  where r.empresa_id = p_empresa;

  return v_res;
end $fn$;

-- ------------------------------------------------------------
-- 11. CREAR EMPRESA · ahora con tipo de cuenta y prueba según el tipo
--
--     Redefinición completa de la versión de la 009. Lo único que cambia:
--     recibe el tipo de cuenta y el largo de la prueba sale de él.
-- ------------------------------------------------------------
create or replace function public.crear_empresa(
  p_nombre text,
  p_moneda text default 'PYG',
  p_nombre_usuario text default null,
  p_zona text default 'America/Asuncion',
  p_tipo_cuenta text default 'emprendedor'
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_id uuid;
  v_codigo text;
  v_intentos int := 0;
  v_fin timestamptz;
  v_tipo text;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  if char_length(trim(coalesce(p_nombre, ''))) < 2 then
    raise exception 'El nombre del negocio es muy corto.' using errcode = '22023';
  end if;

  v_tipo := case when p_tipo_cuenta = 'personal' then 'personal' else 'emprendedor' end;

  loop
    v_codigo := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
    exit when not exists (select 1 from public.empresa_accesos where codigo = v_codigo);
    v_intentos := v_intentos + 1;
    if v_intentos > 12 then
      raise exception 'No se pudo generar un código de acceso.' using errcode = '55000';
    end if;
  end loop;

  insert into public.empresas (nombre, moneda, creada_por, zona_horaria, tipo_cuenta)
  values (trim(p_nombre), coalesce(p_moneda, 'PYG'), auth.uid(),
          coalesce(nullif(trim(p_zona), ''), 'America/Asuncion'), v_tipo)
  returning id into v_id;

  insert into public.miembros (empresa_id, user_id, nombre, rol)
  values (v_id, auth.uid(), coalesce(nullif(trim(p_nombre_usuario), ''), 'Propietario'), 'propietario');

  insert into public.empresa_accesos (empresa_id, codigo)
  values (v_id, v_codigo);

  -- La prueba se escribe acá directamente y no llamando a iniciar_prueba()
  -- porque esa función es de service_role: quien crea la empresa es un
  -- usuario común, y no queremos otorgarle ese permiso para esto.
  v_fin := now() + make_interval(days => public.dias_de_prueba(v_tipo));
  insert into public.suscripciones (empresa_id, plan, estado, periodo_inicio, periodo_fin, prueba_fin)
  values (v_id, 'pro', 'prueba', now(), v_fin, v_fin);

  perform set_config('orden.suscripcion_confiable', '1', true);
  update public.empresas set plan = 'pro' where id = v_id;
  perform set_config('orden.suscripcion_confiable', '0', true);

  return v_id;
end $fn$;

-- La firma de 4 argumentos queda muerta: si no se borra, PostgREST ve dos
-- funciones con el mismo nombre y no sabe cuál llamar.
drop function if exists public.crear_empresa(text, text, text, text);

-- ------------------------------------------------------------
-- 12. PERMISOS
--
--     Todo revocado de PUBLIC, no solo de anon: anon hereda de PUBLIC, y
--     revocarle solo a anon deja la puerta abierta. Ver migración 012.
-- ------------------------------------------------------------
revoke all on function public.listar_cuentas(text, text, integer)      from public, anon;
revoke all on function public.resumen_panel()                          from public, anon;
revoke all on function public.cambiar_plan_cuenta(uuid, text, integer, text) from public, anon;
revoke all on function public.extender_prueba(uuid, integer, text)     from public, anon;
revoke all on function public.cambiar_tipo_cuenta(uuid, text)          from public, anon;
revoke all on function public.historial_cuenta(uuid)                   from public, anon;
revoke all on function public.crear_empresa(text, text, text, text, text) from public, anon;

grant execute on function public.listar_cuentas(text, text, integer)      to authenticated;
grant execute on function public.resumen_panel()                          to authenticated;
grant execute on function public.cambiar_plan_cuenta(uuid, text, integer, text) to authenticated;
grant execute on function public.extender_prueba(uuid, integer, text)     to authenticated;
grant execute on function public.cambiar_tipo_cuenta(uuid, text)          to authenticated;
grant execute on function public.historial_cuenta(uuid)                   to authenticated;
grant execute on function public.crear_empresa(text, text, text, text, text) to authenticated;

-- El grant es a `authenticated` y no a un rol especial porque el permiso de
-- verdad lo pone `es_superadmin()` adentro de cada función. Un usuario
-- común que llame a cualquiera de estas recibe un 42501, no una fila.


-- ############################################################
-- ##  017_precios_por_tipo.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 017 · Precios por tipo de cuenta
--
-- POR QUÉ EL PRECIO NO PUEDE DEPENDER SOLO DEL PLAN
--
-- Una cuenta personal y un comercio pueden estar los dos en plan `pro` —los
-- mismos topes, las mismas funciones— y aun así pagar distinto. No es una
-- inconsistencia: es que **no reciben el mismo valor**.
--
-- Al comerciante, Orden le dice cuánta plata ganó de verdad. Eso se paga
-- solo. A quien lleva sus finanzas personales le dice cuánto debe y cuándo
-- vence la cuota; le sirve, pero no le genera un guaraní. Cobrarle lo mismo
-- a los dos sería no haber entendido a ninguno.
--
-- Por eso el plan sigue decidiendo QUÉ SE PUEDE HACER (`limites_plan`), y el
-- par tipo_cuenta + plan decide CUÁNTO SE PAGA. Son dos preguntas distintas
-- y ahora tienen dos respuestas distintas.
--
-- LOS PRECIOS QUE QUEDAN (Paraguay)
--
--   personal    · plan único            60.000/mes    ·  600.000/año
--   comercio    · Pro, hasta 3 vendedores  190.000/mes  · 1.900.000/año
--   comercio    · Premium, desde          250.000/mes  · 2.500.000/año
--
-- El anual son diez meses por doce. No se escribe «dos meses gratis» a mano
-- en ningún lado: `mesesDeRegalo()` lo calcula de estos números, así que si
-- mañana cambian, el cartel sigue diciendo la verdad o desaparece.
--
-- Premium es «desde»: el precio final depende de cuántos vendedores quiera,
-- a 60.000 cada uno por encima de los 3 que trae Pro. 250.000 es el primer
-- escalón (4 vendedores) y por eso es el número que se muestra.
--
-- Idempotente. Reemplaza los precios viejos (35.000 / 79.000), que eran de
-- cuando Orden tenía un solo público.
-- ============================================================

-- ------------------------------------------------------------
-- 1. LA COLUMNA
-- ------------------------------------------------------------
alter table public.precios
  add column if not exists tipo_cuenta text not null default 'emprendedor';

do $$ begin
  alter table public.precios
    add constraint precios_tipo_cuenta_check
    check (tipo_cuenta in ('personal', 'emprendedor'));
exception when duplicate_object then null; end $$;

-- La unicidad ahora incluye el tipo: el mismo plan y la misma moneda pueden
-- convivir con dos precios distintos, uno por público.
alter table public.precios drop constraint if exists precios_plan_moneda_periodo_key;

do $$ begin
  alter table public.precios
    add constraint precios_tipo_plan_moneda_periodo_key
    unique (tipo_cuenta, plan, moneda, periodo);
exception when duplicate_object then null; end $$;

-- ------------------------------------------------------------
-- 2. LOS PRECIOS
--
--    Se borran los viejos en vez de desactivarlos: un precio que ya no
--    existe no tiene por qué quedar dando vueltas donde alguien lo pueda
--    volver a activar por error.
-- ------------------------------------------------------------
delete from public.precios;

insert into public.precios (tipo_cuenta, plan, moneda, periodo, importe) values
  -- Cuenta personal. Un solo plan pago: no necesita nombre porque no compite
  -- con ningún otro. En la interfaz es «la suscripción», no «Pro», para que
  -- no choque con el Pro de comercios, que cuesta el triple.
  ('personal',    'pro',     'PYG', 'mensual',   60000),
  ('personal',    'pro',     'PYG', 'anual',    600000),
  ('personal',    'pro',     'USD', 'mensual',     7.99),
  ('personal',    'pro',     'USD', 'anual',      79.00),

  -- Comercio · Pro: hasta 3 vendedores.
  ('emprendedor', 'pro',     'PYG', 'mensual',  190000),
  ('emprendedor', 'pro',     'PYG', 'anual',   1900000),
  ('emprendedor', 'pro',     'USD', 'mensual',    24.99),
  ('emprendedor', 'pro',     'USD', 'anual',     249.00),

  -- Comercio · Premium: desde. El precio final se cotiza según cuántos
  -- vendedores, a 60.000 cada uno arriba de los 3 de Pro.
  ('emprendedor', 'negocio', 'PYG', 'mensual',  250000),
  ('emprendedor', 'negocio', 'PYG', 'anual',   2500000),
  ('emprendedor', 'negocio', 'USD', 'mensual',    32.99),
  ('emprendedor', 'negocio', 'USD', 'anual',     329.00);

-- ------------------------------------------------------------
-- 3. CUÁNTO CUESTA CADA VENDEDOR DE MÁS
--
--    Vive en la base y no en el código por el mismo motivo que los precios:
--    subirlo no puede requerir un despliegue. La usa la portada para
--    explicar de dónde sale el «desde», y sirve para cotizar sin improvisar
--    un número distinto en cada conversación de WhatsApp.
-- ------------------------------------------------------------
create or replace function public.precio_por_vendedor(p_moneda text default 'PYG')
returns numeric language sql immutable set search_path = public as $fn$
  select case upper(coalesce(p_moneda, 'PYG'))
    when 'PYG' then 60000::numeric
    when 'USD' then 7.99::numeric
    else 7.99::numeric
  end;
$fn$;

grant execute on function public.precio_por_vendedor(text) to anon, authenticated;

-- ------------------------------------------------------------
-- 4. LISTA DE PRECIOS · ahora filtra por público
--
--    `p_tipo` en null devuelve todo, que es lo que necesita la portada para
--    mostrar los dos lados. La pantalla de Plan, en cambio, pide solo el
--    tipo de la cuenta: a alguien que lleva sus finanzas personales no se le
--    ofrece el plan de un local con vendedores.
-- ------------------------------------------------------------
create or replace function public.lista_precios(
  p_moneda text default null,
  p_tipo   text default null
)
returns jsonb language sql stable security definer set search_path = public as $fn$
  select coalesce(jsonb_agg(jsonb_build_object(
    'tipo_cuenta', p.tipo_cuenta,
    'plan', p.plan, 'moneda', p.moneda, 'periodo', p.periodo,
    'importe', p.importe, 'referencia_externa', p.referencia_externa
  ) order by p.tipo_cuenta, p.plan, p.periodo), '[]'::jsonb)
  from public.precios p
  where p.activo
    and (p_moneda is null or p.moneda = p_moneda)
    and (p_tipo is null or p.tipo_cuenta = p_tipo);
$fn$;

-- La firma de un argumento queda muerta: si no se borra, PostgREST ve dos
-- funciones con el mismo nombre y no sabe cuál llamar.
drop function if exists public.lista_precios(text);

-- Los precios son públicos a propósito: alguien que todavía no tiene cuenta
-- tiene que poder ver cuánto cuesta antes de registrarse.
grant execute on function public.lista_precios(text, text) to anon, authenticated;


-- ############################################################
-- ##  018_solo_lectura.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 018 · Al vencer se deja de cargar, no de mirar
--
-- QUÉ CAMBIA
--
-- Hasta ahora, cuando se terminaba la prueba la cuenta caía al plan `gratis`
-- y ahí se quedaba: 20 capturas de IA al mes, pero **carga manual sin
-- límite**. Para un almacén chico eso alcanzaba de sobra. Era un sistema
-- financiero completo, gratis para siempre, y nadie tenía motivo para pagar.
--
-- Ahora `gratis` deja de significar «plan gratuito» y pasa a significar
-- **cuenta vencida**: se puede entrar, ver todo el historial y bajar el
-- Excel, pero no cargar nada nuevo.
--
-- POR QUÉ NO SE BLOQUEA LA CUENTA ENTERA
--
-- Porque los datos son de esa persona, no nuestros. Dejar a alguien afuera de
-- sus propios números es la clase de cosa que genera un mensaje furioso y
-- mala fama — y en un mercado donde los comerciantes se conocen entre ellos,
-- esa fama cuesta más que la suscripción que se estaría forzando.
--
-- Solo lectura tiene la misma presión que bloquear —para seguir trabajando
-- hay que pagar— sin quedarse con lo ajeno. Y el Excel pasa a ser el mejor
-- argumento de venta: «mirá todo lo que cargaste, seguí desde donde estás».
--
-- POR QUÉ CON TRIGGERS Y NO CON POLÍTICAS
--
-- Se escribe desde muchos lados: políticas RLS para gastos, `registrar_venta`
-- para ventas, `crear_deuda` y `registrar_pago_deuda` para deudas, `adjuntar`
-- para comprobantes, `marcar_cierre` para el cierre. Poner el control en cada
-- uno significa que el día que se agregue una ruta nueva y alguien se olvide,
-- se abre un agujero silencioso.
--
-- Un trigger por tabla lo agarra TODO, venga por donde venga, incluidas las
-- funciones `security definer` que saltean RLS. Una definición por tabla en
-- vez de una por camino.
--
-- Idempotente. No toca datos existentes.
-- ============================================================

-- ------------------------------------------------------------
-- 1. QUÉ DA CADA PLAN · ahora `gratis` es «vencida»
--
--    Dos cambios respecto de la 009:
--
--    · `excel` pasa a true. Es el corazón de todo esto: la persona tiene que
--      poder llevarse lo suyo cuando quiera, aunque no pague.
--    · aparece `escritura`, que es lo que los triggers de abajo consultan.
--
--    `capturas_mes` en 0 y no en 20: si igual no puede cargar el movimiento,
--    darle capturas de IA sería gastar créditos de OpenAI para producir un
--    borrador que después rebota.
-- ------------------------------------------------------------
create or replace function public.limites_plan(p_plan text)
returns jsonb language sql immutable set search_path = public as $fn$
  select case coalesce(p_plan, 'gratis')
    when 'negocio' then jsonb_build_object(
      'capturas_mes', 3000, 'miembros', 15,
      'adjuntos', true, 'excel', true, 'avisos', true, 'escritura', true)
    -- Tres personas: el dueño y un par de ayudantes. Una despensa chica no
    -- tiene por qué pagar el plan de una cadena, y si la apretamos termina
    -- compartiendo un solo login — que es peor para todos, porque perdemos
    -- el registro de quién cargó cada venta.
    when 'pro' then jsonb_build_object(
      'capturas_mes', 600, 'miembros', 3,
      'adjuntos', true, 'excel', true, 'avisos', true, 'escritura', true)
    else jsonb_build_object(
      -- CUENTA VENCIDA. Mira todo, se lleva todo, no carga nada.
      'capturas_mes', 0, 'miembros', 1,
      'adjuntos', false, 'excel', true, 'avisos', true, 'escritura', false)
  end;
$fn$;

grant execute on function public.limites_plan(text) to anon, authenticated;

-- ------------------------------------------------------------
-- 2. ¿ESTA EMPRESA PUEDE CARGAR?
--
--    Una sola pregunta, un solo lugar donde se responde.
-- ------------------------------------------------------------
create or replace function public.puede_cargar(p_empresa uuid)
returns boolean language sql stable security definer set search_path = public as $fn$
  select coalesce(
    (public.limites_plan(public.plan_efectivo_calculado(p_empresa))->>'escritura')::boolean,
    false);
$fn$;

revoke all on function public.puede_cargar(uuid) from public, anon;
grant execute on function public.puede_cargar(uuid) to authenticated;

-- ------------------------------------------------------------
-- 3. EL GUARDIÁN
--
--    Sobre el `auth.uid() is null`: una escritura sin sesión no es de un
--    cliente. Es el webhook de pagos, una tarea programada, una migración o
--    un arreglo con `service_role`. Esas no las puede frenar el estado de
--    cobro de nadie —si no, un pago no podría registrarse justamente cuando
--    la cuenta está vencida, que es cuando más falta hace— y además se
--    ahorra la consulta en las cargas masivas.
-- ------------------------------------------------------------
create or replace function public.exigir_cuenta_activa()
returns trigger language plpgsql security definer set search_path = public as $fn$
begin
  if auth.uid() is null then
    return new;
  end if;

  if not public.puede_cargar(new.empresa_id) then
    raise exception 'Se te terminó la prueba. Podés seguir viendo todo y bajando tu Excel, pero para cargar hay que activar el plan.'
      using errcode = '42501';
  end if;

  return new;
end $fn$;

-- Nadie la ejecuta a mano: la llama PostgreSQL al disparar el trigger, con
-- los permisos del dueño de la función. Que figure como ejecutable por
-- cualquiera no sirve para nada y ensucia la superficie. Misma trampa de la
-- migración 012: PUBLIC recibe EXECUTE sobre toda función nueva, y `anon`
-- hereda de PUBLIC.
revoke all on function public.exigir_cuenta_activa() from public, anon, authenticated;

-- ------------------------------------------------------------
-- 4. DÓNDE SE APLICA
--
--    Solo INSERT y UPDATE. El DELETE queda libre a propósito: vaciar el
--    negocio y borrar la cuenta tienen que funcionar siempre, incluso —sobre
--    todo— con la cuenta vencida. Nadie debería tener que pagar para poder
--    irse.
-- ------------------------------------------------------------
do $$
declare
  v_tabla text;
begin
  foreach v_tabla in array array[
    'movimientos', 'movimiento_items', 'productos',
    'deudas', 'pagos_deuda', 'adjuntos', 'cierres', 'retos'
  ] loop
    -- `if exists` porque este archivo se puede correr sobre una instalación
    -- que todavía no tenga alguna tabla (deudas llegó en la 015).
    if exists (
      select 1 from information_schema.tables
      where table_schema = 'public' and table_name = v_tabla
    ) then
      execute format('drop trigger if exists %I on public.%I',
                     'cuenta_activa_' || v_tabla, v_tabla);
      execute format(
        'create trigger %I before insert or update on public.%I '
        || 'for each row execute function public.exigir_cuenta_activa()',
        'cuenta_activa_' || v_tabla, v_tabla);
    end if;
  end loop;
end $$;

-- ------------------------------------------------------------
-- 5. EL ESTADO, PARA QUE LA PANTALLA LO EXPLIQUE
--
--    Sin esto la persona se encontraría con un error rojo al intentar
--    cargar, sin entender por qué. Con esto, la app le puede avisar ANTES —y
--    ofrecerle el botón de suscribirse— en vez de dejarla chocar contra una
--    pared.
-- ------------------------------------------------------------
create or replace function public.estado_cuenta(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_sus   public.suscripciones;
  v_plan  text;
  v_dias  integer;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select * into v_sus from public.suscripciones where empresa_id = p_empresa;
  v_plan := public.plan_efectivo_calculado(p_empresa);

  v_dias := case
    when v_sus.periodo_fin is null then null
    else floor(extract(epoch from (v_sus.periodo_fin - now())) / 86400)::integer
  end;

  return jsonb_build_object(
    'plan', v_plan,
    'estado', v_sus.estado,
    'en_prueba', v_sus.estado = 'prueba' and coalesce(v_sus.periodo_fin > now(), false),
    'vencida', not coalesce(
      (public.limites_plan(v_plan)->>'escritura')::boolean, false),
    'puede_cargar', coalesce(
      (public.limites_plan(v_plan)->>'escritura')::boolean, false),
    'dias_restantes', v_dias,
    'periodo_fin', v_sus.periodo_fin,
    -- A partir de acá la pantalla decide si avisar. Tres días es cuando deja
    -- de ser un dato y pasa a ser algo que hay que resolver.
    'avisar', v_dias is not null and v_dias <= 3,
    'tipo_cuenta', (select e.tipo_cuenta from public.empresas e where e.id = p_empresa)
  );
end $fn$;

revoke all on function public.estado_cuenta(uuid) from public, anon;
grant execute on function public.estado_cuenta(uuid) to authenticated;


-- ############################################################
-- ##  019_orden_es_un_negocio.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 019 · Orden lleva las finanzas de Orden
--
-- LA IDEA
--
-- El panel de administración mostraba cuentas ajenas y nada más. Pero quien
-- administra Orden **también tiene un negocio**: cobra suscripciones, paga
-- Supabase y OpenAI, y probablemente deba algo. Eso es exactamente lo que
-- Orden sabe hacer.
--
-- Así que no se construye un módulo de finanzas adentro del panel. Se
-- **enlaza**: quien administra tiene su propia empresa en Orden, como
-- cualquier cliente, y el panel le suma dos cosas que ningún cliente
-- necesita:
--
--   1. cuando activa el plan de alguien, el cobro se anota solo como
--      ingreso en SU empresa;
--   2. un resumen de cuánto entró por suscripciones.
--
-- Todo lo demás —deudas, gastos, cierre del día, Excel— ya existe y funciona.
-- Escribir un segundo sistema de finanzas adentro del primero habría sido
-- mantener dos veces la misma matemática.
--
-- EL EFECTO SECUNDARIO QUE VALE LA PENA
--
-- El dueño de Orden pasa a usar Orden todos los días para su propia plata.
-- Es la mejor prueba que puede tener un producto: si algo molesta, lo va a
-- sentir antes que ningún cliente.
--
-- Idempotente. No toca datos existentes.
-- ============================================================

-- ------------------------------------------------------------
-- 1. CUÁL ES LA EMPRESA DE ORDEN
--
--    Una sola fila. La restricción `unica` no es decorativa: sin ella, dos
--    filas harían que los cobros se anoten en una empresa distinta según el
--    orden en que salgan de la consulta, y eso es de los errores que se
--    descubren tarde y mal.
-- ------------------------------------------------------------
create table if not exists public.ajustes_orden (
  unica       boolean primary key default true check (unica),
  empresa_id  uuid references public.empresas (id) on delete set null,
  updated_at  timestamptz not null default now()
);

alter table public.ajustes_orden enable row level security;

-- Solo la administración la lee. Un cliente no tiene por qué saber que
-- existe una empresa que representa a Orden.
drop policy if exists ajustes_orden_select on public.ajustes_orden;
create policy ajustes_orden_select on public.ajustes_orden
  for select to authenticated
  using (public.es_superadmin());

revoke all on public.ajustes_orden from anon, authenticated;
grant select on public.ajustes_orden to authenticated;

create or replace function public.definir_empresa_orden(p_empresa uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
begin
  if not public.es_superadmin() then
    raise exception 'Este panel es solo para la administración de Orden.' using errcode = '42501';
  end if;

  -- Tiene que ser una empresa suya. Apuntar a la de un cliente haría que los
  -- cobros de Orden se anoten adentro del negocio de otro.
  if p_empresa is not null and not exists (
    select 1 from public.miembros m
    where m.empresa_id = p_empresa and m.user_id = auth.uid()
      and m.rol in ('propietario', 'admin')
  ) then
    raise exception 'Solo podés elegir una empresa tuya.' using errcode = '42501';
  end if;

  insert into public.ajustes_orden (unica, empresa_id, updated_at)
  values (true, p_empresa, now())
  on conflict (unica) do update set empresa_id = excluded.empresa_id, updated_at = now();

  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (auth.uid(), p_empresa, 'definir_empresa_orden', jsonb_build_object('empresa', p_empresa));

  return jsonb_build_object('empresa_id', p_empresa);
end $fn$;

revoke all on function public.definir_empresa_orden(uuid) from public, anon;
grant execute on function public.definir_empresa_orden(uuid) to authenticated;

-- ------------------------------------------------------------
-- 2. ACTIVAR UN PLAN TAMBIÉN ANOTA EL COBRO
--
--    Redefine `cambiar_plan_cuenta()` de la 016 sumando `p_importe`.
--
--    El cobro se anota en un bloque aparte con su propio manejador de
--    errores, y eso es deliberado: **si falla anotar el ingreso, la cuenta
--    del cliente se activa igual**. La prioridad es que quien pagó pueda
--    trabajar; la contabilidad propia se arregla después y a mano. Al revés
--    —dejar sin servicio a alguien que pagó porque no se pudo escribir un
--    movimiento— sería absurdo.
-- ------------------------------------------------------------
create or replace function public.cambiar_plan_cuenta(
  p_empresa uuid,
  p_plan    text,
  p_meses   integer default 1,
  p_nota    text default '',
  p_importe numeric default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_antes    public.suscripciones;
  v_fin      timestamptz;
  v_estado   text;
  v_orden    uuid;
  v_cliente  text;
  v_ingreso  uuid;
  v_aviso    text := null;
begin
  if not public.es_superadmin() then
    raise exception 'Este panel es solo para la administración de Orden.' using errcode = '42501';
  end if;

  if p_plan not in ('gratis', 'pro', 'negocio') then
    raise exception 'Plan desconocido: %', p_plan using errcode = '22023';
  end if;

  select * into v_antes from public.suscripciones where empresa_id = p_empresa;
  if v_antes.empresa_id is null then
    raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
  end if;

  select nombre into v_cliente from public.empresas where id = p_empresa;

  if p_plan = 'gratis' then
    v_estado := 'vencida';
    v_fin := now();
  else
    v_estado := 'activa';
    -- Si todavía le queda tiempo pago, se le suma; si no, arranca hoy.
    v_fin := greatest(coalesce(v_antes.periodo_fin, now()), now())
             + make_interval(months => greatest(1, coalesce(p_meses, 1)));
  end if;

  update public.suscripciones
  set plan = p_plan,
      estado = v_estado,
      periodo_inicio = case when p_plan = 'gratis' then periodo_inicio else now() end,
      periodo_fin = v_fin,
      proveedor_pago = case when p_plan = 'gratis' then proveedor_pago else 'transferencia' end,
      updated_at = now()
  where empresa_id = p_empresa;

  perform set_config('orden.suscripcion_confiable', '1', true);
  update public.empresas
  set plan = case when p_plan = 'gratis' then 'gratis' else 'pro' end
  where id = p_empresa;
  perform set_config('orden.suscripcion_confiable', '0', true);

  -- ---- el cobro, como ingreso de Orden ----
  if p_plan <> 'gratis' and coalesce(p_importe, 0) > 0 then
    select empresa_id into v_orden from public.ajustes_orden where unica;

    if v_orden is null then
      v_aviso := 'No hay una empresa de Orden elegida, así que el cobro no se anotó en tus finanzas.';
    elsif v_orden = p_empresa then
      -- Cobrarse a uno mismo sería inventarse un ingreso.
      v_aviso := 'Esta ES tu empresa, así que no se anotó ningún ingreso.';
    else
      begin
        insert into public.movimientos (
          empresa_id, tipo, estado, fecha, descripcion, categoria,
          subtotal, descuento, monto, costo_total, metodo_pago, contraparte, creado_por
        ) values (
          v_orden, 'ingreso', 'activo', public.hoy_empresa(v_orden),
          'Suscripción ' || coalesce(v_cliente, 'cliente'), 'Suscripciones',
          p_importe, 0, p_importe, 0, 'transferencia',
          left(coalesce(v_cliente, ''), 80), auth.uid()
        )
        returning id into v_ingreso;
      exception when others then
        -- La cuenta del cliente YA quedó activa. Que no se pueda anotar el
        -- ingreso propio no puede deshacer eso.
        v_aviso := 'La cuenta se activó, pero el ingreso no se pudo anotar: ' || sqlerrm;
      end;
    end if;
  end if;

  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (auth.uid(), p_empresa, 'cambiar_plan', jsonb_build_object(
    'plan_antes', v_antes.plan, 'plan_despues', p_plan,
    'estado_antes', v_antes.estado, 'estado_despues', v_estado,
    'vence_antes', v_antes.periodo_fin, 'vence_despues', v_fin,
    'meses', greatest(1, coalesce(p_meses, 1)),
    'importe', p_importe,
    'ingreso_id', v_ingreso,
    'nota', left(coalesce(p_nota, ''), 300)
  ));

  return jsonb_build_object(
    'plan', p_plan, 'estado', v_estado, 'periodo_fin', v_fin,
    'ingreso_anotado', v_ingreso is not null,
    'aviso', v_aviso
  );
end $fn$;

-- La firma de 4 argumentos queda muerta: si no se borra, PostgREST ve dos
-- funciones con el mismo nombre y no sabe cuál llamar.
drop function if exists public.cambiar_plan_cuenta(uuid, text, integer, text);

revoke all on function public.cambiar_plan_cuenta(uuid, text, integer, text, numeric)
  from public, anon;
grant execute on function public.cambiar_plan_cuenta(uuid, text, integer, text, numeric)
  to authenticated;

-- ------------------------------------------------------------
-- 3. LAS FINANZAS DE ORDEN, PARA EL PANEL
--
--    Cuánto entró por suscripciones y cómo está la propia empresa. Los
--    números salen de los mismos movimientos que ve cualquier cliente: no
--    hay una contabilidad paralela.
-- ------------------------------------------------------------
create or replace function public.finanzas_orden()
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_orden uuid;
  v_hoy   date;
  v_res   jsonb;
begin
  if not public.es_superadmin() then
    raise exception 'Este panel es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select empresa_id into v_orden from public.ajustes_orden where unica;

  if v_orden is null then
    -- Sin configurar. La pantalla ofrece elegirla en vez de mostrar ceros,
    -- que parecerían un negocio fundido.
    return jsonb_build_object('configurada', false);
  end if;

  v_hoy := public.hoy_empresa(v_orden);

  select jsonb_build_object(
    'configurada', true,
    'empresa_id', v_orden,
    'nombre', (select e.nombre from public.empresas e where e.id = v_orden),
    'moneda', (select e.moneda from public.empresas e where e.id = v_orden),

    -- Suscripciones cobradas este mes y en total.
    'cobrado_mes', coalesce(sum(m.monto) filter (
      where m.categoria = 'Suscripciones'
        and m.fecha >= date_trunc('month', v_hoy)::date), 0),
    'cobrado_total', coalesce(sum(m.monto) filter (where m.categoria = 'Suscripciones'), 0),
    'cobros_mes', coalesce(count(*) filter (
      where m.categoria = 'Suscripciones'
        and m.fecha >= date_trunc('month', v_hoy)::date), 0),

    -- Y el negocio entero, no solo las suscripciones.
    'ingresos_mes', coalesce(sum(m.monto) filter (
      where m.tipo in ('venta', 'ingreso')
        and m.fecha >= date_trunc('month', v_hoy)::date), 0),
    'gastos_mes', coalesce(sum(m.monto) filter (
      where m.tipo = 'gasto'
        and m.fecha >= date_trunc('month', v_hoy)::date), 0)
  ) into v_res
  from public.movimientos m
  where m.empresa_id = v_orden and m.estado = 'activo';

  -- Lo que se debe sale de su propia tabla.
  return v_res || jsonb_build_object(
    'deuda_total', coalesce((
      select sum(d.saldo) from public.deudas d
      where d.empresa_id = v_orden and d.activa), 0),
    'deudas_vencidas', coalesce((
      select count(*) from public.deudas d
      where d.empresa_id = v_orden and d.activa
        and d.saldo > 0 and d.vence_el is not null and d.vence_el < v_hoy), 0)
  );
end $fn$;

revoke all on function public.finanzas_orden() from public, anon;
grant execute on function public.finanzas_orden() to authenticated;

-- ------------------------------------------------------------
-- 4. UNA CUENTA PERSONAL ES DE UNA SOLA PERSONA
--
--    Redefine `unirse_empresa()` de la 009.
--
--    Antes el tope salía solo del plan, y una cuenta personal en `pro`
--    permitía tres. No tiene sentido: quien lleva sus finanzas propias no
--    tiene vendedores. Y como el código de acceso se puede compartir por
--    WhatsApp sin querer, conviene que la base lo impida y no solo que la
--    pantalla lo esconda.
-- ------------------------------------------------------------
create or replace function public.unirse_empresa(
  p_codigo text,
  p_nombre_usuario text default null
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_id      uuid;
  v_cuantos integer;
  v_tope    integer;
  v_tipo    text;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  select a.empresa_id into v_id
  from public.empresa_accesos a
  where a.codigo = upper(trim(coalesce(p_codigo, ''))) and a.activo;

  if v_id is null then
    raise exception 'El código no corresponde a ninguna empresa.' using errcode = '42501';
  end if;

  -- Ya es miembro: no es un error, simplemente devolvemos la empresa.
  if exists (select 1 from public.miembros where empresa_id = v_id and user_id = auth.uid()) then
    return v_id;
  end if;

  select tipo_cuenta into v_tipo from public.empresas where id = v_id;
  if v_tipo = 'personal' then
    raise exception 'Esa es una cuenta personal: no admite más personas.'
      using errcode = '54000';
  end if;

  select count(*)::int into v_cuantos from public.miembros where empresa_id = v_id;
  v_tope := (public.limites_plan(public.plan_efectivo_calculado(v_id))->>'miembros')::integer;

  if v_cuantos >= v_tope then
    raise exception 'Este negocio llegó al máximo de % personas de su plan. El plan Negocio permite más.', v_tope
      using errcode = '54000';
  end if;

  insert into public.miembros (empresa_id, user_id, nombre, rol)
  values (v_id, auth.uid(), coalesce(nullif(trim(p_nombre_usuario), ''), 'Colaborador'), 'vendedor')
  on conflict (empresa_id, user_id) do nothing;

  return v_id;
end $fn$;

revoke all on function public.unirse_empresa(text, text) from public, anon;
grant execute on function public.unirse_empresa(text, text) to authenticated;


-- ############################################################
-- ##  020_precios_ajustados.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 020 · Precios en dólares y un mes de regalo
--
-- DOS CORRECCIONES SOBRE LA 017
--
-- 1. LOS DÓLARES ESTABAN MAL. Se habían puesto números «bonitos» de
--    marketing (7,99 y 24,99) sin mirar el cambio real. A 190.000 guaraníes
--    le corresponden unos 32 dólares, no 25: cobrar 25 era regalar el 20% a
--    todo el que pague en dólares.
--
--    Los precios en guaraníes NO cambian. Es la conversión la que estaba
--    equivocada.
--
--      personal   Gs.  60.000  →  US$ 11
--      Pro        Gs. 190.000  →  US$ 32
--      Premium    Gs. 250.000  →  US$ 42   (el mismo cambio que Pro)
--
-- 2. EL ANUAL DA UN MES, NO DOS. Doce meses al precio de once.
--
--    Dos meses era demasiado para un producto que todavía no tiene historia
--    de retención: se regalaba un sexto del año a cambio de un adelanto que
--    hoy no hace falta. Con uno, el descuento sigue siendo un motivo real
--    para pagar por año y el número cierra mejor.
--
--    El cartel de «un mes de regalo» no se escribe a mano en ningún lado:
--    `mesesDeRegalo()` lo calcula de estos importes. Si mañana cambian, el
--    texto sigue diciendo la verdad o desaparece — nunca miente.
--
-- Idempotente.
-- ============================================================

delete from public.precios;

insert into public.precios (tipo_cuenta, plan, moneda, periodo, importe) values
  -- Cuenta personal. Un solo plan pago.
  ('personal',    'pro',     'PYG', 'mensual',   60000),
  ('personal',    'pro',     'PYG', 'anual',    660000),
  ('personal',    'pro',     'USD', 'mensual',      11),
  ('personal',    'pro',     'USD', 'anual',       121),

  -- Comercio · Pro: hasta 3 vendedores.
  ('emprendedor', 'pro',     'PYG', 'mensual',  190000),
  ('emprendedor', 'pro',     'PYG', 'anual',   2090000),
  ('emprendedor', 'pro',     'USD', 'mensual',      32),
  ('emprendedor', 'pro',     'USD', 'anual',       352),

  -- Comercio · Premium: desde. Cada vendedor extra suma aparte.
  ('emprendedor', 'negocio', 'PYG', 'mensual',  250000),
  ('emprendedor', 'negocio', 'PYG', 'anual',   2750000),
  ('emprendedor', 'negocio', 'USD', 'mensual',      42),
  ('emprendedor', 'negocio', 'USD', 'anual',       462);

-- Cada vendedor de más, con el mismo cambio que el resto.
create or replace function public.precio_por_vendedor(p_moneda text default 'PYG')
returns numeric language sql immutable set search_path = public as $fn$
  select case upper(coalesce(p_moneda, 'PYG'))
    when 'PYG' then 60000::numeric
    when 'USD' then 10::numeric
    else 10::numeric
  end;
$fn$;

grant execute on function public.precio_por_vendedor(text) to anon, authenticated;


-- ############################################################
-- ##  021_rubros.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 021 · El rubro de cada negocio
--
-- LA IDEA: UN MOTOR, VARIAS PUERTAS
--
-- Entró plata, salió plata, esto me queda, debo esto y vence tal día. Eso es
-- igual para un almacén, un ganadero, un agricultor y un taller — y es el
-- 90% de Orden. Lo que cambia entre ellos es más chico de lo que parece:
--
--   · las palabras («producto» vs «hacienda» vs «cultivo»);
--   · las categorías de gasto (Publicidad vs Sanidad vs Fertilizante);
--   · el RITMO, que es lo único que rompe algo de verdad.
--
-- POR QUÉ EL RITMO IMPORTA MÁS QUE LAS PALABRAS
--
-- Orden está construido sobre el hábito diario: la racha, el cierre del día,
-- el recordatorio de la noche. Eso le calza perfecto a quien vende todos los
-- días.
--
-- A un ganadero no. Compra un ternero, gasta en maíz y sanidad durante
-- dieciocho meses, y recién ahí vende. Su cierre del día diría «hoy no hubo
-- actividad» casi siempre, y su racha se cortaría sin parar. Un sistema que
-- todos los días te dice que fallaste, cuando no fallaste en nada, se
-- desinstala.
--
-- Por eso el rubro decide QUÉ SECCIONES EXISTEN, no solo cómo se llaman.
--
-- DÓNDE VIVE CADA COSA
--
-- Acá vive el DATO: qué rubro eligió cada empresa, y las categorías de gasto
-- que le corresponden (para que la IA las sugiera sin desplegar nada).
--
-- Las palabras y qué pantallas se muestran viven en `src/lib/rubros.ts`,
-- porque son presentación y no seguridad: que un ganadero vea el cierre del
-- día no filtra nada de nadie. La regla de siempre —lo que protege va en
-- PostgreSQL— sigue intacta.
--
-- Idempotente. Todo lo que ya existe queda como 'comercio', que es lo que es.
-- ============================================================

-- ------------------------------------------------------------
-- 1. LA COLUMNA
-- ------------------------------------------------------------
alter table public.empresas
  add column if not exists rubro text not null default 'comercio';

do $$ begin
  alter table public.empresas
    add constraint empresas_rubro_check
    check (rubro in ('comercio', 'ganaderia', 'agricultura', 'servicios'));
exception when duplicate_object then null; end $$;

comment on column public.empresas.rubro is
  'Adapta vocabulario, categorías y qué secciones existen. No es un permiso: '
  'lo que protege datos sigue siendo RLS y los roles.';

-- ------------------------------------------------------------
-- 2. LAS CATEGORÍAS DE GASTO DE CADA RUBRO
--
--    Viven en la base y no en el código por el mismo motivo que los precios:
--    ajustar una lista no puede requerir un despliegue. Las usa el prompt de
--    la captura para sugerir, y la persona puede escribir cualquier otra —la
--    columna `categoria` es texto libre y va a seguir siéndolo. Una lista
--    cerrada obligaría a alguien a meter su gasto en el casillero
--    equivocado, que es peor que no sugerir nada.
-- ------------------------------------------------------------
create or replace function public.categorias_de_rubro(p_rubro text)
returns jsonb language sql immutable set search_path = public as $fn$
  -- Cada categoría viene con PISTAS, no solo con su nombre.
  --
  -- Hizo falta al probarlo con el modelo real: «compré veinte bolsas de maíz»
  -- caía en «Otros» porque nada le decía que el maíz de un ganadero es
  -- comida de animales. Con las pistas cae en Alimentación. Un nombre de
  -- categoría solo, sin contexto, no alcanza para clasificar bien.
  select case coalesce(p_rubro, 'comercio')
    when 'ganaderia' then jsonb_build_array(
      jsonb_build_object('nombre','Alimentación','pistas','maíz, balanceado, ración, fardos, sal, pasto'),
      jsonb_build_object('nombre','Sanidad','pistas','vacunas, antiparasitarios, veterinario, remedios'),
      jsonb_build_object('nombre','Personal','pistas','peón, capataz, jornales, sueldos'),
      jsonb_build_object('nombre','Combustible','pistas','gasoil, nafta'),
      jsonb_build_object('nombre','Arrendamiento','pistas','alquiler de campo, pastaje'),
      jsonb_build_object('nombre','Fletes','pistas','transporte de hacienda, camión jaula'),
      jsonb_build_object('nombre','Mantenimiento','pistas','alambrado, aguadas, maquinaria, herramientas'),
      jsonb_build_object('nombre','Impuestos','pistas',''),
      jsonb_build_object('nombre','Otros','pistas',''))
    when 'agricultura' then jsonb_build_array(
      jsonb_build_object('nombre','Semilla','pistas','semilla, plantines'),
      jsonb_build_object('nombre','Fertilizante','pistas','urea, fosfato, abono'),
      jsonb_build_object('nombre','Agroquímicos','pistas','herbicida, fungicida, insecticida'),
      jsonb_build_object('nombre','Combustible','pistas','gasoil, nafta'),
      jsonb_build_object('nombre','Cosecha','pistas','cosechadora, trilla, secado'),
      jsonb_build_object('nombre','Fletes','pistas','transporte de granos'),
      jsonb_build_object('nombre','Arrendamiento','pistas','alquiler de campo'),
      jsonb_build_object('nombre','Personal','pistas','jornales, tractorista, peón'),
      jsonb_build_object('nombre','Otros','pistas',''))
    when 'servicios' then jsonb_build_array(
      jsonb_build_object('nombre','Materiales','pistas','cemento, arena, cables, pintura, insumos'),
      jsonb_build_object('nombre','Repuestos','pistas','piezas, filtros, aceite'),
      jsonb_build_object('nombre','Herramientas','pistas',''),
      jsonb_build_object('nombre','Combustible','pistas','gasoil, nafta'),
      jsonb_build_object('nombre','Personal','pistas','ayudante, jornales, sueldos'),
      jsonb_build_object('nombre','Transporte','pistas','flete, viaje, delivery'),
      jsonb_build_object('nombre','Impuestos','pistas',''),
      jsonb_build_object('nombre','Otros','pistas',''))
    else jsonb_build_array(
      jsonb_build_object('nombre','Mercadería','pistas','lo que comprás para revender'),
      jsonb_build_object('nombre','Transporte','pistas','combustible, flete, delivery'),
      jsonb_build_object('nombre','Comida','pistas',''),
      jsonb_build_object('nombre','Publicidad','pistas',''),
      jsonb_build_object('nombre','Servicios','pistas','luz, agua, internet, teléfono'),
      jsonb_build_object('nombre','Alquiler','pistas',''),
      jsonb_build_object('nombre','Sueldos','pistas','empleados, jornales'),
      jsonb_build_object('nombre','Impuestos','pistas',''),
      jsonb_build_object('nombre','Otros','pistas',''))
  end;
$fn$;

grant execute on function public.categorias_de_rubro(text) to anon, authenticated;

-- ------------------------------------------------------------
-- 3. ¿ESTE RUBRO CIERRA EL DÍA?
--
--    Una sola pregunta en un solo lugar, para que la pantalla y las tareas
--    programadas no puedan contestarla distinto. Sin esto, el recordatorio
--    de la noche le seguiría llegando a un ganadero aunque la pantalla del
--    cierre no exista — que es la peor combinación posible.
-- ------------------------------------------------------------
create or replace function public.rubro_cierra_el_dia(p_rubro text)
returns boolean language sql immutable set search_path = public as $fn$
  select coalesce(p_rubro, 'comercio') in ('comercio', 'servicios');
$fn$;

grant execute on function public.rubro_cierra_el_dia(text) to anon, authenticated;

-- ------------------------------------------------------------
-- 4. CAMBIAR DE RUBRO
--
--    NO borra nada. Cambiar de rubro cambia palabras, categorías sugeridas y
--    qué pantallas se ven; los datos quedan donde están. Si alguien vuelve
--    atrás, los encuentra intactos.
-- ------------------------------------------------------------
create or replace function public.cambiar_rubro(p_empresa uuid, p_rubro text)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_antes text;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el propietario o un administrador puede cambiar el rubro.'
      using errcode = '42501';
  end if;

  if p_rubro not in ('comercio', 'ganaderia', 'agricultura', 'servicios') then
    raise exception 'Rubro desconocido: %', p_rubro using errcode = '22023';
  end if;

  select rubro into v_antes from public.empresas where id = p_empresa;
  if v_antes is null then
    raise exception 'Esa empresa no existe.' using errcode = 'P0002';
  end if;

  update public.empresas set rubro = p_rubro where id = p_empresa;

  return jsonb_build_object('rubro', p_rubro, 'antes', v_antes);
end $fn$;

revoke all on function public.cambiar_rubro(uuid, text) from public, anon;
grant execute on function public.cambiar_rubro(uuid, text) to authenticated;

-- ------------------------------------------------------------
-- 5. CREAR EMPRESA · ahora también con rubro
--
--    Redefinición de la versión de la 016. Lo único que cambia: recibe el
--    rubro. Una cuenta personal no tiene rubro de negocio —no vende nada—
--    así que se le fuerza 'comercio', que es el neutro y del que no ve
--    ninguna pantalla de comercio igual.
-- ------------------------------------------------------------
create or replace function public.crear_empresa(
  p_nombre text,
  p_moneda text default 'PYG',
  p_nombre_usuario text default null,
  p_zona text default 'America/Asuncion',
  p_tipo_cuenta text default 'emprendedor',
  p_rubro text default 'comercio'
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_id uuid;
  v_codigo text;
  v_intentos int := 0;
  v_fin timestamptz;
  v_tipo text;
  v_rubro text;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  if char_length(trim(coalesce(p_nombre, ''))) < 2 then
    raise exception 'El nombre del negocio es muy corto.' using errcode = '22023';
  end if;

  v_tipo := case when p_tipo_cuenta = 'personal' then 'personal' else 'emprendedor' end;

  v_rubro := case
    when v_tipo = 'personal' then 'comercio'
    when p_rubro in ('comercio', 'ganaderia', 'agricultura', 'servicios') then p_rubro
    else 'comercio'
  end;

  loop
    v_codigo := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
    exit when not exists (select 1 from public.empresa_accesos where codigo = v_codigo);
    v_intentos := v_intentos + 1;
    if v_intentos > 12 then
      raise exception 'No se pudo generar un código de acceso.' using errcode = '55000';
    end if;
  end loop;

  insert into public.empresas (nombre, moneda, creada_por, zona_horaria, tipo_cuenta, rubro)
  values (trim(p_nombre), coalesce(p_moneda, 'PYG'), auth.uid(),
          coalesce(nullif(trim(p_zona), ''), 'America/Asuncion'), v_tipo, v_rubro)
  returning id into v_id;

  insert into public.miembros (empresa_id, user_id, nombre, rol)
  values (v_id, auth.uid(), coalesce(nullif(trim(p_nombre_usuario), ''), 'Propietario'), 'propietario');

  insert into public.empresa_accesos (empresa_id, codigo)
  values (v_id, v_codigo);

  -- La prueba se escribe acá directamente y no llamando a iniciar_prueba()
  -- porque esa función es de service_role: quien crea la empresa es un
  -- usuario común, y no queremos otorgarle ese permiso para esto.
  v_fin := now() + make_interval(days => public.dias_de_prueba(v_tipo));
  insert into public.suscripciones (empresa_id, plan, estado, periodo_inicio, periodo_fin, prueba_fin)
  values (v_id, 'pro', 'prueba', now(), v_fin, v_fin);

  perform set_config('orden.suscripcion_confiable', '1', true);
  update public.empresas set plan = 'pro' where id = v_id;
  perform set_config('orden.suscripcion_confiable', '0', true);

  return v_id;
end $fn$;

-- La firma de 5 argumentos queda muerta: si no se borra, PostgREST ve dos
-- funciones con el mismo nombre y no sabe cuál llamar.
drop function if exists public.crear_empresa(text, text, text, text, text);

revoke all on function public.crear_empresa(text, text, text, text, text, text)
  from public, anon;
grant execute on function public.crear_empresa(text, text, text, text, text, text)
  to authenticated;

-- ------------------------------------------------------------
-- 6. EL RECORDATORIO NO LE LLEGA A QUIEN NO CIERRA EL DÍA
--
--    Redefine `empresas_sin_cargar_hoy()` de la 008, con la MISMA firma y
--    la misma forma de respuesta: lo único que se agrega es el filtro por
--    rubro. Cambiarle el tipo de retorno habría roto la tarea de la noche
--    en silencio.
--
--    Sin este filtro, un ganadero recibiría todas las noches un «no
--    cargaste nada hoy» — y no cargó nada porque no tenía nada que cargar.
--    Es la forma más rápida de que alguien apague los avisos y no los
--    vuelva a encender nunca.
-- ------------------------------------------------------------
create or replace function public.empresas_sin_cargar_hoy(p_racha_minima integer default 2)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_res jsonb;
begin
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'empresa_id', e.id,
      'nombre',     e.nombre,
      'zona',       e.zona_horaria,
      'racha',      r.largo
    ) as x
    from public.empresas e
    join lateral (
      with dias as (
        select distinct m.fecha from public.movimientos m
        where m.empresa_id = e.id and m.estado = 'activo'
          and m.fecha <= (now() at time zone e.zona_horaria)::date
      ),
      numeradas as (
        select fecha, (fecha - (row_number() over (order by fecha))::int) as isla from dias
      ),
      rachas as (
        select count(*)::int as largo, max(fecha) as hasta from numeradas group by isla
      )
      select largo, hasta from rachas order by hasta desc limit 1
    ) r on true
    where public.rubro_cierra_el_dia(e.rubro)
      and r.hasta = (now() at time zone e.zona_horaria)::date - 1
      and r.largo >= greatest(p_racha_minima, 1)
  ) s;

  return v_res;
end $fn$;

revoke all on function public.empresas_sin_cargar_hoy(integer) from public, anon, authenticated;
grant execute on function public.empresas_sin_cargar_hoy(integer) to service_role;


-- ############################################################
-- ##  022_ficha_y_correcciones.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 022 · Ficha del cliente, deshacer y borrar
--
-- TRES COSAS QUE FALTABAN, Y LAS TRES APARECIERON USANDO EL PANEL DE VERDAD
--
-- 1. NO SE PODÍA DESHACER UNA ACTIVACIÓN. Se activó un plan por error sobre
--    una cuenta que todavía estaba en prueba, y el periodo de prueba se
--    perdió: quedó reemplazado por el mes pagado. Ninguna pantalla podía
--    devolverlo.
--
--    El arreglo sale gratis porque el registro de auditoría ya guardaba cómo
--    estaba todo ANTES de cada cambio. Estaba ahí para reclamos; resulta que
--    también sirve para deshacer. Un registro que solo se lee cuando hay un
--    problema es medio registro.
--
-- 2. NO SE PODÍA BORRAR UNA CUENTA. Y hacía falta: al borrar un usuario
--    desde el panel de Supabase, sus `miembros` se van por cascada y
--    `empresas.creada_por` queda en null — la empresa sobrevive **sin dueño
--    y sin nadie adentro**. Nadie puede entrar, nadie puede borrarla, y
--    ensucia la lista de clientes para siempre.
--
--    Pasó con dos cuentas de prueba. Va a volver a pasar cada vez que se
--    borre un usuario por fuera de la app.
--
-- 3. NO HABÍA DÓNDE ANOTAR QUIÉN ES EL CLIENTE. Había un botón para
--    escribirle por WhatsApp y ningún lugar donde guardar su teléfono. El
--    panel sabía todo del cobro y nada de la persona.
--
-- Idempotente.
-- ============================================================

-- ------------------------------------------------------------
-- 1. CÓMO NOS CONOCIÓ
--
--    Va en `empresas` y no en la ficha de abajo porque lo contesta la propia
--    persona al registrarse, no lo anota la administración. Preguntarlo en el
--    momento da un dato honesto; reconstruirlo después de memoria, no.
--
--    Es texto libre con una lista sugerida en la pantalla: encasillar a
--    alguien en cinco opciones fijas hace que la mitad elija «otro» y se
--    pierda justo lo que se quería saber.
-- ------------------------------------------------------------
alter table public.empresas
  add column if not exists como_nos_conocio text not null default '';

comment on column public.empresas.como_nos_conocio is
  'Lo contesta quien crea la cuenta. Texto libre: la pantalla sugiere opciones.';

-- ------------------------------------------------------------
-- 2. LA FICHA DEL CLIENTE
--
--    Datos de contacto y de seguimiento. Tabla aparte y no columnas en
--    `empresas` por una razón concreta: `empresas` la leen los miembros del
--    negocio, y las notas de seguimiento son de la administración. Nadie
--    tiene por qué leer lo que anotamos sobre él.
-- ------------------------------------------------------------
create table if not exists public.ficha_cliente (
  empresa_id  uuid primary key references public.empresas (id) on delete cascade,
  contacto    text not null default '',
  telefono    text not null default '',
  se_dedica   text not null default '',
  notas       text not null default '',
  updated_at  timestamptz not null default now()
);

alter table public.ficha_cliente enable row level security;

drop policy if exists ficha_cliente_select on public.ficha_cliente;
create policy ficha_cliente_select on public.ficha_cliente
  for select to authenticated
  using (public.es_superadmin());

revoke all on public.ficha_cliente from anon, authenticated;
grant select on public.ficha_cliente to authenticated;

create or replace function public.guardar_ficha_cliente(
  p_empresa   uuid,
  p_contacto  text default '',
  p_telefono  text default '',
  p_se_dedica text default '',
  p_notas     text default ''
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
begin
  if not public.es_superadmin() then
    raise exception 'Este panel es solo para la administración de Orden.' using errcode = '42501';
  end if;

  if not exists (select 1 from public.empresas where id = p_empresa) then
    raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
  end if;

  insert into public.ficha_cliente (empresa_id, contacto, telefono, se_dedica, notas, updated_at)
  values (p_empresa, left(coalesce(p_contacto, ''), 120), left(coalesce(p_telefono, ''), 40),
          left(coalesce(p_se_dedica, ''), 200), left(coalesce(p_notas, ''), 2000), now())
  on conflict (empresa_id) do update set
    contacto = excluded.contacto,
    telefono = excluded.telefono,
    se_dedica = excluded.se_dedica,
    notas = excluded.notas,
    updated_at = now();

  return jsonb_build_object('guardada', true);
end $fn$;

revoke all on function public.guardar_ficha_cliente(uuid, text, text, text, text) from public, anon;
grant execute on function public.guardar_ficha_cliente(uuid, text, text, text, text) to authenticated;

-- ------------------------------------------------------------
-- 3. DESHACER EL ÚLTIMO CAMBIO
--
--    Restaura plan, estado y vencimiento a como estaban antes, leyéndolo del
--    registro de auditoría.
--
--    Si ese cambio había anotado un cobro, el ingreso NO se borra: se ANULA.
--    Es la misma regla que rige todo el sistema — un movimiento que existió
--    deja rastro aunque deje de sumar. Borrarlo dejaría un registro de
--    auditoría apuntando a algo que ya no está.
--
--    Solo deshace el ÚLTIMO cambio, y una sola vez. Deshacer en cadena
--    llevaría a estados que nunca existieron: el registro guarda «cómo
--    estaba antes de este cambio», no una línea de tiempo completa.
-- ------------------------------------------------------------
create or replace function public.deshacer_ultimo_cambio(p_empresa uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_reg     public.registro_admin;
  v_plan    text;
  v_estado  text;
  v_fin     timestamptz;
  v_ingreso uuid;
  v_anulado boolean := false;
begin
  if not public.es_superadmin() then
    raise exception 'Este panel es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select * into v_reg
  from public.registro_admin
  where empresa_id = p_empresa
    and accion in ('cambiar_plan', 'extender_prueba')
  order by created_at desc
  limit 1;

  if v_reg.id is null then
    raise exception 'No hay ningún cambio para deshacer en esta cuenta.' using errcode = 'P0002';
  end if;

  -- Ya se deshizo: sin esto, tocar dos veces dejaría el estado de dos
  -- cambios atrás, que es un estado que nunca existió.
  if coalesce((v_reg.detalle->>'deshecho')::boolean, false) then
    raise exception 'Ese cambio ya se deshizo.' using errcode = '22023';
  end if;

  v_plan   := coalesce(v_reg.detalle->>'plan_antes', 'pro');
  v_estado := coalesce(v_reg.detalle->>'estado_antes', 'prueba');
  v_fin    := nullif(v_reg.detalle->>'vence_antes', '')::timestamptz;

  update public.suscripciones
  set plan = v_plan,
      estado = v_estado,
      periodo_fin = v_fin,
      updated_at = now()
  where empresa_id = p_empresa;

  perform set_config('orden.suscripcion_confiable', '1', true);
  update public.empresas
  set plan = case when v_plan = 'gratis' then 'gratis' else 'pro' end
  where id = p_empresa;
  perform set_config('orden.suscripcion_confiable', '0', true);

  -- El cobro que se había anotado, si lo hubo.
  v_ingreso := nullif(v_reg.detalle->>'ingreso_id', '')::uuid;
  if v_ingreso is not null then
    update public.movimientos
    set estado = 'anulado',
        anulado_por = auth.uid(),
        anulado_at = now(),
        motivo_anulacion = 'Se deshizo la activación desde el panel'
    where id = v_ingreso and estado = 'activo';
    v_anulado := found;
  end if;

  -- Se marca el registro para que no se pueda deshacer dos veces.
  update public.registro_admin
  set detalle = detalle || jsonb_build_object('deshecho', true, 'deshecho_at', now())
  where id = v_reg.id;

  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (auth.uid(), p_empresa, 'deshacer', jsonb_build_object(
    'registro', v_reg.id,
    'volvio_a_plan', v_plan,
    'volvio_a_estado', v_estado,
    'volvio_a_vencer', v_fin,
    'ingreso_anulado', v_anulado
  ));

  return jsonb_build_object(
    'plan', v_plan, 'estado', v_estado, 'periodo_fin', v_fin,
    'ingreso_anulado', v_anulado
  );
end $fn$;

revoke all on function public.deshacer_ultimo_cambio(uuid) from public, anon;
grant execute on function public.deshacer_ultimo_cambio(uuid) to authenticated;

-- ------------------------------------------------------------
-- 4. QUÉ ARCHIVOS DEJARÍA UNA CUENTA AL BORRARSE
--
--    Se pide ANTES de borrar. Storage no entiende de claves foráneas: si no
--    se guardan las rutas primero, las fotos quedan ocupando lugar para
--    siempre y ya no hay ninguna fila que las nombre.
-- ------------------------------------------------------------
create or replace function public.archivos_de_cuenta(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
begin
  if not public.es_superadmin() then
    raise exception 'Este panel es solo para la administración de Orden.' using errcode = '42501';
  end if;

  return coalesce((
    select jsonb_agg(a.ruta)
    from public.adjuntos a
    where a.empresa_id = p_empresa and a.ruta is not null
  ), '[]'::jsonb);
end $fn$;

revoke all on function public.archivos_de_cuenta(uuid) from public, anon;
grant execute on function public.archivos_de_cuenta(uuid) to authenticated;

-- ------------------------------------------------------------
-- 5. BORRAR UNA CUENTA
--
--    Pide el nombre exacto escrito a mano. Es la misma barrera que usa
--    `vaciar_empresa()`, y por el mismo motivo: un botón rojo se toca por
--    curiosidad, escribir «Perfumeria Zurik» letra por letra no se hace sin
--    querer.
--
--    Lo que NO hace: borrar al usuario de `auth.users`. Esa persona puede
--    tener otra empresa, y además una cuenta de acceso no es lo mismo que un
--    negocio. Si además hay que borrar el usuario, se hace aparte y a
--    conciencia.
-- ------------------------------------------------------------
create or replace function public.borrar_cuenta(p_empresa uuid, p_confirmacion text)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_nombre  text;
  v_movs    integer;
  v_persona integer;
begin
  if not public.es_superadmin() then
    raise exception 'Este panel es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select nombre into v_nombre from public.empresas where id = p_empresa;
  if v_nombre is null then
    raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
  end if;

  if trim(coalesce(p_confirmacion, '')) <> v_nombre then
    raise exception 'Para borrar hay que escribir el nombre exacto: %', v_nombre
      using errcode = '22023';
  end if;

  select count(*) into v_movs from public.movimientos where empresa_id = p_empresa;
  select count(*) into v_persona from public.miembros where empresa_id = p_empresa;

  -- Se deja constancia ANTES de borrar: después la empresa ya no existe y
  -- `registro_admin.empresa_id` queda en null. El nombre va en el detalle
  -- para que el registro siga diciendo de quién se trataba.
  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (auth.uid(), p_empresa, 'borrar_cuenta', jsonb_build_object(
    'nombre', v_nombre, 'movimientos', v_movs, 'personas', v_persona
  ));

  delete from public.empresas where id = p_empresa;

  return jsonb_build_object('borrada', true, 'nombre', v_nombre, 'movimientos', v_movs);
end $fn$;

revoke all on function public.borrar_cuenta(uuid, text) from public, anon;
grant execute on function public.borrar_cuenta(uuid, text) to authenticated;

-- ------------------------------------------------------------
-- 6. LA LISTA DE CUENTAS, CON LO NUEVO
--
--    Redefine `listar_cuentas()` de la 016 sumando la ficha, cómo nos
--    conoció, y —importante— si la cuenta quedó SIN DUEÑO.
--
--    Esa última bandera existe porque el caso es real y silencioso: borrar
--    un usuario desde Supabase deja la empresa viva y vacía. Antes se veía
--    como «sin correo» y parecía un dato que faltaba; ahora se dice lo que
--    es, para que se pueda limpiar.
--
--    Sigue sin devolver un solo monto de nadie. La prueba que lo comprueba
--    también.
-- ------------------------------------------------------------
create or replace function public.listar_cuentas(
  p_busqueda text default null,
  p_estado   text default null,
  p_limite   integer default 200
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_res jsonb;
  v_periodo text;
begin
  if not public.es_superadmin() then
    raise exception 'Este panel es solo para la administración de Orden.' using errcode = '42501';
  end if;

  v_periodo := to_char(now(), 'YYYY-MM');

  select coalesce(jsonb_agg(x order by x->>'orden'), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'empresa_id',   e.id,
      'nombre',       e.nombre,
      'tipo_cuenta',  e.tipo_cuenta,
      'rubro',        e.rubro,
      'moneda',       e.moneda,
      'creada',       e.created_at,
      'propietario',  coalesce(prop.nombre, ''),
      'correo',       coalesce(u.email, ''),
      'sin_duenio',   prop.id is null,
      'como_nos_conocio', e.como_nos_conocio,

      'contacto',  coalesce(f.contacto, ''),
      'telefono',  coalesce(f.telefono, ''),
      'se_dedica', coalesce(f.se_dedica, ''),
      'notas',     coalesce(f.notas, ''),

      'plan',         public.plan_efectivo_calculado(e.id),
      'plan_guardado', s.plan,
      'estado',       s.estado,
      'periodo_fin',  s.periodo_fin,
      'prueba_fin',   s.prueba_fin,
      'dias_restantes', case
        when s.periodo_fin is null then null
        else floor(extract(epoch from (s.periodo_fin - now())) / 86400)::integer
      end,
      'miembros', (select count(*) from public.miembros m where m.empresa_id = e.id),
      'movimientos', (select count(*) from public.movimientos mv where mv.empresa_id = e.id),
      'ultima_actividad', (select max(mv.created_at) from public.movimientos mv where mv.empresa_id = e.id),
      'ia_usada', coalesce((
        select ui.usados from public.uso_ia ui
        where ui.empresa_id = e.id and ui.periodo = v_periodo
      ), 0),
      'ia_tope', (public.limites_plan(public.plan_efectivo_calculado(e.id))->>'capturas_mes')::integer,
      'puede_deshacer', exists (
        select 1 from public.registro_admin r
        where r.empresa_id = e.id
          and r.accion in ('cambiar_plan', 'extender_prueba')
          and not coalesce((r.detalle->>'deshecho')::boolean, false)
      ),
      'orden', lpad(
        greatest(0, coalesce(
          floor(extract(epoch from (s.periodo_fin - now())) / 86400)::integer + 1000,
          9999))::text, 5, '0')
    ) as x
    from public.empresas e
    join public.suscripciones s on s.empresa_id = e.id
    left join public.miembros prop
      on prop.empresa_id = e.id and prop.rol = 'propietario'
    left join auth.users u on u.id = prop.user_id
    left join public.ficha_cliente f on f.empresa_id = e.id
    where (
        p_busqueda is null
        or trim(p_busqueda) = ''
        or e.nombre ilike '%' || trim(p_busqueda) || '%'
        or coalesce(u.email, '') ilike '%' || trim(p_busqueda) || '%'
        or coalesce(f.contacto, '') ilike '%' || trim(p_busqueda) || '%'
        or coalesce(f.telefono, '') ilike '%' || trim(p_busqueda) || '%'
      )
      and (p_estado is null or trim(p_estado) = '' or s.estado = p_estado)
    limit greatest(1, least(coalesce(p_limite, 200), 500))
  ) t;

  return v_res;
end $fn$;

revoke all on function public.listar_cuentas(text, text, integer) from public, anon;
grant execute on function public.listar_cuentas(text, text, integer) to authenticated;

-- ------------------------------------------------------------
-- 7. CREAR EMPRESA · ahora también guarda cómo nos conoció
-- ------------------------------------------------------------
create or replace function public.crear_empresa(
  p_nombre text,
  p_moneda text default 'PYG',
  p_nombre_usuario text default null,
  p_zona text default 'America/Asuncion',
  p_tipo_cuenta text default 'emprendedor',
  p_rubro text default 'comercio',
  p_como_nos_conocio text default ''
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_id uuid;
  v_codigo text;
  v_intentos int := 0;
  v_fin timestamptz;
  v_tipo text;
  v_rubro text;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  if char_length(trim(coalesce(p_nombre, ''))) < 2 then
    raise exception 'El nombre del negocio es muy corto.' using errcode = '22023';
  end if;

  v_tipo := case when p_tipo_cuenta = 'personal' then 'personal' else 'emprendedor' end;
  v_rubro := case
    when v_tipo = 'personal' then 'comercio'
    when p_rubro in ('comercio', 'ganaderia', 'agricultura', 'servicios') then p_rubro
    else 'comercio'
  end;

  loop
    v_codigo := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
    exit when not exists (select 1 from public.empresa_accesos where codigo = v_codigo);
    v_intentos := v_intentos + 1;
    if v_intentos > 12 then
      raise exception 'No se pudo generar un código de acceso.' using errcode = '55000';
    end if;
  end loop;

  insert into public.empresas (
    nombre, moneda, creada_por, zona_horaria, tipo_cuenta, rubro, como_nos_conocio
  )
  values (trim(p_nombre), coalesce(p_moneda, 'PYG'), auth.uid(),
          coalesce(nullif(trim(p_zona), ''), 'America/Asuncion'), v_tipo, v_rubro,
          left(coalesce(p_como_nos_conocio, ''), 80))
  returning id into v_id;

  insert into public.miembros (empresa_id, user_id, nombre, rol)
  values (v_id, auth.uid(), coalesce(nullif(trim(p_nombre_usuario), ''), 'Propietario'), 'propietario');

  insert into public.empresa_accesos (empresa_id, codigo)
  values (v_id, v_codigo);

  v_fin := now() + make_interval(days => public.dias_de_prueba(v_tipo));
  insert into public.suscripciones (empresa_id, plan, estado, periodo_inicio, periodo_fin, prueba_fin)
  values (v_id, 'pro', 'prueba', now(), v_fin, v_fin);

  perform set_config('orden.suscripcion_confiable', '1', true);
  update public.empresas set plan = 'pro' where id = v_id;
  perform set_config('orden.suscripcion_confiable', '0', true);

  return v_id;
end $fn$;

drop function if exists public.crear_empresa(text, text, text, text, text, text);

revoke all on function public.crear_empresa(text, text, text, text, text, text, text)
  from public, anon;
grant execute on function public.crear_empresa(text, text, text, text, text, text, text)
  to authenticated;


-- ############################################################
-- ##  023_registro_con_ficha.sql
-- ############################################################

-- ORDEN · Migración 023 · El registro pregunta quién es la persona
--
-- Hasta acá el orden del registro era: correo y contraseña primero, datos
-- después. Está al revés por dos motivos.
--
-- El primero es de quien se registra: la primera pantalla de un producto que
-- no conoce le pedía una contraseña. Es la peor pregunta para arrancar —
-- todavía no sabe si le sirve y ya le estás pidiendo que se comprometa.
--
-- El segundo es del negocio: el teléfono y a qué se dedica se preguntaban en
-- el panel, o sea NUNCA, porque había que preguntárselo por WhatsApp uno por
-- uno. Se pregunta en el registro o no se sabe.
--
-- La ficha la escribe `crear_empresa`, no la persona. La tabla sigue sin
-- permisos de escritura para nadie: se llena una vez, por esta función, y
-- después solo la administración de Orden la puede tocar. Alguien registrando
-- su negocio no tiene por qué poder editar la ficha de otro.

create or replace function public.crear_empresa(
  p_nombre text,
  p_moneda text default 'PYG',
  p_nombre_usuario text default null,
  p_zona text default 'America/Asuncion',
  p_tipo_cuenta text default 'emprendedor',
  p_rubro text default 'comercio',
  p_como_nos_conocio text default '',
  p_telefono text default '',
  p_se_dedica text default ''
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_id uuid;
  v_codigo text;
  v_intentos int := 0;
  v_fin timestamptz;
  v_tipo text;
  v_rubro text;
  v_contacto text;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  if char_length(trim(coalesce(p_nombre, ''))) < 2 then
    raise exception 'El nombre del negocio es muy corto.' using errcode = '22023';
  end if;

  v_tipo := case when p_tipo_cuenta = 'personal' then 'personal' else 'emprendedor' end;
  v_rubro := case
    when v_tipo = 'personal' then 'comercio'
    when p_rubro in ('comercio', 'ganaderia', 'agricultura', 'servicios') then p_rubro
    else 'comercio' end;

  loop
    v_codigo := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
    exit when not exists (select 1 from public.empresa_accesos where codigo = v_codigo);
    v_intentos := v_intentos + 1;
    if v_intentos > 12 then
      raise exception 'No se pudo generar un código de acceso.' using errcode = '55000';
    end if;
  end loop;

  insert into public.empresas (
    nombre, moneda, creada_por, zona_horaria, tipo_cuenta, rubro, como_nos_conocio)
  values (trim(p_nombre), coalesce(p_moneda, 'PYG'), auth.uid(),
          coalesce(nullif(trim(p_zona), ''), 'America/Asuncion'), v_tipo, v_rubro,
          left(coalesce(p_como_nos_conocio, ''), 80))
  returning id into v_id;

  v_contacto := nullif(trim(coalesce(p_nombre_usuario, '')), '');

  insert into public.miembros (empresa_id, user_id, nombre, rol)
  values (v_id, auth.uid(), coalesce(v_contacto, 'Propietario'), 'propietario');

  insert into public.empresa_accesos (empresa_id, codigo) values (v_id, v_codigo);

  -- La ficha solo se crea si contestó algo. Una fila con los tres campos
  -- vacíos no es un dato, es ruido en la lista de clientes.
  if v_contacto is not null
     or nullif(trim(coalesce(p_telefono, '')), '') is not null
     or nullif(trim(coalesce(p_se_dedica, '')), '') is not null then
    insert into public.ficha_cliente (empresa_id, contacto, telefono, se_dedica, updated_at)
    values (v_id,
            left(coalesce(v_contacto, ''), 120),
            left(regexp_replace(coalesce(p_telefono, ''), '[^0-9+]', '', 'g'), 40),
            left(coalesce(trim(p_se_dedica), ''), 200),
            now())
    on conflict (empresa_id) do nothing;
  end if;

  v_fin := now() + make_interval(days => public.dias_de_prueba(v_tipo));
  insert into public.suscripciones (empresa_id, plan, estado, periodo_inicio, periodo_fin, prueba_fin)
  values (v_id, 'pro', 'prueba', now(), v_fin, v_fin);

  perform set_config('orden.suscripcion_confiable', '1', true);
  update public.empresas set plan = 'pro' where id = v_id;
  perform set_config('orden.suscripcion_confiable', '0', true);

  return v_id;
end $fn$;

drop function if exists public.crear_empresa(text, text, text, text, text, text, text);

revoke all on function public.crear_empresa(text, text, text, text, text, text, text, text, text)
  from public, anon;
grant execute on function public.crear_empresa(text, text, text, text, text, text, text, text, text)
  to authenticated;


-- ############################################################
-- ##  024_cuenta_personal.sql
-- ############################################################

-- ORDEN · Migración 024 · La cuenta personal deja de ser un comercio disfrazado
--
-- Hasta acá, "personal" solo quitaba pantallas: no había Vender, ni Productos,
-- ni Reto. Pero por debajo seguía siendo una cuenta de comercio, y eso se
-- filtraba por dos agujeros que nadie había mirado:
--
--   · EL CIERRE DEL DÍA SEGUÍA AHÍ. Esa pantalla se oculta por RUBRO, y a
--     toda cuenta personal se le guarda rubro 'comercio' porque una persona
--     no tiene rubro. O sea que el filtro nunca se le aplicó. Alguien que
--     lleva su sueldo estaba viendo «cuánto ganaste hoy», que para él no
--     significa nada: su plata no se mide por día.
--
--   · LAS CATEGORÍAS ERAN LAS DE UN ALMACÉN. Mercadería, Publicidad,
--     Sueldos («empleados, jornales»), Impuestos. Ninguna de Comida, Salud,
--     Ropa o Cuidado personal. La IA venía clasificando el gasto de una
--     persona con los casilleros de un negocio.
--
-- Lo segundo importa más de lo que parece: el presupuesto que se agrega en
-- esta misma migración se arma POR CATEGORÍA. Con las categorías de un
-- comercio, toda la organización quedaría construida sobre casilleros
-- equivocados.
--
-- Y se agrega lo que hacía falta para que la cuenta personal sirva de verdad:
-- ingresos que se repiten, un plan de en qué se va la plata, y un ciclo que
-- va de cobro a cobro en vez de día a día.

-- ============================================================
-- 1. LA PUERTA: LAS DOS PREGUNTAS AHORA SABEN QUÉ TIPO DE CUENTA ES
--
--    Las dos funciones pasan a recibir el tipo de cuenta. Se REEMPLAZAN las
--    versiones de un solo argumento en vez de convivir con ellas: dos
--    funciones contestando la misma pregunta es exactamente cómo se llega a
--    que la pantalla diga una cosa y la tarea de la noche otra.
-- ============================================================

drop function if exists public.categorias_de_rubro(text);

create or replace function public.categorias_de_rubro(
  p_rubro text,
  p_tipo_cuenta text default 'emprendedor'
)
returns jsonb language sql immutable set search_path = public as $fn$
  select case
    when coalesce(p_tipo_cuenta, 'emprendedor') = 'personal' then jsonb_build_array(
      jsonb_build_object('nombre','Comida','pistas','supermercado, almacén, verdulería, carnicería, despensa, panadería'),
      jsonb_build_object('nombre','Alquiler','pistas','alquiler, expensas, condominio'),
      jsonb_build_object('nombre','Servicios','pistas','luz, agua, internet, teléfono, cable, gas'),
      jsonb_build_object('nombre','Transporte','pistas','colectivo, nafta, combustible, pasaje, taxi, uber, peaje'),
      jsonb_build_object('nombre','Salud','pistas','farmacia, remedios, médico, dentista, seguro médico, análisis'),
      jsonb_build_object('nombre','Educación','pistas','colegio, cuota, universidad, útiles, curso, libros'),
      jsonb_build_object('nombre','Ropa','pistas','ropa, calzado, zapatillas, campera'),
      jsonb_build_object('nombre','Cuidado personal','pistas','peluquería, uñas, barbería, cosmética, gimnasio, perfume'),
      jsonb_build_object('nombre','Ocio','pistas','salida, restaurante, cine, streaming, viaje, cerveza, cumpleaños'),
      jsonb_build_object('nombre','Hogar','pistas','limpieza, muebles, arreglos, electrodomésticos, ferretería'),
      jsonb_build_object('nombre','Cuotas y deudas','pistas','tarjeta, préstamo, cuota, financiera'),
      jsonb_build_object('nombre','Otros','pistas',''))

    when coalesce(p_rubro, 'comercio') = 'ganaderia' then jsonb_build_array(
      jsonb_build_object('nombre','Alimentación','pistas','maíz, balanceado, ración, fardos, sal, pasto'),
      jsonb_build_object('nombre','Sanidad','pistas','vacunas, antiparasitarios, veterinario, remedios'),
      jsonb_build_object('nombre','Personal','pistas','peón, capataz, jornales, sueldos'),
      jsonb_build_object('nombre','Combustible','pistas','gasoil, nafta'),
      jsonb_build_object('nombre','Arrendamiento','pistas','alquiler de campo, pastaje'),
      jsonb_build_object('nombre','Fletes','pistas','transporte de hacienda, camión jaula'),
      jsonb_build_object('nombre','Mantenimiento','pistas','alambrado, aguadas, maquinaria, herramientas'),
      jsonb_build_object('nombre','Impuestos','pistas',''),
      jsonb_build_object('nombre','Otros','pistas',''))

    when coalesce(p_rubro, 'comercio') = 'agricultura' then jsonb_build_array(
      jsonb_build_object('nombre','Semilla','pistas','semilla, plantines'),
      jsonb_build_object('nombre','Fertilizante','pistas','urea, fosfato, abono'),
      jsonb_build_object('nombre','Agroquímicos','pistas','herbicida, fungicida, insecticida'),
      jsonb_build_object('nombre','Combustible','pistas','gasoil, nafta'),
      jsonb_build_object('nombre','Cosecha','pistas','cosechadora, trilla, secado'),
      jsonb_build_object('nombre','Fletes','pistas','transporte de granos'),
      jsonb_build_object('nombre','Arrendamiento','pistas','alquiler de campo'),
      jsonb_build_object('nombre','Personal','pistas','jornales, tractorista, peón'),
      jsonb_build_object('nombre','Otros','pistas',''))

    when coalesce(p_rubro, 'comercio') = 'servicios' then jsonb_build_array(
      jsonb_build_object('nombre','Materiales','pistas','cemento, arena, cables, pintura, insumos'),
      jsonb_build_object('nombre','Repuestos','pistas','piezas, filtros, aceite'),
      jsonb_build_object('nombre','Herramientas','pistas',''),
      jsonb_build_object('nombre','Combustible','pistas','gasoil, nafta'),
      jsonb_build_object('nombre','Personal','pistas','ayudante, jornales, sueldos'),
      jsonb_build_object('nombre','Transporte','pistas','flete, viaje, delivery'),
      jsonb_build_object('nombre','Impuestos','pistas',''),
      jsonb_build_object('nombre','Otros','pistas',''))

    else jsonb_build_array(
      jsonb_build_object('nombre','Mercadería','pistas','lo que comprás para revender'),
      jsonb_build_object('nombre','Transporte','pistas','combustible, flete, delivery'),
      jsonb_build_object('nombre','Comida','pistas',''),
      jsonb_build_object('nombre','Publicidad','pistas',''),
      jsonb_build_object('nombre','Servicios','pistas','luz, agua, internet, teléfono'),
      jsonb_build_object('nombre','Alquiler','pistas',''),
      jsonb_build_object('nombre','Sueldos','pistas','empleados, jornales'),
      jsonb_build_object('nombre','Impuestos','pistas',''),
      jsonb_build_object('nombre','Otros','pistas',''))
  end;
$fn$;

grant execute on function public.categorias_de_rubro(text, text) to anon, authenticated;

-- ------------------------------------------------------------
-- ¿ESTA CUENTA CIERRA EL DÍA?
--
-- Una persona con sueldo no cierra el día por el mismo motivo que un
-- ganadero no lo cierra: el día no es su ciclo. El del ganadero es el
-- novillo; el de alguien con sueldo va de cobro a cobro.
-- ------------------------------------------------------------
drop function if exists public.rubro_cierra_el_dia(text);

create or replace function public.rubro_cierra_el_dia(
  p_rubro text,
  p_tipo_cuenta text default 'emprendedor'
)
returns boolean language sql immutable set search_path = public as $fn$
  select coalesce(p_tipo_cuenta, 'emprendedor') <> 'personal'
     and coalesce(p_rubro, 'comercio') in ('comercio', 'servicios');
$fn$;

grant execute on function public.rubro_cierra_el_dia(text, text) to anon, authenticated;

-- ------------------------------------------------------------
-- El recordatorio de la noche, con la misma firma y la misma forma de
-- respuesta que en la 008 y la 021. Lo único que cambia es que ahora la
-- cuenta personal tampoco recibe el «no cargaste nada hoy».
-- ------------------------------------------------------------
create or replace function public.empresas_sin_cargar_hoy(p_racha_minima integer default 2)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_res jsonb;
begin
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'empresa_id', e.id,
      'nombre',     e.nombre,
      'zona',       e.zona_horaria,
      'racha',      r.largo
    ) as x
    from public.empresas e
    join lateral (
      with dias as (
        select distinct m.fecha from public.movimientos m
        where m.empresa_id = e.id and m.estado = 'activo'
          and m.fecha <= (now() at time zone e.zona_horaria)::date
      ),
      numeradas as (
        select fecha, (fecha - (row_number() over (order by fecha))::int) as isla from dias
      ),
      rachas as (
        select count(*)::int as largo, max(fecha) as hasta from numeradas group by isla
      )
      select largo, hasta from rachas order by hasta desc limit 1
    ) r on true
    where public.rubro_cierra_el_dia(e.rubro, e.tipo_cuenta)
      and r.hasta = (now() at time zone e.zona_horaria)::date - 1
      and r.largo >= greatest(p_racha_minima, 1)
  ) s;

  return v_res;
end $fn$;

revoke all on function public.empresas_sin_cargar_hoy(integer) from public, anon, authenticated;
grant execute on function public.empresas_sin_cargar_hoy(integer) to service_role;

-- ============================================================
-- 2. INGRESOS FIJOS
--
--    No se llama «sueldo» a propósito. Mucha gente tiene más de una entrada
--    —sueldo, changas, el alquiler de una pieza— y un comisionista no tiene
--    sueldo fijo pero sí ingresos que se repiten. Un solo concepto los cubre
--    a todos; una casilla llamada «salario» dejaría afuera a la mitad.
--
--    Esto NO crea movimientos. Es lo que la persona ESPERA cobrar, no lo que
--    cobró. La plata entra cuando la carga, como cualquier otro ingreso. Si
--    esta tabla generara movimientos sola, el sistema mostraría plata que
--    todavía no existe — que es la única mentira que un sistema de plata no
--    se puede permitir.
-- ============================================================
create table if not exists public.ingresos_fijos (
  id          uuid primary key default gen_random_uuid(),
  empresa_id  uuid not null references public.empresas (id) on delete cascade,
  nombre      text not null check (char_length(trim(nombre)) between 1 and 60),
  importe     numeric(14,2) not null check (importe > 0),
  -- Qué día del mes entra. Define el ciclo: para alguien con sueldo, el mes
  -- útil no va del 1 al 30, va de cobro a cobro.
  dia_del_mes smallint not null default 1 check (dia_del_mes between 1 and 31),
  -- Cuál manda para definir el ciclo, si hay varios.
  principal   boolean not null default false,
  activo      boolean not null default true,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create index if not exists ingresos_fijos_empresa_idx
  on public.ingresos_fijos (empresa_id) where activo;

-- Un solo principal por cuenta: si hubiera dos, el ciclo dependería del
-- orden en que se leyeran las filas.
create unique index if not exists ingresos_fijos_un_principal
  on public.ingresos_fijos (empresa_id) where principal and activo;

-- ============================================================
-- 3. EL PLAN: EN QUÉ SE VA A IR LA PLATA
--
--    Un número por categoría, que vale todos los meses. No se guarda una
--    copia por mes a propósito: obligaría a rearmar el plan cada treinta
--    días, y un plan que hay que rehacer es un plan que se abandona.
--
--    La comparación contra la realidad sale gratis: cada gasto ya se guarda
--    con su categoría desde el día uno.
-- ============================================================
create table if not exists public.presupuesto (
  empresa_id uuid not null references public.empresas (id) on delete cascade,
  categoria  text not null check (char_length(trim(categoria)) between 1 and 40),
  importe    numeric(14,2) not null check (importe >= 0),
  updated_at timestamptz not null default now(),
  primary key (empresa_id, categoria)
);

-- ------------------------------------------------------------
-- Permisos de las dos tablas.
--
-- Se lee con `es_admin`, no con `es_miembro`. Cuánto cobra alguien y cómo
-- reparte su plata es del mismo orden que sus deudas y sus costos: un
-- vendedor no lo ve nunca. Hoy una cuenta personal no tiene vendedores, pero
-- la tabla es genérica y el día que un comercio use el presupuesto la regla
-- ya tiene que estar puesta.
-- ------------------------------------------------------------
alter table public.ingresos_fijos enable row level security;
alter table public.presupuesto    enable row level security;

drop policy if exists ingresos_fijos_select on public.ingresos_fijos;
create policy ingresos_fijos_select on public.ingresos_fijos
  for select to authenticated using (public.es_admin(empresa_id));

drop policy if exists presupuesto_select on public.presupuesto;
create policy presupuesto_select on public.presupuesto
  for select to authenticated using (public.es_admin(empresa_id));

revoke all on public.ingresos_fijos from anon, authenticated;
revoke all on public.presupuesto    from anon, authenticated;
grant select on public.ingresos_fijos to authenticated;
grant select on public.presupuesto    to authenticated;

-- La cuenta vencida queda en solo lectura, igual que todo lo demás. El
-- DELETE sigue libre: nadie tiene que pagar para poder irse.
do $$
declare v_tabla text;
begin
  foreach v_tabla in array array['ingresos_fijos', 'presupuesto'] loop
    execute format('drop trigger if exists %I on public.%I',
                   'cuenta_activa_' || v_tabla, v_tabla);
    execute format(
      'create trigger %I before insert or update on public.%I '
      || 'for each row execute function public.exigir_cuenta_activa()',
      'cuenta_activa_' || v_tabla, v_tabla);
  end loop;
end $$;

-- ============================================================
-- 4. ESCRIBIR: SIEMPRE POR LA PUERTA OFICIAL
-- ============================================================
create or replace function public.guardar_ingreso_fijo(
  p_empresa   uuid,
  p_nombre    text,
  p_importe   numeric,
  p_dia       integer default 1,
  p_principal boolean default false,
  p_id        uuid default null
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare v_id uuid;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar esto.' using errcode = '42501';
  end if;

  if char_length(trim(coalesce(p_nombre, ''))) = 0 then
    raise exception 'Ponele un nombre, para saber qué es cuando entre.' using errcode = '22023';
  end if;

  if coalesce(p_importe, 0) <= 0 then
    raise exception 'El monto tiene que ser mayor que cero.' using errcode = '22023';
  end if;

  -- Si este pasa a ser el principal, el anterior deja de serlo. Se hace
  -- ANTES de escribir, porque el índice único no admite dos.
  if coalesce(p_principal, false) then
    update public.ingresos_fijos
    set principal = false, updated_at = now()
    where empresa_id = p_empresa and principal
      and (p_id is null or id <> p_id);
  end if;

  if p_id is null then
    insert into public.ingresos_fijos (empresa_id, nombre, importe, dia_del_mes, principal)
    values (p_empresa, trim(p_nombre), p_importe,
            least(greatest(coalesce(p_dia, 1), 1), 31), coalesce(p_principal, false))
    returning id into v_id;
  else
    update public.ingresos_fijos
    set nombre = trim(p_nombre), importe = p_importe,
        dia_del_mes = least(greatest(coalesce(p_dia, 1), 1), 31),
        principal = coalesce(p_principal, false), updated_at = now()
    where id = p_id and empresa_id = p_empresa
    returning id into v_id;

    if v_id is null then
      raise exception 'Ese ingreso no existe en esta cuenta.' using errcode = 'P0002';
    end if;
  end if;

  return v_id;
end $fn$;

revoke all on function public.guardar_ingreso_fijo(uuid, text, numeric, integer, boolean, uuid)
  from public, anon;
grant execute on function public.guardar_ingreso_fijo(uuid, text, numeric, integer, boolean, uuid)
  to authenticated;

create or replace function public.borrar_ingreso_fijo(p_empresa uuid, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar esto.' using errcode = '42501';
  end if;

  delete from public.ingresos_fijos where id = p_id and empresa_id = p_empresa;
  if not found then
    raise exception 'Ese ingreso no existe en esta cuenta.' using errcode = 'P0002';
  end if;

  return jsonb_build_object('borrado', true);
end $fn$;

revoke all on function public.borrar_ingreso_fijo(uuid, uuid) from public, anon;
grant execute on function public.borrar_ingreso_fijo(uuid, uuid) to authenticated;

-- Poner en cero es sacar la categoría del plan. Sin esto haría falta un
-- segundo botón de borrar para algo que la persona piensa como «ya no le
-- pongo número a esto».
create or replace function public.guardar_presupuesto(
  p_empresa   uuid,
  p_categoria text,
  p_importe   numeric
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar esto.' using errcode = '42501';
  end if;

  if char_length(trim(coalesce(p_categoria, ''))) = 0 then
    raise exception 'Falta la categoría.' using errcode = '22023';
  end if;

  if coalesce(p_importe, 0) <= 0 then
    delete from public.presupuesto
    where empresa_id = p_empresa and categoria = trim(p_categoria);
    return jsonb_build_object('quitada', true);
  end if;

  insert into public.presupuesto (empresa_id, categoria, importe, updated_at)
  values (p_empresa, trim(p_categoria), p_importe, now())
  on conflict (empresa_id, categoria) do update
    set importe = excluded.importe, updated_at = now();

  return jsonb_build_object('guardado', true);
end $fn$;

revoke all on function public.guardar_presupuesto(uuid, text, numeric) from public, anon;
grant execute on function public.guardar_presupuesto(uuid, text, numeric) to authenticated;

-- ============================================================
-- 5. EL CICLO: DE COBRO A COBRO
--
--    Para alguien con sueldo el mes útil no empieza el 1. Empieza el día que
--    cobra y termina el día antes del próximo cobro. Esa es la pregunta que
--    de verdad le quita el sueño: es 20, ¿llego al 30?
-- ============================================================

-- El día de cobro de un mes dado, recortado si el mes es más corto: quien
-- cobra el 31 en febrero cobra el 28.
create or replace function public.fecha_de_cobro(p_mes date, p_dia integer)
returns date language sql immutable set search_path = public as $fn$
  select (date_trunc('month', p_mes)
          + (least(
               greatest(coalesce(p_dia, 1), 1),
               extract(day from (date_trunc('month', p_mes) + interval '1 month - 1 day'))::int
             ) - 1) * interval '1 day')::date;
$fn$;

-- Revocar ANTES de otorgar: `anon` hereda de PUBLIC, así que un grant
-- suelto la deja abierta aunque nunca se la haya nombrado.
revoke all on function public.fecha_de_cobro(date, integer) from public, anon;
grant execute on function public.fecha_de_cobro(date, integer) to authenticated;

create or replace function public.ciclo_personal(p_empresa uuid)
returns table (desde date, hasta date, dia_cobro integer)
language plpgsql stable security definer set search_path = public as $fn$
declare
  v_zona   text;
  v_hoy    date;
  v_dia    integer;
  v_inicio date;
begin
  select zona_horaria into v_zona from public.empresas where id = p_empresa;
  v_hoy := (now() at time zone coalesce(v_zona, 'America/Asuncion'))::date;

  -- Manda el ingreso marcado como principal; si no hay, el más grande. Sin
  -- ningún ingreso fijo cargado, el ciclo es el mes corrido.
  select i.dia_del_mes into v_dia
  from public.ingresos_fijos i
  where i.empresa_id = p_empresa and i.activo
  order by i.principal desc, i.importe desc, i.created_at
  limit 1;

  v_dia := coalesce(v_dia, 1);

  v_inicio := public.fecha_de_cobro(v_hoy, v_dia);
  if v_hoy < v_inicio then
    v_inicio := public.fecha_de_cobro((v_hoy - interval '1 month')::date, v_dia);
  end if;

  desde     := v_inicio;
  hasta     := public.fecha_de_cobro((v_inicio + interval '1 month')::date, v_dia) - 1;
  dia_cobro := v_dia;
  return next;
end $fn$;

revoke all on function public.ciclo_personal(uuid) from public, anon;
grant execute on function public.ciclo_personal(uuid) to authenticated;

-- ============================================================
-- 6. LA PANTALLA, EN UNA SOLA LLAMADA
--
--    Contesta la única pregunta que importa: cuánto te queda y para cuántos
--    días. Todo lo demás de esta función es el detalle de cómo se llegó a
--    ese número.
--
--    `disponible` sale de plata REAL: lo que entró menos lo que salió, menos
--    las cuotas que todavía faltan pagar antes de que cierre el ciclo. No se
--    suma el sueldo esperado si todavía no entró — decirle a alguien que
--    tiene plata que no cobró es cómo se hace que deje de creerte.
-- ============================================================
create or replace function public.resumen_personal(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_c            record;
  v_zona         text;
  v_hoy          date;
  v_entro        numeric := 0;
  v_salio        numeric := 0;
  v_cuotas       numeric := 0;
  v_dias         integer;
  v_plan         jsonb;
  v_sin_planear  numeric := 0;
  v_fijos        jsonb;
  v_esperado     numeric := 0;
  v_hubo_ingreso boolean := false;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'No tenés acceso a esta cuenta.' using errcode = '42501';
  end if;

  select zona_horaria into v_zona from public.empresas where id = p_empresa;
  v_hoy := (now() at time zone coalesce(v_zona, 'America/Asuncion'))::date;

  select * into v_c from public.ciclo_personal(p_empresa);

  select
    coalesce(sum(m.monto) filter (where m.tipo in ('ingreso', 'venta')), 0),
    coalesce(sum(m.monto) filter (where m.tipo = 'gasto'), 0),
    bool_or(m.tipo in ('ingreso', 'venta'))
  into v_entro, v_salio, v_hubo_ingreso
  from public.movimientos m
  where m.empresa_id = p_empresa
    and m.estado = 'activo'
    and m.fecha between v_c.desde and v_c.hasta;

  -- Cuotas que todavía no se pagaron y vencen antes de que cierre el ciclo.
  -- Lo ya pagado no se cuenta acá: está en `v_salio` como gasto, y sumarlo
  -- dos veces le descontaría a la persona plata que ya descontó.
  select coalesce(sum(d.monto_cuota), 0) into v_cuotas
  from public.deudas d
  where d.empresa_id = p_empresa
    and d.activa and d.saldo > 0
    and d.monto_cuota is not null
    and d.vence_el between v_hoy and v_c.hasta;

  v_dias := greatest(1, (v_c.hasta - v_hoy) + 1);

  select
    coalesce(jsonb_agg(jsonb_build_object(
      'categoria', p.categoria,
      'planeado',  p.importe,
      'gastado',   coalesce(g.total, 0),
      'resta',     p.importe - coalesce(g.total, 0)
    ) order by p.categoria), '[]'::jsonb)
  into v_plan
  from public.presupuesto p
  left join lateral (
    select sum(m.monto) as total
    from public.movimientos m
    where m.empresa_id = p_empresa and m.estado = 'activo' and m.tipo = 'gasto'
      and m.categoria = p.categoria
      and m.fecha between v_c.desde and v_c.hasta
  ) g on true
  where p.empresa_id = p_empresa;

  -- Lo que se gastó fuera del plan. Sin este número el plan miente por
  -- omisión: podés estar bien en las cinco categorías que anotaste y
  -- fundido igual.
  select coalesce(sum(m.monto), 0) into v_sin_planear
  from public.movimientos m
  where m.empresa_id = p_empresa and m.estado = 'activo' and m.tipo = 'gasto'
    and m.fecha between v_c.desde and v_c.hasta
    and not exists (
      select 1 from public.presupuesto p
      where p.empresa_id = p_empresa and p.categoria = m.categoria);

  select
    coalesce(jsonb_agg(jsonb_build_object(
      'id', i.id, 'nombre', i.nombre, 'importe', i.importe,
      'dia_del_mes', i.dia_del_mes, 'principal', i.principal
    ) order by i.principal desc, i.importe desc), '[]'::jsonb),
    coalesce(sum(i.importe), 0)
  into v_fijos, v_esperado
  from public.ingresos_fijos i
  where i.empresa_id = p_empresa and i.activo;

  return jsonb_build_object(
    'desde', v_c.desde,
    'hasta', v_c.hasta,
    'dia_cobro', v_c.dia_cobro,
    'dias_restantes', v_dias,
    'entro', v_entro,
    'salio', v_salio,
    'cuotas_por_vencer', v_cuotas,
    'disponible', v_entro - v_salio - v_cuotas,
    'por_dia', round((v_entro - v_salio - v_cuotas) / v_dias, 2),
    'plan', v_plan,
    'gastado_sin_planear', v_sin_planear,
    'ingresos_fijos', v_fijos,
    'esperado', v_esperado,
    -- Para poder preguntarle «¿ya cobraste?» en vez de mostrarle un cero
    -- sin explicación el día que arranca el ciclo.
    'cobro_pendiente', v_esperado > 0 and not coalesce(v_hubo_ingreso, false)
  );
end $fn$;

revoke all on function public.resumen_personal(uuid) from public, anon;
grant execute on function public.resumen_personal(uuid) to authenticated;


-- ############################################################
-- ##  025_gastos_fijos.sql
-- ############################################################

-- ORDEN · Migración 025 · Lo que se paga todos los meses
--
-- Faltaba la otra mitad. La 024 trajo lo que ENTRA todos los meses; esto es
-- lo que SALE sí o sí: el wifi, la línea del celular, el pasaje del bus, la
-- cuota del gimnasio.
--
-- Sin esto, el número de «te quedan» mentía por optimismo. El día que cobrás
-- te decía que tenías 1.850.000 disponibles cuando 500.000 ya estaban
-- comprometidos antes de que decidieras nada. Es el error más caro que puede
-- cometer un sistema de plata: hacerte creer que tenés más de lo que tenés.
--
-- CÓMO SE EVITA CONTAR DOS VECES
--
-- Un gasto fijo es algo que va a pasar, no algo que pasó. Cuando de verdad
-- pagás el wifi, lo cargás como cualquier gasto — y a partir de ahí ya no
-- puede seguir descontándose, o estaría restado dos veces.
--
-- La regla, por categoría:
--
--     pendiente = max(0, suma de los fijos − lo ya gastado en esa categoría)
--
-- Wifi 200.000 en «Servicios»: si todavía no gastaste nada en Servicios,
-- faltan 200.000. Si gastaste 150.000, faltan 50.000. Si gastaste 200.000 o
-- más, no falta nada.
--
-- No hace falta que nadie marque «ya lo pagué», que es justo lo que la gente
-- deja de hacer a la segunda semana. Y si tenés dos fijos en la misma
-- categoría —wifi y luz, los dos «Servicios»— se suman y se comparan juntos,
-- que es exactamente lo correcto.

create table if not exists public.gastos_fijos (
  id          uuid primary key default gen_random_uuid(),
  empresa_id  uuid not null references public.empresas (id) on delete cascade,
  nombre      text not null check (char_length(trim(nombre)) between 1 and 60),
  importe     numeric(14,2) not null check (importe > 0),
  -- En qué casillero cae. Es lo que permite saber si ya se pagó: se compara
  -- contra lo gastado en esta misma categoría durante el ciclo.
  categoria   text not null default 'Otros' check (char_length(trim(categoria)) between 1 and 40),
  -- Qué día vence. Puede ir vacío a propósito: el pasaje del bus se gasta
  -- todos los días, no tiene fecha. Obligar a inventar un día haría que el
  -- dato sea mentira.
  dia_del_mes smallint check (dia_del_mes is null or dia_del_mes between 1 and 31),
  -- Para escribir lo que no entra en un nombre de sesenta caracteres.
  notas       text not null default '',
  activo      boolean not null default true,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create index if not exists gastos_fijos_empresa_idx
  on public.gastos_fijos (empresa_id) where activo;

alter table public.gastos_fijos enable row level security;

drop policy if exists gastos_fijos_select on public.gastos_fijos;
create policy gastos_fijos_select on public.gastos_fijos
  for select to authenticated using (public.es_admin(empresa_id));

revoke all on public.gastos_fijos from anon, authenticated;
grant select on public.gastos_fijos to authenticated;

do $$ begin
  execute 'drop trigger if exists cuenta_activa_gastos_fijos on public.gastos_fijos';
  execute 'create trigger cuenta_activa_gastos_fijos before insert or update '
       || 'on public.gastos_fijos for each row execute function public.exigir_cuenta_activa()';
end $$;

create or replace function public.guardar_gasto_fijo(
  p_empresa   uuid,
  p_nombre    text,
  p_importe   numeric,
  p_categoria text default 'Otros',
  p_dia       integer default null,
  p_notas     text default '',
  p_id        uuid default null
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_id  uuid;
  v_dia smallint;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar esto.' using errcode = '42501';
  end if;

  if char_length(trim(coalesce(p_nombre, ''))) = 0 then
    raise exception 'Ponele un nombre, para reconocerlo cuando lo pagues.' using errcode = '22023';
  end if;

  if coalesce(p_importe, 0) <= 0 then
    raise exception 'El monto tiene que ser mayor que cero.' using errcode = '22023';
  end if;

  v_dia := case
    when p_dia is null then null
    else least(greatest(p_dia, 1), 31)::smallint end;

  if p_id is null then
    insert into public.gastos_fijos (empresa_id, nombre, importe, categoria, dia_del_mes, notas)
    values (p_empresa, trim(p_nombre), p_importe,
            coalesce(nullif(trim(p_categoria), ''), 'Otros'), v_dia,
            left(coalesce(p_notas, ''), 500))
    returning id into v_id;
  else
    update public.gastos_fijos
    set nombre = trim(p_nombre), importe = p_importe,
        categoria = coalesce(nullif(trim(p_categoria), ''), 'Otros'),
        dia_del_mes = v_dia, notas = left(coalesce(p_notas, ''), 500),
        updated_at = now()
    where id = p_id and empresa_id = p_empresa
    returning id into v_id;

    if v_id is null then
      raise exception 'Ese gasto fijo no existe en esta cuenta.' using errcode = 'P0002';
    end if;
  end if;

  return v_id;
end $fn$;

revoke all on function public.guardar_gasto_fijo(uuid, text, numeric, text, integer, text, uuid)
  from public, anon;
grant execute on function public.guardar_gasto_fijo(uuid, text, numeric, text, integer, text, uuid)
  to authenticated;

create or replace function public.borrar_gasto_fijo(p_empresa uuid, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar esto.' using errcode = '42501';
  end if;

  delete from public.gastos_fijos where id = p_id and empresa_id = p_empresa;
  if not found then
    raise exception 'Ese gasto fijo no existe en esta cuenta.' using errcode = 'P0002';
  end if;

  return jsonb_build_object('borrado', true);
end $fn$;

revoke all on function public.borrar_gasto_fijo(uuid, uuid) from public, anon;
grant execute on function public.borrar_gasto_fijo(uuid, uuid) to authenticated;

-- ------------------------------------------------------------
-- LO QUE SE REPITE, PARA QUE LA IA LO SEPA
--
-- Sin esto pasaba lo que tenía que pasar: alguien con el sueldo cargado
-- decía «ya cobré mi sueldo de este mes» y el sistema contestaba «no pude
-- sacar el monto del mensaje, escribilo vos». El monto estaba guardado en la
-- fila de al lado. Es lo mismo que ya se hace con las deudas: la IA no
-- adivina, se le da lo que la cuenta ya sabe.
--
-- Va con `es_admin` como todo lo demás de esta familia: un vendedor no tiene
-- por qué enterarse de cuánto cobra el dueño, ni siquiera de rebote por el
-- prompt de una captura.
-- ------------------------------------------------------------
create or replace function public.fijos_para_captura(p_empresa uuid)
returns jsonb language sql stable security definer set search_path = public as $fn$
  select case when public.es_admin(p_empresa) then coalesce((
    select jsonb_agg(x order by x->>'nombre') from (
      select jsonb_build_object(
        'clase', 'ingreso', 'nombre', i.nombre, 'importe', i.importe,
        'dia', i.dia_del_mes, 'categoria', 'Sueldo') as x
      from public.ingresos_fijos i
      where i.empresa_id = p_empresa and i.activo
      union all
      select jsonb_build_object(
        'clase', 'gasto', 'nombre', g.nombre, 'importe', g.importe,
        'dia', g.dia_del_mes, 'categoria', g.categoria) as x
      from public.gastos_fijos g
      where g.empresa_id = p_empresa and g.activo
    ) t), '[]'::jsonb)
  else '[]'::jsonb end;
$fn$;

revoke all on function public.fijos_para_captura(uuid) from public, anon;
grant execute on function public.fijos_para_captura(uuid) to authenticated;

-- ------------------------------------------------------------
-- EL RESUMEN, AHORA CON LO QUE FALTA PAGAR
--
-- Cambia una sola cosa en el número grande: `disponible` ahora también
-- descuenta los gastos fijos que todavía no se pagaron en este ciclo.
-- ------------------------------------------------------------
create or replace function public.resumen_personal(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_c            record;
  v_zona         text;
  v_hoy          date;
  v_entro        numeric := 0;
  v_salio        numeric := 0;
  v_cuotas       numeric := 0;
  v_fijos_falta  numeric := 0;
  v_dias         integer;
  v_plan         jsonb;
  v_sin_planear  numeric := 0;
  v_entradas     jsonb;
  v_salidas      jsonb;
  v_esperado     numeric := 0;
  v_fijo_mes     numeric := 0;
  v_hubo_ingreso boolean := false;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'No tenés acceso a esta cuenta.' using errcode = '42501';
  end if;

  select zona_horaria into v_zona from public.empresas where id = p_empresa;
  v_hoy := (now() at time zone coalesce(v_zona, 'America/Asuncion'))::date;

  select * into v_c from public.ciclo_personal(p_empresa);

  select
    coalesce(sum(m.monto) filter (where m.tipo in ('ingreso', 'venta')), 0),
    coalesce(sum(m.monto) filter (where m.tipo = 'gasto'), 0),
    bool_or(m.tipo in ('ingreso', 'venta'))
  into v_entro, v_salio, v_hubo_ingreso
  from public.movimientos m
  where m.empresa_id = p_empresa
    and m.estado = 'activo'
    and m.fecha between v_c.desde and v_c.hasta;

  select coalesce(sum(d.monto_cuota), 0) into v_cuotas
  from public.deudas d
  where d.empresa_id = p_empresa
    and d.activa and d.saldo > 0
    and d.monto_cuota is not null
    and d.vence_el between v_hoy and v_c.hasta;

  -- Lo que falta pagar de los fijos, categoría por categoría. Ver el
  -- comentario de arriba sobre por qué se compara contra lo ya gastado.
  select coalesce(sum(greatest(0, f.total - coalesce(g.gastado, 0))), 0)
  into v_fijos_falta
  from (
    select categoria, sum(importe) as total
    from public.gastos_fijos
    where empresa_id = p_empresa and activo
    group by categoria
  ) f
  left join lateral (
    select sum(m.monto) as gastado
    from public.movimientos m
    where m.empresa_id = p_empresa and m.estado = 'activo' and m.tipo = 'gasto'
      and m.categoria = f.categoria
      and m.fecha between v_c.desde and v_c.hasta
  ) g on true;

  v_dias := greatest(1, (v_c.hasta - v_hoy) + 1);

  select
    coalesce(jsonb_agg(jsonb_build_object(
      'categoria', p.categoria,
      'planeado',  p.importe,
      'gastado',   coalesce(g.total, 0),
      'resta',     p.importe - coalesce(g.total, 0)
    ) order by p.categoria), '[]'::jsonb)
  into v_plan
  from public.presupuesto p
  left join lateral (
    select sum(m.monto) as total
    from public.movimientos m
    where m.empresa_id = p_empresa and m.estado = 'activo' and m.tipo = 'gasto'
      and m.categoria = p.categoria
      and m.fecha between v_c.desde and v_c.hasta
  ) g on true
  where p.empresa_id = p_empresa;

  select coalesce(sum(m.monto), 0) into v_sin_planear
  from public.movimientos m
  where m.empresa_id = p_empresa and m.estado = 'activo' and m.tipo = 'gasto'
    and m.fecha between v_c.desde and v_c.hasta
    and not exists (
      select 1 from public.presupuesto p
      where p.empresa_id = p_empresa and p.categoria = m.categoria);

  select
    coalesce(jsonb_agg(jsonb_build_object(
      'id', i.id, 'nombre', i.nombre, 'importe', i.importe,
      'dia_del_mes', i.dia_del_mes, 'principal', i.principal
    ) order by i.principal desc, i.importe desc), '[]'::jsonb),
    coalesce(sum(i.importe), 0)
  into v_entradas, v_esperado
  from public.ingresos_fijos i
  where i.empresa_id = p_empresa and i.activo;

  select
    coalesce(jsonb_agg(jsonb_build_object(
      'id', g.id, 'nombre', g.nombre, 'importe', g.importe,
      'categoria', g.categoria, 'dia_del_mes', g.dia_del_mes, 'notas', g.notas
    ) order by g.dia_del_mes nulls last, g.importe desc), '[]'::jsonb),
    coalesce(sum(g.importe), 0)
  into v_salidas, v_fijo_mes
  from public.gastos_fijos g
  where g.empresa_id = p_empresa and g.activo;

  return jsonb_build_object(
    'desde', v_c.desde,
    'hasta', v_c.hasta,
    'dia_cobro', v_c.dia_cobro,
    'dias_restantes', v_dias,
    'entro', v_entro,
    'salio', v_salio,
    'cuotas_por_vencer', v_cuotas,
    'fijos_por_pagar', v_fijos_falta,
    'disponible', v_entro - v_salio - v_cuotas - v_fijos_falta,
    'por_dia', round((v_entro - v_salio - v_cuotas - v_fijos_falta) / v_dias, 2),
    'plan', v_plan,
    'gastado_sin_planear', v_sin_planear,
    'ingresos_fijos', v_entradas,
    'gastos_fijos', v_salidas,
    'esperado', v_esperado,
    'fijo_mensual', v_fijo_mes,
    'cobro_pendiente', v_esperado > 0 and not coalesce(v_hubo_ingreso, false)
  );
end $fn$;

revoke all on function public.resumen_personal(uuid) from public, anon;
grant execute on function public.resumen_personal(uuid) to authenticated;


-- ############################################################
-- ##  026_ahorros_y_entradas.sql
-- ############################################################

-- ORDEN · Migración 026 · Ahorros, y de dónde vino la plata
--
-- Le faltaban dos cosas a la cuenta personal, y una de ellas es la que más
-- define si alguien siente que le va bien: el ahorro.
--
-- POR QUÉ EL AHORRO NO ES UN GASTO
--
-- Era tentador resolverlo con una categoría de gasto llamada «Ahorro»: no
-- costaba nada y ya quedaba descontado de lo disponible. Pero sería mentira
-- en el peor lugar posible. Guardar plata no es gastarla — no se fue a
-- ningún lado, la tenés. Si el reporte de fin de año dijera que gastaste
-- cuatro millones en «Ahorro», la persona vería su mejor mes como el peor.
--
-- Así que el ahorro es una MUDANZA, no una salida: la plata pasa del bolsillo
-- de gastar al bolsillo de guardar. Y por eso sí baja lo disponible —no la
-- podés gastar dos veces— pero no cuenta como gasto en ningún reporte. Un
-- retiro hace el camino inverso y vuelve a estar disponible.
--
-- LO SEGUNDO: DE DÓNDE VINO
--
-- Hasta acá todo ingreso caía en una bolsa sin nombre. Para una persona con
-- sueldo eso pierde la única distinción que le importa: qué parte de lo que
-- entró es su sueldo y qué parte fue extra —horas extra, una changa, haber
-- vendido algo que no usaba—. Es la diferencia entre «gano bien» y «este mes
-- zafé».

-- ============================================================
-- 1. LOS FONDOS DE AHORRO
-- ============================================================
create table if not exists public.ahorros (
  id         uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas (id) on delete cascade,
  nombre     text not null check (char_length(trim(nombre)) between 1 and 60),
  -- Cuánto quiere juntar. Opcional: mucha gente ahorra sin una meta puesta,
  -- y exigirla sería inventarle un número para poder empezar.
  meta       numeric(14,2) check (meta is null or meta > 0),
  activo     boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists ahorros_empresa_idx on public.ahorros (empresa_id) where activo;

-- Cada vez que entra o sale plata del fondo. No se guarda un saldo: se
-- calcula sumando. Un saldo guardado se desincroniza el día que algo falla
-- en el medio, y entonces el número que la persona mira deja de ser cierto.
create table if not exists public.movimientos_ahorro (
  id         uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas (id) on delete cascade,
  ahorro_id  uuid not null references public.ahorros (id) on delete cascade,
  tipo       text not null check (tipo in ('aporte', 'retiro')),
  monto      numeric(14,2) not null check (monto > 0),
  fecha      date not null default (now() at time zone 'America/Asuncion')::date,
  nota       text not null default '',
  creado_por uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now()
);

create index if not exists movimientos_ahorro_idx
  on public.movimientos_ahorro (empresa_id, fecha desc);
create index if not exists movimientos_ahorro_fondo_idx
  on public.movimientos_ahorro (ahorro_id);

alter table public.ahorros            enable row level security;
alter table public.movimientos_ahorro enable row level security;

drop policy if exists ahorros_select on public.ahorros;
create policy ahorros_select on public.ahorros
  for select to authenticated using (public.es_admin(empresa_id));

drop policy if exists movimientos_ahorro_select on public.movimientos_ahorro;
create policy movimientos_ahorro_select on public.movimientos_ahorro
  for select to authenticated using (public.es_admin(empresa_id));

revoke all on public.ahorros            from anon, authenticated;
revoke all on public.movimientos_ahorro from anon, authenticated;
grant select on public.ahorros            to authenticated;
grant select on public.movimientos_ahorro to authenticated;

do $$
declare v_tabla text;
begin
  foreach v_tabla in array array['ahorros', 'movimientos_ahorro'] loop
    execute format('drop trigger if exists %I on public.%I',
                   'cuenta_activa_' || v_tabla, v_tabla);
    execute format(
      'create trigger %I before insert or update on public.%I '
      || 'for each row execute function public.exigir_cuenta_activa()',
      'cuenta_activa_' || v_tabla, v_tabla);
  end loop;
end $$;

create or replace function public.saldo_ahorro(p_ahorro uuid)
returns numeric language sql stable security definer set search_path = public as $fn$
  select coalesce(sum(case when tipo = 'aporte' then monto else -monto end), 0)
  from public.movimientos_ahorro where ahorro_id = p_ahorro;
$fn$;

revoke all on function public.saldo_ahorro(uuid) from public, anon;
grant execute on function public.saldo_ahorro(uuid) to authenticated;

create or replace function public.guardar_ahorro(
  p_empresa uuid,
  p_nombre  text,
  p_meta    numeric default null,
  p_id      uuid default null
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare v_id uuid;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar esto.' using errcode = '42501';
  end if;

  if char_length(trim(coalesce(p_nombre, ''))) = 0 then
    raise exception 'Ponele un nombre, para saber para qué estás juntando.' using errcode = '22023';
  end if;

  if p_meta is not null and p_meta <= 0 then
    raise exception 'La meta tiene que ser mayor que cero, o dejala vacía.' using errcode = '22023';
  end if;

  if p_id is null then
    insert into public.ahorros (empresa_id, nombre, meta)
    values (p_empresa, trim(p_nombre), p_meta)
    returning id into v_id;
  else
    update public.ahorros
    set nombre = trim(p_nombre), meta = p_meta, updated_at = now()
    where id = p_id and empresa_id = p_empresa
    returning id into v_id;

    if v_id is null then
      raise exception 'Ese fondo no existe en esta cuenta.' using errcode = 'P0002';
    end if;
  end if;

  return v_id;
end $fn$;

revoke all on function public.guardar_ahorro(uuid, text, numeric, uuid) from public, anon;
grant execute on function public.guardar_ahorro(uuid, text, numeric, uuid) to authenticated;

-- Un fondo con plata adentro no se borra de un toque. No es burocracia: si
-- se borrara, el registro de esa plata desaparecería y el historial diría que
-- nunca existió. Primero se retira, que además deja el rastro de a dónde fue.
create or replace function public.borrar_ahorro(p_empresa uuid, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare v_saldo numeric;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar esto.' using errcode = '42501';
  end if;

  select public.saldo_ahorro(p_id) into v_saldo
  from public.ahorros where id = p_id and empresa_id = p_empresa;

  if v_saldo is null then
    raise exception 'Ese fondo no existe en esta cuenta.' using errcode = 'P0002';
  end if;

  if v_saldo > 0 then
    raise exception 'Ese fondo todavía tiene plata. Retirala primero y después borralo.'
      using errcode = '22023';
  end if;

  delete from public.ahorros where id = p_id and empresa_id = p_empresa;
  return jsonb_build_object('borrado', true);
end $fn$;

revoke all on function public.borrar_ahorro(uuid, uuid) from public, anon;
grant execute on function public.borrar_ahorro(uuid, uuid) to authenticated;

create or replace function public.mover_ahorro(
  p_empresa uuid,
  p_ahorro  uuid,
  p_tipo    text,
  p_monto   numeric,
  p_fecha   date default null,
  p_nota    text default ''
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_saldo numeric;
  v_zona  text;
  v_id    uuid;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar esto.' using errcode = '42501';
  end if;

  if p_tipo not in ('aporte', 'retiro') then
    raise exception 'Solo se puede guardar o retirar.' using errcode = '22023';
  end if;

  if coalesce(p_monto, 0) <= 0 then
    raise exception 'El monto tiene que ser mayor que cero.' using errcode = '22023';
  end if;

  select public.saldo_ahorro(a.id) into v_saldo
  from public.ahorros a where a.id = p_ahorro and a.empresa_id = p_empresa;

  if v_saldo is null then
    raise exception 'Ese fondo no existe en esta cuenta.' using errcode = 'P0002';
  end if;

  -- No se puede sacar lo que no hay. Un saldo negativo no significa nada:
  -- nadie tiene menos que cero guardado en una lata.
  if p_tipo = 'retiro' and p_monto > v_saldo then
    raise exception 'Ese fondo tiene menos de lo que querés retirar.' using errcode = '22023';
  end if;

  select zona_horaria into v_zona from public.empresas where id = p_empresa;

  insert into public.movimientos_ahorro (empresa_id, ahorro_id, tipo, monto, fecha, nota, creado_por)
  values (p_empresa, p_ahorro, p_tipo, p_monto,
          coalesce(p_fecha, (now() at time zone coalesce(v_zona, 'America/Asuncion'))::date),
          left(coalesce(p_nota, ''), 200), auth.uid())
  returning id into v_id;

  return jsonb_build_object(
    'id', v_id,
    'saldo', v_saldo + case when p_tipo = 'aporte' then p_monto else -p_monto end);
end $fn$;

revoke all on function public.mover_ahorro(uuid, uuid, text, numeric, date, text) from public, anon;
grant execute on function public.mover_ahorro(uuid, uuid, text, numeric, date, text) to authenticated;

create or replace function public.borrar_movimiento_ahorro(p_empresa uuid, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar esto.' using errcode = '42501';
  end if;

  delete from public.movimientos_ahorro where id = p_id and empresa_id = p_empresa;
  if not found then
    raise exception 'Ese movimiento no existe en esta cuenta.' using errcode = 'P0002';
  end if;

  return jsonb_build_object('borrado', true);
end $fn$;

revoke all on function public.borrar_movimiento_ahorro(uuid, uuid) from public, anon;
grant execute on function public.borrar_movimiento_ahorro(uuid, uuid) to authenticated;

-- ============================================================
-- 2. DE DÓNDE VINO LA PLATA
--
--    Para un negocio, un ingreso es un ingreso. Para una persona con sueldo,
--    la distinción entre «esto es lo que gano todos los meses» y «esto fue
--    de una» es la más importante que hay: es la diferencia entre gano bien
--    y este mes zafé.
-- ============================================================
create or replace function public.categorias_de_ingreso(p_tipo_cuenta text default 'emprendedor')
returns jsonb language sql immutable set search_path = public as $fn$
  select case when coalesce(p_tipo_cuenta, 'emprendedor') = 'personal' then jsonb_build_array(
      jsonb_build_object('nombre','Sueldo','pistas','sueldo, salario, quincena, me pagaron el mes'),
      jsonb_build_object('nombre','Extra','pistas','horas extra, bonificación, comisión, aguinaldo, propina'),
      jsonb_build_object('nombre','Changa','pistas','trabajo aparte, freelance, un servicio suelto'),
      jsonb_build_object('nombre','Vendí algo','pistas','vendí, revendí, me compraron algo mío'),
      jsonb_build_object('nombre','Me devolvieron','pistas','devolución, reintegro, me pagaron lo que le presté'),
      jsonb_build_object('nombre','Regalo o ayuda','pistas','me regalaron, me ayudaron, me mandaron plata'),
      jsonb_build_object('nombre','Otros ingresos','pistas',''))
    else jsonb_build_array(
      jsonb_build_object('nombre','Ventas','pistas','lo que entra por vender'),
      jsonb_build_object('nombre','Aporte de capital','pistas','plata que puso el dueño'),
      jsonb_build_object('nombre','Devolución','pistas','reintegro, nota de crédito'),
      jsonb_build_object('nombre','Otros ingresos','pistas',''))
  end;
$fn$;

revoke all on function public.categorias_de_ingreso(text) from public, anon;
grant execute on function public.categorias_de_ingreso(text) to anon, authenticated;

-- ============================================================
-- 3. EL RESUMEN, CON EL AHORRO Y EL DESGLOSE
--
--    `disponible` ahora también descuenta lo que se guardó en este ciclo.
--    No porque se haya gastado —no se gastó— sino porque ya no está para
--    gastar. Un retiro va al revés y vuelve a sumar.
-- ============================================================
create or replace function public.resumen_personal(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_c            record;
  v_zona         text;
  v_hoy          date;
  v_entro        numeric := 0;
  v_salio        numeric := 0;
  v_cuotas       numeric := 0;
  v_fijos_falta  numeric := 0;
  v_ahorro_ciclo numeric := 0;
  v_ahorro_total numeric := 0;
  v_dias         integer;
  v_plan         jsonb;
  v_sin_planear  numeric := 0;
  v_entradas     jsonb;
  v_salidas      jsonb;
  v_fondos       jsonb;
  v_de_donde     jsonb;
  v_esperado     numeric := 0;
  v_fijo_mes     numeric := 0;
  v_hubo_ingreso boolean := false;
  v_disponible   numeric;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'No tenés acceso a esta cuenta.' using errcode = '42501';
  end if;

  select zona_horaria into v_zona from public.empresas where id = p_empresa;
  v_hoy := (now() at time zone coalesce(v_zona, 'America/Asuncion'))::date;

  select * into v_c from public.ciclo_personal(p_empresa);

  select
    coalesce(sum(m.monto) filter (where m.tipo in ('ingreso', 'venta')), 0),
    coalesce(sum(m.monto) filter (where m.tipo = 'gasto'), 0),
    bool_or(m.tipo in ('ingreso', 'venta'))
  into v_entro, v_salio, v_hubo_ingreso
  from public.movimientos m
  where m.empresa_id = p_empresa
    and m.estado = 'activo'
    and m.fecha between v_c.desde and v_c.hasta;

  select coalesce(sum(d.monto_cuota), 0) into v_cuotas
  from public.deudas d
  where d.empresa_id = p_empresa
    and d.activa and d.saldo > 0
    and d.monto_cuota is not null
    and d.vence_el between v_hoy and v_c.hasta;

  select coalesce(sum(greatest(0, f.total - coalesce(g.gastado, 0))), 0)
  into v_fijos_falta
  from (
    select categoria, sum(importe) as total
    from public.gastos_fijos
    where empresa_id = p_empresa and activo
    group by categoria
  ) f
  left join lateral (
    select sum(m.monto) as gastado
    from public.movimientos m
    where m.empresa_id = p_empresa and m.estado = 'activo' and m.tipo = 'gasto'
      and m.categoria = f.categoria
      and m.fecha between v_c.desde and v_c.hasta
  ) g on true;

  -- Lo guardado en ESTE ciclo, neto de retiros.
  select coalesce(sum(case when ma.tipo = 'aporte' then ma.monto else -ma.monto end), 0)
  into v_ahorro_ciclo
  from public.movimientos_ahorro ma
  where ma.empresa_id = p_empresa and ma.fecha between v_c.desde and v_c.hasta;

  -- Y lo acumulado de siempre, que es el número del que la gente se
  -- enorgullece.
  select coalesce(sum(case when ma.tipo = 'aporte' then ma.monto else -ma.monto end), 0)
  into v_ahorro_total
  from public.movimientos_ahorro ma
  where ma.empresa_id = p_empresa;

  v_dias := greatest(1, (v_c.hasta - v_hoy) + 1);
  v_disponible := v_entro - v_salio - v_cuotas - v_fijos_falta - v_ahorro_ciclo;

  select
    coalesce(jsonb_agg(jsonb_build_object(
      'categoria', p.categoria,
      'planeado',  p.importe,
      'gastado',   coalesce(g.total, 0),
      'resta',     p.importe - coalesce(g.total, 0)
    ) order by p.categoria), '[]'::jsonb)
  into v_plan
  from public.presupuesto p
  left join lateral (
    select sum(m.monto) as total
    from public.movimientos m
    where m.empresa_id = p_empresa and m.estado = 'activo' and m.tipo = 'gasto'
      and m.categoria = p.categoria
      and m.fecha between v_c.desde and v_c.hasta
  ) g on true
  where p.empresa_id = p_empresa;

  select coalesce(sum(m.monto), 0) into v_sin_planear
  from public.movimientos m
  where m.empresa_id = p_empresa and m.estado = 'activo' and m.tipo = 'gasto'
    and m.fecha between v_c.desde and v_c.hasta
    and not exists (
      select 1 from public.presupuesto p
      where p.empresa_id = p_empresa and p.categoria = m.categoria);

  select
    coalesce(jsonb_agg(jsonb_build_object(
      'id', i.id, 'nombre', i.nombre, 'importe', i.importe,
      'dia_del_mes', i.dia_del_mes, 'principal', i.principal
    ) order by i.principal desc, i.importe desc), '[]'::jsonb),
    coalesce(sum(i.importe), 0)
  into v_entradas, v_esperado
  from public.ingresos_fijos i
  where i.empresa_id = p_empresa and i.activo;

  select
    coalesce(jsonb_agg(jsonb_build_object(
      'id', g.id, 'nombre', g.nombre, 'importe', g.importe,
      'categoria', g.categoria, 'dia_del_mes', g.dia_del_mes, 'notas', g.notas
    ) order by g.dia_del_mes nulls last, g.importe desc), '[]'::jsonb),
    coalesce(sum(g.importe), 0)
  into v_salidas, v_fijo_mes
  from public.gastos_fijos g
  where g.empresa_id = p_empresa and g.activo;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', a.id, 'nombre', a.nombre, 'meta', a.meta,
    'saldo', public.saldo_ahorro(a.id)
  ) order by a.created_at), '[]'::jsonb)
  into v_fondos
  from public.ahorros a
  where a.empresa_id = p_empresa and a.activo;

  -- De dónde vino lo que entró en el ciclo.
  select coalesce(jsonb_agg(x order by (x->>'monto')::numeric desc), '[]'::jsonb)
  into v_de_donde
  from (
    select jsonb_build_object('categoria', m.categoria, 'monto', sum(m.monto)) as x
    from public.movimientos m
    where m.empresa_id = p_empresa and m.estado = 'activo'
      and m.tipo in ('ingreso', 'venta')
      and m.fecha between v_c.desde and v_c.hasta
    group by m.categoria
  ) t;

  return jsonb_build_object(
    'desde', v_c.desde,
    'hasta', v_c.hasta,
    'dia_cobro', v_c.dia_cobro,
    'dias_restantes', v_dias,
    'entro', v_entro,
    'salio', v_salio,
    'cuotas_por_vencer', v_cuotas,
    'fijos_por_pagar', v_fijos_falta,
    'ahorrado_en_el_ciclo', v_ahorro_ciclo,
    'ahorro_total', v_ahorro_total,
    'disponible', v_disponible,
    'por_dia', round(v_disponible / v_dias, 2),
    'plan', v_plan,
    'gastado_sin_planear', v_sin_planear,
    'ingresos_fijos', v_entradas,
    'gastos_fijos', v_salidas,
    'ahorros', v_fondos,
    'de_donde_vino', v_de_donde,
    'esperado', v_esperado,
    'fijo_mensual', v_fijo_mes,
    'cobro_pendiente', v_esperado > 0 and not coalesce(v_hubo_ingreso, false)
  );
end $fn$;

revoke all on function public.resumen_personal(uuid) from public, anon;
grant execute on function public.resumen_personal(uuid) to authenticated;


-- ############################################################
-- ##  027_categorias_propias.sql
-- ############################################################

-- ORDEN · Migración 027 · Cada uno nombra sus gastos como los entiende
--
-- Las categorías venían fijas: doce para una persona, nueve para un comercio,
-- y listo. Funciona para el 80% de los casos y falla justo en el que hace que
-- alguien deje de usar el sistema.
--
-- Alguien tiene un perro y gasta en veterinaria, comida y baño todos los
-- meses. Hoy eso cae en «Otros». Al tercer mes su presupuesto tiene una
-- bolsa llamada «Otros» con la mitad de su plata adentro, que es exactamente
-- lo que vino a evitar. Otro paga la cuota del club, otro manda plata a la
-- familia, otro tiene un auto y quiere separar nafta de mantenimiento.
--
-- Cada persona entiende su plata a su manera, y un sistema que la obliga a
-- usar los casilleros de otro deja de ser suyo.
--
-- LO QUE HACE QUE ESTO SIRVA DE VERDAD
--
-- Que la categoría propia también la conozca la IA. Si alguien crea
-- «Mascotas» pero al dictar «compré comida para el perro» el modelo sigue
-- clasificando en «Otros», la categoría nueva es un adorno: nunca se llena
-- sola y hay que corregir a mano cada vez. Por eso se guardan PISTAS, igual
-- que las categorías fijas, y por eso todo pasa por una sola función que
-- devuelve las fijas y las propias juntas.

create table if not exists public.categorias_propias (
  id         uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas (id) on delete cascade,
  nombre     text not null check (char_length(trim(nombre)) between 1 and 40),
  -- Las de gasto y las de ingreso son listas distintas: «Sueldo» no es un
  -- lugar donde gastar, y «Mascotas» no es de dónde viene la plata.
  clase      text not null default 'gasto' check (clase in ('gasto', 'ingreso')),
  -- Palabras que hacen que la IA sepa cuándo usarla. Sin esto la categoría
  -- existe pero nunca se llena sola.
  pistas     text not null default '',
  activo     boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create unique index if not exists categorias_propias_unica
  on public.categorias_propias (empresa_id, clase, lower(trim(nombre)))
  where activo;

alter table public.categorias_propias enable row level security;

-- Se LEEN con es_miembro y no con es_admin: un vendedor carga gastos, y para
-- clasificarlos necesita ver los nombres. Son etiquetas, no plata.
drop policy if exists categorias_propias_select on public.categorias_propias;
create policy categorias_propias_select on public.categorias_propias
  for select to authenticated using (public.es_miembro(empresa_id));

revoke all on public.categorias_propias from anon, authenticated;
grant select on public.categorias_propias to authenticated;

do $$ begin
  execute 'drop trigger if exists cuenta_activa_categorias_propias on public.categorias_propias';
  execute 'create trigger cuenta_activa_categorias_propias before insert or update '
       || 'on public.categorias_propias for each row execute function public.exigir_cuenta_activa()';
end $$;

-- ------------------------------------------------------------
-- LA LISTA COMPLETA, EN UN SOLO LUGAR
--
-- Las fijas de esta cuenta más las propias. Todo lo que ofrece una pantalla
-- y todo lo que conoce la IA sale de acá. Que fueran dos fuentes distintas
-- es cómo se llegó a que el prompt clasificara en «Salidas» mientras el
-- presupuesto ofrecía «Ocio», y el gasto quedara fuera de la cuenta que la
-- persona había hecho.
-- ------------------------------------------------------------
create or replace function public.categorias_de_empresa(
  p_empresa uuid,
  p_clase   text default 'gasto'
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_rubro  text;
  v_tipo   text;
  v_fijas  jsonb;
  v_mias   jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No tenés acceso a esta cuenta.' using errcode = '42501';
  end if;

  select rubro, tipo_cuenta into v_rubro, v_tipo
  from public.empresas where id = p_empresa;

  v_fijas := case
    when p_clase = 'ingreso' then public.categorias_de_ingreso(v_tipo)
    else public.categorias_de_rubro(v_rubro, v_tipo) end;

  select coalesce(jsonb_agg(jsonb_build_object(
           'nombre', c.nombre, 'pistas', c.pistas, 'propia', true
         ) order by c.nombre), '[]'::jsonb)
  into v_mias
  from public.categorias_propias c
  where c.empresa_id = p_empresa and c.activo
    and c.clase = case when p_clase = 'ingreso' then 'ingreso' else 'gasto' end;

  -- Las propias van ANTES de «Otros», que siempre cierra la lista: una
  -- categoría nueva escondida debajo del cajón de sastre no se usa nunca.
  return (
    select coalesce(jsonb_agg(x order by orden, i), '[]'::jsonb)
    from (
      select value as x,
             case when value->>'nombre' ilike 'otro%' then 2 else 0 end as orden,
             ordinality as i
      from jsonb_array_elements(v_fijas) with ordinality
      union all
      select value, 1, 0 from jsonb_array_elements(v_mias)
    ) t
  );
end $fn$;

revoke all on function public.categorias_de_empresa(uuid, text) from public, anon;
grant execute on function public.categorias_de_empresa(uuid, text) to authenticated;

-- ------------------------------------------------------------
-- CREARLAS Y BORRARLAS
--
-- Solo la administración. Un vendedor que pudiera inventar categorías estaría
-- reescribiendo el presupuesto del dueño sin querer.
-- ------------------------------------------------------------
create or replace function public.guardar_categoria_propia(
  p_empresa uuid,
  p_nombre  text,
  p_clase   text default 'gasto',
  p_pistas  text default '',
  p_id      uuid default null
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_id     uuid;
  v_clase  text;
  v_nombre text;
  v_rubro  text;
  v_tipo   text;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar esto.' using errcode = '42501';
  end if;

  v_nombre := trim(coalesce(p_nombre, ''));
  if char_length(v_nombre) = 0 then
    raise exception 'Escribí un nombre para la categoría.' using errcode = '22023';
  end if;
  if char_length(v_nombre) > 40 then
    raise exception 'Ese nombre es muy largo. Con 40 letras alcanza.' using errcode = '22023';
  end if;

  v_clase := case when p_clase = 'ingreso' then 'ingreso' else 'gasto' end;

  select rubro, tipo_cuenta into v_rubro, v_tipo from public.empresas where id = p_empresa;

  -- Que no repita una que ya viene de fábrica: quedarían dos renglones con
  -- el mismo nombre en el mismo menú y ninguno sabría cuál es cuál.
  if exists (
    select 1 from jsonb_array_elements(
      case when v_clase = 'ingreso'
        then public.categorias_de_ingreso(v_tipo)
        else public.categorias_de_rubro(v_rubro, v_tipo) end) f
    where lower(trim(f.value->>'nombre')) = lower(v_nombre)
  ) then
    raise exception 'Esa categoría ya existe.' using errcode = '22023';
  end if;

  if p_id is null then
    insert into public.categorias_propias (empresa_id, nombre, clase, pistas)
    values (p_empresa, v_nombre, v_clase, left(coalesce(p_pistas, ''), 200))
    returning id into v_id;
  else
    update public.categorias_propias
    set nombre = v_nombre, clase = v_clase,
        pistas = left(coalesce(p_pistas, ''), 200), updated_at = now()
    where id = p_id and empresa_id = p_empresa
    returning id into v_id;

    if v_id is null then
      raise exception 'Esa categoría no existe en esta cuenta.' using errcode = 'P0002';
    end if;
  end if;

  return v_id;
exception
  when unique_violation then
    raise exception 'Esa categoría ya existe.' using errcode = '22023';
end $fn$;

revoke all on function public.guardar_categoria_propia(uuid, text, text, text, uuid) from public, anon;
grant execute on function public.guardar_categoria_propia(uuid, text, text, text, uuid) to authenticated;

-- Borrar la categoría NO toca los movimientos que ya la usaron. Quedan con
-- su nombre escrito, que es lo correcto: el gasto de marzo fue en Mascotas
-- aunque hoy esa categoría ya no se ofrezca.
create or replace function public.borrar_categoria_propia(p_empresa uuid, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare v_nombre text;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar esto.' using errcode = '42501';
  end if;

  delete from public.categorias_propias
  where id = p_id and empresa_id = p_empresa
  returning nombre into v_nombre;

  if v_nombre is null then
    raise exception 'Esa categoría no existe en esta cuenta.' using errcode = 'P0002';
  end if;

  -- Si tenía presupuesto asignado, se va con ella: un límite para una
  -- categoría que ya no existe es un renglón que no se puede tocar.
  delete from public.presupuesto
  where empresa_id = p_empresa and categoria = v_nombre;

  return jsonb_build_object('borrada', true, 'nombre', v_nombre);
end $fn$;

revoke all on function public.borrar_categoria_propia(uuid, uuid) from public, anon;
grant execute on function public.borrar_categoria_propia(uuid, uuid) to authenticated;


-- ############################################################
-- ##  028_ingresos_por_categoria.sql
-- ############################################################

-- ORDEN · Migración 028 · De dónde vino la plata, en el período que elijas
--
-- `gastos_por_categoria` existe desde la 005 y contesta «en qué se me fue».
-- Para un comercio con eso alcanza: casi todo lo que entra es una venta, y el
-- desglose de ingresos no dice nada.
--
-- Para una persona con sueldo es al revés. Saber que este mes entraron
-- 2.350.000 no sirve de mucho; saber que 1.850.000 fue el sueldo y 500.000
-- fueron horas extra y una changa sí, porque una parte se repite el mes que
-- viene y la otra no. Es la diferencia entre gano bien y este mes zafé.
--
-- Espejo exacto de `gastos_por_categoria`: misma forma de respuesta, mismos
-- controles, mismo orden. Solo cambia el tipo de movimiento que mira.

create or replace function public.ingresos_por_categoria(
  p_empresa uuid,
  p_desde date,
  p_hasta date
)
returns setof jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  return query
  with porCategoria as (
    select
      trim(coalesce(nullif(trim(m.categoria), ''), 'General')) as nombre,
      sum(m.monto)::numeric as monto,
      count(*)::bigint      as operaciones
    from public.movimientos m
    where m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
      and m.estado = 'activo'
      -- Ventas e ingresos juntos: para quien mira esto, todo lo que entró es
      -- lo que entró. La distinción venta/ingreso es interna.
      and m.tipo in ('venta', 'ingreso')
    group by 1
  ),
  con_total as (
    select c.*, sum(c.monto) over () as total from porCategoria c
  )
  select jsonb_build_object(
    'nombre',        c.nombre,
    'monto',         c.monto,
    'operaciones',   c.operaciones,
    'participacion', case when c.total > 0 then (c.monto / c.total) * 100 else 0 end
  )
  from con_total c
  order by c.monto desc;
end $$;

revoke all on function public.ingresos_por_categoria(uuid, date, date) from public, anon;
grant execute on function public.ingresos_por_categoria(uuid, date, date) to authenticated;


-- ############################################################
-- ##  029_meta_con_fecha.sql
-- ############################################################

-- ORDEN · Migración 029 · El ahorro con fecha
--
-- La 026 le puso META a los fondos: cuánto quiere juntar. Faltaba la mitad
-- de la pregunta, y es la mitad que hace que alguien ahorre de verdad.
--
-- «Quiero juntar 5.000.000» no le dice a nadie qué hacer este mes. «Quiero
-- juntar 5.000.000 para el viaje de fin de año» sí: son once meses, faltan
-- 3.800.000, o sea 345.000 por mes. Ese número —cuánto tengo que guardar
-- ahora— es el único que cambia una conducta. Una meta sin fecha es un deseo;
-- con fecha es un plan.
--
-- POR QUÉ LA FECHA ES OPCIONAL, IGUAL QUE LA META
--
-- Mucha gente ahorra sin fecha —el fondo de emergencia no vence nunca— y
-- exigirle una la obligaría a inventar un dato falso para poder empezar. Los
-- dos campos son independientes: se puede tener meta sin fecha (junto hasta
-- llegar), fecha sin meta (guardo para diciembre, lo que pueda), las dos, o
-- ninguna.
--
-- EL RITMO LO CALCULA LA BASE, NO LA PANTALLA
--
-- `por_mes` sale de acá y no del navegador por el mismo motivo que todo lo
-- demás: es un número sobre la plata de alguien. Si lo calculara la pantalla,
-- el día que ese cálculo aparezca también en un email o en un aviso habría
-- dos fórmulas para la misma respuesta, y tarde o temprano dirían cosas
-- distintas.

-- ============================================================
-- 1. LA COLUMNA
-- ============================================================
alter table public.ahorros add column if not exists fecha_limite date;

comment on column public.ahorros.fecha_limite is
  'Para cuándo quiere tener juntada la meta. Null = sin fecha, se junta hasta llegar.';

-- ============================================================
-- 2. GUARDAR
--
--    Se REEMPLAZA la función de cuatro argumentos en vez de dejar las dos
--    conviviendo: dos versiones de la misma puerta es cómo se llega a que la
--    pantalla guarde la fecha y otra cosa la pise con null.
-- ============================================================
drop function if exists public.guardar_ahorro(uuid, text, numeric, uuid);

create or replace function public.guardar_ahorro(
  p_empresa      uuid,
  p_nombre       text,
  p_meta         numeric default null,
  p_fecha_limite date    default null,
  p_id           uuid    default null
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_id       uuid;
  v_zona     text;
  v_hoy      date;
  v_anterior date;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar esto.' using errcode = '42501';
  end if;

  if char_length(trim(coalesce(p_nombre, ''))) = 0 then
    raise exception 'Ponele un nombre, para saber para qué estás juntando.' using errcode = '22023';
  end if;

  if p_meta is not null and p_meta <= 0 then
    raise exception 'La meta tiene que ser mayor que cero, o dejala vacía.' using errcode = '22023';
  end if;

  select zona_horaria into v_zona from public.empresas where id = p_empresa;
  v_hoy := (now() at time zone coalesce(v_zona, 'America/Asuncion'))::date;

  -- Una fecha que ya pasó casi siempre es un año mal tipeado. Se rechaza al
  -- ponerla, pero NO se rechaza guardar un fondo cuya fecha venció mientras
  -- tanto: si no, el día después del viaje la persona no podría ni corregirle
  -- el nombre a su propio fondo.
  if p_id is not null then
    select fecha_limite into v_anterior
    from public.ahorros where id = p_id and empresa_id = p_empresa;
  end if;

  if p_fecha_limite is not null
     and p_fecha_limite < v_hoy
     and p_fecha_limite is distinct from v_anterior then
    raise exception 'Esa fecha ya pasó. Poné para cuándo lo querés juntar.' using errcode = '22007';
  end if;

  if p_id is null then
    insert into public.ahorros (empresa_id, nombre, meta, fecha_limite)
    values (p_empresa, trim(p_nombre), p_meta, p_fecha_limite)
    returning id into v_id;
  else
    update public.ahorros
    set nombre = trim(p_nombre), meta = p_meta, fecha_limite = p_fecha_limite,
        updated_at = now()
    where id = p_id and empresa_id = p_empresa
    returning id into v_id;

    if v_id is null then
      raise exception 'Ese fondo no existe en esta cuenta.' using errcode = 'P0002';
    end if;
  end if;

  return v_id;
end $fn$;

revoke all on function public.guardar_ahorro(uuid, text, numeric, date, uuid) from public, anon;
grant execute on function public.guardar_ahorro(uuid, text, numeric, date, uuid) to authenticated;

-- ============================================================
-- 3. EL RESUMEN, CON EL RITMO DE CADA FONDO
--
--    Se reescribe entera (la última versión venía de la 026) porque en
--    PostgreSQL no se puede parchear el cuerpo de una función: o se
--    reemplaza completa o queda la vieja.
-- ============================================================
create or replace function public.resumen_personal(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_c            record;
  v_zona         text;
  v_hoy          date;
  v_entro        numeric := 0;
  v_salio        numeric := 0;
  v_cuotas       numeric := 0;
  v_fijos_falta  numeric := 0;
  v_ahorro_ciclo numeric := 0;
  v_ahorro_total numeric := 0;
  v_dias         integer;
  v_plan         jsonb;
  v_sin_planear  numeric := 0;
  v_entradas     jsonb;
  v_salidas      jsonb;
  v_fondos       jsonb;
  v_de_donde     jsonb;
  v_esperado     numeric := 0;
  v_fijo_mes     numeric := 0;
  v_hubo_ingreso boolean := false;
  v_disponible   numeric;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'No tenés acceso a esta cuenta.' using errcode = '42501';
  end if;

  select zona_horaria into v_zona from public.empresas where id = p_empresa;
  v_hoy := (now() at time zone coalesce(v_zona, 'America/Asuncion'))::date;

  select * into v_c from public.ciclo_personal(p_empresa);

  select
    coalesce(sum(m.monto) filter (where m.tipo in ('ingreso', 'venta')), 0),
    coalesce(sum(m.monto) filter (where m.tipo = 'gasto'), 0),
    bool_or(m.tipo in ('ingreso', 'venta'))
  into v_entro, v_salio, v_hubo_ingreso
  from public.movimientos m
  where m.empresa_id = p_empresa
    and m.estado = 'activo'
    and m.fecha between v_c.desde and v_c.hasta;

  select coalesce(sum(d.monto_cuota), 0) into v_cuotas
  from public.deudas d
  where d.empresa_id = p_empresa
    and d.activa and d.saldo > 0
    and d.monto_cuota is not null
    and d.vence_el between v_hoy and v_c.hasta;

  select coalesce(sum(greatest(0, f.total - coalesce(g.gastado, 0))), 0)
  into v_fijos_falta
  from (
    select categoria, sum(importe) as total
    from public.gastos_fijos
    where empresa_id = p_empresa and activo
    group by categoria
  ) f
  left join lateral (
    select sum(m.monto) as gastado
    from public.movimientos m
    where m.empresa_id = p_empresa and m.estado = 'activo' and m.tipo = 'gasto'
      and m.categoria = f.categoria
      and m.fecha between v_c.desde and v_c.hasta
  ) g on true;

  -- Lo guardado en ESTE ciclo, neto de retiros.
  select coalesce(sum(case when ma.tipo = 'aporte' then ma.monto else -ma.monto end), 0)
  into v_ahorro_ciclo
  from public.movimientos_ahorro ma
  where ma.empresa_id = p_empresa and ma.fecha between v_c.desde and v_c.hasta;

  -- Y lo acumulado de siempre, que es el número del que la gente se
  -- enorgullece.
  select coalesce(sum(case when ma.tipo = 'aporte' then ma.monto else -ma.monto end), 0)
  into v_ahorro_total
  from public.movimientos_ahorro ma
  where ma.empresa_id = p_empresa;

  v_dias := greatest(1, (v_c.hasta - v_hoy) + 1);
  v_disponible := v_entro - v_salio - v_cuotas - v_fijos_falta - v_ahorro_ciclo;

  select
    coalesce(jsonb_agg(jsonb_build_object(
      'categoria', p.categoria,
      'planeado',  p.importe,
      'gastado',   coalesce(g.total, 0),
      'resta',     p.importe - coalesce(g.total, 0)
    ) order by p.categoria), '[]'::jsonb)
  into v_plan
  from public.presupuesto p
  left join lateral (
    select sum(m.monto) as total
    from public.movimientos m
    where m.empresa_id = p_empresa and m.estado = 'activo' and m.tipo = 'gasto'
      and m.categoria = p.categoria
      and m.fecha between v_c.desde and v_c.hasta
  ) g on true
  where p.empresa_id = p_empresa;

  select coalesce(sum(m.monto), 0) into v_sin_planear
  from public.movimientos m
  where m.empresa_id = p_empresa and m.estado = 'activo' and m.tipo = 'gasto'
    and m.fecha between v_c.desde and v_c.hasta
    and not exists (
      select 1 from public.presupuesto p
      where p.empresa_id = p_empresa and p.categoria = m.categoria);

  select
    coalesce(jsonb_agg(jsonb_build_object(
      'id', i.id, 'nombre', i.nombre, 'importe', i.importe,
      'dia_del_mes', i.dia_del_mes, 'principal', i.principal
    ) order by i.principal desc, i.importe desc), '[]'::jsonb),
    coalesce(sum(i.importe), 0)
  into v_entradas, v_esperado
  from public.ingresos_fijos i
  where i.empresa_id = p_empresa and i.activo;

  select
    coalesce(jsonb_agg(jsonb_build_object(
      'id', g.id, 'nombre', g.nombre, 'importe', g.importe,
      'categoria', g.categoria, 'dia_del_mes', g.dia_del_mes, 'notas', g.notas
    ) order by g.dia_del_mes nulls last, g.importe desc), '[]'::jsonb),
    coalesce(sum(g.importe), 0)
  into v_salidas, v_fijo_mes
  from public.gastos_fijos g
  where g.empresa_id = p_empresa and g.activo;

  -- Cada fondo con su ritmo: cuánto falta y cuánto habría que guardar por
  -- mes para llegar a tiempo. `por_mes` en null significa que no hay ritmo
  -- que calcular, y son tres casos distintos que la pantalla distingue por
  -- los otros campos: sin meta, sin fecha, o con la fecha ya vencida.
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', a.id, 'nombre', a.nombre, 'meta', a.meta,
    'fecha_limite', a.fecha_limite,
    'saldo', s.saldo,
    'falta', case when a.meta is null then null
                  else greatest(0, a.meta - s.saldo) end,
    'dias_para_limite', case when a.fecha_limite is null then null
                             else (a.fecha_limite - v_hoy) end,
    'por_mes', case
                 when a.meta is null or a.fecha_limite is null then null
                 when a.meta - s.saldo <= 0 then 0
                 when a.fecha_limite < v_hoy then null
                 -- Los meses se redondean para arriba y nunca bajan de uno:
                 -- si faltan diez días, el ritmo es todo lo que falta.
                 else round((a.meta - s.saldo)
                            / greatest(1, ceil((a.fecha_limite - v_hoy)::numeric / 30)), 2)
               end
  ) order by a.created_at), '[]'::jsonb)
  into v_fondos
  from public.ahorros a
  cross join lateral (select public.saldo_ahorro(a.id) as saldo) s
  where a.empresa_id = p_empresa and a.activo;

  -- De dónde vino lo que entró en el ciclo.
  select coalesce(jsonb_agg(x order by (x->>'monto')::numeric desc), '[]'::jsonb)
  into v_de_donde
  from (
    select jsonb_build_object('categoria', m.categoria, 'monto', sum(m.monto)) as x
    from public.movimientos m
    where m.empresa_id = p_empresa and m.estado = 'activo'
      and m.tipo in ('ingreso', 'venta')
      and m.fecha between v_c.desde and v_c.hasta
    group by m.categoria
  ) t;

  return jsonb_build_object(
    'desde', v_c.desde,
    'hasta', v_c.hasta,
    'dia_cobro', v_c.dia_cobro,
    'dias_restantes', v_dias,
    'entro', v_entro,
    'salio', v_salio,
    'cuotas_por_vencer', v_cuotas,
    'fijos_por_pagar', v_fijos_falta,
    'ahorrado_en_el_ciclo', v_ahorro_ciclo,
    'ahorro_total', v_ahorro_total,
    'disponible', v_disponible,
    'por_dia', round(v_disponible / v_dias, 2),
    'plan', v_plan,
    'gastado_sin_planear', v_sin_planear,
    'ingresos_fijos', v_entradas,
    'gastos_fijos', v_salidas,
    'ahorros', v_fondos,
    'de_donde_vino', v_de_donde,
    'esperado', v_esperado,
    'fijo_mensual', v_fijo_mes,
    'cobro_pendiente', v_esperado > 0 and not coalesce(v_hubo_ingreso, false)
  );
end $fn$;

revoke all on function public.resumen_personal(uuid) from public, anon;
grant execute on function public.resumen_personal(uuid) to authenticated;


-- ############################################################
-- ##  030_ahorro_del_periodo.sql
-- ############################################################

-- ORDEN · Migración 030 · El ahorro dentro de un período elegido
--
-- `resumen_personal` ya cuenta el ahorro, pero siempre del CICLO en curso: de
-- cobro a cobro. El reporte y el Excel trabajan con otro recorte —el rango de
-- fechas que la persona elige— y ahí ese número no sirve.
--
-- Mezclar los dos sería el peor error posible en una planilla: mostrar «entró
-- y salió» de enero a marzo junto a un ahorro que en realidad es el de los
-- últimos veinte días. Dos períodos distintos en la misma hoja, sin que nada
-- lo diga.
--
-- POR QUÉ ES UNA FUNCIÓN Y NO UNA CONSULTA DESDE EL SERVIDOR
--
-- Por lo mismo que los otros agregados: sumar en el servidor obliga a traerse
-- las filas, y una lista traída puede venir recortada por el tope de la Data
-- API sin avisar. Un total que se calcula sobre una lista incompleta no se
-- ve mal: se ve como un total más chico. Sumar acá adentro no puede recortar.

create or replace function public.resumen_ahorro_periodo(
  p_empresa uuid,
  p_desde   date,
  p_hasta   date
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_aportado numeric := 0;
  v_retirado numeric := 0;
  v_fondos   jsonb;
begin
  -- Se lee con `es_admin` y no con `es_miembro`, igual que las tablas de
  -- ahorro desde la 026: cuánto guarda alguien no lo ve un vendedor.
  if not public.es_admin(p_empresa) then
    raise exception 'No tenés acceso a esta cuenta.' using errcode = '42501';
  end if;

  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  select
    coalesce(sum(ma.monto) filter (where ma.tipo = 'aporte'), 0),
    coalesce(sum(ma.monto) filter (where ma.tipo = 'retiro'), 0)
  into v_aportado, v_retirado
  from public.movimientos_ahorro ma
  where ma.empresa_id = p_empresa
    and ma.fecha between p_desde and p_hasta;

  -- Solo los fondos que se movieron en el período. Listar los quietos en cero
  -- alargaría la hoja sin decir nada: que un fondo no se haya tocado en marzo
  -- no es información, es ruido.
  select coalesce(jsonb_agg(x order by (x->>'neto')::numeric desc), '[]'::jsonb)
  into v_fondos
  from (
    select jsonb_build_object(
      'nombre',   a.nombre,
      'aportado', coalesce(sum(ma.monto) filter (where ma.tipo = 'aporte'), 0),
      'retirado', coalesce(sum(ma.monto) filter (where ma.tipo = 'retiro'), 0),
      'neto',     coalesce(sum(case when ma.tipo = 'aporte' then ma.monto else -ma.monto end), 0),
      -- El saldo del fondo a hoy, que es de otro recorte y por eso va con su
      -- propio nombre: la hoja lo rotula aparte para que nadie lo sume con
      -- las columnas del período.
      'saldo_hoy', public.saldo_ahorro(a.id)
    ) as x
    from public.movimientos_ahorro ma
    join public.ahorros a on a.id = ma.ahorro_id
    where ma.empresa_id = p_empresa
      and ma.fecha between p_desde and p_hasta
    group by a.id, a.nombre
  ) t;

  return jsonb_build_object(
    'aportado', v_aportado,
    'retirado', v_retirado,
    'neto',     v_aportado - v_retirado,
    'por_fondo', v_fondos
  );
end $fn$;

revoke all on function public.resumen_ahorro_periodo(uuid, date, date) from public, anon;
grant execute on function public.resumen_ahorro_periodo(uuid, date, date) to authenticated;


-- ############################################################
-- ##  031_aviso_para_personas.sql
-- ############################################################

-- ORDEN · Migración 031 · El recordatorio también es para una persona
--
-- La 024 sacó a las cuentas personales del recordatorio de la noche, y el
-- motivo era bueno: una persona con sueldo no cierra el día. Su ciclo va de
-- cobro a cobro, y decirle «cerrá el día» era hablarle en el idioma de un
-- almacén.
--
-- Pero la conclusión se pasó de largo. Que no cierre el día no quiere decir
-- que no necesite que le recuerden cargar. Es al revés: el gasto de una
-- persona es el que más fácil se olvida —son montos chicos, muchos por día, y
-- ninguno tiene factura que lo recuerde— y si no los carga, en dos semanas la
-- app le miente sobre cuánto le queda. Una cuenta sin datos no es una cuenta
-- prolija: es una cuenta que no sirve.
--
-- Así que vuelve al recordatorio, pero con las mismas dos condiciones que
-- protegen a todos los demás:
--
--   · SOLO A QUIEN YA TIENE EL HÁBITO. Hacen falta dos días seguidos de
--     carga. A quien todavía no lo tiene, un aviso no se lo crea: lo único
--     que logra es enseñarle a ignorar nuestras notificaciones.
--
--   · UNO POR DÍA COMO MÁXIMO. Lo garantiza la tabla `envios`, que no se
--     toca acá.
--
-- Lo que cambia en la respuesta es que ahora dice QUÉ TIPO DE CUENTA es cada
-- una, porque el aviso de una persona no puede llevarla a la pantalla de
-- cierre del día: esa pantalla no existe en su cuenta.
--
-- OJO CON `rubro_cierra_el_dia`: NO SE TOCA
--
-- Esa función contesta otra pregunta —¿esta cuenta ve la pantalla de cierre?—
-- y la respuesta para una persona sigue siendo que no. Meter acá el cambio
-- habría sido más corto y habría hecho aparecer «Cierre del día» en el menú
-- de todas las cuentas personales. Dos preguntas distintas, dos funciones.

create or replace function public.empresas_sin_cargar_hoy(p_racha_minima integer default 2)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_res jsonb;
begin
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'empresa_id',  e.id,
      'nombre',      e.nombre,
      'zona',        e.zona_horaria,
      'racha',       r.largo,
      -- Para que quien manda el aviso sepa a qué pantalla mandarlo y en qué
      -- idioma hablarle. Sin esto habría que volver a consultar la empresa
      -- una por una desde el servidor.
      'tipo_cuenta', coalesce(e.tipo_cuenta, 'emprendedor')
    ) as x
    from public.empresas e
    join lateral (
      with dias as (
        select distinct m.fecha from public.movimientos m
        where m.empresa_id = e.id and m.estado = 'activo'
          and m.fecha <= (now() at time zone e.zona_horaria)::date
      ),
      numeradas as (
        select fecha, (fecha - (row_number() over (order by fecha))::int) as isla from dias
      ),
      rachas as (
        select count(*)::int as largo, max(fecha) as hasta from numeradas group by isla
      )
      select largo, hasta from rachas order by hasta desc limit 1
    ) r on true
    where (
        -- Una persona: siempre, porque su ciclo no depende del rubro.
        coalesce(e.tipo_cuenta, 'emprendedor') = 'personal'
        -- Un negocio: solo los de ciclo diario. A un ganadero no se le
        -- recuerda cargar todos los días porque su ciclo es el novillo.
        or public.rubro_cierra_el_dia(e.rubro, e.tipo_cuenta)
      )
      and r.hasta = (now() at time zone e.zona_horaria)::date - 1
      and r.largo >= greatest(p_racha_minima, 1)
  ) s;

  return v_res;
end $fn$;

revoke all on function public.empresas_sin_cargar_hoy(integer) from public, anon, authenticated;
grant execute on function public.empresas_sin_cargar_hoy(integer) to service_role;


-- ############################################################
-- ##  032_cada_cuenta_su_dia.sql
-- ############################################################

-- ORDEN · Migración 032 · Cada cuenta decide su propio día
--
-- Orden guarda la zona horaria de cada empresa desde la migración 008, y
-- tiene `hoy_empresa(empresa_id)` para preguntarle qué día es allá. Pero
-- media docena de lugares centrales seguían preguntándoselo a Asunción.
--
-- MIENTRAS TODOS LOS CLIENTES ESTUVIERON EN PARAGUAY, NO SE NOTÓ. Y esa es
-- exactamente la forma más peligrosa de un error: el que no falla hasta que
-- falla con un cliente nuevo, lejos, y sin nada en los registros que lo
-- explique.
--
-- Ya se cobró una vez. Un ingreso cargado con fecha de mañana se rechazaba
-- con «new row violates row-level security policy», un mensaje que no dice
-- nada, porque la política comparaba contra el día en Asunción.
--
-- Y se vuelve bloqueante ahora: el módulo de turnos calcula huecos libres.
-- Un motor de horarios que resuelve "hoy" en la zona equivocada ofrece turnos
-- que no existen, y eso aparece como «me dio una hora imposible» — imposible
-- de diagnosticar en producción.
--
-- LO QUE **NO** SE TOCA
--
-- Los doce lugares donde Asunción es un *valor por defecto* se quedan como
-- están: `empresas.zona_horaria`, los `p_zona text default` de las funciones
-- de registro y sus `coalesce`. Ahí Asunción no decide nada, solo cubre el
-- caso en que el navegador no informe su zona. Está bien y tiene que seguir.
--
-- Tampoco se tocan los permisos. `create or replace function` conserva los
-- privilegios que la función ya tenía, así que volver a otorgarlos acá sería
-- arriesgarse a reabrirle a `anon` algo que la migración 012 cerró.

-- ============================================================
-- 1. LA POLÍTICA QUE DIO EL ERROR
--
--    Una política se evalúa por fila, así que puede leer `empresa_id` de la
--    fila que se está insertando. El resto de la política no cambia.
-- ============================================================
drop policy if exists movimientos_insert on public.movimientos;
create policy movimientos_insert on public.movimientos
  for insert with check (
    public.es_miembro(empresa_id)
    and tipo <> 'venta'
    and estado = 'activo'
    and creado_por = auth.uid()
    and descuento = 0
    and costo_total = 0
    and subtotal = monto
    and anulado_por is null
    and anulado_at is null
    and fecha >= date '2000-01-01'
    and fecha <= (public.hoy_empresa(empresa_id) + 1)
  );

-- ============================================================
-- 2. LAS FECHAS POR DEFECTO DE LAS DOS TABLAS
--
--    Un `default` de columna no puede mirar otra columna de su propia fila,
--    así que no hay forma de escribir `hoy_empresa(empresa_id)` ahí. Se
--    resuelve con un trigger que completa la fecha cuando viene vacía.
--
--    El orden importa y sale bien: PostgreSQL corre los triggers BEFORE antes
--    de comprobar las restricciones y las políticas RLS, así que la política
--    de arriba ve la fecha que el trigger ya completó.
-- ============================================================
create or replace function public.fecha_de_la_empresa()
returns trigger language plpgsql set search_path = public as $fn$
begin
  if new.fecha is null then
    new.fecha := public.hoy_empresa(new.empresa_id);
  end if;
  return new;
end $fn$;

alter table public.movimientos        alter column fecha drop default;
alter table public.movimientos_ahorro alter column fecha drop default;

drop trigger if exists fecha_empresa_movimientos on public.movimientos;
create trigger fecha_empresa_movimientos
  before insert on public.movimientos
  for each row execute function public.fecha_de_la_empresa();

drop trigger if exists fecha_empresa_movimientos_ahorro on public.movimientos_ahorro;
create trigger fecha_empresa_movimientos_ahorro
  before insert on public.movimientos_ahorro
  for each row execute function public.fecha_de_la_empresa();

-- ============================================================
-- 3. REGISTRAR UNA VENTA
--
--    Cuerpo idéntico al de la migración 002. Cambian dos líneas: la fecha
--    por defecto y el tope del rango válido.
-- ============================================================
create or replace function public.registrar_venta(
  p_empresa uuid,
  p_items jsonb,
  p_fecha date default null,
  p_descripcion text default '',
  p_metodo_pago text default 'efectivo',
  p_contraparte text default '',
  p_notas text default '',
  p_origen origen_captura default 'manual',
  p_descuento numeric default 0
)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_mov       uuid;
  v_item      jsonb;
  v_prod      public.productos%rowtype;
  v_norm      jsonb := '[]'::jsonb;
  v_subtotal  numeric(14,2) := 0;
  v_costo     numeric(14,2) := 0;
  v_desc      numeric(14,2);
  v_cant      numeric(14,2);
  v_precio    numeric(14,2);
  v_costo_u   numeric(14,2);
  v_nombre    text;
  v_pid       uuid;
  v_fecha     date;
  v_permitir  boolean;
  v_stock     numeric(14,2);
  v_metodo    text;
begin
  ------------------------------------------------ autenticación y pertenencia
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  select permitir_stock_negativo into v_permitir from public.empresas where id = p_empresa;
  if not found then
    raise exception 'La empresa no existe.' using errcode = '42501';
  end if;

  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  ------------------------------------------------ validaciones generales
  if p_items is null or jsonb_typeof(p_items) <> 'array' then
    raise exception 'La venta necesita una lista de productos.' using errcode = '22023';
  end if;

  if jsonb_array_length(p_items) = 0 then
    raise exception 'La venta necesita al menos un producto.' using errcode = '22023';
  end if;

  if jsonb_array_length(p_items) > 200 then
    raise exception 'Una venta no puede tener más de 200 líneas.' using errcode = '22023';
  end if;

  v_fecha := coalesce(p_fecha, public.hoy_empresa(p_empresa));
  if v_fecha < date '2000-01-01' or v_fecha > public.hoy_empresa(p_empresa) + 1 then
    raise exception 'La fecha de la venta no es válida.' using errcode = '22007';
  end if;

  v_metodo := lower(coalesce(nullif(trim(p_metodo_pago), ''), 'efectivo'));
  if v_metodo not in ('efectivo', 'transferencia', 'tarjeta', 'credito', 'otro') then
    raise exception 'La forma de cobro no es válida.' using errcode = '22023';
  end if;

  ------------------------------------------------ primera pasada: validar y normalizar
  for v_item in select * from jsonb_array_elements(p_items) loop
    if jsonb_typeof(v_item) <> 'object' then
      raise exception 'Cada línea de la venta tiene que ser un objeto.' using errcode = '22023';
    end if;

    begin
      v_cant := (v_item ->> 'cantidad')::numeric;
    exception when others then
      raise exception 'La cantidad tiene que ser un número.' using errcode = '22023';
    end;

    if v_cant is null or v_cant <= 0 then
      raise exception 'La cantidad tiene que ser mayor a cero.' using errcode = '22023';
    end if;
    if v_cant > 1000000 then
      raise exception 'La cantidad es demasiado grande.' using errcode = '22023';
    end if;

    v_pid := null;
    if nullif(trim(coalesce(v_item ->> 'producto_id', '')), '') is not null then
      begin
        v_pid := (v_item ->> 'producto_id')::uuid;
      exception when others then
        raise exception 'El identificador del producto no es válido.' using errcode = '22023';
      end;
    end if;

    if v_pid is not null then
      -- El producto tiene que existir Y ser de esta empresa.
      select * into v_prod from public.productos where id = v_pid and empresa_id = p_empresa;
      if not found then
        raise exception 'Ese producto no pertenece a esta empresa.' using errcode = '42501';
      end if;

      v_nombre  := v_prod.nombre;
      -- El precio SÍ puede ser distinto al del catálogo (rebaja puntual, acuerdo con el cliente).
      v_precio  := coalesce(nullif(v_item ->> 'precio_unitario', '')::numeric, v_prod.precio);
      -- El costo NO: siempre el del catálogo. Lo que mande el cliente se descarta.
      v_costo_u := v_prod.costo;
    else
      v_nombre := nullif(trim(coalesce(v_item ->> 'nombre', '')), '');
      if v_nombre is null then
        raise exception 'Cada producto suelto necesita un nombre.' using errcode = '22023';
      end if;
      v_nombre  := left(v_nombre, 120);
      v_precio  := coalesce(nullif(v_item ->> 'precio_unitario', '')::numeric, 0);
      v_costo_u := coalesce(nullif(v_item ->> 'costo_unitario', '')::numeric, 0);
    end if;

    if v_precio is null or v_precio < 0 then
      raise exception 'El precio no puede ser negativo.' using errcode = '22023';
    end if;
    if v_costo_u is null or v_costo_u < 0 then
      raise exception 'El costo no puede ser negativo.' using errcode = '22023';
    end if;

    v_subtotal := v_subtotal + (v_cant * v_precio);
    v_costo    := v_costo + (v_cant * v_costo_u);

    v_norm := v_norm || jsonb_build_object(
      'producto_id', v_pid,
      'nombre', v_nombre,
      'cantidad', v_cant,
      'precio_unitario', v_precio,
      'costo_unitario', v_costo_u,
      'controla_stock', coalesce(v_pid is not null and v_prod.controla_stock, false)
    );
  end loop;

  ------------------------------------------------ descuento
  v_desc := coalesce(p_descuento, 0);
  if v_desc < 0 then
    raise exception 'El descuento no puede ser negativo.' using errcode = '22023';
  end if;
  if v_desc > v_subtotal then
    raise exception 'El descuento no puede ser mayor que el subtotal de la venta.' using errcode = '22023';
  end if;

  ------------------------------------------------ cabecera
  insert into public.movimientos (
    empresa_id, tipo, estado, fecha, descripcion, categoria,
    subtotal, descuento, monto, costo_total,
    metodo_pago, contraparte, notas, origen, creado_por
  )
  values (
    p_empresa, 'venta', 'activo', v_fecha,
    left(coalesce(trim(p_descripcion), ''), 200), 'Ventas',
    v_subtotal, v_desc, v_subtotal - v_desc, v_costo,
    v_metodo, left(coalesce(trim(p_contraparte), ''), 80), left(coalesce(p_notas, ''), 500),
    coalesce(p_origen, 'manual'), auth.uid()
  )
  returning id into v_mov;

  ------------------------------------------------ items y stock
  for v_item in select * from jsonb_elements_ordenados(v_norm) loop
    v_cant := (v_item ->> 'cantidad')::numeric;
    v_pid  := nullif(v_item ->> 'producto_id', '')::uuid;

    if v_pid is not null and (v_item ->> 'controla_stock')::boolean then
      -- Aritmética relativa: dos ventas simultáneas no se pisan.
      update public.productos
        set stock = stock - v_cant
        where id = v_pid
        returning stock into v_stock;

      if not v_permitir and v_stock < 0 then
        raise exception 'No hay stock suficiente de %.', v_item ->> 'nombre' using errcode = '23514';
      end if;
    end if;

    insert into public.movimiento_items (
      movimiento_id, empresa_id, producto_id, nombre, cantidad,
      precio_unitario, costo_unitario, afecto_stock
    )
    values (
      v_mov, p_empresa, v_pid, v_item ->> 'nombre', v_cant,
      (v_item ->> 'precio_unitario')::numeric,
      (v_item ->> 'costo_unitario')::numeric,
      coalesce(v_pid is not null and (v_item ->> 'controla_stock')::boolean, false)
    );
  end loop;

  ------------------------------------------------ descripción automática
  update public.movimientos
  set descripcion = (
    select string_agg(nombre || ' x' || trim(to_char(cantidad, 'FM999999990.##')), ', ')
    from public.movimiento_items where movimiento_id = v_mov
  )
  where id = v_mov and coalesce(trim(descripcion), '') = '';

  return v_mov;
end $$;

-- ============================================================
-- 4. ANULAR UN MOVIMIENTO
--
--    Un vendedor solo anula lo suyo y solo el mismo día. Ese "mismo día" es
--    el de la empresa dueña del movimiento: si no, alguien en otra zona
--    pierde o gana una hora para corregir un error.
-- ============================================================
create or replace function public.anular_movimiento(
  p_movimiento uuid,
  p_motivo text default null
)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_mov     public.movimientos%rowtype;
  v_item    public.movimiento_items%rowtype;
  v_hoy     date;
  v_filas   integer;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  -- El FOR UPDATE serializa dos anulaciones simultáneas del mismo movimiento.
  select * into v_mov from public.movimientos where id = p_movimiento for update;
  if not found then
    raise exception 'El movimiento no existe.' using errcode = '42501';
  end if;

  if not public.es_miembro(v_mov.empresa_id) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  -- Recién acá se puede saber qué día es "hoy": depende de la zona de la
  -- empresa dueña del movimiento, no de la del servidor ni de Asunción.
  v_hoy := public.hoy_empresa(v_mov.empresa_id);

  if v_mov.estado = 'anulado' then
    raise exception 'Este movimiento ya estaba anulado.' using errcode = '23505';
  end if;

  -- Un vendedor solo anula lo que cargó él y solo el mismo día.
  if not public.es_admin(v_mov.empresa_id)
     and not (v_mov.creado_por = auth.uid() and v_mov.fecha = v_hoy) then
    raise exception 'Solo un administrador puede anular movimientos de otra persona o de días anteriores.'
      using errcode = '42501';
  end if;

  -- Marcamos primero, con guarda de estado: si otra transacción ganó la carrera,
  -- v_filas = 0 y salimos sin tocar el stock.
  update public.movimientos
  set estado = 'anulado',
      anulado_por = auth.uid(),
      anulado_at = now(),
      motivo_anulacion = left(nullif(trim(coalesce(p_motivo, '')), ''), 200)
  where id = v_mov.id and estado = 'activo';

  get diagnostics v_filas = row_count;
  if v_filas = 0 then
    raise exception 'Este movimiento ya estaba anulado.' using errcode = '23505';
  end if;

  -- Devolvemos exactamente el stock que la venta descontó.
  if v_mov.tipo = 'venta' then
    for v_item in
      select * from public.movimiento_items
      where movimiento_id = v_mov.id and afecto_stock and producto_id is not null
    loop
      update public.productos
        set stock = stock + v_item.cantidad
        where id = v_item.producto_id;
    end loop;
  end if;

  return v_mov.id;
end $$;


-- ############################################################
-- ##  033_reparto_a_tablas.sql
-- ############################################################

-- ORDEN · Migración 033 · El reparto con los profesionales
--
-- El primer módulo de un rubro. Se llama «reparto» y no «barbería» a
-- propósito: el problema es el mismo en una peluquería, un centro de estética,
-- un consultorio con dos kinesiólogos o una escuela con profesores. El rubro
-- decide si el módulo se enciende y con qué palabras; el módulo no sabe de
-- rubros.
--
-- QUÉ RESUELVE
--
-- En una peluquería real la plata del corte casi nunca es toda del local ni
-- toda del profesional. Conviven cuatro arreglos:
--
--   · LOCAL     el dueño se corta a sí mismo. Todo es del local.
--   · COMISION  el barbero cobra 30.000 y el local se queda el 50%.
--   · ALQUILER  el barbero se queda con el 100% y le paga una mensualidad.
--   · SUELDO    el barbero cobra para el local, que le paga un sueldo aparte.
--
-- DÓNDE VA LA PARTE DEL PROFESIONAL
--
-- En `costo_total` de la venta. No es una analogía forzada: para un almacén
-- ese campo es lo que costó la mercadería, y acá es lo que costó el servicio.
-- En los dos casos es plata que entró por la venta y que el local NO se queda.
--
-- Eso hace que todo lo demás salga solo, sin escribir una fórmula nueva:
-- `ganancia_bruta = ventas − costo_mercaderia` pasa a ser, sin tocarla, lo
-- que de verdad le queda al dueño. El panel, los reportes y el Excel ya
-- calculan sobre esa resta. Y desde la migración 005 esos dos campos vuelven
-- en NULL para quien no es admin, así que un barbero no ve el margen del
-- local: eso ya estaba resuelto en la base y no hubo que construirlo.
--
-- EL ALQUILER ES EL QUE ROMPE ALGO
--
-- Si el barbero se queda con el 100%, esa plata NUNCA fue del local.
-- Registrarla como venta del negocio inflaría la facturación por el monto
-- entero: un local con tres sillas alquiladas mostraría cuatro veces la plata
-- que maneja. Por eso ese corte se registra en la atribución —queda el
-- historial de quién atendió a quién— pero no genera ningún movimiento. Lo
-- que el local factura es la mensualidad, que se carga como cualquier ingreso.
--
-- Es la regla de siempre un paso más allá: además de no mostrar plata que
-- todavía no está, tampoco mostrar plata que nunca fue tuya.

-- ============================================================
-- 1. LOS PROFESIONALES
--
--    `user_id` es opcional a propósito. Un barbero puede estar en la lista y
--    en el reparto sin tener cuenta en Orden: el dueño le carga los cortes.
--    Atarlo a un miembro obligaría a pagar una silla del plan por cada
--    persona que solo necesita aparecer en una lista, y el dueño terminaría
--    llevando a la mitad de su equipo en un cuaderno aparte.
-- ============================================================
create table if not exists public.turnos_profesional (
  id         uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas (id) on delete cascade,
  nombre     text not null check (char_length(trim(nombre)) between 1 and 60),
  -- Si tiene cuenta, es quien puede cargar sus propios cortes y ver lo suyo.
  user_id    uuid references auth.users (id) on delete set null,
  reparto    text not null default 'local'
             check (reparto in ('local', 'comision', 'alquiler', 'sueldo')),
  -- Qué porcentaje se lleva el PROFESIONAL. Solo tiene sentido con comisión.
  porcentaje numeric(5,2) check (porcentaje is null or (porcentaje > 0 and porcentaje <= 100)),
  activo     boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  -- Una comisión sin porcentaje es un reparto que nadie puede calcular, y el
  -- día que se intente cobrar un corte va a fallar en el peor momento.
  constraint comision_con_porcentaje
    check (reparto <> 'comision' or porcentaje is not null)
);

create index if not exists turnos_profesional_empresa_idx
  on public.turnos_profesional (empresa_id) where activo;

-- Una persona no puede estar dos veces en el mismo equipo.
create unique index if not exists turnos_profesional_una_cuenta
  on public.turnos_profesional (empresa_id, user_id) where user_id is not null;

-- ============================================================
-- 2. EL PRECIO DE CADA UNO
--
--    El mismo «Corte» vale 50.000 con el dueño, 35.000 con uno y 30.000 con
--    otro. Sin fila acá, vale el precio del catálogo del local.
-- ============================================================
create table if not exists public.turnos_precio (
  empresa_id     uuid not null references public.empresas (id) on delete cascade,
  profesional_id uuid not null references public.turnos_profesional (id) on delete cascade,
  producto_id    uuid not null references public.productos (id) on delete cascade,
  precio         numeric(14,2) not null check (precio >= 0),
  updated_at     timestamptz not null default now(),
  primary key (profesional_id, producto_id)
);

-- ============================================================
-- 3. DE QUIÉN FUE CADA CORTE
--
--    Tabla propia y no una columna en `movimientos` a propósito. Si cada
--    módulo le agrega la suya, dentro de cuatro rubros la tabla más
--    importante del sistema tiene cuarenta columnas de las que treinta están
--    siempre vacías.
--
--    `movimiento_id` es NULO cuando el reparto es alquiler: ahí hubo un corte
--    y hay que dejar constancia, pero no hubo una venta del local.
--
--    Las dos partes se guardan CONGELADAS, igual que el costo de un producto
--    en el momento de la venta: si el mes que viene cambia el porcentaje, los
--    cortes viejos siguen diciendo lo que se repartió ese día.
-- ============================================================
create table if not exists public.turnos_atribucion (
  id                uuid primary key default gen_random_uuid(),
  empresa_id        uuid not null references public.empresas (id) on delete cascade,
  profesional_id    uuid not null references public.turnos_profesional (id) on delete restrict,
  movimiento_id     uuid references public.movimientos (id) on delete cascade,
  producto_id       uuid references public.productos (id) on delete set null,
  servicio          text not null default '',
  fecha             date not null,
  monto_cobrado     numeric(14,2) not null check (monto_cobrado >= 0),
  parte_profesional numeric(14,2) not null check (parte_profesional >= 0),
  parte_local       numeric(14,2) not null,
  reparto           text not null,
  creado_por        uuid references auth.users (id) on delete set null,
  created_at        timestamptz not null default now(),

  -- Las dos partes tienen que sumar exactamente lo cobrado. Sin esto, un
  -- redondeo mal hecho hace aparecer o desaparecer plata, y el desglose del
  -- panel deja de cerrar con el total.
  constraint partes_suman_el_total
    check (parte_profesional + parte_local = monto_cobrado)
);

create index if not exists turnos_atribucion_empresa_idx
  on public.turnos_atribucion (empresa_id, fecha desc);
create index if not exists turnos_atribucion_profesional_idx
  on public.turnos_atribucion (profesional_id, fecha desc);
create unique index if not exists turnos_atribucion_un_movimiento
  on public.turnos_atribucion (movimiento_id) where movimiento_id is not null;

-- ============================================================
-- 4. PERMISOS
--
--    `turnos_atribucion` se lee SOLO con es_admin, y no es un detalle: la
--    columna `parte_local` es el margen del dueño. Un barbero que la viera
--    sabría cuánto gana el local con cada corte suyo — y con los de sus
--    compañeros. Lo suyo lo lee por una función que le devuelve solo su parte.
--
--    Es la misma división que ya existe: un vendedor carga ventas, pero
--    costo_mercaderia y ganancia_bruta le vuelven vacías desde la 005.
-- ============================================================
alter table public.turnos_profesional enable row level security;
alter table public.turnos_precio      enable row level security;
alter table public.turnos_atribucion  enable row level security;

drop policy if exists turnos_profesional_select on public.turnos_profesional;
create policy turnos_profesional_select on public.turnos_profesional
  for select to authenticated using (public.es_miembro(empresa_id));

drop policy if exists turnos_precio_select on public.turnos_precio;
create policy turnos_precio_select on public.turnos_precio
  for select to authenticated using (public.es_miembro(empresa_id));

drop policy if exists turnos_atribucion_select on public.turnos_atribucion;
create policy turnos_atribucion_select on public.turnos_atribucion
  for select to authenticated using (public.es_admin(empresa_id));

revoke all on public.turnos_profesional from anon, authenticated;
revoke all on public.turnos_precio      from anon, authenticated;
revoke all on public.turnos_atribucion  from anon, authenticated;

grant select on public.turnos_profesional to authenticated;
grant select on public.turnos_precio      to authenticated;
grant select on public.turnos_atribucion  to authenticated;

-- La cuenta vencida queda en solo lectura, igual que todo lo demás.
do $$
declare v_tabla text;
begin
  foreach v_tabla in array array['turnos_profesional', 'turnos_precio', 'turnos_atribucion'] loop
    execute format('drop trigger if exists %I on public.%I',
                   'cuenta_activa_' || v_tabla, v_tabla);
    execute format(
      'create trigger %I before insert or update on public.%I '
      || 'for each row execute function public.exigir_cuenta_activa()',
      'cuenta_activa_' || v_tabla, v_tabla);
  end loop;
end $$;

-- ============================================================
-- 5. CUÁNTOS DECIMALES TIENE UNA MONEDA
--
--    El guaraní no tiene centavos. Repartir 33.333 al 50% sin saberlo deja
--    medio guaraní colgando, y medio guaraní que no existe es exactamente el
--    tipo de número que hace que alguien deje de creerle al sistema.
-- ============================================================
create or replace function public.decimales_de(p_moneda text)
returns integer language sql immutable set search_path = public as $fn$
  select case upper(coalesce(p_moneda, 'PYG')) when 'PYG' then 0 else 2 end;
$fn$;

grant execute on function public.decimales_de(text) to anon, authenticated;


-- ############################################################
-- ##  034_reparto_b_escritura.sql
-- ############################################################

-- ORDEN · Migración 034 · El reparto · las puertas para escribir
--
-- Todo lo que escribe pasa por acá. Las tablas de la 033 solo tienen policy
-- de lectura: nadie inserta ni actualiza desde el cliente, igual que con las
-- ventas y los ahorros.

-- ============================================================
-- 1. EL EQUIPO
--
--    Solo el propietario o un administrador toca esto, y el motivo no es
--    jerárquico: el PORCENTAJE del reparto se define acá. Si un barbero
--    pudiera editarlo, se pone el 100% y el local se entera cuando cuadra la
--    semana.
-- ============================================================
create or replace function public.guardar_profesional(
  p_empresa    uuid,
  p_nombre     text,
  p_reparto    text    default 'local',
  p_porcentaje numeric default null,
  p_user       uuid    default null,
  p_id         uuid    default null
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare v_id uuid;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar el equipo.' using errcode = '42501';
  end if;

  if char_length(trim(coalesce(p_nombre, ''))) = 0 then
    raise exception 'Ponele un nombre, para saber de quién es cada corte.' using errcode = '22023';
  end if;

  if coalesce(p_reparto, '') not in ('local', 'comision', 'alquiler', 'sueldo') then
    raise exception 'Ese tipo de arreglo no existe.' using errcode = '22023';
  end if;

  if p_reparto = 'comision'
     and (p_porcentaje is null or p_porcentaje <= 0 or p_porcentaje > 100) then
    raise exception 'Con comisión hace falta un porcentaje entre 1 y 100.' using errcode = '22023';
  end if;

  -- Si tiene cuenta, tiene que ser de este negocio: si no, se le estaría
  -- dando acceso a los cortes de una empresa a la que no pertenece.
  if p_user is not null
     and not exists (select 1 from public.miembros m
                     where m.empresa_id = p_empresa and m.user_id = p_user) then
    raise exception 'Esa persona no es parte de este negocio.' using errcode = '42501';
  end if;

  -- El porcentaje solo se guarda donde significa algo. Dejarlo escrito en un
  -- profesional a sueldo haría dudar el día que alguien lea la tabla.
  if p_id is null then
    insert into public.turnos_profesional (empresa_id, nombre, user_id, reparto, porcentaje)
    values (p_empresa, trim(p_nombre), p_user, p_reparto,
            case when p_reparto = 'comision' then p_porcentaje else null end)
    returning id into v_id;
  else
    update public.turnos_profesional
    set nombre = trim(p_nombre),
        user_id = p_user,
        reparto = p_reparto,
        porcentaje = case when p_reparto = 'comision' then p_porcentaje else null end,
        updated_at = now()
    where id = p_id and empresa_id = p_empresa
    returning id into v_id;

    if v_id is null then
      raise exception 'Esa persona no está en el equipo de esta cuenta.' using errcode = 'P0002';
    end if;
  end if;

  return v_id;
end $fn$;

revoke all on function public.guardar_profesional(uuid, text, text, numeric, uuid, uuid) from public, anon;
grant execute on function public.guardar_profesional(uuid, text, text, numeric, uuid, uuid) to authenticated;

-- Con cortes cargados no se borra: se desactiva. Borrarlo haría desaparecer
-- de quién fue cada corte, y la liquidación del mes pasado dejaría de cerrar.
create or replace function public.borrar_profesional(p_empresa uuid, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare v_cortes integer;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar el equipo.' using errcode = '42501';
  end if;

  select count(*)::int into v_cortes
  from public.turnos_atribucion where profesional_id = p_id and empresa_id = p_empresa;

  if v_cortes > 0 then
    update public.turnos_profesional set activo = false, updated_at = now()
    where id = p_id and empresa_id = p_empresa;
    if not found then
      raise exception 'Esa persona no está en el equipo de esta cuenta.' using errcode = 'P0002';
    end if;
    return jsonb_build_object('desactivado', true, 'cortes', v_cortes);
  end if;

  delete from public.turnos_profesional where id = p_id and empresa_id = p_empresa;
  if not found then
    raise exception 'Esa persona no está en el equipo de esta cuenta.' using errcode = 'P0002';
  end if;
  return jsonb_build_object('borrado', true);
end $fn$;

revoke all on function public.borrar_profesional(uuid, uuid) from public, anon;
grant execute on function public.borrar_profesional(uuid, uuid) to authenticated;

-- ============================================================
-- 2. EL PRECIO DE CADA UNO
--
--    Acá la regla se invierte: el precio de sus cortes lo maneja el propio
--    profesional. Es lo que cobra él, y obligarlo a pedirle al dueño que se
--    lo cambie es la forma más rápida de que vuelva a anotar en un cuaderno.
--    El dueño también puede, porque muchos barberos no van a tener cuenta.
-- ============================================================
create or replace function public.guardar_precio_profesional(
  p_empresa     uuid,
  p_profesional uuid,
  p_producto    uuid,
  p_precio      numeric
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare v_suyo boolean;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select (user_id is not null and user_id = auth.uid()) into v_suyo
  from public.turnos_profesional
  where id = p_profesional and empresa_id = p_empresa;

  if v_suyo is null then
    raise exception 'Esa persona no está en el equipo de esta cuenta.' using errcode = 'P0002';
  end if;

  if not public.es_admin(p_empresa) and not v_suyo then
    raise exception 'Solo podés cambiar el precio de tus propios servicios.' using errcode = '42501';
  end if;

  if not exists (select 1 from public.productos
                 where id = p_producto and empresa_id = p_empresa) then
    raise exception 'Ese servicio no existe en esta cuenta.' using errcode = 'P0002';
  end if;

  -- Poner el precio en cero es volver al del local: sin fila, manda el
  -- catálogo. Sin esto haría falta un segundo botón para algo que la persona
  -- piensa como «cobro lo mismo que la casa».
  if coalesce(p_precio, 0) <= 0 then
    delete from public.turnos_precio
    where profesional_id = p_profesional and producto_id = p_producto;
    return jsonb_build_object('quitado', true);
  end if;

  insert into public.turnos_precio (empresa_id, profesional_id, producto_id, precio)
  values (p_empresa, p_profesional, p_producto, p_precio)
  on conflict (profesional_id, producto_id) do update
    set precio = excluded.precio, updated_at = now();

  return jsonb_build_object('guardado', true);
end $fn$;

revoke all on function public.guardar_precio_profesional(uuid, uuid, uuid, numeric) from public, anon;
grant execute on function public.guardar_precio_profesional(uuid, uuid, uuid, numeric) to authenticated;

-- Qué cobra este profesional por este servicio. Sin fila propia, el catálogo.
create or replace function public.precio_de_servicio(p_profesional uuid, p_producto uuid)
returns numeric language sql stable security definer set search_path = public as $fn$
  select coalesce(
    (select p.precio from public.turnos_precio p
      where p.profesional_id = p_profesional and p.producto_id = p_producto),
    (select pr.precio from public.productos pr where pr.id = p_producto),
    0);
$fn$;

revoke all on function public.precio_de_servicio(uuid, uuid) from public, anon;
grant execute on function public.precio_de_servicio(uuid, uuid) to authenticated;

-- ============================================================
-- 3. COBRAR UN SERVICIO
--
--    La puerta principal del módulo. Calcula el reparto, crea la venta y deja
--    la atribución, todo en una transacción: o queda todo o no queda nada.
--
--    La venta se registra con el servicio como línea suelta y no como
--    producto del catálogo. Es a propósito: `registrar_venta` descarta el
--    costo que le manden para un producto de catálogo —y hace bien, es lo que
--    impide que un cliente invente su margen— así que la única forma honesta
--    de que el costo sea la parte del barbero es no pasar por ahí. Qué
--    servicio fue queda guardado en la atribución, que es de donde sale el
--    ranking de servicios del módulo.
-- ============================================================
create or replace function public.registrar_servicio(
  p_empresa     uuid,
  p_profesional uuid,
  p_producto    uuid,
  p_precio      numeric default null,
  p_fecha       date    default null,
  p_metodo_pago text    default 'efectivo',
  p_cliente     text    default '',
  p_notas       text    default '',
  p_origen      origen_captura default 'manual'
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_prof     public.turnos_profesional%rowtype;
  v_prod     public.productos%rowtype;
  v_moneda   text;
  v_dec      integer;
  v_monto    numeric(14,2);
  v_prof_par numeric(14,2);
  v_local    numeric(14,2);
  v_mov      uuid;
  v_fecha    date;
  v_id       uuid;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select * into v_prof from public.turnos_profesional
  where id = p_profesional and empresa_id = p_empresa and activo;
  if not found then
    raise exception 'Esa persona no está en el equipo de esta cuenta.' using errcode = 'P0002';
  end if;

  -- Un profesional carga lo suyo; el dueño carga el de cualquiera. Sin esto,
  -- un barbero podría anotarle cortes a un compañero y ensuciarle la
  -- liquidación.
  if not public.es_admin(p_empresa)
     and not (v_prof.user_id is not null and v_prof.user_id = auth.uid()) then
    raise exception 'Solo podés cargar tus propios servicios.' using errcode = '42501';
  end if;

  select * into v_prod from public.productos
  where id = p_producto and empresa_id = p_empresa and activo;
  if not found then
    raise exception 'Ese servicio no existe en esta cuenta.' using errcode = 'P0002';
  end if;

  -- Un servicio no lleva stock. Lo que sí lo lleva —cera, shampoo— es una
  -- venta de mercadería y va por la puerta de siempre: tiene su propio costo
  -- y su propio renglón en el panel.
  if v_prod.controla_stock then
    raise exception 'Eso es un producto con stock: cobralo como una venta normal.' using errcode = '22023';
  end if;

  v_monto := coalesce(nullif(p_precio, 0), public.precio_de_servicio(p_profesional, p_producto));
  if v_monto is null or v_monto <= 0 then
    raise exception 'Falta el precio del servicio.' using errcode = '22023';
  end if;

  select moneda into v_moneda from public.empresas where id = p_empresa;
  v_dec := public.decimales_de(v_moneda);

  -- El redondeo va sobre la parte del PROFESIONAL y el resto queda para el
  -- local. Nunca las dos por separado: ahí las partes dejan de sumar el total
  -- y aparece —o desaparece— plata que nadie cobró.
  v_prof_par := case v_prof.reparto
    when 'comision' then round(v_monto * v_prof.porcentaje / 100, v_dec)
    when 'alquiler' then v_monto
    else 0::numeric
  end;
  v_local := v_monto - v_prof_par;

  v_fecha := coalesce(p_fecha, public.hoy_empresa(p_empresa));

  -- Con alquiler de silla la plata nunca fue del local: queda el registro del
  -- corte, pero no se crea ninguna venta. Lo que el local factura es la
  -- mensualidad, que se carga como cualquier otro ingreso.
  if v_prof.reparto <> 'alquiler' then
    v_mov := public.registrar_venta(
      p_empresa,
      jsonb_build_array(jsonb_build_object(
        'nombre',          v_prod.nombre,
        'cantidad',        1,
        'precio_unitario', v_monto,
        'costo_unitario',  v_prof_par
      )),
      v_fecha,
      trim(v_prod.nombre || case when coalesce(trim(p_cliente), '') <> ''
                                 then ' · ' || trim(p_cliente) else '' end),
      p_metodo_pago,
      left(coalesce(trim(p_cliente), ''), 80),
      p_notas,
      coalesce(p_origen, 'manual'),
      0
    );
  end if;

  insert into public.turnos_atribucion (
    empresa_id, profesional_id, movimiento_id, producto_id, servicio,
    fecha, monto_cobrado, parte_profesional, parte_local, reparto, creado_por
  )
  values (
    p_empresa, p_profesional, v_mov, p_producto, v_prod.nombre,
    v_fecha, v_monto, v_prof_par, v_local, v_prof.reparto, auth.uid()
  )
  returning id into v_id;

  return jsonb_build_object(
    'atribucion',        v_id,
    'movimiento',        v_mov,
    'monto',             v_monto,
    'parte_profesional', v_prof_par,
    'parte_local',       v_local,
    'reparto',           v_prof.reparto
  );
end $fn$;

revoke all on function public.registrar_servicio(uuid, uuid, uuid, numeric, date, text, text, text, origen_captura)
  from public, anon;
grant execute on function public.registrar_servicio(uuid, uuid, uuid, numeric, date, text, text, text, origen_captura)
  to authenticated;


-- ############################################################
-- ##  035_reparto_c_liquidacion.sql
-- ############################################################

-- ORDEN · Migración 035 · El reparto · pagar y mirar
--
-- Lo que el dueño quiere el viernes: cuánto produjo cada uno, cuánto le toca,
-- cuánto ya le pagó y cuánto falta. Y lo que quiere el barbero: lo suyo, sin
-- ver el margen del local ni lo que producen los demás.

-- ============================================================
-- 1. LOS PAGOS AL PROFESIONAL
--
--    Entre el corte y el pago, la parte del barbero está en la caja pero no
--    es del local. El saldo sale de restar —lo que le corresponde menos lo
--    que ya cobró— y por eso no se guarda: un saldo calculado nunca se
--    desincroniza. Lo que sí hay que guardar es cada pago, y que ese pago sea
--    un gasto de verdad, porque ahí la plata sale de la caja.
-- ============================================================
create table if not exists public.turnos_pago (
  id             uuid primary key default gen_random_uuid(),
  empresa_id     uuid not null references public.empresas (id) on delete cascade,
  profesional_id uuid not null references public.turnos_profesional (id) on delete restrict,
  movimiento_id  uuid references public.movimientos (id) on delete set null,
  monto          numeric(14,2) not null check (monto > 0),
  fecha          date not null,
  notas          text not null default '',
  creado_por     uuid references auth.users (id) on delete set null,
  created_at     timestamptz not null default now()
);

create index if not exists turnos_pago_idx
  on public.turnos_pago (empresa_id, profesional_id, fecha desc);

alter table public.turnos_pago enable row level security;

drop policy if exists turnos_pago_select on public.turnos_pago;
create policy turnos_pago_select on public.turnos_pago
  for select to authenticated using (public.es_admin(empresa_id));

revoke all on public.turnos_pago from anon, authenticated;
grant select on public.turnos_pago to authenticated;

drop trigger if exists cuenta_activa_turnos_pago on public.turnos_pago;
create trigger cuenta_activa_turnos_pago
  before insert or update on public.turnos_pago
  for each row execute function public.exigir_cuenta_activa();

create or replace function public.pagar_profesional(
  p_empresa     uuid,
  p_profesional uuid,
  p_monto       numeric,
  p_fecha       date default null,
  p_notas       text default ''
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_nombre text;
  v_fecha  date;
  v_mov    uuid;
  v_id     uuid;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede pagar al equipo.' using errcode = '42501';
  end if;

  select nombre into v_nombre from public.turnos_profesional
  where id = p_profesional and empresa_id = p_empresa;
  if v_nombre is null then
    raise exception 'Esa persona no está en el equipo de esta cuenta.' using errcode = 'P0002';
  end if;

  if coalesce(p_monto, 0) <= 0 then
    raise exception 'El pago tiene que ser mayor que cero.' using errcode = '22023';
  end if;

  v_fecha := coalesce(p_fecha, public.hoy_empresa(p_empresa));

  -- El pago es un gasto de verdad, con el nombre de la persona en la
  -- descripción. No es contabilidad paralela: sale en el panel, en los
  -- reportes y en el Excel como cualquier otro gasto.
  insert into public.movimientos (
    empresa_id, tipo, estado, fecha, descripcion, categoria,
    subtotal, descuento, monto, costo_total, metodo_pago, contraparte, origen, creado_por
  )
  values (
    p_empresa, 'gasto', 'activo', v_fecha,
    'Pago a ' || v_nombre, 'Sueldos',
    p_monto, 0, p_monto, 0, 'efectivo', v_nombre, 'manual', auth.uid()
  )
  returning id into v_mov;

  insert into public.turnos_pago (empresa_id, profesional_id, movimiento_id, monto, fecha, notas, creado_por)
  values (p_empresa, p_profesional, v_mov, p_monto, v_fecha, left(coalesce(p_notas, ''), 200), auth.uid())
  returning id into v_id;

  return jsonb_build_object('pago', v_id, 'movimiento', v_mov);
end $fn$;

revoke all on function public.pagar_profesional(uuid, uuid, numeric, date, text) from public, anon;
grant execute on function public.pagar_profesional(uuid, uuid, numeric, date, text) to authenticated;

-- ============================================================
-- 2. EL PANEL DEL PROPIETARIO
--
--    Un solo número —«te quedaron 650.000»— esconde justo lo que necesita
--    saber. Un peso que entró por sus propias manos y uno que entró por la
--    comisión de un empleado son plata de naturaleza distinta.
--
--    LOS TRES PRIMEROS RENGLONES SUMAN EXACTAMENTE `ventas − costo_total`,
--    que es la ganancia bruta que el panel ya calcula. No es casualidad: cada
--    venta cae en uno y solo uno de los tres, y aporta su propia ganancia
--    bruta. Un desglose que no cierra con el total es peor que no tener
--    desglose, porque obliga a elegir a cuál de los dos creerle.
-- ============================================================
create or replace function public.resumen_reparto(
  p_empresa uuid,
  p_desde   date,
  p_hasta   date
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_mios       numeric := 0;
  v_equipo     numeric := 0;
  v_mercaderia numeric := 0;
  v_ingresos   numeric := 0;
  v_detalle    jsonb;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'No tenés acceso a estos números.' using errcode = '42501';
  end if;

  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  -- Renglones 1 y 2: lo que le queda al local de cada corte, separando los
  -- que hizo con sus propias manos de los que hizo su equipo.
  select
    coalesce(sum(a.parte_local) filter (where p.user_id is not null and p.user_id = auth.uid()), 0),
    coalesce(sum(a.parte_local) filter (where p.user_id is null or p.user_id <> auth.uid()), 0)
  into v_mios, v_equipo
  from public.turnos_atribucion a
  join public.turnos_profesional p on p.id = a.profesional_id
  where a.empresa_id = p_empresa
    and a.fecha between p_desde and p_hasta
    and a.movimiento_id is not null
    and exists (select 1 from public.movimientos m
                where m.id = a.movimiento_id and m.estado = 'activo');

  -- Renglón 3: todo lo demás que se vendió. Cera, shampoo, peines: precio
  -- menos lo que costó. Son las ventas SIN atribución, así que ningún corte
  -- se cuenta dos veces.
  select coalesce(sum(m.monto - m.costo_total), 0) into v_mercaderia
  from public.movimientos m
  where m.empresa_id = p_empresa
    and m.tipo = 'venta' and m.estado = 'activo'
    and m.fecha between p_desde and p_hasta
    and not exists (select 1 from public.turnos_atribucion a where a.movimiento_id = m.id);

  -- Renglón 4: lo que entró sin ser una venta. Acá cae el alquiler de las
  -- sillas de quien se queda con el 100% de sus cortes.
  select coalesce(sum(m.monto), 0) into v_ingresos
  from public.movimientos m
  where m.empresa_id = p_empresa
    and m.tipo = 'ingreso' and m.estado = 'activo'
    and m.fecha between p_desde and p_hasta;

  -- El detalle de cada corte, para que el número se pueda verificar. A un
  -- número sobre su propia plata que no puede verificar, nadie le cree.
  select coalesce(jsonb_agg(x order by (x->>'fecha') desc, (x->>'creado') desc), '[]'::jsonb)
  into v_detalle
  from (
    select jsonb_build_object(
      'id',                a.id,
      'profesional',       p.nombre,
      'servicio',          a.servicio,
      'fecha',             a.fecha,
      'creado',            a.created_at,
      'monto',             a.monto_cobrado,
      'parte_profesional', a.parte_profesional,
      'parte_local',       a.parte_local,
      'reparto',           a.reparto,
      'anulado',           a.movimiento_id is not null and not exists (
                             select 1 from public.movimientos m
                             where m.id = a.movimiento_id and m.estado = 'activo')
    ) as x
    from public.turnos_atribucion a
    join public.turnos_profesional p on p.id = a.profesional_id
    where a.empresa_id = p_empresa and a.fecha between p_desde and p_hasta
  ) t;

  return jsonb_build_object(
    'mis_cortes',      v_mios,
    'de_mi_equipo',    v_equipo,
    'mercaderia',      v_mercaderia,
    'otros_ingresos',  v_ingresos,
    -- Los tres primeros son la ganancia bruta; el cuarto se suma aparte
    -- porque no viene de una venta.
    'ganancia_bruta',  v_mios + v_equipo + v_mercaderia,
    'total',           v_mios + v_equipo + v_mercaderia + v_ingresos,
    'cortes',          v_detalle
  );
end $fn$;

revoke all on function public.resumen_reparto(uuid, date, date) from public, anon;
grant execute on function public.resumen_reparto(uuid, date, date) to authenticated;

-- ============================================================
-- 3. LA LIQUIDACIÓN
--
--    Por profesional y por período: cuántos cortes, cuánto cobró, cuánto le
--    toca, cuánto ya se le pagó y cuánto falta. Es un reporte sobre datos que
--    ya están guardados, no plata nueva.
-- ============================================================
create or replace function public.liquidacion(
  p_empresa uuid,
  p_desde   date,
  p_hasta   date
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_res jsonb;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'No tenés acceso a estos números.' using errcode = '42501';
  end if;

  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  select coalesce(jsonb_agg(x order by (x->>'le_toca')::numeric desc), '[]'::jsonb)
  into v_res
  from (
    select jsonb_build_object(
      'id',         p.id,
      'nombre',     p.nombre,
      'reparto',    p.reparto,
      'porcentaje', p.porcentaje,
      'activo',     p.activo,
      'cortes',     coalesce(c.cortes, 0),
      'cobrado',    coalesce(c.cobrado, 0),
      'le_toca',    coalesce(c.suyo, 0),
      'del_local',  coalesce(c.local, 0),
      'pagado',     coalesce(g.pagado, 0),
      -- Lo que todavía está en la caja del local pero es de él.
      'le_debe',    coalesce(c.suyo, 0) - coalesce(g.pagado, 0)
    ) as x
    from public.turnos_profesional p
    left join lateral (
      select count(*)::int              as cortes,
             sum(a.monto_cobrado)       as cobrado,
             sum(a.parte_profesional)   as suyo,
             sum(a.parte_local)         as local
      from public.turnos_atribucion a
      where a.profesional_id = p.id
        and a.fecha between p_desde and p_hasta
        -- Un corte anulado no se le paga a nadie.
        and (a.movimiento_id is null
             or exists (select 1 from public.movimientos m
                        where m.id = a.movimiento_id and m.estado = 'activo'))
    ) c on true
    left join lateral (
      select sum(t.monto) as pagado
      from public.turnos_pago t
      where t.profesional_id = p.id and t.fecha between p_desde and p_hasta
    ) g on true
    where p.empresa_id = p_empresa
      -- Los desactivados solo aparecen si tuvieron movimiento en el período:
      -- si no, la lista se llena de gente que ya no trabaja ahí.
      and (p.activo or coalesce(c.cortes, 0) > 0 or coalesce(g.pagado, 0) > 0)
  ) t;

  return v_res;
end $fn$;

revoke all on function public.liquidacion(uuid, date, date) from public, anon;
grant execute on function public.liquidacion(uuid, date, date) to authenticated;

-- ============================================================
-- 4. LO QUE VE EL PROFESIONAL
--
--    Sus cortes y su parte. Nada del margen del local, nada de los demás.
--    Es una función y no una policy porque lo que hay que esconder es una
--    COLUMNA —`parte_local`— y RLS filtra filas, no columnas.
-- ============================================================
create or replace function public.mis_servicios(
  p_empresa uuid,
  p_desde   date,
  p_hasta   date
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_prof   uuid;
  v_cortes jsonb;
  v_total  numeric := 0;
  v_pagado numeric := 0;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  select id into v_prof from public.turnos_profesional
  where empresa_id = p_empresa and user_id = auth.uid();

  if v_prof is null then
    return jsonb_build_object('es_profesional', false, 'cortes', '[]'::jsonb,
                              'le_toca', 0, 'pagado', 0, 'le_deben', 0);
  end if;

  select
    coalesce(jsonb_agg(jsonb_build_object(
      'fecha',    a.fecha,
      'servicio', a.servicio,
      'monto',    a.monto_cobrado,
      'tuyo',     a.parte_profesional
    ) order by a.fecha desc, a.created_at desc), '[]'::jsonb),
    coalesce(sum(a.parte_profesional), 0)
  into v_cortes, v_total
  from public.turnos_atribucion a
  where a.profesional_id = v_prof
    and a.fecha between p_desde and p_hasta
    and (a.movimiento_id is null
         or exists (select 1 from public.movimientos m
                    where m.id = a.movimiento_id and m.estado = 'activo'));

  select coalesce(sum(t.monto), 0) into v_pagado
  from public.turnos_pago t
  where t.profesional_id = v_prof and t.fecha between p_desde and p_hasta;

  return jsonb_build_object(
    'es_profesional', true,
    'cortes',   v_cortes,
    'le_toca',  v_total,
    'pagado',   v_pagado,
    'le_deben', v_total - v_pagado
  );
end $fn$;

revoke all on function public.mis_servicios(uuid, date, date) from public, anon;
grant execute on function public.mis_servicios(uuid, date, date) to authenticated;


-- ############################################################
-- ##  036_agenda_a_horarios.sql
-- ############################################################

-- ORDEN · Migración 036 · La agenda: cuándo trabaja cada uno
--
-- Segunda pieza del módulo de turnos. La primera fue el reparto —quién cobra
-- qué y cómo se divide— y esta contesta la otra mitad: cuándo está libre.
--
-- TRES TABLAS Y NO UNA
--
--   · `turnos_servicio`  cuánto dura cada servicio, y si se puede reservar.
--   · `turnos_horario`   lo que se repite todas las semanas.
--   · `turnos_excepcion` el día que no es como los demás.
--
-- Guardar el horario y las excepciones juntos obligaría a reescribir la
-- semana entera cada feriado. Separarlos permite que el horario sea la regla
-- y la excepción sea la excepción, que es como lo piensa la persona.
--
-- LAS HORAS SE GUARDAN COMO HORA LOCAL, NO COMO INSTANTE
--
-- «Abro a las 8» es una regla sobre el reloj de la pared, no sobre un momento
-- del tiempo: sigue siendo a las 8 en verano y en invierno. Guardarla como
-- instante la movería sola con cada cambio de horario. La conversión a
-- instante se hace al calcular los huecos de un día concreto, usando la zona
-- de la empresa — que desde la 032 es la de la empresa y no Asunción.

-- ============================================================
-- 1. QUÉ SE PUEDE RESERVAR Y CUÁNTO DURA
--
--    Un servicio de la lista de precios no es automáticamente reservable: el
--    dueño puede cobrar «retoque de barba» sin querer que ocupe un turno.
--    Y sin duración no hay agenda posible: los huecos salen de ahí.
-- ============================================================
create table if not exists public.turnos_servicio (
  empresa_id   uuid not null references public.empresas (id) on delete cascade,
  producto_id  uuid not null references public.productos (id) on delete cascade,
  duracion_min integer not null default 30
               check (duracion_min between 5 and 480),
  -- Si está en falso, se puede cobrar pero no aparece para reservar.
  reservable   boolean not null default true,
  updated_at   timestamptz not null default now(),
  primary key (producto_id)
);

create index if not exists turnos_servicio_empresa_idx
  on public.turnos_servicio (empresa_id) where reservable;

-- ============================================================
-- 2. EL HORARIO QUE SE REPITE
--
--    Varias filas por día: quien corta de 8 a 12 y de 15 a 20 carga dos
--    franjas, y el hueco del mediodía queda cerrado sin tener que explicarlo.
--    Que sea «cerrado» y no «ocupado» importa: la página pública no muestra
--    el mediodía como un turno tomado, simplemente no está.
-- ============================================================
create table if not exists public.turnos_horario (
  id             uuid primary key default gen_random_uuid(),
  empresa_id     uuid not null references public.empresas (id) on delete cascade,
  profesional_id uuid not null references public.turnos_profesional (id) on delete cascade,
  -- 0 = domingo, igual que `extract(dow from fecha)`.
  dia_semana     smallint not null check (dia_semana between 0 and 6),
  desde          time not null,
  hasta          time not null,
  activo         boolean not null default true,
  created_at     timestamptz not null default now(),

  constraint franja_con_sentido check (hasta > desde)
);

create index if not exists turnos_horario_idx
  on public.turnos_horario (profesional_id, dia_semana) where activo;

-- ============================================================
-- 3. EL DÍA QUE NO ES COMO LOS DEMÁS
--
--    `profesional_id` nulo = vale para todo el local (un feriado). Con
--    profesional = solo esa persona (se tomó el día).
-- ============================================================
create table if not exists public.turnos_excepcion (
  id             uuid primary key default gen_random_uuid(),
  empresa_id     uuid not null references public.empresas (id) on delete cascade,
  profesional_id uuid references public.turnos_profesional (id) on delete cascade,
  fecha          date not null,
  cerrado        boolean not null default true,
  desde          time,
  hasta          time,
  motivo         text not null default '',
  created_at     timestamptz not null default now(),

  -- Si no está cerrado, tiene que decir de cuándo a cuándo. Una excepción
  -- abierta sin horario no significa nada y dejaría la agenda en blanco.
  constraint excepcion_coherente check (
    cerrado or (desde is not null and hasta is not null and hasta > desde)
  )
);

create unique index if not exists turnos_excepcion_una_por_dia
  on public.turnos_excepcion (empresa_id, fecha, coalesce(profesional_id, '00000000-0000-0000-0000-000000000000'::uuid));

-- ============================================================
-- 4. PERMISOS
--
--    Los horarios los lee cualquier miembro: son la agenda del local, no un
--    secreto. Escribir pasa por funciones, como todo lo demás.
-- ============================================================
alter table public.turnos_servicio  enable row level security;
alter table public.turnos_horario   enable row level security;
alter table public.turnos_excepcion enable row level security;

drop policy if exists turnos_servicio_select on public.turnos_servicio;
create policy turnos_servicio_select on public.turnos_servicio
  for select to authenticated using (public.es_miembro(empresa_id));

drop policy if exists turnos_horario_select on public.turnos_horario;
create policy turnos_horario_select on public.turnos_horario
  for select to authenticated using (public.es_miembro(empresa_id));

drop policy if exists turnos_excepcion_select on public.turnos_excepcion;
create policy turnos_excepcion_select on public.turnos_excepcion
  for select to authenticated using (public.es_miembro(empresa_id));

revoke all on public.turnos_servicio  from anon, authenticated;
revoke all on public.turnos_horario   from anon, authenticated;
revoke all on public.turnos_excepcion from anon, authenticated;

grant select on public.turnos_servicio  to authenticated;
grant select on public.turnos_horario   to authenticated;
grant select on public.turnos_excepcion to authenticated;

do $$
declare v_tabla text;
begin
  foreach v_tabla in array array['turnos_servicio', 'turnos_horario', 'turnos_excepcion'] loop
    execute format('drop trigger if exists %I on public.%I',
                   'cuenta_activa_' || v_tabla, v_tabla);
    execute format(
      'create trigger %I before insert or update on public.%I '
      || 'for each row execute function public.exigir_cuenta_activa()',
      'cuenta_activa_' || v_tabla, v_tabla);
  end loop;
end $$;

-- ============================================================
-- 5. ESCRIBIR
--
--    El horario lo maneja el propio profesional, igual que su precio: es SU
--    agenda. El dueño también, porque muchos no van a tener cuenta.
-- ============================================================
create or replace function public.puede_agendar(p_empresa uuid, p_profesional uuid)
returns boolean language sql stable security definer set search_path = public as $fn$
  select public.es_admin(p_empresa) or exists (
    select 1 from public.turnos_profesional p
    where p.id = p_profesional and p.empresa_id = p_empresa
      and p.user_id is not null and p.user_id = auth.uid()
  );
$fn$;

revoke all on function public.puede_agendar(uuid, uuid) from public, anon;
grant execute on function public.puede_agendar(uuid, uuid) to authenticated;

create or replace function public.guardar_servicio_agenda(
  p_empresa   uuid,
  p_producto  uuid,
  p_duracion  integer,
  p_reservable boolean default true
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede definir los servicios.' using errcode = '42501';
  end if;

  if not exists (select 1 from public.productos
                 where id = p_producto and empresa_id = p_empresa and not controla_stock) then
    raise exception 'Eso no es un servicio de esta cuenta.' using errcode = 'P0002';
  end if;

  if coalesce(p_duracion, 0) < 5 or p_duracion > 480 then
    raise exception 'La duración tiene que estar entre 5 minutos y 8 horas.' using errcode = '22023';
  end if;

  insert into public.turnos_servicio (empresa_id, producto_id, duracion_min, reservable)
  values (p_empresa, p_producto, p_duracion, coalesce(p_reservable, true))
  on conflict (producto_id) do update
    set duracion_min = excluded.duracion_min,
        reservable = excluded.reservable,
        updated_at = now();

  return jsonb_build_object('guardado', true);
end $fn$;

revoke all on function public.guardar_servicio_agenda(uuid, uuid, integer, boolean) from public, anon;
grant execute on function public.guardar_servicio_agenda(uuid, uuid, integer, boolean) to authenticated;

create or replace function public.guardar_horario(
  p_empresa     uuid,
  p_profesional uuid,
  p_dia         integer,
  p_desde       time,
  p_hasta       time,
  p_id          uuid default null
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare v_id uuid;
begin
  if not public.puede_agendar(p_empresa, p_profesional) then
    raise exception 'Solo podés cambiar tu propio horario.' using errcode = '42501';
  end if;

  if p_dia is null or p_dia < 0 or p_dia > 6 then
    raise exception 'Ese día de la semana no existe.' using errcode = '22023';
  end if;

  if p_desde is null or p_hasta is null or p_hasta <= p_desde then
    raise exception 'La hora de cierre tiene que ser posterior a la de apertura.' using errcode = '22023';
  end if;

  -- Dos franjas del mismo día que se pisan dejarían huecos duplicados en la
  -- página pública: el mismo turno ofrecido dos veces.
  if exists (
    select 1 from public.turnos_horario h
    where h.profesional_id = p_profesional and h.dia_semana = p_dia and h.activo
      and (p_id is null or h.id <> p_id)
      and h.desde < p_hasta and p_desde < h.hasta
  ) then
    raise exception 'Ese horario se superpone con otro del mismo día.' using errcode = '23505';
  end if;

  if p_id is null then
    insert into public.turnos_horario (empresa_id, profesional_id, dia_semana, desde, hasta)
    values (p_empresa, p_profesional, p_dia, p_desde, p_hasta)
    returning id into v_id;
  else
    update public.turnos_horario
    set dia_semana = p_dia, desde = p_desde, hasta = p_hasta
    where id = p_id and empresa_id = p_empresa and profesional_id = p_profesional
    returning id into v_id;

    if v_id is null then
      raise exception 'Ese horario no existe.' using errcode = 'P0002';
    end if;
  end if;

  return v_id;
end $fn$;

revoke all on function public.guardar_horario(uuid, uuid, integer, time, time, uuid) from public, anon;
grant execute on function public.guardar_horario(uuid, uuid, integer, time, time, uuid) to authenticated;

create or replace function public.borrar_horario(p_empresa uuid, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare v_prof uuid;
begin
  select profesional_id into v_prof from public.turnos_horario
  where id = p_id and empresa_id = p_empresa;
  if v_prof is null then
    raise exception 'Ese horario no existe.' using errcode = 'P0002';
  end if;

  if not public.puede_agendar(p_empresa, v_prof) then
    raise exception 'Solo podés cambiar tu propio horario.' using errcode = '42501';
  end if;

  delete from public.turnos_horario where id = p_id and empresa_id = p_empresa;
  return jsonb_build_object('borrado', true);
end $fn$;

revoke all on function public.borrar_horario(uuid, uuid) from public, anon;
grant execute on function public.borrar_horario(uuid, uuid) to authenticated;

-- Un feriado lo pone el dueño; el día libre de alguien, esa persona.
create or replace function public.guardar_excepcion(
  p_empresa     uuid,
  p_fecha       date,
  p_cerrado     boolean default true,
  p_profesional uuid default null,
  p_desde       time default null,
  p_hasta       time default null,
  p_motivo      text default ''
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare v_id uuid;
begin
  -- Sin profesional es un feriado del local: eso solo lo decide el dueño.
  if p_profesional is null then
    if not public.es_admin(p_empresa) then
      raise exception 'Solo el dueño de la cuenta puede cerrar el local.' using errcode = '42501';
    end if;
  elsif not public.puede_agendar(p_empresa, p_profesional) then
    raise exception 'Solo podés cambiar tu propia agenda.' using errcode = '42501';
  end if;

  if p_fecha is null then
    raise exception 'Falta la fecha.' using errcode = '22023';
  end if;

  if not coalesce(p_cerrado, true)
     and (p_desde is null or p_hasta is null or p_hasta <= p_desde) then
    raise exception 'Si ese día abrís, decí de cuándo a cuándo.' using errcode = '22023';
  end if;

  insert into public.turnos_excepcion (empresa_id, profesional_id, fecha, cerrado, desde, hasta, motivo)
  values (p_empresa, p_profesional, p_fecha, coalesce(p_cerrado, true),
          case when coalesce(p_cerrado, true) then null else p_desde end,
          case when coalesce(p_cerrado, true) then null else p_hasta end,
          left(coalesce(p_motivo, ''), 100))
  on conflict (empresa_id, fecha, coalesce(profesional_id, '00000000-0000-0000-0000-000000000000'::uuid))
  do update set cerrado = excluded.cerrado, desde = excluded.desde,
                hasta = excluded.hasta, motivo = excluded.motivo
  returning id into v_id;

  return v_id;
end $fn$;

revoke all on function public.guardar_excepcion(uuid, date, boolean, uuid, time, time, text) from public, anon;
grant execute on function public.guardar_excepcion(uuid, date, boolean, uuid, time, time, text) to authenticated;

create or replace function public.borrar_excepcion(p_empresa uuid, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare v_prof uuid; v_hay boolean;
begin
  select profesional_id, true into v_prof, v_hay from public.turnos_excepcion
  where id = p_id and empresa_id = p_empresa;
  if not coalesce(v_hay, false) then
    raise exception 'Esa excepción no existe.' using errcode = 'P0002';
  end if;

  if v_prof is null then
    if not public.es_admin(p_empresa) then
      raise exception 'Solo el dueño de la cuenta puede tocar los feriados.' using errcode = '42501';
    end if;
  elsif not public.puede_agendar(p_empresa, v_prof) then
    raise exception 'Solo podés cambiar tu propia agenda.' using errcode = '42501';
  end if;

  delete from public.turnos_excepcion where id = p_id and empresa_id = p_empresa;
  return jsonb_build_object('borrado', true);
end $fn$;

revoke all on function public.borrar_excepcion(uuid, uuid) from public, anon;
grant execute on function public.borrar_excepcion(uuid, uuid) to authenticated;


-- ############################################################
-- ##  037_agenda_b_reservas.sql
-- ############################################################

-- ORDEN · Migración 037 · Los huecos y la reserva
--
-- El motor de la agenda. Dos cosas: calcular qué huecos quedan libres un día
-- dado, y tomar uno sin que dos personas se queden con el mismo.

-- ============================================================
-- 1. LOS HUECOS DE UN DÍA
--
--    Sale de tres capas, en este orden de prioridad:
--
--      1. la excepción de ESA persona para ese día (se tomó el día);
--      2. la excepción del LOCAL para ese día (feriado);
--      3. el horario que se repite esa semana.
--
--    La primera que aparece manda. Sin esa prioridad, un feriado del local
--    taparía el día que alguien decidió abrir igual.
--
--    Los huecos se cortan del tamaño del servicio elegido, no de una grilla
--    fija de una hora: si el corte con barba dura 45 minutos, los turnos van
--    cada 45 minutos.
-- ============================================================
create or replace function public.huecos_del_dia(
  p_profesional uuid,
  p_fecha       date,
  p_producto    uuid
)
returns table (inicia timestamptz, termina timestamptz)
language plpgsql stable security definer set search_path = public as $fn$
declare
  v_empresa uuid;
  v_zona    text;
  v_dur     integer;
  v_ahora   timestamptz := now();
begin
  select p.empresa_id, coalesce(e.zona_horaria, 'America/Asuncion')
  into v_empresa, v_zona
  from public.turnos_profesional p
  join public.empresas e on e.id = p.empresa_id
  where p.id = p_profesional and p.activo;

  if v_empresa is null then
    return;
  end if;

  select coalesce(s.duracion_min, 30) into v_dur
  from public.turnos_servicio s
  where s.producto_id = p_producto and s.empresa_id = v_empresa and s.reservable;

  -- Un servicio que no está marcado como reservable no ofrece huecos. No es
  -- lo mismo que no tener agenda: es que ese servicio no se agenda.
  if v_dur is null then
    return;
  end if;

  return query
  with excepcion as (
    -- La de la persona gana sobre la del local; por eso el order by.
    select x.cerrado, x.desde, x.hasta
    from public.turnos_excepcion x
    where x.empresa_id = v_empresa and x.fecha = p_fecha
      and (x.profesional_id = p_profesional or x.profesional_id is null)
    order by x.profesional_id nulls last
    limit 1
  ),
  ventanas as (
    -- Con excepción abierta, la ventana es la de la excepción.
    select (p_fecha + e.desde)::timestamp as ini, (p_fecha + e.hasta)::timestamp as fin
    from excepcion e
    where not e.cerrado
    union all
    -- Sin ninguna excepción, el horario de siempre.
    select (p_fecha + h.desde)::timestamp, (p_fecha + h.hasta)::timestamp
    from public.turnos_horario h
    where h.profesional_id = p_profesional
      and h.activo
      and h.dia_semana = extract(dow from p_fecha)::smallint
      and not exists (select 1 from excepcion)
  ),
  puntos as (
    select generate_series(
             v.ini,
             v.fin - (v_dur || ' minutes')::interval,
             (v_dur || ' minutes')::interval
           ) as arranca
    from ventanas v
  )
  select
    (pt.arranca at time zone v_zona) as inicia,
    ((pt.arranca + (v_dur || ' minutes')::interval) at time zone v_zona) as termina
  from puntos pt
  where
    -- Un turno que ya pasó no se ofrece.
    (pt.arranca at time zone v_zona) > v_ahora
    -- Ni uno que se pisa con algo ya reservado.
    and not exists (
      select 1 from public.turnos_reserva r
      where r.profesional_id = p_profesional
        and r.estado in ('pendiente', 'confirmada')
        and r.inicia < ((pt.arranca + (v_dur || ' minutes')::interval) at time zone v_zona)
        and (pt.arranca at time zone v_zona) < r.termina
    )
  order by 1;
end $fn$;

-- ============================================================
-- 2. LA RESERVA
--
--    El horario se guarda como INSTANTE y no como «10:30 del jueves». Un
--    texto con la hora se mueve solo el día que cambia la zona de la cuenta;
--    un instante no se mueve nunca.
-- ============================================================
create table if not exists public.turnos_reserva (
  id               uuid primary key default gen_random_uuid(),
  empresa_id       uuid not null references public.empresas (id) on delete cascade,
  profesional_id   uuid not null references public.turnos_profesional (id) on delete cascade,
  producto_id      uuid not null references public.productos (id) on delete restrict,
  inicia           timestamptz not null,
  termina          timestamptz not null,
  cliente_nombre   text not null check (char_length(trim(cliente_nombre)) between 1 and 80),
  cliente_telefono text not null default '',
  estado           text not null default 'pendiente'
                   check (estado in ('pendiente', 'confirmada', 'atendida', 'cancelada', 'no_vino')),
  -- El corte que se cobró, cuando se atendió.
  atribucion_id    uuid references public.turnos_atribucion (id) on delete set null,
  -- El secreto del enlace para cancelar. Es lo único que el cliente guarda.
  token            uuid not null default gen_random_uuid(),
  origen           text not null default 'local' check (origen in ('local', 'publico')),
  creada_por       uuid references auth.users (id) on delete set null,
  created_at       timestamptz not null default now(),

  constraint reserva_con_sentido check (termina > inicia)
);

create index if not exists turnos_reserva_agenda_idx
  on public.turnos_reserva (profesional_id, inicia)
  where estado in ('pendiente', 'confirmada');
create index if not exists turnos_reserva_empresa_idx
  on public.turnos_reserva (empresa_id, inicia desc);
create unique index if not exists turnos_reserva_token_idx
  on public.turnos_reserva (token);

alter table public.turnos_reserva enable row level security;

-- Los datos del cliente son de terceros que nunca se registraron en Orden.
-- Los ve quien trabaja en el local, y nadie más.
drop policy if exists turnos_reserva_select on public.turnos_reserva;
create policy turnos_reserva_select on public.turnos_reserva
  for select to authenticated using (public.es_miembro(empresa_id));

revoke all on public.turnos_reserva from anon, authenticated;
grant select on public.turnos_reserva to authenticated;

drop trigger if exists cuenta_activa_turnos_reserva on public.turnos_reserva;
create trigger cuenta_activa_turnos_reserva
  before insert or update on public.turnos_reserva
  for each row execute function public.exigir_cuenta_activa();

-- ============================================================
-- 3. TOMAR UN TURNO
--
--    QUE DOS PERSONAS NO SE QUEDEN CON EL MISMO HUECO
--
--    `for update` sobre la fila del profesional serializa todas las reservas
--    de esa persona: la segunda transacción espera a que la primera termine y
--    recién entonces mira si el hueco sigue libre. Es el mismo recurso que ya
--    usa `anular_movimiento` para que dos anulaciones simultáneas no se pisen.
--
--    Un chequeo en el navegador pierde esa carrera siempre: entre que
--    pregunta y escribe, el otro ya reservó.
-- ============================================================
create or replace function public.reservar(
  p_empresa     uuid,
  p_profesional uuid,
  p_producto    uuid,
  p_inicia      timestamptz,
  p_nombre      text,
  p_telefono    text default '',
  p_origen      text default 'local'
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_zona   text;
  v_fecha  date;
  v_libre  boolean;
  v_fin    timestamptz;
  v_id     uuid;
  v_token  uuid;
begin
  if char_length(trim(coalesce(p_nombre, ''))) = 0 then
    raise exception 'Falta el nombre de quien reserva.' using errcode = '22023';
  end if;

  if p_inicia is null then
    raise exception 'Falta el horario.' using errcode = '22023';
  end if;

  -- Esta puerta es la del LOCAL: la usa quien trabaja ahí para anotar a
  -- alguien que llamó por teléfono. La puerta pública —la del link que el
  -- dueño comparte— es otra función, con sus propios límites, y por eso acá
  -- se exige pertenecer. Sin esta línea, cualquiera con una cuenta de Orden
  -- podía llenarle la agenda a un negocio ajeno.
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  -- El candado. Todo lo que sigue está serializado por profesional.
  perform 1 from public.turnos_profesional
  where id = p_profesional and empresa_id = p_empresa and activo
  for update;

  if not found then
    raise exception 'Esa persona no está en el equipo de esta cuenta.' using errcode = 'P0002';
  end if;

  select coalesce(e.zona_horaria, 'America/Asuncion') into v_zona
  from public.empresas e where e.id = p_empresa;

  v_fecha := (p_inicia at time zone v_zona)::date;

  -- Que el hueco EXISTA, no solo que esté libre. Sin esto se podría reservar
  -- a las tres de la mañana mandando el horario a mano.
  select exists (
    select 1 from public.huecos_del_dia(p_profesional, v_fecha, p_producto) h
    where h.inicia = p_inicia
  ) into v_libre;

  if not v_libre then
    raise exception 'Ese horario ya no está disponible.' using errcode = '23505';
  end if;

  select h.termina into v_fin
  from public.huecos_del_dia(p_profesional, v_fecha, p_producto) h
  where h.inicia = p_inicia;

  insert into public.turnos_reserva (
    empresa_id, profesional_id, producto_id, inicia, termina,
    cliente_nombre, cliente_telefono, origen, creada_por
  )
  values (
    p_empresa, p_profesional, p_producto, p_inicia, v_fin,
    left(trim(p_nombre), 80), left(coalesce(trim(p_telefono), ''), 40),
    case when p_origen = 'publico' then 'publico' else 'local' end,
    auth.uid()
  )
  returning id, token into v_id, v_token;

  return jsonb_build_object('reserva', v_id, 'token', v_token, 'inicia', p_inicia, 'termina', v_fin);
end $fn$;

revoke all on function public.reservar(uuid, uuid, uuid, timestamptz, text, text, text) from public, anon;
grant execute on function public.reservar(uuid, uuid, uuid, timestamptz, text, text, text) to authenticated;

-- ============================================================
-- 4. CANCELAR
--
--    Por token y sin sesión: es el enlace que el cliente guardó. Sin una
--    forma de avisar que no viene, en dos semanas la agenda está llena de
--    fantasmas y el barbero deja de creerle — que es el mismo problema que
--    una agenda vacía, pero peor, porque parece que funciona.
-- ============================================================
create or replace function public.cancelar_reserva(p_token uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare v_estado text;
begin
  select estado into v_estado from public.turnos_reserva where token = p_token;

  if v_estado is null then
    raise exception 'Esa reserva no existe.' using errcode = 'P0002';
  end if;

  if v_estado = 'cancelada' then
    return jsonb_build_object('cancelada', true, 'ya_estaba', true);
  end if;

  if v_estado <> 'pendiente' and v_estado <> 'confirmada' then
    raise exception 'Esa reserva ya no se puede cancelar.' using errcode = '22023';
  end if;

  update public.turnos_reserva set estado = 'cancelada' where token = p_token;
  return jsonb_build_object('cancelada', true);
end $fn$;

revoke all on function public.cancelar_reserva(uuid) from public, anon;
grant execute on function public.cancelar_reserva(uuid) to authenticated;

-- ============================================================
-- 5. ATENDER
--
--    Cierra el turno y cobra, en una sola transacción. El precio sale del
--    servicio reservado, no de lo que alguien tipee: si el profesional cobró
--    distinto, lo pasa explícito y queda a la vista.
-- ============================================================
create or replace function public.atender_reserva(
  p_reserva uuid,
  p_precio  numeric default null,
  p_metodo  text default 'efectivo'
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_r      public.turnos_reserva%rowtype;
  v_cobro  jsonb;
begin
  select * into v_r from public.turnos_reserva where id = p_reserva for update;
  if not found then
    raise exception 'Esa reserva no existe.' using errcode = 'P0002';
  end if;

  if not public.es_miembro(v_r.empresa_id) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if v_r.estado not in ('pendiente', 'confirmada') then
    raise exception 'Esa reserva ya se cerró.' using errcode = '23505';
  end if;

  -- LA VENTA SE FECHA HOY, NO EL DÍA DEL TURNO.
  --
  -- Parece más prolijo usar la fecha de la reserva, y es un error: un turno
  -- reservado para dentro de dos semanas crearía una venta con fecha futura,
  -- que `registrar_venta` rechaza desde la migración 002 —y hace bien, porque
  -- sería facturación que todavía no ocurrió.
  --
  -- Una venta es plata que SE MOVIÓ, y se mueve cuando el cliente paga. Que
  -- el turno estuviera agendado para otro día ya quedó guardado en la
  -- reserva; no hace falta repetirlo en la contabilidad, ni conviene.
  v_cobro := public.registrar_servicio(
    v_r.empresa_id, v_r.profesional_id, v_r.producto_id,
    p_precio, null, p_metodo, v_r.cliente_nombre, '', 'manual'
  );

  update public.turnos_reserva
  set estado = 'atendida', atribucion_id = (v_cobro->>'atribucion')::uuid
  where id = p_reserva;

  return v_cobro || jsonb_build_object('reserva', p_reserva);
end $fn$;

revoke all on function public.atender_reserva(uuid, numeric, text) from public, anon;
grant execute on function public.atender_reserva(uuid, numeric, text) to authenticated;

-- El que no vino. Sin esto la agenda de la semana que viene arrastra
-- fantasmas y deja de ser confiable.
create or replace function public.marcar_no_vino(p_reserva uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare v_emp uuid; v_estado text;
begin
  select empresa_id, estado into v_emp, v_estado
  from public.turnos_reserva where id = p_reserva;

  if v_emp is null then
    raise exception 'Esa reserva no existe.' using errcode = 'P0002';
  end if;
  if not public.es_miembro(v_emp) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if v_estado not in ('pendiente', 'confirmada') then
    raise exception 'Esa reserva ya se cerró.' using errcode = '23505';
  end if;

  update public.turnos_reserva set estado = 'no_vino' where id = p_reserva;
  return jsonb_build_object('no_vino', true);
end $fn$;

revoke all on function public.marcar_no_vino(uuid) from public, anon;
grant execute on function public.marcar_no_vino(uuid) to authenticated;

-- ============================================================
-- 6. LA AGENDA DEL DÍA
--
--    Lo que el profesional mira a la mañana: sus turnos en orden, con el
--    teléfono a un toque.
-- ============================================================
create or replace function public.agenda_del_dia(
  p_empresa uuid,
  p_fecha   date default null
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_zona  text;
  v_fecha date;
  v_res   jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select coalesce(zona_horaria, 'America/Asuncion') into v_zona
  from public.empresas where id = p_empresa;
  v_fecha := coalesce(p_fecha, public.hoy_empresa(p_empresa));

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',          r.id,
    'inicia',      r.inicia,
    'termina',     r.termina,
    'profesional', p.nombre,
    'profesional_id', r.profesional_id,
    'servicio',    pr.nombre,
    'cliente',     r.cliente_nombre,
    'telefono',    r.cliente_telefono,
    'estado',      r.estado,
    'origen',      r.origen
  ) order by r.inicia), '[]'::jsonb)
  into v_res
  from public.turnos_reserva r
  join public.turnos_profesional p on p.id = r.profesional_id
  join public.productos pr on pr.id = r.producto_id
  where r.empresa_id = p_empresa
    and (r.inicia at time zone v_zona)::date = v_fecha
    -- Una cancelada no ocupa lugar en la agenda del día.
    and r.estado <> 'cancelada';

  return v_res;
end $fn$;

revoke all on function public.agenda_del_dia(uuid, date) from public, anon;
grant execute on function public.agenda_del_dia(uuid, date) to authenticated;

revoke all on function public.huecos_del_dia(uuid, date, uuid) from public, anon;
grant execute on function public.huecos_del_dia(uuid, date, uuid) to authenticated;


-- ############################################################
-- ##  038_agenda_c_puerta_publica.sql
-- ############################################################

-- ORDEN · Migración 038 · El link público de reservas
--
-- Acá se rompe algo a propósito. La migración 012 se llama «Cerrarle la
-- puerta a `anon`», y su argumento sigue siendo bueno: el permiso no debería
-- depender de que nadie se equivoque nunca dentro del cuerpo de una función.
--
-- La página de reservas obliga a abrir esa puerta —un desconocido sin cuenta
-- tiene que poder ver los huecos y tomar uno— así que se abre del ancho
-- exacto: TRES FUNCIONES Y NADA MÁS, cada una devolviendo lo mínimo.
--
-- LO QUE LO PÚBLICO NUNCA PUEDE VER
--
--   · quién ocupa un horario tomado. La respuesta es «libre» u «ocupado»,
--     nunca de quién: si la página dijera «14:00 — Juan Pérez», el barbero
--     acabaría de publicar la agenda de sus clientes en internet;
--   · ningún dato de la empresa que no sea su nombre, dirección y mensaje;
--   · costos, márgenes, ni un solo producto con stock.
--
-- EL LINK ES PARA SIEMPRE
--
-- Una vez que está en la biografía de Instagram, en el estado de WhatsApp y
-- en cien publicaciones viejas, ya no se puede cambiar: no es una URL, es la
-- dirección del local. De ahí sale la regla más importante de este archivo,
-- que un slug liberado NUNCA se le reasigna a otro negocio. Si «barberia-juan»
-- se libera y un año después se lo damos a otro, un cliente que entra por un
-- posteo viejo termina reservando con un barbero que no eligió.

-- ============================================================
-- 1. EL LINK
-- ============================================================
create table if not exists public.turnos_publico (
  empresa_id uuid primary key references public.empresas (id) on delete cascade,
  slug       text not null unique
             check (slug ~ '^[a-z0-9]([a-z0-9-]{1,38}[a-z0-9])$'),
  activo     boolean not null default true,
  titulo     text not null default '',
  mensaje    text not null default '',
  direccion  text not null default '',
  updated_at timestamptz not null default now()
);

-- Los slugs que alguna vez existieron. No se borran nunca: es la única forma
-- de garantizar que un link viejo no lleve a otro negocio.
create table if not exists public.turnos_slug_usado (
  slug       text primary key,
  empresa_id uuid references public.empresas (id) on delete set null,
  liberado   timestamptz not null default now()
);

-- Teléfonos que el dueño no quiere volver a ver en su agenda.
create table if not exists public.turnos_bloqueo (
  empresa_id uuid not null references public.empresas (id) on delete cascade,
  telefono   text not null,
  motivo     text not null default '',
  created_at timestamptz not null default now(),
  primary key (empresa_id, telefono)
);

alter table public.turnos_publico    enable row level security;
alter table public.turnos_slug_usado enable row level security;
alter table public.turnos_bloqueo    enable row level security;

drop policy if exists turnos_publico_select on public.turnos_publico;
create policy turnos_publico_select on public.turnos_publico
  for select to authenticated using (public.es_miembro(empresa_id));

drop policy if exists turnos_bloqueo_select on public.turnos_bloqueo;
create policy turnos_bloqueo_select on public.turnos_bloqueo
  for select to authenticated using (public.es_admin(empresa_id));

revoke all on public.turnos_publico    from anon, authenticated;
revoke all on public.turnos_slug_usado from anon, authenticated;
revoke all on public.turnos_bloqueo    from anon, authenticated;

grant select on public.turnos_publico to authenticated;
grant select on public.turnos_bloqueo to authenticated;

drop trigger if exists cuenta_activa_turnos_publico on public.turnos_publico;
create trigger cuenta_activa_turnos_publico
  before insert or update on public.turnos_publico
  for each row execute function public.exigir_cuenta_activa();

-- ============================================================
-- 2. ARMAR EL SLUG
--
--    Se genera solo a partir del nombre del negocio. Si el dueño tuviera que
--    inventarlo, la mitad no lo hace nunca y el módulo no se usa.
--
--    Sin `unaccent`: esa extensión no está en todos lados, y una función que
--    depende de una extensión ausente falla en el peor momento. `translate`
--    hace el trabajo y no depende de nada.
-- ============================================================
create or replace function public.slug_de(p_texto text)
returns text language sql immutable set search_path = public as $fn$
  select nullif(
    trim(both '-' from
      regexp_replace(
        regexp_replace(
          lower(translate(coalesce(p_texto, ''),
                          'áàäâãéèëêíìïîóòöôõúùüûñçÁÀÄÂÃÉÈËÊÍÌÏÎÓÒÖÔÕÚÙÜÛÑÇ',
                          'aaaaaeeeeiiiiooooouuuuncAAAAAEEEEIIIIOOOOOUUUUNC')),
          '[^a-z0-9]+', '-', 'g'),
        '-+', '-', 'g')),
    '');
$fn$;

grant execute on function public.slug_de(text) to anon, authenticated;

-- ¿Está libre? Libre quiere decir: no lo usa nadie Y no lo usó nadie antes.
create or replace function public.slug_disponible(p_slug text)
returns boolean language sql stable security definer set search_path = public as $fn$
  select p_slug is not null
     and p_slug ~ '^[a-z0-9]([a-z0-9-]{1,38}[a-z0-9])$'
     and not exists (select 1 from public.turnos_publico where slug = p_slug)
     and not exists (select 1 from public.turnos_slug_usado where slug = p_slug);
$fn$;

revoke all on function public.slug_disponible(text) from public, anon;
grant execute on function public.slug_disponible(text) to authenticated;

-- ============================================================
-- 3. CREAR Y CAMBIAR EL LINK
-- ============================================================
create or replace function public.guardar_link_publico(
  p_empresa   uuid,
  p_slug      text default null,
  p_activo    boolean default null,
  p_titulo    text default null,
  p_mensaje   text default null,
  p_direccion text default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_actual text;
  v_slug   text;
  v_base   text;
  v_n      integer := 1;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar el link.' using errcode = '42501';
  end if;

  select slug into v_actual from public.turnos_publico where empresa_id = p_empresa;

  if p_slug is not null and trim(p_slug) <> '' then
    v_slug := public.slug_de(p_slug);
    if v_slug is null or length(v_slug) < 3 then
      raise exception 'Ese link es demasiado corto.' using errcode = '22023';
    end if;
    if v_slug <> coalesce(v_actual, '') and not public.slug_disponible(v_slug) then
      raise exception 'Ese link ya está tomado.' using errcode = '23505';
    end if;
  elsif v_actual is not null then
    v_slug := v_actual;
  else
    -- Primera vez: se arma del nombre del negocio y se le agrega un número
    -- si hace falta. Dos «Barbería Juan» no pueden compartir dirección.
    select public.slug_de(nombre) into v_base from public.empresas where id = p_empresa;
    v_base := coalesce(nullif(v_base, ''), 'negocio');
    v_slug := v_base;
    while not public.slug_disponible(v_slug) loop
      v_n := v_n + 1;
      v_slug := v_base || '-' || v_n;
      if v_n > 500 then
        raise exception 'No se pudo generar un link.' using errcode = 'P0001';
      end if;
    end loop;
  end if;

  -- El slug viejo se quema: no vuelve a estar disponible para nadie.
  if v_actual is not null and v_actual <> v_slug then
    insert into public.turnos_slug_usado (slug, empresa_id)
    values (v_actual, p_empresa)
    on conflict (slug) do nothing;
  end if;

  insert into public.turnos_publico (empresa_id, slug, activo, titulo, mensaje, direccion)
  values (p_empresa, v_slug, coalesce(p_activo, true),
          left(coalesce(p_titulo, ''), 80), left(coalesce(p_mensaje, ''), 300),
          left(coalesce(p_direccion, ''), 160))
  on conflict (empresa_id) do update
    set slug      = excluded.slug,
        activo    = coalesce(p_activo, public.turnos_publico.activo),
        titulo    = coalesce(nullif(excluded.titulo, ''), public.turnos_publico.titulo),
        mensaje   = case when p_mensaje is null then public.turnos_publico.mensaje else excluded.mensaje end,
        direccion = case when p_direccion is null then public.turnos_publico.direccion else excluded.direccion end,
        updated_at = now();

  return jsonb_build_object('slug', v_slug, 'cambio', v_actual is distinct from v_slug);
end $fn$;

revoke all on function public.guardar_link_publico(uuid, text, boolean, text, text, text) from public, anon;
grant execute on function public.guardar_link_publico(uuid, text, boolean, text, text, text) to authenticated;

create or replace function public.bloquear_telefono(
  p_empresa uuid, p_telefono text, p_motivo text default ''
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede bloquear.' using errcode = '42501';
  end if;
  if char_length(trim(coalesce(p_telefono, ''))) = 0 then
    raise exception 'Falta el teléfono.' using errcode = '22023';
  end if;

  insert into public.turnos_bloqueo (empresa_id, telefono, motivo)
  values (p_empresa, trim(p_telefono), left(coalesce(p_motivo, ''), 100))
  on conflict (empresa_id, telefono) do update set motivo = excluded.motivo;

  return jsonb_build_object('bloqueado', true);
end $fn$;

revoke all on function public.bloquear_telefono(uuid, text, text) from public, anon;
grant execute on function public.bloquear_telefono(uuid, text, text) to authenticated;

-- ============================================================
-- 4. PUERTA PÚBLICA · 1 de 3 · QUÉ ES ESTE NEGOCIO
--
--    Nombre, dirección, mensaje, quiénes atienden y qué servicios se pueden
--    reservar con su precio. Nada más. Ni el id de la empresa hace falta que
--    salga de acá: quien reserva lo hace por el slug.
-- ============================================================
create or replace function public.agenda_publica(p_slug text)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_emp   uuid;
  v_pub   public.turnos_publico%rowtype;
  v_nom   text;
  v_mon   text;
  v_profs jsonb;
begin
  select * into v_pub from public.turnos_publico where slug = lower(trim(coalesce(p_slug, '')));

  -- Un link apagado y un link que no existe contestan lo mismo. Distinguirlos
  -- le diría a cualquiera qué negocios usan Orden y cuáles cerraron.
  if v_pub.empresa_id is null or not v_pub.activo then
    return jsonb_build_object('existe', false);
  end if;

  v_emp := v_pub.empresa_id;

  select nombre, moneda into v_nom, v_mon from public.empresas where id = v_emp;

  select coalesce(jsonb_agg(x order by x->>'nombre'), '[]'::jsonb) into v_profs
  from (
    select jsonb_build_object(
      'id',     p.id,
      'nombre', p.nombre,
      'servicios', coalesce((
        select jsonb_agg(jsonb_build_object(
          'id',       pr.id,
          'nombre',   pr.nombre,
          'duracion', s.duracion_min,
          'precio',   public.precio_de_servicio(p.id, pr.id)
        ) order by pr.nombre)
        from public.turnos_servicio s
        join public.productos pr on pr.id = s.producto_id
        where s.empresa_id = v_emp and s.reservable and pr.activo and not pr.controla_stock
      ), '[]'::jsonb)
    ) as x
    from public.turnos_profesional p
    where p.empresa_id = v_emp and p.activo
      -- Solo quien tiene horario cargado: ofrecer a alguien que nunca
      -- trabaja es mandar al cliente a una pantalla vacía.
      and exists (select 1 from public.turnos_horario h
                  where h.profesional_id = p.id and h.activo)
  ) t;

  return jsonb_build_object(
    'existe',    true,
    'negocio',   coalesce(nullif(v_pub.titulo, ''), v_nom),
    'direccion', v_pub.direccion,
    'mensaje',   v_pub.mensaje,
    'moneda',    v_mon,
    'profesionales', v_profs
  );
end $fn$;

revoke all on function public.agenda_publica(text) from public;
grant execute on function public.agenda_publica(text) to anon, authenticated;

-- ============================================================
-- 5. PUERTA PÚBLICA · 2 de 3 · QUÉ HUECOS QUEDAN
--
--    Devuelve horarios y nada más. Quién ocupa los que faltan no sale de
--    acá, y no por omisión: la consulta no lo trae.
-- ============================================================
create or replace function public.huecos_publicos(
  p_slug        text,
  p_profesional uuid,
  p_producto    uuid,
  p_fecha       date
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_emp  uuid;
  v_res  jsonb;
begin
  select tp.empresa_id into v_emp
  from public.turnos_publico tp
  where tp.slug = lower(trim(coalesce(p_slug, ''))) and tp.activo;

  if v_emp is null then
    return '[]'::jsonb;
  end if;

  -- El profesional tiene que ser de ESE negocio. Sin esta comprobación, el
  -- link de una barbería serviría para espiar la agenda de cualquier otra.
  if not exists (select 1 from public.turnos_profesional
                 where id = p_profesional and empresa_id = v_emp and activo) then
    return '[]'::jsonb;
  end if;

  -- Ni ayer ni dentro de dos años. El tope corta el paseo de quien quiera
  -- recorrer la agenda entera pidiendo fechas.
  if p_fecha is null
     or p_fecha < public.hoy_empresa(v_emp)
     or p_fecha > public.hoy_empresa(v_emp) + 60 then
    return '[]'::jsonb;
  end if;

  select coalesce(jsonb_agg(h.inicia order by h.inicia), '[]'::jsonb) into v_res
  from public.huecos_del_dia(p_profesional, p_fecha, p_producto) h;

  return v_res;
end $fn$;

revoke all on function public.huecos_publicos(text, uuid, uuid, date) from public;
grant execute on function public.huecos_publicos(text, uuid, uuid, date) to anon, authenticated;

-- ============================================================
-- 6. PUERTA PÚBLICA · 3 de 3 · TOMAR EL TURNO
--
--    La única que escribe. Un formulario abierto en internet es un
--    formulario que alguien va a llenar cien veces: sin freno, cualquiera con
--    el link le llena el sábado de reservas falsas en dos minutos y el módulo
--    pasa a ser un problema en vez de una solución.
-- ============================================================
create or replace function public.reservar_publico(
  p_slug        text,
  p_profesional uuid,
  p_producto    uuid,
  p_inicia      timestamptz,
  p_nombre      text,
  p_telefono    text
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_emp      uuid;
  v_tel      text;
  v_zona     text;
  v_fecha    date;
  v_fin      timestamptz;
  v_id       uuid;
  v_token    uuid;
  v_pendientes integer;
begin
  select tp.empresa_id into v_emp
  from public.turnos_publico tp
  where tp.slug = lower(trim(coalesce(p_slug, ''))) and tp.activo;

  if v_emp is null then
    raise exception 'Esta página de reservas no está disponible.' using errcode = 'P0002';
  end if;

  if char_length(trim(coalesce(p_nombre, ''))) = 0 then
    raise exception 'Escribí tu nombre.' using errcode = '22023';
  end if;

  v_tel := trim(coalesce(p_telefono, ''));
  if char_length(v_tel) < 6 then
    raise exception 'Escribí un teléfono, para poder avisarte si pasa algo.' using errcode = '22023';
  end if;

  if exists (select 1 from public.turnos_bloqueo
             where empresa_id = v_emp and telefono = v_tel) then
    raise exception 'No se pueden tomar turnos con ese número. Comunicate con el local.'
      using errcode = '42501';
  end if;

  -- El candado, igual que en la puerta de adentro: serializa las reservas de
  -- esa persona para que dos clientes no se queden con el mismo horario.
  perform 1 from public.turnos_profesional
  where id = p_profesional and empresa_id = v_emp and activo
  for update;

  if not found then
    raise exception 'Esa persona no atiende en este local.' using errcode = 'P0002';
  end if;

  -- Tres pendientes por teléfono. Quien de verdad quiere cortarse no tiene
  -- cuatro turnos abiertos a la vez; quien está jugando, sí.
  select count(*)::int into v_pendientes
  from public.turnos_reserva
  where empresa_id = v_emp and cliente_telefono = v_tel
    and estado in ('pendiente', 'confirmada') and inicia > now();

  if v_pendientes >= 3 then
    raise exception 'Ya tenés varios turnos reservados. Cancelá alguno antes de tomar otro.'
      using errcode = '22023';
  end if;

  -- Y un minuto entre reserva y reserva desde el mismo número.
  if exists (
    select 1 from public.turnos_reserva
    where empresa_id = v_emp and cliente_telefono = v_tel
      and created_at > now() - interval '1 minute'
  ) then
    raise exception 'Esperá un momento antes de tomar otro turno.' using errcode = '22023';
  end if;

  select coalesce(zona_horaria, 'America/Asuncion') into v_zona
  from public.empresas where id = v_emp;
  v_fecha := (p_inicia at time zone v_zona)::date;

  if p_inicia is null or v_fecha > public.hoy_empresa(v_emp) + 60 then
    raise exception 'Ese horario no está disponible.' using errcode = '23505';
  end if;

  select h.termina into v_fin
  from public.huecos_del_dia(p_profesional, v_fecha, p_producto) h
  where h.inicia = p_inicia;

  if v_fin is null then
    raise exception 'Ese horario ya no está disponible.' using errcode = '23505';
  end if;

  insert into public.turnos_reserva (
    empresa_id, profesional_id, producto_id, inicia, termina,
    cliente_nombre, cliente_telefono, origen
  )
  values (
    v_emp, p_profesional, p_producto, p_inicia, v_fin,
    left(trim(p_nombre), 80), left(v_tel, 40), 'publico'
  )
  returning id, token into v_id, v_token;

  -- Se devuelve el token porque es lo único que el cliente se lleva: su
  -- enlace para cancelar. Sin eso la agenda se llena de fantasmas.
  return jsonb_build_object('reserva', v_id, 'token', v_token,
                            'inicia', p_inicia, 'termina', v_fin);
end $fn$;

revoke all on function public.reservar_publico(text, uuid, uuid, timestamptz, text, text) from public;
grant execute on function public.reservar_publico(text, uuid, uuid, timestamptz, text, text) to anon, authenticated;

-- Cancelar también es público: es el enlace que el cliente guardó. Sin él la
-- agenda deja de ser confiable en dos semanas.
grant execute on function public.cancelar_reserva(uuid) to anon;

-- Ver la reserva propia con el token, para la pantalla de confirmación.
create or replace function public.reserva_por_token(p_token uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_res jsonb;
begin
  select jsonb_build_object(
    'existe',   true,
    'inicia',   r.inicia,
    'termina',  r.termina,
    'estado',   r.estado,
    'servicio', pr.nombre,
    'con',      p.nombre,
    'negocio',  coalesce(nullif(tp.titulo, ''), e.nombre),
    'cliente',  r.cliente_nombre
  ) into v_res
  from public.turnos_reserva r
  join public.productos pr on pr.id = r.producto_id
  join public.turnos_profesional p on p.id = r.profesional_id
  join public.empresas e on e.id = r.empresa_id
  left join public.turnos_publico tp on tp.empresa_id = r.empresa_id
  where r.token = p_token;

  return coalesce(v_res, jsonb_build_object('existe', false));
end $fn$;

revoke all on function public.reserva_por_token(uuid) from public;
grant execute on function public.reserva_por_token(uuid) to anon, authenticated;


-- ############################################################
-- ##  039_ingreso_de_trabajo.sql
-- ############################################################

-- ORDEN · Migración 039 · Lo que cobraste trabajando, a tu cuenta personal
--
-- Un empleado con reparto —comisión o sueldo— puede tener DOS cuentas en
-- Orden: es miembro del negocio donde trabaja, y puede tener su propia
-- cuenta personal para llevar sus finanzas. Hasta acá, si quería que su
-- cuenta personal reflejara lo que cobra en el negocio, tenía que volver a
-- escribir el número a mano.
--
-- LA CONEXIÓN YA EXISTE, NO SE CREA ACÁ
--
-- Cuando el dueño lo agrega en Equipo y reparto y elige su cuenta en el
-- desplegable, `turnos_profesional.user_id` ya queda apuntando a esa
-- persona. Esta migración no inventa un vínculo nuevo: LEE el que ya está,
-- cruzando por identidad (auth.uid()) y no por pertenecer a la empresa.
--
-- POR QUÉ ES UN TOQUE Y NO ALGO AUTOMÁTICO
--
-- La parte del empleado, apenas se cobra un corte, está en la caja del local
-- pero todavía no es plata que tiene en la mano — está en `le_debe` hasta
-- que el dueño la paga (`pagar_profesional`, migración 035). Cargarla sola
-- en la cuenta personal en el momento del corte sería mostrarle plata que
-- todavía no cobró: la misma mentira que el sistema no se permite en
-- ningún otro lado. Por eso lo que se puede «traer» es lo YA PAGADO, nunca
-- lo que falta cobrar.
--
-- POR QUÉ LA ESCRITURA NUNCA CRUZA LA FRONTERA
--
-- La función que trae el ingreso la ejecuta el propio empleado, sobre su
-- propia cuenta personal, con su propia sesión. El negocio nunca escribe en
-- una cuenta que no es la suya. La lectura cruza la frontera de empresa_id
-- —por eso hace falta SECURITY DEFINER, igual que en `mis_servicios`—; la
-- escritura, nunca.

-- ============================================================
-- 1. QUÉ YA SE TRAJO
--
--    Clave por `turnos_pago_id`, no por (usuario, monto): eso hace que
--    traer dos veces el mismo pago sea imposible al nivel de la base, no
--    solo del botón. Si dos pestañas tocan «Traer» a la vez, la segunda
--    inserción choca contra la primary key y no duplica nada.
-- ============================================================
create table if not exists public.turnos_pago_traido (
  turnos_pago_id    uuid primary key references public.turnos_pago (id) on delete cascade,
  traido_por        uuid not null references auth.users (id) on delete cascade,
  empresa_personal  uuid not null references public.empresas (id) on delete cascade,
  movimiento_id     uuid references public.movimientos (id) on delete set null,
  created_at        timestamptz not null default now()
);

create index if not exists turnos_pago_traido_persona_idx
  on public.turnos_pago_traido (traido_por);

alter table public.turnos_pago_traido enable row level security;

drop policy if exists turnos_pago_traido_select on public.turnos_pago_traido;
create policy turnos_pago_traido_select on public.turnos_pago_traido
  for select to authenticated using (traido_por = auth.uid());

revoke all on public.turnos_pago_traido from anon, authenticated;
grant select on public.turnos_pago_traido to authenticated;

-- Sin esto, buscar «en qué empresas trabajo» recorrería turnos_profesional
-- entera. Con user_id como primera columna, la búsqueda por identidad es
-- directa.
create index if not exists turnos_profesional_user_idx
  on public.turnos_profesional (user_id) where user_id is not null;

-- ============================================================
-- 2. LO QUE TENÉS PENDIENTE DE TRAER
--
--    Sin argumentos: busca por auth.uid(), no por empresa. Es la pregunta
--    «¿dónde trabajo y cuánto me pagaron que todavía no anoté?», y esa
--    pregunta no la puede contestar la empresa activa —el empleado puede
--    trabajar en más de un negocio a la vez—.
-- ============================================================
create or replace function public.trabajos_pendientes()
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_res jsonb;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(x order by x->>'negocio'), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'empresa_id', e.id,
      'negocio',    e.nombre,
      'moneda',     e.moneda,
      'pendiente',  sum(tp.monto),
      'pagos',      count(tp.id)
    ) as x
    from public.turnos_profesional p
    join public.empresas e on e.id = p.empresa_id
    join public.turnos_pago tp on tp.profesional_id = p.id
    left join public.turnos_pago_traido tt on tt.turnos_pago_id = tp.id
    where p.user_id = auth.uid()
      and tt.turnos_pago_id is null
    group by e.id, e.nombre, e.moneda
    having sum(tp.monto) > 0
  ) t;

  return v_res;
end $fn$;

revoke all on function public.trabajos_pendientes() from public, anon;
grant execute on function public.trabajos_pendientes() to authenticated;

-- ============================================================
-- 3. TRAERLO
--
--    Un movimiento POR PAGO, fechado el día real en que el negocio lo pagó
--    —nunca «hoy», que sería el día en que tocaste el botón—. Si te
--    pagaron el 5 y el 12, son dos ingresos en dos días distintos, no uno
--    solo en el día que se te ocurrió cargarlo.
-- ============================================================
create or replace function public.traer_ingreso_de_trabajo(
  p_negocio  uuid,
  p_personal uuid
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_prof      public.turnos_profesional%rowtype;
  v_negocio   text;
  v_categoria text;
  v_pago      record;
  v_mov       uuid;
  v_cuantos   integer := 0;
  v_total     numeric := 0;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  -- Tiene que ser TU trabajo: el profesional de esa empresa cuya cuenta de
  -- Orden es la que está llamando. No alcanza con que el negocio exista.
  select * into v_prof from public.turnos_profesional
  where empresa_id = p_negocio and user_id = auth.uid();
  if not found then
    raise exception 'No trabajás en ese negocio.' using errcode = '42501';
  end if;

  select nombre into v_negocio from public.empresas where id = p_negocio;

  -- Y tiene que ser TU cuenta personal. La única forma de ser admin de una
  -- cuenta personal es ser su dueño —nadie más se puede sumar, ver la 019—
  -- así que esta comprobación alcanza para que nadie traiga un ingreso a
  -- una cuenta que no es la suya.
  if not exists (select 1 from public.empresas
                 where id = p_personal and tipo_cuenta = 'personal') then
    raise exception 'Eso no es una cuenta personal.' using errcode = '22023';
  end if;
  if not public.es_admin(p_personal) then
    raise exception 'Esa cuenta no es tuya.' using errcode = '42501';
  end if;

  -- Comisión y propina van a «Extra»; un sueldo fijo, a «Sueldo». Las dos ya
  -- existen en categorias_de_ingreso (026) para una cuenta personal.
  v_categoria := case when v_prof.reparto = 'sueldo' then 'Sueldo' else 'Extra' end;

  for v_pago in
    select tp.* from public.turnos_pago tp
    left join public.turnos_pago_traido tt on tt.turnos_pago_id = tp.id
    where tp.profesional_id = v_prof.id and tt.turnos_pago_id is null
    order by tp.fecha
  loop
    insert into public.movimientos (
      empresa_id, tipo, fecha, descripcion, categoria,
      subtotal, descuento, monto, costo_total,
      metodo_pago, contraparte, origen, creado_por
    )
    values (
      p_personal, 'ingreso', v_pago.fecha,
      'Cobrado en ' || v_negocio, v_categoria,
      v_pago.monto, 0, v_pago.monto, 0,
      'otro', v_negocio, 'manual', auth.uid()
    )
    returning id into v_mov;

    -- Se registra en la MISMA transacción que el movimiento: si algo de acá
    -- para abajo fallara, PostgreSQL deshace las dos cosas juntas y no
    -- puede quedar un ingreso cargado sin su marca de «ya traído».
    insert into public.turnos_pago_traido (turnos_pago_id, traido_por, empresa_personal, movimiento_id)
    values (v_pago.id, auth.uid(), p_personal, v_mov);

    v_cuantos := v_cuantos + 1;
    v_total := v_total + v_pago.monto;
  end loop;

  if v_cuantos = 0 then
    raise exception 'Ya está todo cargado: no tenés nada pendiente de ese negocio.' using errcode = 'P0002';
  end if;

  return jsonb_build_object('movimientos', v_cuantos, 'total', v_total);
end $fn$;

revoke all on function public.traer_ingreso_de_trabajo(uuid, uuid) from public, anon;
grant execute on function public.traer_ingreso_de_trabajo(uuid, uuid) to authenticated;


-- ############################################################
-- ##  040_agenda_desde_el_local.sql
-- ############################################################

-- ORDEN · Migración 040 · La agenda desde el mostrador
--
-- La 037 dejó el motor entero: calcular huecos y tomar uno. La 038 le puso
-- la puerta pública. Faltaba la puerta de adentro, que es por donde entran
-- casi todos los turnos de verdad: el cliente que llama, el que escribe por
-- WhatsApp, el que pasa por la puerta y pide para el jueves.
--
-- `reservar()` ya estaba escrita para eso desde la 037 —exige pertenecer a la
-- empresa y todo— pero para poder ofrecer horarios había que leer
-- `huecos_del_dia`, y esa función es el MOTOR, no una puerta: no pregunta de
-- quién es la agenda que le están pidiendo. Estaba abierta a cualquier
-- cuenta de Orden. No filtraba datos de clientes —solo horas libres— pero
-- una barbería no tiene por qué contarle su agenda a un desconocido.
--
-- Entonces esta migración hace dos cosas chicas y una sola idea: el motor se
-- cierra, y se abre una puerta que sí pregunta quién sos.

-- ============================================================
-- 1. EL MOTOR SE CIERRA
--
--    Nadie lo llama de afuera: lo usan `huecos_publicos` y `reservar`, las
--    dos `security definer`, que corren con los permisos del dueño de la
--    función y no con los de quien la invoca. Sacarle el permiso directo no
--    les cambia nada a ellas y le saca a un extraño la única forma que tenía
--    de mirar la agenda ajena.
-- ============================================================
revoke execute on function public.huecos_del_dia(uuid, date, uuid) from authenticated;

-- ============================================================
-- 2. LA PUERTA DE ADENTRO
--
--    Misma respuesta que el link público, con dos diferencias: pregunta si
--    pertenecés a la empresa en vez de mirar un slug, y devuelve también la
--    hora de fin, porque en el mostrador se lee «10:00 a 10:30» y no una
--    hora suelta.
--
--    La ve cualquiera del equipo, no solo administración. El que atiende el
--    teléfono un sábado a la mañana suele ser justamente el empleado.
-- ============================================================
create or replace function public.huecos_local(
  p_empresa     uuid,
  p_profesional uuid,
  p_producto    uuid,
  p_fecha       date
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_res jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  -- El profesional tiene que ser de ESTA empresa. Sin esto, pertenecer a
  -- cualquier negocio alcanzaría para leer la agenda de cualquier otro: la
  -- comprobación de arriba mira la empresa que te pasan, no la del turno.
  if not exists (
    select 1 from public.turnos_profesional
    where id = p_profesional and empresa_id = p_empresa and activo
  ) then
    return '[]'::jsonb;
  end if;

  -- Un año para adelante es más de lo que cualquiera agenda, y evita que un
  -- error de tipeo en la fecha ponga a la base a generar series eternas.
  if p_fecha is null or p_fecha > public.hoy_empresa(p_empresa) + 365 then
    return '[]'::jsonb;
  end if;

  -- Los días pasados no hace falta cortarlos acá: `huecos_del_dia` ya
  -- descarta todo instante anterior a ahora, así que un día de la semana
  -- pasada devuelve vacío solo.
  select coalesce(jsonb_agg(
    jsonb_build_object('inicia', h.inicia, 'termina', h.termina) order by h.inicia
  ), '[]'::jsonb)
  into v_res
  from public.huecos_del_dia(p_profesional, p_fecha, p_producto) h;

  return v_res;
end $fn$;

revoke all on function public.huecos_local(uuid, uuid, uuid, date) from public, anon;
grant execute on function public.huecos_local(uuid, uuid, uuid, date) to authenticated;


-- ############################################################
-- ##  041_mover_y_cancelar_turno.sql
-- ############################################################

-- ORDEN · Migración 041 · Mover y cancelar un turno desde el local
--
-- La 037 dejó una sola forma de que un turno deje de ocupar su lugar: que el
-- CLIENTE lo cancele desde el enlace que guardó. Adentro del local no había
-- ninguna.
--
-- En la práctica eso significaba que cuando alguien llamaba para avisar que
-- no venía, o para pasar el turno al jueves, el que atiende no podía hacer
-- nada. Lo único a mano era «no vino» —que es una acusación, no una
-- cancelación: le queda pegada al cliente que sí avisó— y el hueco quedaba
-- ocupado por un turno que nadie iba a usar.
--
-- Una agenda que no se puede corregir se llena de mentiras en dos semanas, y
-- una agenda con mentiras es peor que no tener agenda: parece que funciona.

-- ============================================================
-- 1. CANCELAR DESDE ADENTRO
--
--    Lo mismo que hace el cliente con su enlace, pero con sesión y
--    perteneciendo al local. El hueco se libera solo: `huecos_del_dia` mira
--    únicamente las reservas pendientes y confirmadas.
--
--    Un turno YA ATENDIDO no se cancela acá. Eso ya es una venta cobrada, y
--    deshacer una venta es trabajo de `anular_movimiento`, que devuelve la
--    plata y el stock. Si esto lo dejara pasar, quedaría un movimiento
--    cobrado colgado de un turno cancelado.
-- ============================================================
create or replace function public.cancelar_turno(p_reserva uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare v_emp uuid; v_estado text;
begin
  select empresa_id, estado into v_emp, v_estado
  from public.turnos_reserva where id = p_reserva;

  if v_emp is null then
    raise exception 'Ese turno no existe.' using errcode = 'P0002';
  end if;
  if not public.es_miembro(v_emp) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if v_estado = 'cancelada' then
    return jsonb_build_object('cancelado', true, 'ya_estaba', true);
  end if;
  if v_estado not in ('pendiente', 'confirmada') then
    raise exception 'Ese turno ya se cerró: no se puede cancelar.' using errcode = '22023';
  end if;

  update public.turnos_reserva set estado = 'cancelada' where id = p_reserva;
  return jsonb_build_object('cancelado', true);
end $fn$;

revoke all on function public.cancelar_turno(uuid) from public, anon;
grant execute on function public.cancelar_turno(uuid) to authenticated;

-- ============================================================
-- 2. MOVERLO
--
--    Cambia el horario y, si hace falta, con quién: «Pedro se enfermó, hoy
--    te atiende Juan» es la mitad de los cambios de una peluquería.
--
--    EL SERVICIO NO CAMBIA. De la duración del servicio sale la grilla de
--    horarios, así que dejar cambiarlo acá sería mover y reservar otra cosa
--    al mismo tiempo. Para eso se cancela y se anota de nuevo.
--
--    EL ENLACE DEL CLIENTE SIGUE VIVO. El token no se toca: el que reservó
--    por el link puede seguir cancelando desde el mensaje que ya tiene,
--    aunque el local le haya movido la hora.
--
--    El horario nuevo se valida contra los huecos de verdad —los mismos que
--    ve el link público—, así que mover no puede meter un turno donde no
--    entra. Y `for update` sobre el profesional nuevo serializa esto con las
--    reservas: mover y reservar no pueden quedarse con el mismo hueco.
-- ============================================================
create or replace function public.mover_turno(
  p_reserva     uuid,
  p_profesional uuid,
  p_inicia      timestamptz
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_r     public.turnos_reserva%rowtype;
  v_zona  text;
  v_fecha date;
  v_fin   timestamptz;
begin
  select * into v_r from public.turnos_reserva where id = p_reserva;

  if v_r.id is null then
    raise exception 'Ese turno no existe.' using errcode = 'P0002';
  end if;
  if not public.es_miembro(v_r.empresa_id) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if v_r.estado not in ('pendiente', 'confirmada') then
    raise exception 'Ese turno ya se cerró: no se puede mover.' using errcode = '22023';
  end if;
  if p_inicia is null then
    raise exception 'Falta el horario nuevo.' using errcode = '22023';
  end if;

  -- El candado, igual que en `reservar`. Todo lo que sigue queda serializado
  -- por profesional.
  perform 1 from public.turnos_profesional
  where id = p_profesional and empresa_id = v_r.empresa_id and activo
  for update;

  if not found then
    raise exception 'Esa persona no está en el equipo de esta cuenta.' using errcode = 'P0002';
  end if;

  select coalesce(zona_horaria, 'America/Asuncion') into v_zona
  from public.empresas where id = v_r.empresa_id;

  v_fecha := (p_inicia at time zone v_zona)::date;

  -- Que el hueco exista y esté libre. Como la grilla arranca de la ventana
  -- de atención y avanza de a una duración, un turno solo se pisa a sí mismo
  -- en su propio horario: pedir el mismo que ya tiene cae acá y se rechaza,
  -- que es exactamente lo que corresponde contestar.
  select h.termina into v_fin
  from public.huecos_del_dia(p_profesional, v_fecha, v_r.producto_id) h
  where h.inicia = p_inicia;

  if v_fin is null then
    raise exception 'Ese horario ya no está disponible.' using errcode = '23505';
  end if;

  update public.turnos_reserva
  set profesional_id = p_profesional,
      inicia         = p_inicia,
      termina        = v_fin
  where id = p_reserva;

  return jsonb_build_object('movido', true, 'inicia', p_inicia, 'termina', v_fin);
end $fn$;

revoke all on function public.mover_turno(uuid, uuid, timestamptz) from public, anon;
grant execute on function public.mover_turno(uuid, uuid, timestamptz) to authenticated;

-- ============================================================
-- 3. LA AGENDA DEL DÍA DICE QUÉ SERVICIO ES, NO SOLO CÓMO SE LLAMA
--
--    Para ofrecer horarios al mover hay que saber cuánto dura el servicio
--    reservado, y de eso sale la grilla. Hasta acá la agenda devolvía el
--    nombre del servicio pero no su id, así que la pantalla no tenía con qué
--    preguntar por los huecos. Es el único cambio: una clave más.
-- ============================================================
create or replace function public.agenda_del_dia(
  p_empresa uuid,
  p_fecha   date default null
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_zona  text;
  v_fecha date;
  v_res   jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select coalesce(zona_horaria, 'America/Asuncion') into v_zona
  from public.empresas where id = p_empresa;
  v_fecha := coalesce(p_fecha, public.hoy_empresa(p_empresa));

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',          r.id,
    'inicia',      r.inicia,
    'termina',     r.termina,
    'profesional', p.nombre,
    'profesional_id', r.profesional_id,
    'servicio',    pr.nombre,
    'producto_id', r.producto_id,
    'cliente',     r.cliente_nombre,
    'telefono',    r.cliente_telefono,
    'estado',      r.estado,
    'origen',      r.origen
  ) order by r.inicia), '[]'::jsonb)
  into v_res
  from public.turnos_reserva r
  join public.turnos_profesional p on p.id = r.profesional_id
  join public.productos pr on pr.id = r.producto_id
  where r.empresa_id = p_empresa
    and (r.inicia at time zone v_zona)::date = v_fecha
    -- Una cancelada no ocupa lugar en la agenda del día.
    and r.estado <> 'cancelada';

  return v_res;
end $fn$;

revoke all on function public.agenda_del_dia(uuid, date) from public, anon;
grant execute on function public.agenda_del_dia(uuid, date) to authenticated;


-- ############################################################
-- ##  042_cerrar_por_varios_dias.sql
-- ############################################################

-- ORDEN · Migración 042 · Cerrar y reabrir varios días de una
--
-- `turnos_excepcion` guarda UN DÍA por fila, y está bien: así la excepción de
-- una persona puede ganarle al feriado del local en un día puntual sin que
-- haya que partir rangos. Pero nadie se toma vacaciones de un día.
--
-- Sin esto, «me voy del 10 al 24» eran catorce llamadas desde el navegador,
-- cada una con su ida y vuelta y sin transacción que las junte: si la séptima
-- fallaba, quedaban seis días cerrados y ocho abiertos, y el link público
-- seguía ofreciendo turnos en la mitad de las vacaciones.
--
-- LAS REGLAS NO SE REESCRIBEN ACÁ
--
-- Las dos funciones de abajo no deciden nada: llaman en un bucle a
-- `guardar_excepcion` y `borrar_excepcion`, que ya saben que un feriado del
-- local lo pone el dueño y el día libre de alguien lo pone esa persona. Si
-- mañana esa regla cambia, cambia en un solo lugar. Lo único que agregan es
-- que el rango entero entra o no entra: una sola transacción.

create or replace function public.cerrar_dias(
  p_empresa     uuid,
  p_desde       date,
  p_hasta       date,
  p_profesional uuid default null,
  p_motivo      text default ''
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_dia     date;
  v_cuantos integer := 0;
begin
  if p_desde is null or p_hasta is null then
    raise exception 'Faltan las fechas.' using errcode = '22023';
  end if;
  if p_hasta < p_desde then
    raise exception 'El último día no puede ser anterior al primero.' using errcode = '22023';
  end if;
  -- Un año es más que cualquier cierre real y evita que un error de tipeo en
  -- el año escriba miles de filas.
  if p_hasta - p_desde > 366 then
    raise exception 'No se puede cerrar más de un año seguido.' using errcode = '22023';
  end if;

  v_dia := p_desde;
  while v_dia <= p_hasta loop
    -- Cada vuelta comprueba los permisos por su cuenta. Es a propósito: la
    -- regla de quién puede cerrar qué vive en `guardar_excepcion` y no se
    -- duplica acá.
    perform public.guardar_excepcion(p_empresa, v_dia, true, p_profesional, null, null, p_motivo);
    v_cuantos := v_cuantos + 1;
    v_dia := v_dia + 1;
  end loop;

  return jsonb_build_object('dias', v_cuantos);
end $fn$;

revoke all on function public.cerrar_dias(uuid, date, date, uuid, text) from public, anon;
grant execute on function public.cerrar_dias(uuid, date, date, uuid, text) to authenticated;

-- Volver a abrir lo que se había cerrado. Borra solo las excepciones de ESE
-- profesional (o las del local, si viene sin profesional): reabrir el local
-- no le levanta a nadie el día libre que se había tomado aparte.
create or replace function public.abrir_dias(
  p_empresa     uuid,
  p_desde       date,
  p_hasta       date,
  p_profesional uuid default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_id      uuid;
  v_cuantos integer := 0;
begin
  if p_desde is null or p_hasta is null then
    raise exception 'Faltan las fechas.' using errcode = '22023';
  end if;

  for v_id in
    select x.id from public.turnos_excepcion x
    where x.empresa_id = p_empresa
      and x.fecha between p_desde and p_hasta
      and x.profesional_id is not distinct from p_profesional
    order by x.fecha
  loop
    perform public.borrar_excepcion(p_empresa, v_id);
    v_cuantos := v_cuantos + 1;
  end loop;

  return jsonb_build_object('dias', v_cuantos);
end $fn$;

revoke all on function public.abrir_dias(uuid, date, date, uuid) from public, anon;
grant execute on function public.abrir_dias(uuid, date, date, uuid) to authenticated;


-- ############################################################
-- ##  043_recordatorio_al_cliente.sql
-- ############################################################

-- ORDEN · Migración 043 · Avisarle al cliente que mañana tiene turno
--
-- Los plantones son el problema número uno de cualquier agenda, y casi
-- ninguno es mala fe: la persona reservó hace diez días y se olvidó. Hasta
-- acá `turnos_reserva` guardaba el teléfono del cliente y NADA lo usaba.
--
-- POR QUÉ NO SE MANDA SOLO
--
-- Un cliente de la barbería nunca se registra en Orden, así que el aviso por
-- push —lo único que Orden sabe mandar hoy— no le llega. Mandarle un mensaje
-- de verdad necesita un proveedor (WhatsApp API, SMS), verificación de la
-- empresa, plantillas aprobadas y costo por mensaje: semanas de trámite y
-- una decisión de plata que todavía no está tomada.
--
-- Entonces lo que se hace es lo que sí funciona hoy: el local toca un botón
-- y se abre WhatsApp con el mensaje escrito, desde SU número. Un toque por
-- cliente. Y para que alguien se acuerde de tocarlo, la noche anterior le
-- llega un push al dueño con cuántos turnos tiene mañana y cuántos siguen
-- sin avisar.
--
-- Esta migración aporta las dos piezas que faltaban en la base: dejar
-- constancia de a quién ya se le avisó, y poder preguntar «¿qué hay para
-- mañana?» desde la tarea de la noche.

-- ============================================================
-- 1. A QUIÉN YA SE LE AVISÓ
--
--    Una fecha y no un booleano: sirve para saber CUÁNDO se le avisó, que es
--    lo que después permite no volver a molestarlo dos veces el mismo día.
-- ============================================================
alter table public.turnos_reserva
  add column if not exists avisado_at timestamptz;

-- No lleva restricción de estado a propósito: esto no mueve plata ni ocupa
-- un horario, es una marca de «ya le escribí». Que se pueda marcar un turno
-- ya atendido no rompe nada, y en cambio poner reglas donde no hacen falta
-- termina en un botón que no funciona sin que se entienda por qué.
create or replace function public.marcar_avisado(
  p_reserva uuid,
  p_avisado boolean default true
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare v_emp uuid;
begin
  select empresa_id into v_emp from public.turnos_reserva where id = p_reserva;

  if v_emp is null then
    raise exception 'Ese turno no existe.' using errcode = 'P0002';
  end if;
  if not public.es_miembro(v_emp) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  update public.turnos_reserva
  set avisado_at = case when coalesce(p_avisado, true) then now() else null end
  where id = p_reserva;

  return jsonb_build_object('avisado', coalesce(p_avisado, true));
end $fn$;

revoke all on function public.marcar_avisado(uuid, boolean) from public, anon;
grant execute on function public.marcar_avisado(uuid, boolean) to authenticated;

-- ============================================================
-- 2. LA AGENDA DEL DÍA DICE SI YA SE AVISÓ, Y CON QUÉ ENLACE
--
--    El token va acá porque el mensaje que se le manda al cliente incluye su
--    enlace para cancelar: avisarle sin darle cómo cancelar convierte al que
--    no puede venir en un plantón en vez de en un hueco libre.
--
--    No expone nada nuevo: cualquier miembro ya podía leer la columna `token`
--    directo de `turnos_reserva` desde la 037.
-- ============================================================
create or replace function public.agenda_del_dia(
  p_empresa uuid,
  p_fecha   date default null
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_zona  text;
  v_fecha date;
  v_res   jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select coalesce(zona_horaria, 'America/Asuncion') into v_zona
  from public.empresas where id = p_empresa;
  v_fecha := coalesce(p_fecha, public.hoy_empresa(p_empresa));

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',          r.id,
    'inicia',      r.inicia,
    'termina',     r.termina,
    'profesional', p.nombre,
    'profesional_id', r.profesional_id,
    'servicio',    pr.nombre,
    'producto_id', r.producto_id,
    'cliente',     r.cliente_nombre,
    'telefono',    r.cliente_telefono,
    'estado',      r.estado,
    'origen',      r.origen,
    'token',       r.token,
    'avisado',     (r.avisado_at is not null)
  ) order by r.inicia), '[]'::jsonb)
  into v_res
  from public.turnos_reserva r
  join public.turnos_profesional p on p.id = r.profesional_id
  join public.productos pr on pr.id = r.producto_id
  where r.empresa_id = p_empresa
    and (r.inicia at time zone v_zona)::date = v_fecha
    -- Una cancelada no ocupa lugar en la agenda del día.
    and r.estado <> 'cancelada';

  return v_res;
end $fn$;

revoke all on function public.agenda_del_dia(uuid, date) from public, anon;
grant execute on function public.agenda_del_dia(uuid, date) to authenticated;

-- ============================================================
-- 3. QUÉ HAY PARA MAÑANA (la lee la tarea de la noche)
--
--    Solo para `service_role`: la tarea corre sin sesión de nadie y mira
--    todas las cuentas a la vez, así que esto no se le da a un usuario
--    común ni por equivocación. Mismo criterio que
--    `empresas_sin_cargar_hoy` desde la 008.
--
--    «Mañana» se calcula en la zona de CADA cuenta. Para el mismo instante,
--    el mañana de Asunción y el de Madrid son días distintos.
-- ============================================================
create or replace function public.turnos_de_manana()
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_res jsonb;
begin
  select coalesce(jsonb_agg(x order by x->>'nombre'), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'empresa_id', e.id,
      'nombre',     e.nombre,
      'zona',       coalesce(e.zona_horaria, 'America/Asuncion'),
      'fecha',      (public.hoy_empresa(e.id) + 1),
      'turnos',     count(*)::int,
      'sin_avisar', count(*) filter (where r.avisado_at is null)::int
    ) as x
    from public.empresas e
    join public.turnos_reserva r on r.empresa_id = e.id
    where r.estado in ('pendiente', 'confirmada')
      and (r.inicia at time zone coalesce(e.zona_horaria, 'America/Asuncion'))::date
          = public.hoy_empresa(e.id) + 1
    group by e.id, e.nombre, e.zona_horaria
  ) s;

  return v_res;
end $fn$;

revoke all on function public.turnos_de_manana() from public, anon, authenticated;
grant execute on function public.turnos_de_manana() to service_role;

-- ============================================================
-- 4. PODER APAGARLO
--
--    Un aviso sin forma de apagarlo es spam, por más útil que sea. Va como
--    preferencia de la persona y no de la empresa: en un local con dos
--    dueños, uno puede querer el aviso y el otro no.
--
--    `guardar_preferencias` se BORRA y se vuelve a crear en vez de sumarle
--    el parámetro: con las dos versiones vivas, una llamada que manda solo
--    algunos campos —como hace la pantalla de ajustes— queda ambigua y
--    PostgreSQL no sabe a cuál de las dos le habla.
-- ============================================================
alter table public.preferencias
  add column if not exists aviso_turnos boolean not null default true;

create or replace function public.mis_preferencias()
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_res jsonb;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'idioma', p.idioma, 'aviso_cierre', p.aviso_cierre,
    'aviso_semanal', p.aviso_semanal, 'aviso_turnos', p.aviso_turnos,
    'hora_cierre', p.hora_cierre
  ) into v_res
  from public.preferencias p where p.user_id = auth.uid();

  return coalesce(v_res, jsonb_build_object(
    'idioma', 'es', 'aviso_cierre', true, 'aviso_semanal', true,
    'aviso_turnos', true, 'hora_cierre', 20));
end $fn$;

drop function if exists public.guardar_preferencias(text, boolean, boolean, smallint);

create or replace function public.guardar_preferencias(
  p_idioma text default null,
  p_aviso_cierre boolean default null,
  p_aviso_semanal boolean default null,
  p_hora_cierre smallint default null,
  p_aviso_turnos boolean default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  insert into public.preferencias as p (
    user_id, idioma, aviso_cierre, aviso_semanal, hora_cierre, aviso_turnos)
  values (
    auth.uid(),
    coalesce(nullif(lower(trim(p_idioma)), ''), 'es'),
    coalesce(p_aviso_cierre, true),
    coalesce(p_aviso_semanal, true),
    coalesce(p_hora_cierre, 20::smallint),
    coalesce(p_aviso_turnos, true)
  )
  on conflict (user_id) do update set
    -- coalesce con el valor viejo: mandar un solo campo no borra los otros.
    idioma        = coalesce(nullif(lower(trim(p_idioma)), ''), p.idioma),
    aviso_cierre  = coalesce(p_aviso_cierre,  p.aviso_cierre),
    aviso_semanal = coalesce(p_aviso_semanal, p.aviso_semanal),
    hora_cierre   = coalesce(p_hora_cierre,   p.hora_cierre),
    aviso_turnos  = coalesce(p_aviso_turnos,  p.aviso_turnos),
    updated_at    = now();

  return public.mis_preferencias();
end $fn$;

revoke all on function public.mis_preferencias() from public, anon;
grant execute on function public.mis_preferencias() to authenticated;
revoke all on function public.guardar_preferencias(text, boolean, boolean, smallint, boolean)
  from public, anon;
grant execute on function public.guardar_preferencias(text, boolean, boolean, smallint, boolean)
  to authenticated;


-- ############################################################
-- ##  044_lotes_a_tablas.sql
-- ############################################################

-- ORDEN · Migración 044 · Lotes: lo que tarda meses en dar ganancia
--
-- Hay negocios donde la pregunta «¿cómo me fue hoy?» no significa nada. El
-- ganadero compra cuarenta novillos en marzo, les pone plata todos los meses
-- —alimento, sanidad, flete— y recién los vende en octubre. El agricultor
-- siembra, gasta toda la campaña y cobra una vez. El de la obra compra
-- materiales y paga jornales durante cuatro meses.
--
-- Para los tres, el día es la unidad equivocada: durante siete meses el
-- sistema les muestra pura pérdida, y un día muestran una ganancia enorme.
-- Ninguna de las dos cosas es verdad. La verdad es del CICLO, no del día.
--
-- POR QUÉ SE LLAMA «LOTE» Y NO «HACIENDA» NI «OBRA»
--
-- Porque es el mismo problema en los tres rubros, y el módulo se llama como
-- el problema. Cuarenta novillos, una hectárea de soja y la casa de Pérez son
-- la misma forma: algo que se abre, junta costos durante meses, y recién al
-- cerrarse dice si ganaste. Construirlo tres veces con tres nombres sería
-- mantener el mismo bug en tres lugares.
--
-- CÓMO SE ENGANCHA: POR EL MOVIMIENTO, COMO TODO
--
-- Un lote no tiene su propia contabilidad. No guarda montos, ni totales, ni
-- una caja aparte. Lo único que se agrega al núcleo es UNA COLUMNA en
-- `movimientos`: de qué lote es este gasto, de qué lote es esta venta.
--
-- Eso es lo que hace que todo lo que ya existe siga funcionando sin tocarlo.
-- Comprar los novillos sigue siendo un gasto de marzo —tu plata bajó en
-- marzo, y eso es cierto—; venderlos sigue siendo una venta de octubre.
-- Anular una compra sigue siendo `anular_movimiento`. El panel, el Excel y
-- el cierre no se enteran de que existen los lotes.
--
-- Lo que el lote agrega es la OTRA vista de la misma plata: «este lote lleva
-- siete millones puestos y todavía no vendí nada».

-- ============================================================
-- 1. EL LOTE
-- ============================================================
create table if not exists public.lotes (
  id          uuid primary key default gen_random_uuid(),
  empresa_id  uuid not null references public.empresas (id) on delete cascade,
  nombre      text not null check (char_length(trim(nombre)) between 1 and 80),
  -- Qué se cuenta: cabezas, hectáreas, o nada (una obra no se mide así).
  unidad      text not null default '' check (char_length(unidad) <= 20),
  cantidad    numeric(14,2) not null default 0 check (cantidad >= 0),
  estado      text not null default 'abierto' check (estado in ('abierto', 'cerrado')),
  abierto_el  date not null,
  cerrado_el  date,
  notas       text not null default '' check (char_length(notas) <= 500),
  creado_por  uuid references auth.users (id) on delete set null,
  created_at  timestamptz not null default now(),

  -- Un lote cerrado tiene fecha de cierre y uno abierto no. Sin esto queda
  -- la puerta abierta a un lote «cerrado» sin decir cuándo, que después no
  -- se puede ordenar ni comparar con nada.
  constraint lote_cierre_coherente check (
    (estado = 'abierto' and cerrado_el is null)
    or (estado = 'cerrado' and cerrado_el is not null)
  ),
  constraint lote_no_cierra_antes_de_abrir check (
    cerrado_el is null or cerrado_el >= abierto_el
  )
);

create index if not exists lotes_empresa_idx on public.lotes (empresa_id, estado, abierto_el desc);

-- La clave que permite la llave foránea compuesta de más abajo. No es un
-- índice de rendimiento: es lo que hace estructuralmente imposible colgar un
-- movimiento del lote de otra empresa.
create unique index if not exists lotes_id_empresa_idx on public.lotes (id, empresa_id);

alter table public.lotes enable row level security;

-- Los lee cualquier miembro: para cargarle un gasto a un lote hay que poder
-- elegirlo de una lista. La tabla no guarda ni un monto, así que verla no
-- muestra plata; los números salen de las funciones de la 045, que sí miran
-- el rol antes de contestar.
drop policy if exists lotes_select on public.lotes;
create policy lotes_select on public.lotes
  for select to authenticated using (public.es_miembro(empresa_id));

revoke all on public.lotes from anon, authenticated;
grant select on public.lotes to authenticated;

drop trigger if exists cuenta_activa_lotes on public.lotes;
create trigger cuenta_activa_lotes
  before insert or update on public.lotes
  for each row execute function public.exigir_cuenta_activa();

-- ============================================================
-- 2. EL ENGANCHE: UNA COLUMNA
--
--    La llave foránea es COMPUESTA —(lote_id, empresa_id)— y ahí está todo
--    el trabajo de seguridad de esta migración. Con una llave simple sobre
--    `lote_id`, un movimiento de la barbería podía colgarse del lote de la
--    estancia de al lado y falsearle el resultado a otro. Con la compuesta,
--    PostgreSQL directamente no lo deja escribir.
--
--    Cuando `lote_id` es null la llave no se evalúa (MATCH SIMPLE), así que
--    todos los movimientos que ya existen siguen siendo válidos.
--
--    Sin `on delete`: borrar un lote que tiene plata cargada se RECHAZA. Un
--    lote no es una etiqueta, es dónde quedó registrado lo que gastaste;
--    borrarlo en cascada dejaría gastos huérfanos y borrarlo poniendo null
--    borraría la única prueba de a qué ciclo pertenecían.
-- ============================================================
alter table public.movimientos
  add column if not exists lote_id uuid;

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'movimientos_lote_fk'
  ) then
    alter table public.movimientos
      add constraint movimientos_lote_fk
      foreign key (lote_id, empresa_id) references public.lotes (id, empresa_id);
  end if;
end $$;

create index if not exists movimientos_lote_idx
  on public.movimientos (lote_id) where lote_id is not null;

-- Sin esto la columna nueva no se puede leer: la 003 le sacó a
-- `authenticated` el SELECT sobre toda la tabla y se lo devolvió columna por
-- columna, para que nadie llegue a los costos por consulta directa. Una
-- columna nueva no entra sola en esa lista.
grant select (lote_id) on public.movimientos to authenticated;

-- ============================================================
-- 3. ABRIR Y EDITAR
--
--    Solo administración. Abrir un lote es decidir cómo se mide un ciclo del
--    negocio, del mismo orden que definir un producto o el reparto: quien
--    carga gastos no define contra qué se los mide.
-- ============================================================
create or replace function public.guardar_lote(
  p_empresa  uuid,
  p_nombre   text,
  p_unidad   text default '',
  p_cantidad numeric default 0,
  p_notas    text default '',
  p_id       uuid default null,
  p_abierto  date default null
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare v_id uuid;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo administración maneja los lotes.' using errcode = '42501';
  end if;

  if char_length(trim(coalesce(p_nombre, ''))) = 0 then
    raise exception 'El lote necesita un nombre.' using errcode = '22023';
  end if;
  if coalesce(p_cantidad, 0) < 0 then
    raise exception 'La cantidad no puede ser negativa.' using errcode = '22023';
  end if;

  if p_id is null then
    insert into public.lotes (empresa_id, nombre, unidad, cantidad, notas, abierto_el, creado_por)
    values (
      p_empresa, trim(p_nombre), left(trim(coalesce(p_unidad, '')), 20),
      coalesce(p_cantidad, 0), left(coalesce(p_notas, ''), 500),
      coalesce(p_abierto, public.hoy_empresa(p_empresa)), auth.uid()
    )
    returning id into v_id;
  else
    update public.lotes set
      nombre     = trim(p_nombre),
      unidad     = left(trim(coalesce(p_unidad, '')), 20),
      cantidad   = coalesce(p_cantidad, 0),
      notas      = left(coalesce(p_notas, ''), 500),
      abierto_el = coalesce(p_abierto, abierto_el)
    where id = p_id and empresa_id = p_empresa
    returning id into v_id;

    if v_id is null then
      raise exception 'Ese lote no existe.' using errcode = 'P0002';
    end if;
  end if;

  return v_id;
end $fn$;

revoke all on function public.guardar_lote(uuid, text, text, numeric, text, uuid, date) from public, anon;
grant execute on function public.guardar_lote(uuid, text, text, numeric, text, uuid, date) to authenticated;

-- ============================================================
-- 4. CERRAR Y REABRIR
--
--    Cerrar no calcula ni congela nada: el resultado se saca siempre de los
--    movimientos, así que un lote cerrado que después recibe una corrección
--    —una anulación, un gasto que faltaba— muestra el número correcto igual.
--    Cerrar es decir «este ciclo terminó», y sirve para sacarlo de la lista
--    de lo que está en curso.
-- ============================================================
create or replace function public.cerrar_lote(
  p_empresa uuid,
  p_id      uuid,
  p_fecha   date default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare v_abierto date; v_estado text; v_fecha date;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo administración maneja los lotes.' using errcode = '42501';
  end if;

  select abierto_el, estado into v_abierto, v_estado
  from public.lotes where id = p_id and empresa_id = p_empresa;

  if v_abierto is null then
    raise exception 'Ese lote no existe.' using errcode = 'P0002';
  end if;
  if v_estado = 'cerrado' then
    return jsonb_build_object('cerrado', true, 'ya_estaba', true);
  end if;

  v_fecha := coalesce(p_fecha, public.hoy_empresa(p_empresa));
  if v_fecha < v_abierto then
    raise exception 'Un lote no puede cerrarse antes de haberse abierto.' using errcode = '22007';
  end if;

  update public.lotes set estado = 'cerrado', cerrado_el = v_fecha
  where id = p_id and empresa_id = p_empresa;

  return jsonb_build_object('cerrado', true, 'fecha', v_fecha);
end $fn$;

revoke all on function public.cerrar_lote(uuid, uuid, date) from public, anon;
grant execute on function public.cerrar_lote(uuid, uuid, date) to authenticated;

create or replace function public.reabrir_lote(p_empresa uuid, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo administración maneja los lotes.' using errcode = '42501';
  end if;

  update public.lotes set estado = 'abierto', cerrado_el = null
  where id = p_id and empresa_id = p_empresa;

  if not found then
    raise exception 'Ese lote no existe.' using errcode = 'P0002';
  end if;

  return jsonb_build_object('abierto', true);
end $fn$;

revoke all on function public.reabrir_lote(uuid, uuid) from public, anon;
grant execute on function public.reabrir_lote(uuid, uuid) to authenticated;

-- ============================================================
-- 5. BORRAR
--
--    Solo uno vacío. La llave foránea ya lo impediría, pero lo haría con un
--    error de PostgreSQL que nadie entiende. Acá se dice por qué y cuántos
--    movimientos hay que sacarle primero.
-- ============================================================
create or replace function public.borrar_lote(p_empresa uuid, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare v_cuantos integer;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo administración maneja los lotes.' using errcode = '42501';
  end if;

  if not exists (select 1 from public.lotes where id = p_id and empresa_id = p_empresa) then
    raise exception 'Ese lote no existe.' using errcode = 'P0002';
  end if;

  select count(*)::int into v_cuantos
  from public.movimientos where lote_id = p_id;

  if v_cuantos > 0 then
    raise exception 'Ese lote tiene % movimientos cargados. Sacáselos antes de borrarlo.', v_cuantos
      using errcode = '23503';
  end if;

  delete from public.lotes where id = p_id and empresa_id = p_empresa;
  return jsonb_build_object('borrado', true);
end $fn$;

revoke all on function public.borrar_lote(uuid, uuid) from public, anon;
grant execute on function public.borrar_lote(uuid, uuid) to authenticated;

-- ============================================================
-- 6. PONERLE UN MOVIMIENTO, O SACÁRSELO
--
--    Esto sí lo hace cualquier miembro: el que carga la bolsa de balanceado
--    es el que sabe a qué corral fue. Decir de qué lote es un gasto no es
--    información reservada — es parte de cargarlo bien.
--
--    Cambia una sola columna. El monto, la fecha y todo lo demás del
--    movimiento quedan intactos, así que mover un gasto de lote no puede
--    alterar la caja de ningún día.
-- ============================================================
create or replace function public.asignar_a_lote(
  p_movimiento uuid,
  p_lote       uuid default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare v_emp uuid; v_estado text;
begin
  select empresa_id, estado into v_emp, v_estado
  from public.movimientos where id = p_movimiento;

  if v_emp is null then
    raise exception 'Ese movimiento no existe.' using errcode = 'P0002';
  end if;
  if not public.es_miembro(v_emp) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if v_estado <> 'activo' then
    raise exception 'Ese movimiento está anulado.' using errcode = '22023';
  end if;

  -- Que el lote sea de la misma empresa lo garantiza la llave compuesta,
  -- pero un error de llave foránea no le explica nada a nadie.
  if p_lote is not null
     and not exists (select 1 from public.lotes where id = p_lote and empresa_id = v_emp) then
    raise exception 'Ese lote no es de esta cuenta.' using errcode = '42501';
  end if;

  update public.movimientos set lote_id = p_lote where id = p_movimiento;

  return jsonb_build_object('lote', p_lote);
end $fn$;

revoke all on function public.asignar_a_lote(uuid, uuid) from public, anon;
grant execute on function public.asignar_a_lote(uuid, uuid) to authenticated;


-- ############################################################
-- ##  045_lotes_b_resultado.sql
-- ############################################################

-- ORDEN · Migración 045 · Cómo viene el lote
--
-- La 044 dejó el lote y su enganche. Acá se contesta la única pregunta que
-- importa: cuánta plata le pusiste, cuánta sacaste, y cómo va.
--
-- QUÉ MIDE EL RESULTADO DE UN LOTE
--
-- Plata que entró menos plata que salió, de ese ciclo. Nada más.
--
-- No es el margen contable y es a propósito. En un lote, la compra de los
-- novillos YA es un gasto cargado: contarla otra vez como costo de la venta
-- sería restarla dos veces y mostrarle una pérdida que no existe. Por eso el
-- resultado no toca `costo_total` —el margen del núcleo— y se queda con lo
-- que de verdad pasó por la caja.
--
-- Como efecto, tampoco hace falta esconderle nada a un vendedor: todo lo que
-- se suma acá son montos que la 003 ya le deja ver de a uno. Esconder la
-- suma de números visibles no protege nada, solo estorba a quien carga los
-- gastos. Lo único reservado del núcleo —`costo_total`— no entra en ninguna
-- de estas cuentas.
--
-- LO ANULADO NO CUENTA
--
-- Un gasto anulado no es plata que saliste. Todas las sumas de acá filtran
-- por `estado = 'activo'`, igual que el panel y el cierre.

-- ============================================================
-- 1. LA LISTA
-- ============================================================
create or replace function public.listar_lotes(
  p_empresa           uuid,
  p_incluir_cerrados  boolean default false
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_res jsonb; v_hoy date;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  v_hoy := public.hoy_empresa(p_empresa);

  select coalesce(jsonb_agg(x order by x->>'estado', (x->>'abierto_el') desc), '[]'::jsonb)
  into v_res
  from (
    select jsonb_build_object(
      'id',         l.id,
      'nombre',     l.nombre,
      'unidad',     l.unidad,
      'cantidad',   l.cantidad,
      'estado',     l.estado,
      'abierto_el', l.abierto_el,
      'cerrado_el', l.cerrado_el,
      'notas',      l.notas,
      -- Cuánto lleva en curso, o cuánto duró si ya cerró.
      'dias',        (coalesce(l.cerrado_el, v_hoy) - l.abierto_el),
      'movimientos', coalesce(c.movimientos, 0),
      'puesto',      coalesce(c.puesto, 0),
      'cobrado',     coalesce(c.cobrado, 0),
      'resultado',   coalesce(c.cobrado, 0) - coalesce(c.puesto, 0),
      -- Lo que de verdad mira un ganadero: cuánto por cabeza.
      'por_unidad',  case
                       when l.cantidad > 0
                       then round((coalesce(c.cobrado, 0) - coalesce(c.puesto, 0)) / l.cantidad, 2)
                       else null
                     end
    ) as x
    from public.lotes l
    left join lateral (
      select
        count(*)::int as movimientos,
        sum(m.monto) filter (where m.tipo = 'gasto')              as puesto,
        sum(m.monto) filter (where m.tipo in ('venta', 'ingreso')) as cobrado
      from public.movimientos m
      where m.lote_id = l.id and m.estado = 'activo'
    ) c on true
    where l.empresa_id = p_empresa
      and (coalesce(p_incluir_cerrados, false) or l.estado = 'abierto')
  ) s;

  return v_res;
end $fn$;

revoke all on function public.listar_lotes(uuid, boolean) from public, anon;
grant execute on function public.listar_lotes(uuid, boolean) to authenticated;

-- ============================================================
-- 2. UN LOTE, CON TODO LO QUE TIENE ADENTRO
--
--    Los movimientos vienen sin `costo_total`: es la única columna que la
--    003 reserva, y esta función no tiene por qué ser la puerta de atrás que
--    la deja salir.
-- ============================================================
create or replace function public.resumen_lote(p_empresa uuid, p_lote uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_lote jsonb; v_movs jsonb; v_hoy date;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  v_hoy := public.hoy_empresa(p_empresa);

  select jsonb_build_object(
    'id', l.id, 'nombre', l.nombre, 'unidad', l.unidad, 'cantidad', l.cantidad,
    'estado', l.estado, 'abierto_el', l.abierto_el, 'cerrado_el', l.cerrado_el,
    'notas', l.notas,
    'dias', (coalesce(l.cerrado_el, v_hoy) - l.abierto_el)
  ) into v_lote
  from public.lotes l where l.id = p_lote and l.empresa_id = p_empresa;

  if v_lote is null then
    raise exception 'Ese lote no existe.' using errcode = 'P0002';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',          m.id,
    'tipo',        m.tipo,
    'estado',      m.estado,
    'fecha',       m.fecha,
    'descripcion', m.descripcion,
    'categoria',   m.categoria,
    'monto',       m.monto
  ) order by m.fecha desc, m.created_at desc), '[]'::jsonb)
  into v_movs
  from public.movimientos m
  where m.lote_id = p_lote and m.empresa_id = p_empresa;

  return v_lote || jsonb_build_object('movimientos', v_movs);
end $fn$;

revoke all on function public.resumen_lote(uuid, uuid) from public, anon;
grant execute on function public.resumen_lote(uuid, uuid) to authenticated;

-- ============================================================
-- 3. LO QUE TODAVÍA NO ES DE NINGÚN LOTE
--
--    Para el que ya venía cargando gastos antes de abrir el lote, que va a
--    ser el caso de todos la primera vez. Sin esto habría que volver a
--    cargar a mano lo que ya está cargado, y nadie lo hace.
--
--    Devuelve solo gastos e ingresos activos del rango: las ventas también
--    pueden ir a un lote, pero se asignan desde la venta misma; mezclar acá
--    la lista entera de ventas del mes haría inusable el desplegable.
-- ============================================================
create or replace function public.movimientos_sin_lote(
  p_empresa uuid,
  p_desde   date,
  p_hasta   date
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_res jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',          m.id,
    'tipo',        m.tipo,
    'fecha',       m.fecha,
    'descripcion', m.descripcion,
    'categoria',   m.categoria,
    'monto',       m.monto
  ) order by m.fecha desc, m.created_at desc), '[]'::jsonb)
  into v_res
  from public.movimientos m
  where m.empresa_id = p_empresa
    and m.lote_id is null
    and m.estado = 'activo'
    and m.tipo in ('gasto', 'ingreso')
    and m.fecha between p_desde and p_hasta;

  return v_res;
end $fn$;

revoke all on function public.movimientos_sin_lote(uuid, date, date) from public, anon;
grant execute on function public.movimientos_sin_lote(uuid, date, date) to authenticated;


-- ############################################################
-- ##  046_aviso_de_reserva.sql
-- ############################################################

-- ORDEN · Migración 046 · Avisar al local cuando entra una reserva
--
-- El sentido del link público es que el cliente reserve solo, sin llamar. Pero
-- si al local no le avisa nadie, tiene que entrar a la agenda cada rato a ver
-- si apareció alguien — que es justo el trabajo que el link venía a sacarle.
-- Y con las reservas para el mismo día era peor: la tarea de la tarde solo
-- mira las de MAÑANA, así que quien reservaba a las diez para las cuatro no
-- aparecía en ningún aviso nunca.
--
-- QUIÉN LLAMA A ESTO Y POR QUÉ ES SEGURO
--
-- La ruta `/api/aviso-reserva`, con la clave de servicio, cuando el navegador
-- del cliente le avisa que acaba de reservar. O sea que el disparador viene de
-- afuera, sin sesión, y eso obliga a pensar el abuso:
--
--   · Hace falta el TOKEN de la reserva, que es un uuid que solo conoce quien
--     acaba de reservar. Adivinarlo no es una opción.
--   · Y encima tiene que ser RECIENTE. Un token viejo —el que el cliente
--     guardó para cancelar, por ejemplo— no dispara nada.
--   · La ruta además marca el envío en `envios`, así que un mismo turno no
--     puede avisar dos veces por más que se repita el pedido.
--
-- Las tres juntas hacen que esto no sirva para mandarle notificaciones a un
-- local ajeno ni para repetirle la misma cien veces.
--
-- NO DEVUELVE EL TELÉFONO DEL CLIENTE
--
-- El aviso dice quién reservó, qué y cuándo. El teléfono está a un toque en la
-- agenda, y no hace falta que viaje hasta una notificación para que lo lea
-- cualquiera que mire la pantalla de bloqueo del celular.

create or replace function public.aviso_de_reserva(
  p_token   uuid,
  p_minutos integer default 5
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_res  jsonb;
  v_zona text;
begin
  select coalesce(e.zona_horaria, 'America/Asuncion') into v_zona
  from public.turnos_reserva r
  join public.empresas e on e.id = r.empresa_id
  where r.token = p_token;

  if v_zona is null then
    return null;
  end if;

  select jsonb_build_object(
    'reserva',     r.id,
    'empresa_id',  r.empresa_id,
    'negocio',     e.nombre,
    'cliente',     r.cliente_nombre,
    'servicio',    pr.nombre,
    'profesional', p.nombre,
    -- Ya formateado en la zona del local: la hora que le importa al barbero
    -- es la de su local, no la del servidor ni la del que reservó.
    'hora',        to_char(r.inicia at time zone v_zona, 'HH24:MI'),
    'fecha',       (r.inicia at time zone v_zona)::date,
    'es_hoy',      (r.inicia at time zone v_zona)::date = public.hoy_empresa(r.empresa_id),
    'es_manana',   (r.inicia at time zone v_zona)::date = public.hoy_empresa(r.empresa_id) + 1
  )
  into v_res
  from public.turnos_reserva r
  join public.empresas e on e.id = r.empresa_id
  join public.productos pr on pr.id = r.producto_id
  join public.turnos_profesional p on p.id = r.profesional_id
  where r.token = p_token
    -- Recién hecha. Sin esto, el enlace que el cliente guarda para cancelar
    -- serviría para hacer sonar el teléfono del barbero cuando se le antoje.
    and r.created_at > now() - make_interval(mins => greatest(coalesce(p_minutos, 5), 1))
    -- Una que ya se canceló no se anuncia como nueva.
    and r.estado in ('pendiente', 'confirmada');

  return v_res;
end $fn$;

-- Solo la ruta, que corre con la clave de servicio. Ni un usuario con sesión
-- necesita esto: para eso está la agenda.
revoke all on function public.aviso_de_reserva(uuid, integer) from public, anon, authenticated;
grant execute on function public.aviso_de_reserva(uuid, integer) to service_role;


-- ############################################################
-- ##  047_la_plata_del_dueno.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 047 · La plata del dueño no es del vendedor
--
-- EL PROBLEMA, TAL COMO APARECIÓ
--
-- El dueño paga la cuota de su tarjeta desde Deudas. `registrar_pago_deuda`
-- (015) crea, como corresponde, un movimiento de tipo 'gasto' con la
-- descripción «Pago Tarjeta Visa» y categoría «Deudas»: la plata salió, y
-- tiene que salir en los números del negocio.
--
-- Pero después el vendedor abre Gastos y lo lee.
--
-- No es un descuido de una pantalla: es que NADIE preguntaba de quién era el
-- gasto. `movimientos_select` (002) deja ver todo lo de la empresa a todo
-- miembro, y las funciones de lectura son `security definer`, así que ni
-- siquiera pasan por esa política — suman todo y devuelven el total.
--
-- Por eso el arreglo va en los dos lugares. Cerrar solo la política dejaría
-- los totales mal; cerrar solo las funciones dejaría abierta la consulta
-- directa desde el navegador, que es justamente la que no controlamos.
--
-- LA REGLA, EN UNA LÍNEA
--
--   Las ventas son del negocio y las ve todo el mundo.
--   Todo lo demás —gastos y otros ingresos— lo ve su autor, y el admin.
--
-- POR QUÉ TAMBIÉN LOS OTROS INGRESOS
--
-- Porque están en la misma pantalla y son igual de privados. Si el dueño
-- cobra el alquiler de un local, eso entra como 'ingreso' y aparecía en la
-- lista de Gastos junto a los gastos. Tapar una mitad y dejar la otra sería
-- arreglar la captura de pantalla, no el problema.
--
-- POR QUÉ NO SE LE OCULTAN LAS VENTAS
--
-- Un vendedor tiene que ver cómo va el día: es su trabajo, es lo que mide su
-- comisión y es lo que ya veía. Los costos y el margen de esas ventas siguen
-- volviendo en NULL para él, como desde la 003. Acá no se toca nada de eso.
--
-- LO QUE ESTO NO ES
--
-- No es una sección nueva ni una preferencia. No hay ningún interruptor que
-- el dueño pueda apagar por error: si sos vendedor, no está, y punto.
-- ============================================================

-- ------------------------------------------------------------
-- 1. LA POLÍTICA
--
--    Primera barrera y la única que protege la consulta directa. Alguien con
--    la clave pública del navegador puede pedir `movimientos` sin pasar por
--    ninguna de nuestras funciones; esto es lo que le contesta.
-- ------------------------------------------------------------
drop policy if exists movimientos_select on public.movimientos;
create policy movimientos_select on public.movimientos
  for select using (
    public.es_miembro(empresa_id)
    and (
      tipo = 'venta'
      or public.es_admin(empresa_id)
      or creado_por = auth.uid()
    )
  );

-- ------------------------------------------------------------
-- 2. EL RESUMEN
--
--    De acá salen los indicadores del panel y de Gastos. Es el que mostraba
--    «Gastos del periodo: 15.000.000» a alguien que cargó tres.
--
--    `v_admin` ya existía en esta función para decidir si devuelve los
--    costos. Se reutiliza: una sola idea de «quién ve la plata entera».
-- ------------------------------------------------------------
create or replace function public.resumen_financiero(
  p_empresa uuid,
  p_desde date,
  p_hasta date
)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_admin boolean;
  v_res   jsonb;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  v_admin := public.es_admin(p_empresa);

  with base as (
    select m.tipo, m.estado, m.monto, m.subtotal, m.costo_total, m.id
    from public.movimientos m
    where m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
      -- Acá se cae el gasto del dueño para el vendedor. Va en la CTE y no en
      -- cada `filter` de abajo para que no quede ni un total sin filtrar el
      -- día que se agregue una métrica nueva.
      and (v_admin or m.tipo = 'venta' or m.creado_por = auth.uid())
  ),
  totales as (
    select
      coalesce(sum(monto)       filter (where estado = 'activo' and tipo = 'venta'),   0)::numeric as ventas,
      coalesce(sum(subtotal)    filter (where estado = 'activo' and tipo = 'venta'),   0)::numeric as ventas_brutas,
      coalesce(sum(costo_total) filter (where estado = 'activo' and tipo = 'venta'),   0)::numeric as costo_mercaderia,
      coalesce(sum(monto)       filter (where estado = 'activo' and tipo = 'ingreso'), 0)::numeric as otros_ingresos,
      coalesce(sum(monto)       filter (where estado = 'activo' and tipo = 'gasto'),   0)::numeric as gastos,
      coalesce(count(*)         filter (where estado = 'activo' and tipo = 'venta'),   0)::bigint  as cantidad_ventas,
      coalesce(count(*)         filter (where estado = 'anulado' and tipo = 'venta'),  0)::bigint  as ventas_anuladas,
      coalesce(sum(monto)       filter (where estado = 'anulado' and tipo = 'venta'),  0)::numeric as monto_ventas_anuladas,
      coalesce(count(*)         filter (where estado = 'anulado'),                     0)::bigint  as movimientos_anulados,
      coalesce(sum(monto)       filter (where estado = 'anulado'),                     0)::numeric as monto_movimientos_anulados
    from base
  ),
  unidades as (
    select coalesce(sum(i.cantidad), 0)::numeric as unidades
    from public.movimiento_items i
    join public.movimientos m on m.id = i.movimiento_id
    where i.empresa_id = p_empresa
      and m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
      and m.estado = 'activo'
      and m.tipo = 'venta'
  ),
  derivados as (
    select
      t.*,
      u.unidades,
      (t.ventas + t.otros_ingresos) as ingresos_totales,
      (t.ventas - t.costo_mercaderia) as ganancia_bruta,
      (t.ventas - t.costo_mercaderia + t.otros_ingresos - t.gastos) as ganancia_neta
    from totales t cross join unidades u
  )
  select jsonb_build_object(
    'ventas',                     d.ventas,
    'ventas_brutas',              d.ventas_brutas,
    'descuentos',                 d.ventas_brutas - d.ventas,
    'otros_ingresos',             d.otros_ingresos,
    'ingresos_totales',           d.ingresos_totales,
    'gastos',                     d.gastos,
    'cantidad_ventas',            d.cantidad_ventas,
    'unidades_vendidas',          d.unidades,
    'ticket_promedio',            case when d.cantidad_ventas > 0 then d.ventas / d.cantidad_ventas else 0 end,
    'ventas_anuladas',            d.ventas_anuladas,
    'monto_ventas_anuladas',      d.monto_ventas_anuladas,
    'movimientos_anulados',       d.movimientos_anulados,
    'monto_movimientos_anulados', d.monto_movimientos_anulados,
    'costo_mercaderia', case when v_admin then d.costo_mercaderia else null end,
    'ganancia_bruta',   case when v_admin then d.ganancia_bruta   else null end,
    'ganancia_neta',    case when v_admin then d.ganancia_neta    else null end,
    'margen_bruto',     case when v_admin and d.ventas > 0
                             then (d.ganancia_bruta / d.ventas) * 100 else null end,
    'margen_neto',      case when v_admin and d.ingresos_totales > 0
                             then (d.ganancia_neta / d.ingresos_totales) * 100 else null end,
    'con_costos',       v_admin
  ) into v_res
  from derivados d;

  return v_res;
end $$;

-- ------------------------------------------------------------
-- 3. LA SERIE DIARIA
--
--    El gráfico del panel. Sin esto, el vendedor no leía el número pero veía
--    la barra roja del día que el dueño pagó la cuota.
-- ------------------------------------------------------------
create or replace function public.serie_financiera_diaria(
  p_empresa uuid,
  p_desde date,
  p_hasta date
)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_admin boolean;
  v_dias  integer;
  v_res   jsonb;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  v_dias := (p_hasta - p_desde) + 1;
  if v_dias > 1100 then
    raise exception 'El rango no puede superar los 3 años para la serie diaria.' using errcode = '22023';
  end if;

  v_admin := public.es_admin(p_empresa);

  with dias as (
    select generate_series(p_desde, p_hasta, interval '1 day')::date as fecha
  ),
  porDia as (
    select
      m.fecha,
      coalesce(sum(m.monto)       filter (where m.tipo = 'venta'), 0)::numeric   as ventas,
      coalesce(sum(m.monto)       filter (where m.tipo = 'gasto'), 0)::numeric   as gastos,
      coalesce(sum(m.monto)       filter (where m.tipo = 'ingreso'), 0)::numeric as otros_ingresos,
      coalesce(sum(m.costo_total) filter (where m.tipo = 'venta'), 0)::numeric   as costo
    from public.movimientos m
    where m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
      and m.estado = 'activo'
      and (v_admin or m.tipo = 'venta' or m.creado_por = auth.uid())
    group by m.fecha
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'fecha',          to_char(d.fecha, 'YYYY-MM-DD'),
      'ventas',         coalesce(p.ventas, 0),
      'gastos',         coalesce(p.gastos, 0),
      'otros_ingresos', coalesce(p.otros_ingresos, 0),
      'ganancia', case
        when v_admin then coalesce(p.ventas, 0) - coalesce(p.costo, 0)
                        + coalesce(p.otros_ingresos, 0) - coalesce(p.gastos, 0)
        else null
      end
    ) order by d.fecha
  ), '[]'::jsonb) into v_res
  from dias d
  left join porDia p on p.fecha = d.fecha;

  return v_res;
end $$;

-- ------------------------------------------------------------
-- 4. GASTOS POR CATEGORÍA
--
--    Es el que más contaba de una sola mirada: la categoría «Deudas» con el
--    monto al lado, y el nombre de la deuda en la lista de abajo.
--
--    Esta función no calculaba `v_admin` porque no devolvía costos. Ahora lo
--    necesita.
-- ------------------------------------------------------------
create or replace function public.gastos_por_categoria(
  p_empresa uuid,
  p_desde date,
  p_hasta date
)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_admin boolean;
  v_res   jsonb;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  v_admin := public.es_admin(p_empresa);

  with porCategoria as (
    select
      trim(coalesce(nullif(trim(m.categoria), ''), 'General')) as nombre,
      sum(m.monto)::numeric as monto,
      count(*)::bigint      as operaciones
    from public.movimientos m
    where m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
      and m.estado = 'activo'
      and m.tipo = 'gasto'
      and (v_admin or m.creado_por = auth.uid())
    group by 1
  ),
  con_total as (
    select c.*, sum(c.monto) over () as total from porCategoria c
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'nombre',        c.nombre,
      'monto',         c.monto,
      'operaciones',   c.operaciones,
      'participacion', case when c.total > 0 then (c.monto / c.total) * 100 else 0 end
    ) order by c.monto desc
  ), '[]'::jsonb) into v_res
  from con_total c;

  return v_res;
end $$;

-- ------------------------------------------------------------
-- 5. LA PÁGINA DE MOVIMIENTOS
--
--    La lista que se ve abajo de los indicadores, en Gastos y en
--    Movimientos. Es donde se leía «Pago Tarjeta Visa» con nombre y monto.
-- ------------------------------------------------------------
create or replace function public.pagina_movimientos(
  p_empresa uuid,
  p_desde date,
  p_hasta date,
  p_tamano integer default 100,
  p_cursor_fecha date default null,
  p_cursor_created timestamptz default null,
  p_cursor_id uuid default null,
  p_tipo tipo_movimiento default null,
  p_incluir_anuladas boolean default true,
  p_busqueda text default null
)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_admin   boolean;
  v_tamano  integer;
  v_busca   text;
  v_filas   jsonb;
  v_cuantas integer;
  v_ultima  jsonb;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  v_tamano := least(greatest(coalesce(p_tamano, 100), 1), 500);
  v_admin  := public.es_admin(p_empresa);
  v_busca  := nullif(lower(trim(coalesce(p_busqueda, ''))), '');

  select coalesce(jsonb_agg(to_jsonb(x) order by x.fecha desc, x.created_at desc, x.id desc), '[]'::jsonb)
  into v_filas
  from (
    select
      m.id, m.empresa_id, m.tipo, m.estado, m.fecha, m.descripcion, m.categoria,
      m.subtotal, m.descuento, m.monto,
      case when v_admin then m.costo_total else null end as costo_total,
      m.metodo_pago, m.contraparte, m.notas, m.origen, m.creado_por, m.created_at,
      m.anulado_por, m.anulado_at, m.motivo_anulacion, m.actualizado_por, m.updated_at,
      coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id', i.id,
            'movimiento_id', i.movimiento_id,
            'empresa_id', i.empresa_id,
            'producto_id', i.producto_id,
            'nombre', i.nombre,
            'cantidad', i.cantidad,
            'precio_unitario', i.precio_unitario,
            'costo_unitario', case when v_admin then i.costo_unitario else null end,
            'afecto_stock', i.afecto_stock
          ) order by i.nombre
        )
        from public.movimiento_items i where i.movimiento_id = m.id
      ), '[]'::jsonb) as movimiento_items
    from public.movimientos m
    where m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
      and (v_admin or m.tipo = 'venta' or m.creado_por = auth.uid())
      and (p_tipo is null or m.tipo = p_tipo)
      and (p_incluir_anuladas or m.estado = 'activo')
      and (
        p_cursor_id is null
        or (m.fecha, m.created_at, m.id) < (p_cursor_fecha, p_cursor_created, p_cursor_id)
      )
      and (
        v_busca is null
        or lower(m.descripcion) like '%' || v_busca || '%'
        or lower(m.categoria)   like '%' || v_busca || '%'
        or lower(coalesce(m.contraparte, '')) like '%' || v_busca || '%'
        or exists (
          select 1 from public.movimiento_items i2
          where i2.movimiento_id = m.id and lower(i2.nombre) like '%' || v_busca || '%'
        )
      )
    order by m.fecha desc, m.created_at desc, m.id desc
    limit v_tamano
  ) x;

  v_cuantas := jsonb_array_length(v_filas);
  v_ultima  := case when v_cuantas > 0 then v_filas -> (v_cuantas - 1) else null end;

  return jsonb_build_object(
    'movimientos', v_filas,
    'siguiente', case
      when v_cuantas = v_tamano and v_ultima is not null then jsonb_build_object(
        'fecha',      v_ultima ->> 'fecha',
        'created_at', v_ultima ->> 'created_at',
        'id',         v_ultima ->> 'id'
      )
      else null
    end,
    'tamano', v_tamano
  );
end $$;

-- ------------------------------------------------------------
-- 6. LOS DOS CAMINOS QUE NO USA NINGUNA PANTALLA
--
--    `listar_movimientos` y `contar_movimientos` no los llama nadie hoy. Se
--    cierran igual, y por la misma razón que dice el comentario de la 006:
--    mientras existan son un camino que alguien podría tomar. Una puerta que
--    nadie usa sigue siendo una puerta.
--
--    En `contar_movimientos` el efecto es más chico pero real: el conteo le
--    decía cuántos movimientos hay, y de ahí se deduce cuántos no ve.
-- ------------------------------------------------------------
create or replace function public.listar_movimientos(
  p_empresa uuid,
  p_desde date,
  p_hasta date
)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_admin boolean;
  v_total bigint;
  v_tope  constant integer := 20000;
  v_res   jsonb;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  v_admin := public.es_admin(p_empresa);

  -- El tope se mide sobre lo que esta persona puede ver: si no, a un
  -- vendedor le podría fallar por movimientos que no le vamos a devolver.
  select count(*) into v_total
  from public.movimientos m
  where m.empresa_id = p_empresa
    and m.fecha between p_desde and p_hasta
    and (v_admin or m.tipo = 'venta' or m.creado_por = auth.uid());

  if v_total > v_tope then
    raise exception
      'El periodo elegido tiene % movimientos y el máximo por consulta es %. Elegí un rango más corto para que los totales sean exactos.',
      v_total, v_tope
      using errcode = '54000';
  end if;

  select coalesce(jsonb_agg(to_jsonb(x) order by x.fecha desc, x.created_at desc), '[]'::jsonb)
  into v_res
  from (
    select
      m.id, m.empresa_id, m.tipo, m.estado, m.fecha, m.descripcion, m.categoria,
      m.subtotal, m.descuento, m.monto,
      case when v_admin then m.costo_total else null end as costo_total,
      m.metodo_pago, m.contraparte, m.notas, m.origen, m.creado_por, m.created_at,
      m.anulado_por, m.anulado_at, m.motivo_anulacion, m.actualizado_por, m.updated_at,
      coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id', i.id,
            'movimiento_id', i.movimiento_id,
            'empresa_id', i.empresa_id,
            'producto_id', i.producto_id,
            'nombre', i.nombre,
            'cantidad', i.cantidad,
            'precio_unitario', i.precio_unitario,
            'costo_unitario', case when v_admin then i.costo_unitario else null end,
            'afecto_stock', i.afecto_stock
          ) order by i.nombre
        )
        from public.movimiento_items i where i.movimiento_id = m.id
      ), '[]'::jsonb) as movimiento_items
    from public.movimientos m
    where m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
      and (v_admin or m.tipo = 'venta' or m.creado_por = auth.uid())
  ) x;

  return v_res;
end $$;

create or replace function public.contar_movimientos(
  p_empresa uuid,
  p_desde date,
  p_hasta date
)
returns bigint language plpgsql stable security definer set search_path = public as $$
declare
  v_admin boolean;
  v_total bigint;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  v_admin := public.es_admin(p_empresa);

  select count(*) into v_total
  from public.movimientos m
  where m.empresa_id = p_empresa
    and m.fecha between p_desde and p_hasta
    and (v_admin or m.tipo = 'venta' or m.creado_por = auth.uid());

  return v_total;
end $$;


-- ############################################################
-- ##  048_las_sillas_se_pagan.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 048 · Las sillas se pagan
--
-- LOS DOS AGUJEROS QUE CIERRA
--
-- 1. EL TOPE ERA DEL PLAN, Y EL PLAN ERA UNO SOLO PARA TODOS.
--
--    `limites_plan` da 3 personas en Pro y 15 en Negocio, y no había forma
--    de decir «este negocio pagó por cuatro». Peor: la portada vende Negocio
--    como «sin tope de vendedores» y la base corta en 15. Prometíamos algo
--    que el sistema no cumple, y el que se llevaba la sorpresa era el que ya
--    había pagado.
--
--    Desde acá el tope se escribe por negocio, a mano, en el panel de
--    administración, en el mismo momento en que se cobra. El plan pasa a ser
--    el valor por defecto de quien no tiene nada escrito.
--
-- 2. UN PROFESIONAL SIN CUENTA NO CONTABA PARA NADA.
--
--    `turnos_profesional.user_id` era opcional a propósito (ver la 033), y
--    el argumento no era malo: que el barbero sin celular pueda estar en la
--    agenda. Pero la consecuencia sí lo era. Una peluquería con seis sillas
--    usaba agenda, reparto y comisiones enteras SIN sumar un solo miembro,
--    o sea en el plan gratis. El tope de personas no tocaba el único rubro
--    donde más gente significa más trabajo para el sistema.
--
--    Ahora, para estar en el equipo de reparto hay que ser miembro. Una sola
--    cuenta de «cuántas personas hay acá», y el tope la gobierna entera.
--
-- LO QUE ESTO LE CUESTA AL PRODUCTO, DICHO SIN ADORNO
--
-- El barbero que no tiene celular ya no puede estar en la agenda. Es una
-- pérdida real y fue una decisión tomada a sabiendas: el dueño va a tener
-- que sumarlo como miembro —y pagar su silla— o llevarlo aparte.
--
-- QUÉ PASA CON LOS QUE YA ESTABAN
--
-- No se borra ninguno. Los profesionales sin cuenta se DESACTIVAN, que es
-- reversible y no toca el historial: sus cortes, sus reservas y las
-- liquidaciones ya cerradas quedan intactas. Para recuperarlos, la persona
-- entra con el código del negocio y el dueño lo vuelve a activar.
-- ============================================================

-- ------------------------------------------------------------
-- 1. EL TOPE DE CADA NEGOCIO
--
--    Se escribe en VENDEDORES y no en personas porque es lo que se negocia
--    y se cobra: «pagás por cuatro vendedores». El dueño no es un vendedor
--    al que se le cobre una silla — es el que paga.
--
--    `null` no es cero: significa «este negocio no tiene trato especial,
--    vale lo que diga su plan». Cero sí es cero: el dueño solo.
-- ------------------------------------------------------------
alter table public.suscripciones
  add column if not exists tope_vendedores integer;

do $$
begin
  if not exists (
    select 1 from pg_constraint where conname = 'tope_vendedores_razonable'
  ) then
    alter table public.suscripciones
      add constraint tope_vendedores_razonable
      check (tope_vendedores is null or tope_vendedores between 0 and 200);
  end if;
end $$;

comment on column public.suscripciones.tope_vendedores is
  'Cuántos vendedores pagó este negocio, sin contar al dueño. NULL = lo que diga su plan. Lo escribe la administración al cobrar.';

-- ------------------------------------------------------------
-- 2. CUÁNTAS PERSONAS ENTRAN ACÁ
--
--    Una sola función que responde la pregunta, para que no haya dos
--    lugares que puedan contestar distinto.
--
--    El «+1» es el dueño, y vive únicamente acá. En el panel se escriben
--    vendedores; la tabla `miembros` cuenta personas. Si esa suma estuviera
--    repetida en dos lados, tarde o temprano una de las dos se olvidaría.
--
--    SIN PLAN PAGO NO VALE EL TRATO. Si no, un negocio al que le
--    habilitamos diez sillas se quedaría con las diez el día que deja de
--    pagar, que es exactamente cuando no corresponde.
-- ------------------------------------------------------------
create or replace function public.tope_de_miembros(p_empresa uuid)
returns integer language sql stable security definer set search_path = public as $fn$
  select case
    when public.plan_efectivo_calculado(p_empresa) = 'gratis'
      then (public.limites_plan('gratis')->>'miembros')::integer
    else coalesce(
      (select s.tope_vendedores + 1
       from public.suscripciones s
       where s.empresa_id = p_empresa and s.tope_vendedores is not null),
      (public.limites_plan(public.plan_efectivo_calculado(p_empresa))->>'miembros')::integer
    )
  end;
$fn$;

revoke all on function public.tope_de_miembros(uuid) from public, anon;
grant execute on function public.tope_de_miembros(uuid) to authenticated;

-- ------------------------------------------------------------
-- 3. LA PUERTA DE ENTRADA AL NEGOCIO
--
--    Único lugar donde alguien se suma a una empresa, y por eso único lugar
--    donde hay que contar. Lo que cambia es de dónde sale el tope.
--
--    El mensaje también cambia. El viejo decía «el plan Negocio permite
--    más», que ahora sería mentira: en Negocio el tope también lo ponemos
--    nosotros. Un mensaje de error que manda a la persona equivocada a
--    hacer la cosa equivocada es peor que uno corto.
-- ------------------------------------------------------------
create or replace function public.unirse_empresa(
  p_codigo text,
  p_nombre_usuario text default null
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_id      uuid;
  v_cuantos integer;
  v_tope    integer;
  v_tipo    text;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  select a.empresa_id into v_id
  from public.empresa_accesos a
  where a.codigo = upper(trim(coalesce(p_codigo, ''))) and a.activo;

  if v_id is null then
    raise exception 'El código no corresponde a ninguna empresa.' using errcode = '42501';
  end if;

  -- Ya es miembro: no es un error, simplemente devolvemos la empresa.
  if exists (select 1 from public.miembros where empresa_id = v_id and user_id = auth.uid()) then
    return v_id;
  end if;

  select tipo_cuenta into v_tipo from public.empresas where id = v_id;
  if v_tipo = 'personal' then
    raise exception 'Esa es una cuenta personal: no admite más personas.'
      using errcode = '54000';
  end if;

  select count(*)::int into v_cuantos from public.miembros where empresa_id = v_id;
  v_tope := public.tope_de_miembros(v_id);

  if v_cuantos >= v_tope then
    raise exception
      'Este negocio ya tiene sus % personas. Para sumar a alguien más hay que ampliar el plan.', v_tope
      using errcode = '54000';
  end if;

  insert into public.miembros (empresa_id, user_id, nombre, rol)
  values (v_id, auth.uid(), coalesce(nullif(trim(p_nombre_usuario), ''), 'Colaborador'), 'vendedor')
  on conflict (empresa_id, user_id) do nothing;

  return v_id;
end $fn$;

revoke all on function public.unirse_empresa(text, text) from public, anon;
grant execute on function public.unirse_empresa(text, text) to authenticated;

-- ------------------------------------------------------------
-- 4. EL PANEL: COBRAR Y HABILITAR SON EL MISMO ACTO
--
--    El tope se pone donde se cobra, y no en otra pantalla, porque son la
--    misma decisión: «me pagó por cuatro vendedores hasta el 9 de octubre».
--    Separarlos daría cuentas cobradas y sin habilitar, o al revés.
--
--    `p_vendedores` en null deja el tope como estaba. Para volver al valor
--    del plan hay que mandar -1: sin esa distinción no habría forma de
--    borrar un trato especial, porque null ya significa «no lo toques».
-- ------------------------------------------------------------
create or replace function public.cambiar_plan_cuenta(
  p_empresa    uuid,
  p_plan       text,
  p_meses      integer default 1,
  p_nota       text default '',
  p_importe    numeric default null,
  p_vendedores integer default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_antes    public.suscripciones;
  v_fin      timestamptz;
  v_estado   text;
  v_orden    uuid;
  v_cliente  text;
  v_ingreso  uuid;
  v_aviso    text := null;
  v_tope     integer;
  v_personas integer;
begin
  if not public.es_superadmin() then
    raise exception 'Este panel es solo para la administración de Orden.' using errcode = '42501';
  end if;

  if p_plan not in ('gratis', 'pro', 'negocio') then
    raise exception 'Plan desconocido: %', p_plan using errcode = '22023';
  end if;

  if p_vendedores is not null and p_vendedores < -1 then
    raise exception 'El tope de vendedores no puede ser negativo.' using errcode = '22023';
  end if;

  select * into v_antes from public.suscripciones where empresa_id = p_empresa;
  if v_antes.empresa_id is null then
    raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
  end if;

  select nombre into v_cliente from public.empresas where id = p_empresa;

  if p_plan = 'gratis' then
    v_estado := 'vencida';
    v_fin := now();
    -- Cortar el servicio borra el trato: si vuelve, se negocia de nuevo.
    v_tope := null;
  else
    v_estado := 'activa';
    -- Si todavía le queda tiempo pago, se le suma; si no, arranca hoy.
    v_fin := greatest(coalesce(v_antes.periodo_fin, now()), now())
             + make_interval(months => greatest(1, coalesce(p_meses, 1)));
    v_tope := case
      when p_vendedores is null then v_antes.tope_vendedores  -- no se toca
      when p_vendedores = -1    then null                     -- volver al plan
      else p_vendedores
    end;
  end if;

  update public.suscripciones
  set plan = p_plan,
      estado = v_estado,
      periodo_inicio = case when p_plan = 'gratis' then periodo_inicio else now() end,
      periodo_fin = v_fin,
      tope_vendedores = v_tope,
      proveedor_pago = case when p_plan = 'gratis' then proveedor_pago else 'transferencia' end,
      updated_at = now()
  where empresa_id = p_empresa;

  perform set_config('orden.suscripcion_confiable', '1', true);
  update public.empresas
  set plan = case when p_plan = 'gratis' then 'gratis' else 'pro' end
  where id = p_empresa;
  perform set_config('orden.suscripcion_confiable', '0', true);

  -- ---- ¿le queda gente afuera del tope nuevo? ----
  --
  -- No se echa a nadie: bajar un número en un panel no puede sacarle el
  -- acceso a una persona que hoy está trabajando. Pero hay que decirlo, o
  -- el que lo bajó se entera cuando el cliente reclama.
  if v_tope is not null then
    select count(*)::int into v_personas from public.miembros where empresa_id = p_empresa;
    if v_personas > v_tope + 1 then
      v_aviso := 'Ojo: este negocio ya tiene ' || v_personas || ' personas y le habilitaste '
              || v_tope || ' vendedores (' || (v_tope + 1) || ' con el dueño). '
              || 'No se sacó a nadie, pero no va a poder sumar a nadie más.';
    end if;
  end if;

  -- ---- el cobro, como ingreso de Orden ----
  if p_plan <> 'gratis' and coalesce(p_importe, 0) > 0 then
    select empresa_id into v_orden from public.ajustes_orden where unica;

    if v_orden is null then
      v_aviso := coalesce(v_aviso || ' ', '')
              || 'No hay una empresa de Orden elegida, así que el cobro no se anotó en tus finanzas.';
    elsif v_orden = p_empresa then
      v_aviso := coalesce(v_aviso || ' ', '')
              || 'Esta ES tu empresa, así que no se anotó ningún ingreso.';
    else
      begin
        insert into public.movimientos (
          empresa_id, tipo, estado, fecha, descripcion, categoria,
          subtotal, descuento, monto, costo_total, metodo_pago, contraparte, creado_por
        ) values (
          v_orden, 'ingreso', 'activo', public.hoy_empresa(v_orden),
          'Suscripción ' || coalesce(v_cliente, 'cliente'), 'Suscripciones',
          p_importe, 0, p_importe, 0, 'transferencia',
          left(coalesce(v_cliente, ''), 80), auth.uid()
        )
        returning id into v_ingreso;
      exception when others then
        v_aviso := coalesce(v_aviso || ' ', '')
                || 'La cuenta se activó, pero el ingreso no se pudo anotar: ' || sqlerrm;
      end;
    end if;
  end if;

  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (auth.uid(), p_empresa, 'cambiar_plan', jsonb_build_object(
    'plan_antes', v_antes.plan, 'plan_despues', p_plan,
    'estado_antes', v_antes.estado, 'estado_despues', v_estado,
    'vence_antes', v_antes.periodo_fin, 'vence_despues', v_fin,
    'meses', greatest(1, coalesce(p_meses, 1)),
    'importe', p_importe,
    'tope_antes', v_antes.tope_vendedores,
    'tope_despues', v_tope,
    'ingreso_id', v_ingreso,
    'nota', left(coalesce(p_nota, ''), 300)
  ));

  return jsonb_build_object(
    'plan', p_plan, 'estado', v_estado, 'periodo_fin', v_fin,
    'tope_vendedores', v_tope,
    'personas_permitidas', public.tope_de_miembros(p_empresa),
    'ingreso_anotado', v_ingreso is not null,
    'aviso', v_aviso
  );
end $fn$;

-- La firma de 5 argumentos queda muerta: si no se borra, PostgREST ve dos
-- funciones con el mismo nombre y no sabe cuál llamar. Es la misma razón
-- por la que la 019 borró la de 4.
drop function if exists public.cambiar_plan_cuenta(uuid, text, integer, text, numeric);

revoke all on function public.cambiar_plan_cuenta(uuid, text, integer, text, numeric, integer)
  from public, anon;
grant execute on function public.cambiar_plan_cuenta(uuid, text, integer, text, numeric, integer)
  to authenticated;

-- ------------------------------------------------------------
-- 5. PARA ESTAR EN EL EQUIPO HAY QUE ESTAR EN EL NEGOCIO
--
--    La comprobación de que la cuenta pertenece a esta empresa ya existía
--    desde la 034. Lo único que cambia es que ahora no se puede omitir.
-- ------------------------------------------------------------
create or replace function public.guardar_profesional(
  p_empresa    uuid,
  p_nombre     text,
  p_reparto    text    default 'local',
  p_porcentaje numeric default null,
  p_user       uuid    default null,
  p_id         uuid    default null
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare v_id uuid;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar el equipo.' using errcode = '42501';
  end if;

  if char_length(trim(coalesce(p_nombre, ''))) = 0 then
    raise exception 'Ponele un nombre, para saber de quién es cada corte.' using errcode = '22023';
  end if;

  if coalesce(p_reparto, '') not in ('local', 'comision', 'alquiler', 'sueldo') then
    raise exception 'Ese tipo de arreglo no existe.' using errcode = '22023';
  end if;

  if p_reparto = 'comision'
     and (p_porcentaje is null or p_porcentaje <= 0 or p_porcentaje > 100) then
    raise exception 'Con comisión hace falta un porcentaje entre 1 y 100.' using errcode = '22023';
  end if;

  -- El cambio de la 048. El mensaje explica el camino completo, porque el
  -- dueño está mirando una lista de nombres y no tiene por qué adivinar que
  -- primero hay que pasarle un código.
  if p_user is null then
    raise exception
      'Para estar en el equipo, esa persona tiene que entrar antes al negocio con el código de acceso. Pasale el código, que se cree su cuenta, y después sumala acá.'
      using errcode = '22023';
  end if;

  if not exists (select 1 from public.miembros m
                 where m.empresa_id = p_empresa and m.user_id = p_user) then
    raise exception 'Esa persona no es parte de este negocio.' using errcode = '42501';
  end if;

  if p_id is null then
    insert into public.turnos_profesional (empresa_id, nombre, user_id, reparto, porcentaje)
    values (p_empresa, trim(p_nombre), p_user, p_reparto,
            case when p_reparto = 'comision' then p_porcentaje else null end)
    returning id into v_id;
  else
    update public.turnos_profesional
    set nombre = trim(p_nombre),
        user_id = p_user,
        reparto = p_reparto,
        porcentaje = case when p_reparto = 'comision' then p_porcentaje else null end,
        updated_at = now()
    where id = p_id and empresa_id = p_empresa
    returning id into v_id;

    if v_id is null then
      raise exception 'Esa persona no está en el equipo de esta cuenta.' using errcode = 'P0002';
    end if;
  end if;

  return v_id;
end $fn$;

revoke all on function public.guardar_profesional(uuid, text, text, numeric, uuid, uuid) from public, anon;
grant execute on function public.guardar_profesional(uuid, text, text, numeric, uuid, uuid) to authenticated;

-- ------------------------------------------------------------
-- 6. LOS QUE YA ESTABAN SIN CUENTA
--
--    Se desactivan, no se borran. `activo = false` los saca de la agenda y
--    del reparto de acá en adelante y deja intacto todo lo anterior: sus
--    cortes, sus reservas y las liquidaciones ya cerradas siguen
--    respondiendo por su id.
--
--    Borrarlos habría hecho desaparecer de quién fue cada corte y las
--    liquidaciones del mes pasado dejarían de cerrar — que es exactamente
--    lo que la 034 evita cuando se borra a alguien con cortes cargados.
-- ------------------------------------------------------------
do $$
declare v_cuantos integer;
begin
  update public.turnos_profesional
  set activo = false, updated_at = now()
  where user_id is null and activo;

  get diagnostics v_cuantos = row_count;

  if v_cuantos > 0 then
    raise notice
      'Se desactivaron % profesionales sin cuenta. No se borró ninguno: para recuperarlos, que la persona entre con el código del negocio y volvelos a activar.',
      v_cuantos;
  end if;
end $$;

-- ------------------------------------------------------------
-- 7. QUE EL PANEL PUEDA LEER EL TOPE
--
--    Sin esto, el número se puede escribir y no se puede ver: quien cobra
--    tendría que acordarse de memoria de cuántas sillas le habilitó a cada
--    negocio, o mirar la tabla a mano.
--
--    Van los dos números y no uno solo, a propósito: `tope_vendedores` es lo
--    que se negoció y `personas_permitidas` es lo que la puerta va a contar
--    de verdad. Mostrar solo el primero obligaría a la pantalla a hacer el
--    «+1» por su cuenta, y esa suma tiene que vivir en un solo lugar.
-- ------------------------------------------------------------
create or replace function public.listar_cuentas(
  p_busqueda text default null,
  p_estado   text default null,
  p_limite   integer default 200
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_res jsonb;
  v_periodo text;
begin
  if not public.es_superadmin() then
    raise exception 'Este panel es solo para la administración de Orden.' using errcode = '42501';
  end if;

  v_periodo := to_char(now(), 'YYYY-MM');

  select coalesce(jsonb_agg(x order by x->>'orden'), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'empresa_id',   e.id,
      'nombre',       e.nombre,
      'tipo_cuenta',  e.tipo_cuenta,
      'rubro',        e.rubro,
      'moneda',       e.moneda,
      'creada',       e.created_at,
      'propietario',  coalesce(prop.nombre, ''),
      'correo',       coalesce(u.email, ''),
      'sin_duenio',   prop.id is null,
      'como_nos_conocio', e.como_nos_conocio,

      'contacto',  coalesce(f.contacto, ''),
      'telefono',  coalesce(f.telefono, ''),
      'se_dedica', coalesce(f.se_dedica, ''),
      'notas',     coalesce(f.notas, ''),

      'plan',         public.plan_efectivo_calculado(e.id),
      'plan_guardado', s.plan,
      'estado',       s.estado,
      'periodo_fin',  s.periodo_fin,
      'prueba_fin',   s.prueba_fin,
      'dias_restantes', case
        when s.periodo_fin is null then null
        else floor(extract(epoch from (s.periodo_fin - now())) / 86400)::integer
      end,
      'miembros', (select count(*) from public.miembros m where m.empresa_id = e.id),
      -- Lo negociado y lo que la puerta cuenta. Ver el comentario de arriba.
      'tope_vendedores',     s.tope_vendedores,
      'personas_permitidas', public.tope_de_miembros(e.id),
      'movimientos', (select count(*) from public.movimientos mv where mv.empresa_id = e.id),
      'ultima_actividad', (select max(mv.created_at) from public.movimientos mv where mv.empresa_id = e.id),
      'ia_usada', coalesce((
        select ui.usados from public.uso_ia ui
        where ui.empresa_id = e.id and ui.periodo = v_periodo
      ), 0),
      'ia_tope', (public.limites_plan(public.plan_efectivo_calculado(e.id))->>'capturas_mes')::integer,
      'puede_deshacer', exists (
        select 1 from public.registro_admin r
        where r.empresa_id = e.id
          and r.accion in ('cambiar_plan', 'extender_prueba')
          and not coalesce((r.detalle->>'deshecho')::boolean, false)
      ),
      'orden', lpad(
        greatest(0, coalesce(
          floor(extract(epoch from (s.periodo_fin - now())) / 86400)::integer + 1000,
          9999))::text, 5, '0')
    ) as x
    from public.empresas e
    join public.suscripciones s on s.empresa_id = e.id
    left join public.miembros prop
      on prop.empresa_id = e.id and prop.rol = 'propietario'
    left join auth.users u on u.id = prop.user_id
    left join public.ficha_cliente f on f.empresa_id = e.id
    where (
        p_busqueda is null
        or trim(p_busqueda) = ''
        or e.nombre ilike '%' || trim(p_busqueda) || '%'
        or coalesce(u.email, '') ilike '%' || trim(p_busqueda) || '%'
        or coalesce(f.contacto, '') ilike '%' || trim(p_busqueda) || '%'
        or coalesce(f.telefono, '') ilike '%' || trim(p_busqueda) || '%'
      )
      and (p_estado is null or trim(p_estado) = '' or s.estado = p_estado)
    limit greatest(1, least(coalesce(p_limite, 200), 500))
  ) t;

  return v_res;
end $fn$;

revoke all on function public.listar_cuentas(text, text, integer) from public, anon;
grant execute on function public.listar_cuentas(text, text, integer) to authenticated;


-- ############################################################
-- ##  049_prueba_mas_corta.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 049 · La prueba, más corta
--
-- 20 días para un negocio y 14 para una cuenta personal pasan a ser 8 y 5.
--
-- POR QUÉ SE TOCA UNA SOLA FUNCIÓN
--
-- `dias_de_prueba()` la llama `crear_empresa()` UNA vez, en el momento de
-- nacer la cuenta, y escribe el resultado en `suscripciones.prueba_fin`.
-- Desde ahí manda esa fecha y nadie vuelve a preguntar.
--
-- Eso tiene una consecuencia que conviene saber y no descubrir después:
-- A NADIE QUE YA ESTÉ PROBANDO SE LE ACORTA LA PRUEBA. Quien entró ayer
-- con 20 días sigue teniendo sus 20. El número nuevo solo lo ven las
-- cuentas que se creen a partir de acá.
--
-- Y así tiene que ser. Recortarle la prueba a alguien que la está usando es
-- cambiarle el trato después de haberlo hecho — la misma razón por la que
-- `extender_prueba()` (016) solo estira y nunca acorta.
--
-- LA OTRA MITAD DE ESTE CAMBIO NO ESTÁ ACÁ
--
-- El número está escrito a mano en la portada y en los Términos del
-- servicio. Si se cambia solo esto, la web sigue prometiendo 20 días y la
-- persona entra y tiene 8: un reclamo con la razón entera del lado del
-- cliente. Por eso, junto con esta migración, la web pasa a leer el número
-- de un solo lugar (`DIAS_DE_PRUEBA` en src/lib/precios.ts) y hay una
-- prueba que compara ese archivo contra esta función y falla si se separan.
-- ============================================================

create or replace function public.dias_de_prueba(p_tipo text)
returns integer language sql immutable set search_path = public as $fn$
  select case coalesce(p_tipo, 'emprendedor')
    -- Quien anota sus gastos personales sabe en pocos días si le sirve:
    -- lo usa todos los días desde el primero.
    when 'personal' then 5
    -- Un comercio necesita ver un pedazo de semana suyo —los días flojos y
    -- los buenos— antes de poder decidir.
    else 8
  end;
$fn$;

grant execute on function public.dias_de_prueba(text) to anon, authenticated;


-- ############################################################
-- ##  050_el_precio_del_vendedor.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 050 · El precio del vendedor, donde viven los precios
--
-- DOS COSAS MAL, Y LA SEGUNDA ES LA QUE IMPORTA
--
-- 1. El número en dólares estaba mal. `precio_por_vendedor` (017) devolvía
--    60.000 Gs. y US$ 7,99, o sea un cambio de 7.509 Gs. por dólar. Los
--    planes usan entre 5.937 y 5.952 (190.000 = 32, 250.000 = 42), así que
--    ese 7,99 no salía de ningún lado. Pasa a US$ 11, que es el número que
--    se decidió.
--
--    Los 60.000 con los 11 dan 5.454, que tampoco es exactamente el cambio
--    de los planes, y está bien: son dos precios redondos, uno en cada
--    moneda. Un precio se elige, no se calcula con la calculadora del día.
--
-- 2. Estaba escrito a mano adentro de una función.
--
--    El módulo de precios lo dice desde el primer día: «Los importes viven en
--    la tabla `precios`, no acá: cambiar un precio no puede requerir un
--    despliegue». Este número se saltó esa regla, y cambiarlo obligaba a
--    escribir una migración y desplegar — para tocar un precio.
--
--    Eso no es solo incómodo. Un precio que cuesta cambiar se cambia tarde, y
--    mientras tanto la portada le está diciendo un número a la gente.
--
-- POR QUÉ UNA TABLA APARTE Y NO UNA FILA EN `precios`
--
-- `precios` está indexada por (tipo_cuenta, plan, moneda, periodo) y su check
-- solo admite los planes 'pro' y 'negocio'. Meter al vendedor ahí obligaría a
-- ensanchar ese check con un plan que no es un plan, y `lista_precios()` lo
-- devolvería junto a los demás: la pantalla de planes mostraría «Vendedor»
-- como si fuera una opción a contratar.
--
-- Un vendedor no es un plan: es algo que se suma a uno. Tabla propia.
-- ============================================================

-- ------------------------------------------------------------
-- 1. LO QUE SE COBRA ADEMÁS DEL PLAN
--
--    `concepto` con lista cerrada y no texto libre: el día que haya un
--    segundo agregado, va a haber que escribirlo acá y pensarlo, en vez de
--    que aparezca una fila con una palabra que nadie sabe de dónde salió.
-- ------------------------------------------------------------
create table if not exists public.precios_adicionales (
  concepto   text not null check (concepto in ('vendedor')),
  moneda     text not null check (moneda in ('PYG', 'USD', 'ARS', 'BRL', 'EUR')),
  importe    numeric(14,2) not null check (importe > 0),
  activo     boolean not null default true,
  updated_at timestamptz not null default now(),
  primary key (concepto, moneda)
);

comment on table public.precios_adicionales is
  'Lo que se cobra ADEMÁS del plan. Hoy solo el vendedor extra. Se edita acá, sin desplegar nada.';

alter table public.precios_adicionales enable row level security;

-- Pública igual que `precios`: la portada la muestra antes de que la persona
-- se registre.
drop policy if exists precios_adicionales_select on public.precios_adicionales;
create policy precios_adicionales_select on public.precios_adicionales
  for select using (activo);

revoke all on public.precios_adicionales from anon, authenticated;
grant select on public.precios_adicionales to anon, authenticated;

-- ------------------------------------------------------------
-- 2. LOS IMPORTES
--
--    Idempotente: correr esta migración dos veces no duplica ni pisa con
--    valores viejos algo que se haya ajustado a mano después.
-- ------------------------------------------------------------
insert into public.precios_adicionales (concepto, moneda, importe) values
  ('vendedor', 'PYG', 60000),
  ('vendedor', 'USD', 11)
on conflict (concepto, moneda) do update
  set importe = excluded.importe, updated_at = now();

-- ------------------------------------------------------------
-- 3. LA FUNCIÓN, AHORA LEYENDO
--
--    Deja de ser `immutable` —lee una tabla— y pasa a `stable`. Si no se
--    cambiara, PostgreSQL podría cachear el valor viejo dentro de una misma
--    consulta y el precio nuevo no aparecería.
--
--    NO lleva `security definer`, y eso es deliberado. La primera versión de
--    esta migración se lo puso por costumbre y la prueba de permisos la
--    frenó: hay un control que lista qué funciones `security definer` pueden
--    estar abiertas a `anon`, y esta no tiene por qué estarlo. La tabla ya es
--    pública por su política; no hace falta prestarle a nadie privilegios que
--    no necesita para leer un precio.
--
--    Sin fila devuelve NULL, y eso está bien: la portada ya sabe no mostrar
--    la nota cuando no hay número. Mejor no decir nada que decir un importe
--    inventado sobre algo que se cobra.
-- ------------------------------------------------------------
create or replace function public.precio_por_vendedor(p_moneda text default 'PYG')
returns numeric language sql stable set search_path = public as $fn$
  select a.importe
  from public.precios_adicionales a
  where a.concepto = 'vendedor'
    and a.moneda = upper(coalesce(nullif(trim(p_moneda), ''), 'PYG'))
    and a.activo;
$fn$;

grant execute on function public.precio_por_vendedor(text) to anon, authenticated;


-- ############################################################
-- ##  051_ver_en_otra_moneda.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 051 · Ver en otra moneda
--
-- LO QUE HAY HOY ESTÁ MAL, Y ES PEOR QUE QUE FALTE
--
-- En Ajustes se puede cambiar la moneda del negocio, y NO CONVIERTE NADA:
-- solo cambia la etiqueta. Quien pasa de guaraníes a dólares ve sus
-- 5.000.000 de ventas convertidos en «US$ 5.000.000». El panel, los reportes
-- y el Excel pasan a mentir, sin un aviso, sin un error, y con los mismos
-- números de siempre — que es lo que lo hace difícil de notar.
--
-- LA DIFERENCIA ENTRE LAS DOS COSAS
--
-- Hay dos preguntas distintas que se estaban contestando con un solo campo:
--
--   `moneda`        → en qué moneda cargás. Es la moneda de tus datos.
--                     Cada importe guardado está en ESTA y en ninguna otra.
--   `moneda_vista`  → en qué moneda querés MIRARLOS ahora.
--
-- La primera se elige al abrir la cuenta y no se cambia más. La segunda se
-- cambia cuando se quiera, no toca un solo dato guardado, y se puede volver
-- atrás sin consecuencias.
--
-- POR QUÉ LA COTIZACIÓN LA PONE EL NEGOCIO
--
-- Porque no hay «el» cambio: hay el del banco, el de la casa de cambio de la
-- esquina y el que le hizo su proveedor. Traerlo de una API sería inventar
-- una precisión que no tenemos y, peor, cambiaría los números de ayer sin
-- que nadie toque nada. El dueño escribe el suyo y sabe de dónde salió.
--
-- Y POR QUÉ SE GUARDA LA FECHA
--
-- Porque una cotización de hace tres meses mostrada como número de hoy es
-- otra forma de mentir. La pantalla dice «al cambio 7.300, cargado el 5/9»:
-- el que lo lee decide si le sirve.
-- ============================================================

-- ------------------------------------------------------------
-- 1. LOS TRES CAMPOS
--
--    `cotizacion` es CUÁNTO VALE UNA UNIDAD DE `moneda_vista` EN `moneda`.
--    Con moneda = PYG y vista = USD, es «a cuánto está el dólar»: 7300.
--    Se guarda en esa dirección y no al revés porque es la que la persona
--    dice en voz alta, y la que va a escribir sin pensarlo dos veces.
--
--    Para convertir: importe_a_la_vista = importe_guardado / cotizacion.
-- ------------------------------------------------------------
alter table public.empresas
  add column if not exists moneda_vista  text,
  add column if not exists cotizacion    numeric(18,6),
  add column if not exists cotizacion_at timestamptz;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'vista_moneda_conocida') then
    alter table public.empresas add constraint vista_moneda_conocida
      check (moneda_vista is null or moneda_vista in ('PYG', 'USD', 'ARS', 'BRL', 'EUR'));
  end if;

  -- Una vista sin cotización no se puede calcular, y una cotización en cero
  -- o negativa daría importes infinitos o con el signo cambiado. Las dos
  -- cosas van juntas o no va ninguna.
  if not exists (select 1 from pg_constraint where conname = 'vista_con_cotizacion') then
    alter table public.empresas add constraint vista_con_cotizacion
      check (
        (moneda_vista is null and cotizacion is null)
        or (moneda_vista is not null and cotizacion is not null and cotizacion > 0)
      );
  end if;
end $$;

comment on column public.empresas.moneda_vista is
  'Solo para MIRAR. Los importes se guardan siempre en `moneda`. NULL = se ve en la moneda propia.';
comment on column public.empresas.cotizacion is
  'Cuánto vale 1 unidad de `moneda_vista` en `moneda`. Con PYG y USD: a cuánto está el dólar.';

-- ------------------------------------------------------------
-- 2. LA MONEDA DE LOS DATOS NO SE TOCA DESPUÉS
--
--    Este es el arreglo del error de hoy. Cambiar `moneda` con movimientos
--    cargados no convierte nada: reetiqueta el historial entero y lo vuelve
--    falso.
--
--    No se prohíbe siempre, y eso importa: quien se equivocó al abrir la
--    cuenta y todavía no cargó nada tiene que poder corregirlo. Lo que no se
--    puede es reetiquetar plata que ya existe.
--
--    Va como trigger y no como política de RLS porque una política mira la
--    fila, no lo que cambió en ella. Esto necesita comparar el antes con el
--    después.
-- ------------------------------------------------------------
create or replace function public.moneda_no_se_reetiqueta()
returns trigger language plpgsql security definer set search_path = public as $fn$
begin
  if new.moneda is distinct from old.moneda
     and exists (select 1 from public.movimientos m where m.empresa_id = old.id) then
    raise exception
      'Ya tenés movimientos cargados en %, así que la moneda del negocio no se puede cambiar: se reetiquetaría todo tu historial sin convertirlo. Si querés ver tus números en otra moneda, usá «Ver en» y poné la cotización.',
      old.moneda
      using errcode = '22023';
  end if;

  -- Si se cambia la moneda de los datos, una vista vieja deja de tener
  -- sentido: la cotización que había era contra la moneda anterior.
  if new.moneda is distinct from old.moneda then
    new.moneda_vista  := null;
    new.cotizacion    := null;
    new.cotizacion_at := null;
  end if;

  -- Ver en la misma moneda que se carga no es una vista: es no tener
  -- ninguna. Se normaliza acá para que no haya dos maneras de decir lo mismo
  -- y una pantalla muestre «al cambio 1,00».
  if new.moneda_vista = new.moneda then
    new.moneda_vista  := null;
    new.cotizacion    := null;
    new.cotizacion_at := null;
  end if;

  return new;
end $fn$;

drop trigger if exists moneda_no_se_reetiqueta on public.empresas;
create trigger moneda_no_se_reetiqueta
  before update on public.empresas
  for each row execute function public.moneda_no_se_reetiqueta();

-- Una función de trigger no la llama nadie a mano: la dispara PostgreSQL.
-- Por defecto queda ejecutable por todos, y como es `security definer` eso
-- la deja abierta a `anon` sin ninguna razón. La prueba de permisos tiene un
-- control que lista cuáles pueden estarlo y frenó esto — es la segunda vez
-- esta semana que ataja un `security definer` puesto por costumbre.
--
-- Revocar no rompe el trigger: el permiso se comprueba al CREAR el trigger,
-- no cada vez que se dispara.
revoke all on function public.moneda_no_se_reetiqueta() from public, anon, authenticated;

-- ------------------------------------------------------------
-- 3. GUARDAR LA VISTA
--
--    Por función y no por UPDATE directo porque hay que escribir la fecha, y
--    la fecha es la mitad del dato: sin ella, la pantalla no puede decir de
--    cuándo es el cambio que está usando.
--
--    `p_moneda` en null apaga la vista y vuelve a la moneda propia.
-- ------------------------------------------------------------
create or replace function public.guardar_vista_moneda(
  p_empresa    uuid,
  p_moneda     text default null,
  p_cotizacion numeric default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_propia text;
  v_moneda text;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el propietario o un administrador puede cambiar esto.' using errcode = '42501';
  end if;

  select moneda into v_propia from public.empresas where id = p_empresa;
  if v_propia is null then
    raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
  end if;

  v_moneda := nullif(upper(trim(coalesce(p_moneda, ''))), '');

  -- Apagar la vista: se vuelve a ver en la moneda propia.
  if v_moneda is null or v_moneda = v_propia then
    update public.empresas
    set moneda_vista = null, cotizacion = null, cotizacion_at = null
    where id = p_empresa;
    return jsonb_build_object('moneda_vista', null, 'cotizacion', null);
  end if;

  if v_moneda not in ('PYG', 'USD', 'ARS', 'BRL', 'EUR') then
    raise exception 'No conocemos esa moneda.' using errcode = '22023';
  end if;

  if p_cotizacion is null or p_cotizacion <= 0 then
    raise exception 'Poné a cuánto está el cambio: sin eso no se puede convertir nada.'
      using errcode = '22023';
  end if;

  -- Un tope alto y no una validación fina. No sabemos cuánto vale una moneda
  -- mañana; lo único que se puede afirmar es que un dedazo de más ceros no
  -- es un tipo de cambio.
  if p_cotizacion > 100000000 then
    raise exception 'Esa cotización es demasiado grande. Revisá los ceros.' using errcode = '22023';
  end if;

  update public.empresas
  set moneda_vista = v_moneda, cotizacion = p_cotizacion, cotizacion_at = now()
  where id = p_empresa;

  return jsonb_build_object(
    'moneda_vista', v_moneda,
    'cotizacion', p_cotizacion,
    'desde', v_propia
  );
end $fn$;

revoke all on function public.guardar_vista_moneda(uuid, text, numeric) from public, anon;
grant execute on function public.guardar_vista_moneda(uuid, text, numeric) to authenticated;


-- ############################################################
-- ##  052_clientes_a_tabla.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 052 · Los clientes del negocio
--
-- LO QUE PASA HOY
--
-- Cuando alguien reserva un turno, su nombre y su teléfono quedan sueltos
-- adentro de esa reserva (`turnos_reserva.cliente_nombre`). Si Juan viene
-- diez veces, hay diez reservas y ningún Juan: no se puede ver su historial,
-- ni cuándo vino por última vez, ni cuánto dejó en el local.
--
-- Y al vender o al agendar hay que volver a escribir el nombre y el número
-- todas las veces.
--
-- LA IDENTIDAD ES EL TELÉFONO, NO EL NOMBRE
--
-- Hay tres Juan; hay un solo 0981 234 567. Por eso el teléfono es lo único
-- que no se puede repetir dentro de un negocio, y por eso se compara
-- normalizado —solo los dígitos—: «0981 234 567», «0981234567» y
-- «0981-234-567» son la misma persona, y si se guardaran como tres clientes
-- distintos el historial quedaría partido en tres sin que nadie lo note.
--
-- PERO EL TELÉFONO PUEDE FALTAR
--
-- En un almacén entra gente que compra fiado y no deja número. Obligarlo
-- haría que el que atiende invente uno —«0000000»— y entonces sí se
-- mezclarían clientes distintos. Sin teléfono, cada uno es una ficha aparte:
-- es peor para buscar y es lo correcto.
--
-- ESTO NO ES LA FICHA DE `ficha_cliente`
--
-- Aquella (022) son los clientes de ORDEN, para tu panel de administración:
-- a quién le vendemos el sistema. Esta son los clientes DEL NEGOCIO: a quién
-- le vende él. Se llaman parecido y no tienen nada que ver.
-- ============================================================

-- ------------------------------------------------------------
-- 1. LA TABLA
--
--    `telefono_norm` es una columna generada y no algo que escriba la
--    aplicación: así no hay forma de guardar una fila cuyo teléfono
--    normalizado no corresponda a su teléfono. Un dato derivado que se
--    escribe a mano se desincroniza el día que alguien haga un UPDATE
--    directo, y ese día dos clientes pasan a ser el mismo.
-- ------------------------------------------------------------
create table if not exists public.clientes (
  id         uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas (id) on delete cascade,
  nombre     text not null check (char_length(trim(nombre)) between 1 and 80),
  telefono   text not null default '' check (char_length(telefono) <= 40),
  -- Solo los dígitos. Es lo que se compara para saber si ya existe.
  telefono_norm text generated always as
    (regexp_replace(coalesce(telefono, ''), '\D', '', 'g')) stored,
  notas      text not null default '' check (char_length(notas) <= 1000),
  activo     boolean not null default true,
  creado_por uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  -- Para que otras tablas puedan apuntar acá SIN poder cruzar de empresa.
  -- Es el mismo candado estructural que usan los lotes (044): con una clave
  -- compuesta, una reserva de la empresa A no puede referirse a un cliente
  -- de la B ni con un UPDATE a mano.
  constraint clientes_id_empresa unique (id, empresa_id)
);

comment on table public.clientes is
  'Los clientes DEL NEGOCIO. No confundir con ficha_cliente (022), que son los clientes de Orden.';

-- Un teléfono, un cliente. Los que no dejaron número quedan afuera del
-- índice y por eso pueden repetirse: no hay con qué distinguirlos.
create unique index if not exists clientes_telefono_unico
  on public.clientes (empresa_id, telefono_norm)
  where telefono_norm <> '';

create index if not exists clientes_empresa_nombre_idx
  on public.clientes (empresa_id, lower(nombre)) where activo;

-- ------------------------------------------------------------
-- 2. QUIÉN LOS VE
--
--    Cualquier miembro. No es un descuido: el que atiende el mostrador es
--    justamente el que necesita el nombre y el número para agendar y para
--    cobrar, y esconderlos lo obligaría a llevar la libreta aparte.
--
--    Vale decir lo que eso implica: un vendedor puede ver la agenda de
--    teléfonos de la clientela, y el día que se va, se la lleva. Es una
--    decisión de producto, no un olvido. Si algún día molesta, el lugar de
--    cambiarla es esta política y nada más.
-- ------------------------------------------------------------
alter table public.clientes enable row level security;

drop policy if exists clientes_select on public.clientes;
create policy clientes_select on public.clientes
  for select using (public.es_miembro(empresa_id));

-- Se escribe por función, no directo: hay que normalizar, buscar duplicados
-- y no dejar que se cambie de empresa una ficha existente.
revoke all on public.clientes from anon, authenticated;
grant select on public.clientes to authenticated;

-- ------------------------------------------------------------
-- 3. GUARDAR UN CLIENTE
--
--    Lo puede hacer cualquier miembro, incluido un vendedor: es lo que pasa
--    cuando alguien llama al local y el que atiende lo anota.
--
--    Con `p_id` edita; sin él, crea. Y si el teléfono ya es de otro cliente
--    del mismo negocio, no crea un duplicado: devuelve el que existe con el
--    nombre actualizado. Un mostrador con dos «Juan 0981...» es peor que uno
--    con el nombre viejo.
-- ------------------------------------------------------------
create or replace function public.guardar_cliente(
  p_empresa  uuid,
  p_nombre   text,
  p_telefono text default '',
  p_notas    text default '',
  p_id       uuid default null
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_id     uuid;
  v_nombre text;
  v_tel    text;
  v_norm   text;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  v_nombre := trim(coalesce(p_nombre, ''));
  if char_length(v_nombre) = 0 then
    raise exception 'Ponele un nombre, para saber de quién estamos hablando.' using errcode = '22023';
  end if;
  v_nombre := left(v_nombre, 80);

  v_tel  := left(trim(coalesce(p_telefono, '')), 40);
  v_norm := regexp_replace(v_tel, '\D', '', 'g');

  -- Un teléfono de dos dígitos no es un teléfono: es un dedazo. Se guarda
  -- vacío antes que guardar algo que después va a hacer chocar a dos
  -- personas distintas en el mismo índice.
  if v_norm <> '' and char_length(v_norm) < 6 then
    v_tel := '';
    v_norm := '';
  end if;

  if p_id is not null then
    update public.clientes
    set nombre = v_nombre,
        telefono = v_tel,
        notas = left(coalesce(p_notas, ''), 1000),
        updated_at = now()
    where id = p_id and empresa_id = p_empresa
    returning id into v_id;

    if v_id is null then
      raise exception 'Ese cliente no es de esta cuenta.' using errcode = 'P0002';
    end if;
    return v_id;
  end if;

  -- Sin id: si el teléfono ya está, es la misma persona.
  if v_norm <> '' then
    select c.id into v_id
    from public.clientes c
    where c.empresa_id = p_empresa and c.telefono_norm = v_norm;

    if v_id is not null then
      update public.clientes
      set nombre = v_nombre,
          notas = case when trim(coalesce(p_notas, '')) = '' then notas
                       else left(p_notas, 1000) end,
          activo = true,
          updated_at = now()
      where id = v_id;
      return v_id;
    end if;
  end if;

  insert into public.clientes (empresa_id, nombre, telefono, notas, creado_por)
  values (p_empresa, v_nombre, v_tel, left(coalesce(p_notas, ''), 1000), auth.uid())
  returning id into v_id;

  return v_id;
end $fn$;

revoke all on function public.guardar_cliente(uuid, text, text, text, uuid) from public, anon;
grant execute on function public.guardar_cliente(uuid, text, text, text, uuid) to authenticated;

-- ------------------------------------------------------------
-- 4. ENCONTRAR O CREAR, PARA USO INTERNO
--
--    Lo que llaman las reservas. No comprueba pertenencia porque quien la
--    llama ya la comprobó —o es la puerta pública, que no tiene a quién
--    comprobarle— y por eso NO se le da permiso a nadie desde afuera.
--
--    Devuelve null si no hay con qué identificar a nadie, en vez de crear
--    una ficha vacía: mejor una reserva sin cliente que una lista de
--    clientes llena de fantasmas.
-- ------------------------------------------------------------
create or replace function public.cliente_de_contacto(
  p_empresa  uuid,
  p_nombre   text,
  p_telefono text
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_id     uuid;
  v_nombre text;
  v_tel    text;
  v_norm   text;
begin
  v_nombre := left(trim(coalesce(p_nombre, '')), 80);
  if char_length(v_nombre) = 0 then return null; end if;

  v_tel  := left(trim(coalesce(p_telefono, '')), 40);
  v_norm := regexp_replace(v_tel, '\D', '', 'g');
  if char_length(v_norm) < 6 then
    v_tel := '';
    v_norm := '';
  end if;

  if v_norm <> '' then
    select c.id into v_id
    from public.clientes c
    where c.empresa_id = p_empresa and c.telefono_norm = v_norm;

    if v_id is not null then
      -- El nombre se refresca: la gente cambia cómo se anota, y el último
      -- que dio es el que reconoce quien atiende.
      update public.clientes
      set nombre = v_nombre, activo = true, updated_at = now()
      where id = v_id;
      return v_id;
    end if;
  end if;

  -- Sin teléfono no se crea nada desde acá. Una reserva puede no tener
  -- cliente; una lista de clientes con veinte «Juan» sin número no sirve
  -- para nada y ensucia la búsqueda para siempre.
  if v_norm = '' then return null; end if;

  insert into public.clientes (empresa_id, nombre, telefono, creado_por)
  values (p_empresa, v_nombre, v_tel, auth.uid())
  returning id into v_id;

  return v_id;
end $fn$;

revoke all on function public.cliente_de_contacto(uuid, text, text) from public, anon, authenticated;

-- ------------------------------------------------------------
-- 5. LA LISTA Y LA BÚSQUEDA
--
--    Dos funciones y no una: la lista es la sección de Clientes y la
--    búsqueda es el buscador de cuando estás vendiendo o agendando. La
--    segunda tiene que ser corta y rápida; la primera, completa.
--
--    Las dos devuelven UNA fila con un jsonb adentro, como el resto de las
--    lecturas desde la 006: así el tope de filas de la Data API no puede
--    recortar media lista sin avisar.
-- ------------------------------------------------------------
create or replace function public.buscar_clientes(
  p_empresa uuid,
  p_texto   text default '',
  p_limite  integer default 8
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_res   jsonb;
  v_busca text;
  v_norm  text;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  v_busca := lower(trim(coalesce(p_texto, '')));
  v_norm  := regexp_replace(v_busca, '\D', '', 'g');

  select coalesce(jsonb_agg(to_jsonb(x) order by x.nombre), '[]'::jsonb) into v_res
  from (
    select c.id, c.nombre, c.telefono
    from public.clientes c
    where c.empresa_id = p_empresa
      and c.activo
      and (
        v_busca = ''
        or lower(c.nombre) like '%' || v_busca || '%'
        -- Buscar por número escrito de cualquier manera.
        or (v_norm <> '' and c.telefono_norm like '%' || v_norm || '%')
      )
    order by c.nombre
    limit least(greatest(coalesce(p_limite, 8), 1), 50)
  ) x;

  return v_res;
end $fn$;

revoke all on function public.buscar_clientes(uuid, text, integer) from public, anon;
grant execute on function public.buscar_clientes(uuid, text, integer) to authenticated;


-- ############################################################
-- ##  053_clientes_b_agenda.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 053 · Cada reserva deja un cliente
--
-- Lo que pidió el dueño, textual: «reservó un servicio y ya queda registrado
-- ese cliente».
--
-- POR QUÉ UN TRIGGER Y NO UNA LÍNEA EN CADA FUNCIÓN
--
-- Hay dos puertas por donde entra una reserva —`reservar()` desde el local y
-- `reservar_publico()` desde el link que comparte el dueño— y las dos tienen
-- que registrar al cliente. Poner la llamada en cada una significa que el día
-- que se agregue una tercera puerta, o que alguien toque una de las dos, la
-- regla se puede caer de una sola y nadie lo va a notar: las reservas van a
-- seguir funcionando, solo que sin cliente.
--
-- Con un trigger la regla se escribe una vez y no hay forma de esquivarla,
-- ni siquiera con un INSERT a mano desde el editor SQL.
--
-- LO QUE EL TRIGGER NO HACE
--
-- No inventa clientes. Si la reserva no trae teléfono, `cliente_de_contacto`
-- devuelve null y la reserva queda sin cliente — que es lo correcto: no hay
-- con qué distinguir a esa persona de la próxima que se llame igual.
-- ============================================================

-- ------------------------------------------------------------
-- 1. LA COLUMNA
--
--    La clave compuesta contra `clientes (id, empresa_id)` es la que impide
--    que una reserva de un negocio apunte al cliente de otro. No es
--    prolijidad: es lo único que lo impide incluso ante un UPDATE directo.
--
--    `on delete set null` y no `cascade`: borrar una ficha de cliente no
--    puede hacer desaparecer un turno que existió y se cobró.
-- ------------------------------------------------------------
alter table public.turnos_reserva
  add column if not exists cliente_id uuid;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'reserva_cliente_misma_empresa') then
    alter table public.turnos_reserva
      add constraint reserva_cliente_misma_empresa
      foreign key (cliente_id, empresa_id)
      references public.clientes (id, empresa_id)
      on delete set null;
  end if;
end $$;

create index if not exists turnos_reserva_cliente_idx
  on public.turnos_reserva (cliente_id) where cliente_id is not null;

-- ------------------------------------------------------------
-- 2. EL TRIGGER
-- ------------------------------------------------------------
create or replace function public.reserva_registra_cliente()
returns trigger language plpgsql security definer set search_path = public as $fn$
begin
  -- Si ya viene con cliente (por ejemplo, se lo eligió de la lista al
  -- agendar), no se toca: quien lo eligió sabe mejor que el teléfono.
  if new.cliente_id is null then
    new.cliente_id := public.cliente_de_contacto(
      new.empresa_id, new.cliente_nombre, new.cliente_telefono);
  end if;
  return new;
end $fn$;

-- Una función de trigger no la llama nadie a mano: la dispara PostgreSQL, y
-- dejarla ejecutable por todos la abriría a `anon` sin ninguna razón. El
-- permiso se comprueba al CREAR el trigger, no cada vez que se dispara.
revoke all on function public.reserva_registra_cliente() from public, anon, authenticated;

drop trigger if exists reserva_registra_cliente on public.turnos_reserva;
create trigger reserva_registra_cliente
  before insert on public.turnos_reserva
  for each row execute function public.reserva_registra_cliente();

-- ------------------------------------------------------------
-- 3. LOS QUE YA ESTABAN
--
--    Las reservas viejas también tienen gente adentro. Se les arma la ficha
--    y se las enlaza, agrupando por teléfono normalizado y quedándose con el
--    nombre de la reserva más reciente — que es el que el local reconoce.
--
--    Se hace en dos pasos y no con un INSERT ... SELECT y un UPDATE sueltos
--    para que el enlace use exactamente las fichas que se acaban de crear.
-- ------------------------------------------------------------
do $$
declare
  v_creados integer := 0;
  v_ligados integer := 0;
begin
  with contactos as (
    select
      r.empresa_id,
      regexp_replace(r.cliente_telefono, '\D', '', 'g') as norm,
      -- El nombre de la reserva más nueva de ese número.
      (array_agg(r.cliente_nombre order by r.created_at desc))[1] as nombre,
      (array_agg(r.cliente_telefono order by r.created_at desc))[1] as telefono
    from public.turnos_reserva r
    where r.cliente_id is null
      and char_length(regexp_replace(r.cliente_telefono, '\D', '', 'g')) >= 6
    group by 1, 2
  )
  insert into public.clientes (empresa_id, nombre, telefono)
  select c.empresa_id, left(c.nombre, 80), left(c.telefono, 40)
  from contactos c
  on conflict (empresa_id, telefono_norm) where telefono_norm <> '' do nothing;

  get diagnostics v_creados = row_count;

  update public.turnos_reserva r
  set cliente_id = c.id
  from public.clientes c
  where r.cliente_id is null
    and c.empresa_id = r.empresa_id
    and c.telefono_norm = regexp_replace(r.cliente_telefono, '\D', '', 'g')
    and c.telefono_norm <> '';

  get diagnostics v_ligados = row_count;

  raise notice 'Clientes creados desde reservas viejas: %. Reservas enlazadas: %.',
    v_creados, v_ligados;
end $$;

-- ------------------------------------------------------------
-- 4. LA SECCIÓN DE CLIENTES
--
--    Una lista que solo se mira no vale el trabajo de mantenerla. Lo que la
--    hace útil es lo de al lado: cuántas veces vino, cuándo fue la última y
--    cuánto dejó. Eso es lo que convierte «Juan Pérez» en «Juan, que viene
--    cada tres semanas y hace seis meses que no aparece».
--
--    `gastado` sale de los turnos ATENDIDOS, no de los reservados: un turno
--    al que no vino no es plata. Es la misma regla de siempre.
-- ------------------------------------------------------------
create or replace function public.lista_clientes(
  p_empresa uuid,
  p_texto   text default '',
  p_limite  integer default 200
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_res   jsonb;
  v_busca text;
  v_norm  text;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  v_busca := lower(trim(coalesce(p_texto, '')));
  v_norm  := regexp_replace(v_busca, '\D', '', 'g');

  select coalesce(jsonb_agg(to_jsonb(x) order by x.ultima_visita desc nulls last, x.nombre), '[]'::jsonb)
  into v_res
  from (
    select
      c.id, c.nombre, c.telefono, c.notas, c.created_at,
      coalesce(t.visitas, 0)::int    as visitas,
      t.ultima_visita,
      coalesce(t.gastado, 0)::numeric as gastado,
      coalesce(t.proximo, null)      as proximo_turno
    from public.clientes c
    left join lateral (
      select
        count(*) filter (where r.estado = 'atendida')::int as visitas,
        max(r.inicia) filter (where r.estado = 'atendida') as ultima_visita,
        coalesce(sum(a.monto_cobrado) filter (where r.estado = 'atendida'), 0) as gastado,
        min(r.inicia) filter (
          where r.estado in ('pendiente', 'confirmada') and r.inicia > now()
        ) as proximo
      from public.turnos_reserva r
      left join public.turnos_atribucion a on a.id = r.atribucion_id
      where r.cliente_id = c.id
    ) t on true
    where c.empresa_id = p_empresa
      and c.activo
      and (
        v_busca = ''
        or lower(c.nombre) like '%' || v_busca || '%'
        or (v_norm <> '' and c.telefono_norm like '%' || v_norm || '%')
      )
    limit least(greatest(coalesce(p_limite, 200), 1), 500)
  ) x;

  return v_res;
end $fn$;

revoke all on function public.lista_clientes(uuid, text, integer) from public, anon;
grant execute on function public.lista_clientes(uuid, text, integer) to authenticated;

-- ------------------------------------------------------------
-- 5. LA FICHA DE UNO
--
--    Sus turnos, del más nuevo al más viejo. Es lo que se abre al tocarlo en
--    la lista, y lo que contesta «¿este cliente ya vino?» sin tener que
--    acordarse.
-- ------------------------------------------------------------
create or replace function public.historial_cliente(
  p_cliente uuid,
  p_limite  integer default 50
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_empresa uuid;
  v_res     jsonb;
begin
  select empresa_id into v_empresa from public.clientes where id = p_cliente;
  if v_empresa is null then
    raise exception 'Ese cliente no existe.' using errcode = 'P0002';
  end if;
  if not public.es_miembro(v_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(to_jsonb(x) order by x.inicia desc), '[]'::jsonb) into v_res
  from (
    select
      r.id, r.inicia, r.estado,
      pr.nombre as servicio,
      p.nombre  as profesional,
      coalesce(a.monto_cobrado, 0)::numeric as monto
    from public.turnos_reserva r
    left join public.productos pr on pr.id = r.producto_id
    left join public.turnos_profesional p on p.id = r.profesional_id
    left join public.turnos_atribucion a on a.id = r.atribucion_id
    where r.cliente_id = p_cliente
    order by r.inicia desc
    limit least(greatest(coalesce(p_limite, 50), 1), 200)
  ) x;

  return v_res;
end $fn$;

revoke all on function public.historial_cliente(uuid, integer) from public, anon;
grant execute on function public.historial_cliente(uuid, integer) to authenticated;


-- ############################################################
-- ##  054_lo_que_te_deben.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 054 · Lo que te deben
--
-- EL ERROR QUE ESTABA A MEDIO HACER
--
-- La forma de cobro «Fiado» ya existía: se podía marcar una venta como
-- fiada. Pero no se guardaba QUIÉN debe, ni si alguna vez pagó, y —lo
-- grave— esa venta sumaba como ingreso del día igual que si te hubieran
-- pagado en efectivo. El método de pago solo se usaba para agrupar, nunca
-- para descontar.
--
-- Vendés 500.000 fiado y el panel te dice que ganaste 500.000. Esa plata no
-- está en tu bolsillo. Es exactamente lo que este sistema promete no hacer.
--
-- POR QUÉ NO VA ADENTRO DE `deudas`
--
-- `deudas` es lo que el negocio DEBE: tiene una columna `acreedor`, a quién
-- le debés. Meter las dos direcciones en la misma tabla obliga a que cada
-- consulta que ya existe lleve un filtro nuevo, y el día que alguien se
-- olvide de uno, tu deuda va a aparecer sumando como plata tuya. Ese error
-- no avisa: da un número lindo y falso.
--
-- CÓMO SE MODELA
--
-- No como «una deuda por cliente con su saldo», sino como un LIBRO: cada
-- línea es «se le fio tanto» o «me pagó tanto», y el saldo es la resta.
--
-- Un saldo guardado se desincroniza —basta una línea borrada, un pago
-- cargado dos veces, un UPDATE a mano— y cuando eso pasa nadie se entera
-- hasta que el cliente reclama. Sumando el libro, el saldo no puede estar
-- mal: es lo que hay escrito.
--
-- SIRVE PARA LOS DOS TIPOS DE CUENTA
--
-- Un almacén fía; a una persona también le deben. Y quien debe puede ser
-- una persona o un negocio —«hoy me llevó tanto el supermercado»—, que es
-- por lo que el que debe es un `cliente` y un cliente es solo un nombre con
-- un teléfono.
-- ============================================================

-- ------------------------------------------------------------
-- 1. EL LIBRO
--
--    `venta_id` enlaza la línea con la venta que la originó, cuando vino de
--    una. Es lo que permite que anular una venta fiada borre la deuda que
--    creó, en vez de dejarla viva reclamando plata por algo que no pasó.
--
--    Y es opcional, porque el otro caso es igual de real: «David me debe
--    500.000» dicho en un audio, sin ninguna venta detrás.
-- ------------------------------------------------------------
create table if not exists public.fiado (
  id         uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas (id) on delete cascade,
  cliente_id uuid not null,
  -- 'fio'   → le fiaste: te deben más.
  -- 'cobro' → te pagó: te deben menos.
  tipo       text not null check (tipo in ('fio', 'cobro')),
  monto      numeric(14,2) not null check (monto > 0),
  fecha      date not null,
  concepto   text not null default '' check (char_length(concepto) <= 200),
  -- La venta que lo originó, si vino de una.
  venta_id   uuid references public.movimientos (id) on delete cascade,
  -- El movimiento de ingreso que generó el cobro, para poder anularlo junto.
  cobro_id   uuid references public.movimientos (id) on delete set null,
  creado_por uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),

  -- El mismo candado estructural de siempre: una línea de fiado no puede
  -- apuntar al cliente de otro negocio.
  constraint fiado_cliente_misma_empresa
    foreign key (cliente_id, empresa_id)
    references public.clientes (id, empresa_id) on delete cascade,

  constraint fiado_fecha_razonable check (fecha >= date '2000-01-01')
);

comment on table public.fiado is
  'Libro de lo que le deben al negocio. Cada línea suma o resta; el saldo es la resta, nunca un número guardado.';

create index if not exists fiado_cliente_idx on public.fiado (cliente_id, fecha desc);
create index if not exists fiado_empresa_idx on public.fiado (empresa_id, fecha desc);
create index if not exists fiado_venta_idx   on public.fiado (venta_id) where venta_id is not null;

alter table public.fiado enable row level security;

-- Se lee como miembro; se escribe solo por función, porque hay que validar
-- el cliente, la fecha y el tope contra lo que realmente se debe.
drop policy if exists fiado_select on public.fiado;
create policy fiado_select on public.fiado
  for select using (public.es_miembro(empresa_id));

revoke all on public.fiado from anon, authenticated;
grant select on public.fiado to authenticated;

-- ------------------------------------------------------------
-- 2. CUÁNTO DEBE UNO
--
--    Una sola definición del saldo. Si esta cuenta estuviera repetida en la
--    pantalla, en el reporte y en el Excel, tarde o temprano una de las tres
--    diría otra cosa — y ninguna sabría cuál está mal.
-- ------------------------------------------------------------
create or replace function public.saldo_fiado(p_cliente uuid)
returns numeric language sql stable security definer set search_path = public as $fn$
  select coalesce(sum(
    case when f.tipo = 'fio' then f.monto else -f.monto end
  ), 0)::numeric
  from public.fiado f
  where f.cliente_id = p_cliente;
$fn$;

revoke all on function public.saldo_fiado(uuid) from public, anon;
grant execute on function public.saldo_fiado(uuid) to authenticated;

-- ------------------------------------------------------------
-- 3. ANOTAR QUE ALGUIEN TE DEBE
--
--    Cualquier miembro: el que fía es el que está en el mostrador.
-- ------------------------------------------------------------
create or replace function public.anotar_fiado(
  p_empresa  uuid,
  p_cliente  uuid,
  p_monto    numeric,
  p_concepto text default '',
  p_fecha    date default null
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare v_id uuid;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if coalesce(p_monto, 0) <= 0 then
    raise exception 'El monto tiene que ser mayor que cero.' using errcode = '22023';
  end if;

  if not exists (select 1 from public.clientes
                 where id = p_cliente and empresa_id = p_empresa) then
    raise exception 'Ese cliente no es de esta cuenta.' using errcode = 'P0002';
  end if;

  insert into public.fiado (empresa_id, cliente_id, tipo, monto, fecha, concepto, creado_por)
  values (p_empresa, p_cliente, 'fio', p_monto,
          coalesce(p_fecha, public.hoy_empresa(p_empresa)),
          left(coalesce(p_concepto, ''), 200), auth.uid())
  returning id into v_id;

  return v_id;
end $fn$;

revoke all on function public.anotar_fiado(uuid, uuid, numeric, text, date) from public, anon;
grant execute on function public.anotar_fiado(uuid, uuid, numeric, text, date) to authenticated;

-- ------------------------------------------------------------
-- 4. COBRAR
--
--    ACÁ ES DONDE LA PLATA ENTRA DE VERDAD, y por eso acá —y no en la venta
--    fiada— es donde se registra el ingreso.
--
--    El movimiento se crea primero: si falla, no queremos haber bajado el
--    saldo. Es la misma secuencia que `registrar_pago_deuda` (015), por la
--    misma razón.
--
--    No se puede cobrar más de lo que se debe. Un saldo negativo no
--    significa nada: si el cliente pagó de más, eso es otra cosa (un
--    adelanto) y no se resuelve fingiendo que debe menos que cero.
-- ------------------------------------------------------------
create or replace function public.cobrar_fiado(
  p_empresa uuid,
  p_cliente uuid,
  p_monto   numeric,
  p_metodo  text default 'efectivo',
  p_fecha   date default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_saldo   numeric;
  v_nombre  text;
  v_fecha   date;
  v_mov     uuid;
  v_id      uuid;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if coalesce(p_monto, 0) <= 0 then
    raise exception 'El monto tiene que ser mayor que cero.' using errcode = '22023';
  end if;

  select nombre into v_nombre from public.clientes
  where id = p_cliente and empresa_id = p_empresa;
  if v_nombre is null then
    raise exception 'Ese cliente no es de esta cuenta.' using errcode = 'P0002';
  end if;

  v_saldo := public.saldo_fiado(p_cliente);
  if v_saldo <= 0 then
    raise exception '% no te debe nada.', v_nombre using errcode = '22023';
  end if;
  if p_monto > v_saldo then
    raise exception '% te debe %, no podés cobrarle más que eso.', v_nombre, v_saldo
      using errcode = '22023';
  end if;

  if coalesce(p_metodo, '') not in ('efectivo', 'transferencia', 'tarjeta', 'otro') then
    raise exception 'Esa forma de cobro no es válida.' using errcode = '22023';
  end if;

  v_fecha := coalesce(p_fecha, public.hoy_empresa(p_empresa));

  -- Entra como «otro ingreso» y NO como venta: la venta ya se registró el
  -- día que se entregó la mercadería. Contarla otra vez acá duplicaría la
  -- facturación del negocio.
  insert into public.movimientos (
    empresa_id, tipo, fecha, descripcion, categoria,
    subtotal, descuento, monto, costo_total, metodo_pago, contraparte, creado_por
  ) values (
    p_empresa, 'ingreso', v_fecha,
    'Cobro de fiado · ' || v_nombre, 'Fiado',
    p_monto, 0, p_monto, 0, coalesce(p_metodo, 'efectivo'), left(v_nombre, 80), auth.uid()
  )
  returning id into v_mov;

  insert into public.fiado (
    empresa_id, cliente_id, tipo, monto, fecha, concepto, cobro_id, creado_por
  ) values (
    p_empresa, p_cliente, 'cobro', p_monto, v_fecha, 'Pago recibido', v_mov, auth.uid()
  )
  returning id into v_id;

  return jsonb_build_object(
    'id', v_id,
    'movimiento', v_mov,
    'saldo', public.saldo_fiado(p_cliente)
  );
end $fn$;

revoke all on function public.cobrar_fiado(uuid, uuid, numeric, text, date) from public, anon;
grant execute on function public.cobrar_fiado(uuid, uuid, numeric, text, date) to authenticated;

-- ------------------------------------------------------------
-- 5. LO QUE TE DEBEN, TODO JUNTO
--
--    El total y la lista de quiénes. Es la pantalla, y es también el número
--    que el panel necesita para poder decir la verdad.
--
--    `dias` es cuántos hace de la línea más vieja sin saldar. No es un
--    adorno: la diferencia entre «me deben 800.000» y «me deben 800.000
--    desde hace cuatro meses» es toda.
-- ------------------------------------------------------------
create or replace function public.resumen_fiado(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_res jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  with saldos as (
    select
      f.cliente_id,
      sum(case when f.tipo = 'fio' then f.monto else -f.monto end)::numeric as saldo,
      min(f.fecha) filter (where f.tipo = 'fio') as desde
    from public.fiado f
    where f.empresa_id = p_empresa
    group by f.cliente_id
  ),
  conNombre as (
    select
      s.cliente_id, c.nombre, c.telefono, s.saldo, s.desde,
      (public.hoy_empresa(p_empresa) - s.desde) as dias
    from saldos s
    join public.clientes c on c.id = s.cliente_id
    -- Quien ya pagó todo no aparece en «lo que te deben». Sigue en Clientes.
    where s.saldo > 0
  )
  select jsonb_build_object(
    'total',    coalesce((select sum(saldo) from conNombre), 0),
    'cuantos',  coalesce((select count(*) from conNombre), 0),
    'clientes', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.saldo desc)
      from conNombre x
    ), '[]'::jsonb)
  ) into v_res;

  return v_res;
end $fn$;

revoke all on function public.resumen_fiado(uuid) from public, anon;
grant execute on function public.resumen_fiado(uuid) to authenticated;

-- ------------------------------------------------------------
-- 6. EL MOVIMIENTO DE UN CLIENTE
-- ------------------------------------------------------------
create or replace function public.libro_fiado(p_cliente uuid, p_limite integer default 100)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_empresa uuid;
  v_res     jsonb;
begin
  select empresa_id into v_empresa from public.clientes where id = p_cliente;
  if v_empresa is null then
    raise exception 'Ese cliente no existe.' using errcode = 'P0002';
  end if;
  if not public.es_miembro(v_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(to_jsonb(x) order by x.fecha desc, x.created_at desc), '[]'::jsonb)
  into v_res
  from (
    select f.id, f.tipo, f.monto, f.fecha, f.concepto, f.venta_id, f.created_at
    from public.fiado f
    where f.cliente_id = p_cliente
    order by f.fecha desc, f.created_at desc
    limit least(greatest(coalesce(p_limite, 100), 1), 500)
  ) x;

  return v_res;
end $fn$;

revoke all on function public.libro_fiado(uuid, integer) from public, anon;
grant execute on function public.libro_fiado(uuid, integer) to authenticated;


-- ############################################################
-- ##  055_venta_fiada.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 055 · Una venta fiada deja una deuda
--
-- LA MITAD QUE FALTABA
--
-- La 054 armó el libro de lo que te deben. Esto lo conecta con la caja:
-- cuando una venta se cobra «Fiado», queda anotada como deuda de ese
-- cliente en lugar de desaparecer en una etiqueta.
--
-- Y con eso, «Fiado» deja de ser una palabra al lado de una venta y pasa a
-- ser plata que alguien tiene que ir a cobrar.
--
-- POR QUÉ AHORA HAY QUE DECIR A QUIÉN SE LE FÍA
--
-- Antes se podía marcar una venta como fiada sin decir de quién. Eso dejaba
-- una deuda que nadie puede cobrar y un ingreso que nunca se va a cerrar.
-- Ahora es obligatorio, y es un cambio de comportamiento: una venta fiada
-- sin cliente ahora es rechazada, con un mensaje que dice qué hacer.
--
-- LA FIRMA CAMBIA, ASÍ QUE LA VIEJA SE BORRA
--
-- Si quedaran las dos, PostgREST vería dos funciones con el mismo nombre y
-- no sabría cuál llamar. Es lo mismo que hicieron la 019 y la 048.
--
-- EL CUERPO NO SE TOCÓ A MANO
--
-- Esta función mueve stock y plata. El cuerpo se extrajo del archivo de la
-- 032 con un script y se le agregaron solo las partes marcadas, para que no
-- haya forma de que se cuele una diferencia silenciosa al transcribir.
-- ============================================================

-- ------------------------------------------------------------
-- 1. A QUIÉN SE LE VENDIÓ
--
--    Sirve para toda venta, no solo para las fiadas: es lo que permite ver
--    el historial de un cliente en un almacén, donde no hay turnos.
--
--    Clave compuesta contra `clientes (id, empresa_id)`: una venta no puede
--    apuntar al cliente de otro negocio ni con un UPDATE a mano.
-- ------------------------------------------------------------
alter table public.movimientos
  add column if not exists cliente_id uuid;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'movimiento_cliente_misma_empresa') then
    alter table public.movimientos
      add constraint movimiento_cliente_misma_empresa
      foreign key (cliente_id, empresa_id)
      references public.clientes (id, empresa_id) on delete set null;
  end if;
end $$;

create index if not exists movimientos_cliente_idx
  on public.movimientos (cliente_id) where cliente_id is not null;

-- ------------------------------------------------------------
-- 2. LA VENTA
-- ------------------------------------------------------------
create or replace function public.registrar_venta(
  p_empresa uuid,
  p_items jsonb,
  p_fecha date default null,
  p_descripcion text default '',
  p_metodo_pago text default 'efectivo',
  p_contraparte text default '',
  p_notas text default '',
  p_origen origen_captura default 'manual',
  p_descuento numeric default 0,
  -- A quién se le vende. Solo hace falta cuando la venta es fiada, pero se
  -- guarda siempre: sirve para el historial del cliente.
  p_cliente uuid default null
)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_mov       uuid;
  v_item      jsonb;
  v_prod      public.productos%rowtype;
  v_norm      jsonb := '[]'::jsonb;
  v_subtotal  numeric(14,2) := 0;
  v_costo     numeric(14,2) := 0;
  v_desc      numeric(14,2);
  v_cant      numeric(14,2);
  v_precio    numeric(14,2);
  v_costo_u   numeric(14,2);
  v_nombre    text;
  v_pid       uuid;
  v_fecha     date;
  v_permitir  boolean;
  v_stock     numeric(14,2);
  v_metodo    text;
  v_cliente   uuid;
begin
  ------------------------------------------------ autenticación y pertenencia
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  select permitir_stock_negativo into v_permitir from public.empresas where id = p_empresa;
  if not found then
    raise exception 'La empresa no existe.' using errcode = '42501';
  end if;

  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  ------------------------------------------------ validaciones generales
  if p_items is null or jsonb_typeof(p_items) <> 'array' then
    raise exception 'La venta necesita una lista de productos.' using errcode = '22023';
  end if;

  if jsonb_array_length(p_items) = 0 then
    raise exception 'La venta necesita al menos un producto.' using errcode = '22023';
  end if;

  if jsonb_array_length(p_items) > 200 then
    raise exception 'Una venta no puede tener más de 200 líneas.' using errcode = '22023';
  end if;

  v_fecha := coalesce(p_fecha, public.hoy_empresa(p_empresa));
  if v_fecha < date '2000-01-01' or v_fecha > public.hoy_empresa(p_empresa) + 1 then
    raise exception 'La fecha de la venta no es válida.' using errcode = '22007';
  end if;

  v_metodo := lower(coalesce(nullif(trim(p_metodo_pago), ''), 'efectivo'));
  if v_metodo not in ('efectivo', 'transferencia', 'tarjeta', 'credito', 'otro') then
    raise exception 'La forma de cobro no es válida.' using errcode = '22023';
  end if;

  ------------------------------------------------ primera pasada: validar y normalizar
  for v_item in select * from jsonb_array_elements(p_items) loop
    if jsonb_typeof(v_item) <> 'object' then
      raise exception 'Cada línea de la venta tiene que ser un objeto.' using errcode = '22023';
    end if;

    begin
      v_cant := (v_item ->> 'cantidad')::numeric;
    exception when others then
      raise exception 'La cantidad tiene que ser un número.' using errcode = '22023';
    end;

    if v_cant is null or v_cant <= 0 then
      raise exception 'La cantidad tiene que ser mayor a cero.' using errcode = '22023';
    end if;
    if v_cant > 1000000 then
      raise exception 'La cantidad es demasiado grande.' using errcode = '22023';
    end if;

    v_pid := null;
    if nullif(trim(coalesce(v_item ->> 'producto_id', '')), '') is not null then
      begin
        v_pid := (v_item ->> 'producto_id')::uuid;
      exception when others then
        raise exception 'El identificador del producto no es válido.' using errcode = '22023';
      end;
    end if;

    if v_pid is not null then
      -- El producto tiene que existir Y ser de esta empresa.
      select * into v_prod from public.productos where id = v_pid and empresa_id = p_empresa;
      if not found then
        raise exception 'Ese producto no pertenece a esta empresa.' using errcode = '42501';
      end if;

      v_nombre  := v_prod.nombre;
      -- El precio SÍ puede ser distinto al del catálogo (rebaja puntual, acuerdo con el cliente).
      v_precio  := coalesce(nullif(v_item ->> 'precio_unitario', '')::numeric, v_prod.precio);
      -- El costo NO: siempre el del catálogo. Lo que mande el cliente se descarta.
      v_costo_u := v_prod.costo;
    else
      v_nombre := nullif(trim(coalesce(v_item ->> 'nombre', '')), '');
      if v_nombre is null then
        raise exception 'Cada producto suelto necesita un nombre.' using errcode = '22023';
      end if;
      v_nombre  := left(v_nombre, 120);
      v_precio  := coalesce(nullif(v_item ->> 'precio_unitario', '')::numeric, 0);
      v_costo_u := coalesce(nullif(v_item ->> 'costo_unitario', '')::numeric, 0);
    end if;

    if v_precio is null or v_precio < 0 then
      raise exception 'El precio no puede ser negativo.' using errcode = '22023';
    end if;
    if v_costo_u is null or v_costo_u < 0 then
      raise exception 'El costo no puede ser negativo.' using errcode = '22023';
    end if;

    v_subtotal := v_subtotal + (v_cant * v_precio);
    v_costo    := v_costo + (v_cant * v_costo_u);

    v_norm := v_norm || jsonb_build_object(
      'producto_id', v_pid,
      'nombre', v_nombre,
      'cantidad', v_cant,
      'precio_unitario', v_precio,
      'costo_unitario', v_costo_u,
      'controla_stock', coalesce(v_pid is not null and v_prod.controla_stock, false)
    );
  end loop;

  ------------------------------------------------ descuento
  v_desc := coalesce(p_descuento, 0);
  if v_desc < 0 then
    raise exception 'El descuento no puede ser negativo.' using errcode = '22023';
  end if;
  if v_desc > v_subtotal then
    raise exception 'El descuento no puede ser mayor que el subtotal de la venta.' using errcode = '22023';
  end if;

  ------------------------------------------------ el cliente
  -- Se valida ANTES de tocar el stock: si el cliente no es de esta cuenta,
  -- que la venta entera no llegue a existir.
  v_cliente := p_cliente;
  if v_cliente is not null
     and not exists (select 1 from public.clientes
                     where id = v_cliente and empresa_id = p_empresa) then
    raise exception 'Ese cliente no es de esta cuenta.' using errcode = 'P0002';
  end if;

  -- Fiar sin saber a quién es anotar en la pared. Se puede vender fiado sin
  -- cliente en otros sistemas; acá no, porque el resultado sería una deuda
  -- que nadie puede cobrar y un número que infla los ingresos para siempre.
  if v_metodo = 'credito' and v_cliente is null then
    raise exception 'Para vender fiado hay que decir a quién: elegí o creá el cliente.'
      using errcode = '22023';
  end if;

  ------------------------------------------------ cabecera
  insert into public.movimientos (
    empresa_id, tipo, estado, fecha, descripcion, categoria,
    subtotal, descuento, monto, costo_total,
    metodo_pago, contraparte, notas, origen, creado_por, cliente_id
  )
  values (
    p_empresa, 'venta', 'activo', v_fecha,
    left(coalesce(trim(p_descripcion), ''), 200), 'Ventas',
    v_subtotal, v_desc, v_subtotal - v_desc, v_costo,
    v_metodo, left(coalesce(trim(p_contraparte), ''), 80), left(coalesce(p_notas, ''), 500),
    coalesce(p_origen, 'manual'), auth.uid(), v_cliente
  )
  returning id into v_mov;

  ------------------------------------------------ items y stock
  for v_item in select * from jsonb_elements_ordenados(v_norm) loop
    v_cant := (v_item ->> 'cantidad')::numeric;
    v_pid  := nullif(v_item ->> 'producto_id', '')::uuid;

    if v_pid is not null and (v_item ->> 'controla_stock')::boolean then
      -- Aritmética relativa: dos ventas simultáneas no se pisan.
      update public.productos
        set stock = stock - v_cant
        where id = v_pid
        returning stock into v_stock;

      if not v_permitir and v_stock < 0 then
        raise exception 'No hay stock suficiente de %.', v_item ->> 'nombre' using errcode = '23514';
      end if;
    end if;

    insert into public.movimiento_items (
      movimiento_id, empresa_id, producto_id, nombre, cantidad,
      precio_unitario, costo_unitario, afecto_stock
    )
    values (
      v_mov, p_empresa, v_pid, v_item ->> 'nombre', v_cant,
      (v_item ->> 'precio_unitario')::numeric,
      (v_item ->> 'costo_unitario')::numeric,
      coalesce(v_pid is not null and (v_item ->> 'controla_stock')::boolean, false)
    );
  end loop;

  ------------------------------------------------ descripción automática
  update public.movimientos
  set descripcion = (
    select string_agg(nombre || ' x' || trim(to_char(cantidad, 'FM999999990.##')), ', ')
    from public.movimiento_items where movimiento_id = v_mov
  )
  where id = v_mov and coalesce(trim(descripcion), '') = '';

  ------------------------------------------------ si fue fiada, se anota
  --
  -- Acá está el arreglo. Hasta ahora «Fiado» era una etiqueta: la venta
  -- sumaba como ingreso igual que si te hubieran pagado en efectivo, y no
  -- quedaba escrito quién debía.
  --
  -- Va al final, después del stock y de los items: si algo de eso falla, la
  -- transacción se va entera y no queda una deuda por una venta que no pasó.
  if v_metodo = 'credito' then
    insert into public.fiado (
      empresa_id, cliente_id, tipo, monto, fecha, concepto, venta_id, creado_por
    )
    select p_empresa, v_cliente, 'fio', v_subtotal - v_desc, v_fecha,
           left(coalesce((
             select string_agg(nombre || ' x' || trim(to_char(cantidad, 'FM999999990.##')), ', ')
             from public.movimiento_items where movimiento_id = v_mov
           ), 'Venta fiada'), 200),
           v_mov, auth.uid();
  end if;

  return v_mov;
end $$;

-- La firma vieja de 9 argumentos queda muerta.
drop function if exists public.registrar_venta(
  uuid, jsonb, date, text, text, text, text, origen_captura, numeric);

revoke all on function public.registrar_venta(
  uuid, jsonb, date, text, text, text, text, origen_captura, numeric, uuid) from public, anon;
grant execute on function public.registrar_venta(
  uuid, jsonb, date, text, text, text, text, origen_captura, numeric, uuid) to authenticated;

-- ------------------------------------------------------------
-- 3. ANULAR UNA VENTA FIADA BORRA LA DEUDA
--
--    Anular no borra el movimiento: lo marca. Así que la línea del libro no
--    se va sola, y quedaría reclamando plata por una venta que se deshizo.
--
--    Se hace con un trigger y no dentro de `anular_movimiento` por lo mismo
--    de siempre: es una regla sobre el dato, y tiene que valer venga por
--    donde venga —incluido un UPDATE desde el editor SQL.
--
--    Si el cliente ya pagó algo, NO se borra en silencio: eso dejaría el
--    saldo en negativo, que no significa nada. Se frena y se explica.
-- ------------------------------------------------------------
create or replace function public.anular_borra_el_fiado()
returns trigger language plpgsql security definer set search_path = public as $fn$
declare
  v_cliente uuid;
  v_monto   numeric;
  v_saldo   numeric;
begin
  if new.estado <> 'anulado' or old.estado = 'anulado' then
    return new;
  end if;

  select f.cliente_id, f.monto into v_cliente, v_monto
  from public.fiado f
  where f.venta_id = new.id and f.tipo = 'fio';

  if v_cliente is null then return new; end if;

  v_saldo := public.saldo_fiado(v_cliente);
  if v_saldo - v_monto < 0 then
    raise exception
      'Esa venta fiada ya fue cobrada, entera o en parte. Anulá primero el cobro y después la venta.'
      using errcode = '22023';
  end if;

  delete from public.fiado where venta_id = new.id and tipo = 'fio';
  return new;
end $fn$;

revoke all on function public.anular_borra_el_fiado() from public, anon, authenticated;

drop trigger if exists anular_borra_el_fiado on public.movimientos;
create trigger anular_borra_el_fiado
  after update on public.movimientos
  for each row execute function public.anular_borra_el_fiado();


-- ############################################################
-- ##  056_cobrar_no_es_ganar_dos_veces.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 056 · Cobrar un fiado no es ganar dos veces
--
-- EL ERROR, QUE ESTABA EN LA 054
--
-- `cobrar_fiado` registraba cada cobro como «otro ingreso». La intención
-- era no duplicar la FACTURACIÓN —la venta ya se había registrado el día que
-- salió la mercadería— y eso se cumplía. Pero la ganancia se calcula como
--
--     ventas − costo + otros ingresos − gastos
--
-- así que una venta fiada de 500.000 contaba 500.000 el día de la venta y
-- otros 500.000 el día del cobro. La ganancia del negocio quedaba inflada
-- exactamente en todo lo que se cobraba de fiado.
--
-- Con lo anotado a mano era igual de falso: si le prestaste 500.000 a David
-- y te los devuelve, no ganaste nada. Con la 054, ganabas 500.000.
--
-- Apareció escribiendo la pantalla de Fiado, antes de que existiera ningún
-- botón «Cobrar». La prueba de la 054 afirmaba que el cobro entraba como
-- otro ingreso —describía el error como si fuera la regla— y por eso pasaba.
--
-- LO QUE PASA AHORA
--
-- Cobrar solo baja lo que te deben. No crea ningún movimiento: la venta ya
-- está contada, y un préstamo que vuelve no es ganancia. El panel va a decir
-- cuánto de lo vendido todavía no se cobró, que es la otra mitad de la verdad.
--
-- LO QUE ESTO NO RESUELVE, DICHO DE FRENTE
--
-- La plata que se cobra en efectivo entra al cajón y no aparece entre los
-- movimientos del día, así que el cierre de caja no la ve. Es información que
-- falta, no un número falso, y se arregla mostrando los cobros de fiado en el
-- cierre. Duplicar la ganancia era peor.
-- ============================================================

-- ------------------------------------------------------------
-- 1. CÓMO SE COBRÓ
--
--    Sin movimiento, el libro es el único lugar donde queda. Y va a hacer
--    falta el día que el cierre de caja muestre los cobros en efectivo.
-- ------------------------------------------------------------
alter table public.fiado
  add column if not exists metodo text;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'fiado_metodo_valido') then
    alter table public.fiado add constraint fiado_metodo_valido
      check (metodo is null or metodo in ('efectivo', 'transferencia', 'tarjeta', 'otro'));
  end if;
end $$;

-- ------------------------------------------------------------
-- 2. COBRAR, SIN INGRESO
--
--    Misma firma que en la 054, así que se reemplaza sin tocar a quien ya la
--    llama. Lo único que cambia es que no inserta nada en `movimientos`.
--
--    Se agrega un candado sobre el cliente: dos cobros al mismo tiempo podían
--    pasar los dos el control del saldo y dejarlo por debajo de cero.
-- ------------------------------------------------------------
create or replace function public.cobrar_fiado(
  p_empresa uuid,
  p_cliente uuid,
  p_monto   numeric,
  p_metodo  text default 'efectivo',
  p_fecha   date default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_saldo  numeric;
  v_nombre text;
  v_id     uuid;
  v_debe   text;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if coalesce(p_monto, 0) <= 0 then
    raise exception 'El monto tiene que ser mayor que cero.' using errcode = '22023';
  end if;

  select nombre into v_nombre from public.clientes
  where id = p_cliente and empresa_id = p_empresa
  for update;
  if v_nombre is null then
    raise exception 'Ese cliente no es de esta cuenta.' using errcode = 'P0002';
  end if;

  if coalesce(p_metodo, '') not in ('efectivo', 'transferencia', 'tarjeta', 'otro') then
    raise exception 'Esa forma de cobro no es válida.' using errcode = '22023';
  end if;

  v_saldo := public.saldo_fiado(p_cliente);
  if v_saldo <= 0 then
    raise exception '% no te debe nada.', v_nombre using errcode = '22023';
  end if;

  if p_monto > v_saldo then
    -- «600.000» y no «600000.00»: esto lo lee una persona.
    v_debe := case when v_saldo = trunc(v_saldo)
                   then replace(to_char(v_saldo, 'FM999,999,999,990'), ',', '.')
                   else v_saldo::text end;
    raise exception '% te debe %, no podés cobrarle más que eso.', v_nombre, v_debe
      using errcode = '22023';
  end if;

  insert into public.fiado (
    empresa_id, cliente_id, tipo, monto, fecha, concepto, metodo, creado_por
  ) values (
    p_empresa, p_cliente, 'cobro', p_monto,
    coalesce(p_fecha, public.hoy_empresa(p_empresa)),
    'Pago recibido', p_metodo, auth.uid()
  )
  returning id into v_id;

  return jsonb_build_object('id', v_id, 'saldo', public.saldo_fiado(p_cliente));
end $fn$;

revoke all on function public.cobrar_fiado(uuid, uuid, numeric, text, date) from public, anon;
grant execute on function public.cobrar_fiado(uuid, uuid, numeric, text, date) to authenticated;

-- ------------------------------------------------------------
-- 3. BORRAR LO ANOTADO POR ERROR
--
--    Un fiado cargado dos veces, un pago con el monto equivocado: sin esto,
--    la única salida era anotar una línea al revés y ensuciar el libro.
--
--    Lo puede borrar quien lo anotó o un administrador. Lo que vino de una
--    venta NO se borra acá: se deshace anulando la venta, que es la que
--    además devuelve el stock.
--
--    Y borrar algo fiado no puede dejar el saldo por debajo de cero: si ya te
--    pagó parte, primero va el cobro.
-- ------------------------------------------------------------
create or replace function public.borrar_linea_fiado(p_linea uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v public.fiado;
begin
  select * into v from public.fiado where id = p_linea;
  if v.id is null then
    raise exception 'Esa línea ya no existe.' using errcode = 'P0002';
  end if;

  if not public.es_miembro(v.empresa_id) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if not (public.es_admin(v.empresa_id) or v.creado_por = auth.uid()) then
    raise exception 'Solo quien la anotó o un administrador puede borrarla.' using errcode = '42501';
  end if;

  if v.venta_id is not null then
    raise exception
      'Esa deuda viene de una venta. Para borrarla, anulá la venta desde el historial: así también vuelve el stock.'
      using errcode = '22023';
  end if;

  -- El mismo candado que al cobrar: el control del saldo no puede correr
  -- en paralelo con un cobro.
  perform 1 from public.clientes where id = v.cliente_id for update;

  if v.tipo = 'fio' and public.saldo_fiado(v.cliente_id) - v.monto < 0 then
    raise exception
      'Si borrás eso quedaría debiendo menos que cero, porque ya te pagó parte. Borrá primero el pago.'
      using errcode = '22023';
  end if;

  delete from public.fiado where id = p_linea;

  return jsonb_build_object('saldo', public.saldo_fiado(v.cliente_id));
end $fn$;

revoke all on function public.borrar_linea_fiado(uuid) from public, anon;
grant execute on function public.borrar_linea_fiado(uuid) to authenticated;

-- ------------------------------------------------------------
-- 4. EL MENSAJE AL ANULAR UNA VENTA YA COBRADA
--
--    Decía «anulá primero el cobro», y no había forma de hacerlo. Ahora la
--    hay, así que el mensaje dice dónde.
-- ------------------------------------------------------------
create or replace function public.anular_borra_el_fiado()
returns trigger language plpgsql security definer set search_path = public as $fn$
declare
  v_cliente uuid;
  v_monto   numeric;
begin
  if new.estado <> 'anulado' or old.estado = 'anulado' then
    return new;
  end if;

  select f.cliente_id, f.monto into v_cliente, v_monto
  from public.fiado f
  where f.venta_id = new.id and f.tipo = 'fio';

  if v_cliente is null then return new; end if;

  if public.saldo_fiado(v_cliente) - v_monto < 0 then
    raise exception
      'Esa venta fiada ya fue cobrada, entera o en parte. Borrá primero el pago desde Fiado y después anulá la venta.'
      using errcode = '22023';
  end if;

  delete from public.fiado where venta_id = new.id and tipo = 'fio';
  return new;
end $fn$;

revoke all on function public.anular_borra_el_fiado() from public, anon, authenticated;

-- ------------------------------------------------------------
-- 5. LOS COBROS QUE YA SE HABÍAN CONTADO COMO INGRESO
--
--    Si alguno llegó a existir, su «otro ingreso» sigue inflando la ganancia.
--    No se tocan solos: son movimientos de un negocio real, y anularlos es
--    una decisión que se toma mirándolos. Se avisa cuántos hay.
-- ------------------------------------------------------------
do $$
declare v_cuantos integer;
begin
  select count(*) into v_cuantos
  from public.fiado f
  join public.movimientos m on m.id = f.cobro_id
  where f.tipo = 'cobro' and m.estado = 'activo';

  if v_cuantos > 0 then
    raise notice
      'Hay % cobros de fiado anteriores que siguen contando como ingreso. Revisalos en el historial (categoría «Fiado») y anulalos.',
      v_cuantos;
  end if;
end $$;


-- ############################################################
-- ##  057_fiado_en_el_cierre_y_cliente_en_la_agenda.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 057 · El fiado en el cierre, y el cliente en la agenda
--
-- 1. EL CIERRE DEL DÍA NO SABÍA DEL FIADO
--
-- «Entró» es ventas más otros ingresos. Una venta fiada está en ventas, así
-- que el cierre la mostraba como plata que entró ese día, cuando al cajón no
-- entró nada. Y lo que te pagan de fiados viejos (desde la 056, un cobro ya
-- no es un ingreso) no aparecía en ningún lado: un día en que solo cobraste
-- fiados salía «sin actividad».
--
-- No se cambia lo que significa «Entró»: rompería las comparaciones con la
-- semana pasada, que se calculan igual. Se agregan dos números, y la pantalla
-- los muestra solo cuando no son cero:
--
--   fiado_vendido → de lo vendido hoy, cuánto se fio: se vendió, no entró.
--   fiado_cobrado → cuánto se cobró hoy de fiados: entró, sin venta de hoy.
--
-- 2. RESERVAR, CON EL CLIENTE ELEGIDO
--
-- Al agendar desde el local ahora se elige al cliente de la lista. La 053 ya
-- ata cada reserva a su cliente por el teléfono; lo que faltaba es el cliente
-- elegido que no tiene teléfono, que quedaba suelto y se perdía su historial.
-- El trigger de la 053 respeta un cliente que ya viene puesto, así que alcanza
-- con que `reservar` lo reciba.
--
-- La firma cambia, así que la vieja se borra: con las dos, PostgREST no
-- sabría cuál llamar. Es lo mismo que hicieron la 019, la 048 y la 055.
--
-- LOS CUERPOS NO SE TOCARON A MANO
--
-- Se extrajeron de la 008 y la 037 con un script y se les agregaron solo las
-- partes marcadas.
-- ============================================================

-- ------------------------------------------------------------
-- 1. EL CIERRE DEL DÍA
--
--    Misma firma que en la 008, así que se reemplaza sin tocar a quien ya la
--    llama.
-- ------------------------------------------------------------
create or replace function public.cierre_del_dia(p_empresa uuid, p_fecha date default null)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_fecha    date;
  v_previo   date;
  v_hoy_r    jsonb;
  v_prev_r   jsonb;
  v_sem_r    jsonb;
  v_top      jsonb;
  v_res      jsonb;
  v_admin    boolean;
  v_fiado_vendido numeric;
  v_fiado_cobrado numeric;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  v_fecha  := coalesce(p_fecha, public.hoy_empresa(p_empresa));
  v_previo := v_fecha - 7;
  v_admin  := public.es_admin(p_empresa);

  v_hoy_r  := public.resumen_financiero(p_empresa, v_fecha, v_fecha);
  v_prev_r := public.resumen_financiero(p_empresa, v_previo, v_previo);
  -- Los siete días ANTERIORES, sin incluir el que se está cerrando: si lo
  -- incluyéramos, el día se estaría comparando en parte contra sí mismo.
  v_sem_r  := public.resumen_financiero(p_empresa, v_fecha - 7, v_fecha - 1);

  -- Lo que la venta del día no dice. Una venta fiada está en «ventas» —se
  -- vendió— pero no entró al cajón; y lo que se cobra de fiados viejos
  -- entró al cajón pero no está en ninguna venta de hoy (056).
  select coalesce(sum(m.monto), 0) into v_fiado_vendido
  from public.movimientos m
  where m.empresa_id = p_empresa and m.fecha = v_fecha
    and m.tipo = 'venta' and m.estado = 'activo' and m.metodo_pago = 'credito';

  select coalesce(sum(f.monto), 0) into v_fiado_cobrado
  from public.fiado f
  where f.empresa_id = p_empresa and f.fecha = v_fecha and f.tipo = 'cobro';

  select jsonb_build_object('nombre', r->>'nombre', 'unidades', r->'unidades', 'ingresos', r->'ingresos')
  into v_top
  from jsonb_array_elements(
    coalesce(public.ranking_productos(p_empresa, v_fecha, v_fecha, 1), '[]'::jsonb)
  ) as r
  limit 1;

  select jsonb_build_object(
    'fecha',              v_fecha,
    'es_hoy',             v_fecha = public.hoy_empresa(p_empresa),
    'hubo_actividad',     coalesce((v_hoy_r->>'cantidad_ventas')::numeric, 0) > 0
                          or coalesce((v_hoy_r->>'gastos')::numeric, 0) > 0
                          or coalesce((v_hoy_r->>'otros_ingresos')::numeric, 0) > 0
                          -- Un día en que solo se cobraron fiados también tuvo
                          -- plata que entró: no es un día «sin actividad».
                          or v_fiado_cobrado > 0,
    'resumen',            v_hoy_r,
    'misma_dia_semana_pasada', v_prev_r,
    -- Promedio diario de la semana previa, para decir "hoy vendiste más que
    -- un día normal tuyo" sin que un lunes flojo arruine la comparación.
    'promedio_semana',    jsonb_build_object(
                            'ventas',  round(coalesce((v_sem_r->>'ventas')::numeric, 0) / 7, 2),
                            'gastos',  round(coalesce((v_sem_r->>'gastos')::numeric, 0) / 7, 2),
                            'ganancia_neta', case when v_admin
                              then round(coalesce((v_sem_r->>'ganancia_neta')::numeric, 0) / 7, 2)
                              else null end
                          ),
    'producto_estrella',  v_top,
    'fiado_vendido',      v_fiado_vendido,
    'fiado_cobrado',      v_fiado_cobrado,
    'racha',              public.racha_empresa(p_empresa),
    'ya_cerrado',         exists (
                            select 1 from public.cierres c
                            where c.empresa_id = p_empresa
                              and c.user_id = auth.uid()
                              and c.fecha = v_fecha
                          )
  ) into v_res;

  return v_res;
end $fn$;

-- ------------------------------------------------------------
-- 2. RESERVAR
-- ------------------------------------------------------------
create or replace function public.reservar(
  p_empresa     uuid,
  p_profesional uuid,
  p_producto    uuid,
  p_inicia      timestamptz,
  p_nombre      text,
  p_telefono    text default '',
  p_origen      text default 'local',
  -- El cliente elegido de la lista (057). Si viene, la reserva queda atada a
  -- él aunque no tenga teléfono; si no, el trigger de la 053 lo busca por el
  -- teléfono, como siempre.
  p_cliente     uuid default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_zona   text;
  v_fecha  date;
  v_libre  boolean;
  v_fin    timestamptz;
  v_id     uuid;
  v_token  uuid;
  v_cliente uuid;
begin
  if char_length(trim(coalesce(p_nombre, ''))) = 0 then
    raise exception 'Falta el nombre de quien reserva.' using errcode = '22023';
  end if;

  if p_inicia is null then
    raise exception 'Falta el horario.' using errcode = '22023';
  end if;

  -- Esta puerta es la del LOCAL: la usa quien trabaja ahí para anotar a
  -- alguien que llamó por teléfono. La puerta pública —la del link que el
  -- dueño comparte— es otra función, con sus propios límites, y por eso acá
  -- se exige pertenecer. Sin esta línea, cualquiera con una cuenta de Orden
  -- podía llenarle la agenda a un negocio ajeno.
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  -- El candado. Todo lo que sigue está serializado por profesional.
  perform 1 from public.turnos_profesional
  where id = p_profesional and empresa_id = p_empresa and activo
  for update;

  if not found then
    raise exception 'Esa persona no está en el equipo de esta cuenta.' using errcode = 'P0002';
  end if;

  select coalesce(e.zona_horaria, 'America/Asuncion') into v_zona
  from public.empresas e where e.id = p_empresa;

  v_fecha := (p_inicia at time zone v_zona)::date;

  -- Que el hueco EXISTA, no solo que esté libre. Sin esto se podría reservar
  -- a las tres de la mañana mandando el horario a mano.
  select exists (
    select 1 from public.huecos_del_dia(p_profesional, v_fecha, p_producto) h
    where h.inicia = p_inicia
  ) into v_libre;

  if not v_libre then
    raise exception 'Ese horario ya no está disponible.' using errcode = '23505';
  end if;

  select h.termina into v_fin
  from public.huecos_del_dia(p_profesional, v_fecha, p_producto) h
  where h.inicia = p_inicia;

  -- Un cliente de otro negocio no se puede colgar de un turno de este. La
  -- clave compuesta de la 053 ya lo impediría, pero con un error que nadie
  -- entiende; esto lo dice en castellano.
  v_cliente := p_cliente;
  if v_cliente is not null
     and not exists (select 1 from public.clientes
                     where id = v_cliente and empresa_id = p_empresa) then
    raise exception 'Ese cliente no es de esta cuenta.' using errcode = 'P0002';
  end if;

  insert into public.turnos_reserva (
    empresa_id, profesional_id, producto_id, inicia, termina,
    cliente_nombre, cliente_telefono, origen, creada_por, cliente_id
  )
  values (
    p_empresa, p_profesional, p_producto, p_inicia, v_fin,
    left(trim(p_nombre), 80), left(coalesce(trim(p_telefono), ''), 40),
    case when p_origen = 'publico' then 'publico' else 'local' end,
    auth.uid(), v_cliente
  )
  returning id, token into v_id, v_token;

  return jsonb_build_object('reserva', v_id, 'token', v_token, 'inicia', p_inicia, 'termina', v_fin);
end $fn$;

drop function if exists public.reservar(uuid, uuid, uuid, timestamptz, text, text, text);

revoke all on function public.reservar(uuid, uuid, uuid, timestamptz, text, text, text, uuid)
  from public, anon;
grant execute on function public.reservar(uuid, uuid, uuid, timestamptz, text, text, text, uuid)
  to authenticated;


-- ############################################################
-- ##  058_eliminar_clientes_y_productos.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 058 · Eliminar un cliente, y eliminar del catálogo
--
-- Hasta acá no había forma de sacar a nadie de la lista de clientes, y del
-- catálogo solo se podía pausar. Las dos cosas se piden igual —«eliminar»—
-- pero ninguna puede ser un DELETE a secas, porque cada ficha tiene cosas
-- colgadas.
--
-- 1. UN CLIENTE
--
--    El libro de fiado cuelga del cliente con borrado en cascada (054):
--    borrar la ficha de alguien que te debe borraría también su deuda, sin
--    avisar a nadie. Por eso:
--
--      · Si te debe, no se elimina. Primero se cobra o se borra la deuda.
--      · Si no tiene nada atado —la ficha repetida, el nombre mal escrito—
--        se borra de verdad.
--      · Si tiene historia —ventas, turnos, un fiado ya pagado— se archiva:
--        deja de aparecer en la lista y al elegir cliente, y lo que ya pasó
--        sigue diciendo a quién. Si vuelve a reservar o se lo carga con el
--        mismo teléfono, reaparece con su historial (la 052 ya lo hacía).
--
--    Y un arreglo que esto vuelve necesario: al ponerle a un cliente el
--    teléfono de una ficha eliminada, el índice único lo frenaba con «ya
--    existe algo con ese nombre». Ahora el número eliminado queda libre, y
--    si es de una ficha activa se dice de quién es.
--
-- 2. ALGO DEL CATÁLOGO
--
--    Lo que ya se vendió o tiene turnos no se borra: se pausa, que es lo que
--    la pantalla ofreció siempre. Deja de aparecer para vender sin soltar las
--    ventas ni los turnos que ya pasaron. Lo que nunca se usó —lo cargado
--    por error— se borra de verdad.
--
-- LAS DOS COSAS SON DEL DUEÑO O DE UN ADMINISTRADOR
--
--    Un vendedor puede cargar clientes (052) pero no sacarlos: sacarlos
--    esconde historia, y eso lo decide quien administra.
--
-- El cuerpo de guardar_cliente se extrajo de la 052 con un script y se le
-- agregó solo la parte marcada con (058).
-- ============================================================

-- ------------------------------------------------------------
-- 1. GUARDAR UN CLIENTE
--
--    Misma firma que en la 052: se reemplaza sin tocar a quien ya la llama.
-- ------------------------------------------------------------
create or replace function public.guardar_cliente(
  p_empresa  uuid,
  p_nombre   text,
  p_telefono text default '',
  p_notas    text default '',
  p_id       uuid default null
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_id     uuid;
  v_nombre text;
  v_tel    text;
  v_norm   text;
  v_otro   public.clientes;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  v_nombre := trim(coalesce(p_nombre, ''));
  if char_length(v_nombre) = 0 then
    raise exception 'Ponele un nombre, para saber de quién estamos hablando.' using errcode = '22023';
  end if;
  v_nombre := left(v_nombre, 80);

  v_tel  := left(trim(coalesce(p_telefono, '')), 40);
  v_norm := regexp_replace(v_tel, '\D', '', 'g');

  -- Un teléfono de dos dígitos no es un teléfono: es un dedazo. Se guarda
  -- vacío antes que guardar algo que después va a hacer chocar a dos
  -- personas distintas en el mismo índice.
  if v_norm <> '' and char_length(v_norm) < 6 then
    v_tel := '';
    v_norm := '';
  end if;

  if p_id is not null then
    -- (058) El número nuevo puede ser de otra ficha. Si esa ficha se
    -- eliminó, el número quedó libre: se le saca a la vieja, que conserva
    -- su historial por id. Si está activa, se dice de quién es, en vez del
    -- «ya existe algo con ese nombre» del índice único, que encima hablaba
    -- del nombre cuando el problema era el teléfono.
    if v_norm <> '' then
      select * into v_otro
      from public.clientes c
      where c.empresa_id = p_empresa and c.telefono_norm = v_norm and c.id <> p_id;

      if v_otro.id is not null then
        if v_otro.activo then
          raise exception 'Ese teléfono ya es de «%». Si son la misma persona, eliminá la ficha que sobra.',
            v_otro.nombre using errcode = '22023';
        end if;
        update public.clientes set telefono = '', updated_at = now() where id = v_otro.id;
      end if;
    end if;

    update public.clientes
    set nombre = v_nombre,
        telefono = v_tel,
        notas = left(coalesce(p_notas, ''), 1000),
        updated_at = now()
    where id = p_id and empresa_id = p_empresa
    returning id into v_id;

    if v_id is null then
      raise exception 'Ese cliente no es de esta cuenta.' using errcode = 'P0002';
    end if;
    return v_id;
  end if;

  -- Sin id: si el teléfono ya está, es la misma persona.
  if v_norm <> '' then
    select c.id into v_id
    from public.clientes c
    where c.empresa_id = p_empresa and c.telefono_norm = v_norm;

    if v_id is not null then
      update public.clientes
      set nombre = v_nombre,
          notas = case when trim(coalesce(p_notas, '')) = '' then notas
                       else left(p_notas, 1000) end,
          activo = true,
          updated_at = now()
      where id = v_id;
      return v_id;
    end if;
  end if;

  insert into public.clientes (empresa_id, nombre, telefono, notas, creado_por)
  values (p_empresa, v_nombre, v_tel, left(coalesce(p_notas, ''), 1000), auth.uid())
  returning id into v_id;

  return v_id;
end $fn$;

revoke all on function public.guardar_cliente(uuid, text, text, text, uuid) from public, anon;
grant execute on function public.guardar_cliente(uuid, text, text, text, uuid) to authenticated;

-- ------------------------------------------------------------
-- 2. ELIMINAR UN CLIENTE
--
--    Devuelve qué hizo: 'borrado' o 'archivado'. Para quien toca el botón es
--    lo mismo —deja de estar en la lista—, pero las pruebas necesitan saber
--    cuál de las dos pasó.
-- ------------------------------------------------------------
create or replace function public.eliminar_cliente(p_cliente uuid)
returns text language plpgsql security definer set search_path = public as $fn$
declare
  v       public.clientes;
  v_saldo numeric;
  v_debe  text;
begin
  select * into v from public.clientes where id = p_cliente;
  if v.id is null then
    raise exception 'Ese cliente ya no existe.' using errcode = 'P0002';
  end if;

  if not public.es_miembro(v.empresa_id) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if not public.es_admin(v.empresa_id) then
    raise exception 'Eliminar clientes es del dueño o de un administrador.' using errcode = '42501';
  end if;

  -- El mismo candado que al cobrar (056): mientras se decide, nadie le fía
  -- ni le cobra a este cliente.
  perform 1 from public.clientes where id = p_cliente for update;

  v_saldo := public.saldo_fiado(p_cliente);
  if v_saldo > 0 then
    -- «80.000» y no «80000.00»: esto lo lee una persona.
    v_debe := case when v_saldo = trunc(v_saldo)
                   then replace(to_char(v_saldo, 'FM999,999,999,990'), ',', '.')
                   else v_saldo::text end;
    raise exception '% todavía te debe %. Cobrale o borrá esa deuda desde Fiado, y después lo eliminás.',
      v.nombre, v_debe using errcode = '22023';
  end if;

  -- Sin nada atado se borra de verdad: no hay nada que conservar.
  if not exists (select 1 from public.fiado where cliente_id = p_cliente)
     and not exists (select 1 from public.movimientos where cliente_id = p_cliente)
     and not exists (select 1 from public.turnos_reserva where cliente_id = p_cliente) then
    delete from public.clientes where id = p_cliente;
    return 'borrado';
  end if;

  -- Con historia se archiva. La lista y el buscador ya dejan afuera a los
  -- archivados (052, 053); «lo que te deben» no, así que si alguna vez
  -- vuelve a deber algo, aparece ahí igual.
  update public.clientes set activo = false, updated_at = now() where id = p_cliente;
  return 'archivado';
end $fn$;

revoke all on function public.eliminar_cliente(uuid) from public, anon;
grant execute on function public.eliminar_cliente(uuid) to authenticated;

-- ------------------------------------------------------------
-- 3. ELIMINAR DEL CATÁLOGO
--
--    Devuelve 'borrado' o 'pausado', y la pantalla lo dice: si quedó
--    pausado, que no parezca que el botón no hizo lo que decía.
-- ------------------------------------------------------------
create or replace function public.eliminar_producto(p_producto uuid)
returns text language plpgsql security definer set search_path = public as $fn$
declare
  v_empresa uuid;
begin
  select empresa_id into v_empresa from public.productos where id = p_producto;
  if v_empresa is null then
    raise exception 'Eso ya no está en tu catálogo.' using errcode = 'P0002';
  end if;

  if not public.es_miembro(v_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if not public.es_admin(v_empresa) then
    raise exception 'Eliminar del catálogo es del dueño o de un administrador.' using errcode = '42501';
  end if;

  -- Que no se venda ni se reserve justo mientras se decide.
  perform 1 from public.productos where id = p_producto for update;

  -- Lo vendido queda atado a sus ventas (001) y al reparto (033), y un
  -- turno no puede quedar sin su servicio (037). En esos casos pausar hace
  -- lo que se busca —que no aparezca más para vender— sin soltar nada de lo
  -- que ya pasó.
  if exists (select 1 from public.movimiento_items where producto_id = p_producto)
     or exists (select 1 from public.turnos_atribucion where producto_id = p_producto)
     or exists (select 1 from public.turnos_reserva where producto_id = p_producto) then
    update public.productos set activo = false where id = p_producto;
    return 'pausado';
  end if;

  -- Nunca se usó: se borra, y con él su duración en la agenda (036) y sus
  -- precios por profesional (033), que sin el servicio no significan nada.
  delete from public.productos where id = p_producto;
  return 'borrado';
end $fn$;

revoke all on function public.eliminar_producto(uuid) from public, anon;
grant execute on function public.eliminar_producto(uuid) to authenticated;


-- ############################################################
-- ##  059_quitar_del_equipo.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 059 · Quitar a alguien del equipo sin romper nada
--
-- Lo pidió el dueño: poder quitar a alguien desde Equipo y reparto, y
-- cambiar cómo se le paga. Cambiar ya se podía, y no reescribe el pasado:
-- cada cobro guarda su propia parte desde la 033. Quitar tenía tres agujeros:
--
-- 1. Solo miraba los cobros. Alguien sin cobros pero con un pago registrado
--    no se podía borrar —la 035 frena ese borrado— y el dueño recibía un
--    error de la base que no dice nada.
--
-- 2. Alguien sin cobros pero con turnos se borraba, y sus turnos se iban con
--    él en cascada (037): el cliente llegaba y no había turno, y nadie le
--    había avisado.
--
-- 3. A quien se quitaba no había forma de volver a sumarlo.
--
-- Ahora:
--   · Con turnos agendados de acá en adelante, no se quita: primero se
--     mueven o se cancelan desde Agenda. El mensaje dice cuántos son.
--   · Con historia —cobros, pagos o turnos que ya pasaron— se desactiva.
--     Deja de aparecer para cobrar y para reservar (la agenda, el link y el
--     mostrador ya filtran por activo), y lo que pasó sigue diciendo de
--     quién fue.
--   · Sin nada, se borra de verdad.
--   · Guardarlo de nuevo lo vuelve a sumar.
--
-- El cuerpo de guardar_profesional se extrajo de la 048 con un script y se
-- le agregó solo la línea marcada con (059).
-- ============================================================

-- ------------------------------------------------------------
-- 1. GUARDAR A ALGUIEN DEL EQUIPO
--
--    Misma firma que en la 048: se reemplaza sin tocar a quien ya la llama.
-- ------------------------------------------------------------
create or replace function public.guardar_profesional(
  p_empresa    uuid,
  p_nombre     text,
  p_reparto    text    default 'local',
  p_porcentaje numeric default null,
  p_user       uuid    default null,
  p_id         uuid    default null
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare v_id uuid;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar el equipo.' using errcode = '42501';
  end if;

  if char_length(trim(coalesce(p_nombre, ''))) = 0 then
    raise exception 'Ponele un nombre, para saber de quién es cada corte.' using errcode = '22023';
  end if;

  if coalesce(p_reparto, '') not in ('local', 'comision', 'alquiler', 'sueldo') then
    raise exception 'Ese tipo de arreglo no existe.' using errcode = '22023';
  end if;

  if p_reparto = 'comision'
     and (p_porcentaje is null or p_porcentaje <= 0 or p_porcentaje > 100) then
    raise exception 'Con comisión hace falta un porcentaje entre 1 y 100.' using errcode = '22023';
  end if;

  -- El cambio de la 048. El mensaje explica el camino completo, porque el
  -- dueño está mirando una lista de nombres y no tiene por qué adivinar que
  -- primero hay que pasarle un código.
  if p_user is null then
    raise exception
      'Para estar en el equipo, esa persona tiene que entrar antes al negocio con el código de acceso. Pasale el código, que se cree su cuenta, y después sumala acá.'
      using errcode = '22023';
  end if;

  if not exists (select 1 from public.miembros m
                 where m.empresa_id = p_empresa and m.user_id = p_user) then
    raise exception 'Esa persona no es parte de este negocio.' using errcode = '42501';
  end if;

  if p_id is null then
    insert into public.turnos_profesional (empresa_id, nombre, user_id, reparto, porcentaje)
    values (p_empresa, trim(p_nombre), p_user, p_reparto,
            case when p_reparto = 'comision' then p_porcentaje else null end)
    returning id into v_id;
  else
    update public.turnos_profesional
    set nombre = trim(p_nombre),
        user_id = p_user,
        reparto = p_reparto,
        porcentaje = case when p_reparto = 'comision' then p_porcentaje else null end,
        -- (059) Guardar a alguien es tenerlo en el equipo. Sin esto, a quien se
        -- quitaba no había forma de volver a sumarlo: se lo editaba, se
        -- guardaba, y seguía afuera.
        activo = true,
        updated_at = now()
    where id = p_id and empresa_id = p_empresa
    returning id into v_id;

    if v_id is null then
      raise exception 'Esa persona no está en el equipo de esta cuenta.' using errcode = 'P0002';
    end if;
  end if;

  return v_id;
end $fn$;

revoke all on function public.guardar_profesional(uuid, text, text, numeric, uuid, uuid) from public, anon;
grant execute on function public.guardar_profesional(uuid, text, text, numeric, uuid, uuid) to authenticated;

-- ------------------------------------------------------------
-- 2. QUITAR DEL EQUIPO
--
--    Devuelve lo mismo que en la 034 —{borrado} o {desactivado}— para que
--    quien ya la llama no tenga que cambiar.
-- ------------------------------------------------------------
create or replace function public.borrar_profesional(p_empresa uuid, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v        public.turnos_profesional;
  v_turnos integer;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar el equipo.' using errcode = '42501';
  end if;

  -- El candado: que no se le anote un turno ni un cobro justo mientras se
  -- decide qué hacer con él.
  select * into v
  from public.turnos_profesional
  where id = p_id and empresa_id = p_empresa
  for update;

  if v.id is null then
    raise exception 'Esa persona no está en el equipo de esta cuenta.' using errcode = 'P0002';
  end if;

  select count(*)::int into v_turnos
  from public.turnos_reserva r
  where r.profesional_id = p_id
    and r.estado in ('pendiente', 'confirmada')
    and r.inicia > now();

  if v_turnos > 0 then
    raise exception
      '% todavía tiene turnos agendados (%). Pasalos a otra persona o cancelalos desde Agenda, y después lo sacás del equipo.',
      v.nombre, v_turnos
      using errcode = '22023';
  end if;

  -- Con historia se desactiva: sus cobros, lo que se le pagó y sus turnos
  -- viejos siguen diciendo de quién fueron, y la liquidación del mes pasado
  -- sigue cerrando.
  if exists (select 1 from public.turnos_atribucion where profesional_id = p_id)
     or exists (select 1 from public.turnos_pago where profesional_id = p_id)
     or exists (select 1 from public.turnos_reserva where profesional_id = p_id) then
    update public.turnos_profesional
    set activo = false, updated_at = now()
    where id = p_id;
    return jsonb_build_object('desactivado', true);
  end if;

  -- Sin nada: se borra, y con él su horario y sus precios propios, que sin
  -- la persona no significan nada.
  delete from public.turnos_profesional where id = p_id;
  return jsonb_build_object('borrado', true);
end $fn$;

revoke all on function public.borrar_profesional(uuid, uuid) from public, anon;
grant execute on function public.borrar_profesional(uuid, uuid) to authenticated;


-- ############################################################
-- ##  060_socios_y_comisiones.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 060 · Socios que traen clientes, y sus comisiones
--
-- La idea, tal como la escribió el dueño: cualquiera puede ganar plata
-- trayendo clientes nuevos a Orden, sin ser empleado ni tener que vender.
--
--   · La comisión es el 50% del PRIMER pago del referido.
--   · Se paga UNA SOLA VEZ. Lo que el cliente pague después es todo del
--     negocio, para siempre.
--   · Se gana cuando el cliente paga DE VERDAD, no cuando crea una cuenta
--     gratis. Por eso la comisión nace pegada al ingreso de Orden: si no
--     entró plata, no hay comisión.
--   · Se calcula sobre lo que realmente entró, no sobre el precio de lista.
--     Así los vendedores extra del Premium salen solos, y un descuento baja
--     la comisión en la misma proporción, sin tablas que mantener.
--
-- LO QUE NO SE VUELVE A CALCULAR NUNCA
--
-- Si después el negocio crece, sube de plan o suma vendedores, eso ya no le
-- toca a quien lo trajo. Sin esa regla habría que recalcular comisiones
-- viejas para siempre, y ese es el tipo de cuenta que termina mal.
--
-- SE PAGA A MANO
--
-- La comisión nace «por pagar». El dueño transfiere y la marca pagada desde
-- el panel, con el medio y una nota. El monto se puede ajustar al marcarla:
-- si alguien pagó un año por adelantado, la mitad de ese pago es mucha
-- plata, y esa decisión es de una persona, no de una fórmula.
--
-- El cuerpo de cambiar_plan_cuenta se extrajo de la 048 con un script y se
-- le agregó solo la parte marcada con (060).
-- ============================================================

-- ------------------------------------------------------------
-- 1. LOS SOCIOS
--
--    Quien trae clientes. No necesita cuenta en Orden: la mayoría no va a
--    usar el sistema, solo conoce negocios a los que les sirve.
-- ------------------------------------------------------------
create table if not exists public.socios (
  id         uuid primary key default gen_random_uuid(),
  nombre     text not null check (char_length(trim(nombre)) between 1 and 80),
  telefono   text not null default '' check (char_length(telefono) <= 40),
  email      text not null default '' check (char_length(email) <= 120),
  -- Lo que comparte para que le atribuyan los clientes que trae.
  codigo     text not null unique,
  -- Si tiene cuenta en Orden. Sirve para una sola cosa: que nadie se
  -- refiera a sí mismo.
  user_id    uuid references auth.users (id) on delete set null,
  activo     boolean not null default true,
  -- Cómo se le paga: banco, billetera, alias. Texto libre a propósito.
  cobra_en   text not null default '' check (char_length(cobra_en) <= 200),
  notas      text not null default '' check (char_length(notas) <= 500),
  creado_por uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- ------------------------------------------------------------
-- 2. QUIÉN TRAJO A QUIÉN
--
--    Un negocio tiene un solo socio, y para siempre: la clave primaria es la
--    empresa. Si mañana otro dice «yo también lo traje», contesta la base y
--    no hay que discutirlo con nadie.
-- ------------------------------------------------------------
create table if not exists public.referidos (
  empresa_id uuid primary key references public.empresas (id) on delete cascade,
  socio_id   uuid not null references public.socios (id) on delete restrict,
  origen     text not null default 'a_mano' check (origen in ('link', 'a_mano')),
  nota       text not null default '' check (char_length(nota) <= 300),
  creado_por uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now()
);

create index if not exists referidos_socio_idx on public.referidos (socio_id);

-- ------------------------------------------------------------
-- 3. LAS COMISIONES
--
--    Una por negocio. Ese índice único es lo que hace que «se paga una sola
--    vez» sea una propiedad de la base y no una intención.
-- ------------------------------------------------------------
create table if not exists public.comisiones (
  id            uuid primary key default gen_random_uuid(),
  socio_id      uuid not null references public.socios (id) on delete restrict,
  empresa_id    uuid not null unique references public.empresas (id) on delete cascade,
  -- El ingreso de Orden que la originó. Si se anula, la comisión se cae.
  movimiento_id uuid references public.movimientos (id) on delete set null,
  -- Y el gasto de Orden al pagarla. Pagar una comisión no es contabilidad
  -- aparte: es plata que salió, y tiene que verse en las finanzas de Orden.
  gasto_id      uuid references public.movimientos (id) on delete set null,
  base          numeric(14,2) not null check (base >= 0),
  porcentaje    numeric(5,2) not null check (porcentaje > 0 and porcentaje <= 100),
  monto         numeric(14,2) not null check (monto >= 0),
  estado        text not null default 'por_pagar' check (estado in ('por_pagar', 'pagada', 'anulada')),
  pagada_at     timestamptz,
  medio         text not null default '' check (char_length(medio) <= 60),
  nota          text not null default '' check (char_length(nota) <= 300),
  created_at    timestamptz not null default now()
);

create index if not exists comisiones_socio_idx on public.comisiones (socio_id, estado);

-- ------------------------------------------------------------
-- 4. QUIÉN VE ESTO
--
--    Nadie, salvo la administración de Orden, y siempre por función. Un
--    cliente no tiene por qué saber que existe un programa de socios, ni
--    cuánto se le paga a quien lo trajo.
-- ------------------------------------------------------------
alter table public.socios     enable row level security;
alter table public.referidos  enable row level security;
alter table public.comisiones enable row level security;

revoke all on public.socios     from anon, authenticated;
revoke all on public.referidos  from anon, authenticated;
revoke all on public.comisiones from anon, authenticated;

-- ------------------------------------------------------------
-- 5. EL PORCENTAJE, EN UN SOLO LUGAR
--
--    Si algún día deja de ser el 50%, se cambia acá y no en cinco lugares.
--    Las comisiones ya creadas guardan el suyo: cambiar el número de hoy no
--    puede reescribir lo que se le prometió a alguien el mes pasado.
-- ------------------------------------------------------------
alter table public.ajustes_orden
  add column if not exists comision_porcentaje numeric(5,2) not null default 50;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'ajustes_orden_comision_rango') then
    alter table public.ajustes_orden
      add constraint ajustes_orden_comision_rango
      check (comision_porcentaje > 0 and comision_porcentaje <= 100);
  end if;
end $$;

-- ------------------------------------------------------------
-- 6. EL COBRO, QUE AHORA GENERA LA COMISIÓN
--
--    Misma firma que en la 048: se reemplaza sin tocar a quien ya la llama.
-- ------------------------------------------------------------
create or replace function public.cambiar_plan_cuenta(
  p_empresa    uuid,
  p_plan       text,
  p_meses      integer default 1,
  p_nota       text default '',
  p_importe    numeric default null,
  p_vendedores integer default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_antes    public.suscripciones;
  v_fin      timestamptz;
  v_estado   text;
  v_orden    uuid;
  v_cliente  text;
  v_ingreso  uuid;
  v_aviso    text := null;
  v_tope     integer;
  v_personas integer;
  v_socio    uuid;
  v_pct      numeric;
  v_comision boolean := false;
begin
  if not public.es_superadmin() then
    raise exception 'Este panel es solo para la administración de Orden.' using errcode = '42501';
  end if;

  if p_plan not in ('gratis', 'pro', 'negocio') then
    raise exception 'Plan desconocido: %', p_plan using errcode = '22023';
  end if;

  if p_vendedores is not null and p_vendedores < -1 then
    raise exception 'El tope de vendedores no puede ser negativo.' using errcode = '22023';
  end if;

  select * into v_antes from public.suscripciones where empresa_id = p_empresa;
  if v_antes.empresa_id is null then
    raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
  end if;

  select nombre into v_cliente from public.empresas where id = p_empresa;

  if p_plan = 'gratis' then
    v_estado := 'vencida';
    v_fin := now();
    -- Cortar el servicio borra el trato: si vuelve, se negocia de nuevo.
    v_tope := null;
  else
    v_estado := 'activa';
    -- Si todavía le queda tiempo pago, se le suma; si no, arranca hoy.
    v_fin := greatest(coalesce(v_antes.periodo_fin, now()), now())
             + make_interval(months => greatest(1, coalesce(p_meses, 1)));
    v_tope := case
      when p_vendedores is null then v_antes.tope_vendedores  -- no se toca
      when p_vendedores = -1    then null                     -- volver al plan
      else p_vendedores
    end;
  end if;

  update public.suscripciones
  set plan = p_plan,
      estado = v_estado,
      periodo_inicio = case when p_plan = 'gratis' then periodo_inicio else now() end,
      periodo_fin = v_fin,
      tope_vendedores = v_tope,
      proveedor_pago = case when p_plan = 'gratis' then proveedor_pago else 'transferencia' end,
      updated_at = now()
  where empresa_id = p_empresa;

  perform set_config('orden.suscripcion_confiable', '1', true);
  update public.empresas
  set plan = case when p_plan = 'gratis' then 'gratis' else 'pro' end
  where id = p_empresa;
  perform set_config('orden.suscripcion_confiable', '0', true);

  -- ---- ¿le queda gente afuera del tope nuevo? ----
  --
  -- No se echa a nadie: bajar un número en un panel no puede sacarle el
  -- acceso a una persona que hoy está trabajando. Pero hay que decirlo, o
  -- el que lo bajó se entera cuando el cliente reclama.
  if v_tope is not null then
    select count(*)::int into v_personas from public.miembros where empresa_id = p_empresa;
    if v_personas > v_tope + 1 then
      v_aviso := 'Ojo: este negocio ya tiene ' || v_personas || ' personas y le habilitaste '
              || v_tope || ' vendedores (' || (v_tope + 1) || ' con el dueño). '
              || 'No se sacó a nadie, pero no va a poder sumar a nadie más.';
    end if;
  end if;

  -- ---- el cobro, como ingreso de Orden ----
  if p_plan <> 'gratis' and coalesce(p_importe, 0) > 0 then
    select empresa_id into v_orden from public.ajustes_orden where unica;

    if v_orden is null then
      v_aviso := coalesce(v_aviso || ' ', '')
              || 'No hay una empresa de Orden elegida, así que el cobro no se anotó en tus finanzas.';
    elsif v_orden = p_empresa then
      v_aviso := coalesce(v_aviso || ' ', '')
              || 'Esta ES tu empresa, así que no se anotó ningún ingreso.';
    else
      begin
        insert into public.movimientos (
          empresa_id, tipo, estado, fecha, descripcion, categoria,
          subtotal, descuento, monto, costo_total, metodo_pago, contraparte, creado_por
        ) values (
          v_orden, 'ingreso', 'activo', public.hoy_empresa(v_orden),
          'Suscripción ' || coalesce(v_cliente, 'cliente'), 'Suscripciones',
          p_importe, 0, p_importe, 0, 'transferencia',
          left(coalesce(v_cliente, ''), 80), auth.uid()
        )
        returning id into v_ingreso;
      exception when others then
        v_aviso := coalesce(v_aviso || ' ', '')
                || 'La cuenta se activó, pero el ingreso no se pudo anotar: ' || sqlerrm;
      end;
    end if;
  end if;

  -- ---- la comisión de quien trajo al cliente (060) ----
  -- Nace en el mismo momento en que entra la plata, y una sola vez por
  -- negocio: lo garantiza el índice único de comisiones, no el acordarse.
  -- Si el ingreso no se pudo anotar, no hay comisión: se paga por plata
  -- que entró, no por una cuenta activada.
  if v_ingreso is not null then
    select r.socio_id into v_socio
    from public.referidos r
    join public.socios s on s.id = r.socio_id
    where r.empresa_id = p_empresa and s.activo;

    if v_socio is not null then
      select coalesce(a.comision_porcentaje, 50) into v_pct
      from public.ajustes_orden a where a.unica;

      begin
        insert into public.comisiones (
          socio_id, empresa_id, movimiento_id, base, porcentaje, monto
        ) values (
          v_socio, p_empresa, v_ingreso, p_importe, coalesce(v_pct, 50),
          round(p_importe * coalesce(v_pct, 50) / 100)
        );
        v_comision := true;
      exception when unique_violation then
        -- Ya cobró por este negocio. Se paga una sola vez: el primer pago.
        null;
      end;
    end if;
  end if;

  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (auth.uid(), p_empresa, 'cambiar_plan', jsonb_build_object(
    'plan_antes', v_antes.plan, 'plan_despues', p_plan,
    'estado_antes', v_antes.estado, 'estado_despues', v_estado,
    'vence_antes', v_antes.periodo_fin, 'vence_despues', v_fin,
    'meses', greatest(1, coalesce(p_meses, 1)),
    'importe', p_importe,
    'tope_antes', v_antes.tope_vendedores,
    'tope_despues', v_tope,
    'ingreso_id', v_ingreso,
    'nota', left(coalesce(p_nota, ''), 300)
  ));

  return jsonb_build_object(
    'plan', p_plan, 'estado', v_estado, 'periodo_fin', v_fin,
    'tope_vendedores', v_tope,
    'personas_permitidas', public.tope_de_miembros(p_empresa),
    'ingreso_anotado', v_ingreso is not null,
    'comision_generada', v_comision,
    'aviso', v_aviso
  );
end $fn$;


-- ------------------------------------------------------------
-- 7. DAR DE ALTA (O EDITAR) UN SOCIO
--
--    El código se genera una sola vez y no cambia nunca más: puede estar
--    escrito en un WhatsApp que esa persona mandó hace dos meses.
--
--    Si el email coincide con un usuario de Orden, se guarda el vínculo. No
--    sirve para entrar a ningún lado todavía; sirve para una sola cosa: que
--    nadie cobre comisión por traerse a sí mismo.
-- ------------------------------------------------------------
create or replace function public.guardar_socio(
  p_socio    uuid default null,
  p_nombre   text default '',
  p_telefono text default '',
  p_email    text default '',
  p_cobra_en text default '',
  p_notas    text default '',
  p_activo   boolean default true
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_id      uuid;
  v_codigo  text;
  v_user    uuid;
  v_email   text;
  v_intento integer := 0;
begin
  if not public.es_superadmin() then
    raise exception 'Esto es solo para la administración de Orden.' using errcode = '42501';
  end if;

  if coalesce(trim(p_nombre), '') = '' then
    raise exception 'Falta el nombre de la persona.' using errcode = '22023';
  end if;

  v_email := left(lower(coalesce(trim(p_email), '')), 120);

  if v_email <> '' then
    select u.id into v_user from auth.users u where lower(u.email) = v_email limit 1;
  end if;

  if p_socio is null then
    loop
      v_codigo := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
      exit when not exists (select 1 from public.socios where codigo = v_codigo);
      v_intento := v_intento + 1;
      if v_intento > 20 then
        raise exception 'No se pudo generar el código. Probá de nuevo.' using errcode = '22023';
      end if;
    end loop;

    insert into public.socios (
      nombre, telefono, email, codigo, user_id, cobra_en, notas, activo, creado_por
    ) values (
      left(trim(p_nombre), 80), left(coalesce(trim(p_telefono), ''), 40), v_email,
      v_codigo, v_user, left(coalesce(trim(p_cobra_en), ''), 200),
      left(coalesce(trim(p_notas), ''), 500), coalesce(p_activo, true), auth.uid()
    )
    returning id, codigo into v_id, v_codigo;
  else
    update public.socios set
      nombre     = left(trim(p_nombre), 80),
      telefono   = left(coalesce(trim(p_telefono), ''), 40),
      email      = v_email,
      user_id    = coalesce(v_user, user_id),
      cobra_en   = left(coalesce(trim(p_cobra_en), ''), 200),
      notas      = left(coalesce(trim(p_notas), ''), 500),
      activo     = coalesce(p_activo, true),
      updated_at = now()
    where id = p_socio
    returning id, codigo into v_id, v_codigo;

    if v_id is null then
      raise exception 'Ese socio no existe.' using errcode = '22023';
    end if;
  end if;

  return jsonb_build_object('id', v_id, 'codigo', v_codigo);
end $fn$;

revoke all on function public.guardar_socio(uuid, text, text, text, text, text, boolean)
  from public, anon;
grant execute on function public.guardar_socio(uuid, text, text, text, text, text, boolean)
  to authenticated;

-- ------------------------------------------------------------
-- 8. ANOTAR QUIÉN TRAJO A UN NEGOCIO
--
--    Se anota una vez y no se cambia. Si dos personas dicen haber traído al
--    mismo cliente, contesta la base con el nombre del que ya está anotado, y
--    no hay que resolverlo de memoria ni por orden de reclamo.
--
--    Si el negocio ya había pagado antes de anotarlo, se avisa: ese primer
--    pago ya pasó, y la comisión se va a generar con el próximo cobro. Es
--    información para decidir el monto a mano, no un error que frene nada.
-- ------------------------------------------------------------
create or replace function public.asignar_referido(
  p_empresa uuid,
  p_codigo  text,
  p_nota    text default ''
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_socio public.socios;
  v_ya    uuid;
  v_pagos integer;
  v_aviso text := null;
begin
  if not public.es_superadmin() then
    raise exception 'Esto es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select * into v_socio from public.socios
  where codigo = upper(trim(coalesce(p_codigo, '')));

  if v_socio.id is null then
    raise exception 'No hay ningún socio con ese código.' using errcode = '22023';
  end if;

  if not v_socio.activo then
    raise exception '% está desactivado como socio.', v_socio.nombre using errcode = '22023';
  end if;

  if not exists (select 1 from public.empresas where id = p_empresa) then
    raise exception 'Ese negocio no existe.' using errcode = '22023';
  end if;

  if v_socio.user_id is not null and exists (
    select 1 from public.miembros m
    where m.empresa_id = p_empresa and m.user_id = v_socio.user_id
  ) then
    raise exception
      '% trabaja en ese negocio: no se cobra comisión por traerse a uno mismo.',
      v_socio.nombre using errcode = '22023';
  end if;

  select socio_id into v_ya from public.referidos where empresa_id = p_empresa;

  if v_ya is not null then
    if v_ya = v_socio.id then
      return jsonb_build_object(
        'ok', true, 'socio', v_socio.nombre,
        'aviso', 'Ya estaba anotado a nombre de ' || v_socio.nombre || '.'
      );
    end if;
    raise exception
      'Ese negocio ya está anotado a nombre de %. Se cuenta una sola vez y no se cambia.',
      coalesce((select nombre from public.socios where id = v_ya), 'otra persona')
      using errcode = '22023';
  end if;

  select count(*)::int into v_pagos
  from public.registro_admin r
  where r.empresa_id = p_empresa
    and r.accion = 'cambiar_plan'
    and coalesce(r.detalle->>'ingreso_id', '') <> '';

  if v_pagos > 0 then
    v_aviso := 'Ojo: este negocio ya pagó ' || v_pagos
            || (case when v_pagos = 1 then ' vez' else ' veces' end)
            || ' antes de anotarlo. La comisión no se genera por esos pagos, sino con el próximo cobro. Revisá el monto antes de pagarla.';
  end if;

  insert into public.referidos (empresa_id, socio_id, origen, nota, creado_por)
  values (p_empresa, v_socio.id, 'a_mano', left(coalesce(p_nota, ''), 300), auth.uid());

  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (auth.uid(), p_empresa, 'asignar_referido', jsonb_build_object(
    'socio_id', v_socio.id, 'socio', v_socio.nombre, 'codigo', v_socio.codigo,
    'pagos_previos', v_pagos
  ));

  return jsonb_build_object('ok', true, 'socio', v_socio.nombre, 'aviso', v_aviso);
end $fn$;

revoke all on function public.asignar_referido(uuid, text, text) from public, anon;
grant execute on function public.asignar_referido(uuid, text, text) to authenticated;

-- ------------------------------------------------------------
-- 9. DESANOTARLO, SI FUE UN ERROR
--
--    Solo mientras no haya plata de por medio. Si ya se le pagó la comisión,
--    borrar el vínculo sería borrar el por qué de un gasto real.
-- ------------------------------------------------------------
create or replace function public.quitar_referido(p_empresa uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_socio uuid;
  v_est   text;
begin
  if not public.es_superadmin() then
    raise exception 'Esto es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select socio_id into v_socio from public.referidos where empresa_id = p_empresa;
  if v_socio is null then
    raise exception 'Ese negocio no está anotado a nombre de nadie.' using errcode = '22023';
  end if;

  select estado into v_est from public.comisiones where empresa_id = p_empresa;

  if v_est = 'pagada' then
    raise exception
      'Ya se pagó la comisión por ese negocio, así que no se puede desanotar.'
      using errcode = '22023';
  end if;

  if v_est = 'por_pagar' then
    raise exception
      'Hay una comisión por pagar por ese negocio. Anulala primero y después desanotalo.'
      using errcode = '22023';
  end if;

  delete from public.referidos where empresa_id = p_empresa;

  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (auth.uid(), p_empresa, 'quitar_referido',
          jsonb_build_object('socio_id', v_socio));

  return jsonb_build_object('ok', true);
end $fn$;

revoke all on function public.quitar_referido(uuid) from public, anon;
grant execute on function public.quitar_referido(uuid) to authenticated;

-- ------------------------------------------------------------
-- 10. LA LISTA DE SOCIOS
--
--     Con lo único que importa mirar de un socio: a cuántos trajo, cuántos
--     de esos pagaron, cuánto se le debe y cuánto ya se le pagó.
-- ------------------------------------------------------------
create or replace function public.listar_socios(
  p_busqueda text default null,
  p_limite   integer default 200
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_res jsonb;
begin
  if not public.es_superadmin() then
    raise exception 'Esto es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(x order by x->>'nombre'), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'id',        s.id,
      'nombre',    s.nombre,
      'telefono',  s.telefono,
      'email',     s.email,
      'codigo',    s.codigo,
      'activo',    s.activo,
      'cobra_en',  s.cobra_en,
      'notas',     s.notas,
      'tiene_cuenta', s.user_id is not null,
      'creado',    s.created_at,
      'traidos',   (select count(*) from public.referidos r where r.socio_id = s.id),
      'pagaron',   (select count(*) from public.comisiones c
                    where c.socio_id = s.id and c.estado <> 'anulada'),
      'por_pagar', coalesce((select sum(c.monto) from public.comisiones c
                             where c.socio_id = s.id and c.estado = 'por_pagar'), 0),
      'pagado',    coalesce((select sum(c.monto) from public.comisiones c
                             where c.socio_id = s.id and c.estado = 'pagada'), 0)
    ) as x
    from public.socios s
    where (
        p_busqueda is null
        or trim(p_busqueda) = ''
        or s.nombre ilike '%' || trim(p_busqueda) || '%'
        or s.codigo ilike '%' || trim(p_busqueda) || '%'
        or s.telefono ilike '%' || trim(p_busqueda) || '%'
        or s.email ilike '%' || trim(p_busqueda) || '%'
      )
    order by s.nombre
    limit greatest(1, least(coalesce(p_limite, 200), 500))
  ) t;

  return v_res;
end $fn$;

revoke all on function public.listar_socios(text, integer) from public, anon;
grant execute on function public.listar_socios(text, integer) to authenticated;

-- ------------------------------------------------------------
-- 11. LAS COMISIONES
--
--     Para la pantalla de por pagar: quién, por qué negocio, sobre cuánto, y
--     dónde cobra. Con el aviso de si el ingreso que la originó terminó
--     anulado, que es el caso en el que no hay que transferir nada.
-- ------------------------------------------------------------
create or replace function public.listar_comisiones(
  p_estado text default null,
  p_socio  uuid default null,
  p_limite integer default 200
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_res jsonb;
begin
  if not public.es_superadmin() then
    raise exception 'Esto es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(x order by x->>'creado' desc), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'id',         c.id,
      'socio_id',   c.socio_id,
      'socio',      s.nombre,
      'telefono',   s.telefono,
      'cobra_en',   s.cobra_en,
      'empresa_id', c.empresa_id,
      'negocio',    coalesce(e.nombre, 'Negocio borrado'),
      'base',       c.base,
      'porcentaje', c.porcentaje,
      'monto',      c.monto,
      'estado',     c.estado,
      'creado',     c.created_at,
      'pagada_at',  c.pagada_at,
      'medio',      c.medio,
      'nota',       c.nota,
      -- estado es un enum: se compara como texto o revienta con el coalesce.
      'ingreso_anulado', coalesce(mv.estado::text, '') = 'anulado'
    ) as x
    from public.comisiones c
    join public.socios s on s.id = c.socio_id
    left join public.empresas e on e.id = c.empresa_id
    left join public.movimientos mv on mv.id = c.movimiento_id
    where (p_estado is null or trim(p_estado) = '' or c.estado = p_estado)
      and (p_socio is null or c.socio_id = p_socio)
    order by c.created_at desc
    limit greatest(1, least(coalesce(p_limite, 200), 500))
  ) t;

  return v_res;
end $fn$;

revoke all on function public.listar_comisiones(text, uuid, integer) from public, anon;
grant execute on function public.listar_comisiones(text, uuid, integer) to authenticated;

-- ------------------------------------------------------------
-- 11 bis. QUIÉN TRAJO A CADA NEGOCIO
--
--        Para la ficha de cada cliente en el panel: una sola consulta para
--        toda la lista, en vez de una por cada ficha que se abre.
-- ------------------------------------------------------------
create or replace function public.listar_referidos(p_limite integer default 500)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_res jsonb;
begin
  if not public.es_superadmin() then
    raise exception 'Esto es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'empresa_id', r.empresa_id,
      'socio_id',   r.socio_id,
      'socio',      s.nombre,
      'codigo',     s.codigo,
      'origen',     r.origen,
      'nota',       r.nota,
      'desde',      r.created_at,
      'comision',   c.estado,
      'monto',      c.monto
    ) as x
    from public.referidos r
    join public.socios s on s.id = r.socio_id
    left join public.comisiones c on c.empresa_id = r.empresa_id
    limit greatest(1, least(coalesce(p_limite, 500), 2000))
  ) t;

  return v_res;
end $fn$;

revoke all on function public.listar_referidos(integer) from public, anon;
grant execute on function public.listar_referidos(integer) to authenticated;

-- ------------------------------------------------------------
-- 12. MARCARLA PAGADA
--
--     El monto se puede ajustar acá, y a propósito: si un negocio pagó un
--     año por adelantado, la mitad de ese pago es mucha plata, y esa
--     decisión es de una persona mirando el caso, no de una fórmula.
--
--     El pago queda como gasto de Orden. Si no se pudo anotar, la comisión
--     igual se marca pagada —la transferencia ya se hizo— y se avisa.
-- ------------------------------------------------------------
create or replace function public.marcar_comision_pagada(
  p_comision uuid,
  p_monto    numeric default null,
  p_medio    text default '',
  p_nota     text default ''
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_c     public.comisiones;
  v_socio text;
  v_monto numeric;
  v_orden uuid;
  v_gasto uuid;
  v_aviso text := null;
begin
  if not public.es_superadmin() then
    raise exception 'Esto es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select * into v_c from public.comisiones where id = p_comision;

  if v_c.id is null then
    raise exception 'Esa comisión no existe.' using errcode = '22023';
  end if;

  if v_c.estado = 'pagada' then
    raise exception 'Esa comisión ya está pagada.' using errcode = '22023';
  end if;

  if v_c.estado = 'anulada' then
    raise exception 'Esa comisión está anulada: el cobro que la generó se deshizo.'
      using errcode = '22023';
  end if;

  v_monto := coalesce(p_monto, v_c.monto);

  if v_monto < 0 then
    raise exception 'El monto no puede ser negativo.' using errcode = '22023';
  end if;

  select nombre into v_socio from public.socios where id = v_c.socio_id;
  select empresa_id into v_orden from public.ajustes_orden where unica;

  if v_orden is null then
    v_aviso := 'No hay una empresa de Orden elegida, así que el pago no se anotó en tus finanzas.';
  elsif v_monto > 0 then
    begin
      insert into public.movimientos (
        empresa_id, tipo, estado, fecha, descripcion, categoria,
        subtotal, descuento, monto, costo_total, metodo_pago, contraparte, creado_por
      ) values (
        v_orden, 'gasto', 'activo', public.hoy_empresa(v_orden),
        'Comisión a ' || coalesce(v_socio, 'socio'), 'Comisiones',
        v_monto, 0, v_monto, 0, 'transferencia',
        left(coalesce(v_socio, ''), 80), auth.uid()
      )
      returning id into v_gasto;
    exception when others then
      v_aviso := 'La comisión quedó pagada, pero el gasto no se pudo anotar: ' || sqlerrm;
    end;
  end if;

  update public.comisiones set
    estado    = 'pagada',
    monto     = v_monto,
    pagada_at = now(),
    gasto_id  = v_gasto,
    medio     = left(coalesce(trim(p_medio), ''), 60),
    nota      = left(coalesce(trim(p_nota), ''), 300)
  where id = p_comision;

  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (auth.uid(), v_c.empresa_id, 'pagar_comision', jsonb_build_object(
    'comision_id', v_c.id,
    'socio_id', v_c.socio_id,
    'socio', v_socio,
    'monto_calculado', v_c.monto,
    'monto_pagado', v_monto,
    'medio', left(coalesce(trim(p_medio), ''), 60),
    'gasto_id', v_gasto
  ));

  return jsonb_build_object(
    'ok', true,
    'monto', v_monto,
    'ajustado', v_monto <> v_c.monto,
    'gasto_anotado', v_gasto is not null,
    'aviso', v_aviso
  );
end $fn$;

revoke all on function public.marcar_comision_pagada(uuid, numeric, text, text) from public, anon;
grant execute on function public.marcar_comision_pagada(uuid, numeric, text, text) to authenticated;

-- ------------------------------------------------------------
-- 13. ANULARLA A MANO
--
--     Para el caso que no puede resolver ninguna regla: la transferencia
--     nunca llegó, el cliente se arrepintió, el referido era falso. Queda
--     anulada con el motivo escrito, y el negocio sigue anotado igual: no se
--     vuelve a generar otra comisión por él.
-- ------------------------------------------------------------
create or replace function public.anular_comision(
  p_comision uuid,
  p_nota     text default ''
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_c public.comisiones;
begin
  if not public.es_superadmin() then
    raise exception 'Esto es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select * into v_c from public.comisiones where id = p_comision;

  if v_c.id is null then
    raise exception 'Esa comisión no existe.' using errcode = '22023';
  end if;

  if v_c.estado = 'pagada' then
    raise exception
      'Esa comisión ya se pagó. Si hay que recuperar la plata, eso se arregla con la persona, no borrando el registro.'
      using errcode = '22023';
  end if;

  update public.comisiones set
    estado = 'anulada',
    nota   = left(coalesce(trim(p_nota), ''), 300)
  where id = p_comision;

  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (auth.uid(), v_c.empresa_id, 'anular_comision', jsonb_build_object(
    'comision_id', v_c.id, 'socio_id', v_c.socio_id, 'monto', v_c.monto,
    'motivo', left(coalesce(trim(p_nota), ''), 300)
  ));

  return jsonb_build_object('ok', true);
end $fn$;

revoke all on function public.anular_comision(uuid, text) from public, anon;
grant execute on function public.anular_comision(uuid, text) to authenticated;

-- ------------------------------------------------------------
-- 14. SI EL COBRO SE DESHACE, LA COMISIÓN TAMBIÉN
--
--     Se paga por plata que entró. Si el ingreso que la generó se anula, la
--     comisión que está por pagar se cae sola, y no queda esperando en la
--     lista a que alguien se acuerde de revisarla.
--
--     Si ya estaba pagada no se toca: esa plata salió de verdad, y el gasto
--     queda en las finanzas de Orden, que es exactamente lo que pasó.
--
--     Va como trigger y no dentro de anular_movimiento por lo mismo de
--     siempre: es una regla sobre el dato, y tiene que valer venga por donde
--     venga, incluido un UPDATE desde el editor SQL.
-- ------------------------------------------------------------
create or replace function public.anular_baja_la_comision()
returns trigger language plpgsql security definer set search_path = public as $fn$
begin
  if new.estado <> 'anulado' or old.estado = 'anulado' then
    return new;
  end if;

  update public.comisiones
  set estado = 'anulada',
      nota = left(
        case when coalesce(nota, '') = '' then '' else nota || ' · ' end
        || 'Se anuló el cobro que la generó.', 300)
  where movimiento_id = new.id and estado = 'por_pagar';

  return new;
end $fn$;

revoke all on function public.anular_baja_la_comision() from public, anon, authenticated;

drop trigger if exists anular_baja_la_comision on public.movimientos;
create trigger anular_baja_la_comision
  after update on public.movimientos
  for each row execute function public.anular_baja_la_comision();


-- ############################################################
-- ##  061_recomendar_orden.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 061 · Recomendar Orden desde adentro
--
-- La 060 dejó el programa de socios funcionando, pero con una sola puerta: la
-- administración cargaba a la persona a mano. El cuaderno del dueño dice otra
-- cosa, y es mejor:
--
--   «Cada usuario tendrá la opción de generar un extra comisionando,
--    recomendando Orden. Se le dará el 50% de lo que pagó el nuevo usuario.»
--   «El usuario que accedió para recomendar Orden tendrá un link para
--    compartir o un código.»
--
-- Así que el socio no es alguien de afuera que se carga a mano: es cualquier
-- usuario de Orden que pide su código. Esta migración abre esa puerta.
--
-- QUIÉN PUEDE RECOMENDAR
--
-- Cualquiera con cuenta, pague o no. Bloquearlo a los que ya pagan achicaría
-- el programa justo donde más sirve: el que está en la prueba y le encantó es
-- el que más habla del sistema esta semana. Lo que sí se sostiene es la otra
-- regla, que es la que protege la plata: nadie se trae a sí mismo, y la
-- comisión se paga a mano, mirándola.
--
-- POR QUÉ EL CÓDIGO SE PIDE Y NO SE REPARTE SOLO
--
-- Se podría crear un código para cada usuario al registrarse. No se hace: la
-- inmensa mayoría no va a recomendar nada, y quedarían miles de filas
-- muertas. El código nace cuando alguien entra a la pantalla y lo pide.
-- ============================================================

-- ------------------------------------------------------------
-- 1. MI CÓDIGO
--
--    Lo pide el usuario para sí mismo. Si ya lo tenía, se le devuelve el
--    mismo: el código no cambia nunca, porque puede estar pegado en un
--    mensaje que mandó hace dos meses.
--
--    Y si la administración ya lo había cargado a mano por su correo, es la
--    misma persona: se le pega la cuenta en vez de dejarle dos códigos
--    distintos y dos listas de referidos que nadie va a poder juntar después.
-- ------------------------------------------------------------
create or replace function public.mi_codigo_socio()
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_uid     uuid := auth.uid();
  v_socio   public.socios;
  v_nombre  text;
  v_email   text;
  v_codigo  text;
  v_intento integer := 0;
begin
  if v_uid is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  select * into v_socio from public.socios where user_id = v_uid;

  if v_socio.id is null then
    select lower(coalesce(u.email, '')) into v_email from auth.users u where u.id = v_uid;

    select * into v_socio from public.socios
    where user_id is null and email <> '' and email = v_email
    limit 1;

    if v_socio.id is not null then
      update public.socios set user_id = v_uid, updated_at = now() where id = v_socio.id;
    end if;
  end if;

  if v_socio.id is null then
    -- El nombre con el que se presentó en su negocio. Es el que va a
    -- reconocer cuando lo vea en la lista de socios.
    select m.nombre into v_nombre
    from public.miembros m
    where m.user_id = v_uid and coalesce(trim(m.nombre), '') <> ''
    order by m.created_at
    limit 1;

    loop
      v_codigo := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
      exit when not exists (select 1 from public.socios where codigo = v_codigo);
      v_intento := v_intento + 1;
      if v_intento > 20 then
        raise exception 'No se pudo generar el código. Probá de nuevo.' using errcode = '55000';
      end if;
    end loop;

    insert into public.socios (nombre, email, codigo, user_id, creado_por)
    values (
      left(coalesce(nullif(trim(v_nombre), ''), nullif(split_part(v_email, '@', 1), ''), 'Socio'), 80),
      left(coalesce(v_email, ''), 120), v_codigo, v_uid, v_uid
    )
    returning * into v_socio;
  end if;

  -- Desactivado no es un error a esconder: si alguien quedó afuera del
  -- programa tiene que enterarse, y no quedarse esperando una comisión.
  if not v_socio.activo then
    raise exception 'Tu código de recomendación está desactivado. Escribinos y lo vemos.'
      using errcode = '42501';
  end if;

  return jsonb_build_object(
    'codigo',   v_socio.codigo,
    'nombre',   v_socio.nombre,
    'cobra_en', v_socio.cobra_en
  );
end $fn$;

revoke all on function public.mi_codigo_socio() from public, anon;
grant execute on function public.mi_codigo_socio() to authenticated;

-- ------------------------------------------------------------
-- 2. DÓNDE COBRO
--
--    El socio escribe su banco o su billetera. Es lo único suyo que puede
--    editar: el nombre y el correo salen de su cuenta, y el código no se
--    toca. Que lo escriba él ahorra el ida y vuelta de pedírselo por
--    WhatsApp justo cuando hay que transferirle.
-- ------------------------------------------------------------
create or replace function public.guardar_donde_cobro(p_cobra_en text)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_uid uuid := auth.uid();
  v_id  uuid;
begin
  if v_uid is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  update public.socios
  set cobra_en = left(coalesce(trim(p_cobra_en), ''), 200), updated_at = now()
  where user_id = v_uid
  returning id into v_id;

  if v_id is null then
    raise exception 'Todavía no pediste tu código de recomendación.' using errcode = '22023';
  end if;

  return jsonb_build_object('ok', true);
end $fn$;

revoke all on function public.guardar_donde_cobro(text) from public, anon;
grant execute on function public.guardar_donde_cobro(text) to authenticated;

-- ------------------------------------------------------------
-- 3. MI PANEL DE RECOMENDADOS
--
--    Lo que el socio necesita ver, y nada más: a quiénes trajo, cuáles
--    llegaron a pagar, cuánto le van a dar y cuánto ya cobró.
--
--    NO devuelve un solo número de las finanzas del negocio que trajo. Ve el
--    nombre, si está pagando y la comisión que le toca —que sale de un pago
--    que él mismo generó—. Nada de lo que ese negocio vende, gasta o debe.
--
--    No crea nada: si todavía no pidió su código, contesta que no lo tiene.
--    Una lectura que escribe es una lectura que un día se llama dos veces.
-- ------------------------------------------------------------
create or replace function public.mi_panel_socio()
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_uid   uuid := auth.uid();
  v_socio public.socios;
  v_lista jsonb;
begin
  if v_uid is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  select * into v_socio from public.socios where user_id = v_uid;

  if v_socio.id is null then
    return jsonb_build_object('tiene_codigo', false);
  end if;

  select coalesce(jsonb_agg(x order by x->>'desde' desc), '[]'::jsonb) into v_lista
  from (
    select jsonb_build_object(
      'negocio',  coalesce(e.nombre, 'Negocio borrado'),
      'desde',    r.created_at,
      'paga',     public.plan_efectivo_calculado(r.empresa_id) <> 'gratis',
      'plan',     public.plan_efectivo_calculado(r.empresa_id),
      'estado',   coalesce(c.estado, 'sin_pagar'),
      'monto',    coalesce(c.monto, 0),
      'cuando',   c.created_at,
      'pagada_at', c.pagada_at
    ) as x
    from public.referidos r
    left join public.empresas e on e.id = r.empresa_id
    left join public.comisiones c on c.empresa_id = r.empresa_id
    where r.socio_id = v_socio.id
  ) t;

  return jsonb_build_object(
    'tiene_codigo', true,
    'codigo',    v_socio.codigo,
    'nombre',    v_socio.nombre,
    'cobra_en',  v_socio.cobra_en,
    'activo',    v_socio.activo,
    'traidos',   (select count(*) from public.referidos r where r.socio_id = v_socio.id),
    'pagaron',   (select count(*) from public.comisiones c
                  where c.socio_id = v_socio.id and c.estado <> 'anulada'),
    'por_pagar', coalesce((select sum(c.monto) from public.comisiones c
                           where c.socio_id = v_socio.id and c.estado = 'por_pagar'), 0),
    'pagado',    coalesce((select sum(c.monto) from public.comisiones c
                           where c.socio_id = v_socio.id and c.estado = 'pagada'), 0),
    'referidos', v_lista
  );
end $fn$;

revoke all on function public.mi_panel_socio() from public, anon;
grant execute on function public.mi_panel_socio() to authenticated;

-- ------------------------------------------------------------
-- 4. ENTRAR CON EL CÓDIGO DE ALGUIEN
--
--    Lo llama el dueño de la cuenta recién creada, no la administración. Es
--    la otra mitad del link que comparte el socio.
--
--    LAS TRES PUERTAS QUE CIERRA
--
--    · El código es para cuentas NUEVAS. Pasados los 30 días ya no sirve: si
--      no, alguien reparte su código entre clientes que Orden ya tenía y
--      cobra por gente que no trajo.
--    · Una cuenta que ya pagó no se puede reclamar. El premio es por traer a
--      alguien, no por llegar primero a un cliente que ya estaba pagando.
--    · Nadie se trae a sí mismo, ni a un negocio donde trabaja.
--
--    Y si algo de eso falla, falla con un mensaje claro: esto lo llama una
--    persona que acaba de registrarse, y no puede quedarse pensando que su
--    cuenta se rompió.
-- ------------------------------------------------------------
create or replace function public.usar_codigo_referido(p_empresa uuid, p_codigo text)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_uid    uuid := auth.uid();
  v_socio  public.socios;
  v_creada timestamptz;
  v_ya     uuid;
begin
  if v_uid is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  -- Solo el dueño. Un vendedor no decide a nombre de quién queda el negocio
  -- donde trabaja.
  if not exists (
    select 1 from public.miembros m
    where m.empresa_id = p_empresa and m.user_id = v_uid and m.rol = 'propietario'
  ) then
    raise exception 'Solo el dueño de la cuenta puede usar un código.' using errcode = '42501';
  end if;

  select * into v_socio from public.socios
  where codigo = upper(trim(coalesce(p_codigo, '')));

  if v_socio.id is null then
    raise exception 'Ese código no existe. Revisalo con quien te lo pasó.' using errcode = '22023';
  end if;

  if not v_socio.activo then
    raise exception 'Ese código ya no está activo.' using errcode = '22023';
  end if;

  if v_socio.user_id = v_uid then
    raise exception 'Ese es tu propio código: no se gana comisión por uno mismo.'
      using errcode = '22023';
  end if;

  if v_socio.user_id is not null and exists (
    select 1 from public.miembros m
    where m.empresa_id = p_empresa and m.user_id = v_socio.user_id
  ) then
    raise exception 'Esa persona trabaja en este negocio: no corresponde comisión.'
      using errcode = '22023';
  end if;

  select socio_id into v_ya from public.referidos where empresa_id = p_empresa;
  if v_ya is not null then
    if v_ya = v_socio.id then
      return jsonb_build_object('ok', true, 'socio', v_socio.nombre, 'repetido', true);
    end if;
    raise exception 'Esta cuenta ya entró con otro código.' using errcode = '22023';
  end if;

  select created_at into v_creada from public.empresas where id = p_empresa;
  if v_creada is null then
    raise exception 'Esa cuenta no existe.' using errcode = '22023';
  end if;

  if v_creada < now() - interval '30 days' then
    raise exception 'El código es para cuentas nuevas, y esta ya tiene más de un mes.'
      using errcode = '22023';
  end if;

  if exists (
    select 1 from public.registro_admin r
    where r.empresa_id = p_empresa and r.accion = 'cambiar_plan'
      and coalesce(r.detalle->>'ingreso_id', '') <> ''
  ) then
    raise exception 'Esta cuenta ya pagó, así que el código no corresponde.'
      using errcode = '22023';
  end if;

  insert into public.referidos (empresa_id, socio_id, origen, nota, creado_por)
  values (p_empresa, v_socio.id, 'link', '', v_uid);

  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (v_uid, p_empresa, 'asignar_referido', jsonb_build_object(
    'socio_id', v_socio.id, 'socio', v_socio.nombre, 'codigo', v_socio.codigo,
    'origen', 'link'
  ));

  return jsonb_build_object('ok', true, 'socio', v_socio.nombre, 'repetido', false);
end $fn$;

revoke all on function public.usar_codigo_referido(uuid, text) from public, anon;
grant execute on function public.usar_codigo_referido(uuid, text) to authenticated;

-- ------------------------------------------------------------
-- 5. LA LISTA DEL ADMINISTRADOR, CON LO QUE FALTABA
--
--    Del cuaderno: «ver los usuarios que accedieron para ganar la comisión, a
--    cuántas personas hizo suscribir, cuánto le debería de dar por el 50%, y
--    en qué se suscribieron sus recomendados».
--
--    Lo que faltaba era lo último: el plan de cada negocio traído y si está
--    pagando. Sin eso, «trajo cuatro» no dice si trajo cuatro clientes o
--    cuatro cuentas gratis que nunca van a pagar.
-- ------------------------------------------------------------
create or replace function public.listar_referidos(p_limite integer default 500)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_res jsonb;
begin
  if not public.es_superadmin() then
    raise exception 'Esto es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'empresa_id', r.empresa_id,
      'negocio',    coalesce(e.nombre, 'Negocio borrado'),
      'socio_id',   r.socio_id,
      'socio',      s.nombre,
      'codigo',     s.codigo,
      'origen',     r.origen,
      'nota',       r.nota,
      'desde',      r.created_at,
      'plan',       public.plan_efectivo_calculado(r.empresa_id),
      'paga',       public.plan_efectivo_calculado(r.empresa_id) <> 'gratis',
      'comision',   c.estado,
      'base',       c.base,
      'monto',      c.monto
    ) as x
    from public.referidos r
    join public.socios s on s.id = r.socio_id
    left join public.empresas e on e.id = r.empresa_id
    left join public.comisiones c on c.empresa_id = r.empresa_id
    limit greatest(1, least(coalesce(p_limite, 500), 2000))
  ) t;

  return v_res;
end $fn$;

revoke all on function public.listar_referidos(integer) from public, anon;
grant execute on function public.listar_referidos(integer) to authenticated;


-- ############################################################
-- ##  062_pedir_en_el_momento.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 062 · Pedir la recomendación en el momento
--
-- El programa de socios (060 y 061) tiene una pantalla, y una pantalla en un
-- menú no la abre nadie. Lo que mata a estos programas no es el abuso: es el
-- silencio.
--
-- Así que se pide solo, y se pide donde la persona acaba de ver que Orden le
-- sirve: al cerrar un buen día, y justo después de pagar. Nunca en un menú,
-- nunca a alguien que recién entró, nunca dos veces seguidas.
--
-- LAS REGLAS VIVEN ACÁ Y NO EN LA PANTALLA
--
-- Son cinco condiciones, y si viven en el componente hay que repetirlas en
-- cada lugar donde se pida —y el día que se agregue el tercero, alguna se va
-- a quedar afuera—. La pantalla pregunta «¿pido?» y la base contesta.
--
-- Lo único que decide cada pantalla es lo suyo: el cierre, que el día haya
-- cerrado bien; el plan, que el pago sea reciente. Eso es el momento, y el
-- momento es distinto en cada lugar.
--
-- Y LO QUE HACE QUE TRAIGA AL SEGUNDO
--
-- Cuando el que trajo paga de verdad, hay que avisarle. Sin eso manda un
-- enlace, no pasa nada visible, y no manda nunca más. Es lo más barato de
-- todo el programa y es lo que más rinde.
-- ============================================================

-- ------------------------------------------------------------
-- 1. DOS FECHAS EN LAS PREFERENCIAS DE LA PERSONA
--
--    Van en `preferencias` y no en la empresa: quien recomienda es una
--    persona. Si las guardara el negocio, un vendedor vería el «ahora no» de
--    su jefe, y el jefe volvería a ver el aviso en cada empresa suya.
-- ------------------------------------------------------------
alter table public.preferencias
  add column if not exists recomendar_pedido_at timestamptz,
  add column if not exists comisiones_vistas_at timestamptz;

comment on column public.preferencias.recomendar_pedido_at is
  'Última vez que se le ofreció recomendar Orden. Se respeta 30 días.';
comment on column public.preferencias.comisiones_vistas_at is
  'Hasta cuándo vio sus comisiones nuevas. Lo posterior es novedad.';

-- ------------------------------------------------------------
-- 2. ¿ES MOMENTO DE PEDIRLE?
--
--    Las cinco condiciones, en un solo lugar:
--
--    · Que ya no tenga su código: al que ya está adentro no se le pide, se le
--      muestra lo que ganó.
--    · Que hayan pasado 30 días desde la última vez. Si aparece en cada día
--      bueno, se vuelve paisaje y deja de verse.
--    · Que use Orden hace al menos una semana. Pedirle a alguien de dos días
--      que recomiende es pedirle que mienta.
--    · Que tenga movimientos cargados de verdad, no tres de prueba.
--    · Que la cuenta no esté vencida. Pedirle un favor a alguien a quien se
--      le cortó el servicio es el peor momento posible.
-- ------------------------------------------------------------
create or replace function public.momento_de_recomendar(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_uid    uuid := auth.uid();
  v_ultima timestamptz;
  v_creada timestamptz;
  v_movs   integer;
begin
  -- Sin sesión o mirando un negocio ajeno no se contesta nada. Esto no
  -- devuelve datos de nadie, pero la costumbre de comprobar siempre es la
  -- que hace que no se olvide el día que sí importa.
  if v_uid is null or not public.es_miembro(p_empresa) then
    return jsonb_build_object('pedir', false);
  end if;

  if exists (select 1 from public.socios s where s.user_id = v_uid) then
    return jsonb_build_object('pedir', false);
  end if;

  select recomendar_pedido_at into v_ultima
  from public.preferencias where user_id = v_uid;

  if v_ultima is not null and v_ultima > now() - interval '30 days' then
    return jsonb_build_object('pedir', false);
  end if;

  select created_at into v_creada from public.empresas where id = p_empresa;
  if v_creada is null or v_creada > now() - interval '7 days' then
    return jsonb_build_object('pedir', false);
  end if;

  if public.plan_efectivo_calculado(p_empresa) = 'gratis' then
    return jsonb_build_object('pedir', false);
  end if;

  select count(*)::int into v_movs
  from public.movimientos mv
  where mv.empresa_id = p_empresa and mv.estado = 'activo';

  if v_movs < 15 then
    return jsonb_build_object('pedir', false);
  end if;

  return jsonb_build_object('pedir', true);
end $fn$;

revoke all on function public.momento_de_recomendar(uuid) from public, anon;
grant execute on function public.momento_de_recomendar(uuid) to authenticated;

-- ------------------------------------------------------------
-- 3. «AHORA NO»
--
--    Se guarda por persona y no en el teléfono: quien dijo que no en la
--    computadora no tiene que volver a decirlo en el celular.
--
--    Se llama también cuando SÍ acepta. Parece raro y no lo es: apenas pide
--    su código deja de entrar por esta puerta, y si algo fallara justo ahí,
--    lo peor que pasa es que no se le vuelva a ofrecer por un mes.
-- ------------------------------------------------------------
create or replace function public.posponer_recomendacion()
returns jsonb language plpgsql security definer set search_path = public as $fn$
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  insert into public.preferencias as p (user_id, recomendar_pedido_at)
  values (auth.uid(), now())
  on conflict (user_id) do update set
    recomendar_pedido_at = now(),
    updated_at = now();

  return jsonb_build_object('ok', true);
end $fn$;

revoke all on function public.posponer_recomendacion() from public, anon;
grant execute on function public.posponer_recomendacion() to authenticated;

-- ------------------------------------------------------------
-- 4. «FULANO PAGÓ SU PRIMER MES»
--
--    La novedad para el socio. Solo lo que pasó desde la última vez que
--    miró: un aviso que repite lo de siempre se aprende a ignorar en dos
--    días.
--
--    Las anuladas no avisan. Prometerle plata a alguien y después decirle
--    que no, por un cobro que se deshizo, es peor que no haberle dicho nada.
-- ------------------------------------------------------------
create or replace function public.novedad_comisiones()
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_uid    uuid := auth.uid();
  v_socio  uuid;
  v_desde  timestamptz;
  v_cuanto integer;
  v_total  numeric;
  v_quien  text;
begin
  if v_uid is null then
    return jsonb_build_object('hay', false);
  end if;

  select id into v_socio from public.socios where user_id = v_uid;
  if v_socio is null then
    return jsonb_build_object('hay', false);
  end if;

  select comisiones_vistas_at into v_desde from public.preferencias where user_id = v_uid;

  select count(*)::int, coalesce(sum(c.monto), 0), max(e.nombre)
  into v_cuanto, v_total, v_quien
  from public.comisiones c
  left join public.empresas e on e.id = c.empresa_id
  where c.socio_id = v_socio
    and c.estado <> 'anulada'
    and c.created_at > coalesce(v_desde, '-infinity'::timestamptz);

  if coalesce(v_cuanto, 0) = 0 then
    return jsonb_build_object('hay', false);
  end if;

  return jsonb_build_object(
    'hay', true,
    'cuantos', v_cuanto,
    'total', v_total,
    'negocio', coalesce(v_quien, 'un negocio')
  );
end $fn$;

revoke all on function public.novedad_comisiones() from public, anon;
grant execute on function public.novedad_comisiones() to authenticated;

create or replace function public.marcar_comisiones_vistas()
returns jsonb language plpgsql security definer set search_path = public as $fn$
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  insert into public.preferencias as p (user_id, comisiones_vistas_at)
  values (auth.uid(), now())
  on conflict (user_id) do update set
    comisiones_vistas_at = now(),
    updated_at = now();

  return jsonb_build_object('ok', true);
end $fn$;

revoke all on function public.marcar_comisiones_vistas() from public, anon;
grant execute on function public.marcar_comisiones_vistas() to authenticated;


-- ############################################################
-- ##  063_la_comision_no_cuelga_del_asiento.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 063 · La comisión no cuelga de la contabilidad
--
-- LO QUE PASÓ, PORQUE ES EL MOTIVO DE ESTA MIGRACIÓN
--
-- Primera prueba real del programa de socios. Se recomendó, el referido entró
-- por el enlace, se le activó el plan con 60.000 de importe... y el socio no
-- vio ninguna comisión.
--
-- No falló nada del programa. Falló otra cosa: la empresa que representaba a
-- Orden en `ajustes_orden` había sido borrada, y la clave foránea dejó ese
-- campo en null. Así que al cobrar no había dónde anotar el ingreso, la
-- función avisó «no hay una empresa de Orden elegida», y como la comisión
-- colgaba de que ese ingreso existiera, no nació.
--
-- Dicho de otro modo: un problema de contabilidad interna le borró la
-- comisión a una persona que sí trajo un cliente que sí pagó.
--
-- LA REGLA QUE CAMBIA
--
-- La señal de que entró plata NO es la fila del libro. Es que una persona
-- escribió un importe en el panel porque vio la transferencia. Eso es lo que
-- la comisión mira ahora: plan pago más importe mayor que cero.
--
-- Lo que NO cambia: sin importe no hay comisión, sigue siendo una sola por
-- negocio, y si el cobro se anula la que está por pagar se cae igual. El
-- movimiento se guarda cuando existe, y ahora puede quedar en null —la
-- columna ya lo permitía—.
--
-- Y de paso, «esta cuenta ya pagó» en `usar_codigo_referido` se mide igual:
-- por el importe cobrado y no por el asiento, que era la misma trampa.
-- ============================================================

-- ------------------------------------------------------------
-- 1. EL COBRO
-- ------------------------------------------------------------
create or replace function public.cambiar_plan_cuenta(
  p_empresa    uuid,
  p_plan       text,
  p_meses      integer default 1,
  p_nota       text default '',
  p_importe    numeric default null,
  p_vendedores integer default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_antes    public.suscripciones;
  v_fin      timestamptz;
  v_estado   text;
  v_orden    uuid;
  v_cliente  text;
  v_ingreso  uuid;
  v_aviso    text := null;
  v_tope     integer;
  v_personas integer;
  v_socio    uuid;
  v_pct      numeric;
  v_comision boolean := false;
begin
  if not public.es_superadmin() then
    raise exception 'Este panel es solo para la administración de Orden.' using errcode = '42501';
  end if;

  if p_plan not in ('gratis', 'pro', 'negocio') then
    raise exception 'Plan desconocido: %', p_plan using errcode = '22023';
  end if;

  if p_vendedores is not null and p_vendedores < -1 then
    raise exception 'El tope de vendedores no puede ser negativo.' using errcode = '22023';
  end if;

  select * into v_antes from public.suscripciones where empresa_id = p_empresa;
  if v_antes.empresa_id is null then
    raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
  end if;

  select nombre into v_cliente from public.empresas where id = p_empresa;

  if p_plan = 'gratis' then
    v_estado := 'vencida';
    v_fin := now();
    -- Cortar el servicio borra el trato: si vuelve, se negocia de nuevo.
    v_tope := null;
  else
    v_estado := 'activa';
    -- Si todavía le queda tiempo pago, se le suma; si no, arranca hoy.
    v_fin := greatest(coalesce(v_antes.periodo_fin, now()), now())
             + make_interval(months => greatest(1, coalesce(p_meses, 1)));
    v_tope := case
      when p_vendedores is null then v_antes.tope_vendedores  -- no se toca
      when p_vendedores = -1    then null                     -- volver al plan
      else p_vendedores
    end;
  end if;

  update public.suscripciones
  set plan = p_plan,
      estado = v_estado,
      periodo_inicio = case when p_plan = 'gratis' then periodo_inicio else now() end,
      periodo_fin = v_fin,
      tope_vendedores = v_tope,
      proveedor_pago = case when p_plan = 'gratis' then proveedor_pago else 'transferencia' end,
      updated_at = now()
  where empresa_id = p_empresa;

  perform set_config('orden.suscripcion_confiable', '1', true);
  update public.empresas
  set plan = case when p_plan = 'gratis' then 'gratis' else 'pro' end
  where id = p_empresa;
  perform set_config('orden.suscripcion_confiable', '0', true);

  -- ---- ¿le queda gente afuera del tope nuevo? ----
  --
  -- No se echa a nadie: bajar un número en un panel no puede sacarle el
  -- acceso a una persona que hoy está trabajando. Pero hay que decirlo, o
  -- el que lo bajó se entera cuando el cliente reclama.
  if v_tope is not null then
    select count(*)::int into v_personas from public.miembros where empresa_id = p_empresa;
    if v_personas > v_tope + 1 then
      v_aviso := 'Ojo: este negocio ya tiene ' || v_personas || ' personas y le habilitaste '
              || v_tope || ' vendedores (' || (v_tope + 1) || ' con el dueño). '
              || 'No se sacó a nadie, pero no va a poder sumar a nadie más.';
    end if;
  end if;

  -- ---- el cobro, como ingreso de Orden ----
  if p_plan <> 'gratis' and coalesce(p_importe, 0) > 0 then
    select empresa_id into v_orden from public.ajustes_orden where unica;

    if v_orden is null then
      v_aviso := coalesce(v_aviso || ' ', '')
              || 'No hay una empresa de Orden elegida, así que el cobro no se anotó en tus finanzas.';
    elsif v_orden = p_empresa then
      v_aviso := coalesce(v_aviso || ' ', '')
              || 'Esta ES tu empresa, así que no se anotó ningún ingreso.';
    else
      begin
        insert into public.movimientos (
          empresa_id, tipo, estado, fecha, descripcion, categoria,
          subtotal, descuento, monto, costo_total, metodo_pago, contraparte, creado_por
        ) values (
          v_orden, 'ingreso', 'activo', public.hoy_empresa(v_orden),
          'Suscripción ' || coalesce(v_cliente, 'cliente'), 'Suscripciones',
          p_importe, 0, p_importe, 0, 'transferencia',
          left(coalesce(v_cliente, ''), 80), auth.uid()
        )
        returning id into v_ingreso;
      exception when others then
        v_aviso := coalesce(v_aviso || ' ', '')
                || 'La cuenta se activó, pero el ingreso no se pudo anotar: ' || sqlerrm;
      end;
    end if;
  end if;

  -- ---- la comisión de quien trajo al cliente (060, corregida acá) ----
  -- Nace cuando se cobra, una sola vez por negocio, y eso lo garantiza el
  -- índice único de comisiones y no el acordarse.
  --
  -- Antes colgaba de que el ingreso se hubiera podido anotar, y eso costó
  -- una comisión de verdad: la empresa que representaba a Orden estaba
  -- borrada, el ingreso no se pudo escribir, y el socio se quedó sin nada
  -- por un problema de contabilidad que no tenía nada que ver con él.
  --
  -- La señal de que entró plata no es la fila del libro: es que una
  -- persona escribió un importe porque vio la transferencia. Eso es lo
  -- que se mira. El movimiento se guarda si existe, y puede ser null.
  if p_plan <> 'gratis' and coalesce(p_importe, 0) > 0 then
    select r.socio_id into v_socio
    from public.referidos r
    join public.socios s on s.id = r.socio_id
    where r.empresa_id = p_empresa and s.activo;

    if v_socio is not null then
      select coalesce(a.comision_porcentaje, 50) into v_pct
      from public.ajustes_orden a where a.unica;

      begin
        insert into public.comisiones (
          socio_id, empresa_id, movimiento_id, base, porcentaje, monto
        ) values (
          v_socio, p_empresa, v_ingreso, p_importe, coalesce(v_pct, 50),
          round(p_importe * coalesce(v_pct, 50) / 100)
        );
        v_comision := true;
      exception when unique_violation then
        -- Ya cobró por este negocio. Se paga una sola vez: el primer pago.
        null;
      end;
    end if;
  end if;

  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (auth.uid(), p_empresa, 'cambiar_plan', jsonb_build_object(
    'plan_antes', v_antes.plan, 'plan_despues', p_plan,
    'estado_antes', v_antes.estado, 'estado_despues', v_estado,
    'vence_antes', v_antes.periodo_fin, 'vence_despues', v_fin,
    'meses', greatest(1, coalesce(p_meses, 1)),
    'importe', p_importe,
    'tope_antes', v_antes.tope_vendedores,
    'tope_despues', v_tope,
    'ingreso_id', v_ingreso,
    'nota', left(coalesce(p_nota, ''), 300)
  ));

  return jsonb_build_object(
    'plan', p_plan, 'estado', v_estado, 'periodo_fin', v_fin,
    'tope_vendedores', v_tope,
    'personas_permitidas', public.tope_de_miembros(p_empresa),
    'ingreso_anotado', v_ingreso is not null,
    'comision_generada', v_comision,
    'aviso', v_aviso
  );
end $fn$;

-- ------------------------------------------------------------
-- 2. ENTRAR CON EL CÓDIGO DE ALGUIEN
-- ------------------------------------------------------------
create or replace function public.usar_codigo_referido(p_empresa uuid, p_codigo text)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_uid    uuid := auth.uid();
  v_socio  public.socios;
  v_creada timestamptz;
  v_ya     uuid;
begin
  if v_uid is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  -- Solo el dueño. Un vendedor no decide a nombre de quién queda el negocio
  -- donde trabaja.
  if not exists (
    select 1 from public.miembros m
    where m.empresa_id = p_empresa and m.user_id = v_uid and m.rol = 'propietario'
  ) then
    raise exception 'Solo el dueño de la cuenta puede usar un código.' using errcode = '42501';
  end if;

  select * into v_socio from public.socios
  where codigo = upper(trim(coalesce(p_codigo, '')));

  if v_socio.id is null then
    raise exception 'Ese código no existe. Revisalo con quien te lo pasó.' using errcode = '22023';
  end if;

  if not v_socio.activo then
    raise exception 'Ese código ya no está activo.' using errcode = '22023';
  end if;

  if v_socio.user_id = v_uid then
    raise exception 'Ese es tu propio código: no se gana comisión por uno mismo.'
      using errcode = '22023';
  end if;

  if v_socio.user_id is not null and exists (
    select 1 from public.miembros m
    where m.empresa_id = p_empresa and m.user_id = v_socio.user_id
  ) then
    raise exception 'Esa persona trabaja en este negocio: no corresponde comisión.'
      using errcode = '22023';
  end if;

  select socio_id into v_ya from public.referidos where empresa_id = p_empresa;
  if v_ya is not null then
    if v_ya = v_socio.id then
      return jsonb_build_object('ok', true, 'socio', v_socio.nombre, 'repetido', true);
    end if;
    raise exception 'Esta cuenta ya entró con otro código.' using errcode = '22023';
  end if;

  select created_at into v_creada from public.empresas where id = p_empresa;
  if v_creada is null then
    raise exception 'Esa cuenta no existe.' using errcode = '22023';
  end if;

  if v_creada < now() - interval '30 days' then
    raise exception 'El código es para cuentas nuevas, y esta ya tiene más de un mes.'
      using errcode = '22023';
  end if;

  -- Ya pagó: se mira el importe cobrado y no el ingreso anotado, por lo
  -- mismo que arriba. Que la contabilidad de Orden haya fallado no
  -- convierte a un cliente que ya paga en un cliente nuevo.
  if exists (
    select 1 from public.registro_admin r
    where r.empresa_id = p_empresa and r.accion = 'cambiar_plan'
      and coalesce(r.detalle->>'importe', '') ~ '^[0-9]+(\.[0-9]+)?$'
      and (r.detalle->>'importe')::numeric > 0
  ) then
    raise exception 'Esta cuenta ya pagó, así que el código no corresponde.'
      using errcode = '22023';
  end if;

  insert into public.referidos (empresa_id, socio_id, origen, nota, creado_por)
  values (p_empresa, v_socio.id, 'link', '', v_uid);

  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (v_uid, p_empresa, 'asignar_referido', jsonb_build_object(
    'socio_id', v_socio.id, 'socio', v_socio.nombre, 'codigo', v_socio.codigo,
    'origen', 'link'
  ));

  return jsonb_build_object('ok', true, 'socio', v_socio.nombre, 'repetido', false);
end $fn$;

revoke all on function public.usar_codigo_referido(uuid, text) from public, anon;
grant execute on function public.usar_codigo_referido(uuid, text) to authenticated;


-- ------------------------------------------------------------
-- 3. LAS COMISIONES QUE SE PERDIERON POR ESTO
--
--    Una, la de la prueba. Pero si no se recupera acá, hay que acordarse de
--    volver a activarle el plan al mismo cliente para que nazca —y eso le
--    suma un mes que no pagó—. Se arregla sola, ahora, con lo que ya quedó
--    escrito en el registro del panel.
--
--    Se toma el PRIMER cobro con importe de cada negocio traído que todavía
--    no tenga comisión. El primero y no el último: la comisión es del primer
--    pago, y si hubo dos, el segundo ya no le corresponde a nadie.
-- ------------------------------------------------------------
do $$
declare
  v_pct   numeric;
  v_hecho integer := 0;
  f       record;
begin
  select coalesce(comision_porcentaje, 50) into v_pct from public.ajustes_orden where unica;
  v_pct := coalesce(v_pct, 50);

  for f in
    select r.empresa_id, r.socio_id, c.importe, c.ingreso
    from public.referidos r
    cross join lateral (
      select (ra.detalle->>'importe')::numeric as importe,
             nullif(ra.detalle->>'ingreso_id', '')::uuid as ingreso
      from public.registro_admin ra
      where ra.empresa_id = r.empresa_id
        and ra.accion = 'cambiar_plan'
        and coalesce(ra.detalle->>'importe', '') ~ '^[0-9]+(\.[0-9]+)?$'
        and (ra.detalle->>'importe')::numeric > 0
      order by ra.created_at
      limit 1
    ) c
    where not exists (select 1 from public.comisiones x where x.empresa_id = r.empresa_id)
  loop
    insert into public.comisiones (
      socio_id, empresa_id, movimiento_id, base, porcentaje, monto, nota
    ) values (
      f.socio_id, f.empresa_id, f.ingreso, f.importe, v_pct,
      round(f.importe * v_pct / 100),
      'Recuperada: el cobro existió pero la comisión no se había generado.'
    )
    on conflict (empresa_id) do nothing;
    v_hecho := v_hecho + 1;
  end loop;

  raise notice 'Comisiones recuperadas: %', v_hecho;
end $$;


-- ############################################################
-- ##  064_datos_para_transferirte.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 064 · Los datos para transferirle, en su lugar
--
-- «Dónde te transferimos» era UNA línea de texto libre. El dueño escribió
-- «Banco Familiar, alias 0984158986» y quedó claro el problema: al momento de
-- transferir hay que leer esa frase y adivinar qué parte es el banco, cuál el
-- alias y a nombre de quién está la cuenta. Y falta el dato que todos los
-- bancos de acá piden igual: la cédula o el RUC del titular.
--
-- Cuatro campos, que son los que pide cualquier formulario de transferencia:
-- dónde, a nombre de quién, a qué cuenta y con qué documento.
--
-- `cobra_en` no se borra: es lo que ya escribieron los que cargaron algo, y
-- borrarlo sería perder el único dato que había para pagarles. Queda como
-- lo anterior, a la vista, hasta que completen los campos nuevos.
-- ============================================================

alter table public.socios
  add column if not exists banco     text not null default '' check (char_length(banco) <= 80),
  add column if not exists titular   text not null default '' check (char_length(titular) <= 120),
  add column if not exists cuenta    text not null default '' check (char_length(cuenta) <= 60),
  add column if not exists documento text not null default '' check (char_length(documento) <= 30);

comment on column public.socios.banco is 'Banco, financiera o billetera.';
comment on column public.socios.titular is 'A nombre de quién está la cuenta.';
comment on column public.socios.cuenta is 'Número de cuenta o alias.';
comment on column public.socios.documento is 'CI o RUC del titular: los bancos lo piden.';
comment on column public.socios.cobra_en is 'Texto libre viejo (anterior a la 064). Se conserva para no perder datos.';

-- ------------------------------------------------------------
-- 1. LO ESCRIBE EL SOCIO
--
--    Cuatro campos y ninguno obligatorio: alguien puede tener solo una
--    billetera, y pedirle un número de cuenta que no tiene lo dejaría sin
--    poder guardar nada.
--
--    La línea vieja se sigue armando con lo nuevo, porque hay pantallas que
--    muestran «cobra en …» de un vistazo y no tienen por qué saber de cuatro
--    campos.
-- ------------------------------------------------------------
drop function if exists public.guardar_donde_cobro(text);

create or replace function public.guardar_donde_cobro(
  p_banco     text default '',
  p_titular   text default '',
  p_cuenta    text default '',
  p_documento text default ''
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_uid   uuid := auth.uid();
  v_id    uuid;
  v_banco text := left(coalesce(trim(p_banco), ''), 80);
  v_tit   text := left(coalesce(trim(p_titular), ''), 120);
  v_cta   text := left(coalesce(trim(p_cuenta), ''), 60);
  v_doc   text := left(coalesce(trim(p_documento), ''), 30);
  v_linea text;
begin
  if v_uid is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  v_linea := left(trim(both ' ·' from concat_ws(' · ', nullif(v_banco, ''), nullif(v_cta, ''))), 200);

  update public.socios set
    banco      = v_banco,
    titular    = v_tit,
    cuenta     = v_cta,
    documento  = v_doc,
    cobra_en   = case when v_linea <> '' then v_linea else cobra_en end,
    updated_at = now()
  where user_id = v_uid
  returning id into v_id;

  if v_id is null then
    raise exception 'Todavía no pediste tu código de recomendación.' using errcode = '22023';
  end if;

  return jsonb_build_object('ok', true);
end $fn$;

revoke all on function public.guardar_donde_cobro(text, text, text, text) from public, anon;
grant execute on function public.guardar_donde_cobro(text, text, text, text) to authenticated;

-- ------------------------------------------------------------
-- 2. Y SE VEN DONDE HAY QUE PAGARLE
--
--    Las tres lecturas devuelven los cuatro campos. La administración no
--    tendría que entrar a «editar» para leer un número de cuenta: editar es
--    para cambiar, no para mirar.
-- ------------------------------------------------------------
create or replace function public.listar_socios(
  p_busqueda text default null,
  p_limite   integer default 200
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_res jsonb;
begin
  if not public.es_superadmin() then
    raise exception 'Esto es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(x order by x->>'nombre'), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'id',        s.id,
      'nombre',    s.nombre,
      'telefono',  s.telefono,
      'email',     s.email,
      'codigo',    s.codigo,
      'activo',    s.activo,
      'cobra_en',  s.cobra_en,
      'banco',     s.banco,
      'titular',   s.titular,
      'cuenta',    s.cuenta,
      'documento', s.documento,
      'notas',     s.notas,
      'tiene_cuenta', s.user_id is not null,
      'creado',    s.created_at,
      'traidos',   (select count(*) from public.referidos r where r.socio_id = s.id),
      'pagaron',   (select count(*) from public.comisiones c
                    where c.socio_id = s.id and c.estado <> 'anulada'),
      'por_pagar', coalesce((select sum(c.monto) from public.comisiones c
                             where c.socio_id = s.id and c.estado = 'por_pagar'), 0),
      'pagado',    coalesce((select sum(c.monto) from public.comisiones c
                             where c.socio_id = s.id and c.estado = 'pagada'), 0)
    ) as x
    from public.socios s
    where (
        p_busqueda is null
        or trim(p_busqueda) = ''
        or s.nombre ilike '%' || trim(p_busqueda) || '%'
        or s.codigo ilike '%' || trim(p_busqueda) || '%'
        or s.telefono ilike '%' || trim(p_busqueda) || '%'
        or s.email ilike '%' || trim(p_busqueda) || '%'
      )
    order by s.nombre
    limit greatest(1, least(coalesce(p_limite, 200), 500))
  ) t;

  return v_res;
end $fn$;

revoke all on function public.listar_socios(text, integer) from public, anon;
grant execute on function public.listar_socios(text, integer) to authenticated;

create or replace function public.listar_comisiones(
  p_estado text default null,
  p_socio  uuid default null,
  p_limite integer default 200
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_res jsonb;
begin
  if not public.es_superadmin() then
    raise exception 'Esto es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(x order by x->>'creado' desc), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'id',         c.id,
      'socio_id',   c.socio_id,
      'socio',      s.nombre,
      'telefono',   s.telefono,
      'cobra_en',   s.cobra_en,
      'banco',      s.banco,
      'titular',    s.titular,
      'cuenta',     s.cuenta,
      'documento',  s.documento,
      'empresa_id', c.empresa_id,
      'negocio',    coalesce(e.nombre, 'Negocio borrado'),
      'base',       c.base,
      'porcentaje', c.porcentaje,
      'monto',      c.monto,
      'estado',     c.estado,
      'creado',     c.created_at,
      'pagada_at',  c.pagada_at,
      'medio',      c.medio,
      'nota',       c.nota,
      -- estado es un enum: se compara como texto o revienta con el coalesce.
      'ingreso_anulado', coalesce(mv.estado::text, '') = 'anulado'
    ) as x
    from public.comisiones c
    join public.socios s on s.id = c.socio_id
    left join public.empresas e on e.id = c.empresa_id
    left join public.movimientos mv on mv.id = c.movimiento_id
    where (p_estado is null or trim(p_estado) = '' or c.estado = p_estado)
      and (p_socio is null or c.socio_id = p_socio)
    order by c.created_at desc
    limit greatest(1, least(coalesce(p_limite, 200), 500))
  ) t;

  return v_res;
end $fn$;

revoke all on function public.listar_comisiones(text, uuid, integer) from public, anon;
grant execute on function public.listar_comisiones(text, uuid, integer) to authenticated;

create or replace function public.mi_panel_socio()
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_uid   uuid := auth.uid();
  v_socio public.socios;
  v_lista jsonb;
begin
  if v_uid is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  select * into v_socio from public.socios where user_id = v_uid;

  if v_socio.id is null then
    return jsonb_build_object('tiene_codigo', false);
  end if;

  select coalesce(jsonb_agg(x order by x->>'desde' desc), '[]'::jsonb) into v_lista
  from (
    select jsonb_build_object(
      'negocio',  coalesce(e.nombre, 'Negocio borrado'),
      'desde',    r.created_at,
      'paga',     public.plan_efectivo_calculado(r.empresa_id) <> 'gratis',
      'plan',     public.plan_efectivo_calculado(r.empresa_id),
      'estado',   coalesce(c.estado, 'sin_pagar'),
      'monto',    coalesce(c.monto, 0),
      'cuando',   c.created_at,
      'pagada_at', c.pagada_at
    ) as x
    from public.referidos r
    left join public.empresas e on e.id = r.empresa_id
    left join public.comisiones c on c.empresa_id = r.empresa_id
    where r.socio_id = v_socio.id
  ) t;

  return jsonb_build_object(
    'tiene_codigo', true,
    'codigo',    v_socio.codigo,
    'nombre',    v_socio.nombre,
    'cobra_en',  v_socio.cobra_en,
    'banco',     v_socio.banco,
    'titular',   v_socio.titular,
    'cuenta',    v_socio.cuenta,
    'documento', v_socio.documento,
    'activo',    v_socio.activo,
    'traidos',   (select count(*) from public.referidos r where r.socio_id = v_socio.id),
    'pagaron',   (select count(*) from public.comisiones c
                  where c.socio_id = v_socio.id and c.estado <> 'anulada'),
    'por_pagar', coalesce((select sum(c.monto) from public.comisiones c
                           where c.socio_id = v_socio.id and c.estado = 'por_pagar'), 0),
    'pagado',    coalesce((select sum(c.monto) from public.comisiones c
                           where c.socio_id = v_socio.id and c.estado = 'pagada'), 0),
    'referidos', v_lista
  );
end $fn$;

revoke all on function public.mi_panel_socio() from public, anon;
grant execute on function public.mi_panel_socio() to authenticated;


-- ############################################################
-- ##  065_fiado_en_resumen_personal.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 065 · El fiado cobrado también es plata disponible, en la cuenta personal
--
-- EL AGUJERO
--
-- Desde la 054, «Me deben» existe también en la cuenta personal: le
-- prestaste plata a alguien, o te deben por lo que sea, y queda anotado
-- ahí. La 056 decidió, con razón, que cobrar un fiado no crea un ingreso
-- —esa plata ya había salido antes, y contarla de nuevo la duplicaría—, y
-- la 057 le sumó al CIERRE DEL DÍA dos números aparte para que esa plata
-- no desapareciera del resumen del negocio.
--
-- Pero `resumen_personal()` no se tocó desde la 030, antes de que el fiado
-- existiera. Y la cuenta personal no tiene Cierre del día (en el código,
-- PERSONAL.secciones['/cierre'] = false: esa pantalla es de un negocio, no
-- de alguien con sueldo). Entonces cobrar un fiado en una cuenta personal
-- no aparecía en NINGÚN lado: no sumaba a lo disponible, y no había una
-- sola línea que dijera qué había pasado con esa plata. Entraba de verdad
-- y el sistema no se enteraba.
--
-- LO QUE CAMBIA
--
-- `disponible` ahora también suma lo cobrado de fiado en este ciclo: es
-- plata real en el bolsillo, aunque no sea ganancia — la misma distinción
-- que ya vale para el negocio, acá aplicada al número del que depende una
-- decisión de gasto. Y el resumen devuelve dos campos nuevos para que la
-- persona vea de dónde salió ese número:
--
--   fiado_cobrado_en_el_ciclo → lo que cobró de fiados en este ciclo.
--   fiado_pendiente           → lo que todavía le deben, en total.
--
-- Idempotente. No toca datos existentes: solo cambia lo que la función
-- calcula a partir de ellos.
-- ============================================================

create or replace function public.resumen_personal(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_c            record;
  v_zona         text;
  v_hoy          date;
  v_entro        numeric := 0;
  v_salio        numeric := 0;
  v_cuotas       numeric := 0;
  v_fijos_falta  numeric := 0;
  v_ahorro_ciclo numeric := 0;
  v_ahorro_total numeric := 0;
  v_fiado_ciclo  numeric := 0;
  v_fiado_total  numeric := 0;
  v_dias         integer;
  v_plan         jsonb;
  v_sin_planear  numeric := 0;
  v_entradas     jsonb;
  v_salidas      jsonb;
  v_fondos       jsonb;
  v_de_donde     jsonb;
  v_esperado     numeric := 0;
  v_fijo_mes     numeric := 0;
  v_hubo_ingreso boolean := false;
  v_disponible   numeric;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'No tenés acceso a esta cuenta.' using errcode = '42501';
  end if;

  select zona_horaria into v_zona from public.empresas where id = p_empresa;
  v_hoy := (now() at time zone coalesce(v_zona, 'America/Asuncion'))::date;

  select * into v_c from public.ciclo_personal(p_empresa);

  select
    coalesce(sum(m.monto) filter (where m.tipo in ('ingreso', 'venta')), 0),
    coalesce(sum(m.monto) filter (where m.tipo = 'gasto'), 0),
    bool_or(m.tipo in ('ingreso', 'venta'))
  into v_entro, v_salio, v_hubo_ingreso
  from public.movimientos m
  where m.empresa_id = p_empresa
    and m.estado = 'activo'
    and m.fecha between v_c.desde and v_c.hasta;

  select coalesce(sum(d.monto_cuota), 0) into v_cuotas
  from public.deudas d
  where d.empresa_id = p_empresa
    and d.activa and d.saldo > 0
    and d.monto_cuota is not null
    and d.vence_el between v_hoy and v_c.hasta;

  select coalesce(sum(greatest(0, f.total - coalesce(g.gastado, 0))), 0)
  into v_fijos_falta
  from (
    select categoria, sum(importe) as total
    from public.gastos_fijos
    where empresa_id = p_empresa and activo
    group by categoria
  ) f
  left join lateral (
    select sum(m.monto) as gastado
    from public.movimientos m
    where m.empresa_id = p_empresa and m.estado = 'activo' and m.tipo = 'gasto'
      and m.categoria = f.categoria
      and m.fecha between v_c.desde and v_c.hasta
  ) g on true;

  select coalesce(sum(case when ma.tipo = 'aporte' then ma.monto else -ma.monto end), 0)
  into v_ahorro_ciclo
  from public.movimientos_ahorro ma
  where ma.empresa_id = p_empresa and ma.fecha between v_c.desde and v_c.hasta;

  select coalesce(sum(case when ma.tipo = 'aporte' then ma.monto else -ma.monto end), 0)
  into v_ahorro_total
  from public.movimientos_ahorro ma
  where ma.empresa_id = p_empresa;

  -- Lo cobrado de fiado en ESTE ciclo. `cobrar_fiado` (056) no crea
  -- movimiento a propósito, así que sin esto esa plata no aparecía en
  -- ningún cálculo.
  select coalesce(sum(f.monto) filter (where f.tipo = 'cobro'), 0)
  into v_fiado_ciclo
  from public.fiado f
  where f.empresa_id = p_empresa and f.fecha between v_c.desde and v_c.hasta;

  -- Lo que le deben en total, sumando a todos los que le deben. Mismo
  -- cálculo que `resumen_fiado()` (054), acá sin el desglose por persona
  -- porque este resumen ya tiene bastante.
  select coalesce(sum(case when f.tipo = 'fio' then f.monto else -f.monto end), 0)
  into v_fiado_total
  from public.fiado f
  where f.empresa_id = p_empresa;

  v_dias := greatest(1, (v_c.hasta - v_hoy) + 1);
  -- El fiado cobrado suma a lo disponible: es plata real en el bolsillo,
  -- aunque no haya sido «entro» (eso ya se explicó por qué no).
  v_disponible := v_entro - v_salio - v_cuotas - v_fijos_falta - v_ahorro_ciclo + v_fiado_ciclo;

  select
    coalesce(jsonb_agg(jsonb_build_object(
      'categoria', p.categoria,
      'planeado',  p.importe,
      'gastado',   coalesce(g.total, 0),
      'resta',     p.importe - coalesce(g.total, 0)
    ) order by p.categoria), '[]'::jsonb)
  into v_plan
  from public.presupuesto p
  left join lateral (
    select sum(m.monto) as total
    from public.movimientos m
    where m.empresa_id = p_empresa and m.estado = 'activo' and m.tipo = 'gasto'
      and m.categoria = p.categoria
      and m.fecha between v_c.desde and v_c.hasta
  ) g on true
  where p.empresa_id = p_empresa;

  select coalesce(sum(m.monto), 0) into v_sin_planear
  from public.movimientos m
  where m.empresa_id = p_empresa and m.estado = 'activo' and m.tipo = 'gasto'
    and m.fecha between v_c.desde and v_c.hasta
    and not exists (
      select 1 from public.presupuesto p
      where p.empresa_id = p_empresa and p.categoria = m.categoria);

  select
    coalesce(jsonb_agg(jsonb_build_object(
      'id', i.id, 'nombre', i.nombre, 'importe', i.importe,
      'dia_del_mes', i.dia_del_mes, 'principal', i.principal
    ) order by i.principal desc, i.importe desc), '[]'::jsonb),
    coalesce(sum(i.importe), 0)
  into v_entradas, v_esperado
  from public.ingresos_fijos i
  where i.empresa_id = p_empresa and i.activo;

  select
    coalesce(jsonb_agg(jsonb_build_object(
      'id', g.id, 'nombre', g.nombre, 'importe', g.importe,
      'categoria', g.categoria, 'dia_del_mes', g.dia_del_mes, 'notas', g.notas
    ) order by g.dia_del_mes nulls last, g.importe desc), '[]'::jsonb),
    coalesce(sum(g.importe), 0)
  into v_salidas, v_fijo_mes
  from public.gastos_fijos g
  where g.empresa_id = p_empresa and g.activo;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', a.id, 'nombre', a.nombre, 'meta', a.meta,
    'fecha_limite', a.fecha_limite,
    'saldo', s.saldo,
    'falta', case when a.meta is null then null
                  else greatest(0, a.meta - s.saldo) end,
    'dias_para_limite', case when a.fecha_limite is null then null
                             else (a.fecha_limite - v_hoy) end,
    'por_mes', case
                 when a.meta is null or a.fecha_limite is null then null
                 when a.meta - s.saldo <= 0 then 0
                 when a.fecha_limite < v_hoy then null
                 else round((a.meta - s.saldo)
                            / greatest(1, ceil((a.fecha_limite - v_hoy)::numeric / 30)), 2)
               end
  ) order by a.created_at), '[]'::jsonb)
  into v_fondos
  from public.ahorros a
  cross join lateral (select public.saldo_ahorro(a.id) as saldo) s
  where a.empresa_id = p_empresa and a.activo;

  select coalesce(jsonb_agg(x order by (x->>'monto')::numeric desc), '[]'::jsonb)
  into v_de_donde
  from (
    select jsonb_build_object('categoria', m.categoria, 'monto', sum(m.monto)) as x
    from public.movimientos m
    where m.empresa_id = p_empresa and m.estado = 'activo'
      and m.tipo in ('ingreso', 'venta')
      and m.fecha between v_c.desde and v_c.hasta
    group by m.categoria
  ) t;

  return jsonb_build_object(
    'desde', v_c.desde,
    'hasta', v_c.hasta,
    'dia_cobro', v_c.dia_cobro,
    'dias_restantes', v_dias,
    'entro', v_entro,
    'salio', v_salio,
    'cuotas_por_vencer', v_cuotas,
    'fijos_por_pagar', v_fijos_falta,
    'ahorrado_en_el_ciclo', v_ahorro_ciclo,
    'ahorro_total', v_ahorro_total,
    'fiado_cobrado_en_el_ciclo', v_fiado_ciclo,
    'fiado_pendiente', v_fiado_total,
    'disponible', v_disponible,
    'por_dia', round(v_disponible / v_dias, 2),
    'plan', v_plan,
    'gastado_sin_planear', v_sin_planear,
    'ingresos_fijos', v_entradas,
    'gastos_fijos', v_salidas,
    'ahorros', v_fondos,
    'de_donde_vino', v_de_donde,
    'esperado', v_esperado,
    'fijo_mensual', v_fijo_mes,
    'cobro_pendiente', v_esperado > 0 and not coalesce(v_hubo_ingreso, false)
  );
end $fn$;

revoke all on function public.resumen_personal(uuid) from public, anon;
grant execute on function public.resumen_personal(uuid) to authenticated;


-- ############################################################
-- ##  066_pedir_el_cobro.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 066 · El socio pide su cobro
--
-- LO QUE FALTABA
--
-- Desde la 060 la comisión nace sola cuando el referido paga, y desde la
-- 061 el socio la ve en su pantalla. Pero no había forma de PEDIRLA: la
-- plata figuraba como «te deben» y ahí se quedaba, esperando a que Matías
-- se acordara de mirar el panel. El socio no tenía ningún botón y nosotros
-- ningún aviso.
--
-- Eso es justo lo que mata un programa de referidos. Alguien trae un
-- cliente, ve su comisión en pantalla, no pasa nada durante dos semanas, y
-- no vuelve a recomendar nunca más.
--
-- CÓMO FUNCIONA
--
-- El socio toca «Pedir mi cobro» y se marcan sus comisiones por pagar con
-- la fecha del pedido. Eso dispara un aviso a la administración (push, en
-- la ruta que llama a esta función) y le deja al socio la promesa escrita:
-- se transfiere dentro de las 24 a 48 horas hábiles.
--
-- DOS GUARDAS QUE IMPORTAN
--
--   · SIN DATOS BANCARIOS NO SE PUEDE PEDIR. Pedir un cobro sin decir a
--     dónde transferir deja a la administración con un aviso que no puede
--     resolver, y al socio esperando una plata que nadie sabe mandar.
--   · NO SE PIDE DOS VECES. `solicitada_at` se escribe una sola vez por
--     comisión: quien toca el botón cinco veces no manda cinco avisos. La
--     función contesta que ya estaba pedido y cuándo, y la pantalla lo
--     dice.
--
-- Idempotente.
-- ============================================================

-- ------------------------------------------------------------
-- 1. CUÁNDO LO PIDIÓ
--
--    Una fecha y no un booleano, por lo mismo que `avisado_at` en la 043:
--    saber que pidió no sirve tanto como saber hace cuánto. «Pidió hace
--    tres días» es un reclamo; «pidió hace diez minutos» es una tarea.
-- ------------------------------------------------------------
alter table public.comisiones
  add column if not exists solicitada_at timestamptz;

comment on column public.comisiones.solicitada_at is
  'Cuándo el socio pidió que se le transfiera. Null = todavía no lo pidió.';

create index if not exists comisiones_solicitadas_idx
  on public.comisiones (solicitada_at desc)
  where estado = 'por_pagar' and solicitada_at is not null;

-- ------------------------------------------------------------
-- 2. PEDIR EL COBRO
--
--    La llama el propio socio, con su sesión. No recibe a quién pagarle:
--    se resuelve de `auth.uid()`, así que nadie puede pedir el cobro de
--    otro por más que arme el pedido a mano.
-- ------------------------------------------------------------
create or replace function public.solicitar_cobro()
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_uid     uuid := auth.uid();
  v_socio   public.socios;
  v_pendientes integer;
  v_nuevas  integer;
  v_total   numeric;
  v_desde   timestamptz;
begin
  if v_uid is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  select * into v_socio from public.socios where user_id = v_uid;
  if v_socio.id is null then
    raise exception 'Todavía no pediste tu código de recomendación.' using errcode = '22023';
  end if;

  if not v_socio.activo then
    raise exception 'Tu código está pausado. Escribinos y lo vemos.' using errcode = '42501';
  end if;

  select count(*)::int, coalesce(sum(monto), 0)
  into v_pendientes, v_total
  from public.comisiones
  where socio_id = v_socio.id and estado = 'por_pagar';

  if v_pendientes = 0 then
    raise exception 'Todavía no tenés nada por cobrar.' using errcode = '22023';
  end if;

  -- Sin saber a dónde transferir, el pedido no se puede resolver. Se frena
  -- acá y no en la pantalla: la pantalla puede cambiar, esto no.
  if coalesce(nullif(trim(v_socio.cuenta), ''), nullif(trim(v_socio.cobra_en), '')) is null then
    raise exception 'Antes de pedir el cobro, completá dónde te transferimos.'
      using errcode = '22023';
  end if;

  -- Solo las que todavía no pidió. Tocar el botón de nuevo no vuelve a
  -- avisar: quien llama mira `nuevas` para decidir si manda el push.
  update public.comisiones
  set solicitada_at = now()
  where socio_id = v_socio.id and estado = 'por_pagar' and solicitada_at is null;

  get diagnostics v_nuevas = row_count;

  select min(solicitada_at) into v_desde
  from public.comisiones
  where socio_id = v_socio.id and estado = 'por_pagar' and solicitada_at is not null;

  return jsonb_build_object(
    'ok', true,
    'socio', v_socio.nombre,
    'socio_id', v_socio.id,
    'comisiones', v_pendientes,
    'total', v_total,
    'nuevas', v_nuevas,
    -- true = ya lo había pedido antes y no hay que volver a avisar.
    'ya_estaba', v_nuevas = 0,
    'pedido_el', v_desde,
    'donde', coalesce(nullif(trim(v_socio.cuenta), ''), v_socio.cobra_en)
  );
end $fn$;

revoke all on function public.solicitar_cobro() from public, anon;
grant execute on function public.solicitar_cobro() to authenticated;

-- ------------------------------------------------------------
-- 3. QUE EL SOCIO VEA QUE YA LO PIDIÓ
--
--    Redefine `mi_panel_socio()` de la 064 sumando dos campos. Sin esto, el
--    socio toca el botón, recarga la pantalla y vuelve a ver el botón como
--    si no hubiera pasado nada — que es exactamente la sensación que este
--    cambio venía a arreglar.
-- ------------------------------------------------------------
create or replace function public.mi_panel_socio()
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_uid   uuid := auth.uid();
  v_socio public.socios;
  v_lista jsonb;
  v_pedido timestamptz;
begin
  if v_uid is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  select * into v_socio from public.socios where user_id = v_uid;

  if v_socio.id is null then
    return jsonb_build_object('tiene_codigo', false);
  end if;

  select coalesce(jsonb_agg(x order by x->>'desde' desc), '[]'::jsonb) into v_lista
  from (
    select jsonb_build_object(
      'negocio',  coalesce(e.nombre, 'Negocio borrado'),
      'desde',    r.created_at,
      'paga',     public.plan_efectivo_calculado(r.empresa_id) <> 'gratis',
      'plan',     public.plan_efectivo_calculado(r.empresa_id),
      'estado',   coalesce(c.estado, 'sin_pagar'),
      'monto',    coalesce(c.monto, 0),
      'cuando',   c.created_at,
      'pagada_at', c.pagada_at
    ) as x
    from public.referidos r
    left join public.empresas e on e.id = r.empresa_id
    left join public.comisiones c on c.empresa_id = r.empresa_id
    where r.socio_id = v_socio.id
  ) t;

  -- El pedido más viejo que sigue sin pagarse: es el que cuenta para saber
  -- hace cuánto está esperando.
  select min(solicitada_at) into v_pedido
  from public.comisiones
  where socio_id = v_socio.id and estado = 'por_pagar' and solicitada_at is not null;

  return jsonb_build_object(
    'tiene_codigo', true,
    'codigo',    v_socio.codigo,
    'nombre',    v_socio.nombre,
    'cobra_en',  v_socio.cobra_en,
    'banco',     v_socio.banco,
    'titular',   v_socio.titular,
    'cuenta',    v_socio.cuenta,
    'documento', v_socio.documento,
    'activo',    v_socio.activo,
    'traidos',   (select count(*) from public.referidos r where r.socio_id = v_socio.id),
    'pagaron',   (select count(*) from public.comisiones c
                  where c.socio_id = v_socio.id and c.estado <> 'anulada'),
    'por_pagar', coalesce((select sum(c.monto) from public.comisiones c
                           where c.socio_id = v_socio.id and c.estado = 'por_pagar'), 0),
    'pagado',    coalesce((select sum(c.monto) from public.comisiones c
                           where c.socio_id = v_socio.id and c.estado = 'pagada'), 0),
    'cobro_pedido_el', v_pedido,
    'referidos', v_lista
  );
end $fn$;

revoke all on function public.mi_panel_socio() from public, anon;
grant execute on function public.mi_panel_socio() to authenticated;

-- ------------------------------------------------------------
-- 4. Y QUE LA ADMINISTRACIÓN VEA QUIÉN LO PIDIÓ
--
--    Redefine `listar_comisiones()` de la 064 sumando `solicitada_at`. El
--    push avisa una vez; el panel es donde se trabaja, y sin este dato no
--    hay forma de saber a quién le urge.
-- ------------------------------------------------------------
create or replace function public.listar_comisiones(
  p_estado text default null,
  p_socio  uuid default null,
  p_limite integer default 200
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_res jsonb;
begin
  if not public.es_superadmin() then
    raise exception 'Esto es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(x order by x->>'creado' desc), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'id',         c.id,
      'socio_id',   c.socio_id,
      'socio',      s.nombre,
      'telefono',   s.telefono,
      'cobra_en',   s.cobra_en,
      'banco',      s.banco,
      'titular',    s.titular,
      'cuenta',     s.cuenta,
      'documento',  s.documento,
      'empresa_id', c.empresa_id,
      'negocio',    coalesce(e.nombre, 'Negocio borrado'),
      'base',       c.base,
      'porcentaje', c.porcentaje,
      'monto',      c.monto,
      'estado',     c.estado,
      'creado',     c.created_at,
      'pagada_at',  c.pagada_at,
      'solicitada_at', c.solicitada_at,
      'medio',      c.medio,
      'nota',       c.nota,
      'ingreso_anulado', coalesce(mv.estado::text, '') = 'anulado'
    ) as x
    from public.comisiones c
    join public.socios s on s.id = c.socio_id
    left join public.empresas e on e.id = c.empresa_id
    left join public.movimientos mv on mv.id = c.movimiento_id
    where (p_estado is null or trim(p_estado) = '' or c.estado = p_estado)
      and (p_socio is null or c.socio_id = p_socio)
    order by c.created_at desc
    limit greatest(1, least(coalesce(p_limite, 200), 500))
  ) t;

  return v_res;
end $fn$;

revoke all on function public.listar_comisiones(text, uuid, integer) from public, anon;
grant execute on function public.listar_comisiones(text, uuid, integer) to authenticated;

-- ------------------------------------------------------------
-- 5. A QUIÉN AVISARLE
--
--    La ruta que manda el push necesita los usuarios de la administración.
--    `superadmins` solo deja que cada uno se vea a sí mismo (016), así que
--    hace falta esta función para que el servidor los lea a todos.
--
--    Solo `service_role`: es la lista de quiénes administran Orden, y no
--    tiene por qué salir hacia ningún navegador.
-- ------------------------------------------------------------
create or replace function public.usuarios_de_la_administracion()
returns jsonb language sql stable security definer set search_path = public as $fn$
  select coalesce(jsonb_agg(s.usuario_id), '[]'::jsonb) from public.superadmins s;
$fn$;

revoke all on function public.usuarios_de_la_administracion() from public, anon, authenticated;
grant execute on function public.usuarios_de_la_administracion() to service_role;


-- ############################################################
-- ##  067_borrar_un_socio.sql
-- ############################################################

-- ============================================================
-- 067 · BORRAR UN SOCIO
--
-- Hasta ahora un socio se podía crear y desactivar, pero nunca sacar. En
-- la práctica quedó a la vista el 2026-09-16: había una fila de alguien
-- cuya cuenta ya no existía, no servía para nada y no se podía quitar. La
-- única salida a mano era desactivarlo —que es otra cosa: desactivado
-- sigue en la lista, solo que no suma negocios nuevos— así que la lista
-- se iba a ir llenando de gente que ya no está.
--
-- QUÉ NO SE BORRA
--
-- `referidos.socio_id` y `comisiones.socio_id` son `on delete restrict`
-- (060), o sea que la base ya frenaba el borrado. Eso está bien y no se
-- toca: lo que faltaba era decirlo con palabras en vez de un error de
-- llave foránea.
--
--   · Con comisiones anotadas NO se borra, ni pagadas ni anuladas. Una
--     comisión es plata que se movió; sacar al socio dejaría el historial
--     de Orden hablando de alguien que no existe.
--   · Con negocios traídos NO se borra. Ese vínculo es lo que hace nacer
--     la comisión cuando el cliente paga: borrarlo en silencio sería
--     regalarse a sí mismo la comisión del mes que viene. Primero hay que
--     sacarle el referido a cada cuenta, una por una y a conciencia.
--
-- Queda entonces para lo que de verdad sobra: el socio cargado por error,
-- el que se probó una vez, el que nunca trajo a nadie.
--
-- SE ESCRIBE EL NOMBRE
--
-- Igual que `borrar_cuenta` (022): hay que escribir el nombre exacto. Es
-- la misma idea de siempre —que borrar cueste un segundo más que tocar un
-- botón— y de paso obliga a mirar a quién se está borrando.
-- ============================================================

create or replace function public.borrar_socio(
  p_socio       uuid,
  p_confirmacion text default ''
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_socio      public.socios;
  v_traidos    integer;
  v_comisiones integer;
begin
  if not public.es_superadmin() then
    raise exception 'Esto es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select * into v_socio from public.socios where id = p_socio;
  if v_socio.id is null then
    raise exception 'Ese socio no existe.' using errcode = 'P0002';
  end if;

  if trim(coalesce(p_confirmacion, '')) <> v_socio.nombre then
    raise exception 'Para borrar hay que escribir el nombre exacto: %', v_socio.nombre
      using errcode = '22023';
  end if;

  select count(*) into v_traidos    from public.referidos  where socio_id = p_socio;
  select count(*) into v_comisiones from public.comisiones where socio_id = p_socio;

  -- Las dos puertas, en orden de gravedad. Se cuentan antes de intentar el
  -- delete para poder decir cuántos son: «tiene 3 cuentas anotadas» ayuda
  -- mucho más que «no se puede».
  if v_comisiones > 0 then
    raise exception
      'Tiene % comisión(es) en el historial de Orden, así que no se puede borrar. Si ya no trabaja con nosotros, desactivalo: desactivado no recibe negocios nuevos y el historial queda entero.',
      v_comisiones using errcode = '22023';
  end if;

  if v_traidos > 0 then
    raise exception
      'Trajo % cuenta(s). Sacale el referido a esas cuentas primero, desde la ficha de cada una, y después borralo.',
      v_traidos using errcode = '22023';
  end if;

  -- Constancia antes de borrar: después la fila ya no existe y el nombre
  -- se pierde. Esto es lo único que va a quedar de este socio.
  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (auth.uid(), null, 'borrar_socio', jsonb_build_object(
    'socio_id', v_socio.id,
    'nombre',   v_socio.nombre,
    'codigo',   v_socio.codigo,
    'email',    v_socio.email,
    'tenia_cuenta', v_socio.user_id is not null
  ));

  delete from public.socios where id = p_socio;

  return jsonb_build_object('ok', true, 'nombre', v_socio.nombre);
end $fn$;

revoke all on function public.borrar_socio(uuid, text) from public, anon;
grant execute on function public.borrar_socio(uuid, text) to authenticated;


-- ############################################################
-- ##  068_el_codigo_no_se_pierde.sql
-- ############################################################

-- ============================================================
-- 068 · EL CÓDIGO DEL ENLACE NO SE PIERDE EN SILENCIO
--
-- LO QUE PASÓ (2026-09-16)
--
-- Matías había desactivado su propio socio a la mañana: era la única forma
-- de sacarlo de la lista antes de que existiera borrar (067). A la tarde
-- alguien entró con su enlace, creó la cuenta y pagó. Resultado:
--
--   1. `usar_codigo_referido` rechazó el código —«Ese código ya no está
--      activo»—, que es exactamente lo que tiene que hacer con uno pausado.
--   2. La pantalla borró el código del navegador ANTES de intentar usarlo,
--      y el rechazo no se guardó en ningún lado. `aplicarRef` además
--      esperaba una excepción, y supabase-js no tira: devuelve `{ error }`.
--      No quedó ni un rastro de que esa cuenta había llegado por un enlace.
--   3. Al cobrarle, como no había referido, no nació ninguna comisión.
--   4. Al querer anotarlo a mano después, la regla del grupo 4 de las
--      pruebas —anotar tarde no inventa comisiones viejas— dejó al socio
--      sin la comisión del primer pago, que era suya.
--
-- La regla del punto 4 está bien y NO se toca: si la administración le
-- atribuye a alguien un cliente viejo que nunca usó su enlace, no le
-- corresponde lo que ese cliente ya pagó. Lo que faltaba era poder probar
-- el otro caso: la cuenta SÍ entró con ese código, antes de pagar, y se
-- perdió en el camino.
--
-- LO QUE CAMBIA
--
--   · `codigos_rechazados`: cuando el código del enlace se rechaza al crear
--     la cuenta, queda anotado con el motivo. Una fila por negocio.
--   · `listar_codigos_rechazados()`: el panel de administración los ve en
--     la ficha de cada cuenta, con el motivo y a quién pertenecía.
--   · `asignar_referido()`: si el código que se anota es el mismo con el
--     que la cuenta intentó entrar, se anota como que vino por el enlace y
--     la comisión sale del PRIMER pago, como si nunca se hubiera perdido.
--     Si no coincide, todo sigue exactamente como antes.
--   · De paso, «ya pagó N veces» se cuenta por el importe y no por el
--     asiento contable, igual que hace `usar_codigo_referido` desde la 063.
--     Con la empresa de Orden sin elegir, el asiento no existe aunque el
--     cliente haya pagado, y el aviso no aparecía.
-- ============================================================

create table if not exists public.codigos_rechazados (
  empresa_id    uuid primary key references public.empresas (id) on delete cascade,
  codigo        text not null,
  motivo        text not null default '',
  intentado_por uuid references auth.users (id) on delete set null,
  intentado_at  timestamptz not null default now()
);

alter table public.codigos_rechazados enable row level security;
revoke all on public.codigos_rechazados from anon, authenticated;

-- ------------------------------------------------------------
-- 1. ANOTAR EL RECHAZO
--
--    Lo llama la pantalla de registro cuando `usar_codigo_referido` dice
--    que no. Solo el dueño de la cuenta, y solo si la cuenta todavía no
--    tiene a nadie anotado: una vez que hay referido, un rechazo posterior
--    es ruido.
--
--    El motivo lo manda el navegador, así que no se le cree para nada más
--    que para mostrárselo a la administración. Nada se decide con él.
-- ------------------------------------------------------------
create or replace function public.guardar_codigo_rechazado(
  p_empresa uuid,
  p_codigo  text,
  p_motivo  text default ''
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_uid    uuid := auth.uid();
  v_codigo text := left(upper(trim(coalesce(p_codigo, ''))), 12);
begin
  if v_uid is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.miembros m
    where m.empresa_id = p_empresa and m.user_id = v_uid and m.rol = 'propietario'
  ) then
    raise exception 'Solo el dueño de la cuenta puede usar un código.' using errcode = '42501';
  end if;

  if v_codigo = '' or exists (select 1 from public.referidos where empresa_id = p_empresa) then
    return jsonb_build_object('ok', true, 'guardado', false);
  end if;

  -- Se queda el primero: es el enlace con el que la persona llegó. Si
  -- después prueba otro código a mano, el que importa sigue siendo aquel.
  insert into public.codigos_rechazados (empresa_id, codigo, motivo, intentado_por)
  values (p_empresa, v_codigo, left(coalesce(p_motivo, ''), 200), v_uid)
  on conflict (empresa_id) do nothing;

  return jsonb_build_object('ok', true, 'guardado', true);
end $fn$;

revoke all on function public.guardar_codigo_rechazado(uuid, text, text) from public, anon;
grant execute on function public.guardar_codigo_rechazado(uuid, text, text) to authenticated;

-- ------------------------------------------------------------
-- 2. QUE LA ADMINISTRACIÓN LOS VEA
-- ------------------------------------------------------------
create or replace function public.listar_codigos_rechazados()
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
begin
  if not public.es_superadmin() then
    raise exception 'Esto es solo para la administración de Orden.' using errcode = '42501';
  end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'empresa_id',   c.empresa_id,
      'codigo',       c.codigo,
      'motivo',       c.motivo,
      'intentado_at', c.intentado_at,
      'socio_id',     s.id,
      'socio',        s.nombre,
      'socio_activo', s.activo
    ) order by c.intentado_at desc)
    from public.codigos_rechazados c
    left join public.socios s on s.codigo = c.codigo
    -- Si ya se anotó a alguien, el rechazo ya no es asunto de nadie.
    where not exists (select 1 from public.referidos r where r.empresa_id = c.empresa_id)
  ), '[]'::jsonb);
end $fn$;

revoke all on function public.listar_codigos_rechazados() from public, anon;
grant execute on function public.listar_codigos_rechazados() to authenticated;

-- ------------------------------------------------------------
-- 3. ANOTARLO A MANO, SABIENDO SI VINO POR EL ENLACE
-- ------------------------------------------------------------
create or replace function public.asignar_referido(
  p_empresa uuid,
  p_codigo  text,
  p_nota    text default ''
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_socio      public.socios;
  v_ya         uuid;
  v_pagos      integer;
  v_aviso      text := null;
  v_rechazo    public.codigos_rechazados;
  v_por_enlace boolean := false;
  v_primero    record;
  v_pct        numeric;
  v_comision   boolean := false;
begin
  if not public.es_superadmin() then
    raise exception 'Esto es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select * into v_socio from public.socios
  where codigo = upper(trim(coalesce(p_codigo, '')));

  if v_socio.id is null then
    raise exception 'No hay ningún socio con ese código.' using errcode = '22023';
  end if;

  if not v_socio.activo then
    raise exception '% está desactivado como socio. Activalo en «Socios» y volvé a anotarlo.',
      v_socio.nombre using errcode = '22023';
  end if;

  if not exists (select 1 from public.empresas where id = p_empresa) then
    raise exception 'Ese negocio no existe.' using errcode = '22023';
  end if;

  if v_socio.user_id is not null and exists (
    select 1 from public.miembros m
    where m.empresa_id = p_empresa and m.user_id = v_socio.user_id
  ) then
    raise exception
      '% trabaja en ese negocio: no se cobra comisión por traerse a uno mismo.',
      v_socio.nombre using errcode = '22023';
  end if;

  select socio_id into v_ya from public.referidos where empresa_id = p_empresa;

  if v_ya is not null then
    if v_ya = v_socio.id then
      return jsonb_build_object(
        'ok', true, 'socio', v_socio.nombre,
        'aviso', 'Ya estaba anotado a nombre de ' || v_socio.nombre || '.'
      );
    end if;
    raise exception
      'Ese negocio ya está anotado a nombre de %. Se cuenta una sola vez y no se cambia.',
      coalesce((select nombre from public.socios where id = v_ya), 'otra persona')
      using errcode = '22023';
  end if;

  -- ¿Esta cuenta intentó entrar con ESTE código y se lo rechazaron?
  select * into v_rechazo from public.codigos_rechazados where empresa_id = p_empresa;
  v_por_enlace := v_rechazo.empresa_id is not null and v_rechazo.codigo = v_socio.codigo;

  -- «Ya pagó» se mide por el importe, no por el asiento (ver arriba).
  select count(*)::int into v_pagos
  from public.registro_admin r
  where r.empresa_id = p_empresa
    and r.accion = 'cambiar_plan'
    and coalesce(r.detalle->>'importe', '') ~ '^[0-9]+(\.[0-9]+)?$'
    and (r.detalle->>'importe')::numeric > 0;

  insert into public.referidos (empresa_id, socio_id, origen, nota, creado_por)
  values (
    p_empresa, v_socio.id,
    case when v_por_enlace then 'link' else 'a_mano' end,
    left(coalesce(p_nota, ''), 300), auth.uid()
  );

  if v_por_enlace and v_pagos > 0 then
    -- Entró con el enlace antes de pagar: la comisión del primer pago es
    -- suya, igual que si el código no se hubiera perdido. El primero y no
    -- el último, por la misma razón que en la 063.
    select (ra.detalle->>'importe')::numeric as importe,
           nullif(ra.detalle->>'ingreso_id', '')::uuid as ingreso,
           ra.created_at
    into v_primero
    from public.registro_admin ra
    where ra.empresa_id = p_empresa
      and ra.accion = 'cambiar_plan'
      and coalesce(ra.detalle->>'importe', '') ~ '^[0-9]+(\.[0-9]+)?$'
      and (ra.detalle->>'importe')::numeric > 0
    order by ra.created_at
    limit 1;

    select coalesce(a.comision_porcentaje, 50) into v_pct from public.ajustes_orden a where a.unica;
    v_pct := coalesce(v_pct, 50);

    begin
      insert into public.comisiones (
        socio_id, empresa_id, movimiento_id, base, porcentaje, monto, nota
      ) values (
        v_socio.id, p_empresa, v_primero.ingreso, v_primero.importe, v_pct,
        round(v_primero.importe * v_pct / 100),
        'Entró con el enlace el ' || to_char(v_rechazo.intentado_at at time zone 'America/Asuncion', 'DD/MM/YYYY')
          || ', pero el código fue rechazado (' || coalesce(nullif(v_rechazo.motivo, ''), 'sin motivo') || ') y se anotó después.'
      );
      v_comision := true;
      v_aviso := 'Entró con este código y se había perdido. Se generó la comisión por su primer pago.';
    exception when unique_violation then
      v_aviso := 'Entró con este código y se había perdido. Ya tenía una comisión, así que no se generó otra.';
    end;
  elsif v_por_enlace then
    v_aviso := 'Entró con este código y se había perdido. Cuando pague, la comisión sale sola.';
  elsif v_pagos > 0 then
    v_aviso := 'Ojo: este negocio ya pagó ' || v_pagos
            || (case when v_pagos = 1 then ' vez' else ' veces' end)
            || ' antes de anotarlo. La comisión no se genera por esos pagos, sino con el próximo cobro. Revisá el monto antes de pagarla.';
  end if;

  -- Resuelto: el rechazo deja de figurar.
  delete from public.codigos_rechazados where empresa_id = p_empresa;

  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (auth.uid(), p_empresa, 'asignar_referido', jsonb_build_object(
    'socio_id', v_socio.id, 'socio', v_socio.nombre, 'codigo', v_socio.codigo,
    'pagos_previos', v_pagos, 'por_enlace', v_por_enlace, 'comision_generada', v_comision
  ));

  return jsonb_build_object(
    'ok', true, 'socio', v_socio.nombre, 'aviso', v_aviso,
    'por_enlace', v_por_enlace, 'comision_generada', v_comision
  );
end $fn$;

revoke all on function public.asignar_referido(uuid, text, text) from public, anon;
grant execute on function public.asignar_referido(uuid, text, text) to authenticated;


-- ############################################################
-- ##  069_el_candado_dice_la_verdad.sql
-- ############################################################

-- ============================================================
-- 069 · EL MENSAJE DE CUENTA VENCIDA DICE LO QUE PASA DE VERDAD
--
-- `exigir_cuenta_activa` (018) frena cualquier escritura de una cuenta con
-- la prueba o el plan vencidos, y lo explicaba así:
--
--   «Se te terminó la prueba. Podés seguir viendo todo y bajando tu Excel,
--    pero para cargar hay que activar el plan.»
--
-- Era cierto cuando se escribió: la 018 decidió a propósito que una cuenta
-- vencida siguiera mirando. El 2026-09-15 Matías lo decidió al revés —vencida
-- la cuenta, Orden se cierra entero hasta que se pague (ver CandadoCuenta)—,
-- y este mensaje quedó prometiendo algo que ya no existe.
--
-- Solo cambia el texto. La regla —qué se frena y qué no— es exactamente la
-- misma de la 018.
-- ============================================================

create or replace function public.exigir_cuenta_activa()
returns trigger language plpgsql security definer set search_path = public as $fn$
begin
  if auth.uid() is null then
    return new;
  end if;

  if not public.puede_cargar(new.empresa_id) then
    raise exception 'Se te terminó la prueba. Para seguir usando Orden hace falta activar tu plan.'
      using errcode = '42501';
  end if;

  return new;
end $fn$;

revoke all on function public.exigir_cuenta_activa() from public, anon, authenticated;


-- ############################################################
-- ##  070_saldo_y_retiros.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 070 · El socio tiene un saldo y retira lo que quiere
--
-- LO QUE CAMBIA
--
-- Hasta la 066 el socio pedía «todo lo pendiente» de una: cada comisión era
-- una unidad y se pagaba entera. Matías lo pidió distinto (16/09/2026):
--
--   «Un usuario tiene un millón de saldo, decide retirar quinientos mil, eso
--    es lo que se le transfiere, y queda el resto de su saldo.»
--
-- Y con un mínimo: menos de Gs. 120.000 no se retira, porque transferir de a
-- poco cuesta más en tiempo que lo que se paga.
--
-- EL MODELO
--
--   · Las comisiones siguen naciendo igual (060) y siguen siendo una por
--     negocio. Mientras están «por_pagar», suman al saldo.
--   · Un RETIRO es un pedido de plata contra ese saldo: tiene monto, estado
--     (pedido, pagado, rechazado) y la foto de a dónde había que transferir
--     en el momento de pedirlo.
--   · SALDO = comisiones por_pagar − retiros pedidos o pagados.
--
--   Un retiro pedido ya descuenta: si no, alguien con un millón podría pedir
--   un millón dos veces antes de que nadie pague la primera. Si se rechaza,
--   vuelve solo al saldo, porque deja de contar.
--
--   Las comisiones marcadas «pagada» antes de esto (pago directo, 060) no
--   entran en el saldo: esa plata ya se transfirió.
--
-- UN PEDIDO A LA VEZ
--
-- Un índice único parcial: mientras hay un retiro pedido, no se puede pedir
-- otro. Para la administración, una sola transferencia pendiente por persona
-- es algo que se resuelve; tres pedidos chicos del mismo socio es desorden.
--
-- Idempotente.
-- ============================================================

-- ------------------------------------------------------------
-- 1. EL MÍNIMO, EN UN SOLO LUGAR
-- ------------------------------------------------------------
alter table public.ajustes_orden
  add column if not exists retiro_minimo numeric(14,2) not null default 120000;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'ajustes_orden_retiro_minimo') then
    alter table public.ajustes_orden
      add constraint ajustes_orden_retiro_minimo check (retiro_minimo >= 0);
  end if;
end $$;

-- ------------------------------------------------------------
-- 2. LOS RETIROS
-- ------------------------------------------------------------
create table if not exists public.retiros (
  id           uuid primary key default gen_random_uuid(),
  socio_id     uuid not null references public.socios (id) on delete restrict,
  monto        numeric(14,2) not null check (monto > 0),
  estado       text not null default 'pedido' check (estado in ('pedido', 'pagado', 'rechazado')),
  pedido_at    timestamptz not null default now(),
  resuelto_at  timestamptz,
  -- A dónde había que transferir cuando lo pidió. Si después cambia sus
  -- datos, este pedido sigue diciendo a qué cuenta se prometió.
  banco        text not null default '',
  titular      text not null default '',
  cuenta       text not null default '',
  documento    text not null default '',
  medio        text not null default '' check (char_length(medio) <= 60),
  nota         text not null default '' check (char_length(nota) <= 300),
  -- El gasto de Orden al pagarlo, como en la 060.
  gasto_id     uuid references public.movimientos (id) on delete set null,
  resuelto_por uuid references auth.users (id) on delete set null,
  created_at   timestamptz not null default now()
);

create unique index if not exists retiros_uno_pedido_por_socio
  on public.retiros (socio_id) where estado = 'pedido';

create index if not exists retiros_estado_idx on public.retiros (estado, pedido_at desc);

alter table public.retiros enable row level security;
revoke all on public.retiros from anon, authenticated;

-- ------------------------------------------------------------
-- 3. DOS AYUDAS: EL SALDO Y LA PLATA ESCRITA
-- ------------------------------------------------------------
create or replace function public.saldo_socio(p_socio uuid)
returns numeric language sql stable security definer set search_path = public as $fn$
  select coalesce((select sum(monto) from public.comisiones
                    where socio_id = p_socio and estado = 'por_pagar'), 0)
       - coalesce((select sum(monto) from public.retiros
                    where socio_id = p_socio and estado in ('pedido', 'pagado')), 0);
$fn$;

revoke all on function public.saldo_socio(uuid) from public, anon, authenticated;

-- «Gs. 120.000», con punto de miles como se escribe acá. La coma de
-- to_char es fija (no depende del idioma del servidor) y se cambia por punto.
create or replace function public.guaranies(p numeric)
returns text language sql immutable set search_path = public as $fn$
  select 'Gs. ' || replace(to_char(round(coalesce(p, 0)), 'FM999,999,999,990'), ',', '.');
$fn$;

revoke all on function public.guaranies(numeric) from public, anon, authenticated;

-- ------------------------------------------------------------
-- 4. PEDIR UN RETIRO
--
--    Lo llama el socio con su sesión: el socio sale de auth.uid(). Reemplaza
--    a `solicitar_cobro()` de la 066, que pedía todo junto.
-- ------------------------------------------------------------
create or replace function public.solicitar_retiro(p_monto numeric)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_uid    uuid := auth.uid();
  v_socio  public.socios;
  v_minimo numeric;
  v_saldo  numeric;
  v_monto  numeric := round(coalesce(p_monto, 0));
  v_pedido public.retiros;
  v_id     uuid;
begin
  if v_uid is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  select * into v_socio from public.socios where user_id = v_uid;
  if v_socio.id is null then
    raise exception 'Todavía no pediste tu código de recomendación.' using errcode = '22023';
  end if;

  if not v_socio.activo then
    raise exception 'Tu código está pausado. Escribinos y lo vemos.' using errcode = '42501';
  end if;

  select * into v_pedido from public.retiros where socio_id = v_socio.id and estado = 'pedido';
  if v_pedido.id is not null then
    raise exception 'Ya pediste un retiro de % el %. Cuando te lo transfiramos vas a poder pedir otro.',
      public.guaranies(v_pedido.monto),
      to_char(v_pedido.pedido_at at time zone 'America/Asuncion', 'DD/MM/YYYY')
      using errcode = '22023';
  end if;

  select coalesce(retiro_minimo, 120000) into v_minimo from public.ajustes_orden where unica;
  v_minimo := coalesce(v_minimo, 120000);
  v_saldo := public.saldo_socio(v_socio.id);

  if v_saldo <= 0 then
    raise exception 'Todavía no tenés nada por cobrar.' using errcode = '22023';
  end if;

  if coalesce(nullif(trim(v_socio.cuenta), ''), nullif(trim(v_socio.cobra_en), '')) is null then
    raise exception 'Antes de pedir el cobro, completá dónde te transferimos.'
      using errcode = '22023';
  end if;

  if v_saldo < v_minimo then
    raise exception 'Para retirar necesitás al menos %. Hoy tenés %.',
      public.guaranies(v_minimo), public.guaranies(v_saldo)
      using errcode = '22023';
  end if;

  if v_monto <= 0 then
    raise exception 'Escribí cuánto querés retirar.' using errcode = '22023';
  end if;

  if v_monto < v_minimo then
    raise exception 'El mínimo para retirar es %.', public.guaranies(v_minimo) using errcode = '22023';
  end if;

  if v_monto > v_saldo then
    raise exception 'No podés retirar más de lo que tenés: tu saldo es %.', public.guaranies(v_saldo)
      using errcode = '22023';
  end if;

  insert into public.retiros (socio_id, monto, banco, titular, cuenta, documento)
  values (v_socio.id, v_monto, v_socio.banco, v_socio.titular,
          coalesce(nullif(trim(v_socio.cuenta), ''), v_socio.cobra_en), v_socio.documento)
  returning id into v_id;

  return jsonb_build_object(
    'ok', true,
    'retiro_id', v_id,
    'socio', v_socio.nombre,
    'socio_id', v_socio.id,
    'monto', v_monto,
    'saldo', v_saldo - v_monto,
    'banco', v_socio.banco,
    'titular', v_socio.titular,
    'documento', v_socio.documento,
    'donde', coalesce(nullif(trim(v_socio.cuenta), ''), v_socio.cobra_en)
  );
end $fn$;

revoke all on function public.solicitar_retiro(numeric) from public, anon;
grant execute on function public.solicitar_retiro(numeric) to authenticated;

-- El pedido de todo junto ya no existe: dejarlo sería una segunda puerta
-- para cobrar sin mínimo y sin saldo.
drop function if exists public.solicitar_cobro();

-- ------------------------------------------------------------
-- 5. LA ADMINISTRACIÓN: VER LOS RETIROS
-- ------------------------------------------------------------
create or replace function public.listar_retiros(
  p_estado text default null,
  p_limite integer default 200
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_res jsonb;
begin
  if not public.es_superadmin() then
    raise exception 'Esto es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(x order by x->>'pedido_at' desc), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'id',          r.id,
      'socio_id',    r.socio_id,
      'socio',       s.nombre,
      'telefono',    s.telefono,
      'monto',       r.monto,
      'estado',      r.estado,
      'pedido_at',   r.pedido_at,
      'resuelto_at', r.resuelto_at,
      'banco',       r.banco,
      'titular',     r.titular,
      'cuenta',      r.cuenta,
      'documento',   r.documento,
      'medio',       r.medio,
      'nota',        r.nota
    ) as x
    from public.retiros r
    join public.socios s on s.id = r.socio_id
    where (p_estado is null or trim(p_estado) = '' or r.estado = p_estado)
    order by r.pedido_at desc
    limit greatest(1, least(coalesce(p_limite, 200), 500))
  ) t;

  return v_res;
end $fn$;

revoke all on function public.listar_retiros(text, integer) from public, anon;
grant execute on function public.listar_retiros(text, integer) to authenticated;

-- ------------------------------------------------------------
-- 6. LA ADMINISTRACIÓN: YA LE TRANSFERÍ
--
--    Queda como gasto de Orden, igual que el pago de una comisión en la 060.
--    Devuelve el usuario del socio: la ruta que llama a esto le manda el
--    push de «tu pago ya fue realizado».
-- ------------------------------------------------------------
create or replace function public.marcar_retiro_pagado(
  p_retiro uuid,
  p_medio  text default '',
  p_nota   text default ''
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_r     public.retiros;
  v_socio public.socios;
  v_orden uuid;
  v_gasto uuid;
  v_aviso text := null;
begin
  if not public.es_superadmin() then
    raise exception 'Esto es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select * into v_r from public.retiros where id = p_retiro for update;
  if v_r.id is null then
    raise exception 'Ese retiro no existe.' using errcode = '22023';
  end if;
  if v_r.estado = 'pagado' then
    raise exception 'Ese retiro ya está pagado.' using errcode = '22023';
  end if;
  if v_r.estado = 'rechazado' then
    raise exception 'Ese retiro está rechazado: la plata volvió a su saldo.' using errcode = '22023';
  end if;

  select * into v_socio from public.socios where id = v_r.socio_id;
  select empresa_id into v_orden from public.ajustes_orden where unica;

  if v_orden is null then
    v_aviso := 'No hay una empresa de Orden elegida, así que el pago no se anotó en tus finanzas.';
  else
    begin
      insert into public.movimientos (
        empresa_id, tipo, estado, fecha, descripcion, categoria,
        subtotal, descuento, monto, costo_total, metodo_pago, contraparte, creado_por
      ) values (
        v_orden, 'gasto', 'activo', public.hoy_empresa(v_orden),
        'Retiro de ' || coalesce(v_socio.nombre, 'socio'), 'Comisiones',
        v_r.monto, 0, v_r.monto, 0, 'transferencia',
        left(coalesce(v_socio.nombre, ''), 80), auth.uid()
      )
      returning id into v_gasto;
    exception when others then
      v_aviso := 'El retiro quedó pagado, pero el gasto no se pudo anotar: ' || sqlerrm;
    end;
  end if;

  update public.retiros set
    estado       = 'pagado',
    resuelto_at  = now(),
    resuelto_por = auth.uid(),
    gasto_id     = v_gasto,
    medio        = left(coalesce(trim(p_medio), ''), 60),
    nota         = left(coalesce(trim(p_nota), ''), 300)
  where id = p_retiro;

  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (auth.uid(), null, 'pagar_retiro', jsonb_build_object(
    'retiro_id', v_r.id, 'socio_id', v_r.socio_id, 'socio', v_socio.nombre,
    'monto', v_r.monto, 'medio', left(coalesce(trim(p_medio), ''), 60), 'gasto_id', v_gasto
  ));

  return jsonb_build_object(
    'ok', true,
    'monto', v_r.monto,
    'socio', v_socio.nombre,
    'socio_user_id', v_socio.user_id,
    'saldo', greatest(public.saldo_socio(v_r.socio_id), 0),
    'gasto_anotado', v_gasto is not null,
    'aviso', v_aviso
  );
end $fn$;

revoke all on function public.marcar_retiro_pagado(uuid, text, text) from public, anon;
grant execute on function public.marcar_retiro_pagado(uuid, text, text) to authenticated;

-- ------------------------------------------------------------
-- 7. LA ADMINISTRACIÓN: NO SE PUEDE PAGAR
--
--    Los datos no sirven, la cuenta no existe. La plata vuelve a su saldo
--    sola (un retiro rechazado no descuenta) y el motivo queda escrito.
-- ------------------------------------------------------------
create or replace function public.rechazar_retiro(
  p_retiro uuid,
  p_nota   text default ''
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_r     public.retiros;
  v_socio public.socios;
begin
  if not public.es_superadmin() then
    raise exception 'Esto es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select * into v_r from public.retiros where id = p_retiro for update;
  if v_r.id is null then
    raise exception 'Ese retiro no existe.' using errcode = '22023';
  end if;
  if v_r.estado <> 'pedido' then
    raise exception 'Solo se puede rechazar un retiro que todavía no se pagó.' using errcode = '22023';
  end if;
  if coalesce(trim(p_nota), '') = '' then
    raise exception 'Escribí por qué no se pudo pagar: es lo que va a leer.' using errcode = '22023';
  end if;

  update public.retiros set
    estado       = 'rechazado',
    resuelto_at  = now(),
    resuelto_por = auth.uid(),
    nota         = left(trim(p_nota), 300)
  where id = p_retiro;

  select * into v_socio from public.socios where id = v_r.socio_id;

  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (auth.uid(), null, 'rechazar_retiro', jsonb_build_object(
    'retiro_id', v_r.id, 'socio_id', v_r.socio_id, 'monto', v_r.monto,
    'motivo', left(trim(p_nota), 300)
  ));

  return jsonb_build_object(
    'ok', true,
    'monto', v_r.monto,
    'socio', v_socio.nombre,
    'socio_user_id', v_socio.user_id,
    'motivo', left(trim(p_nota), 300)
  );
end $fn$;

revoke all on function public.rechazar_retiro(uuid, text) from public, anon;
grant execute on function public.rechazar_retiro(uuid, text) to authenticated;

-- ------------------------------------------------------------
-- 8. AJUSTAR UNA COMISIÓN
--
--    En la 060 el monto se ajustaba al pagarla (un negocio que pagó un año
--    de una). Ahora la comisión no se paga sola —se retira del saldo—, así
--    que el ajuste va antes: se corrige la comisión y el saldo la sigue.
-- ------------------------------------------------------------
create or replace function public.ajustar_comision(
  p_comision uuid,
  p_monto    numeric,
  p_nota     text default ''
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_c public.comisiones;
begin
  if not public.es_superadmin() then
    raise exception 'Esto es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select * into v_c from public.comisiones where id = p_comision for update;
  if v_c.id is null then
    raise exception 'Esa comisión no existe.' using errcode = '22023';
  end if;
  if v_c.estado <> 'por_pagar' then
    raise exception 'Solo se ajusta una comisión que todavía está en el saldo.' using errcode = '22023';
  end if;
  if p_monto is null or p_monto < 0 then
    raise exception 'El monto no puede ser negativo.' using errcode = '22023';
  end if;
  if public.saldo_socio(v_c.socio_id) - v_c.monto + p_monto < 0 then
    raise exception 'Ese socio ya retiró parte de esa plata: el monto no puede bajar de %.',
      public.guaranies(v_c.monto - public.saldo_socio(v_c.socio_id))
      using errcode = '22023';
  end if;

  update public.comisiones set
    monto = round(p_monto),
    nota  = left(
      case when coalesce(trim(p_nota), '') = '' then nota else trim(p_nota) end, 300)
  where id = p_comision;

  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (auth.uid(), v_c.empresa_id, 'ajustar_comision', jsonb_build_object(
    'comision_id', v_c.id, 'socio_id', v_c.socio_id,
    'antes', v_c.monto, 'ahora', round(p_monto), 'nota', left(coalesce(trim(p_nota), ''), 300)
  ));

  return jsonb_build_object('ok', true, 'monto', round(p_monto));
end $fn$;

revoke all on function public.ajustar_comision(uuid, numeric, text) from public, anon;
grant execute on function public.ajustar_comision(uuid, numeric, text) to authenticated;

-- ------------------------------------------------------------
-- 9. LOS DOS CAMINOS VIEJOS, CON UNA GUARDA
--
--    Pagar o anular una comisión suelta sigue sirviendo para los socios que
--    nunca retiraron. Pero si ya retiró, sacar esa comisión del saldo lo
--    dejaría en negativo: se le pagó plata que ya no figura en ningún lado.
--    Mismo cuerpo que la 060, con la guarda marcada (070).
-- ------------------------------------------------------------
create or replace function public.marcar_comision_pagada(
  p_comision uuid,
  p_monto    numeric default null,
  p_medio    text default '',
  p_nota     text default ''
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_c     public.comisiones;
  v_socio text;
  v_monto numeric;
  v_orden uuid;
  v_gasto uuid;
  v_aviso text := null;
begin
  if not public.es_superadmin() then
    raise exception 'Esto es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select * into v_c from public.comisiones where id = p_comision;

  if v_c.id is null then
    raise exception 'Esa comisión no existe.' using errcode = '22023';
  end if;

  if v_c.estado = 'pagada' then
    raise exception 'Esa comisión ya está pagada.' using errcode = '22023';
  end if;

  if v_c.estado = 'anulada' then
    raise exception 'Esa comisión está anulada: el cobro que la generó se deshizo.'
      using errcode = '22023';
  end if;

  -- (070) Quien ya cobra por retiros se paga por retiros.
  if exists (select 1 from public.retiros where socio_id = v_c.socio_id and estado in ('pedido', 'pagado')) then
    raise exception 'Este socio cobra con retiros desde su saldo. Registrá el pago desde su pedido de retiro.'
      using errcode = '22023';
  end if;

  v_monto := coalesce(p_monto, v_c.monto);

  if v_monto < 0 then
    raise exception 'El monto no puede ser negativo.' using errcode = '22023';
  end if;

  select nombre into v_socio from public.socios where id = v_c.socio_id;
  select empresa_id into v_orden from public.ajustes_orden where unica;

  if v_orden is null then
    v_aviso := 'No hay una empresa de Orden elegida, así que el pago no se anotó en tus finanzas.';
  elsif v_monto > 0 then
    begin
      insert into public.movimientos (
        empresa_id, tipo, estado, fecha, descripcion, categoria,
        subtotal, descuento, monto, costo_total, metodo_pago, contraparte, creado_por
      ) values (
        v_orden, 'gasto', 'activo', public.hoy_empresa(v_orden),
        'Comisión a ' || coalesce(v_socio, 'socio'), 'Comisiones',
        v_monto, 0, v_monto, 0, 'transferencia',
        left(coalesce(v_socio, ''), 80), auth.uid()
      )
      returning id into v_gasto;
    exception when others then
      v_aviso := 'La comisión quedó pagada, pero el gasto no se pudo anotar: ' || sqlerrm;
    end;
  end if;

  update public.comisiones set
    estado    = 'pagada',
    monto     = v_monto,
    pagada_at = now(),
    gasto_id  = v_gasto,
    medio     = left(coalesce(trim(p_medio), ''), 60),
    nota      = left(coalesce(trim(p_nota), ''), 300)
  where id = p_comision;

  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (auth.uid(), v_c.empresa_id, 'pagar_comision', jsonb_build_object(
    'comision_id', v_c.id,
    'socio_id', v_c.socio_id,
    'socio', v_socio,
    'monto_calculado', v_c.monto,
    'monto_pagado', v_monto,
    'medio', left(coalesce(trim(p_medio), ''), 60),
    'gasto_id', v_gasto
  ));

  return jsonb_build_object(
    'ok', true,
    'monto', v_monto,
    'ajustado', v_monto <> v_c.monto,
    'gasto_anotado', v_gasto is not null,
    'aviso', v_aviso
  );
end $fn$;

revoke all on function public.marcar_comision_pagada(uuid, numeric, text, text) from public, anon;
grant execute on function public.marcar_comision_pagada(uuid, numeric, text, text) to authenticated;

create or replace function public.anular_comision(
  p_comision uuid,
  p_nota     text default ''
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_c public.comisiones;
begin
  if not public.es_superadmin() then
    raise exception 'Esto es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select * into v_c from public.comisiones where id = p_comision;

  if v_c.id is null then
    raise exception 'Esa comisión no existe.' using errcode = '22023';
  end if;

  if v_c.estado = 'pagada' then
    raise exception
      'Esa comisión ya se pagó. Si hay que recuperar la plata, eso se arregla con la persona, no borrando el registro.'
      using errcode = '22023';
  end if;

  -- (070) Si ya la retiró, anularla lo deja debiendo plata que se le pagó.
  if v_c.estado = 'por_pagar' and public.saldo_socio(v_c.socio_id) - v_c.monto < 0 then
    raise exception
      'Ese socio ya retiró esa plata. Si hay que recuperarla, eso se arregla con la persona, no anulando la comisión.'
      using errcode = '22023';
  end if;

  update public.comisiones set
    estado = 'anulada',
    nota   = left(coalesce(trim(p_nota), ''), 300)
  where id = p_comision;

  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (auth.uid(), v_c.empresa_id, 'anular_comision', jsonb_build_object(
    'comision_id', v_c.id, 'socio_id', v_c.socio_id, 'monto', v_c.monto,
    'motivo', left(coalesce(trim(p_nota), ''), 300)
  ));

  return jsonb_build_object('ok', true);
end $fn$;

revoke all on function public.anular_comision(uuid, text) from public, anon;
grant execute on function public.anular_comision(uuid, text) to authenticated;

-- ------------------------------------------------------------
-- 10. LO QUE VE EL SOCIO
--
--     Redefine `mi_panel_socio()` de la 066. `por_pagar` pasa a ser el saldo
--     disponible (lo que puede retirar), y `pagado` suma lo que se le pagó
--     de las dos formas: comisiones pagadas directo y retiros pagados.
-- ------------------------------------------------------------
create or replace function public.mi_panel_socio()
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_uid    uuid := auth.uid();
  v_socio  public.socios;
  v_lista  jsonb;
  v_retiros jsonb;
  v_pedido public.retiros;
  v_minimo numeric;
begin
  if v_uid is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  select * into v_socio from public.socios where user_id = v_uid;

  if v_socio.id is null then
    return jsonb_build_object('tiene_codigo', false);
  end if;

  select coalesce(jsonb_agg(x order by x->>'desde' desc), '[]'::jsonb) into v_lista
  from (
    select jsonb_build_object(
      'negocio',  coalesce(e.nombre, 'Negocio borrado'),
      'desde',    r.created_at,
      'paga',     public.plan_efectivo_calculado(r.empresa_id) <> 'gratis',
      'plan',     public.plan_efectivo_calculado(r.empresa_id),
      'estado',   coalesce(c.estado, 'sin_pagar'),
      'monto',    coalesce(c.monto, 0),
      'cuando',   c.created_at,
      'pagada_at', c.pagada_at
    ) as x
    from public.referidos r
    left join public.empresas e on e.id = r.empresa_id
    left join public.comisiones c on c.empresa_id = r.empresa_id
    where r.socio_id = v_socio.id
  ) t;

  select coalesce(jsonb_agg(x order by x->>'pedido_at' desc), '[]'::jsonb) into v_retiros
  from (
    select jsonb_build_object(
      'id', rt.id, 'monto', rt.monto, 'estado', rt.estado,
      'pedido_at', rt.pedido_at, 'resuelto_at', rt.resuelto_at,
      -- El motivo se muestra solo si lo rechazaron: es lo que tiene que leer.
      'nota', case when rt.estado = 'rechazado' then rt.nota else '' end
    ) as x
    from public.retiros rt
    where rt.socio_id = v_socio.id
    order by rt.pedido_at desc
    limit 20
  ) t;

  select * into v_pedido from public.retiros where socio_id = v_socio.id and estado = 'pedido';
  select retiro_minimo into v_minimo from public.ajustes_orden where unica;

  return jsonb_build_object(
    'tiene_codigo', true,
    'codigo',    v_socio.codigo,
    'nombre',    v_socio.nombre,
    'cobra_en',  v_socio.cobra_en,
    'banco',     v_socio.banco,
    'titular',   v_socio.titular,
    'cuenta',    v_socio.cuenta,
    'documento', v_socio.documento,
    'activo',    v_socio.activo,
    'traidos',   (select count(*) from public.referidos r where r.socio_id = v_socio.id),
    'pagaron',   (select count(*) from public.comisiones c
                  where c.socio_id = v_socio.id and c.estado <> 'anulada'),
    'por_pagar', greatest(public.saldo_socio(v_socio.id), 0),
    'pagado',    coalesce((select sum(c.monto) from public.comisiones c
                           where c.socio_id = v_socio.id and c.estado = 'pagada'), 0)
               + coalesce((select sum(rt.monto) from public.retiros rt
                           where rt.socio_id = v_socio.id and rt.estado = 'pagado'), 0),
    'minimo',    coalesce(v_minimo, 120000),
    'cobro_pedido_el', v_pedido.pedido_at,
    'retiro_pedido', case when v_pedido.id is null then null else jsonb_build_object(
      'id', v_pedido.id, 'monto', v_pedido.monto, 'pedido_at', v_pedido.pedido_at
    ) end,
    'retiros',   v_retiros,
    'referidos', v_lista
  );
end $fn$;

revoke all on function public.mi_panel_socio() from public, anon;
grant execute on function public.mi_panel_socio() to authenticated;

-- ------------------------------------------------------------
-- 11. Y LO QUE VE LA ADMINISTRACIÓN DE CADA SOCIO
--
--     Redefine `listar_socios()` de la 064: el saldo real y cuánto tiene
--     pedido, en vez de la suma de comisiones sin descontar retiros.
-- ------------------------------------------------------------
create or replace function public.listar_socios(
  p_busqueda text default null,
  p_limite   integer default 200
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_res jsonb;
begin
  if not public.es_superadmin() then
    raise exception 'Esto es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(x order by x->>'nombre'), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'id',        s.id,
      'nombre',    s.nombre,
      'telefono',  s.telefono,
      'email',     s.email,
      'codigo',    s.codigo,
      'activo',    s.activo,
      'cobra_en',  s.cobra_en,
      'banco',     s.banco,
      'titular',   s.titular,
      'cuenta',    s.cuenta,
      'documento', s.documento,
      'notas',     s.notas,
      'tiene_cuenta', s.user_id is not null,
      'creado',    s.created_at,
      'traidos',   (select count(*) from public.referidos r where r.socio_id = s.id),
      'pagaron',   (select count(*) from public.comisiones c
                    where c.socio_id = s.id and c.estado <> 'anulada'),
      -- Lo que todavía se le debe: su saldo más lo que tiene pedido.
      'por_pagar', greatest(public.saldo_socio(s.id), 0)
                 + coalesce((select sum(rt.monto) from public.retiros rt
                             where rt.socio_id = s.id and rt.estado = 'pedido'), 0),
      'pagado',    coalesce((select sum(c.monto) from public.comisiones c
                             where c.socio_id = s.id and c.estado = 'pagada'), 0)
                 + coalesce((select sum(rt.monto) from public.retiros rt
                             where rt.socio_id = s.id and rt.estado = 'pagado'), 0)
    ) as x
    from public.socios s
    where (
        p_busqueda is null
        or trim(p_busqueda) = ''
        or s.nombre ilike '%' || trim(p_busqueda) || '%'
        or s.codigo ilike '%' || trim(p_busqueda) || '%'
        or s.telefono ilike '%' || trim(p_busqueda) || '%'
        or s.email ilike '%' || trim(p_busqueda) || '%'
      )
    order by s.nombre
    limit greatest(1, least(coalesce(p_limite, 200), 500))
  ) t;

  return v_res;
end $fn$;

revoke all on function public.listar_socios(text, integer) from public, anon;
grant execute on function public.listar_socios(text, integer) to authenticated;


-- ############################################################
-- ##  071_orden_que_habla.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 071 · Una app que habla todos los días
--
-- LO QUE PIDIÓ MATÍAS (16/09/2026)
--
--   «Tiene que ser bien activo Orden, que le esté enviando notificaciones
--    todos los días: no te olvides de cargar hoy, hoy ganaste esto, hoy
--    estás un dos por ciento más de venta que ayer, hoy tenés estos gastos.
--    Que la aplicación sea más viva.»
--
-- Hasta acá Orden hablaba una sola vez por día, y solo para salvar una
-- racha. Esto suma tres momentos: a la mañana (cómo fue ayer), a la tarde
-- (si todavía no cargó nada) y a la noche (cómo fue hoy, contra ayer). Y el
-- aviso de que la prueba se termina, que es el que más importa para que la
-- cuenta no se corte sin que la persona lo vea venir.
--
-- LO QUE SIGUE SIENDO REGLA
--
--   · Una preferencia para apagarlo (`aviso_diario`). Un aviso que no se
--     puede apagar termina con la persona apagando TODOS los avisos.
--   · Solo cuentas vivas: con algo cargado en los últimos 30 días o creadas
--     en la última semana. A quien abandonó hace meses no se le escribe.
--   · Solo rubros de ciclo diario. A un ganadero no se le pregunta todos los
--     días si vendió algo (ver 024, `rubro_cierra_el_dia`).
--   · Una vez por persona, momento y día: la tabla `envios` (010).
--
-- Los números salen acá y no en el servidor: el servidor solo arma la frase
-- en el idioma de cada uno.
-- ============================================================

-- ------------------------------------------------------------
-- 1. LA PREFERENCIA
-- ------------------------------------------------------------
alter table public.preferencias
  add column if not exists aviso_diario boolean not null default true;

create or replace function public.mis_preferencias()
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_res jsonb;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'idioma', p.idioma, 'aviso_cierre', p.aviso_cierre,
    'aviso_semanal', p.aviso_semanal, 'aviso_turnos', p.aviso_turnos,
    'aviso_diario', p.aviso_diario,
    'hora_cierre', p.hora_cierre
  ) into v_res
  from public.preferencias p where p.user_id = auth.uid();

  return coalesce(v_res, jsonb_build_object(
    'idioma', 'es', 'aviso_cierre', true, 'aviso_semanal', true,
    'aviso_turnos', true, 'aviso_diario', true, 'hora_cierre', 20));
end $fn$;

-- La firma cambia: sin borrar la de cinco, una llamada con algunos campos
-- queda ambigua (ver 043).
drop function if exists public.guardar_preferencias(text, boolean, boolean, smallint, boolean);

create or replace function public.guardar_preferencias(
  p_idioma text default null,
  p_aviso_cierre boolean default null,
  p_aviso_semanal boolean default null,
  p_hora_cierre smallint default null,
  p_aviso_turnos boolean default null,
  p_aviso_diario boolean default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  insert into public.preferencias as p (
    user_id, idioma, aviso_cierre, aviso_semanal, hora_cierre, aviso_turnos, aviso_diario)
  values (
    auth.uid(),
    coalesce(nullif(lower(trim(p_idioma)), ''), 'es'),
    coalesce(p_aviso_cierre, true),
    coalesce(p_aviso_semanal, true),
    coalesce(p_hora_cierre, 20::smallint),
    coalesce(p_aviso_turnos, true),
    coalesce(p_aviso_diario, true)
  )
  on conflict (user_id) do update set
    idioma        = coalesce(nullif(lower(trim(p_idioma)), ''), p.idioma),
    aviso_cierre  = coalesce(p_aviso_cierre,  p.aviso_cierre),
    aviso_semanal = coalesce(p_aviso_semanal, p.aviso_semanal),
    hora_cierre   = coalesce(p_hora_cierre,   p.hora_cierre),
    aviso_turnos  = coalesce(p_aviso_turnos,  p.aviso_turnos),
    aviso_diario  = coalesce(p_aviso_diario,  p.aviso_diario),
    updated_at    = now();

  return public.mis_preferencias();
end $fn$;

revoke all on function public.mis_preferencias() from public, anon;
grant execute on function public.mis_preferencias() to authenticated;
revoke all on function public.guardar_preferencias(text, boolean, boolean, smallint, boolean, boolean)
  from public, anon;
grant execute on function public.guardar_preferencias(text, boolean, boolean, smallint, boolean, boolean)
  to authenticated;

-- ------------------------------------------------------------
-- 2. LOS NÚMEROS DE HOY Y DE AYER, POR CUENTA
--
--    Solo para service_role: son los números de todos los negocios.
--    `ganancia` es la misma cuenta que el panel: lo que entró menos el costo
--    de lo vendido menos los gastos.
-- ------------------------------------------------------------
create or replace function public.avisos_del_dia()
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_res jsonb;
begin
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'empresa_id',  e.id,
      'nombre',      e.nombre,
      'moneda',      e.moneda,
      'tipo_cuenta', coalesce(e.tipo_cuenta, 'emprendedor'),
      -- La fecha de hoy EN LA ZONA DEL NEGOCIO: con ella se arma la clave
      -- de «una vez por día».
      'fecha',       z.hoy,
      'hoy', jsonb_build_object(
        'ventas', a.ventas_hoy, 'ingresos', a.ingresos_hoy, 'gastos', a.gastos_hoy,
        'ganancia', a.ventas_hoy + a.ingresos_hoy - a.costo_hoy - a.gastos_hoy, 'cargados', a.n_hoy),
      'ayer', jsonb_build_object(
        'ventas', a.ventas_ayer, 'ingresos', a.ingresos_ayer, 'gastos', a.gastos_ayer,
        'ganancia', a.ventas_ayer + a.ingresos_ayer - a.costo_ayer - a.gastos_ayer, 'cargados', a.n_ayer),
      'destinatarios', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'user_id', mi.user_id, 'idioma', coalesce(p.idioma, 'es'))), '[]'::jsonb)
        from public.miembros mi
        left join public.preferencias p on p.user_id = mi.user_id
        where mi.empresa_id = e.id
          and mi.rol in ('propietario', 'admin')
          and coalesce(p.aviso_diario, true)
      )
    ) as x
    from public.empresas e
    cross join lateral (
      select (now() at time zone coalesce(e.zona_horaria, 'America/Asuncion'))::date as hoy
    ) z
    cross join lateral (
      select
        coalesce(sum(m.monto) filter (where m.fecha = z.hoy and m.tipo = 'venta'), 0)       as ventas_hoy,
        coalesce(sum(m.monto) filter (where m.fecha = z.hoy and m.tipo = 'ingreso'), 0)     as ingresos_hoy,
        coalesce(sum(m.monto) filter (where m.fecha = z.hoy and m.tipo = 'gasto'), 0)       as gastos_hoy,
        coalesce(sum(coalesce(m.costo_total, 0)) filter (where m.fecha = z.hoy and m.tipo = 'venta'), 0) as costo_hoy,
        count(*) filter (where m.fecha = z.hoy)::int                                       as n_hoy,
        coalesce(sum(m.monto) filter (where m.fecha = z.hoy - 1 and m.tipo = 'venta'), 0)   as ventas_ayer,
        coalesce(sum(m.monto) filter (where m.fecha = z.hoy - 1 and m.tipo = 'ingreso'), 0) as ingresos_ayer,
        coalesce(sum(m.monto) filter (where m.fecha = z.hoy - 1 and m.tipo = 'gasto'), 0)   as gastos_ayer,
        coalesce(sum(coalesce(m.costo_total, 0)) filter (where m.fecha = z.hoy - 1 and m.tipo = 'venta'), 0) as costo_ayer,
        count(*) filter (where m.fecha = z.hoy - 1)::int                                   as n_ayer
      from public.movimientos m
      where m.empresa_id = e.id and m.estado = 'activo'
        and m.fecha between z.hoy - 1 and z.hoy
    ) a
    where (
        coalesce(e.tipo_cuenta, 'emprendedor') = 'personal'
        or public.rubro_cierra_el_dia(e.rubro, e.tipo_cuenta)
      )
      -- Una cuenta vencida no puede cargar: pedirle que cargue es mentirle.
      and public.puede_cargar(e.id)
      and (
        e.created_at > now() - interval '7 days'
        or exists (select 1 from public.movimientos m2
                   where m2.empresa_id = e.id and m2.created_at > now() - interval '30 days')
      )
  ) s;

  return v_res;
end $fn$;

revoke all on function public.avisos_del_dia() from public, anon, authenticated;
grant execute on function public.avisos_del_dia() to service_role;

-- ------------------------------------------------------------
-- 3. LAS PRUEBAS QUE SE TERMINAN
--
--    Faltando 3 días, 1 día y el último día. `dias` se cuenta en la fecha de
--    la zona del negocio: «termina mañana» tiene que ser mañana para él.
-- ------------------------------------------------------------
create or replace function public.pruebas_por_terminar()
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_res jsonb;
begin
  select coalesce(jsonb_agg(x order by (x->>'dias')::int), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'empresa_id',  e.id,
      'nombre',      e.nombre,
      'tipo_cuenta', coalesce(e.tipo_cuenta, 'emprendedor'),
      'fin',         s.periodo_fin,
      'dias',        (s.periodo_fin at time zone coalesce(e.zona_horaria, 'America/Asuncion'))::date
                     - (now() at time zone coalesce(e.zona_horaria, 'America/Asuncion'))::date,
      'destinatarios', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'user_id', mi.user_id, 'idioma', coalesce(p.idioma, 'es'))), '[]'::jsonb)
        from public.miembros mi
        left join public.preferencias p on p.user_id = mi.user_id
        where mi.empresa_id = e.id and mi.rol in ('propietario', 'admin')
      )
    ) as x
    from public.suscripciones s
    join public.empresas e on e.id = s.empresa_id
    where s.estado = 'prueba'
      and s.periodo_fin > now()
      and (s.periodo_fin at time zone coalesce(e.zona_horaria, 'America/Asuncion'))::date
          - (now() at time zone coalesce(e.zona_horaria, 'America/Asuncion'))::date in (0, 1, 3)
  ) t;

  return v_res;
end $fn$;

revoke all on function public.pruebas_por_terminar() from public, anon, authenticated;
grant execute on function public.pruebas_por_terminar() to service_role;


-- ############################################################
-- ##  072_agenda_en_calendario.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 072 · La agenda vista como calendario
--
-- LO QUE PIDIÓ MATÍAS (16/09/2026)
--
--   «Añadir calendario para ver la agenda. El calendario como una opción
--    para ver: una semana, un mes o el rango que quieran, si tienen
--    disponible o no.»
--
-- Hasta acá la agenda se miraba de a un día. Para saber si el jueves que
-- viene hay lugar había que avanzar día por día con la flecha.
--
-- QUÉ DEVUELVE, POR DÍA
--
--   · cuántos turnos hay (sin contar los cancelados);
--   · cuántos minutos atiende el local ese día (la suma de las franjas de
--     cada profesional, o la del día especial si hay una excepción);
--   · cuántos de esos minutos ya están tomados;
--   · y una sola palabra para pintarlo: libre, casi (60% o más ocupado),
--     lleno (90% o más) o cerrado.
--
-- Es la misma regla de horarios que usa `huecos_del_dia` (037): la excepción
-- de la persona gana sobre la del local, y sin excepción manda el horario de
-- siempre. Un calendario que dijera «libre» un feriado sería peor que no
-- tener calendario.
-- ============================================================

create or replace function public.agenda_calendario(
  p_empresa uuid,
  p_desde   date,
  p_hasta   date
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_zona text;
  v_res  jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if p_desde is null or p_hasta is null or p_hasta < p_desde then
    raise exception 'El rango de fechas no es válido.' using errcode = '22023';
  end if;

  -- Tres meses alcanzan para cualquier vista y no dejan pedir un año entero.
  if p_hasta - p_desde > 92 then
    raise exception 'Elegí un rango de hasta tres meses.' using errcode = '22023';
  end if;

  select coalesce(zona_horaria, 'America/Asuncion') into v_zona
  from public.empresas where id = p_empresa;

  with dias as (
    select d::date as fecha from generate_series(p_desde, p_hasta, interval '1 day') d
  ),
  gente as (
    select p.id from public.turnos_profesional p
    where p.empresa_id = p_empresa and p.activo
  ),
  -- Para cada día y persona, la excepción que manda (la suya antes que la del local).
  excepcion as (
    select distinct on (d.fecha, g.id)
      d.fecha, g.id as profesional_id, x.cerrado, x.desde, x.hasta
    from dias d
    cross join gente g
    join public.turnos_excepcion x
      on x.empresa_id = p_empresa and x.fecha = d.fecha
     and (x.profesional_id = g.id or x.profesional_id is null)
    order by d.fecha, g.id, x.profesional_id nulls last
  ),
  abierto as (
    select d.fecha, g.id as profesional_id,
      case
        when e.profesional_id is not null then
          case when e.cerrado then 0 else extract(epoch from (e.hasta - e.desde)) / 60 end
        else coalesce((
          select sum(extract(epoch from (h.hasta - h.desde)) / 60)
          from public.turnos_horario h
          where h.profesional_id = g.id and h.activo
            and h.dia_semana = extract(dow from d.fecha)::smallint
        ), 0)
      end as minutos
    from dias d
    cross join gente g
    left join excepcion e on e.fecha = d.fecha and e.profesional_id = g.id
  ),
  tomado as (
    select (r.inicia at time zone v_zona)::date as fecha,
      count(*)::int as turnos,
      sum(extract(epoch from (r.termina - r.inicia)) / 60) as minutos
    from public.turnos_reserva r
    where r.empresa_id = p_empresa
      and r.estado in ('pendiente', 'confirmada', 'atendida', 'no_vino')
      and r.inicia >= (p_desde::timestamp at time zone v_zona)
      and r.inicia <  ((p_hasta + 1)::timestamp at time zone v_zona)
    group by 1
  ),
  por_dia as (
    select d.fecha,
      coalesce((select sum(a.minutos) from abierto a where a.fecha = d.fecha), 0)::int as abierto_min,
      coalesce(t.minutos, 0)::int as ocupado_min,
      coalesce(t.turnos, 0) as turnos
    from dias d
    left join tomado t on t.fecha = d.fecha
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'fecha', fecha,
    'turnos', turnos,
    'abierto_min', abierto_min,
    'ocupado_min', least(ocupado_min, abierto_min),
    'libre_min', greatest(abierto_min - ocupado_min, 0),
    'estado', case
      when abierto_min = 0 then 'cerrado'
      when ocupado_min >= abierto_min * 0.9 then 'lleno'
      when ocupado_min >= abierto_min * 0.6 then 'casi'
      else 'libre'
    end
  ) order by fecha), '[]'::jsonb) into v_res
  from por_dia;

  return v_res;
end $fn$;

revoke all on function public.agenda_calendario(uuid, date, date) from public, anon;
grant execute on function public.agenda_calendario(uuid, date, date) to authenticated;


-- ############################################################
-- ##  073_ahorro_en_otra_moneda.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 073 · Ahorrar en la moneda que uno quiera
--
-- LO QUE PIDIÓ MATÍAS (16/09/2026)
--
--   «Mucha gente no ahorra en su moneda local. Debemos poner la opción de si
--    quiere ahorrar en su moneda o elegir una moneda: dólares, euros, libras.»
--
-- En Paraguay casi todo el que ahorra en serio ahorra en dólares. Hasta acá
-- un fondo estaba siempre en la moneda de la cuenta: quien compraba 100
-- dólares tenía que anotar «Gs. 750.000» y, cuando el dólar subía, su fondo
-- decía una mentira.
--
-- EL MODELO
--
--   · Cada fondo tiene su moneda (`ahorros.moneda`; null = la de la cuenta).
--     El saldo, la meta y cada depósito van en ESA moneda: «US$ 350».
--   · Cada movimiento de un fondo en otra moneda guarda además cuánto costó
--     (o cuánto se recibió) en la moneda de la cuenta: `monto_local`. Es el
--     cambio que le hicieron a ESA persona ese día, no una cotización de
--     internet.
--   · Todo lo que SUMA —lo guardado en el mes, el resumen, el Excel— suma
--     `monto_local`: no se pueden sumar guaraníes con dólares.
--
-- La moneda de un fondo se elige al crearlo y no se cambia si ya tiene
-- movimientos: cambiarla reetiquetaría lo guardado sin convertirlo (la misma
-- regla que la moneda de la cuenta, 051).
-- ============================================================

alter table public.ahorros
  add column if not exists moneda text;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'ahorros_moneda_valida') then
    alter table public.ahorros
      add constraint ahorros_moneda_valida check (moneda is null or moneda ~ '^[A-Z]{3}$');
  end if;
end $$;

alter table public.movimientos_ahorro
  add column if not exists monto_local numeric(14,2);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'movimientos_ahorro_local_positivo') then
    alter table public.movimientos_ahorro
      add constraint movimientos_ahorro_local_positivo check (monto_local is null or monto_local > 0);
  end if;
end $$;

-- ------------------------------------------------------------
-- 1. CREAR O EDITAR UN FONDO, CON SU MONEDA
-- ------------------------------------------------------------
drop function if exists public.guardar_ahorro(uuid, text, numeric, date, uuid);

create or replace function public.guardar_ahorro(
  p_empresa      uuid,
  p_nombre       text,
  p_meta         numeric default null,
  p_fecha_limite date    default null,
  p_id           uuid    default null,
  p_moneda       text    default null
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_id       uuid;
  v_zona     text;
  v_hoy      date;
  v_anterior date;
  v_propia   text;
  v_moneda   text;
  v_antes    public.ahorros;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar esto.' using errcode = '42501';
  end if;

  if char_length(trim(coalesce(p_nombre, ''))) = 0 then
    raise exception 'Ponele un nombre, para saber para qué estás juntando.' using errcode = '22023';
  end if;

  if p_meta is not null and p_meta <= 0 then
    raise exception 'La meta tiene que ser mayor que cero, o dejala vacía.' using errcode = '22023';
  end if;

  select zona_horaria, moneda into v_zona, v_propia from public.empresas where id = p_empresa;
  v_hoy := (now() at time zone coalesce(v_zona, 'America/Asuncion'))::date;

  -- La moneda de la cuenta se guarda como null: «la de siempre».
  v_moneda := nullif(upper(trim(coalesce(p_moneda, ''))), '');
  if v_moneda is not null and v_moneda !~ '^[A-Z]{3}$' then
    raise exception 'Esa moneda no es válida.' using errcode = '22023';
  end if;
  if v_moneda = v_propia then
    v_moneda := null;
  end if;

  if p_id is not null then
    select * into v_antes from public.ahorros where id = p_id and empresa_id = p_empresa;
    v_anterior := v_antes.fecha_limite;
  end if;

  if p_fecha_limite is not null
     and p_fecha_limite < v_hoy
     and p_fecha_limite is distinct from v_anterior then
    raise exception 'Esa fecha ya pasó. Poné para cuándo lo querés juntar.' using errcode = '22007';
  end if;

  if p_id is null then
    insert into public.ahorros (empresa_id, nombre, meta, fecha_limite, moneda)
    values (p_empresa, trim(p_nombre), p_meta, p_fecha_limite, v_moneda)
    returning id into v_id;
  else
    if v_antes.id is null then
      raise exception 'Ese fondo no existe en esta cuenta.' using errcode = 'P0002';
    end if;

    -- Editar sin mandar moneda la deja como estaba.
    if p_moneda is null then
      v_moneda := v_antes.moneda;
    end if;

    if v_moneda is distinct from v_antes.moneda
       and exists (select 1 from public.movimientos_ahorro where ahorro_id = p_id) then
      raise exception 'Ese fondo ya tiene movimientos: no se le puede cambiar la moneda. Creá otro fondo.'
        using errcode = '22023';
    end if;

    update public.ahorros
    set nombre = trim(p_nombre), meta = p_meta, fecha_limite = p_fecha_limite,
        moneda = v_moneda, updated_at = now()
    where id = p_id and empresa_id = p_empresa
    returning id into v_id;
  end if;

  return v_id;
end $fn$;

revoke all on function public.guardar_ahorro(uuid, text, numeric, date, uuid, text) from public, anon;
grant execute on function public.guardar_ahorro(uuid, text, numeric, date, uuid, text) to authenticated;

-- ------------------------------------------------------------
-- 2. GUARDAR O RETIRAR, CON LO QUE COSTÓ
-- ------------------------------------------------------------
drop function if exists public.mover_ahorro(uuid, uuid, text, numeric, date, text);

create or replace function public.mover_ahorro(
  p_empresa     uuid,
  p_ahorro      uuid,
  p_tipo        text,
  p_monto       numeric,
  p_fecha       date default null,
  p_nota        text default '',
  p_monto_local numeric default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_saldo  numeric;
  v_zona   text;
  v_id     uuid;
  v_moneda text;
  v_propia text;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar esto.' using errcode = '42501';
  end if;

  if p_tipo not in ('aporte', 'retiro') then
    raise exception 'Solo se puede guardar o retirar.' using errcode = '22023';
  end if;

  if coalesce(p_monto, 0) <= 0 then
    raise exception 'El monto tiene que ser mayor que cero.' using errcode = '22023';
  end if;

  select public.saldo_ahorro(a.id), a.moneda into v_saldo, v_moneda
  from public.ahorros a where a.id = p_ahorro and a.empresa_id = p_empresa;

  if v_saldo is null then
    raise exception 'Ese fondo no existe en esta cuenta.' using errcode = 'P0002';
  end if;

  if p_tipo = 'retiro' and p_monto > v_saldo then
    raise exception 'Ese fondo tiene menos de lo que querés retirar.' using errcode = '22023';
  end if;

  select zona_horaria, moneda into v_zona, v_propia from public.empresas where id = p_empresa;

  -- (073) Un fondo en otra moneda necesita lo que costó en la de la cuenta:
  -- sin eso no se puede sumar a lo que guardaste este mes.
  if v_moneda is not null and coalesce(p_monto_local, 0) <= 0 then
    raise exception 'Escribí cuánto fue en %: sin eso no se puede sumar a tus números.', v_propia
      using errcode = '22023';
  end if;

  insert into public.movimientos_ahorro (empresa_id, ahorro_id, tipo, monto, monto_local, fecha, nota, creado_por)
  values (p_empresa, p_ahorro, p_tipo, p_monto,
          case when v_moneda is null then null else p_monto_local end,
          coalesce(p_fecha, (now() at time zone coalesce(v_zona, 'America/Asuncion'))::date),
          left(coalesce(p_nota, ''), 200), auth.uid())
  returning id into v_id;

  return jsonb_build_object(
    'id', v_id,
    'saldo', v_saldo + case when p_tipo = 'aporte' then p_monto else -p_monto end);
end $fn$;

revoke all on function public.mover_ahorro(uuid, uuid, text, numeric, date, text, numeric) from public, anon;
grant execute on function public.mover_ahorro(uuid, uuid, text, numeric, date, text, numeric) to authenticated;

-- ------------------------------------------------------------
-- 3. EL RESUMEN PERSONAL: SUMA EN LA MONEDA DE LA CUENTA
--
--    Mismo cuerpo que la 065, con lo marcado (073).
-- ------------------------------------------------------------
create or replace function public.resumen_personal(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_c            record;
  v_zona         text;
  v_hoy          date;
  v_entro        numeric := 0;
  v_salio        numeric := 0;
  v_cuotas       numeric := 0;
  v_fijos_falta  numeric := 0;
  v_ahorro_ciclo numeric := 0;
  v_ahorro_total numeric := 0;
  v_fiado_ciclo  numeric := 0;
  v_fiado_total  numeric := 0;
  v_dias         integer;
  v_plan         jsonb;
  v_sin_planear  numeric := 0;
  v_entradas     jsonb;
  v_salidas      jsonb;
  v_fondos       jsonb;
  v_de_donde     jsonb;
  v_esperado     numeric := 0;
  v_fijo_mes     numeric := 0;
  v_hubo_ingreso boolean := false;
  v_disponible   numeric;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'No tenés acceso a esta cuenta.' using errcode = '42501';
  end if;

  select zona_horaria into v_zona from public.empresas where id = p_empresa;
  v_hoy := (now() at time zone coalesce(v_zona, 'America/Asuncion'))::date;

  select * into v_c from public.ciclo_personal(p_empresa);

  select
    coalesce(sum(m.monto) filter (where m.tipo in ('ingreso', 'venta')), 0),
    coalesce(sum(m.monto) filter (where m.tipo = 'gasto'), 0),
    bool_or(m.tipo in ('ingreso', 'venta'))
  into v_entro, v_salio, v_hubo_ingreso
  from public.movimientos m
  where m.empresa_id = p_empresa
    and m.estado = 'activo'
    and m.fecha between v_c.desde and v_c.hasta;

  select coalesce(sum(d.monto_cuota), 0) into v_cuotas
  from public.deudas d
  where d.empresa_id = p_empresa
    and d.activa and d.saldo > 0
    and d.monto_cuota is not null
    and d.vence_el between v_hoy and v_c.hasta;

  select coalesce(sum(greatest(0, f.total - coalesce(g.gastado, 0))), 0)
  into v_fijos_falta
  from (
    select categoria, sum(importe) as total
    from public.gastos_fijos
    where empresa_id = p_empresa and activo
    group by categoria
  ) f
  left join lateral (
    select sum(m.monto) as gastado
    from public.movimientos m
    where m.empresa_id = p_empresa and m.estado = 'activo' and m.tipo = 'gasto'
      and m.categoria = f.categoria
      and m.fecha between v_c.desde and v_c.hasta
  ) g on true;

  select coalesce(sum(case when ma.tipo = 'aporte' then coalesce(ma.monto_local, ma.monto) else -coalesce(ma.monto_local, ma.monto) end), 0)
  into v_ahorro_ciclo
  from public.movimientos_ahorro ma
  where ma.empresa_id = p_empresa and ma.fecha between v_c.desde and v_c.hasta;

  select coalesce(sum(case when ma.tipo = 'aporte' then coalesce(ma.monto_local, ma.monto) else -coalesce(ma.monto_local, ma.monto) end), 0)
  into v_ahorro_total
  from public.movimientos_ahorro ma
  where ma.empresa_id = p_empresa;

  -- Lo cobrado de fiado en ESTE ciclo. `cobrar_fiado` (056) no crea
  -- movimiento a propósito, así que sin esto esa plata no aparecía en
  -- ningún cálculo.
  select coalesce(sum(f.monto) filter (where f.tipo = 'cobro'), 0)
  into v_fiado_ciclo
  from public.fiado f
  where f.empresa_id = p_empresa and f.fecha between v_c.desde and v_c.hasta;

  -- Lo que le deben en total, sumando a todos los que le deben. Mismo
  -- cálculo que `resumen_fiado()` (054), acá sin el desglose por persona
  -- porque este resumen ya tiene bastante.
  select coalesce(sum(case when f.tipo = 'fio' then f.monto else -f.monto end), 0)
  into v_fiado_total
  from public.fiado f
  where f.empresa_id = p_empresa;

  v_dias := greatest(1, (v_c.hasta - v_hoy) + 1);
  -- El fiado cobrado suma a lo disponible: es plata real en el bolsillo,
  -- aunque no haya sido «entro» (eso ya se explicó por qué no).
  v_disponible := v_entro - v_salio - v_cuotas - v_fijos_falta - v_ahorro_ciclo + v_fiado_ciclo;

  select
    coalesce(jsonb_agg(jsonb_build_object(
      'categoria', p.categoria,
      'planeado',  p.importe,
      'gastado',   coalesce(g.total, 0),
      'resta',     p.importe - coalesce(g.total, 0)
    ) order by p.categoria), '[]'::jsonb)
  into v_plan
  from public.presupuesto p
  left join lateral (
    select sum(m.monto) as total
    from public.movimientos m
    where m.empresa_id = p_empresa and m.estado = 'activo' and m.tipo = 'gasto'
      and m.categoria = p.categoria
      and m.fecha between v_c.desde and v_c.hasta
  ) g on true
  where p.empresa_id = p_empresa;

  select coalesce(sum(m.monto), 0) into v_sin_planear
  from public.movimientos m
  where m.empresa_id = p_empresa and m.estado = 'activo' and m.tipo = 'gasto'
    and m.fecha between v_c.desde and v_c.hasta
    and not exists (
      select 1 from public.presupuesto p
      where p.empresa_id = p_empresa and p.categoria = m.categoria);

  select
    coalesce(jsonb_agg(jsonb_build_object(
      'id', i.id, 'nombre', i.nombre, 'importe', i.importe,
      'dia_del_mes', i.dia_del_mes, 'principal', i.principal
    ) order by i.principal desc, i.importe desc), '[]'::jsonb),
    coalesce(sum(i.importe), 0)
  into v_entradas, v_esperado
  from public.ingresos_fijos i
  where i.empresa_id = p_empresa and i.activo;

  select
    coalesce(jsonb_agg(jsonb_build_object(
      'id', g.id, 'nombre', g.nombre, 'importe', g.importe,
      'categoria', g.categoria, 'dia_del_mes', g.dia_del_mes, 'notas', g.notas
    ) order by g.dia_del_mes nulls last, g.importe desc), '[]'::jsonb),
    coalesce(sum(g.importe), 0)
  into v_salidas, v_fijo_mes
  from public.gastos_fijos g
  where g.empresa_id = p_empresa and g.activo;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', a.id, 'nombre', a.nombre, 'meta', a.meta,
    'fecha_limite', a.fecha_limite,
    'saldo', s.saldo,
    -- (073) En qué moneda está el fondo (null = la de la cuenta) y cuánto
    -- costó en la moneda de la cuenta lo que tiene guardado.
    'moneda', a.moneda,
    'saldo_local', sl.saldo_local,
    'falta', case when a.meta is null then null
                  else greatest(0, a.meta - s.saldo) end,
    'dias_para_limite', case when a.fecha_limite is null then null
                             else (a.fecha_limite - v_hoy) end,
    'por_mes', case
                 when a.meta is null or a.fecha_limite is null then null
                 when a.meta - s.saldo <= 0 then 0
                 when a.fecha_limite < v_hoy then null
                 else round((a.meta - s.saldo)
                            / greatest(1, ceil((a.fecha_limite - v_hoy)::numeric / 30)), 2)
               end
  ) order by a.created_at), '[]'::jsonb)
  into v_fondos
  from public.ahorros a
  cross join lateral (select public.saldo_ahorro(a.id) as saldo) s
  cross join lateral (
    select coalesce(sum(case when ma.tipo = 'aporte' then coalesce(ma.monto_local, ma.monto) else -coalesce(ma.monto_local, ma.monto) end), 0) as saldo_local
    from public.movimientos_ahorro ma where ma.ahorro_id = a.id
  ) sl
  where a.empresa_id = p_empresa and a.activo;

  select coalesce(jsonb_agg(x order by (x->>'monto')::numeric desc), '[]'::jsonb)
  into v_de_donde
  from (
    select jsonb_build_object('categoria', m.categoria, 'monto', sum(m.monto)) as x
    from public.movimientos m
    where m.empresa_id = p_empresa and m.estado = 'activo'
      and m.tipo in ('ingreso', 'venta')
      and m.fecha between v_c.desde and v_c.hasta
    group by m.categoria
  ) t;

  return jsonb_build_object(
    'desde', v_c.desde,
    'hasta', v_c.hasta,
    'dia_cobro', v_c.dia_cobro,
    'dias_restantes', v_dias,
    'entro', v_entro,
    'salio', v_salio,
    'cuotas_por_vencer', v_cuotas,
    'fijos_por_pagar', v_fijos_falta,
    'ahorrado_en_el_ciclo', v_ahorro_ciclo,
    'ahorro_total', v_ahorro_total,
    'fiado_cobrado_en_el_ciclo', v_fiado_ciclo,
    'fiado_pendiente', v_fiado_total,
    'disponible', v_disponible,
    'por_dia', round(v_disponible / v_dias, 2),
    'plan', v_plan,
    'gastado_sin_planear', v_sin_planear,
    'ingresos_fijos', v_entradas,
    'gastos_fijos', v_salidas,
    'ahorros', v_fondos,
    'de_donde_vino', v_de_donde,
    'esperado', v_esperado,
    'fijo_mensual', v_fijo_mes,
    'cobro_pendiente', v_esperado > 0 and not coalesce(v_hubo_ingreso, false)
  );
end $fn$;

revoke all on function public.resumen_personal(uuid) from public, anon;
grant execute on function public.resumen_personal(uuid) to authenticated;

-- ------------------------------------------------------------
-- 4. EL AHORRO DEL PERÍODO (EXCEL): TAMBIÉN
--
--    Mismo cuerpo que la 030, con lo marcado (073).
-- ------------------------------------------------------------
create or replace function public.resumen_ahorro_periodo(
  p_empresa uuid,
  p_desde   date,
  p_hasta   date
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_aportado numeric := 0;
  v_retirado numeric := 0;
  v_fondos   jsonb;
begin
  -- Se lee con `es_admin` y no con `es_miembro`, igual que las tablas de
  -- ahorro desde la 026: cuánto guarda alguien no lo ve un vendedor.
  if not public.es_admin(p_empresa) then
    raise exception 'No tenés acceso a esta cuenta.' using errcode = '42501';
  end if;

  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  select
    coalesce(sum(coalesce(ma.monto_local, ma.monto)) filter (where ma.tipo = 'aporte'), 0),
    coalesce(sum(coalesce(ma.monto_local, ma.monto)) filter (where ma.tipo = 'retiro'), 0)
  into v_aportado, v_retirado
  from public.movimientos_ahorro ma
  where ma.empresa_id = p_empresa
    and ma.fecha between p_desde and p_hasta;

  -- Solo los fondos que se movieron en el período. Listar los quietos en cero
  -- alargaría la hoja sin decir nada: que un fondo no se haya tocado en marzo
  -- no es información, es ruido.
  select coalesce(jsonb_agg(x order by (x->>'neto')::numeric desc), '[]'::jsonb)
  into v_fondos
  from (
    select jsonb_build_object(
      'nombre',   a.nombre,
      'aportado', coalesce(sum(coalesce(ma.monto_local, ma.monto)) filter (where ma.tipo = 'aporte'), 0),
      'retirado', coalesce(sum(coalesce(ma.monto_local, ma.monto)) filter (where ma.tipo = 'retiro'), 0),
      'neto',     coalesce(sum(case when ma.tipo = 'aporte' then coalesce(ma.monto_local, ma.monto) else -coalesce(ma.monto_local, ma.monto) end), 0),
      -- El saldo del fondo a hoy, que es de otro recorte y por eso va con su
      -- propio nombre: la hoja lo rotula aparte para que nadie lo sume con
      -- las columnas del período.
      -- (073) En la moneda de la cuenta: la planilla suma y compara en una
      -- sola moneda. Para un fondo en dólares es lo que costó lo guardado.
      'saldo_hoy', (select coalesce(sum(case when m2.tipo = 'aporte' then coalesce(m2.monto_local, m2.monto)
                                        else -coalesce(m2.monto_local, m2.monto) end), 0)
                    from public.movimientos_ahorro m2 where m2.ahorro_id = a.id),
      'moneda', a.moneda
    ) as x
    from public.movimientos_ahorro ma
    join public.ahorros a on a.id = ma.ahorro_id
    where ma.empresa_id = p_empresa
      and ma.fecha between p_desde and p_hasta
    group by a.id, a.nombre, a.moneda
  ) t;

  return jsonb_build_object(
    'aportado', v_aportado,
    'retirado', v_retirado,
    'neto',     v_aportado - v_retirado,
    'por_fondo', v_fondos
  );
end $fn$;

revoke all on function public.resumen_ahorro_periodo(uuid, date, date) from public, anon;
grant execute on function public.resumen_ahorro_periodo(uuid, date, date) to authenticated;


-- ############################################################
-- ##  074_billetera.sql
-- ############################################################

-- ============================================================
-- ORDEN · Migración 074 · La billetera: cuánto hay en cada banco
--
-- LO QUE PIDIÓ MATÍAS (16/09/2026)
--
--   «Todas las personas tienen muchos bancos, no solamente un banco. En el
--    Banco Familiar recibe su sueldo, tiene un poquito más de plata en otro
--    banco, y así. Que puedan cargar cuánto saldo tiene cada banco.»
--
-- Y eligió que el saldo SE MUEVA CON LO QUE CARGA, no que se escriba a mano.
--
-- CÓMO SE MUEVE SOLO
--
-- Cada cuenta dice qué formas de pago entran en ella: «Efectivo» recibe lo
-- cobrado en efectivo; «Banco Familiar», las transferencias y la tarjeta.
-- Cuando se carga una venta, un gasto o un ingreso, un trigger mira su forma
-- de pago y lo anota en esa cuenta.
--
-- Así no hubo que tocar ninguna de las puertas por donde entra un
-- movimiento —la venta, el gasto a mano, la voz, la foto, el ingreso fijo,
-- el pago de una deuda—: todas terminan en `movimientos`, y ahí se resuelve.
--
--   SALDO = saldo con que se creó la cuenta
--         + lo que entró por ella (ventas e ingresos activos)
--         − lo que salió (gastos activos)
--         + ajustes y transferencias.
--
-- Lo cargado ANTES de crear la cuenta no cuenta: ese pasado ya está dentro
-- del saldo inicial que la persona escribió al crearla.
--
-- LO QUE NO HACE, Y HAY QUE DECIRLO
--
-- En Paraguay no hay forma de conectarse a los bancos. El saldo es el que
-- calcula Orden con lo que la persona carga, y puede no coincidir con el del
-- banco (una comisión, algo que se olvidó cargar). Para eso está «ajustar
-- saldo»: queda como un ajuste con fecha, no se reescribe la historia.
--
-- Solo el dueño y los administradores: cuánto hay en cada banco no lo ve un
-- vendedor.
-- ============================================================

-- ------------------------------------------------------------
-- 1. LAS CUENTAS
-- ------------------------------------------------------------
create table if not exists public.cuentas_dinero (
  id            uuid primary key default gen_random_uuid(),
  empresa_id    uuid not null references public.empresas (id) on delete cascade,
  nombre        text not null check (char_length(trim(nombre)) between 1 and 40),
  tipo          text not null default 'banco' check (tipo in ('banco', 'efectivo', 'billetera')),
  saldo_inicial numeric(14,2) not null default 0,
  -- Qué formas de pago caen acá. Cada forma, en una sola cuenta.
  metodos       text[] not null default '{}',
  activa        boolean not null default true,
  orden         smallint not null default 0,
  creada_por    uuid references auth.users (id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create index if not exists cuentas_dinero_empresa_idx on public.cuentas_dinero (empresa_id) where activa;

alter table public.cuentas_dinero enable row level security;
revoke all on public.cuentas_dinero from anon, authenticated;

-- ------------------------------------------------------------
-- 2. AJUSTES Y TRANSFERENCIAS
--
--    Una transferencia son dos filas con el mismo `par`: sale de una y entra
--    en la otra. Pasar plata del banco al bolsillo no es un gasto ni un
--    ingreso: no cambia cuánto tenés, cambia dónde.
-- ------------------------------------------------------------
create table if not exists public.ajustes_cuenta (
  id         uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas (id) on delete cascade,
  cuenta_id  uuid not null references public.cuentas_dinero (id) on delete cascade,
  tipo       text not null check (tipo in ('ajuste', 'transferencia')),
  monto      numeric(14,2) not null check (monto <> 0),
  par        uuid,
  fecha      date not null,
  nota       text not null default '' check (char_length(nota) <= 200),
  creado_por uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now()
);

create index if not exists ajustes_cuenta_idx on public.ajustes_cuenta (cuenta_id, fecha desc);

alter table public.ajustes_cuenta enable row level security;
revoke all on public.ajustes_cuenta from anon, authenticated;

-- ------------------------------------------------------------
-- 3. CADA MOVIMIENTO, EN SU CUENTA
-- ------------------------------------------------------------
alter table public.movimientos
  add column if not exists cuenta_id uuid references public.cuentas_dinero (id) on delete set null;

create index if not exists movimientos_cuenta_idx
  on public.movimientos (cuenta_id) where cuenta_id is not null;

create or replace function public.cuenta_de_metodo(p_empresa uuid, p_metodo text)
returns uuid language sql stable security definer set search_path = public as $fn$
  select c.id from public.cuentas_dinero c
  where c.empresa_id = p_empresa and c.activa and p_metodo = any (c.metodos)
  order by c.orden, c.created_at
  limit 1;
$fn$;

revoke all on function public.cuenta_de_metodo(uuid, text) from public, anon, authenticated;

create or replace function public.anotar_en_su_cuenta()
returns trigger language plpgsql security definer set search_path = public as $fn$
begin
  if tg_op = 'UPDATE' and new.metodo_pago is distinct from old.metodo_pago then
    -- Si se corrige la forma de pago, el movimiento se muda de cuenta.
    new.cuenta_id := public.cuenta_de_metodo(new.empresa_id, new.metodo_pago);
  elsif tg_op = 'UPDATE' and new.cuenta_id is distinct from old.cuenta_id
        and new.cuenta_id is not null
        and not exists (select 1 from public.cuentas_dinero c
                        where c.id = new.cuenta_id and c.empresa_id = new.empresa_id) then
    new.cuenta_id := old.cuenta_id;
  elsif tg_op = 'INSERT' then
    -- Una cuenta de OTRO negocio no se acepta aunque alguien arme el pedido a
    -- mano: sería meterle plata en el saldo de un desconocido.
    if new.cuenta_id is not null
       and not exists (select 1 from public.cuentas_dinero c
                       where c.id = new.cuenta_id and c.empresa_id = new.empresa_id) then
      new.cuenta_id := null;
    end if;
    if new.cuenta_id is null then
      new.cuenta_id := public.cuenta_de_metodo(new.empresa_id, new.metodo_pago);
    end if;
  end if;
  return new;
end $fn$;

revoke all on function public.anotar_en_su_cuenta() from public, anon, authenticated;

drop trigger if exists anotar_en_su_cuenta on public.movimientos;
create trigger anotar_en_su_cuenta
  before insert or update on public.movimientos
  for each row execute function public.anotar_en_su_cuenta();

-- ------------------------------------------------------------
-- 4. EL SALDO
-- ------------------------------------------------------------
create or replace function public.saldo_cuenta_dinero(p_cuenta uuid)
returns numeric language sql stable security definer set search_path = public as $fn$
  select c.saldo_inicial
       + coalesce((select sum(case when m.tipo = 'gasto' then -m.monto else m.monto end)
                   from public.movimientos m
                   where m.cuenta_id = c.id and m.empresa_id = c.empresa_id and m.estado = 'activo'), 0)
       + coalesce((select sum(a.monto) from public.ajustes_cuenta a where a.cuenta_id = c.id), 0)
  from public.cuentas_dinero c
  where c.id = p_cuenta;
$fn$;

revoke all on function public.saldo_cuenta_dinero(uuid) from public, anon, authenticated;

-- ------------------------------------------------------------
-- 5. LA BILLETERA ENTERA
-- ------------------------------------------------------------
create or replace function public.billetera(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_cuentas jsonb;
  v_zona    text;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede ver esto.' using errcode = '42501';
  end if;

  select coalesce(zona_horaria, 'America/Asuncion') into v_zona from public.empresas where id = p_empresa;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', c.id,
    'nombre', c.nombre,
    'tipo', c.tipo,
    'metodos', to_jsonb(c.metodos),
    'saldo', s.saldo,
    -- Lo que se movió este mes por esta cuenta, para que el número no esté solo.
    'entro_mes', coalesce(mes.entro, 0),
    'salio_mes', coalesce(mes.salio, 0)
  ) order by c.orden, c.created_at), '[]'::jsonb)
  into v_cuentas
  from public.cuentas_dinero c
  cross join lateral (select public.saldo_cuenta_dinero(c.id) as saldo) s
  left join lateral (
    select
      sum(m.monto) filter (where m.tipo <> 'gasto') as entro,
      sum(m.monto) filter (where m.tipo = 'gasto')  as salio
    from public.movimientos m
    where m.cuenta_id = c.id and m.estado = 'activo'
      and m.fecha >= date_trunc('month', (now() at time zone v_zona))::date
  ) mes on true
  where c.empresa_id = p_empresa and c.activa;

  return jsonb_build_object(
    'cuentas', v_cuentas,
    'total', coalesce((select sum((x->>'saldo')::numeric) from jsonb_array_elements(v_cuentas) x), 0)
  );
end $fn$;

revoke all on function public.billetera(uuid) from public, anon;
grant execute on function public.billetera(uuid) to authenticated;

-- ------------------------------------------------------------
-- 6. CREAR O EDITAR UNA CUENTA
--
--    El saldo inicial se escribe al crearla y después no se toca: una
--    corrección posterior es un ajuste con fecha (ver 7). Si se toca el
--    inicial, cambia todo el pasado sin dejar rastro.
--
--    Una forma de pago va a una sola cuenta: marcar «transferencia» en el
--    Itaú la saca del Familiar. Si no, cada cobro tendría dos casas.
-- ------------------------------------------------------------
create or replace function public.guardar_cuenta_dinero(
  p_empresa       uuid,
  p_nombre        text,
  p_tipo          text default 'banco',
  p_saldo_inicial numeric default 0,
  p_metodos       text[] default '{}',
  p_id            uuid default null
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_id      uuid;
  v_metodos text[];
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar esto.' using errcode = '42501';
  end if;

  if char_length(trim(coalesce(p_nombre, ''))) = 0 then
    raise exception 'Ponele un nombre: el del banco, «Efectivo», «Tigo Money».' using errcode = '22023';
  end if;

  if coalesce(p_tipo, '') not in ('banco', 'efectivo', 'billetera') then
    raise exception 'Ese tipo de cuenta no existe.' using errcode = '22023';
  end if;

  select coalesce(array_agg(distinct m), '{}') into v_metodos
  from unnest(coalesce(p_metodos, '{}')) m
  where m in ('efectivo', 'transferencia', 'tarjeta', 'credito', 'otro');

  if p_id is null then
    if (select count(*) from public.cuentas_dinero where empresa_id = p_empresa and activa) >= 20 then
      raise exception 'Ya tenés 20 cuentas. Archivá alguna antes de sumar otra.' using errcode = '22023';
    end if;

    insert into public.cuentas_dinero (empresa_id, nombre, tipo, saldo_inicial, metodos, orden, creada_por)
    values (p_empresa, trim(p_nombre), p_tipo, coalesce(p_saldo_inicial, 0), v_metodos,
            coalesce((select max(orden) + 1 from public.cuentas_dinero where empresa_id = p_empresa), 0),
            auth.uid())
    returning id into v_id;
  else
    update public.cuentas_dinero
    set nombre = trim(p_nombre), tipo = p_tipo, metodos = v_metodos, updated_at = now()
    where id = p_id and empresa_id = p_empresa and activa
    returning id into v_id;

    if v_id is null then
      raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
    end if;
  end if;

  -- Cada forma de pago, en una sola casa.
  update public.cuentas_dinero
  set metodos = array(select x from unnest(metodos) x where not (x = any (v_metodos))),
      updated_at = now()
  where empresa_id = p_empresa and id <> v_id and metodos && v_metodos;

  return v_id;
end $fn$;

revoke all on function public.guardar_cuenta_dinero(uuid, text, text, numeric, text[], uuid) from public, anon;
grant execute on function public.guardar_cuenta_dinero(uuid, text, text, numeric, text[], uuid) to authenticated;

-- ------------------------------------------------------------
-- 7. AJUSTAR EL SALDO A LO QUE DICE EL BANCO
-- ------------------------------------------------------------
create or replace function public.ajustar_saldo_cuenta(
  p_empresa    uuid,
  p_cuenta     uuid,
  p_saldo_real numeric,
  p_nota       text default ''
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_saldo numeric;
  v_dif   numeric;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar esto.' using errcode = '42501';
  end if;

  if p_saldo_real is null then
    raise exception 'Escribí cuánto dice tu banco que tenés.' using errcode = '22023';
  end if;

  if not exists (select 1 from public.cuentas_dinero where id = p_cuenta and empresa_id = p_empresa and activa) then
    raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
  end if;

  v_saldo := public.saldo_cuenta_dinero(p_cuenta);
  v_dif := round(p_saldo_real - v_saldo, 2);

  if v_dif <> 0 then
    insert into public.ajustes_cuenta (empresa_id, cuenta_id, tipo, monto, fecha, nota, creado_por)
    values (p_empresa, p_cuenta, 'ajuste', v_dif, public.hoy_empresa(p_empresa),
            left(coalesce(trim(p_nota), ''), 200), auth.uid());
  end if;

  return jsonb_build_object('ok', true, 'antes', v_saldo, 'ahora', p_saldo_real, 'diferencia', v_dif);
end $fn$;

revoke all on function public.ajustar_saldo_cuenta(uuid, uuid, numeric, text) from public, anon;
grant execute on function public.ajustar_saldo_cuenta(uuid, uuid, numeric, text) to authenticated;

-- ------------------------------------------------------------
-- 8. PASAR PLATA DE UNA CUENTA A OTRA
-- ------------------------------------------------------------
create or replace function public.transferir_entre_cuentas(
  p_empresa uuid,
  p_desde   uuid,
  p_hacia   uuid,
  p_monto   numeric,
  p_nota    text default ''
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_par uuid := gen_random_uuid();
  v_hoy date;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar esto.' using errcode = '42501';
  end if;

  if coalesce(p_monto, 0) <= 0 then
    raise exception 'El monto tiene que ser mayor que cero.' using errcode = '22023';
  end if;

  if p_desde = p_hacia then
    raise exception 'Elegí dos cuentas distintas.' using errcode = '22023';
  end if;

  if (select count(*) from public.cuentas_dinero
      where id in (p_desde, p_hacia) and empresa_id = p_empresa and activa) <> 2 then
    raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
  end if;

  v_hoy := public.hoy_empresa(p_empresa);

  insert into public.ajustes_cuenta (empresa_id, cuenta_id, tipo, monto, par, fecha, nota, creado_por)
  values
    (p_empresa, p_desde, 'transferencia', -p_monto, v_par, v_hoy, left(coalesce(trim(p_nota), ''), 200), auth.uid()),
    (p_empresa, p_hacia, 'transferencia',  p_monto, v_par, v_hoy, left(coalesce(trim(p_nota), ''), 200), auth.uid());

  return jsonb_build_object('ok', true, 'par', v_par);
end $fn$;

revoke all on function public.transferir_entre_cuentas(uuid, uuid, uuid, numeric, text) from public, anon;
grant execute on function public.transferir_entre_cuentas(uuid, uuid, uuid, numeric, text) to authenticated;

-- ------------------------------------------------------------
-- 9. SACAR UNA CUENTA
--
--    Sin historia se borra. Con historia se archiva: los movimientos viejos
--    siguen diciendo de dónde salieron, y deja de recibir los nuevos.
-- ------------------------------------------------------------
create or replace function public.quitar_cuenta_dinero(p_empresa uuid, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar esto.' using errcode = '42501';
  end if;

  if not exists (select 1 from public.cuentas_dinero where id = p_id and empresa_id = p_empresa) then
    raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
  end if;

  if exists (select 1 from public.movimientos where cuenta_id = p_id)
     or exists (select 1 from public.ajustes_cuenta where cuenta_id = p_id) then
    update public.cuentas_dinero set activa = false, metodos = '{}', updated_at = now()
    where id = p_id;
    return jsonb_build_object('ok', true, 'archivada', true);
  end if;

  delete from public.cuentas_dinero where id = p_id;
  return jsonb_build_object('ok', true, 'archivada', false);
end $fn$;

revoke all on function public.quitar_cuenta_dinero(uuid, uuid) from public, anon;
grant execute on function public.quitar_cuenta_dinero(uuid, uuid) to authenticated;


-- ############################################################
-- ##  075_cada_movimiento_su_cuenta.sql
-- ############################################################

-- ============================================================
-- 075 · EN QUÉ CUENTA ENTRÓ O DE CUÁL SALIÓ, ELEGIDO A MANO
-- ============================================================
--
-- La 074 hizo que cada movimiento caiga solo en la cuenta que recibe su
-- forma de pago. Alcanza cuando hay un banco: lo cobrado por transferencia
-- va ahí y listo. Con dos bancos ya no alcanza —«transferencia» no dice a
-- cuál de los dos— y Matías lo pidió explícito: «si tengo varias cuentas en
-- mi billetera, quiero elegir de qué banco salió, o si fue en efectivo».
--
-- Para los movimientos eso ya funciona sin tocar la base: el disparador
-- `anotar_en_su_cuenta` (074) respeta la `cuenta_id` que venga escrita y solo
-- la deduce de la forma de pago cuando llega vacía. Y si alguien manda la
-- cuenta de otro negocio, la descarta.
--
-- Lo que falta es el OTRO pedido: el sueldo. «El ingreso fijo normalmente es
-- un sueldo, y normalmente se cobra en un banco en específico.» Eso es parte
-- de la definición del ingreso, no de un movimiento suelto: se guarda una vez
-- y después cada cobro ya sabe dónde cae.
--
-- `on delete set null`: si la cuenta se archiva, el sueldo no se borra —
-- queda sin cuenta asignada, que es exactamente lo que pasó.

alter table public.ingresos_fijos
  add column if not exists cuenta_id uuid references public.cuentas_dinero (id) on delete set null;

comment on column public.ingresos_fijos.cuenta_id is
  'En qué cuenta de la billetera se cobra este ingreso. Null = sin definir.';

-- La versión de seis parámetros se borra en vez de dejarla al lado: con las
-- dos vivas, una llamada por nombre queda ambigua y PostgREST no sabe cuál
-- elegir.
drop function if exists public.guardar_ingreso_fijo(uuid, text, numeric, integer, boolean, uuid);

create or replace function public.guardar_ingreso_fijo(
  p_empresa   uuid,
  p_nombre    text,
  p_importe   numeric,
  p_dia       integer default 1,
  p_principal boolean default false,
  p_id        uuid default null,
  p_cuenta    uuid default null
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare v_id uuid;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar esto.' using errcode = '42501';
  end if;

  if char_length(trim(coalesce(p_nombre, ''))) = 0 then
    raise exception 'Ponele un nombre, para saber qué es cuando entre.' using errcode = '22023';
  end if;

  if coalesce(p_importe, 0) <= 0 then
    raise exception 'El monto tiene que ser mayor que cero.' using errcode = '22023';
  end if;

  -- Una cuenta de otro negocio no se acepta ni por error ni a propósito.
  if p_cuenta is not null and not exists (
    select 1 from public.cuentas_dinero c
    where c.id = p_cuenta and c.empresa_id = p_empresa
  ) then
    raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
  end if;

  -- Si este pasa a ser el principal, el anterior deja de serlo. Se hace
  -- ANTES de escribir, porque el índice único no admite dos.
  if coalesce(p_principal, false) then
    update public.ingresos_fijos
    set principal = false, updated_at = now()
    where empresa_id = p_empresa and principal
      and (p_id is null or id <> p_id);
  end if;

  if p_id is null then
    insert into public.ingresos_fijos (empresa_id, nombre, importe, dia_del_mes, principal, cuenta_id)
    values (p_empresa, trim(p_nombre), p_importe,
            least(greatest(coalesce(p_dia, 1), 1), 31), coalesce(p_principal, false), p_cuenta)
    returning id into v_id;
  else
    update public.ingresos_fijos
    set nombre = trim(p_nombre), importe = p_importe,
        dia_del_mes = least(greatest(coalesce(p_dia, 1), 1), 31),
        principal = coalesce(p_principal, false),
        cuenta_id = p_cuenta, updated_at = now()
    where id = p_id and empresa_id = p_empresa
    returning id into v_id;

    if v_id is null then
      raise exception 'Ese ingreso no existe en esta cuenta.' using errcode = 'P0002';
    end if;
  end if;

  return v_id;
end $fn$;

revoke all on function public.guardar_ingreso_fijo(uuid, text, numeric, integer, boolean, uuid, uuid)
  from public, anon;
grant execute on function public.guardar_ingreso_fijo(uuid, text, numeric, integer, boolean, uuid, uuid)
  to authenticated;

-- ------------------------------------------------------------
-- LAS CUENTAS, SOLO PARA ELEGIR UNA
-- ------------------------------------------------------------
--
-- `cuentas_dinero` no se lee directo desde el navegador (la 074 le revocó
-- todo) y `billetera()` calcula el saldo de cada cuenta, que acá no hace
-- falta: para llenar un selector alcanzan el nombre y el tipo. Esta devuelve
-- eso y nada más, y solo a quien administra la cuenta.
create or replace function public.cuentas_para_elegir(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_lista jsonb;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede ver esto.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'nombre', c.nombre, 'tipo', c.tipo)
                            order by c.orden, c.created_at), '[]'::jsonb)
  into v_lista
  from public.cuentas_dinero c
  where c.empresa_id = p_empresa and c.activa;

  return v_lista;
end $fn$;

revoke all on function public.cuentas_para_elegir(uuid) from public, anon;
grant execute on function public.cuentas_para_elegir(uuid) to authenticated;


-- ############################################################
-- ##  076_avisos_con_mas_fuerza.sql
-- ############################################################

-- ============================================================
-- 076 · LOS AVISOS DIARIOS, CON MÁS FUERZA
-- ============================================================
--
-- No hay widget de pantalla de inicio: eso pide una app nativa (Swift para
-- iPhone, Kotlin para Android) subida a cada tienda, y Orden es una PWA a
-- propósito —se instala en un minuto, sin pasar por ninguna revisión—. Es
-- una limitación real del sistema, no una que se resuelva con código.
--
-- Matías, de acuerdo: «por ahora metámosle más fuerza a los avisos, y
-- cuando subamos a las tiendas metemos los widgets». Esto es la primera
-- parte: los avisos de la mañana, la tarde y la noche (071) ahora también
-- dicen la racha de días seguidos, que es lo que en Duolingo hace que la app
-- se sienta presente sin necesitar un widget.
--
-- La racha ya se calculaba para el panel (`racha_empresa`, 008), pero esa
-- función exige `auth.uid()` porque la llama la persona con su sesión. Acá
-- la llama un cron con el rol de servicio, sin sesión de nadie: se repite el
-- mismo cálculo, sin la comprobación de sesión, adentro de esta función.

create or replace function public.avisos_del_dia()
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_res jsonb;
begin
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'empresa_id',  e.id,
      'nombre',      e.nombre,
      'moneda',      e.moneda,
      'tipo_cuenta', coalesce(e.tipo_cuenta, 'emprendedor'),
      -- La fecha de hoy EN LA ZONA DEL NEGOCIO: con ella se arma la clave
      -- de «una vez por día».
      'fecha',       z.hoy,
      'hoy', jsonb_build_object(
        'ventas', a.ventas_hoy, 'ingresos', a.ingresos_hoy, 'gastos', a.gastos_hoy,
        'ganancia', a.ventas_hoy + a.ingresos_hoy - a.costo_hoy - a.gastos_hoy, 'cargados', a.n_hoy),
      'ayer', jsonb_build_object(
        'ventas', a.ventas_ayer, 'ingresos', a.ingresos_ayer, 'gastos', a.gastos_ayer,
        'ganancia', a.ventas_ayer + a.ingresos_ayer - a.costo_ayer - a.gastos_ayer, 'cargados', a.n_ayer),
      -- Días seguidos cargando, la misma cuenta que ve el panel (008). Si
      -- hoy ya cargó algo, cuenta hasta hoy; si no, hasta ayer —que es
      -- justo lo que hace falta a la tarde para el empujón «no la cortés»—.
      'racha', jsonb_build_object('dias', r.dias, 'en_riesgo', r.en_riesgo),
      'destinatarios', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'user_id', mi.user_id, 'idioma', coalesce(p.idioma, 'es'))), '[]'::jsonb)
        from public.miembros mi
        left join public.preferencias p on p.user_id = mi.user_id
        where mi.empresa_id = e.id
          and mi.rol in ('propietario', 'admin')
          and coalesce(p.aviso_diario, true)
      )
    ) as x
    from public.empresas e
    cross join lateral (
      select (now() at time zone coalesce(e.zona_horaria, 'America/Asuncion'))::date as hoy
    ) z
    cross join lateral (
      select
        coalesce(sum(m.monto) filter (where m.fecha = z.hoy and m.tipo = 'venta'), 0)       as ventas_hoy,
        coalesce(sum(m.monto) filter (where m.fecha = z.hoy and m.tipo = 'ingreso'), 0)     as ingresos_hoy,
        coalesce(sum(m.monto) filter (where m.fecha = z.hoy and m.tipo = 'gasto'), 0)       as gastos_hoy,
        coalesce(sum(coalesce(m.costo_total, 0)) filter (where m.fecha = z.hoy and m.tipo = 'venta'), 0) as costo_hoy,
        count(*) filter (where m.fecha = z.hoy)::int                                       as n_hoy,
        coalesce(sum(m.monto) filter (where m.fecha = z.hoy - 1 and m.tipo = 'venta'), 0)   as ventas_ayer,
        coalesce(sum(m.monto) filter (where m.fecha = z.hoy - 1 and m.tipo = 'ingreso'), 0) as ingresos_ayer,
        coalesce(sum(m.monto) filter (where m.fecha = z.hoy - 1 and m.tipo = 'gasto'), 0)   as gastos_ayer,
        coalesce(sum(coalesce(m.costo_total, 0)) filter (where m.fecha = z.hoy - 1 and m.tipo = 'venta'), 0) as costo_ayer,
        count(*) filter (where m.fecha = z.hoy - 1)::int                                   as n_ayer
      from public.movimientos m
      where m.empresa_id = e.id and m.estado = 'activo'
        and m.fecha between z.hoy - 1 and z.hoy
    ) a
    cross join lateral (
      with dias as (
        select distinct m.fecha
        from public.movimientos m
        where m.empresa_id = e.id and m.estado = 'activo' and m.fecha <= z.hoy
      ),
      numeradas as (
        select fecha, (fecha - (row_number() over (order by fecha))::int) as isla
        from dias
      ),
      rachas as (
        select isla, count(*)::int as largo, max(fecha) as hasta
        from numeradas group by isla
      ),
      vigente as (
        select * from rachas where hasta in (z.hoy, z.hoy - 1) order by hasta desc limit 1
      )
      select
        coalesce((select largo from vigente), 0) as dias,
        -- En riesgo: la racha llega hasta ayer y hoy todavía no cargó nada.
        -- Sin racha (dias = 0) esto da false, que es lo correcto.
        coalesce((select hasta from vigente), z.hoy - 2) = z.hoy - 1 as en_riesgo
    ) r
    where (
        coalesce(e.tipo_cuenta, 'emprendedor') = 'personal'
        or public.rubro_cierra_el_dia(e.rubro, e.tipo_cuenta)
      )
      -- Una cuenta vencida no puede cargar: pedirle que cargue es mentirle.
      and public.puede_cargar(e.id)
      and (
        e.created_at > now() - interval '7 days'
        or exists (select 1 from public.movimientos m2
                   where m2.empresa_id = e.id and m2.created_at > now() - interval '30 days')
      )
  ) s;

  return v_res;
end $fn$;

revoke all on function public.avisos_del_dia() from public, anon, authenticated;
grant execute on function public.avisos_del_dia() to service_role;


-- ############################################################
-- ##  077_plan_basico.sql
-- ############################################################

-- ============================================================
-- 077 · EL PLAN BÁSICO: UN NEGOCIO DE UNA SOLA PERSONA
-- ============================================================
--
-- Hasta hoy un negocio tenía dos precios: Pro (190.000, hasta 3 personas) y
-- Premium (250.000, hasta 15). Los dos cobran por gente que muchos no
-- tienen: el que atiende solo su despensa, el que arregla celulares, el que
-- corta el pelo en su casa. A ese le estábamos cobrando vendedores que nunca
-- va a cargar.
--
-- Decisión de Matías: un tercer plan, **Básico**, a 110.000 Gs. Es el negocio
-- completo —ventas, gastos, fiado, agenda, billetera, reportes, Excel— con
-- una sola diferencia: **una sola persona**. Sin vendedores. Vale para todos
-- los rubros: comercio, servicios y oficios.
--
-- POR QUÉ `miembros = 1` Y NO UN CAMPO NUEVO
--
-- El tope de gente ya sale de `limites_plan()` y lo aplica `tope_de_miembros`
-- (048), que suma `tope_vendedores + 1` cuando la administración cobró
-- sillas. Con `miembros = 1` el plan Básico queda cerrado a una persona sin
-- tocar una sola función más, y si algún día alguien paga una silla suelta,
-- el mecanismo de siempre la habilita.

-- ------------------------------------------------------------
-- 1. LOS CHECKS CONOCEN EL PLAN NUEVO
-- ------------------------------------------------------------
alter table public.empresas      drop constraint if exists empresas_plan_check;
alter table public.suscripciones drop constraint if exists suscripciones_plan_check;
alter table public.precios       drop constraint if exists precios_plan_check;

alter table public.empresas
  add constraint empresas_plan_check check (plan in ('gratis', 'basico', 'pro', 'negocio'));

alter table public.suscripciones
  add constraint suscripciones_plan_check check (plan in ('gratis', 'basico', 'pro', 'negocio'));

alter table public.precios
  add constraint precios_plan_check check (plan in ('basico', 'pro', 'negocio'));

-- ------------------------------------------------------------
-- 2. QUÉ INCLUYE
--
--    Todo lo de un negocio, con una persona. Las capturas con IA van en 300
--    —la mitad de Pro— porque es el único costo que crece con el uso y el
--    plan sale casi la mitad. No es un recorte de funciones: es el mismo
--    Orden, para uno solo.
-- ------------------------------------------------------------
create or replace function public.limites_plan(p_plan text)
returns jsonb language sql immutable set search_path = public as $fn$
  select case coalesce(p_plan, 'gratis')
    when 'negocio' then jsonb_build_object(
      'capturas_mes', 3000, 'miembros', 15,
      'adjuntos', true, 'excel', true, 'avisos', true, 'escritura', true)
    when 'pro' then jsonb_build_object(
      'capturas_mes', 600, 'miembros', 3,
      'adjuntos', true, 'excel', true, 'avisos', true, 'escritura', true)
    when 'basico' then jsonb_build_object(
      'capturas_mes', 300, 'miembros', 1,
      'adjuntos', true, 'excel', true, 'avisos', true, 'escritura', true)
    else jsonb_build_object(
      'capturas_mes', 0, 'miembros', 1,
      'adjuntos', false, 'excel', true, 'avisos', true, 'escritura', false)
  end;
$fn$;

-- ------------------------------------------------------------
-- 3. EL PRECIO
--
--    Solo para cuentas de negocio: una cuenta personal ya es de una sola
--    persona y tiene su propio precio. El anual son once meses, como en los
--    otros dos planes.
-- ------------------------------------------------------------
insert into public.precios (plan, tipo_cuenta, moneda, periodo, importe) values
  ('basico', 'emprendedor', 'PYG', 'mensual',  110000),
  ('basico', 'emprendedor', 'PYG', 'anual',   1210000),
  ('basico', 'emprendedor', 'USD', 'mensual',      19),
  ('basico', 'emprendedor', 'USD', 'anual',       209)
on conflict (tipo_cuenta, plan, moneda, periodo) do nothing;


-- ############################################################
-- ##  078_descuento_por_racha.sql
-- ############################################################

-- ============================================================
-- 078 · EL DESCUENTO QUE SE GANA USANDO ORDEN EN LA PRUEBA
-- ============================================================
--
-- Idea de Matías: la prueba gratis no alcanza para que alguien tome el
-- hábito. Hay que darle un motivo para volver TODOS los días, y que ese
-- motivo valga plata: **si durante la prueba junta una racha de días
-- seguidos cargando, se lleva un descuento en su primer mes.**
--
--   · Negocio  → 8 días seguidos.
--   · Personal → 5 días seguidos (carga menos cosas por día; pedirle ocho
--     sería pedirle el doble de esfuerzo por el mismo premio).
--   · El premio: 18% del primer pago.
--
-- POR QUÉ NO SE GUARDA UN «YA LO GANÓ» EN NINGUNA COLUMNA
--
-- Un premio ganado no se puede perder, y una bandera se puede perder: un
-- borrado, un rollback, un movimiento anulado y la persona que cumplió ve
-- que su descuento desapareció. Acá se calcula de los hechos —qué días
-- tuvieron movimientos dentro de la ventana de la prueba— así que la
-- respuesta es siempre la misma y se puede auditar mirando la lista de
-- movimientos. Si mañana cambia el objetivo, los que ya lo cumplieron lo
-- siguen teniendo.
--
-- La ventana es la prueba y nada más: desde que se creó la suscripción hasta
-- que termina (o hasta hoy, si sigue corriendo). Cargar después de pagar ya
-- no suma — el descuento es para el primer mes.

-- ------------------------------------------------------------
-- 1. LOS NÚMEROS SE EDITAN, NO SE DESPLIEGAN
--
--    Mismo criterio que la comisión y el retiro mínimo: viven en
--    `ajustes_orden` para que cambiar la promo sea un UPDATE.
-- ------------------------------------------------------------
alter table public.ajustes_orden
  add column if not exists descuento_racha_porcentaje numeric(5,2) not null default 18
    check (descuento_racha_porcentaje >= 0 and descuento_racha_porcentaje <= 100),
  add column if not exists racha_objetivo_negocio integer not null default 8
    check (racha_objetivo_negocio between 1 and 60),
  add column if not exists racha_objetivo_personal integer not null default 5
    check (racha_objetivo_personal between 1 and 60);

comment on column public.ajustes_orden.descuento_racha_porcentaje is
  'Cuánto se descuenta del primer mes al que junta la racha durante la prueba.';

-- ------------------------------------------------------------
-- 2. CUÁNTO LLEVA Y CUÁNTO LE FALTA
--
--    `mejor` es la racha más larga DENTRO de la prueba, no la de hoy: quien
--    hizo ocho días y después se tomó el domingo no perdió lo ganado.
-- ------------------------------------------------------------
create or replace function public.descuento_por_racha(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_tipo     text;
  v_zona     text;
  v_desde    date;
  v_hasta    date;
  v_hoy      date;
  v_objetivo integer;
  v_pct      numeric;
  v_mejor    integer := 0;
  v_vigente  boolean := false;
  v_sus      record;
begin
  if not public.es_admin(p_empresa) and not public.es_superadmin() then
    raise exception 'Solo el dueño de la cuenta puede ver esto.' using errcode = '42501';
  end if;

  select coalesce(e.tipo_cuenta, 'emprendedor'), coalesce(e.zona_horaria, 'America/Asuncion')
  into v_tipo, v_zona
  from public.empresas e where e.id = p_empresa;

  if v_tipo is null then
    raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
  end if;

  select descuento_racha_porcentaje,
         case when v_tipo = 'personal' then racha_objetivo_personal else racha_objetivo_negocio end
  into v_pct, v_objetivo
  from public.ajustes_orden where unica;

  v_pct      := coalesce(v_pct, 18);
  v_objetivo := coalesce(v_objetivo, case when v_tipo = 'personal' then 5 else 8 end);
  v_hoy      := (now() at time zone v_zona)::date;

  select s.* into v_sus from public.suscripciones s where s.empresa_id = p_empresa;

  -- Sin suscripción no hay prueba de la que hablar.
  if v_sus.empresa_id is null then
    return jsonb_build_object('objetivo', v_objetivo, 'mejor', 0, 'faltan', v_objetivo,
                              'logrado', false, 'porcentaje', v_pct, 'vigente', false);
  end if;

  v_desde := (v_sus.created_at at time zone v_zona)::date;
  v_hasta := least(v_hoy, (coalesce(v_sus.prueba_fin, now()) at time zone v_zona)::date);
  -- Todavía se puede sumar mientras la prueba corre y no se pagó nada.
  v_vigente := v_sus.estado = 'prueba' and v_hoy <= (coalesce(v_sus.prueba_fin, now()) at time zone v_zona)::date;

  with dias as (
    select distinct m.fecha
    from public.movimientos m
    where m.empresa_id = p_empresa
      and m.estado = 'activo'
      and m.fecha between v_desde and v_hasta
  ),
  numeradas as (
    select fecha, (fecha - (row_number() over (order by fecha))::int) as isla from dias
  )
  select coalesce(max(largo), 0) into v_mejor
  from (select count(*)::int as largo from numeradas group by isla) r;

  return jsonb_build_object(
    'objetivo',   v_objetivo,
    'mejor',      v_mejor,
    'faltan',     greatest(0, v_objetivo - v_mejor),
    'logrado',    v_mejor >= v_objetivo,
    'porcentaje', v_pct,
    'vigente',    v_vigente
  );
end $fn$;

revoke all on function public.descuento_por_racha(uuid) from public, anon;
grant execute on function public.descuento_por_racha(uuid) to authenticated;

-- ------------------------------------------------------------
-- 3. LOS NÚMEROS DE LA PROMO, PARA LA PORTADA
--
--    La portada la lee alguien que todavía no tiene cuenta, así que esto es
--    público. No dice nada de nadie: solo cuánto se descuenta y cuántos días
--    hay que juntar. Si el número se cambia en `ajustes_orden`, la portada
--    lo dice al instante — sin desplegar.
-- ------------------------------------------------------------
create or replace function public.promo_de_la_prueba()
returns jsonb language sql stable security definer set search_path = public as $fn$
  select jsonb_build_object(
    'porcentaje', coalesce((select descuento_racha_porcentaje from public.ajustes_orden where unica), 18),
    'negocio',    coalesce((select racha_objetivo_negocio    from public.ajustes_orden where unica), 8),
    'personal',   coalesce((select racha_objetivo_personal   from public.ajustes_orden where unica), 5)
  );
$fn$;

grant execute on function public.promo_de_la_prueba() to anon, authenticated;


-- ############################################################
-- ##  079_descuento_por_constancia.sql
-- ############################################################

-- ============================================================
-- 079 · EL DESCUENTO QUE SE MANTIENE: RACHA VIVA, 20% MENOS
-- ============================================================
--
-- La 078 le puso premio a la prueba: junta la racha y tu PRIMER mes sale más
-- barato. Matías: «eso está bien para que arranque, pero después se acaba.
-- Si mantenés la racha de 30 días, siempre vas a tener el 20%». O sea: el
-- premio deja de ser de bienvenida y pasa a ser por constancia.
--
-- LAS DOS ETAPAS, UNA SOLA FUNCIÓN
--
-- Es el mismo trato contado en dos momentos de la vida de una cuenta, así
-- que `descuento_por_racha()` ahora contesta según dónde está parada:
--
--   · TODAVÍA NO PAGÓ (prueba, o prueba vencida sin pagar)
--     Objetivo corto —8 días un negocio, 5 una cuenta personal— y el premio
--     es del PRIMER mes. Se mira la MEJOR racha dentro de la prueba: una vez
--     ganado no se pierde, aunque después se tome un día.
--
--   · YA PAGA (suscripción activa)
--     Objetivo 30 días y el premio es 20% de cada renovación. Acá se mira la
--     racha VIVA, no la mejor: el premio es por sostenerla. Si la corta,
--     deja de tener descuento hasta que la vuelva a levantar. Eso es lo que
--     pidió: «si mantenés tu racha, siempre vas a tener el 20%».
--
-- La racha viva se cuenta igual que en el panel (`racha_empresa`, 008):
-- vale si llega hasta hoy o hasta ayer. Tiene que ser el MISMO número que la
-- persona ve en su pantalla — si el panel dice 31 y el descuento dice 30,
-- el que pierde es el descuento, porque nadie le cree.
--
-- El cobro sigue siendo a mano: esto le dice al cliente lo que se ganó y le
-- dice a la administración cuánto cobrar. Cuando entre la pasarela, el mismo
-- número se aplica solo al cobrar.

-- ------------------------------------------------------------
-- 1. LOS NÚMEROS DE LA SEGUNDA ETAPA
-- ------------------------------------------------------------
alter table public.ajustes_orden
  add column if not exists descuento_constancia_porcentaje numeric(5,2) not null default 20
    check (descuento_constancia_porcentaje >= 0 and descuento_constancia_porcentaje <= 100),
  add column if not exists racha_objetivo_constancia integer not null default 30
    check (racha_objetivo_constancia between 1 and 365);

comment on column public.ajustes_orden.descuento_constancia_porcentaje is
  'Cuánto se descuenta de cada renovación mientras la cuenta mantenga su racha viva.';

-- ------------------------------------------------------------
-- 2. EL DESCUENTO QUE CORRESPONDE HOY
-- ------------------------------------------------------------
create or replace function public.descuento_por_racha(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_tipo     text;
  v_zona     text;
  v_desde    date;
  v_hasta    date;
  v_hoy      date;
  v_objetivo integer;
  v_pct      numeric;
  v_mejor    integer := 0;
  v_vigente  boolean := false;
  v_fase     text;
  v_ajustes  record;
  v_sus      record;
begin
  if not public.es_admin(p_empresa) and not public.es_superadmin() then
    raise exception 'Solo el dueño de la cuenta puede ver esto.' using errcode = '42501';
  end if;

  select coalesce(e.tipo_cuenta, 'emprendedor'), coalesce(e.zona_horaria, 'America/Asuncion')
  into v_tipo, v_zona
  from public.empresas e where e.id = p_empresa;

  if v_tipo is null then
    raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
  end if;

  select * into v_ajustes from public.ajustes_orden where unica;
  v_hoy := (now() at time zone v_zona)::date;

  select s.* into v_sus from public.suscripciones s where s.empresa_id = p_empresa;

  -- Sin suscripción no hay nada que ofrecer todavía.
  if v_sus.empresa_id is null then
    return jsonb_build_object(
      'fase', 'prueba', 'objetivo', coalesce(v_ajustes.racha_objetivo_negocio, 8),
      'mejor', 0, 'faltan', coalesce(v_ajustes.racha_objetivo_negocio, 8),
      'logrado', false, 'porcentaje', coalesce(v_ajustes.descuento_racha_porcentaje, 18),
      'vigente', false);
  end if;

  -- Paga de verdad: el trato pasa a ser por constancia.
  v_fase := case
    when v_sus.estado = 'activa' and coalesce(v_sus.plan, 'gratis') <> 'gratis' then 'constancia'
    else 'prueba'
  end;

  if v_fase = 'constancia' then
    v_pct      := coalesce(v_ajustes.descuento_constancia_porcentaje, 20);
    v_objetivo := coalesce(v_ajustes.racha_objetivo_constancia, 30);
    -- La racha VIVA, la misma que muestra el panel: vale hasta ayer.
    with dias as (
      select distinct m.fecha
      from public.movimientos m
      where m.empresa_id = p_empresa and m.estado = 'activo' and m.fecha <= v_hoy
    ),
    numeradas as (
      select fecha, (fecha - (row_number() over (order by fecha))::int) as isla from dias
    ),
    rachas as (
      select isla, count(*)::int as largo, max(fecha) as hasta from numeradas group by isla
    )
    select coalesce((select largo from rachas where hasta in (v_hoy, v_hoy - 1)
                     order by hasta desc limit 1), 0)
    into v_mejor;
    -- Siempre se puede sostener: mientras pague, el trato sigue en pie.
    v_vigente := true;
  else
    v_pct      := coalesce(v_ajustes.descuento_racha_porcentaje, 18);
    v_objetivo := coalesce(
      case when v_tipo = 'personal' then v_ajustes.racha_objetivo_personal
           else v_ajustes.racha_objetivo_negocio end,
      case when v_tipo = 'personal' then 5 else 8 end);

    v_desde := (v_sus.created_at at time zone v_zona)::date;
    v_hasta := least(v_hoy, (coalesce(v_sus.prueba_fin, now()) at time zone v_zona)::date);
    v_vigente := v_sus.estado = 'prueba'
                 and v_hoy <= (coalesce(v_sus.prueba_fin, now()) at time zone v_zona)::date;

    -- La MEJOR de la prueba: lo ganado no se pierde.
    with dias as (
      select distinct m.fecha
      from public.movimientos m
      where m.empresa_id = p_empresa and m.estado = 'activo'
        and m.fecha between v_desde and v_hasta
    ),
    numeradas as (
      select fecha, (fecha - (row_number() over (order by fecha))::int) as isla from dias
    )
    select coalesce(max(largo), 0) into v_mejor
    from (select count(*)::int as largo from numeradas group by isla) r;
  end if;

  return jsonb_build_object(
    'fase',       v_fase,
    'objetivo',   v_objetivo,
    'mejor',      v_mejor,
    'faltan',     greatest(0, v_objetivo - v_mejor),
    'logrado',    v_mejor >= v_objetivo,
    'porcentaje', v_pct,
    'vigente',    v_vigente
  );
end $fn$;

revoke all on function public.descuento_por_racha(uuid) from public, anon;
grant execute on function public.descuento_por_racha(uuid) to authenticated;

-- ------------------------------------------------------------
-- 3. LA PROMO ENTERA, PARA LA PORTADA
--
--    Se le suman los números de la segunda etapa sin tocar los que ya lee
--    la portada: quien mira precios tiene que ver las dos mitades del trato
--    —el primer mes y los que siguen— antes de registrarse.
-- ------------------------------------------------------------
create or replace function public.promo_de_la_prueba()
returns jsonb language sql stable security definer set search_path = public as $fn$
  select jsonb_build_object(
    'porcentaje',            coalesce((select descuento_racha_porcentaje from public.ajustes_orden where unica), 18),
    'negocio',               coalesce((select racha_objetivo_negocio    from public.ajustes_orden where unica), 8),
    'personal',              coalesce((select racha_objetivo_personal   from public.ajustes_orden where unica), 5),
    'constancia_porcentaje', coalesce((select descuento_constancia_porcentaje from public.ajustes_orden where unica), 20),
    'constancia_dias',       coalesce((select racha_objetivo_constancia       from public.ajustes_orden where unica), 30)
  );
$fn$;

grant execute on function public.promo_de_la_prueba() to anon, authenticated;


-- ############################################################
-- ##  080_ahorrar_tambien_es_cargar.sql
-- ############################################################

-- ============================================================
-- 080 · AHORRAR TAMBIÉN ES CARGAR (Y UN SOLO LUGAR QUE LO DECIDE)
-- ============================================================
--
-- La racha contaba los días que tienen algún movimiento. Guardar plata en un
-- fondo de ahorro no es un movimiento: va a `movimientos_ahorro`, que es otra
-- tabla. Resultado: alguien que un martes abre Orden y manda Gs. 200.000 al
-- fondo «Viaje» hizo exactamente lo que queremos que haga, y a la noche
-- pierde la racha igual. Eso no se explica; se arregla.
--
-- Desde acá, un día cuenta si la persona registró ALGO ese día: un
-- movimiento (venta, gasto, ingreso) o un movimiento de ahorro.
--
-- POR QUÉ UNA FUNCIÓN Y NO TRES CONSULTAS IGUALES
--
-- La misma cuenta —«qué días cargó»— estaba escrita tres veces: en la racha
-- del panel (008), en el descuento (078/079) y en los avisos diarios (076).
-- Tres copias de una regla es la garantía de que el día que cambie, cambie
-- en dos lugares y no en tres: el panel diría 31 días y el descuento 30, y
-- el que pierde es el descuento, porque nadie le cree a un número que se
-- contradice con el de al lado. Ahora la regla vive en `dias_cargados()` y
-- las tres la llaman.
--
-- Retirar del fondo también cuenta. No es «portarse bien», pero es usar
-- Orden para registrar plata que se movió, que es el hábito que se premia.

-- ------------------------------------------------------------
-- 1. QUÉ DÍAS CUENTAN
--
--    Devuelve las fechas, sin repetir, hasta `p_hasta` inclusive. La usan
--    funciones que ya son SECURITY DEFINER, así que no la ejecuta nadie de
--    afuera: quien pregunta por una cuenta ajena lo hace por la función de
--    arriba, que sí comprueba permisos.
-- ------------------------------------------------------------
create or replace function public.dias_cargados(p_empresa uuid, p_hasta date)
returns setof date language sql stable security definer set search_path = public as $fn$
  select fecha
  from (
    select m.fecha
    from public.movimientos m
    where m.empresa_id = p_empresa and m.estado = 'activo' and m.fecha <= p_hasta
    union
    select a.fecha
    from public.movimientos_ahorro a
    where a.empresa_id = p_empresa and a.fecha <= p_hasta
  ) d
  group by fecha;
$fn$;

revoke all on function public.dias_cargados(uuid, date) from public, anon, authenticated;

comment on function public.dias_cargados(uuid, date) is
  'Los días en que la cuenta registró algo: movimientos y movimientos de ahorro. Única fuente de la racha.';

-- ------------------------------------------------------------
-- 2. LA RACHA DEL PANEL, SOBRE LA MISMA REGLA
-- ------------------------------------------------------------
create or replace function public.racha_empresa(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_hoy   date;
  v_ayer  date;
  v_res   jsonb;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  v_hoy  := public.hoy_empresa(p_empresa);
  v_ayer := v_hoy - 1;

  with dias as (
    select d.fecha from public.dias_cargados(p_empresa, v_hoy) d(fecha)
  ),
  numeradas as (
    select fecha, (fecha - (row_number() over (order by fecha))::int) as isla
    from dias
  ),
  rachas as (
    select isla, count(*)::int as largo, min(fecha) as desde, max(fecha) as hasta
    from numeradas group by isla
  ),
  vigente as (
    select * from rachas where hasta in (v_hoy, v_ayer) order by hasta desc limit 1
  )
  select jsonb_build_object(
    'hoy',           v_hoy,
    'dias',          coalesce((select largo from vigente), 0),
    'desde',         (select desde from vigente),
    'hoy_cargado',   exists (select 1 from dias where fecha = v_hoy),
    -- Solo está en riesgo si HAY algo que perder.
    'en_riesgo',     coalesce((select hasta from vigente), v_ayer - 1) = v_ayer,
    'mejor',         coalesce((select max(largo) from rachas), 0),
    'dias_activos',  (select count(*)::int from dias)
  ) into v_res;

  return v_res;
end $fn$;

-- ------------------------------------------------------------
-- 3. EL DESCUENTO, SOBRE LA MISMA REGLA
--
--    Igual que en la 079 —prueba: la mejor racha de la ventana; constancia:
--    la racha viva—, solo cambia de dónde salen los días.
-- ------------------------------------------------------------
create or replace function public.descuento_por_racha(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_tipo     text;
  v_zona     text;
  v_desde    date;
  v_hasta    date;
  v_hoy      date;
  v_objetivo integer;
  v_pct      numeric;
  v_mejor    integer := 0;
  v_vigente  boolean := false;
  v_fase     text;
  v_ajustes  record;
  v_sus      record;
begin
  if not public.es_admin(p_empresa) and not public.es_superadmin() then
    raise exception 'Solo el dueño de la cuenta puede ver esto.' using errcode = '42501';
  end if;

  select coalesce(e.tipo_cuenta, 'emprendedor'), coalesce(e.zona_horaria, 'America/Asuncion')
  into v_tipo, v_zona
  from public.empresas e where e.id = p_empresa;

  if v_tipo is null then
    raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
  end if;

  select * into v_ajustes from public.ajustes_orden where unica;
  v_hoy := (now() at time zone v_zona)::date;

  select s.* into v_sus from public.suscripciones s where s.empresa_id = p_empresa;

  if v_sus.empresa_id is null then
    return jsonb_build_object(
      'fase', 'prueba', 'objetivo', coalesce(v_ajustes.racha_objetivo_negocio, 8),
      'mejor', 0, 'faltan', coalesce(v_ajustes.racha_objetivo_negocio, 8),
      'logrado', false, 'porcentaje', coalesce(v_ajustes.descuento_racha_porcentaje, 18),
      'vigente', false);
  end if;

  v_fase := case
    when v_sus.estado = 'activa' and coalesce(v_sus.plan, 'gratis') <> 'gratis' then 'constancia'
    else 'prueba'
  end;

  if v_fase = 'constancia' then
    v_pct      := coalesce(v_ajustes.descuento_constancia_porcentaje, 20);
    v_objetivo := coalesce(v_ajustes.racha_objetivo_constancia, 30);
    with dias as (
      select d.fecha from public.dias_cargados(p_empresa, v_hoy) d(fecha)
    ),
    numeradas as (
      select fecha, (fecha - (row_number() over (order by fecha))::int) as isla from dias
    ),
    rachas as (
      select isla, count(*)::int as largo, max(fecha) as hasta from numeradas group by isla
    )
    select coalesce((select largo from rachas where hasta in (v_hoy, v_hoy - 1)
                     order by hasta desc limit 1), 0)
    into v_mejor;
    v_vigente := true;
  else
    v_pct      := coalesce(v_ajustes.descuento_racha_porcentaje, 18);
    v_objetivo := coalesce(
      case when v_tipo = 'personal' then v_ajustes.racha_objetivo_personal
           else v_ajustes.racha_objetivo_negocio end,
      case when v_tipo = 'personal' then 5 else 8 end);

    v_desde := (v_sus.created_at at time zone v_zona)::date;
    v_hasta := least(v_hoy, (coalesce(v_sus.prueba_fin, now()) at time zone v_zona)::date);
    v_vigente := v_sus.estado = 'prueba'
                 and v_hoy <= (coalesce(v_sus.prueba_fin, now()) at time zone v_zona)::date;

    with dias as (
      select d.fecha from public.dias_cargados(p_empresa, v_hasta) d(fecha)
      where d.fecha >= v_desde
    ),
    numeradas as (
      select fecha, (fecha - (row_number() over (order by fecha))::int) as isla from dias
    )
    select coalesce(max(largo), 0) into v_mejor
    from (select count(*)::int as largo from numeradas group by isla) r;
  end if;

  return jsonb_build_object(
    'fase',       v_fase,
    'objetivo',   v_objetivo,
    'mejor',      v_mejor,
    'faltan',     greatest(0, v_objetivo - v_mejor),
    'logrado',    v_mejor >= v_objetivo,
    'porcentaje', v_pct,
    'vigente',    v_vigente
  );
end $fn$;

-- ------------------------------------------------------------
-- 4. LOS AVISOS DIARIOS, SOBRE LA MISMA REGLA
--
--    Además de la racha, cambia una cosa más: el aviso de la tarde («todavía
--    no cargaste nada hoy») ya no se manda a quien hoy solo movió su ahorro.
--    Decirle «no cargaste nada» a alguien que acaba de guardar plata es
--    pedirle que ignore la notificación siguiente.
--
--    `cargados` sigue contando solo movimientos: es el número con el que se
--    arma el resumen de la noche, y un día de puro ahorro no tiene resumen
--    de ventas ni de gastos que contar. Por eso el ahorro va aparte.
-- ------------------------------------------------------------
create or replace function public.avisos_del_dia()
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_res jsonb;
begin
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'empresa_id',  e.id,
      'nombre',      e.nombre,
      'moneda',      e.moneda,
      'tipo_cuenta', coalesce(e.tipo_cuenta, 'emprendedor'),
      'fecha',       z.hoy,
      'hoy', jsonb_build_object(
        'ventas', a.ventas_hoy, 'ingresos', a.ingresos_hoy, 'gastos', a.gastos_hoy,
        'ganancia', a.ventas_hoy + a.ingresos_hoy - a.costo_hoy - a.gastos_hoy,
        'cargados', a.n_hoy,
        -- Movimientos de ahorro de hoy: no arman resumen, pero sí cuentan
        -- como «ya usó Orden hoy» para no empujarlo a la tarde.
        'ahorros', h.n_ahorro_hoy),
      'ayer', jsonb_build_object(
        'ventas', a.ventas_ayer, 'ingresos', a.ingresos_ayer, 'gastos', a.gastos_ayer,
        'ganancia', a.ventas_ayer + a.ingresos_ayer - a.costo_ayer - a.gastos_ayer,
        'cargados', a.n_ayer),
      'racha', jsonb_build_object('dias', r.dias, 'en_riesgo', r.en_riesgo),
      'destinatarios', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'user_id', mi.user_id, 'idioma', coalesce(p.idioma, 'es'))), '[]'::jsonb)
        from public.miembros mi
        left join public.preferencias p on p.user_id = mi.user_id
        where mi.empresa_id = e.id
          and mi.rol in ('propietario', 'admin')
          and coalesce(p.aviso_diario, true)
      )
    ) as x
    from public.empresas e
    cross join lateral (
      select (now() at time zone coalesce(e.zona_horaria, 'America/Asuncion'))::date as hoy
    ) z
    cross join lateral (
      select
        coalesce(sum(m.monto) filter (where m.fecha = z.hoy and m.tipo = 'venta'), 0)       as ventas_hoy,
        coalesce(sum(m.monto) filter (where m.fecha = z.hoy and m.tipo = 'ingreso'), 0)     as ingresos_hoy,
        coalesce(sum(m.monto) filter (where m.fecha = z.hoy and m.tipo = 'gasto'), 0)       as gastos_hoy,
        coalesce(sum(coalesce(m.costo_total, 0)) filter (where m.fecha = z.hoy and m.tipo = 'venta'), 0) as costo_hoy,
        count(*) filter (where m.fecha = z.hoy)::int                                       as n_hoy,
        coalesce(sum(m.monto) filter (where m.fecha = z.hoy - 1 and m.tipo = 'venta'), 0)   as ventas_ayer,
        coalesce(sum(m.monto) filter (where m.fecha = z.hoy - 1 and m.tipo = 'ingreso'), 0) as ingresos_ayer,
        coalesce(sum(m.monto) filter (where m.fecha = z.hoy - 1 and m.tipo = 'gasto'), 0)   as gastos_ayer,
        coalesce(sum(coalesce(m.costo_total, 0)) filter (where m.fecha = z.hoy - 1 and m.tipo = 'venta'), 0) as costo_ayer,
        count(*) filter (where m.fecha = z.hoy - 1)::int                                   as n_ayer
      from public.movimientos m
      where m.empresa_id = e.id and m.estado = 'activo'
        and m.fecha between z.hoy - 1 and z.hoy
    ) a
    cross join lateral (
      select count(*)::int as n_ahorro_hoy
      from public.movimientos_ahorro ma
      where ma.empresa_id = e.id and ma.fecha = z.hoy
    ) h
    cross join lateral (
      with dias as (
        select d.fecha from public.dias_cargados(e.id, z.hoy) d(fecha)
      ),
      numeradas as (
        select fecha, (fecha - (row_number() over (order by fecha))::int) as isla
        from dias
      ),
      rachas as (
        select isla, count(*)::int as largo, max(fecha) as hasta
        from numeradas group by isla
      ),
      vigente as (
        select * from rachas where hasta in (z.hoy, z.hoy - 1) order by hasta desc limit 1
      )
      select
        coalesce((select largo from vigente), 0) as dias,
        coalesce((select hasta from vigente), z.hoy - 2) = z.hoy - 1 as en_riesgo
    ) r
    where (
        coalesce(e.tipo_cuenta, 'emprendedor') = 'personal'
        or public.rubro_cierra_el_dia(e.rubro, e.tipo_cuenta)
      )
      and public.puede_cargar(e.id)
      and (
        e.created_at > now() - interval '7 days'
        or exists (select 1 from public.movimientos m2
                   where m2.empresa_id = e.id and m2.created_at > now() - interval '30 days')
        or exists (select 1 from public.movimientos_ahorro a2
                   where a2.empresa_id = e.id and a2.created_at > now() - interval '30 days')
      )
  ) s;

  return v_res;
end $fn$;

revoke all on function public.avisos_del_dia() from public, anon, authenticated;
grant execute on function public.avisos_del_dia() to service_role;


-- ############################################################
-- ##  081_el_calendario_de_los_avisos.sql
-- ############################################################

-- ============================================================
-- 081 · EL CALENDARIO DE LOS AVISOS, DESDE LA BASE
-- ============================================================
--
-- QUÉ PASABA
--
-- Matías: «no me llega ninguna notificación». Se revisó la base y el código
-- estaba bien: la persona tiene su iPhone registrado, `avisos_del_dia()`
-- devuelve a quién escribirle, y la frase se arma. Lo que faltaba era el
-- reloj. En `envios` solo hay avisos de tipo `diario_manana`: de la tarde y
-- de la noche no hay NINGUNO, y no es que no hubiera a quién escribirle —el
-- 18/09 tres cuentas no habían cargado nada a las tres de la tarde, y una
-- había cargado a la noche—. Las tareas de la tarde y de la noche nunca
-- corrieron. La de la mañana corrió una vez, 45 minutos tarde.
--
-- Eso es el plan gratuito de Vercel: las tareas programadas corren «alguna
-- vez dentro de la hora» y con un tope por cuenta. Hay seis en vercel.json y
-- se ejecuta una.
--
-- QUÉ SE HACE
--
-- El reloj se trae acá. Supabase tiene `pg_cron` —el planificador de
-- PostgreSQL— y `pg_net` —llamadas HTTP desde la base—, gratis y sin tope.
-- Cada horario llama a la misma ruta de siempre; no cambia nada del envío.
--
-- Los dos relojes pueden convivir sin peligro: cada aviso pasa por
-- `reservar_envio`, que garantiza uno por persona, momento y día. Si Vercel
-- llega primero, la corrida de la base no manda nada, y al revés. Por eso no
-- se toca vercel.json: si algún día el plan cambia, sobra, no estorba.
--
-- EL SECRETO NO ESTÁ ACÁ
--
-- Las rutas piden `Authorization: Bearer <CRON_SECRETO>`. Ese secreto no se
-- escribe en una migración —esto vive en git— ni lo maneja nadie más que
-- Matías: se guarda en el Vault de Supabase, con una sola instrucción que
-- corre él. Hasta que lo haga, `disparar_tarea` no llama a nada y lo dice.
--
--   select vault.create_secret('<el CRON_SECRETO de Vercel>', 'cron_secreto');
--
-- Para cambiarlo después:
--
--   select vault.update_secret(
--     (select id from vault.secrets where name = 'cron_secreto'),
--     '<el nuevo>');

-- ------------------------------------------------------------
-- 1. A QUÉ DIRECCIÓN LLAMAR
--
--    No es secreto —es la dirección pública del sitio— pero sí tiene que ser
--    editable: en un entorno de prueba apunta a otro lado.
-- ------------------------------------------------------------
alter table public.ajustes_orden
  add column if not exists sitio_url text not null default 'https://orden.com.py';

comment on column public.ajustes_orden.sitio_url is
  'De dónde cuelgan las rutas de tareas que dispara pg_cron (081).';

-- ------------------------------------------------------------
-- 2. LA LLAMADA
--
--    No la ejecuta nadie de afuera: `cron` corre como el dueño de la base.
--    Se revoca de todos igual, porque una función que hace pedidos HTTP con
--    un secreto adentro es exactamente lo que no se quiere dejar suelto.
-- ------------------------------------------------------------
create or replace function public.disparar_tarea(p_ruta text)
returns text language plpgsql security definer set search_path = public as $fn$
declare
  v_url     text;
  v_secreto text;
begin
  -- Solo rutas de tareas: si alguna vez esta función se alcanza desde otro
  -- lado, que no sirva para pedirle nada a ninguna otra dirección.
  if p_ruta !~ '^/api/tareas/[a-z-]+$' then
    raise exception 'Esa no es una ruta de tareas.' using errcode = '22023';
  end if;

  select coalesce(sitio_url, 'https://orden.com.py') into v_url
  from public.ajustes_orden where unica;
  v_url := coalesce(v_url, 'https://orden.com.py') || p_ruta;

  begin
    select decrypted_secret into v_secreto
    from vault.decrypted_secrets where name = 'cron_secreto';
  exception when others then
    v_secreto := null;
  end;

  if v_secreto is null or v_secreto = '' then
    -- Sin secreto la ruta contestaría 401. Mejor no llamar y dejar dicho por
    -- qué, que llenar el registro de pedidos rechazados.
    raise warning 'Falta el secreto «cron_secreto» en el Vault: no se llamó a %.', p_ruta;
    return 'sin secreto';
  end if;

  perform net.http_get(
    url     := v_url,
    headers := jsonb_build_object('Authorization', 'Bearer ' || v_secreto),
    timeout_milliseconds := 55000
  );

  return v_url;
end $fn$;

revoke all on function public.disparar_tarea(text) from public, anon, authenticated;

-- ------------------------------------------------------------
-- 3. LOS HORARIOS
--
--    En UTC, que es la hora de la base. Paraguay es UTC-3:
--
--      12:00 → 09:00, cómo fue ayer
--      18:00 → 15:00, «todavía no cargaste nada hoy»
--      23:30 → 20:30, cómo fue hoy
--
--    Va adentro de un bloque que se traga el error a propósito: las pruebas
--    corren estas migraciones sobre una base de mentira (pglite) que no
--    tiene pg_cron ni pg_net. Que ahí no se programe nada es lo correcto;
--    lo que no puede pasar es que reviente la suite entera.
-- ------------------------------------------------------------
do $cal$
declare
  v_horarios constant text[][] := array[
    ['orden-avisos-manana',  '0 12 * * *',  '/api/tareas/avisos-manana'],
    ['orden-avisos-tarde',   '0 18 * * *',  '/api/tareas/avisos-tarde'],
    ['orden-avisos-noche',   '30 23 * * *', '/api/tareas/avisos-noche'],
    ['orden-recordatorio',   '0 0 * * *',   '/api/tareas/recordatorio'],
    ['orden-turnos-manana',  '0 22 * * *',  '/api/tareas/turnos-manana'],
    ['orden-resumen-semanal','30 11 * * 1', '/api/tareas/resumen-semanal']
  ];
  v_i integer;
begin
  execute 'create extension if not exists pg_cron';
  execute 'create extension if not exists pg_net';

  for v_i in 1 .. array_length(v_horarios, 1) loop
    -- `schedule` con un nombre que ya existe lo reemplaza, así que volver a
    -- aplicar esta migración no duplica nada.
    execute format(
      'select cron.schedule(%L, %L, %L)',
      v_horarios[v_i][1],
      v_horarios[v_i][2],
      format('select public.disparar_tarea(%L)', v_horarios[v_i][3])
    );
  end loop;
exception when others then
  raise notice 'Sin pg_cron acá (%): los avisos no se programan en este entorno.', sqlerrm;
end $cal$;


-- ############################################################
-- ##  082_deshacer_un_pago_de_deuda.sql
-- ############################################################

-- ============================================================
-- 082 · DESHACER UN PAGO DE DEUDA QUE NO FUE
-- ============================================================
--
-- Matías: «pagué una deuda que en realidad no pagué. Borré el historial y me
-- seguía apareciendo como pagada». Las dos mitades del problema:
--
--   1. No había forma de anular un pago. `registrar_pago_deuda` baja el
--      saldo, suma una cuota, corre el vencimiento un mes y crea el gasto.
--      Nada de eso tenía vuelta atrás.
--   2. Borrar el movimiento a mano no alcanza y encima confunde: el saldo de
--      la deuda vive en `deudas.saldo`, no se recalcula de los pagos. El
--      gasto desaparecía y la deuda seguía saldada.
--
-- Anular un pago tiene que deshacer las cuatro cosas juntas o ninguna.
--
-- POR QUÉ SE GUARDA EL «ANTES» Y NO SE RECALCULA
--
-- El saldo se puede devolver sumando: es plata. El vencimiento no. Si el
-- pago dejó la deuda saldada, `vence_el` quedó en null, y de un null no se
-- deduce qué fecha había antes. Lo mismo con la cuota: solo se sumó si la
-- deuda tenía cuotas y faltaban, así que restar siempre uno sería inventar.
--
-- Por eso cada pago anota qué había antes de tocarlo. Es la misma idea que
-- el resto del sistema: guardar el hecho, no la conclusión. Los pagos
-- anteriores a esta migración no lo tienen, y ahí se hace lo mejor posible
-- —restar un mes si hay fecha, restar la cuota si hay cuotas— y se avisa en
-- la respuesta, para que la pantalla pueda pedir que revise el vencimiento.
--
-- EL GASTO SE ANULA, NO SE BORRA
--
-- `anular_movimiento` lo deja marcado con quién y cuándo. El saldo de la
-- cuenta cuenta solo los activos, así que la billetera vuelve sola a donde
-- estaba, y queda el rastro de que hubo un pago y se deshizo.

-- ------------------------------------------------------------
-- 1. QUÉ HABÍA ANTES DE ESTE PAGO
-- ------------------------------------------------------------
alter table public.pagos_deuda
  add column if not exists vence_antes   date,
  add column if not exists cuota_contada boolean;

comment on column public.pagos_deuda.vence_antes is
  'El vencimiento de la deuda antes de este pago, para poder deshacerlo (082).';
comment on column public.pagos_deuda.cuota_contada is
  'Si este pago sumó una cuota. Null en los pagos anteriores a la 082.';

-- ------------------------------------------------------------
-- 2. REGISTRAR UN PAGO, ANOTANDO EL ANTES
--
--    Igual que en la 015; lo único nuevo es que deja constancia de lo que
--    cambió, para que se pueda volver.
-- ------------------------------------------------------------
create or replace function public.registrar_pago_deuda(
  p_deuda       uuid,
  p_monto       numeric,
  p_fecha       date default null,
  p_crear_gasto boolean default true,
  p_metodo      text default 'efectivo',
  p_nota        text default ''
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_deuda      public.deudas;
  v_fecha      date;
  v_aplicado   numeric;
  v_movimiento uuid;
  v_pago       uuid;
  v_cuenta     boolean;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  select * into v_deuda from public.deudas where id = p_deuda;
  if v_deuda.id is null then
    raise exception 'Esa deuda no existe.' using errcode = 'P0002';
  end if;
  if not public.es_admin(v_deuda.empresa_id) then
    raise exception 'Solo el propietario o un administrador puede registrar pagos.' using errcode = '42501';
  end if;
  if coalesce(p_monto, 0) <= 0 then
    raise exception 'El pago tiene que ser mayor que cero.' using errcode = '22023';
  end if;
  if v_deuda.saldo <= 0 then
    raise exception 'Esa deuda ya está saldada.' using errcode = '22023';
  end if;

  v_fecha := coalesce(p_fecha, public.hoy_empresa(v_deuda.empresa_id));

  -- Nunca más de lo que falta.
  v_aplicado := least(p_monto, v_deuda.saldo);

  -- La misma condición que usa el update de abajo: se decide una vez y se
  -- guarda, para que deshacerlo no tenga que adivinarla.
  v_cuenta := v_deuda.cuotas_totales is not null
              and v_deuda.cuotas_pagadas < v_deuda.cuotas_totales;

  -- El gasto primero: si falla, no queremos haber bajado el saldo.
  if p_crear_gasto then
    insert into public.movimientos (
      empresa_id, tipo, fecha, descripcion, categoria,
      subtotal, descuento, monto, costo_total, metodo_pago, creado_por
    ) values (
      v_deuda.empresa_id, 'gasto', v_fecha,
      'Pago ' || v_deuda.nombre, 'Deudas',
      v_aplicado, 0, v_aplicado, 0, coalesce(p_metodo, 'efectivo'), auth.uid()
    )
    returning id into v_movimiento;
  end if;

  insert into public.pagos_deuda (
    deuda_id, empresa_id, monto, fecha, movimiento_id, nota, creado_por,
    vence_antes, cuota_contada
  )
  values (p_deuda, v_deuda.empresa_id, v_aplicado, v_fecha, v_movimiento,
          coalesce(left(p_nota, 300), ''), auth.uid(),
          v_deuda.vence_el, v_cuenta)
  returning id into v_pago;

  update public.deudas
  set saldo = saldo - v_aplicado,
      cuotas_pagadas = case when v_cuenta then cuotas_pagadas + 1 else cuotas_pagadas end,
      vence_el = case
        when saldo - v_aplicado <= 0 then null
        when vence_el is not null then vence_el + interval '1 month'
        else null
      end,
      updated_at = now()
  where id = p_deuda;

  return jsonb_build_object(
    'pago_id', v_pago,
    'aplicado', v_aplicado,
    'sobrante', greatest(p_monto - v_aplicado, 0),
    'saldo', v_deuda.saldo - v_aplicado,
    'saldada', (v_deuda.saldo - v_aplicado) <= 0,
    'movimiento_id', v_movimiento
  );
end $fn$;

-- ------------------------------------------------------------
-- 3. DESHACERLO
--
--    Devuelve `vencimiento_a_revisar` cuando el pago es viejo y no guardó su
--    «antes»: la deuda vuelve, pero la fecha puede no ser la que era y quien
--    la mira tiene que poder enterarse.
-- ------------------------------------------------------------
create or replace function public.anular_pago_deuda(p_pago uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_pago    public.pagos_deuda;
  v_deuda   public.deudas;
  v_revisar boolean := false;
  v_vence   date;
  v_cuotas  integer;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  select * into v_pago from public.pagos_deuda where id = p_pago;
  if v_pago.id is null then
    raise exception 'Ese pago no existe.' using errcode = 'P0002';
  end if;
  if not public.es_admin(v_pago.empresa_id) then
    raise exception 'Solo el propietario o un administrador puede deshacer un pago.' using errcode = '42501';
  end if;

  select * into v_deuda from public.deudas where id = v_pago.deuda_id;
  if v_deuda.id is null then
    raise exception 'Esa deuda no existe.' using errcode = 'P0002';
  end if;

  -- El vencimiento: el guardado, o lo mejor que se pueda deducir.
  if v_pago.vence_antes is not null then
    v_vence := v_pago.vence_antes;
  elsif v_deuda.vence_el is not null then
    v_vence := (v_deuda.vence_el - interval '1 month')::date;
    v_revisar := true;
  else
    v_vence := null;
    -- Quedó en null porque el pago la saldó, y no hay de dónde sacar la
    -- fecha vieja. La deuda vuelve sin vencimiento y se edita a mano.
    v_revisar := true;
  end if;

  -- La cuota: solo se descuenta la que este pago sumó.
  v_cuotas := case
    when v_pago.cuota_contada is true then greatest(0, v_deuda.cuotas_pagadas - 1)
    when v_pago.cuota_contada is false then v_deuda.cuotas_pagadas
    -- Pago viejo, sin constancia: se deshace lo que la 015 habría hecho.
    when v_deuda.cuotas_totales is not null then greatest(0, v_deuda.cuotas_pagadas - 1)
    else v_deuda.cuotas_pagadas
  end;

  -- El gasto se anula, no se borra: queda el rastro y la billetera vuelve
  -- sola, porque el saldo de una cuenta solo suma los movimientos activos.
  if v_pago.movimiento_id is not null then
    begin
      perform public.anular_movimiento(v_pago.movimiento_id, 'Se deshizo el pago de la deuda');
    exception when others then
      -- Ya estaba anulado, o lo borraron a mano. El resto se deshace igual:
      -- dejar la deuda pagada porque el gasto no estaba sería peor.
      null;
    end;
  end if;

  update public.deudas
  set saldo          = saldo + v_pago.monto,
      cuotas_pagadas = v_cuotas,
      vence_el       = v_vence,
      updated_at     = now()
  where id = v_deuda.id;

  delete from public.pagos_deuda where id = p_pago;

  return jsonb_build_object(
    'deuda_id',  v_deuda.id,
    'devuelto',  v_pago.monto,
    'saldo',     v_deuda.saldo + v_pago.monto,
    'vencimiento_a_revisar', v_revisar
  );
end $fn$;

revoke all on function public.anular_pago_deuda(uuid) from public, anon;
grant execute on function public.anular_pago_deuda(uuid) to authenticated;


-- ############################################################
-- ##  083_nada_queda_fuera_de_la_billetera.sql
-- ############################################################

-- ============================================================
-- 083 · LO QUE QUEDÓ FUERA DE LA BILLETERA SE VE Y SE ARREGLA
-- ============================================================
--
-- Matías: «entro a Orden y lo primero que veo es cuánto tengo. Si gasté de
-- mi Banco Atlas y no se me descuenta, eso no es lo que tengo». Tenía razón,
-- y el agujero es más ancho de lo que parecía.
--
-- CÓMO FUNCIONA EL REPARTO (074) Y DÓNDE SE ROMPE
--
-- Cada forma de pago vive en UNA sola cuenta: transferencia en el banco,
-- efectivo en la caja. Al cargar un movimiento, un trigger lo manda a la
-- cuenta que reclama esa forma de pago. Limpio, mientras todas las formas de
-- pago tengan casa. Cuando alguna no la tiene, el movimiento se guarda con
-- `cuenta_id` en null y **desaparece de la billetera sin decir nada**.
--
-- Pasa más de lo que uno creería. Mirando la base el 21/09:
--
--   · «otro» no estaba asignado a ninguna cuenta en NINGUNA empresa. Todo
--     gasto cargado con esa forma de pago caía al vacío.
--   · «Banco Atlas» existía con la lista de formas de pago vacía: una cuenta
--     que no puede recibir nada, ahí en la pantalla como si funcionara.
--   · Había Gs. 13.000.000 y Gs. 2.711.156 sin asignar en dos cuentas.
--
-- QUÉ SE HACE ACÁ
--
-- Nada de adivinar. Un movimiento que no se pudo repartir NO se manda a una
-- cuenta cualquiera para que el total cierre: eso sería cambiar un número
-- que miente por otro que miente distinto. Lo que se hace es **mostrarlo**,
-- con el monto y la cantidad, y dar la forma de asignarlo —de a uno o todos
-- juntos—. La plata la ubica quien sabe dónde estuvo.
--
-- El arreglo de raíz es de pantalla y va aparte: que al cargar un gasto se
-- pregunte siempre de qué cuenta sale.

-- ------------------------------------------------------------
-- 1. LA BILLETERA TAMBIÉN CUENTA LO QUE NO ESTÁ EN ELLA
--
--    Va adentro de `billetera()` y no en una función aparte para que sea
--    imposible dibujar el total sin tener a mano lo que falta: quien pinte
--    la pantalla lo recibe sí o sí.
-- ------------------------------------------------------------
create or replace function public.billetera(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_cuentas jsonb;
  v_zona    text;
  v_sueltos record;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede ver esto.' using errcode = '42501';
  end if;

  select coalesce(zona_horaria, 'America/Asuncion') into v_zona from public.empresas where id = p_empresa;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', c.id,
    'nombre', c.nombre,
    'tipo', c.tipo,
    'metodos', to_jsonb(c.metodos),
    'saldo', s.saldo,
    -- Lo que se movió este mes por esta cuenta, para que el número no esté solo.
    'entro_mes', coalesce(mes.entro, 0),
    'salio_mes', coalesce(mes.salio, 0)
  ) order by c.orden, c.created_at), '[]'::jsonb)
  into v_cuentas
  from public.cuentas_dinero c
  cross join lateral (select public.saldo_cuenta_dinero(c.id) as saldo) s
  left join lateral (
    select
      sum(m.monto) filter (where m.tipo <> 'gasto') as entro,
      sum(m.monto) filter (where m.tipo = 'gasto')  as salio
    from public.movimientos m
    where m.cuenta_id = c.id and m.estado = 'activo'
      and m.fecha >= date_trunc('month', (now() at time zone v_zona))::date
  ) mes on true
  where c.empresa_id = p_empresa and c.activa;

  -- Lo que se cargó y no llegó a ninguna cuenta. El neto y no la suma a
  -- secas: un gasto de 100 y un ingreso de 100 sin asignar no son 200 de
  -- desajuste, son cero.
  select count(*)::int as cantidad,
         coalesce(sum(case when m.tipo = 'gasto' then -m.monto else m.monto end), 0) as neto,
         min(m.fecha) as desde
  into v_sueltos
  from public.movimientos m
  where m.empresa_id = p_empresa and m.estado = 'activo' and m.cuenta_id is null;

  return jsonb_build_object(
    'cuentas', v_cuentas,
    'total', coalesce((select sum((x->>'saldo')::numeric) from jsonb_array_elements(v_cuentas) x), 0),
    'sin_cuenta', jsonb_build_object(
      'cantidad', coalesce(v_sueltos.cantidad, 0),
      'neto',     coalesce(v_sueltos.neto, 0),
      'desde',    v_sueltos.desde
    ),
    -- Formas de pago que no tienen dónde caer. Con esto la pantalla puede
    -- decir «arreglá esto» en vez de esperar a que la plata se pierda.
    'metodos_sin_cuenta', (
      select coalesce(jsonb_agg(m order by m), '[]'::jsonb)
      from unnest(array['efectivo', 'transferencia', 'tarjeta', 'credito', 'otro']) m
      where exists (select 1 from public.cuentas_dinero c2
                    where c2.empresa_id = p_empresa and c2.activa)
        and not exists (select 1 from public.cuentas_dinero c3
                        where c3.empresa_id = p_empresa and c3.activa and m = any (c3.metodos))
    )
  );
end $fn$;

-- ------------------------------------------------------------
-- 2. LA LISTA DE LO QUE QUEDÓ SUELTO
--
--    Con la forma de pago adentro: es el dato que le dice a la persona de
--    qué cuenta salió realmente («fue transferencia» → fue del banco).
-- ------------------------------------------------------------
create or replace function public.movimientos_sin_cuenta(p_empresa uuid, p_limite integer default 100)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_res jsonb;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede ver esto.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', x.id, 'fecha', x.fecha, 'tipo', x.tipo, 'descripcion', x.descripcion,
    'categoria', x.categoria, 'monto', x.monto, 'metodo_pago', x.metodo_pago
  ) order by x.fecha desc, x.created_at desc), '[]'::jsonb)
  into v_res
  from (
    select m.id, m.fecha, m.tipo, m.descripcion, m.categoria, m.monto, m.metodo_pago, m.created_at
    from public.movimientos m
    where m.empresa_id = p_empresa and m.estado = 'activo' and m.cuenta_id is null
    order by m.fecha desc, m.created_at desc
    limit greatest(1, least(coalesce(p_limite, 100), 500))
  ) x;

  return v_res;
end $fn$;

revoke all on function public.movimientos_sin_cuenta(uuid, integer) from public, anon;
grant execute on function public.movimientos_sin_cuenta(uuid, integer) to authenticated;

-- ------------------------------------------------------------
-- 3. PONERLE CUENTA A LO QUE NO LA TIENE
--
--    Solo mueve lo que está suelto. Un movimiento que YA tiene cuenta no se
--    toca desde acá: cambiarle la cuenta a algo que ya cuadró es corregir un
--    error distinto, y para eso está editar el movimiento.
-- ------------------------------------------------------------
create or replace function public.asignar_cuenta_a_sueltos(
  p_empresa uuid,
  p_cuenta  uuid,
  p_movimiento uuid default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_filas integer;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar esto.' using errcode = '42501';
  end if;

  if not exists (select 1 from public.cuentas_dinero c
                 where c.id = p_cuenta and c.empresa_id = p_empresa and c.activa) then
    raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
  end if;

  update public.movimientos m
  set cuenta_id = p_cuenta
  where m.empresa_id = p_empresa
    and m.estado = 'activo'
    and m.cuenta_id is null
    and (p_movimiento is null or m.id = p_movimiento);

  get diagnostics v_filas = row_count;

  return jsonb_build_object('asignados', v_filas, 'saldo', public.saldo_cuenta_dinero(p_cuenta));
end $fn$;

revoke all on function public.asignar_cuenta_a_sueltos(uuid, uuid, uuid) from public, anon;
grant execute on function public.asignar_cuenta_a_sueltos(uuid, uuid, uuid) to authenticated;

-- ------------------------------------------------------------
-- 4. EL SELECTOR TIENE QUE PODER DECIR A DÓNDE VA A IR LA PLATA
--
--    Sin las formas de pago de cada cuenta, la pantalla puede ofrecer
--    «automática» pero no puede decir qué significa. Y «automática» sin
--    decir a dónde es exactamente el agujero de esta migración: la persona
--    elige confiando y la plata se va a ningún lado.
-- ------------------------------------------------------------
create or replace function public.cuentas_para_elegir(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_lista jsonb;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede ver esto.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
                    'id', c.id, 'nombre', c.nombre, 'tipo', c.tipo,
                    'metodos', to_jsonb(c.metodos))
                            order by c.orden, c.created_at), '[]'::jsonb)
  into v_lista
  from public.cuentas_dinero c
  where c.empresa_id = p_empresa and c.activa;

  return v_lista;
end $fn$;


-- ############################################################
-- ##  084_prestar_plata_sale_de_una_cuenta.sql
-- ############################################################

-- ============================================================
-- 084 · PRESTAR PLATA SALE DE UNA CUENTA (Y NO ES UN GASTO)
-- ============================================================
--
-- Matías: «el fiado puede ser prestarle plata de tu billetera a alguien. Yo
-- le presté 300.000 y se los transferí de mi banco. Tendría que poder elegir
-- de cuál banco lo debité, así se actualiza el saldo que tengo realmente. O
-- el fiado puede ser solo porque te debe: tiene que estar la opción de
-- «¿querés debitar de tu billetera o dejamos así nomás?»».
--
-- Son dos cosas distintas que hoy se anotaban igual:
--
--   · FIASTE UNA VENTA. Entregaste mercadería, no plata. De tus cuentas no
--     salió nada, y está bien que el saldo no se mueva.
--   · PRESTASTE PLATA. Salió de una cuenta tuya de verdad. Que el saldo no
--     baje es mentirle a la persona sobre cuánto tiene.
--
-- POR QUÉ NO SE REGISTRA COMO GASTO
--
-- Sería lo fácil: un gasto baja el saldo y listo. Pero prestar plata NO es
-- un gasto, es la misma plata cambiada de lugar —de tu banco a «lo que me
-- deben»—. Anotarlo como gasto le inflaría los gastos del mes y le bajaría
-- la ganancia neta por algo que no perdió. Ese es justamente el número que
-- Matías ya vio raro («me aparece en negativo cuando no tenía nada que ver»).
--
-- Va como un ajuste de cuenta, que es lo que mueve el saldo sin tocar las
-- ventas ni los gastos. Con su propio tipo, `prestamo`, para que la fila
-- diga qué es y no se confunda con una corrección a mano.
--
-- LO QUE ESTA MIGRACIÓN NO RESUELVE
--
-- Cuando el cliente devuelve la plata, `cobrar_fiado` la registra como «otro
-- ingreso». Para una venta fiada eso es correcto —la plata entra recién ahí—
-- pero para un préstamo devuelto no: estás recuperando lo tuyo, no ganando.
-- Se deja así a propósito: un cobro se hace contra el total del cliente, que
-- puede mezclar ventas fiadas y préstamos, y repartirlo entre los dos es una
-- decisión de producto que hay que tomar con Matías, no adivinar acá.

-- ------------------------------------------------------------
-- 1. UN AJUSTE PUEDE SER UN PRÉSTAMO
-- ------------------------------------------------------------
alter table public.ajustes_cuenta drop constraint if exists ajustes_cuenta_tipo_check;
alter table public.ajustes_cuenta
  add constraint ajustes_cuenta_tipo_check
  check (tipo in ('ajuste', 'transferencia', 'prestamo'));

-- ------------------------------------------------------------
-- 2. EL FIADO RECUERDA DE DÓNDE SALIÓ LA PLATA
--
--    En null cuando no salió de ningún lado, que es el caso de una venta
--    fiada. No es lo mismo «no se eligió cuenta» que «no salió plata»: acá
--    significan lo mismo a propósito, porque si no salió de una cuenta el
--    saldo no tiene por qué moverse.
-- ------------------------------------------------------------
alter table public.fiado
  add column if not exists cuenta_id uuid references public.cuentas_dinero (id) on delete set null;

comment on column public.fiado.cuenta_id is
  'De qué cuenta salió la plata prestada. Null si fue una venta fiada: ahí no salió plata (084).';

-- ------------------------------------------------------------
-- 3. ANOTAR: CON CUENTA ES PRÉSTAMO, SIN CUENTA ES FIADO
--
--    La firma vieja se borra antes de crear la nueva. Si quedaran las dos,
--    llamarla con cinco argumentos sería ambiguo y PostgreSQL rechazaría la
--    llamada: la pantalla dejaría de poder anotar nada.
-- ------------------------------------------------------------
drop function if exists public.anotar_fiado(uuid, uuid, numeric, text, date);

create or replace function public.anotar_fiado(
  p_empresa  uuid,
  p_cliente  uuid,
  p_monto    numeric,
  p_concepto text default '',
  p_fecha    date default null,
  p_cuenta   uuid default null
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_id     uuid;
  v_fecha  date;
  v_nombre text;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if coalesce(p_monto, 0) <= 0 then
    raise exception 'El monto tiene que ser mayor que cero.' using errcode = '22023';
  end if;

  select nombre into v_nombre from public.clientes
  where id = p_cliente and empresa_id = p_empresa;
  if v_nombre is null then
    raise exception 'Ese cliente no es de esta cuenta.' using errcode = 'P0002';
  end if;

  -- Tocar el saldo de una cuenta es cosa de quien administra la plata, no de
  -- cualquiera que pueda anotar un fiado.
  if p_cuenta is not null then
    if not public.es_admin(p_empresa) then
      raise exception 'Solo el dueño de la cuenta puede sacar plata de la billetera.' using errcode = '42501';
    end if;
    if not exists (select 1 from public.cuentas_dinero c
                   where c.id = p_cuenta and c.empresa_id = p_empresa and c.activa) then
      raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
    end if;
  end if;

  v_fecha := coalesce(p_fecha, public.hoy_empresa(p_empresa));

  insert into public.fiado (empresa_id, cliente_id, tipo, monto, fecha, concepto, cuenta_id, creado_por)
  values (p_empresa, p_cliente, 'fio', p_monto, v_fecha,
          left(coalesce(p_concepto, ''), 200), p_cuenta, auth.uid())
  returning id into v_id;

  -- La plata salió: el saldo baja. Como ajuste y no como gasto, porque no
  -- perdiste esa plata, la prestaste.
  if p_cuenta is not null then
    insert into public.ajustes_cuenta (empresa_id, cuenta_id, tipo, monto, fecha, nota, creado_por)
    values (p_empresa, p_cuenta, 'prestamo', -p_monto, v_fecha,
            left('Le prestaste a ' || v_nombre, 200), auth.uid());
  end if;

  return v_id;
end $fn$;

revoke all on function public.anotar_fiado(uuid, uuid, numeric, text, date, uuid) from public, anon;
grant execute on function public.anotar_fiado(uuid, uuid, numeric, text, date, uuid) to authenticated;

-- ------------------------------------------------------------
-- 4. Y COBRAR ENTRA EN LA CUENTA QUE SE ELIJA
--
--    Matías: «me puede pagar por transferencia, y yo elijo el banco al que
--    me transfirió, así ya me aparece actualizado en mi billetera».
--
--    OJO CON CÓMO SE ARREGLA ESTO. La 056 sacó a propósito el ingreso que
--    creaba el cobro, porque inflaba la ganancia: una venta fiada de 500.000
--    se contaba el día de la venta y otra vez el día del cobro. Volver a
--    crear ese movimiento para mover el saldo sería revertir ese arreglo y
--    devolverle al negocio una ganancia que no tuvo.
--
--    Va por el mismo camino que el préstamo, y por el mismo motivo: un
--    ajuste de cuenta mueve el saldo SIN tocar ventas, ingresos ni ganancia.
--    Queda simétrico y se lee solo:
--
--      · prestar  → ajuste  −monto  (bajó tu plata, no fue un gasto)
--      · cobrar   → ajuste  +monto  (subió tu plata, no fue una ganancia)
--
--    Sin cuenta elegida no se toca ningún saldo, igual que hasta ahora: si
--    te pagaron en efectivo y no llevás caja en Orden, nada que mover.
-- ------------------------------------------------------------
drop function if exists public.cobrar_fiado(uuid, uuid, numeric, text, date);

create or replace function public.cobrar_fiado(
  p_empresa uuid,
  p_cliente uuid,
  p_monto   numeric,
  p_metodo  text default 'efectivo',
  p_fecha   date default null,
  p_cuenta  uuid default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_saldo  numeric;
  v_nombre text;
  v_id     uuid;
  v_debe   text;
  v_fecha  date;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if coalesce(p_monto, 0) <= 0 then
    raise exception 'El monto tiene que ser mayor que cero.' using errcode = '22023';
  end if;

  select nombre into v_nombre from public.clientes
  where id = p_cliente and empresa_id = p_empresa
  for update;
  if v_nombre is null then
    raise exception 'Ese cliente no es de esta cuenta.' using errcode = 'P0002';
  end if;

  if coalesce(p_metodo, '') not in ('efectivo', 'transferencia', 'tarjeta', 'otro') then
    raise exception 'Esa forma de cobro no es válida.' using errcode = '22023';
  end if;

  -- Decir en qué cuenta entró es administrar la billetera, igual que sacar
  -- plata de ella para prestarla.
  if p_cuenta is not null then
    if not public.es_admin(p_empresa) then
      raise exception 'Solo el dueño de la cuenta puede elegir en qué cuenta entra.' using errcode = '42501';
    end if;
    if not exists (select 1 from public.cuentas_dinero c
                   where c.id = p_cuenta and c.empresa_id = p_empresa and c.activa) then
      raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
    end if;
  end if;

  v_saldo := public.saldo_fiado(p_cliente);
  if v_saldo <= 0 then
    raise exception '% no te debe nada.', v_nombre using errcode = '22023';
  end if;

  if p_monto > v_saldo then
    -- «600.000» y no «600000.00»: esto lo lee una persona.
    v_debe := case when v_saldo = trunc(v_saldo)
                   then replace(to_char(v_saldo, 'FM999,999,999,990'), ',', '.')
                   else v_saldo::text end;
    raise exception '% te debe %, no podés cobrarle más que eso.', v_nombre, v_debe
      using errcode = '22023';
  end if;

  v_fecha := coalesce(p_fecha, public.hoy_empresa(p_empresa));

  insert into public.fiado (
    empresa_id, cliente_id, tipo, monto, fecha, concepto, metodo, cuenta_id, creado_por
  ) values (
    p_empresa, p_cliente, 'cobro', p_monto, v_fecha,
    'Pago recibido', p_metodo, p_cuenta, auth.uid()
  )
  returning id into v_id;

  if p_cuenta is not null then
    insert into public.ajustes_cuenta (empresa_id, cuenta_id, tipo, monto, fecha, nota, creado_por)
    values (p_empresa, p_cuenta, 'prestamo', p_monto, v_fecha,
            left('Te pagó ' || v_nombre, 200), auth.uid());
  end if;

  return jsonb_build_object('id', v_id, 'saldo', public.saldo_fiado(p_cliente));
end $fn$;

revoke all on function public.cobrar_fiado(uuid, uuid, numeric, text, date, uuid) from public, anon;
grant execute on function public.cobrar_fiado(uuid, uuid, numeric, text, date, uuid) to authenticated;


-- ############################################################
-- ##  085_el_disponible_sale_de_la_plata_real.sql
-- ############################################################

-- ============================================================
-- 085 · EL DISPONIBLE SALE DE LA PLATA QUE TENÉS DE VERDAD
-- ============================================================
--
-- Matías: «entro en mi billetera y tengo cinco mil guaraníes, entro en mi
-- presupuesto y tengo todavía dos millones. Como que no conecta, no tiene
-- sentido».
--
-- POR QUÉ NO CONECTABAN
--
-- Eran dos formas distintas de contar la misma plata:
--
--   · La billetera suma los saldos de las cuentas. Es «lo que tengo ahora»,
--     venga de donde venga, incluida plata de meses anteriores.
--   · El disponible arrancaba en cero cada ciclo: «lo que entró este ciclo,
--     menos lo que salió, menos lo que falta pagar». No sabía nada de lo que
--     ya había antes, ni de que esa plata se hubiera ido.
--
-- LO QUE PIDIÓ, EN SUS PALABRAS
--
-- «Cargo mi ingreso fijo con cómo me pagan y a qué cuenta. El 21 se acredita
-- y el Atlas sube en mi billetera. Ahí me aparece el disponible y cuánto por
-- día. Y durante el mes, cada movimiento en esa cuenta tiene que actualizar
-- ese saldo y recalcular el por día».
--
-- Así que el disponible deja de ser un flujo del ciclo y pasa a ser plata
-- real: lo que hay en las cuentas, menos lo que ya tiene dueño.
--
--     disponible = saldo de las cuentas
--                − lo guardado en los fondos de ahorro
--                − los gastos fijos que faltan pagar
--                − las cuotas que vencen antes de que cierre el ciclo
--
-- POR QUÉ SE RESTA EL AHORRO ENTERO Y NO SOLO EL DE ESTE CICLO
--
-- Porque guardar en un fondo NO baja ningún saldo: los fondos viven en
-- `movimientos_ahorro`, que la billetera no mira. Esa plata sigue contada
-- dentro del banco. Si no se restara, el disponible incluiría los ahorros de
-- toda la vida como si fueran para gastar. Y se resta el total y no el del
-- ciclo justamente porque lo de los ciclos anteriores también sigue adentro.
--
-- EL RESPALDO, QUE NO ES UN DETALLE
--
-- Quien todavía no cargó ninguna cuenta en la billetera sigue con el cálculo
-- de siempre. Si no, abriría Orden y vería «disponible: Gs. 0» teniendo
-- plata, que es peor que un número impreciso: es un número que asusta. Al
-- 21/09 hay tres cuentas de Matías sin cuentas de dinero creadas.

-- ------------------------------------------------------------
-- 1. EL CÁLCULO DE SIEMPRE, CON SU NOMBRE PROPIO
--
--    Se renombra en vez de copiarlo: son doscientas líneas y tener dos
--    versiones de la misma cuenta es tenerlas esperando a separarse. El
--    bloque se traga el error si ya se renombró, para que volver a aplicar
--    la migración no falle.
-- ------------------------------------------------------------
do $ren$
begin
  if exists (
    select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname = 'resumen_personal'
  ) and not exists (
    select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname = 'resumen_personal_por_ciclo'
  ) then
    alter function public.resumen_personal(uuid) rename to resumen_personal_por_ciclo;
  end if;
end $ren$;

revoke all on function public.resumen_personal_por_ciclo(uuid) from public, anon, authenticated;

-- ------------------------------------------------------------
-- 2. Y EL QUE MIRA LA PLATA DE VERDAD
-- ------------------------------------------------------------
create or replace function public.resumen_personal(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_res jsonb;
  v_cuentas integer;
  v_en_cuentas numeric;
  v_dias integer;
  v_hoy date;
  v_hasta date;
  v_descontar numeric;
begin
  -- Se parte del resumen de siempre y se corrige el disponible. Repetir
  -- acá las doscientas líneas que lo arman sería tener dos versiones de la
  -- misma cuenta esperando a separarse.
  v_res := public.resumen_personal_por_ciclo(p_empresa);

  select count(*)::int into v_cuentas
  from public.cuentas_dinero c where c.empresa_id = p_empresa and c.activa;

  -- Sin cuentas cargadas no hay saldo real del que partir: queda el cálculo
  -- por ciclo, que es impreciso pero no asusta.
  if v_cuentas = 0 then
    return v_res;
  end if;

  select coalesce(sum(public.saldo_cuenta_dinero(c.id)), 0) into v_en_cuentas
  from public.cuentas_dinero c where c.empresa_id = p_empresa and c.activa;

  -- Lo que está en las cuentas pero ya tiene dueño.
  v_descontar := coalesce((v_res->>'ahorro_total')::numeric, 0)
               + coalesce((v_res->>'fijos_por_pagar')::numeric, 0)
               + coalesce((v_res->>'cuotas_por_vencer')::numeric, 0);

  v_hoy   := public.hoy_empresa(p_empresa);
  v_hasta := (v_res->>'hasta')::date;
  v_dias  := greatest(1, (v_hasta - v_hoy) + 1);

  return v_res
    || jsonb_build_object(
         'disponible', v_en_cuentas - v_descontar,
         'por_dia',    round((v_en_cuentas - v_descontar) / v_dias, 2),
         -- Para que la pantalla pueda explicar de dónde sale el número en
         -- vez de pedir que se le crea.
         'en_cuentas', v_en_cuentas,
         'desde_la_billetera', true
       );
end $fn$;

revoke all on function public.resumen_personal(uuid) from public, anon;
grant execute on function public.resumen_personal(uuid) to authenticated;


-- ############################################################
-- ##  086_cada_cuenta_con_su_color.sql
-- ############################################################

-- ============================================================
-- 086 · CADA CUENTA CON SU COLOR
-- ============================================================
--
-- Matías: «los colores de cada banco. El Ueno es verde, el Atlas rojo
-- oscuro, el Continental azul marino, el Familiar celeste».
--
-- PARA QUÉ
--
-- En el panel las cuentas son tarjetas que se deslizan de costado. Con seis
-- tarjetas iguales hay que leer cada nombre para saber cuál es; con seis
-- colores no hace falta leer. La pantalla ya sabe pintar los bancos que
-- reconoce por el nombre —eso no necesita base—, pero dos cosas sí:
--
--   · el banco que no está en esa lista, que hay muchos;
--   · y el gusto de cada uno, que gana siempre sobre lo que adivinemos.
--
-- POR NOMBRE Y NO POR CÓDIGO DE COLOR
--
-- Se guarda «azul», no «#1B3A6B». Dos motivos. Uno: un código libre deja
-- entrar blanco sobre blanco, y una cuenta que no se ve. Dos: el tono exacto
-- depende de si la pantalla está en claro o en oscuro, y eso lo sabe la
-- pantalla, no la base. Guardando el nombre, retocar un tono es cambiar una
-- línea en el código y no tocar una sola fila.
--
-- En null significa «el que corresponda»: el del banco si lo reconocemos, y
-- si no uno sacado del nombre. Nadie queda sin color.

-- ------------------------------------------------------------
-- 1. LA COLUMNA
-- ------------------------------------------------------------
alter table public.cuentas_dinero
  add column if not exists color text;

alter table public.cuentas_dinero drop constraint if exists cuentas_dinero_color_check;
alter table public.cuentas_dinero
  add constraint cuentas_dinero_color_check
  check (color is null or color in
    ('verde', 'rojo', 'azul', 'celeste', 'naranja', 'violeta', 'rosa', 'gris'));

comment on column public.cuentas_dinero.color is
  'Color elegido a mano. Null: lo decide la pantalla por el nombre del banco (086).';

-- ------------------------------------------------------------
-- 2. GUARDARLO AL CREAR O EDITAR
--
--    La firma vieja se borra antes de crear la nueva. `create or replace`
--    con un parámetro más no reemplaza: crea una segunda función al lado, y
--    entonces la llamada de siempre se vuelve ambigua y PostgreSQL la
--    rechaza. La pantalla dejaría de poder guardar una cuenta.
-- ------------------------------------------------------------
drop function if exists public.guardar_cuenta_dinero(uuid, text, text, numeric, text[], uuid);

create or replace function public.guardar_cuenta_dinero(
  p_empresa       uuid,
  p_nombre        text,
  p_tipo          text default 'banco',
  p_saldo_inicial numeric default 0,
  p_metodos       text[] default '{}',
  p_id            uuid default null,
  p_color         text default null
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_id      uuid;
  v_metodos text[];
  v_color   text;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede tocar esto.' using errcode = '42501';
  end if;

  if char_length(trim(coalesce(p_nombre, ''))) = 0 then
    raise exception 'Ponele un nombre: el del banco, «Efectivo», «Tigo Money».' using errcode = '22023';
  end if;

  if coalesce(p_tipo, '') not in ('banco', 'efectivo', 'billetera') then
    raise exception 'Ese tipo de cuenta no existe.' using errcode = '22023';
  end if;

  -- Un color que no conocemos no es motivo para no guardar la cuenta: se
  -- deja en null y la pantalla elige. Lo que se pierde es una preferencia;
  -- lo que se salvaría rechazando, nada.
  v_color := case
    when p_color in ('verde', 'rojo', 'azul', 'celeste', 'naranja', 'violeta', 'rosa', 'gris')
    then p_color else null end;

  select coalesce(array_agg(distinct m), '{}') into v_metodos
  from unnest(coalesce(p_metodos, '{}')) m
  where m in ('efectivo', 'transferencia', 'tarjeta', 'credito', 'otro');

  if p_id is null then
    if (select count(*) from public.cuentas_dinero where empresa_id = p_empresa and activa) >= 20 then
      raise exception 'Ya tenés 20 cuentas. Archivá alguna antes de sumar otra.' using errcode = '22023';
    end if;

    insert into public.cuentas_dinero (empresa_id, nombre, tipo, saldo_inicial, metodos, color, orden, creada_por)
    values (p_empresa, trim(p_nombre), p_tipo, coalesce(p_saldo_inicial, 0), v_metodos, v_color,
            coalesce((select max(orden) + 1 from public.cuentas_dinero where empresa_id = p_empresa), 0),
            auth.uid())
    returning id into v_id;
  else
    update public.cuentas_dinero
    set nombre = trim(p_nombre), tipo = p_tipo, metodos = v_metodos, color = v_color, updated_at = now()
    where id = p_id and empresa_id = p_empresa and activa
    returning id into v_id;

    if v_id is null then
      raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
    end if;
  end if;

  -- Cada forma de pago, en una sola casa.
  update public.cuentas_dinero
  set metodos = array(select x from unnest(metodos) x where not (x = any (v_metodos))),
      updated_at = now()
  where empresa_id = p_empresa and id <> v_id and metodos && v_metodos;

  return v_id;
end $fn$;

revoke all on function public.guardar_cuenta_dinero(uuid, text, text, numeric, text[], uuid, text) from public, anon;
grant execute on function public.guardar_cuenta_dinero(uuid, text, text, numeric, text[], uuid, text) to authenticated;

-- ------------------------------------------------------------
-- 3. Y QUE LLEGUE A LA PANTALLA
--
--    Sin esto la columna existe y no la ve nadie. Va en las dos funciones
--    que arman cuentas para mostrar.
-- ------------------------------------------------------------
create or replace function public.billetera(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_cuentas jsonb;
  v_zona    text;
  v_sueltos record;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede ver esto.' using errcode = '42501';
  end if;

  select coalesce(zona_horaria, 'America/Asuncion') into v_zona from public.empresas where id = p_empresa;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', c.id,
    'nombre', c.nombre,
    'tipo', c.tipo,
    'color', c.color,
    'metodos', to_jsonb(c.metodos),
    'saldo', s.saldo,
    -- Lo que se movió este mes por esta cuenta, para que el número no esté solo.
    'entro_mes', coalesce(mes.entro, 0),
    'salio_mes', coalesce(mes.salio, 0)
  ) order by c.orden, c.created_at), '[]'::jsonb)
  into v_cuentas
  from public.cuentas_dinero c
  cross join lateral (select public.saldo_cuenta_dinero(c.id) as saldo) s
  left join lateral (
    select
      sum(m.monto) filter (where m.tipo <> 'gasto') as entro,
      sum(m.monto) filter (where m.tipo = 'gasto')  as salio
    from public.movimientos m
    where m.cuenta_id = c.id and m.estado = 'activo'
      and m.fecha >= date_trunc('month', (now() at time zone v_zona))::date
  ) mes on true
  where c.empresa_id = p_empresa and c.activa;

  -- Lo que se cargó y no llegó a ninguna cuenta. El neto y no la suma a
  -- secas: un gasto de 100 y un ingreso de 100 sin asignar no son 200 de
  -- desajuste, son cero.
  select count(*)::int as cantidad,
         coalesce(sum(case when m.tipo = 'gasto' then -m.monto else m.monto end), 0) as neto,
         min(m.fecha) as desde
  into v_sueltos
  from public.movimientos m
  where m.empresa_id = p_empresa and m.estado = 'activo' and m.cuenta_id is null;

  return jsonb_build_object(
    'cuentas', v_cuentas,
    'total', coalesce((select sum((x->>'saldo')::numeric) from jsonb_array_elements(v_cuentas) x), 0),
    'sin_cuenta', jsonb_build_object(
      'cantidad', coalesce(v_sueltos.cantidad, 0),
      'neto',     coalesce(v_sueltos.neto, 0),
      'desde',    v_sueltos.desde
    ),
    'metodos_sin_cuenta', (
      select coalesce(jsonb_agg(m order by m), '[]'::jsonb)
      from unnest(array['efectivo', 'transferencia', 'tarjeta', 'credito', 'otro']) m
      where exists (select 1 from public.cuentas_dinero c2
                    where c2.empresa_id = p_empresa and c2.activa)
        and not exists (select 1 from public.cuentas_dinero c3
                        where c3.empresa_id = p_empresa and c3.activa and m = any (c3.metodos))
    )
  );
end $fn$;

create or replace function public.cuentas_para_elegir(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_lista jsonb;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede ver esto.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
                    'id', c.id, 'nombre', c.nombre, 'tipo', c.tipo, 'color', c.color,
                    'metodos', to_jsonb(c.metodos))
                            order by c.orden, c.created_at), '[]'::jsonb)
  into v_lista
  from public.cuentas_dinero c
  where c.empresa_id = p_empresa and c.activa;

  return v_lista;
end $fn$;


-- ############################################################
-- ##  087_clases_y_cursos.sql
-- ############################################################

-- ============================================================
-- 087 · UN RUBRO PARA QUIEN VENDE CLASES
-- ============================================================
--
-- Matías quiere que Orden sirva también a quien da clases: profes de inglés,
-- de matemática, de música, de programación, presenciales u online.
--
-- POR QUÉ NO ALCANZA CON «SERVICIOS Y OFICIOS»
--
-- Un plomero y un profe de inglés se parecen en que los dos venden su
-- tiempo, y ahí se termina el parecido:
--
--   · El plomero cobra un trabajo y se termina. El profe tiene ALUMNOS, que
--     vuelven todas las semanas durante meses.
--   · El plomero factura un arreglo. El profe vende OCHO CLASES juntas y
--     después las va dando.
--   · El plomero gasta en cemento y repuestos. El profe gasta en internet,
--     en el micrófono y en la plataforma que le come una comisión.
--
-- Meterlos en la misma puerta le deja a cada uno la mitad de las palabras
-- equivocadas. Y hay un motivo más concreto: los paquetes de clases se van a
-- prender solo acá, y no en la barbería, donde no significan nada.
--
-- QUÉ HACE ESTA MIGRACIÓN Y QUÉ NO
--
-- Solo abre la puerta: que el rubro exista, que tenga sus categorías de
-- gasto y que se pueda elegir. Los paquetes vienen aparte, en su propia
-- migración, porque tocan plata y esto no toca nada.
--
-- LA LISTA ESTABA ESCRITA CUATRO VECES
--
-- En el constraint de `empresas`, en `cambiar_rubro`, en `crear_empresa` y,
-- de refilón, en `categorias_de_rubro`. Cuatro copias que tienen que decir
-- lo mismo o el rubro se rompe de una forma particularmente fea: la peor es
-- la de `crear_empresa`, que a un rubro que no conoce NO lo rechaza —lo
-- convierte en 'comercio' sin avisar—. Alguien elegiría «Clases y cursos»,
-- vería la pantalla de un almacén, y no habría ningún error en ningún lado.
--
-- Así que primero se deja una sola lista y después se agrega el rubro. El
-- que viene detrás —personal trainer— va a ser una línea.

-- ------------------------------------------------------------
-- 1. LA ÚNICA LISTA DE RUBROS
--
--    `immutable` para poder usarla dentro de un CHECK. Que no revalide las
--    filas viejas al cambiarla no es un problema acá: esta lista solo crece.
-- ------------------------------------------------------------
create or replace function public.rubros_validos()
returns text[] language sql immutable set search_path = public as $fn$
  select array['comercio', 'ganaderia', 'agricultura', 'servicios', 'clases'];
$fn$;

grant execute on function public.rubros_validos() to anon, authenticated;

alter table public.empresas drop constraint if exists empresas_rubro_check;
alter table public.empresas
  add constraint empresas_rubro_check
  check (rubro = any (public.rubros_validos()));

-- ------------------------------------------------------------
-- 2. EN QUÉ GASTA QUIEN DA CLASES
--
--    Se redefine la versión de DOS argumentos, que es la que vive desde la
--    024. Crear una de un argumento al lado sería dejar una función muerta:
--    la app llama a la de dos, y el rubro nuevo caería en el `else` —las
--    categorías de un almacén— sin que nada fallara.
--
--    Con pistas, como todas: un nombre de categoría solo no alcanza para que
--    el modelo clasifique bien lo que se dicta. «Pagué el Zoom» tiene que
--    caer en Internet y plataformas, no en Otros.
--
--    La categoría que ningún otro rubro tiene es «Comisiones»: quien enseña
--    por Preply, Superprof o Italki no cobra lo que factura, cobra lo que
--    queda después de que la plataforma se lleve su parte. Sin esa
--    categoría, esa mordida se reparte entre «Otros» y la nada, y el profe
--    nunca ve cuánto le cuesta de verdad conseguir alumnos ahí.
-- ------------------------------------------------------------
create or replace function public.categorias_de_rubro(
  p_rubro text,
  p_tipo_cuenta text default 'emprendedor'
)
returns jsonb language sql immutable set search_path = public as $fn$
  select case
    when coalesce(p_tipo_cuenta, 'emprendedor') = 'personal' then jsonb_build_array(
      jsonb_build_object('nombre','Comida','pistas','supermercado, almacén, verdulería, carnicería, despensa, panadería'),
      jsonb_build_object('nombre','Alquiler','pistas','alquiler, expensas, condominio'),
      jsonb_build_object('nombre','Servicios','pistas','luz, agua, internet, teléfono, cable, gas'),
      jsonb_build_object('nombre','Transporte','pistas','colectivo, nafta, combustible, pasaje, taxi, uber, peaje'),
      jsonb_build_object('nombre','Salud','pistas','farmacia, remedios, médico, dentista, seguro médico, análisis'),
      jsonb_build_object('nombre','Educación','pistas','colegio, cuota, universidad, útiles, curso, libros'),
      jsonb_build_object('nombre','Ropa','pistas','ropa, calzado, zapatillas, campera'),
      jsonb_build_object('nombre','Cuidado personal','pistas','peluquería, uñas, barbería, cosmética, gimnasio, perfume'),
      jsonb_build_object('nombre','Ocio','pistas','salida, restaurante, cine, streaming, viaje, cerveza, cumpleaños'),
      jsonb_build_object('nombre','Hogar','pistas','limpieza, muebles, arreglos, electrodomésticos, ferretería'),
      jsonb_build_object('nombre','Cuotas y deudas','pistas','tarjeta, préstamo, cuota, financiera'),
      jsonb_build_object('nombre','Otros','pistas',''))

    when coalesce(p_rubro, 'comercio') = 'ganaderia' then jsonb_build_array(
      jsonb_build_object('nombre','Alimentación','pistas','maíz, balanceado, ración, fardos, sal, pasto'),
      jsonb_build_object('nombre','Sanidad','pistas','vacunas, antiparasitarios, veterinario, remedios'),
      jsonb_build_object('nombre','Personal','pistas','peón, capataz, jornales, sueldos'),
      jsonb_build_object('nombre','Combustible','pistas','gasoil, nafta'),
      jsonb_build_object('nombre','Arrendamiento','pistas','alquiler de campo, pastaje'),
      jsonb_build_object('nombre','Fletes','pistas','transporte de hacienda, camión jaula'),
      jsonb_build_object('nombre','Mantenimiento','pistas','alambrado, aguadas, maquinaria, herramientas'),
      jsonb_build_object('nombre','Impuestos','pistas',''),
      jsonb_build_object('nombre','Otros','pistas',''))

    when coalesce(p_rubro, 'comercio') = 'agricultura' then jsonb_build_array(
      jsonb_build_object('nombre','Semilla','pistas','semilla, plantines'),
      jsonb_build_object('nombre','Fertilizante','pistas','urea, fosfato, abono'),
      jsonb_build_object('nombre','Agroquímicos','pistas','herbicida, fungicida, insecticida'),
      jsonb_build_object('nombre','Combustible','pistas','gasoil, nafta'),
      jsonb_build_object('nombre','Cosecha','pistas','cosechadora, trilla, secado'),
      jsonb_build_object('nombre','Fletes','pistas','transporte de granos'),
      jsonb_build_object('nombre','Arrendamiento','pistas','alquiler de campo'),
      jsonb_build_object('nombre','Personal','pistas','jornales, tractorista, peón'),
      jsonb_build_object('nombre','Otros','pistas',''))

    when coalesce(p_rubro, 'comercio') = 'servicios' then jsonb_build_array(
      jsonb_build_object('nombre','Materiales','pistas','cemento, arena, cables, pintura, insumos'),
      jsonb_build_object('nombre','Repuestos','pistas','piezas, filtros, aceite'),
      jsonb_build_object('nombre','Herramientas','pistas',''),
      jsonb_build_object('nombre','Combustible','pistas','gasoil, nafta'),
      jsonb_build_object('nombre','Personal','pistas','ayudante, jornales, sueldos'),
      jsonb_build_object('nombre','Transporte','pistas','flete, viaje, delivery'),
      jsonb_build_object('nombre','Impuestos','pistas',''),
      jsonb_build_object('nombre','Otros','pistas',''))

    when coalesce(p_rubro, 'comercio') = 'clases' then jsonb_build_array(
      jsonb_build_object('nombre','Internet y plataformas','pistas','internet, wifi, Zoom, Meet, plan del celular, hosting'),
      jsonb_build_object('nombre','Comisiones','pistas','Preply, Italki, Superprof, lo que se lleva la plataforma, comisión de cobro'),
      jsonb_build_object('nombre','Material','pistas','libros, licencias, PDF, impresiones, fotocopias, cuadernos'),
      jsonb_build_object('nombre','Equipo','pistas','notebook, micrófono, cámara, auriculares, tablet, pizarra, luz'),
      jsonb_build_object('nombre','Publicidad','pistas','anuncios, Instagram, Facebook, volantes'),
      jsonb_build_object('nombre','Capacitación','pistas','cursos propios, certificaciones, exámenes, membresías'),
      jsonb_build_object('nombre','Alquiler','pistas','aula, salón, espacio de trabajo'),
      jsonb_build_object('nombre','Impuestos','pistas',''),
      jsonb_build_object('nombre','Otros','pistas',''))

    else jsonb_build_array(
      jsonb_build_object('nombre','Mercadería','pistas','lo que comprás para revender'),
      jsonb_build_object('nombre','Transporte','pistas','combustible, flete, delivery'),
      jsonb_build_object('nombre','Comida','pistas',''),
      jsonb_build_object('nombre','Publicidad','pistas',''),
      jsonb_build_object('nombre','Servicios','pistas','luz, agua, internet, teléfono'),
      jsonb_build_object('nombre','Alquiler','pistas',''),
      jsonb_build_object('nombre','Sueldos','pistas','empleados, jornales'),
      jsonb_build_object('nombre','Impuestos','pistas',''),
      jsonb_build_object('nombre','Otros','pistas',''))
  end;
$fn$;

grant execute on function public.categorias_de_rubro(text, text) to anon, authenticated;

-- ------------------------------------------------------------
-- 3. SÍ CIERRA EL DÍA
--
--    Un profe da sus clases hoy y las cobra hoy: el día es su unidad, igual
--    que la de un peluquero. Por eso tiene cierre y tiene racha.
--
--    Es lo contrario del ganadero, que vende tres veces al año: a él se le
--    apagó justamente para no decirle todas las noches que no cargó nada.
--
--    También acá se redefine la de dos argumentos: la cuenta personal no
--    cierra el día sea cual sea su rubro, y esa regla no se puede perder.
-- ------------------------------------------------------------
create or replace function public.rubro_cierra_el_dia(
  p_rubro text,
  p_tipo_cuenta text default 'emprendedor'
)
returns boolean language sql immutable set search_path = public as $fn$
  select coalesce(p_tipo_cuenta, 'emprendedor') <> 'personal'
     and coalesce(p_rubro, 'comercio') in ('comercio', 'servicios', 'clases');
$fn$;

grant execute on function public.rubro_cierra_el_dia(text, text) to anon, authenticated;

-- ------------------------------------------------------------
-- 4. CAMBIAR DE RUBRO, CONTRA LA LISTA ÚNICA
-- ------------------------------------------------------------
create or replace function public.cambiar_rubro(p_empresa uuid, p_rubro text)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_antes text;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el propietario o un administrador puede cambiar el rubro.'
      using errcode = '42501';
  end if;

  if not (p_rubro = any (public.rubros_validos())) then
    raise exception 'Rubro desconocido: %', p_rubro using errcode = '22023';
  end if;

  select rubro into v_antes from public.empresas where id = p_empresa;
  if v_antes is null then
    raise exception 'Esa empresa no existe.' using errcode = 'P0002';
  end if;

  update public.empresas set rubro = p_rubro where id = p_empresa;

  return jsonb_build_object('rubro', p_rubro, 'antes', v_antes);
end $fn$;

revoke all on function public.cambiar_rubro(uuid, text) from public, anon;
grant execute on function public.cambiar_rubro(uuid, text) to authenticated;

-- ------------------------------------------------------------
-- 5. CREAR LA EMPRESA, TAMBIÉN CONTRA LA LISTA ÚNICA
--
--    Copia exacta de la versión que está viva (023), con UNA línea
--    cambiada: la que decide `v_rubro`. Se transcribe entera porque
--    PostgreSQL no sabe reemplazar un pedazo del cuerpo de una función.
--
--    Sigue cayendo a 'comercio' cuando el rubro no existe, y eso queda a
--    propósito: en el alta, rechazar es dejar a alguien afuera de Orden por
--    un dato que se arregla después en Ajustes. Lo que cambia es que ahora
--    'clases' sí está en la lista, que era el agujero.
-- ------------------------------------------------------------
create or replace function public.crear_empresa(
  p_nombre text,
  p_moneda text default 'PYG',
  p_nombre_usuario text default null,
  p_zona text default 'America/Asuncion',
  p_tipo_cuenta text default 'emprendedor',
  p_rubro text default 'comercio',
  p_como_nos_conocio text default '',
  p_telefono text default '',
  p_se_dedica text default ''
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_id uuid;
  v_codigo text;
  v_intentos int := 0;
  v_fin timestamptz;
  v_tipo text;
  v_rubro text;
  v_contacto text;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  if char_length(trim(coalesce(p_nombre, ''))) < 2 then
    raise exception 'El nombre del negocio es muy corto.' using errcode = '22023';
  end if;

  v_tipo := case when p_tipo_cuenta = 'personal' then 'personal' else 'emprendedor' end;
  v_rubro := case
    when v_tipo = 'personal' then 'comercio'
    when p_rubro = any (public.rubros_validos()) then p_rubro
    else 'comercio' end;

  loop
    v_codigo := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
    exit when not exists (select 1 from public.empresa_accesos where codigo = v_codigo);
    v_intentos := v_intentos + 1;
    if v_intentos > 12 then
      raise exception 'No se pudo generar un código de acceso.' using errcode = '55000';
    end if;
  end loop;

  insert into public.empresas (
    nombre, moneda, creada_por, zona_horaria, tipo_cuenta, rubro, como_nos_conocio)
  values (trim(p_nombre), coalesce(p_moneda, 'PYG'), auth.uid(),
          coalesce(nullif(trim(p_zona), ''), 'America/Asuncion'), v_tipo, v_rubro,
          left(coalesce(p_como_nos_conocio, ''), 80))
  returning id into v_id;

  v_contacto := nullif(trim(coalesce(p_nombre_usuario, '')), '');

  insert into public.miembros (empresa_id, user_id, nombre, rol)
  values (v_id, auth.uid(), coalesce(v_contacto, 'Propietario'), 'propietario');

  insert into public.empresa_accesos (empresa_id, codigo) values (v_id, v_codigo);

  if v_contacto is not null
     or nullif(trim(coalesce(p_telefono, '')), '') is not null
     or nullif(trim(coalesce(p_se_dedica, '')), '') is not null then
    insert into public.ficha_cliente (empresa_id, contacto, telefono, se_dedica, updated_at)
    values (v_id,
            left(coalesce(v_contacto, ''), 120),
            left(regexp_replace(coalesce(p_telefono, ''), '[^0-9+]', '', 'g'), 40),
            left(coalesce(trim(p_se_dedica), ''), 200),
            now())
    on conflict (empresa_id) do nothing;
  end if;

  v_fin := now() + make_interval(days => public.dias_de_prueba(v_tipo));
  insert into public.suscripciones (empresa_id, plan, estado, periodo_inicio, periodo_fin, prueba_fin)
  values (v_id, 'pro', 'prueba', now(), v_fin, v_fin);

  perform set_config('orden.suscripcion_confiable', '1', true);
  update public.empresas set plan = 'pro' where id = v_id;
  perform set_config('orden.suscripcion_confiable', '0', true);

  return v_id;
end $fn$;

revoke all on function public.crear_empresa(text, text, text, text, text, text, text, text, text)
  from public, anon;
grant execute on function public.crear_empresa(text, text, text, text, text, text, text, text, text)
  to authenticated;


-- ############################################################
-- ##  088_el_paquete_de_clases.sql
-- ############################################################

-- ============================================================
-- 088 · EL PAQUETE DE CLASES
-- ============================================================
--
-- «Ocho clases por Gs. 400.000, pagadas el día 1.» Es la forma en que cobra
-- casi todo el que enseña, y hasta ahora Orden no tenía dónde anotarla: se
-- cargaba una venta de 400.000 y el profe llevaba en la cabeza —o en un
-- cuaderno— cuántas le quedaban a cada alumno.
--
-- LO QUE DECIDIÓ MATÍAS, Y QUÉ SIGNIFICA ACÁ
--
-- «Se gana al cobrar.» Los 400.000 cuentan como ingreso el día que entran,
-- no clase por clase. Por eso esta migración NO inventa ninguna lógica de
-- plata: el paquete se cobra con `registrar_venta`, igual que cualquier
-- venta. Cae en la billetera por su forma de pago, suma en la ganancia, y
-- si se fía queda en el fiado. Todo eso ya estaba probado; acá no se toca.
--
-- Lo que el paquete agrega es solo el CONTADOR: cuántas clases se
-- compraron, cuántas se dieron, cuántas quedan.
--
-- LA CONSECUENCIA, DICHA UNA VEZ
--
-- Si un alumno abandona en la tercera clase y se le devuelve plata, esa
-- devolución cae en el mes en que se devuelve, no en el que pagó. Es la
-- regla que eligió Matías con esa consecuencia a la vista.
--
-- LO USADO SE CALCULA, NO SE GUARDA
--
-- Cada clase dada es una fila, con su fecha. Lo usado es la suma de esas
-- filas, igual que el saldo de una cuenta es la suma de sus movimientos. Un
-- contador guardado aparte termina, tarde o temprano, diciendo otra cosa
-- que su historia —y el alumno que pregunta «¿cuándo usé mis clases?»
-- merece una respuesta con fechas, no un número.

-- ------------------------------------------------------------
-- 1. EL PAQUETE
-- ------------------------------------------------------------
create table if not exists public.paquetes (
  id            uuid primary key default gen_random_uuid(),
  empresa_id    uuid not null references public.empresas (id) on delete cascade,
  -- El alumno. `restrict`: un alumno con paquetes no se borra por
  -- accidente llevándose la historia de lo que pagó.
  cliente_id    uuid not null references public.clientes (id) on delete restrict,
  nombre        text not null check (char_length(trim(nombre)) between 1 and 80),
  -- `numeric` y no entero: el mismo paquete sirve para «8 clases», para
  -- «10 horas» y para una clase de hora y media que cuenta 1,5.
  clases        numeric(8, 2) not null check (clases > 0 and clases <= 1000),
  precio        numeric not null check (precio >= 0),
  -- La venta que lo pagó. En null si el paquete fue gratis (una clase de
  -- prueba): no hay venta de cero que anotar.
  movimiento_id uuid references public.movimientos (id) on delete set null,
  -- En null no vence. Matías: «vos decidís en cada paquete».
  vence_el      date,
  -- Cerrado a mano: el alumno abandonó. Las clases que quedaban no se
  -- pueden usar, pero la historia sigue ahí.
  cerrado       boolean not null default false,
  creado_por    uuid references auth.users (id) on delete set null,
  created_at    timestamptz not null default now()
);

create index if not exists paquetes_alumno_idx on public.paquetes (cliente_id, created_at desc);
create index if not exists paquetes_empresa_idx on public.paquetes (empresa_id);

alter table public.paquetes enable row level security;
revoke all on public.paquetes from anon, authenticated;

-- ------------------------------------------------------------
-- 2. CADA CLASE QUE SE DESCONTÓ
--
--    `motivo` distingue la clase que se dio de la falta que se descontó:
--    Matías quiere decidir en cada falta si se cobra. Las dos restan igual,
--    pero en la historia no son lo mismo.
--
--    `reserva_id` queda listo para cuando se enganche la agenda: el turno
--    marcado como atendido va a descontar solo. El índice único garantiza
--    que un mismo turno nunca descuente dos veces, aunque alguien toque el
--    botón dos veces o la pantalla reintente.
-- ------------------------------------------------------------
create table if not exists public.clases_dadas (
  id          uuid primary key default gen_random_uuid(),
  empresa_id  uuid not null references public.empresas (id) on delete cascade,
  paquete_id  uuid not null references public.paquetes (id) on delete cascade,
  fecha       date not null,
  cantidad    numeric(8, 2) not null check (cantidad > 0),
  motivo      text not null default 'dada' check (motivo in ('dada', 'falta')),
  reserva_id  uuid references public.turnos_reserva (id) on delete set null,
  creado_por  uuid references auth.users (id) on delete set null,
  created_at  timestamptz not null default now()
);

create index if not exists clases_dadas_paquete_idx on public.clases_dadas (paquete_id, fecha desc);
create unique index if not exists clases_dadas_reserva_idx
  on public.clases_dadas (reserva_id) where reserva_id is not null;

alter table public.clases_dadas enable row level security;
revoke all on public.clases_dadas from anon, authenticated;

-- ------------------------------------------------------------
-- 3. LO QUE SE LEE DE UN PAQUETE
--
--    Un solo lugar que dice cuánto se usó y en qué estado está, para que la
--    pantalla y las funciones de abajo no puedan contestar distinto.
-- ------------------------------------------------------------
create or replace function public.estado_paquete(p_paquete uuid)
returns jsonb language sql stable security definer set search_path = public as $fn$
  select jsonb_build_object(
    'usadas', coalesce(u.usadas, 0),
    'quedan', greatest(0, p.clases - coalesce(u.usadas, 0)),
    'estado', case
      when p.cerrado then 'cerrado'
      when coalesce(u.usadas, 0) >= p.clases then 'terminado'
      when p.vence_el is not null and p.vence_el < public.hoy_empresa(p.empresa_id) then 'vencido'
      else 'activo' end
  )
  from public.paquetes p
  left join lateral (
    select sum(c.cantidad) as usadas from public.clases_dadas c where c.paquete_id = p.id
  ) u on true
  where p.id = p_paquete;
$fn$;

revoke all on function public.estado_paquete(uuid) from public, anon, authenticated;

-- ------------------------------------------------------------
-- 4. VENDER UN PAQUETE
--
--    Todo o nada: la venta y el paquete se crean juntos. Un paquete sin su
--    venta es un alumno con clases que nadie cobró; una venta sin paquete es
--    plata que entró sin que se sepa por qué.
-- ------------------------------------------------------------
create or replace function public.vender_paquete(
  p_empresa uuid,
  p_cliente uuid,
  p_nombre  text,
  p_clases  numeric,
  p_precio  numeric,
  p_metodo  text default 'efectivo',
  p_fecha   date default null,
  p_vence   date default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_alumno text;
  v_mov    uuid;
  v_id     uuid;
  v_fecha  date;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if char_length(trim(coalesce(p_nombre, ''))) = 0 then
    raise exception 'Ponele un nombre al paquete: «8 clases de inglés».' using errcode = '22023';
  end if;

  if coalesce(p_clases, 0) <= 0 then
    raise exception 'El paquete tiene que tener al menos una clase.' using errcode = '22023';
  end if;

  if coalesce(p_precio, -1) < 0 then
    raise exception 'El precio no puede ser negativo.' using errcode = '22023';
  end if;

  select nombre into v_alumno from public.clientes
  where id = p_cliente and empresa_id = p_empresa;
  if v_alumno is null then
    raise exception 'Ese alumno no es de esta cuenta.' using errcode = 'P0002';
  end if;

  v_fecha := coalesce(p_fecha, public.hoy_empresa(p_empresa));

  if p_vence is not null and p_vence < v_fecha then
    raise exception 'El paquete no puede vencer antes de venderse.' using errcode = '22023';
  end if;

  -- La plata, por el camino de siempre. Sin costo: una clase no tiene
  -- mercadería, así que todo lo cobrado es ganancia bruta.
  if p_precio > 0 then
    v_mov := public.registrar_venta(
      p_empresa     => p_empresa,
      p_items       => jsonb_build_array(jsonb_build_object(
                         'nombre', left(trim(p_nombre), 80),
                         'cantidad', 1,
                         'precio_unitario', p_precio,
                         'costo_unitario', 0)),
      p_fecha       => v_fecha,
      p_descripcion => left(trim(p_nombre), 80),
      p_metodo_pago => coalesce(p_metodo, 'efectivo'),
      p_contraparte => v_alumno,
      p_cliente     => p_cliente
    );
  end if;

  insert into public.paquetes (empresa_id, cliente_id, nombre, clases, precio, movimiento_id, vence_el, creado_por)
  values (p_empresa, p_cliente, trim(p_nombre), p_clases, p_precio, v_mov, p_vence, auth.uid())
  returning id into v_id;

  return jsonb_build_object('paquete', v_id, 'movimiento', v_mov);
end $fn$;

revoke all on function public.vender_paquete(uuid, uuid, text, numeric, numeric, text, date, date) from public, anon;
grant execute on function public.vender_paquete(uuid, uuid, text, numeric, numeric, text, date, date) to authenticated;

-- ------------------------------------------------------------
-- 5. DESCONTAR UNA CLASE
--
--    `for update` sobre el paquete: dos toques casi juntos —el profe y la
--    agenda, o un reintento de la red— no pueden descontar las dos la
--    última clase que quedaba.
-- ------------------------------------------------------------
create or replace function public.dar_clase(
  p_paquete  uuid,
  p_cantidad numeric default 1,
  p_fecha    date default null,
  p_motivo   text default 'dada',
  p_reserva  uuid default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_p      record;
  v_estado jsonb;
  v_fecha  date;
begin
  select * into v_p from public.paquetes where id = p_paquete for update;
  if v_p.id is null then
    raise exception 'Ese paquete no existe.' using errcode = 'P0002';
  end if;

  if not public.es_miembro(v_p.empresa_id) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if coalesce(p_cantidad, 0) <= 0 then
    raise exception 'Hay que descontar al menos una clase.' using errcode = '22023';
  end if;

  if coalesce(p_motivo, '') not in ('dada', 'falta') then
    raise exception 'Eso no es una clase ni una falta.' using errcode = '22023';
  end if;

  v_estado := public.estado_paquete(p_paquete);
  v_fecha  := coalesce(p_fecha, public.hoy_empresa(v_p.empresa_id));

  if v_estado->>'estado' = 'cerrado' then
    raise exception 'Ese paquete está cerrado.' using errcode = '22023';
  end if;

  -- Vencido se mira contra la fecha de la clase y no contra hoy: una clase
  -- que se dio el día 30 se puede anotar el 2, aunque el paquete venciera
  -- el 31. Lo que importa es cuándo fue, no cuándo se acordó alguien.
  if v_p.vence_el is not null and v_fecha > v_p.vence_el then
    raise exception 'Ese paquete venció el %.', to_char(v_p.vence_el, 'DD/MM') using errcode = '22023';
  end if;

  if (v_estado->>'quedan')::numeric < p_cantidad then
    raise exception 'Le quedan % clases y querés descontar %.',
      trim(to_char((v_estado->>'quedan')::numeric, 'FM999990.##')),
      trim(to_char(p_cantidad, 'FM999990.##'))
      using errcode = '22023';
  end if;

  insert into public.clases_dadas (empresa_id, paquete_id, fecha, cantidad, motivo, reserva_id, creado_por)
  values (v_p.empresa_id, p_paquete, v_fecha, p_cantidad, p_motivo, p_reserva, auth.uid());

  return public.estado_paquete(p_paquete);
end $fn$;

revoke all on function public.dar_clase(uuid, numeric, date, text, uuid) from public, anon;
grant execute on function public.dar_clase(uuid, numeric, date, text, uuid) to authenticated;

-- ------------------------------------------------------------
-- 6. DESHACER UNA CLASE ANOTADA POR ERROR
--
--    Se borra la fila, sin más. No es plata —la plata está en la venta, que
--    no se toca—: es una marca en un contador, y el error más común del
--    mundo es tocar el botón dos veces.
-- ------------------------------------------------------------
create or replace function public.deshacer_clase(p_clase uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_empresa uuid;
  v_paquete uuid;
begin
  select empresa_id, paquete_id into v_empresa, v_paquete
  from public.clases_dadas where id = p_clase;
  if v_empresa is null then
    raise exception 'Esa clase no existe.' using errcode = 'P0002';
  end if;

  if not public.es_miembro(v_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  delete from public.clases_dadas where id = p_clase;

  return public.estado_paquete(v_paquete);
end $fn$;

revoke all on function public.deshacer_clase(uuid) from public, anon;
grant execute on function public.deshacer_clase(uuid) to authenticated;

-- ------------------------------------------------------------
-- 7. CERRAR EL PAQUETE DE QUIEN ABANDONÓ
--
--    Y reabrirlo, porque el que dijo «no vuelvo más» a veces vuelve. Cerrar
--    es cosa de quien administra: es decidir que unas clases pagadas ya no
--    se van a dar.
-- ------------------------------------------------------------
create or replace function public.cerrar_paquete(p_paquete uuid, p_cerrado boolean default true)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_empresa uuid;
begin
  select empresa_id into v_empresa from public.paquetes where id = p_paquete;
  if v_empresa is null then
    raise exception 'Ese paquete no existe.' using errcode = 'P0002';
  end if;

  if not public.es_admin(v_empresa) then
    raise exception 'Solo el dueño de la cuenta puede cerrar un paquete.' using errcode = '42501';
  end if;

  update public.paquetes set cerrado = coalesce(p_cerrado, true) where id = p_paquete;

  return public.estado_paquete(p_paquete);
end $fn$;

revoke all on function public.cerrar_paquete(uuid, boolean) from public, anon;
grant execute on function public.cerrar_paquete(uuid, boolean) to authenticated;

-- ------------------------------------------------------------
-- 8. LOS PAQUETES DE UN ALUMNO, CON SU HISTORIA
--
--    Primero los que se pueden usar, después los viejos. Cada uno con las
--    clases que se descontaron y cuándo: es la respuesta a «¿cuándo usé mis
--    clases?».
-- ------------------------------------------------------------
create or replace function public.paquetes_del_alumno(p_empresa uuid, p_cliente uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_lista jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(x.fila order by x.orden, x.creado desc), '[]'::jsonb)
  into v_lista
  from (
    select
      p.created_at as creado,
      case when (public.estado_paquete(p.id)->>'estado') = 'activo' then 0 else 1 end as orden,
      jsonb_build_object(
        'id', p.id,
        'nombre', p.nombre,
        'clases', p.clases,
        'precio', p.precio,
        'vence_el', p.vence_el,
        'creado', p.created_at
      ) || public.estado_paquete(p.id)
        || jsonb_build_object('historia', coalesce((
             select jsonb_agg(jsonb_build_object(
                      'id', c.id, 'fecha', c.fecha, 'cantidad', c.cantidad, 'motivo', c.motivo)
                    order by c.fecha desc, c.created_at desc)
             from public.clases_dadas c where c.paquete_id = p.id
           ), '[]'::jsonb)) as fila
    from public.paquetes p
    where p.empresa_id = p_empresa and p.cliente_id = p_cliente
  ) x;

  return v_lista;
end $fn$;

revoke all on function public.paquetes_del_alumno(uuid, uuid) from public, anon;
grant execute on function public.paquetes_del_alumno(uuid, uuid) to authenticated;


-- ############################################################
-- ##  089_un_profe_no_tiene_link_publico.sql
-- ############################################################

-- ============================================================
-- 089 · UN PROFE NO TIENE LINK PÚBLICO DE RESERVAS
-- ============================================================
--
-- Matías: «el link, no sé para qué estaría sirviendo. Si entro a reservar,
-- solo voy a poder reservar un día y una hora. Pero un profesor no trabaja
-- así: tiene un horario definido para cada alumno —todos los martes,
-- miércoles y viernes a tal hora— y se cobra el mes antes de empezar».
--
-- Tiene razón, y es más que una preferencia. El link de la 038 se hizo
-- para una barbería: un desconocido entra, ve los huecos libres y toma uno.
-- Un profe no deja que un desconocido le tome un hueco de la agenda: los
-- horarios los arma él, alumno por alumno. Un link así abierto sería una
-- puerta por la que le entran reservas que después tiene que ir a cancelar.
--
-- POR QUÉ SE CIERRA ACÁ Y NO SOLO EN LA PANTALLA
--
-- Esconder la tarjeta del link alcanza para que nadie lo configure. No
-- alcanza para el caso que sí va a pasar: una barbería que tenía su link
-- publicado y un día se pasa a «Clases y cursos». Su link sigue en la
-- biografía de Instagram, y seguiría tomando reservas.
--
-- Las tres puertas públicas (`agenda_publica`, `huecos_publicos`,
-- `reservar_publico`) ya miran si el link está activo, y a un link apagado
-- le contestan lo mismo que a uno que no existe. Así que no se tocan: se
-- garantiza que el link de un profe nunca esté activo, y las tres se
-- cierran de una. Reescribir tres funciones de seguridad para agregarles
-- una condición sería arriesgar lo que ya estaba probado.
--
-- Pasarse de vuelta a un rubro con link NO lo reactiva solo: el dueño lo
-- vuelve a prender cuando quiera. Un link que reaparece sin que nadie lo
-- pida es tan sorpresivo como uno que desaparece.

-- ------------------------------------------------------------
-- 1. QUÉ RUBROS TRABAJAN CON ALUMNOS DE HORARIO FIJO
--
--    Espejo de `agendaDeAlumnos` en `src/lib/rubros.ts`. Una sola pregunta
--    en un solo lugar de la base, igual que `rubro_cierra_el_dia`.
-- ------------------------------------------------------------
create or replace function public.rubro_de_alumnos(p_rubro text)
returns boolean language sql immutable set search_path = public as $fn$
  select coalesce(p_rubro, '') = 'clases';
$fn$;

grant execute on function public.rubro_de_alumnos(text) to anon, authenticated;

-- ------------------------------------------------------------
-- 2. EL LINK DE UN PROFE NO SE PUEDE PRENDER
--
--    Se rechaza con un mensaje, no se apaga en silencio: si alguien llega
--    hasta acá, tiene que saber por qué su link no anda.
-- ------------------------------------------------------------
create or replace function public.link_publico_segun_rubro()
returns trigger language plpgsql security definer set search_path = public as $fn$
begin
  if new.activo and public.rubro_de_alumnos(
       (select e.rubro from public.empresas e where e.id = new.empresa_id)) then
    raise exception 'Una cuenta de clases no tiene link de reservas: los horarios de cada alumno los armás vos.'
      using errcode = '22023';
  end if;
  return new;
end $fn$;

revoke all on function public.link_publico_segun_rubro() from public, anon, authenticated;

drop trigger if exists link_publico_segun_rubro on public.turnos_publico;
create trigger link_publico_segun_rubro
  before insert or update on public.turnos_publico
  for each row execute function public.link_publico_segun_rubro();

-- ------------------------------------------------------------
-- 3. PASARSE A CLASES APAGA EL LINK QUE HUBIERA
--
--    Es la barbería del ejemplo de arriba. Se apaga, no se borra: el slug
--    es la dirección del negocio (038) y si vuelve a su rubro anterior lo
--    tiene que encontrar igual.
-- ------------------------------------------------------------
create or replace function public.apagar_link_de_alumnos()
returns trigger language plpgsql security definer set search_path = public as $fn$
begin
  if public.rubro_de_alumnos(new.rubro) and not public.rubro_de_alumnos(old.rubro) then
    update public.turnos_publico
    set activo = false, updated_at = now()
    where empresa_id = new.id and activo;
  end if;
  return new;
end $fn$;

revoke all on function public.apagar_link_de_alumnos() from public, anon, authenticated;

drop trigger if exists apagar_link_de_alumnos on public.empresas;
create trigger apagar_link_de_alumnos
  after update of rubro on public.empresas
  for each row execute function public.apagar_link_de_alumnos();

-- ------------------------------------------------------------
-- 4. Y SI YA HABÍA ALGUNO, SE APAGA AHORA
--
--    No debería haber ninguno —el rubro existe desde la 087, de hoy—, pero
--    la regla vale desde que se aplica, no desde el próximo cambio.
-- ------------------------------------------------------------
update public.turnos_publico tp
set activo = false, updated_at = now()
from public.empresas e
where e.id = tp.empresa_id and public.rubro_de_alumnos(e.rubro) and tp.activo;


-- ############################################################
-- ##  090_un_profe_no_cierra_caja.sql
-- ############################################################

-- ============================================================
-- 090 · UN PROFE NO CIERRA CAJA
-- ============================================================
--
-- Matías, mirando el rubro terminado: «¿cómo vas a comprar y vender un
-- curso? Aparece invertido en stock, reponer. No tiene sentido. Esto es
-- para que el profesor se administre con su agenda, con lo que entra y con
-- lo que sale».
--
-- La mayor parte de ese cambio es de pantalla (`src/lib/rubros.ts`): se
-- van los productos, la pantalla de cobrar y el cierre del día. Pero el
-- cierre tiene una mitad que vive acá, y es la que molesta de verdad: el
-- recordatorio de la noche. Con el rubro en `true`, a un profe que no da
-- clases los sábados le llegaría todos los sábados «no cargaste nada hoy».
-- Es retarlo por descansar.
--
-- La racha no se toca en esta migración. Hoy cuenta los días con algo
-- cargado; va a pasar a contar los días que tenía clases y las marcó,
-- cuando exista marcar una clase como dada. Hasta entonces sigue como está.

create or replace function public.rubro_cierra_el_dia(
  p_rubro text,
  p_tipo_cuenta text default 'emprendedor'
)
returns boolean language sql immutable set search_path = public as $fn$
  select coalesce(p_tipo_cuenta, 'emprendedor') <> 'personal'
     and coalesce(p_rubro, 'comercio') in ('comercio', 'servicios');
$fn$;

grant execute on function public.rubro_cierra_el_dia(text, text) to anon, authenticated;


-- ############################################################
-- ##  091_inscribir_a_un_alumno.sql
-- ############################################################

-- ============================================================
-- 091 · INSCRIBIR A UN ALUMNO
-- ============================================================
--
-- Cómo trabaja un profe online, en palabras de Matías:
--
--   «El alumno se conecta con el profesor por WhatsApp. El profesor entra a
--   su sistema para ver si tiene libre tal día, tal hora. Cuando llegan a un
--   acuerdo —cuántos días, cuántas semanas, cuántos meses— el profesor anota:
--   Matías va a tener clases lunes, martes y jueves de 6 a 7 de la tarde. Yo
--   cobro 50.000 la hora. Y automáticamente se calcula cuánto sería en el
--   plazo que marqué. El alumno paga y el profesor registra ese pago.»
--
-- Eso es esta migración. Una inscripción es:
--
--   · un horario  — qué días de la semana, de qué hora a qué hora;
--   · un período  — desde cuándo hasta cuándo;
--   · un precio   — por hora (y Orden multiplica) o cerrado;
--   · y las clases que salen de cruzar lo anterior, puestas en la agenda.
--
-- POR DENTRO ES UN PAQUETE (088) CON HORARIO
--
-- Lo que la 088 llamaba paquete —N clases, un precio, un vencimiento, un
-- contador— es exactamente lo que resulta de inscribir a alguien: trece
-- clases, Gs. 650.000, vence el 31. Así que no se crea otra tabla: el
-- paquete gana el horario, y las clases de la agenda saben de qué paquete
-- salieron. Nada de lo que ya estaba probado se tira.
--
-- SE GANA AL COBRAR, TAMBIÉN ACÁ
--
-- Matías lo eligió: la plata cuenta el día que entra. Por eso una
-- inscripción que todavía no se pagó NO es una venta fiada. Una venta fiada
-- cuenta como cobrada el día de la venta (056), y eso sería decirle al profe
-- que ganó en octubre plata que recién le pagan en noviembre. Una
-- inscripción sin pagar queda «por cobrar», sin movimiento de plata, y la
-- venta nace el día que el alumno paga.

-- ------------------------------------------------------------
-- 1. EL PAQUETE GANA UN HORARIO
--
--    `dias` con la numeración de PostgreSQL (`extract(dow)`): 0 es domingo,
--    1 lunes… 6 sábado. Todo o nada: un horario a medias no genera clases.
-- ------------------------------------------------------------
alter table public.paquetes
  add column if not exists dias        smallint[],
  add column if not exists hora_desde  time,
  add column if not exists hora_hasta  time,
  add column if not exists desde       date,
  add column if not exists precio_hora numeric;

alter table public.paquetes drop constraint if exists paquete_horario_completo;
alter table public.paquetes add constraint paquete_horario_completo check (
  (dias is null and hora_desde is null and hora_hasta is null and desde is null)
  or (dias is not null and cardinality(dias) > 0
      and hora_desde is not null and hora_hasta is not null and hora_hasta > hora_desde
      and desde is not null)
);

alter table public.paquetes drop constraint if exists paquete_precio_hora;
alter table public.paquetes add constraint paquete_precio_hora
  check (precio_hora is null or precio_hora >= 0);

-- ------------------------------------------------------------
-- 2. CADA CLASE DE LA AGENDA SABE DE QUÉ INSCRIPCIÓN SALIÓ
--
--    El alumno ya lo sabía: `cliente_id` existe desde la 052. Lo nuevo es
--    el paquete, que es lo que va a permitir descontar la clase al marcarla
--    como dada, y cancelar las que faltan si el alumno deja.
-- ------------------------------------------------------------
alter table public.turnos_reserva
  add column if not exists paquete_id uuid references public.paquetes (id) on delete cascade;

create index if not exists turnos_reserva_paquete_idx
  on public.turnos_reserva (paquete_id) where paquete_id is not null;

-- ------------------------------------------------------------
-- 3. LAS FECHAS QUE SALEN DE UN HORARIO
--
--    Tope de un año: un error de tipeo en el año («2062») generaría miles
--    de clases, y nadie inscribe a un alumno por más de un año de una vez.
-- ------------------------------------------------------------
create or replace function public.fechas_de_horario(p_dias smallint[], p_desde date, p_hasta date)
returns setof date language sql immutable set search_path = public as $fn$
  select d::date
  from generate_series(p_desde, least(p_hasta, p_desde + 366), interval '1 day') d
  where extract(dow from d)::smallint = any (p_dias)
  order by 1;
$fn$;

revoke all on function public.fechas_de_horario(smallint[], date, date) from public, anon, authenticated;

-- ------------------------------------------------------------
-- 4. LO QUE VA A PASAR, ANTES DE QUE PASE
--
--    La pantalla lo llama mientras el profe completa el formulario: cuántas
--    clases, cuántas horas, cuánto da, y con quién choca. Es lo que le
--    reemplaza el cuaderno: «el jueves 15 a las 18 ya tenés a Ana».
--
--    Choca con cualquier clase pendiente o confirmada de la cuenta, sea de
--    quien sea: un profe da una clase a la vez.
-- ------------------------------------------------------------
create or replace function public.vista_previa_inscripcion(
  p_empresa     uuid,
  p_dias        smallint[],
  p_hora_desde  time,
  p_hora_hasta  time,
  p_desde       date,
  p_hasta       date,
  p_precio_hora numeric default null,
  p_total       numeric default null
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_zona   text;
  v_clases integer;
  v_horas  numeric;
  v_total  numeric;
  v_choques jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  -- Un formulario a medio completar no es un error: devuelve ceros.
  if p_dias is null or cardinality(p_dias) = 0 or p_hora_desde is null or p_hora_hasta is null
     or p_hora_hasta <= p_hora_desde or p_desde is null or p_hasta is null or p_hasta < p_desde then
    return jsonb_build_object('clases', 0, 'horas', 0, 'total', 0, 'choques', '[]'::jsonb);
  end if;

  select coalesce(zona_horaria, 'America/Asuncion') into v_zona from public.empresas where id = p_empresa;

  select count(*)::int into v_clases from public.fechas_de_horario(p_dias, p_desde, p_hasta);
  v_horas := round(v_clases * extract(epoch from (p_hora_hasta - p_hora_desde)) / 3600.0, 2);
  v_total := coalesce(p_total, round(v_horas * coalesce(p_precio_hora, 0)));

  select coalesce(jsonb_agg(jsonb_build_object(
           'fecha', f.d,
           'hora', to_char(r.inicia at time zone v_zona, 'HH24:MI'),
           'alumno', r.cliente_nombre
         ) order by f.d, r.inicia), '[]'::jsonb)
  into v_choques
  from public.fechas_de_horario(p_dias, p_desde, p_hasta) f(d)
  join public.turnos_reserva r
    on r.empresa_id = p_empresa
   and r.estado in ('pendiente', 'confirmada')
   and r.inicia < ((f.d + p_hora_hasta) at time zone v_zona)
   and ((f.d + p_hora_desde) at time zone v_zona) < r.termina;

  return jsonb_build_object('clases', v_clases, 'horas', v_horas, 'total', v_total, 'choques', v_choques);
end $fn$;

revoke all on function public.vista_previa_inscripcion(uuid, smallint[], time, time, date, date, numeric, numeric) from public, anon;
grant execute on function public.vista_previa_inscripcion(uuid, smallint[], time, time, date, date, numeric, numeric) to authenticated;

-- ------------------------------------------------------------
-- 5. EL QUE DA LAS CLASES Y LO QUE SE DA
--
--    La agenda exige un profesional y un servicio por turno: se hizo para
--    una barbería. Un profe no tiene por qué saberlo. Si no existen, se
--    crean acá: él, sin comisión (`local`: todo queda para el negocio), y un
--    servicio «Clase» que nunca ve, porque no tiene catálogo.
-- ------------------------------------------------------------
create or replace function public.profe_y_clase(p_empresa uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_prof     uuid;
  v_producto uuid;
  v_nombre   text;
begin
  select id into v_prof from public.turnos_profesional
  where empresa_id = p_empresa and activo
  order by (user_id = auth.uid()) desc nulls last, created_at
  limit 1;

  if v_prof is null then
    select nombre into v_nombre from public.miembros
    where empresa_id = p_empresa and user_id = auth.uid();
    insert into public.turnos_profesional (empresa_id, nombre, user_id, reparto)
    values (p_empresa, left(coalesce(nullif(trim(v_nombre), ''), 'Yo'), 60), auth.uid(), 'local')
    returning id into v_prof;
  end if;

  select id into v_producto from public.productos
  where empresa_id = p_empresa and nombre = 'Clase' and activo and not controla_stock
  order by created_at limit 1;

  if v_producto is null then
    insert into public.productos (empresa_id, nombre, precio, costo, controla_stock)
    values (p_empresa, 'Clase', 0, 0, false)
    returning id into v_producto;
  end if;

  return jsonb_build_object('profesional', v_prof, 'producto', v_producto);
end $fn$;

revoke all on function public.profe_y_clase(uuid) from public, anon, authenticated;

-- ------------------------------------------------------------
-- 6. COBRAR UNA INSCRIPCIÓN
--
--    Es la venta de siempre, el día que el alumno paga. Va antes de
--    `inscribir_alumno` porque la usa cuando el pago es en el momento.
-- ------------------------------------------------------------
create or replace function public.cobrar_inscripcion(
  p_paquete uuid,
  p_metodo  text default 'efectivo',
  p_fecha   date default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_p      record;
  v_alumno text;
  v_mov    uuid;
begin
  select * into v_p from public.paquetes where id = p_paquete for update;
  if v_p.id is null then
    raise exception 'Ese paquete no existe.' using errcode = 'P0002';
  end if;

  if not public.es_miembro(v_p.empresa_id) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if v_p.movimiento_id is not null then
    raise exception 'Esa inscripción ya está cobrada.' using errcode = '22023';
  end if;

  if coalesce(v_p.precio, 0) <= 0 then
    raise exception 'Esa inscripción no tiene nada que cobrar.' using errcode = '22023';
  end if;

  -- El fiado no es un pago: sería volver a anotar como deuda lo que ya es
  -- una deuda, y contarlo como cobrado el día que no se cobró.
  if coalesce(p_metodo, '') = 'credito' then
    raise exception 'Para dejarlo pendiente no hace falta cobrar: ya queda por cobrar.' using errcode = '22023';
  end if;

  select nombre into v_alumno from public.clientes where id = v_p.cliente_id;

  v_mov := public.registrar_venta(
    p_empresa     => v_p.empresa_id,
    p_items       => jsonb_build_array(jsonb_build_object(
                       'nombre', left(v_p.nombre, 80),
                       'cantidad', 1,
                       'precio_unitario', v_p.precio,
                       'costo_unitario', 0)),
    p_fecha       => coalesce(p_fecha, public.hoy_empresa(v_p.empresa_id)),
    p_descripcion => left(v_p.nombre, 80),
    p_metodo_pago => coalesce(p_metodo, 'efectivo'),
    p_contraparte => coalesce(v_alumno, ''),
    p_cliente     => v_p.cliente_id
  );

  update public.paquetes set movimiento_id = v_mov where id = p_paquete;

  return jsonb_build_object('movimiento', v_mov, 'monto', v_p.precio);
end $fn$;

revoke all on function public.cobrar_inscripcion(uuid, text, date) from public, anon;
grant execute on function public.cobrar_inscripcion(uuid, text, date) to authenticated;

-- ------------------------------------------------------------
-- 7. INSCRIBIR
--
--    Todo o nada: el paquete, sus clases en la agenda y —si ya pagó— la
--    venta. Si una sola clase choca, no se inscribe nada: una inscripción a
--    la que le faltan dos martes es peor que ninguna, porque el profe cree
--    que las tiene.
-- ------------------------------------------------------------
create or replace function public.inscribir_alumno(
  p_empresa     uuid,
  p_cliente     uuid,
  p_dias        smallint[],
  p_hora_desde  time,
  p_hora_hasta  time,
  p_desde       date,
  p_hasta       date,
  p_precio_hora numeric default null,
  p_total       numeric default null,
  p_pagado      boolean default false,
  p_metodo      text default 'efectivo',
  p_nombre      text default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_alumno   record;
  v_zona     text;
  v_previa   jsonb;
  v_choque   jsonb;
  v_base     jsonb;
  v_id       uuid;
  v_mov      uuid;
  v_total    numeric;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select id, nombre, coalesce(telefono, '') as telefono into v_alumno
  from public.clientes where id = p_cliente and empresa_id = p_empresa;
  if v_alumno.id is null then
    raise exception 'Ese alumno no es de esta cuenta.' using errcode = 'P0002';
  end if;

  if p_dias is null or cardinality(p_dias) = 0
     or exists (select 1 from unnest(p_dias) d where d not between 0 and 6) then
    raise exception 'Elegí al menos un día de la semana.' using errcode = '22023';
  end if;

  if p_hora_desde is null or p_hora_hasta is null or p_hora_hasta <= p_hora_desde then
    raise exception 'La clase tiene que terminar después de empezar.' using errcode = '22023';
  end if;

  if p_desde is null or p_hasta is null or p_hasta < p_desde then
    raise exception 'El período tiene que terminar después de empezar.' using errcode = '22023';
  end if;

  if p_hasta > p_desde + 366 then
    raise exception 'Se puede inscribir hasta un año de una vez.' using errcode = '22023';
  end if;

  if p_total is null and p_precio_hora is null then
    raise exception 'Poné cuánto cobrás: por hora o un precio cerrado.' using errcode = '22023';
  end if;

  if coalesce(p_total, 0) < 0 or coalesce(p_precio_hora, 0) < 0 then
    raise exception 'El precio no puede ser negativo.' using errcode = '22023';
  end if;

  v_previa := public.vista_previa_inscripcion(
    p_empresa, p_dias, p_hora_desde, p_hora_hasta, p_desde, p_hasta, p_precio_hora, p_total);

  if (v_previa->>'clases')::int = 0 then
    raise exception 'En ese período no cae ningún día de los que elegiste.' using errcode = '22023';
  end if;

  v_choque := v_previa->'choques'->0;
  if v_choque is not null then
    raise exception 'El % a las % ya tenés a %.',
      to_char((v_choque->>'fecha')::date, 'DD/MM'), v_choque->>'hora', v_choque->>'alumno'
      using errcode = '23P01';
  end if;

  v_total := (v_previa->>'total')::numeric;
  v_base  := public.profe_y_clase(p_empresa);
  select coalesce(zona_horaria, 'America/Asuncion') into v_zona from public.empresas where id = p_empresa;

  insert into public.paquetes (
    empresa_id, cliente_id, nombre, clases, precio, vence_el, creado_por,
    dias, hora_desde, hora_hasta, desde, precio_hora)
  values (
    p_empresa, p_cliente,
    left(coalesce(nullif(trim(p_nombre), ''), 'Clases'), 80),
    (v_previa->>'clases')::numeric, v_total, p_hasta, auth.uid(),
    (select array_agg(distinct d order by d) from unnest(p_dias) d),
    p_hora_desde, p_hora_hasta, p_desde,
    case when p_total is null then p_precio_hora end)
  returning id into v_id;

  -- Las clases, en la agenda. Confirmadas: ya se acordaron por WhatsApp.
  insert into public.turnos_reserva (
    empresa_id, profesional_id, producto_id, inicia, termina,
    cliente_nombre, cliente_telefono, cliente_id, paquete_id, estado, origen, creada_por)
  select
    p_empresa, (v_base->>'profesional')::uuid, (v_base->>'producto')::uuid,
    (f.d + p_hora_desde) at time zone v_zona,
    (f.d + p_hora_hasta) at time zone v_zona,
    v_alumno.nombre, v_alumno.telefono, p_cliente, v_id, 'confirmada', 'local', auth.uid()
  from public.fechas_de_horario(p_dias, p_desde, p_hasta) f(d);

  if coalesce(p_pagado, false) and v_total > 0 then
    v_mov := (public.cobrar_inscripcion(v_id, p_metodo, null)->>'movimiento')::uuid;
  end if;

  return jsonb_build_object(
    'paquete', v_id, 'clases', (v_previa->>'clases')::int, 'total', v_total, 'movimiento', v_mov);
end $fn$;

revoke all on function public.inscribir_alumno(uuid, uuid, smallint[], time, time, date, date, numeric, numeric, boolean, text, text) from public, anon;
grant execute on function public.inscribir_alumno(uuid, uuid, smallint[], time, time, date, date, numeric, numeric, boolean, text, text) to authenticated;

-- ------------------------------------------------------------
-- 8. LO QUE FALTA COBRAR
--
--    Inscripciones con precio, sin cobrar y sin cerrar. Es lo que el profe
--    ve arriba de sus alumnos: a quién le tiene que pedir la plata.
-- ------------------------------------------------------------
create or replace function public.por_cobrar_alumnos(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_lista jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'paquete', p.id, 'cliente_id', p.cliente_id, 'alumno', c.nombre,
           'nombre', p.nombre, 'monto', p.precio, 'desde', p.desde, 'hasta', p.vence_el)
         order by p.desde nulls last, c.nombre), '[]'::jsonb)
  into v_lista
  from public.paquetes p
  join public.clientes c on c.id = p.cliente_id
  where p.empresa_id = p_empresa and p.movimiento_id is null and p.precio > 0 and not p.cerrado;

  return jsonb_build_object(
    'total', coalesce((select sum((x->>'monto')::numeric) from jsonb_array_elements(v_lista) x), 0),
    'lista', v_lista);
end $fn$;

revoke all on function public.por_cobrar_alumnos(uuid) from public, anon;
grant execute on function public.por_cobrar_alumnos(uuid) to authenticated;

-- ------------------------------------------------------------
-- 9. CERRAR UNA INSCRIPCIÓN SACA SUS CLASES DE LA AGENDA
--
--    El alumno dejó: las clases que faltaban no se van a dar, y si quedan
--    en la agenda ocupan un horario que el profe podría darle a otro.
--    Reabrirla las vuelve a poner, pero solo si ese horario sigue libre: el
--    profe pudo habérselo dado a alguien mientras tanto.
-- ------------------------------------------------------------
create or replace function public.cerrar_paquete(p_paquete uuid, p_cerrado boolean default true)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_empresa uuid;
begin
  select empresa_id into v_empresa from public.paquetes where id = p_paquete;
  if v_empresa is null then
    raise exception 'Ese paquete no existe.' using errcode = 'P0002';
  end if;

  if not public.es_admin(v_empresa) then
    raise exception 'Solo el dueño de la cuenta puede cerrar un paquete.' using errcode = '42501';
  end if;

  update public.paquetes set cerrado = coalesce(p_cerrado, true) where id = p_paquete;

  if coalesce(p_cerrado, true) then
    update public.turnos_reserva
    set estado = 'cancelada'
    where paquete_id = p_paquete and estado in ('pendiente', 'confirmada') and inicia > now();
  else
    update public.turnos_reserva r
    set estado = 'confirmada'
    where r.paquete_id = p_paquete and r.estado = 'cancelada' and r.inicia > now()
      and not exists (
        select 1 from public.turnos_reserva o
        where o.empresa_id = r.empresa_id and o.id <> r.id
          and o.estado in ('pendiente', 'confirmada')
          and o.inicia < r.termina and r.inicia < o.termina);
  end if;

  return public.estado_paquete(p_paquete);
end $fn$;

revoke all on function public.cerrar_paquete(uuid, boolean) from public, anon;
grant execute on function public.cerrar_paquete(uuid, boolean) to authenticated;

-- ------------------------------------------------------------
-- 10. LA FICHA DEL ALUMNO VE EL HORARIO Y SI ESTÁ PAGADO
-- ------------------------------------------------------------
create or replace function public.paquetes_del_alumno(p_empresa uuid, p_cliente uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_lista jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(x.fila order by x.orden, x.creado desc), '[]'::jsonb)
  into v_lista
  from (
    select
      p.created_at as creado,
      case when (public.estado_paquete(p.id)->>'estado') = 'activo' then 0 else 1 end as orden,
      jsonb_build_object(
        'id', p.id,
        'nombre', p.nombre,
        'clases', p.clases,
        'precio', p.precio,
        'vence_el', p.vence_el,
        'creado', p.created_at,
        'dias', to_jsonb(p.dias),
        'hora_desde', to_char(p.hora_desde, 'HH24:MI'),
        'hora_hasta', to_char(p.hora_hasta, 'HH24:MI'),
        'desde', p.desde,
        'precio_hora', p.precio_hora,
        -- Pagado si tiene su venta, o si no había nada que cobrar.
        'pagado', p.movimiento_id is not null or coalesce(p.precio, 0) = 0
      ) || public.estado_paquete(p.id)
        || jsonb_build_object('historia', coalesce((
             select jsonb_agg(jsonb_build_object(
                      'id', c.id, 'fecha', c.fecha, 'cantidad', c.cantidad, 'motivo', c.motivo)
                    order by c.fecha desc, c.created_at desc)
             from public.clases_dadas c where c.paquete_id = p.id
           ), '[]'::jsonb)) as fila
    from public.paquetes p
    where p.empresa_id = p_empresa and p.cliente_id = p_cliente
  ) x;

  return v_lista;
end $fn$;

revoke all on function public.paquetes_del_alumno(uuid, uuid) from public, anon;
grant execute on function public.paquetes_del_alumno(uuid, uuid) to authenticated;


-- ############################################################
-- ##  092_la_clase_del_dia.sql
-- ############################################################

-- ============================================================
-- 092 · LA CLASE DEL DÍA, EL PANEL DEL PROFE Y SU RACHA
-- ============================================================
--
-- Matías, después de probar: «llega el día y me aparece atendido, cobrar,
-- mover, cancelar, no vino. Atendido y cobrar no se puede, porque yo ya
-- cobré por adelantado. Lo que podría hacer es "clase finalizada", para
-- marcar que sí se tuvo. Y si no se tuvo, en vez de "no vino", "no se tuvo
-- la clase"».
--
-- Y sobre el panel: «si entro como profesor no me puede aparecer lo
-- vendido, ganancia bruta, ganancia neta, lo que más se vendió. Tiene que
-- estar adaptado a su rubro».
--
-- MARCAR UNA CLASE NO COBRA NADA
--
-- `atender_reserva` es de la barbería: marcar atendido ES cobrar el corte,
-- ahí mismo. Un profe ya cobró el período al inscribir. Marcar la clase es
-- solo decir que pasó —y descontarla del período, por el camino de la 088,
-- con la reserva pegada para que un doble toque no la descuente dos veces.
--
-- LA CLASE QUE NO SE TUVO
--
-- Matías decidió que en cada falta se pregunte si se descuenta. Acá se
-- recibe la respuesta: con descuento queda como «falta» en la historia del
-- alumno; sin descuento la clase sigue disponible, como si nunca hubiera
-- estado agendada. En la agenda queda igual «no se tuvo».

-- ------------------------------------------------------------
-- 1. LA AGENDA DEL DÍA DICE DE QUÉ INSCRIPCIÓN ES CADA CLASE
--
--    Sin esto la pantalla no puede saber si un turno es una clase de un
--    período pagado o un corte que hay que cobrar.
-- ------------------------------------------------------------
create or replace function public.agenda_del_dia(
  p_empresa uuid,
  p_fecha   date default null
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_zona  text;
  v_fecha date;
  v_res   jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select coalesce(zona_horaria, 'America/Asuncion') into v_zona
  from public.empresas where id = p_empresa;
  v_fecha := coalesce(p_fecha, public.hoy_empresa(p_empresa));

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',          r.id,
    'inicia',      r.inicia,
    'termina',     r.termina,
    'profesional', p.nombre,
    'profesional_id', r.profesional_id,
    'servicio',    pr.nombre,
    'producto_id', r.producto_id,
    'cliente',     r.cliente_nombre,
    'telefono',    r.cliente_telefono,
    'estado',      r.estado,
    'origen',      r.origen,
    'token',       r.token,
    'avisado',     (r.avisado_at is not null),
    'paquete_id',  r.paquete_id
  ) order by r.inicia), '[]'::jsonb)
  into v_res
  from public.turnos_reserva r
  join public.turnos_profesional p on p.id = r.profesional_id
  join public.productos pr on pr.id = r.producto_id
  where r.empresa_id = p_empresa
    and (r.inicia at time zone v_zona)::date = v_fecha
    and r.estado <> 'cancelada';

  return v_res;
end $fn$;

revoke all on function public.agenda_del_dia(uuid, date) from public, anon;
grant execute on function public.agenda_del_dia(uuid, date) to authenticated;

-- ------------------------------------------------------------
-- 2. MARCAR LA CLASE: SE TUVO, O NO SE TUVO
-- ------------------------------------------------------------
create or replace function public.marcar_clase(
  p_reserva   uuid,
  p_dada      boolean default true,
  p_descontar boolean default true
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_r     public.turnos_reserva%rowtype;
  v_zona  text;
  v_fecha date;
  v_paq   jsonb;
begin
  select * into v_r from public.turnos_reserva where id = p_reserva for update;
  if not found then
    raise exception 'Esa reserva no existe.' using errcode = 'P0002';
  end if;

  if not public.es_miembro(v_r.empresa_id) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if v_r.estado not in ('pendiente', 'confirmada') then
    raise exception 'Esa reserva ya se cerró.' using errcode = '23505';
  end if;

  if v_r.paquete_id is null then
    raise exception 'Esa clase no es de ninguna inscripción.' using errcode = '22023';
  end if;

  select coalesce(zona_horaria, 'America/Asuncion') into v_zona
  from public.empresas where id = v_r.empresa_id;
  -- La fecha de la CLASE, no la de hoy: la del lunes que se marca el martes
  -- sigue siendo del lunes.
  v_fecha := (v_r.inicia at time zone v_zona)::date;

  if coalesce(p_dada, true) then
    v_paq := public.dar_clase(v_r.paquete_id, 1, v_fecha, 'dada', p_reserva);
    update public.turnos_reserva set estado = 'atendida' where id = p_reserva;
  else
    if coalesce(p_descontar, true) then
      v_paq := public.dar_clase(v_r.paquete_id, 1, v_fecha, 'falta', p_reserva);
    else
      v_paq := public.estado_paquete(v_r.paquete_id);
    end if;
    update public.turnos_reserva set estado = 'no_vino' where id = p_reserva;
  end if;

  return jsonb_build_object('reserva', p_reserva, 'paquete', v_paq);
end $fn$;

revoke all on function public.marcar_clase(uuid, boolean, boolean) from public, anon;
grant execute on function public.marcar_clase(uuid, boolean, boolean) to authenticated;

-- ------------------------------------------------------------
-- 3. LA RACHA CUENTA LOS DÍAS CON CLASE DADA
--
--    Un profe no cierra caja ni carga ventas: su «cargué algo hoy» es marcar
--    la clase. Va a la única fuente de la racha (080), así que el panel, el
--    descuento por constancia y el recordatorio miran lo mismo.
--
--    Lo que todavía NO hace: que los días sin clases no corten la racha.
--    Eso cambia la regla de las islas y va aparte.
-- ------------------------------------------------------------
create or replace function public.dias_cargados(p_empresa uuid, p_hasta date)
returns setof date language sql stable security definer set search_path = public as $fn$
  select fecha
  from (
    select m.fecha
    from public.movimientos m
    where m.empresa_id = p_empresa and m.estado = 'activo' and m.fecha <= p_hasta
    union
    select a.fecha
    from public.movimientos_ahorro a
    where a.empresa_id = p_empresa and a.fecha <= p_hasta
    union
    select c.fecha
    from public.clases_dadas c
    where c.empresa_id = p_empresa and c.motivo = 'dada' and c.fecha <= p_hasta
  ) d
  group by fecha;
$fn$;

revoke all on function public.dias_cargados(uuid, date) from public, anon, authenticated;

-- ------------------------------------------------------------
-- 4. LO QUE MIRA UN PROFE AL ABRIR ORDEN
--
--    Nada de vendido ni de ganancia bruta. Sus preguntas son otras: ¿qué
--    clases tengo hoy?, ¿cuánto cobré?, ¿quién me debe?, ¿cuántos alumnos
--    activos tengo?
-- ------------------------------------------------------------
create or replace function public.panel_profe(p_empresa uuid, p_desde date, p_hasta date)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_zona text;
  v_hoy  date;
  v_res  jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select coalesce(zona_horaria, 'America/Asuncion') into v_zona from public.empresas where id = p_empresa;
  v_hoy := public.hoy_empresa(p_empresa);

  select jsonb_build_object(
    'hoy', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', r.id, 'hora', to_char(r.inicia at time zone v_zona, 'HH24:MI'),
        'alumno', r.cliente_nombre, 'estado', r.estado) order by r.inicia)
      from public.turnos_reserva r
      where r.empresa_id = p_empresa and r.estado <> 'cancelada'
        and (r.inicia at time zone v_zona)::date = v_hoy), '[]'::jsonb),
    'clases_periodo', (
      select count(*)::int from public.turnos_reserva r
      where r.empresa_id = p_empresa and r.estado = 'atendida'
        and (r.inicia at time zone v_zona)::date between p_desde and p_hasta),
    'cobrado', coalesce((
      select sum(m.monto) from public.movimientos m
      where m.empresa_id = p_empresa and m.estado = 'activo' and m.tipo in ('venta', 'ingreso')
        and m.fecha between p_desde and p_hasta), 0),
    'gastado', coalesce((
      select sum(m.monto) from public.movimientos m
      where m.empresa_id = p_empresa and m.estado = 'activo' and m.tipo = 'gasto'
        and m.fecha between p_desde and p_hasta), 0),
    'por_cobrar', coalesce((
      select sum(p.precio) from public.paquetes p
      where p.empresa_id = p_empresa and p.movimiento_id is null and p.precio > 0 and not p.cerrado), 0),
    'deben', (
      select count(distinct p.cliente_id)::int from public.paquetes p
      where p.empresa_id = p_empresa and p.movimiento_id is null and p.precio > 0 and not p.cerrado),
    'alumnos_activos', (
      select count(distinct p.cliente_id)::int from public.paquetes p
      where p.empresa_id = p_empresa and not p.cerrado
        and (public.estado_paquete(p.id)->>'estado') = 'activo')
  ) into v_res;

  return v_res;
end $fn$;

revoke all on function public.panel_profe(uuid, date, date) from public, anon;
grant execute on function public.panel_profe(uuid, date, date) to authenticated;


-- ############################################################
-- ##  093_constancia_al_cinco.sql
-- ############################################################

-- ============================================================
-- 093 · EL DESCUENTO POR CONSTANCIA BAJA A 5%
-- ============================================================
--
-- Matías: «el descuento después de la primera suscripción, si completaba
-- la racha de 30 días, era de 20%. Estuve calculando y 20% es muchísimo.
-- Quiero que sea solo 5%».
--
-- LO QUE QUEDA, ENTERO
--
--   · LA PRUEBA NO CAMBIA. Junta la racha de la prueba —8 días un negocio,
--     5 una cuenta personal— y el primer mes sale 18% más barato.
--   · DESPUÉS DE PAGAR: con 30 días seguidos cargando, la renovación sale
--     5% más barata. Y así todos los meses, mientras la racha siga viva.
--     Si se corta, se pausa hasta volver a juntar los 30. Es el mismo
--     trato de la 079, con otro número.
--
-- A QUIÉN LE TOCA
--
-- A nadie se le quita algo que ya ganó. Al 21/09 hay dos suscripciones
-- activas, y ninguna tiene racha hoy: la más larga que llegaron a juntar
-- fue de 2 días, lejos de los 30 que hacían falta para el 20%.
--
-- EL NÚMERO VIVE EN UN SOLO LUGAR
--
-- `ajustes_orden.descuento_constancia_porcentaje`. Todos los textos —el
-- panel, el plan, la página de inicio, el correo de activación, el
-- recordatorio— lo leen de ahí. Se cambia también el valor por defecto de
-- la columna y la reserva de las dos funciones que lo leen, para que no
-- quede un 20 escrito en ningún lado esperando a reaparecer.

-- ------------------------------------------------------------
-- 1. EL NÚMERO
-- ------------------------------------------------------------
alter table public.ajustes_orden
  alter column descuento_constancia_porcentaje set default 5;

update public.ajustes_orden set descuento_constancia_porcentaje = 5 where unica;

-- ------------------------------------------------------------
-- 2. LO QUE MUESTRA LA PÁGINA DE INICIO
--
--    Copia exacta de la versión viva (079), con la reserva de la
--    constancia en 5.
-- ------------------------------------------------------------
create or replace function public.promo_de_la_prueba()
returns jsonb language sql stable security definer set search_path = public as $fn$
  select jsonb_build_object(
    'porcentaje',            coalesce((select descuento_racha_porcentaje from public.ajustes_orden where unica), 18),
    'negocio',               coalesce((select racha_objetivo_negocio    from public.ajustes_orden where unica), 8),
    'personal',              coalesce((select racha_objetivo_personal   from public.ajustes_orden where unica), 5),
    'constancia_porcentaje', coalesce((select descuento_constancia_porcentaje from public.ajustes_orden where unica), 5),
    'constancia_dias',       coalesce((select racha_objetivo_constancia       from public.ajustes_orden where unica), 30)
  );
$fn$;

-- ------------------------------------------------------------
-- 3. EL DESCUENTO QUE CORRESPONDE HOY
--
--    Copia exacta de la versión viva (080), con la reserva de la
--    constancia en 5. Nada más cambia: ni las fases, ni los objetivos, ni
--    cómo se cuenta la racha.
-- ------------------------------------------------------------
create or replace function public.descuento_por_racha(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_tipo     text;
  v_zona     text;
  v_desde    date;
  v_hasta    date;
  v_hoy      date;
  v_objetivo integer;
  v_pct      numeric;
  v_mejor    integer := 0;
  v_vigente  boolean := false;
  v_fase     text;
  v_ajustes  record;
  v_sus      record;
begin
  if not public.es_admin(p_empresa) and not public.es_superadmin() then
    raise exception 'Solo el dueño de la cuenta puede ver esto.' using errcode = '42501';
  end if;

  select coalesce(e.tipo_cuenta, 'emprendedor'), coalesce(e.zona_horaria, 'America/Asuncion')
  into v_tipo, v_zona
  from public.empresas e where e.id = p_empresa;

  if v_tipo is null then
    raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
  end if;

  select * into v_ajustes from public.ajustes_orden where unica;
  v_hoy := (now() at time zone v_zona)::date;

  select s.* into v_sus from public.suscripciones s where s.empresa_id = p_empresa;

  if v_sus.empresa_id is null then
    return jsonb_build_object(
      'fase', 'prueba', 'objetivo', coalesce(v_ajustes.racha_objetivo_negocio, 8),
      'mejor', 0, 'faltan', coalesce(v_ajustes.racha_objetivo_negocio, 8),
      'logrado', false, 'porcentaje', coalesce(v_ajustes.descuento_racha_porcentaje, 18),
      'vigente', false);
  end if;

  v_fase := case
    when v_sus.estado = 'activa' and coalesce(v_sus.plan, 'gratis') <> 'gratis' then 'constancia'
    else 'prueba'
  end;

  if v_fase = 'constancia' then
    v_pct      := coalesce(v_ajustes.descuento_constancia_porcentaje, 5);
    v_objetivo := coalesce(v_ajustes.racha_objetivo_constancia, 30);
    with dias as (
      select d.fecha from public.dias_cargados(p_empresa, v_hoy) d(fecha)
    ),
    numeradas as (
      select fecha, (fecha - (row_number() over (order by fecha))::int) as isla from dias
    ),
    rachas as (
      select isla, count(*)::int as largo, max(fecha) as hasta from numeradas group by isla
    )
    select coalesce((select largo from rachas where hasta in (v_hoy, v_hoy - 1)
                     order by hasta desc limit 1), 0)
    into v_mejor;
    v_vigente := true;
  else
    v_pct      := coalesce(v_ajustes.descuento_racha_porcentaje, 18);
    v_objetivo := coalesce(
      case when v_tipo = 'personal' then v_ajustes.racha_objetivo_personal
           else v_ajustes.racha_objetivo_negocio end,
      case when v_tipo = 'personal' then 5 else 8 end);

    v_desde := (v_sus.created_at at time zone v_zona)::date;
    v_hasta := least(v_hoy, (coalesce(v_sus.prueba_fin, now()) at time zone v_zona)::date);
    v_vigente := v_sus.estado = 'prueba'
                 and v_hoy <= (coalesce(v_sus.prueba_fin, now()) at time zone v_zona)::date;

    with dias as (
      select d.fecha from public.dias_cargados(p_empresa, v_hasta) d(fecha)
      where d.fecha >= v_desde
    ),
    numeradas as (
      select fecha, (fecha - (row_number() over (order by fecha))::int) as isla from dias
    )
    select coalesce(max(largo), 0) into v_mejor
    from (select count(*)::int as largo from numeradas group by isla) r;
  end if;

  return jsonb_build_object(
    'fase',       v_fase,
    'objetivo',   v_objetivo,
    'mejor',      v_mejor,
    'faltan',     greatest(0, v_objetivo - v_mejor),
    'logrado',    v_mejor >= v_objetivo,
    'porcentaje', v_pct,
    'vigente',    v_vigente
  );
end $fn$;

revoke all on function public.descuento_por_racha(uuid) from public, anon;
grant execute on function public.descuento_por_racha(uuid) to authenticated;
grant execute on function public.promo_de_la_prueba() to anon, authenticated;


-- ############################################################
-- ##  094_que_se_le_ensena.sql
-- ############################################################

-- ============================================================
-- 094 · QUÉ SE LE ENSEÑA A CADA ALUMNO
-- ============================================================
--
-- Matías: «al momento de inscribir a un alumno, tener una opción donde
-- especificar qué es lo que se le va a enseñar: inglés, matemática, o algo
-- distinto. Así para saber qué se le enseña a cada alumno».
--
-- Un profe que da inglés a las cinco y matemática a las seis mira la agenda
-- y tiene que saber qué preparar sin abrir la ficha de cada uno. Así que la
-- materia se anota al inscribir y se ve donde se mira el día: la agenda, las
-- clases de hoy del panel, la ficha del alumno y lo que falta cobrar.
--
-- ES DE LA INSCRIPCIÓN, NO DEL ALUMNO
--
-- El mismo alumno puede tomar inglés en marzo y francés en agosto, o las dos
-- cosas a la vez en dos horarios. La materia va con cada inscripción.
--
-- TEXTO LIBRE, CON SUGERENCIAS
--
-- No hay una lista cerrada de materias: nadie puede adivinar qué enseña cada
-- profe («Guitarra», «Excel», «Apoyo escolar 3er grado»). Se escribe lo que
-- sea, y al escribir se sugieren las que ese profe ya usó, para que «Inglés»
-- no termine siendo también «ingles» e «Ingles».

-- ------------------------------------------------------------
-- 1. LA COLUMNA
-- ------------------------------------------------------------
alter table public.paquetes
  add column if not exists materia text check (materia is null or char_length(materia) <= 60);

comment on column public.paquetes.materia is
  'Qué se le enseña en esta inscripción (094). Texto libre; null si no se dijo.';

-- ------------------------------------------------------------
-- 2. INSCRIBIR, AHORA CON LA MATERIA
--
--    La firma vieja se borra antes de crear la nueva: con un parámetro
--    más, `create or replace` no reemplaza, crea una segunda función al
--    lado, y la llamada de siempre se vuelve ambigua.
--
--    Copia exacta de la 091 salvo `p_materia` y la columna que la guarda.
-- ------------------------------------------------------------
drop function if exists public.inscribir_alumno(uuid, uuid, smallint[], time, time, date, date, numeric, numeric, boolean, text, text);

create or replace function public.inscribir_alumno(
  p_empresa     uuid,
  p_cliente     uuid,
  p_dias        smallint[],
  p_hora_desde  time,
  p_hora_hasta  time,
  p_desde       date,
  p_hasta       date,
  p_precio_hora numeric default null,
  p_total       numeric default null,
  p_pagado      boolean default false,
  p_metodo      text default 'efectivo',
  p_nombre      text default null,
  p_materia     text default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_alumno   record;
  v_zona     text;
  v_previa   jsonb;
  v_choque   jsonb;
  v_base     jsonb;
  v_id       uuid;
  v_mov      uuid;
  v_total    numeric;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select id, nombre, coalesce(telefono, '') as telefono into v_alumno
  from public.clientes where id = p_cliente and empresa_id = p_empresa;
  if v_alumno.id is null then
    raise exception 'Ese alumno no es de esta cuenta.' using errcode = 'P0002';
  end if;

  if p_dias is null or cardinality(p_dias) = 0
     or exists (select 1 from unnest(p_dias) d where d not between 0 and 6) then
    raise exception 'Elegí al menos un día de la semana.' using errcode = '22023';
  end if;

  if p_hora_desde is null or p_hora_hasta is null or p_hora_hasta <= p_hora_desde then
    raise exception 'La clase tiene que terminar después de empezar.' using errcode = '22023';
  end if;

  if p_desde is null or p_hasta is null or p_hasta < p_desde then
    raise exception 'El período tiene que terminar después de empezar.' using errcode = '22023';
  end if;

  if p_hasta > p_desde + 366 then
    raise exception 'Se puede inscribir hasta un año de una vez.' using errcode = '22023';
  end if;

  if p_total is null and p_precio_hora is null then
    raise exception 'Poné cuánto cobrás: por hora o un precio cerrado.' using errcode = '22023';
  end if;

  if coalesce(p_total, 0) < 0 or coalesce(p_precio_hora, 0) < 0 then
    raise exception 'El precio no puede ser negativo.' using errcode = '22023';
  end if;

  v_previa := public.vista_previa_inscripcion(
    p_empresa, p_dias, p_hora_desde, p_hora_hasta, p_desde, p_hasta, p_precio_hora, p_total);

  if (v_previa->>'clases')::int = 0 then
    raise exception 'En ese período no cae ningún día de los que elegiste.' using errcode = '22023';
  end if;

  v_choque := v_previa->'choques'->0;
  if v_choque is not null then
    raise exception 'El % a las % ya tenés a %.',
      to_char((v_choque->>'fecha')::date, 'DD/MM'), v_choque->>'hora', v_choque->>'alumno'
      using errcode = '23P01';
  end if;

  v_total := (v_previa->>'total')::numeric;
  v_base  := public.profe_y_clase(p_empresa);
  select coalesce(zona_horaria, 'America/Asuncion') into v_zona from public.empresas where id = p_empresa;

  insert into public.paquetes (
    empresa_id, cliente_id, nombre, clases, precio, vence_el, creado_por,
    dias, hora_desde, hora_hasta, desde, precio_hora, materia)
  values (
    p_empresa, p_cliente,
    left(coalesce(nullif(trim(p_nombre), ''), 'Clases'), 80),
    (v_previa->>'clases')::numeric, v_total, p_hasta, auth.uid(),
    (select array_agg(distinct d order by d) from unnest(p_dias) d),
    p_hora_desde, p_hora_hasta, p_desde,
    case when p_total is null then p_precio_hora end,
    nullif(left(trim(coalesce(p_materia, '')), 60), ''))
  returning id into v_id;

  insert into public.turnos_reserva (
    empresa_id, profesional_id, producto_id, inicia, termina,
    cliente_nombre, cliente_telefono, cliente_id, paquete_id, estado, origen, creada_por)
  select
    p_empresa, (v_base->>'profesional')::uuid, (v_base->>'producto')::uuid,
    (f.d + p_hora_desde) at time zone v_zona,
    (f.d + p_hora_hasta) at time zone v_zona,
    v_alumno.nombre, v_alumno.telefono, p_cliente, v_id, 'confirmada', 'local', auth.uid()
  from public.fechas_de_horario(p_dias, p_desde, p_hasta) f(d);

  if coalesce(p_pagado, false) and v_total > 0 then
    v_mov := (public.cobrar_inscripcion(v_id, p_metodo, null)->>'movimiento')::uuid;
  end if;

  return jsonb_build_object(
    'paquete', v_id, 'clases', (v_previa->>'clases')::int, 'total', v_total, 'movimiento', v_mov);
end $fn$;

revoke all on function public.inscribir_alumno(uuid, uuid, smallint[], time, time, date, date, numeric, numeric, boolean, text, text, text) from public, anon;
grant execute on function public.inscribir_alumno(uuid, uuid, smallint[], time, time, date, date, numeric, numeric, boolean, text, text, text) to authenticated;

-- ------------------------------------------------------------
-- 3. LAS MATERIAS QUE YA USÓ, PARA SUGERIRLAS
--
--    La más usada primero. Así el profe escribe «In» y le aparece «Inglés»
--    tal como la escribió la primera vez.
-- ------------------------------------------------------------
create or replace function public.materias_usadas(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_lista jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(m.materia order by m.veces desc, m.ultima desc), '[]'::jsonb)
  into v_lista
  from (
    select p.materia, count(*) as veces, max(p.created_at) as ultima
    from public.paquetes p
    where p.empresa_id = p_empresa and p.materia is not null
    group by p.materia
    order by count(*) desc, max(p.created_at) desc
    limit 30
  ) m;

  return v_lista;
end $fn$;

revoke all on function public.materias_usadas(uuid) from public, anon;
grant execute on function public.materias_usadas(uuid) to authenticated;

-- ------------------------------------------------------------
-- 4. LA AGENDA DEL DÍA DICE QUÉ SE DA EN CADA CLASE
--
--    Copia exacta de la 092 con la materia de la inscripción.
-- ------------------------------------------------------------
create or replace function public.agenda_del_dia(
  p_empresa uuid,
  p_fecha   date default null
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_zona  text;
  v_fecha date;
  v_res   jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select coalesce(zona_horaria, 'America/Asuncion') into v_zona
  from public.empresas where id = p_empresa;
  v_fecha := coalesce(p_fecha, public.hoy_empresa(p_empresa));

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',          r.id,
    'inicia',      r.inicia,
    'termina',     r.termina,
    'profesional', p.nombre,
    'profesional_id', r.profesional_id,
    'servicio',    pr.nombre,
    'producto_id', r.producto_id,
    'cliente',     r.cliente_nombre,
    'telefono',    r.cliente_telefono,
    'estado',      r.estado,
    'origen',      r.origen,
    'token',       r.token,
    'avisado',     (r.avisado_at is not null),
    'paquete_id',  r.paquete_id,
    'materia',     pq.materia
  ) order by r.inicia), '[]'::jsonb)
  into v_res
  from public.turnos_reserva r
  join public.turnos_profesional p on p.id = r.profesional_id
  join public.productos pr on pr.id = r.producto_id
  left join public.paquetes pq on pq.id = r.paquete_id
  where r.empresa_id = p_empresa
    and (r.inicia at time zone v_zona)::date = v_fecha
    and r.estado <> 'cancelada';

  return v_res;
end $fn$;

revoke all on function public.agenda_del_dia(uuid, date) from public, anon;
grant execute on function public.agenda_del_dia(uuid, date) to authenticated;

-- ------------------------------------------------------------
-- 5. LAS CLASES DE HOY DEL PANEL, CON SU MATERIA
--
--    Copia exacta de la 092 con la materia en cada clase de hoy.
-- ------------------------------------------------------------
create or replace function public.panel_profe(p_empresa uuid, p_desde date, p_hasta date)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_zona text;
  v_hoy  date;
  v_res  jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select coalesce(zona_horaria, 'America/Asuncion') into v_zona from public.empresas where id = p_empresa;
  v_hoy := public.hoy_empresa(p_empresa);

  select jsonb_build_object(
    'hoy', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', r.id, 'hora', to_char(r.inicia at time zone v_zona, 'HH24:MI'),
        'alumno', r.cliente_nombre, 'estado', r.estado, 'materia', pq.materia) order by r.inicia)
      from public.turnos_reserva r
      left join public.paquetes pq on pq.id = r.paquete_id
      where r.empresa_id = p_empresa and r.estado <> 'cancelada'
        and (r.inicia at time zone v_zona)::date = v_hoy), '[]'::jsonb),
    'clases_periodo', (
      select count(*)::int from public.turnos_reserva r
      where r.empresa_id = p_empresa and r.estado = 'atendida'
        and (r.inicia at time zone v_zona)::date between p_desde and p_hasta),
    'cobrado', coalesce((
      select sum(m.monto) from public.movimientos m
      where m.empresa_id = p_empresa and m.estado = 'activo' and m.tipo in ('venta', 'ingreso')
        and m.fecha between p_desde and p_hasta), 0),
    'gastado', coalesce((
      select sum(m.monto) from public.movimientos m
      where m.empresa_id = p_empresa and m.estado = 'activo' and m.tipo = 'gasto'
        and m.fecha between p_desde and p_hasta), 0),
    'por_cobrar', coalesce((
      select sum(p.precio) from public.paquetes p
      where p.empresa_id = p_empresa and p.movimiento_id is null and p.precio > 0 and not p.cerrado), 0),
    'deben', (
      select count(distinct p.cliente_id)::int from public.paquetes p
      where p.empresa_id = p_empresa and p.movimiento_id is null and p.precio > 0 and not p.cerrado),
    'alumnos_activos', (
      select count(distinct p.cliente_id)::int from public.paquetes p
      where p.empresa_id = p_empresa and not p.cerrado
        and (public.estado_paquete(p.id)->>'estado') = 'activo')
  ) into v_res;

  return v_res;
end $fn$;

revoke all on function public.panel_profe(uuid, date, date) from public, anon;
grant execute on function public.panel_profe(uuid, date, date) to authenticated;

-- ------------------------------------------------------------
-- 6. LA FICHA DEL ALUMNO Y LO QUE FALTA COBRAR, CON LA MATERIA
--
--    Copias exactas de la 091 con la materia.
-- ------------------------------------------------------------
create or replace function public.paquetes_del_alumno(p_empresa uuid, p_cliente uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_lista jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(x.fila order by x.orden, x.creado desc), '[]'::jsonb)
  into v_lista
  from (
    select
      p.created_at as creado,
      case when (public.estado_paquete(p.id)->>'estado') = 'activo' then 0 else 1 end as orden,
      jsonb_build_object(
        'id', p.id,
        'nombre', p.nombre,
        'materia', p.materia,
        'clases', p.clases,
        'precio', p.precio,
        'vence_el', p.vence_el,
        'creado', p.created_at,
        'dias', to_jsonb(p.dias),
        'hora_desde', to_char(p.hora_desde, 'HH24:MI'),
        'hora_hasta', to_char(p.hora_hasta, 'HH24:MI'),
        'desde', p.desde,
        'precio_hora', p.precio_hora,
        'pagado', p.movimiento_id is not null or coalesce(p.precio, 0) = 0
      ) || public.estado_paquete(p.id)
        || jsonb_build_object('historia', coalesce((
             select jsonb_agg(jsonb_build_object(
                      'id', c.id, 'fecha', c.fecha, 'cantidad', c.cantidad, 'motivo', c.motivo)
                    order by c.fecha desc, c.created_at desc)
             from public.clases_dadas c where c.paquete_id = p.id
           ), '[]'::jsonb)) as fila
    from public.paquetes p
    where p.empresa_id = p_empresa and p.cliente_id = p_cliente
  ) x;

  return v_lista;
end $fn$;

revoke all on function public.paquetes_del_alumno(uuid, uuid) from public, anon;
grant execute on function public.paquetes_del_alumno(uuid, uuid) to authenticated;

create or replace function public.por_cobrar_alumnos(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_lista jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'paquete', p.id, 'cliente_id', p.cliente_id, 'alumno', c.nombre,
           'nombre', p.nombre, 'materia', p.materia,
           'monto', p.precio, 'desde', p.desde, 'hasta', p.vence_el)
         order by p.desde nulls last, c.nombre), '[]'::jsonb)
  into v_lista
  from public.paquetes p
  join public.clientes c on c.id = p.cliente_id
  where p.empresa_id = p_empresa and p.movimiento_id is null and p.precio > 0 and not p.cerrado;

  return jsonb_build_object(
    'total', coalesce((select sum((x->>'monto')::numeric) from jsonb_array_elements(v_lista) x), 0),
    'lista', v_lista);
end $fn$;

revoke all on function public.por_cobrar_alumnos(uuid) from public, anon;
grant execute on function public.por_cobrar_alumnos(uuid) to authenticated;


-- ############################################################
-- ##  095_el_cobro_dice_a_que_cuenta.sql
-- ############################################################

-- ============================================================
-- 095 · EL COBRO DICE A QUÉ CUENTA ENTRÓ
-- ============================================================
--
-- Matías: «al cobrar, si selecciono transferencia, me debería aparecer la
-- opción de a cuál banco se me va a acreditar. Tengo Atlas, Continental,
-- Ueno registrados en la billetera. Si se me transfirió en mi Continental y
-- en Orden se me carga en el Atlas, no tiene sentido: no es sincronización».
--
-- Tiene razón. Desde la 074 cada forma de pago vive en UNA cuenta: todas
-- las transferencias caen en el banco que reclama «transferencia». Con un
-- solo banco da igual; con tres, el alumno que te transfirió al Continental
-- te aparece en el Atlas, y la billetera de Orden deja de coincidir con la
-- de tu celular. Que es justamente lo único que tiene que hacer.
--
-- Así que cobrar una inscripción —al inscribir o después— puede decir en
-- qué cuenta entró. Si no se dice, va como siempre: a la cuenta de esa forma
-- de pago. Es lo mismo que ya hacía el fiado desde la 084.
--
-- Las firmas viejas se borran antes de crear las nuevas: con un parámetro
-- más, `create or replace` crea una segunda función al lado y la llamada de
-- siempre se vuelve ambigua. Las dos son copias exactas de su versión viva
-- (091 y 094) con la cuenta agregada.

-- ------------------------------------------------------------
-- 1. COBRAR UNA INSCRIPCIÓN, EN LA CUENTA QUE SE ELIJA
-- ------------------------------------------------------------
drop function if exists public.cobrar_inscripcion(uuid, text, date);

create or replace function public.cobrar_inscripcion(
  p_paquete uuid,
  p_metodo  text default 'efectivo',
  p_fecha   date default null,
  p_cuenta  uuid default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_p      record;
  v_alumno text;
  v_mov    uuid;
begin
  select * into v_p from public.paquetes where id = p_paquete for update;
  if v_p.id is null then
    raise exception 'Ese paquete no existe.' using errcode = 'P0002';
  end if;

  if not public.es_miembro(v_p.empresa_id) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if v_p.movimiento_id is not null then
    raise exception 'Esa inscripción ya está cobrada.' using errcode = '22023';
  end if;

  if coalesce(v_p.precio, 0) <= 0 then
    raise exception 'Esa inscripción no tiene nada que cobrar.' using errcode = '22023';
  end if;

  -- Decir en qué cuenta entró es administrar la billetera: lo mismo que al
  -- cobrar un fiado (084). Se revisa antes de anotar nada.
  if p_cuenta is not null then
    if not public.es_admin(v_p.empresa_id) then
      raise exception 'Solo el dueño de la cuenta puede elegir en qué cuenta entra.' using errcode = '42501';
    end if;
    if not exists (select 1 from public.cuentas_dinero c
                   where c.id = p_cuenta and c.empresa_id = v_p.empresa_id and c.activa) then
      raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
    end if;
  end if;

  -- El fiado no es un pago: sería volver a anotar como deuda lo que ya es
  -- una deuda, y contarlo como cobrado el día que no se cobró.
  if coalesce(p_metodo, '') = 'credito' then
    raise exception 'Para dejarlo pendiente no hace falta cobrar: ya queda por cobrar.' using errcode = '22023';
  end if;

  select nombre into v_alumno from public.clientes where id = v_p.cliente_id;

  v_mov := public.registrar_venta(
    p_empresa     => v_p.empresa_id,
    p_items       => jsonb_build_array(jsonb_build_object(
                       'nombre', left(v_p.nombre, 80),
                       'cantidad', 1,
                       'precio_unitario', v_p.precio,
                       'costo_unitario', 0)),
    p_fecha       => coalesce(p_fecha, public.hoy_empresa(v_p.empresa_id)),
    p_descripcion => left(v_p.nombre, 80),
    p_metodo_pago => coalesce(p_metodo, 'efectivo'),
    p_contraparte => coalesce(v_alumno, ''),
    p_cliente     => v_p.cliente_id
  );

  -- La cuenta elegida gana sobre la forma de pago (075): «me transfirió al
  -- Continental» va al Continental aunque las transferencias caigan, por
  -- defecto, en el Atlas. El disparador de la 074 acepta el cambio porque la
  -- cuenta es de la misma empresa.
  if p_cuenta is not null then
    update public.movimientos set cuenta_id = p_cuenta where id = v_mov;
  end if;

  update public.paquetes set movimiento_id = v_mov where id = p_paquete;

  return jsonb_build_object('movimiento', v_mov, 'monto', v_p.precio);
end $fn$;

revoke all on function public.cobrar_inscripcion(uuid, text, date, uuid) from public, anon;
grant execute on function public.cobrar_inscripcion(uuid, text, date, uuid) to authenticated;

-- ------------------------------------------------------------
-- 2. INSCRIBIR, PAGANDO EN LA CUENTA QUE SE ELIJA
-- ------------------------------------------------------------
drop function if exists public.inscribir_alumno(uuid, uuid, smallint[], time, time, date, date, numeric, numeric, boolean, text, text, text);

create or replace function public.inscribir_alumno(
  p_empresa     uuid,
  p_cliente     uuid,
  p_dias        smallint[],
  p_hora_desde  time,
  p_hora_hasta  time,
  p_desde       date,
  p_hasta       date,
  p_precio_hora numeric default null,
  p_total       numeric default null,
  p_pagado      boolean default false,
  p_metodo      text default 'efectivo',
  p_nombre      text default null,
  p_materia     text default null,
  p_cuenta      uuid default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_alumno   record;
  v_zona     text;
  v_previa   jsonb;
  v_choque   jsonb;
  v_base     jsonb;
  v_id       uuid;
  v_mov      uuid;
  v_total    numeric;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select id, nombre, coalesce(telefono, '') as telefono into v_alumno
  from public.clientes where id = p_cliente and empresa_id = p_empresa;
  if v_alumno.id is null then
    raise exception 'Ese alumno no es de esta cuenta.' using errcode = 'P0002';
  end if;

  if p_dias is null or cardinality(p_dias) = 0
     or exists (select 1 from unnest(p_dias) d where d not between 0 and 6) then
    raise exception 'Elegí al menos un día de la semana.' using errcode = '22023';
  end if;

  if p_hora_desde is null or p_hora_hasta is null or p_hora_hasta <= p_hora_desde then
    raise exception 'La clase tiene que terminar después de empezar.' using errcode = '22023';
  end if;

  if p_desde is null or p_hasta is null or p_hasta < p_desde then
    raise exception 'El período tiene que terminar después de empezar.' using errcode = '22023';
  end if;

  if p_hasta > p_desde + 366 then
    raise exception 'Se puede inscribir hasta un año de una vez.' using errcode = '22023';
  end if;

  if p_total is null and p_precio_hora is null then
    raise exception 'Poné cuánto cobrás: por hora o un precio cerrado.' using errcode = '22023';
  end if;

  if coalesce(p_total, 0) < 0 or coalesce(p_precio_hora, 0) < 0 then
    raise exception 'El precio no puede ser negativo.' using errcode = '22023';
  end if;

  v_previa := public.vista_previa_inscripcion(
    p_empresa, p_dias, p_hora_desde, p_hora_hasta, p_desde, p_hasta, p_precio_hora, p_total);

  if (v_previa->>'clases')::int = 0 then
    raise exception 'En ese período no cae ningún día de los que elegiste.' using errcode = '22023';
  end if;

  v_choque := v_previa->'choques'->0;
  if v_choque is not null then
    raise exception 'El % a las % ya tenés a %.',
      to_char((v_choque->>'fecha')::date, 'DD/MM'), v_choque->>'hora', v_choque->>'alumno'
      using errcode = '23P01';
  end if;

  v_total := (v_previa->>'total')::numeric;
  v_base  := public.profe_y_clase(p_empresa);
  select coalesce(zona_horaria, 'America/Asuncion') into v_zona from public.empresas where id = p_empresa;

  insert into public.paquetes (
    empresa_id, cliente_id, nombre, clases, precio, vence_el, creado_por,
    dias, hora_desde, hora_hasta, desde, precio_hora, materia)
  values (
    p_empresa, p_cliente,
    left(coalesce(nullif(trim(p_nombre), ''), 'Clases'), 80),
    (v_previa->>'clases')::numeric, v_total, p_hasta, auth.uid(),
    (select array_agg(distinct d order by d) from unnest(p_dias) d),
    p_hora_desde, p_hora_hasta, p_desde,
    case when p_total is null then p_precio_hora end,
    nullif(left(trim(coalesce(p_materia, '')), 60), ''))
  returning id into v_id;

  insert into public.turnos_reserva (
    empresa_id, profesional_id, producto_id, inicia, termina,
    cliente_nombre, cliente_telefono, cliente_id, paquete_id, estado, origen, creada_por)
  select
    p_empresa, (v_base->>'profesional')::uuid, (v_base->>'producto')::uuid,
    (f.d + p_hora_desde) at time zone v_zona,
    (f.d + p_hora_hasta) at time zone v_zona,
    v_alumno.nombre, v_alumno.telefono, p_cliente, v_id, 'confirmada', 'local', auth.uid()
  from public.fechas_de_horario(p_dias, p_desde, p_hasta) f(d);

  if coalesce(p_pagado, false) and v_total > 0 then
    v_mov := (public.cobrar_inscripcion(v_id, p_metodo, null, p_cuenta)->>'movimiento')::uuid;
  end if;

  return jsonb_build_object(
    'paquete', v_id, 'clases', (v_previa->>'clases')::int, 'total', v_total, 'movimiento', v_mov);
end $fn$;

revoke all on function public.inscribir_alumno(uuid, uuid, smallint[], time, time, date, date, numeric, numeric, boolean, text, text, text, uuid) from public, anon;
grant execute on function public.inscribir_alumno(uuid, uuid, smallint[], time, time, date, date, numeric, numeric, boolean, text, text, text, uuid) to authenticated;


-- ############################################################
-- ##  096_la_venta_dice_a_que_cuenta.sql
-- ############################################################

-- ============================================================
-- 096 · LA VENTA TAMBIÉN DICE A QUÉ CUENTA ENTRÓ
-- ============================================================
--
-- La 095 lo hizo para el cobro de un alumno. Matías lo pidió para todo
-- cobro: «al cobrar, si selecciono transferencia, me debería aparecer la
-- opción de a cuál banco se me va a acreditar». En la pantalla de Cobrar
-- pasa lo mismo: con Atlas y Continental, toda transferencia caía en el que
-- reclama «transferencia», aunque la plata haya llegado al otro.
--
-- `registrar_venta` suma un parámetro al final, `p_cuenta`. Sin él todo
-- sigue igual: la captura inteligente, los paquetes y las correcciones
-- (`reemplazar_venta`, que la llama con nueve argumentos) no cambian.
--
-- Es una copia exacta de la 055 —la versión viva; su cuerpo, sin
-- comentarios, da la misma huella— con la cuenta agregada. La firma vieja
-- se borra antes: con un parámetro más, `create or replace` crearía una
-- segunda función al lado y cada llamada de siempre se volvería ambigua.

drop function if exists public.registrar_venta(
  uuid, jsonb, date, text, text, text, text, origen_captura, numeric, uuid);

create or replace function public.registrar_venta(
  p_empresa uuid,
  p_items jsonb,
  p_fecha date default null,
  p_descripcion text default '',
  p_metodo_pago text default 'efectivo',
  p_contraparte text default '',
  p_notas text default '',
  p_origen origen_captura default 'manual',
  p_descuento numeric default 0,
  -- A quién se le vende. Solo hace falta cuando la venta es fiada, pero se
  -- guarda siempre: sirve para el historial del cliente.
  p_cliente uuid default null,
  -- En qué cuenta entró (096). Null = la de su forma de pago, como siempre.
  p_cuenta uuid default null
)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_mov       uuid;
  v_item      jsonb;
  v_prod      public.productos%rowtype;
  v_norm      jsonb := '[]'::jsonb;
  v_subtotal  numeric(14,2) := 0;
  v_costo     numeric(14,2) := 0;
  v_desc      numeric(14,2);
  v_cant      numeric(14,2);
  v_precio    numeric(14,2);
  v_costo_u   numeric(14,2);
  v_nombre    text;
  v_pid       uuid;
  v_fecha     date;
  v_permitir  boolean;
  v_stock     numeric(14,2);
  v_metodo    text;
  v_cliente   uuid;
begin
  ------------------------------------------------ autenticación y pertenencia
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  select permitir_stock_negativo into v_permitir from public.empresas where id = p_empresa;
  if not found then
    raise exception 'La empresa no existe.' using errcode = '42501';
  end if;

  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  ------------------------------------------------ validaciones generales
  if p_items is null or jsonb_typeof(p_items) <> 'array' then
    raise exception 'La venta necesita una lista de productos.' using errcode = '22023';
  end if;

  if jsonb_array_length(p_items) = 0 then
    raise exception 'La venta necesita al menos un producto.' using errcode = '22023';
  end if;

  if jsonb_array_length(p_items) > 200 then
    raise exception 'Una venta no puede tener más de 200 líneas.' using errcode = '22023';
  end if;

  v_fecha := coalesce(p_fecha, public.hoy_empresa(p_empresa));
  if v_fecha < date '2000-01-01' or v_fecha > public.hoy_empresa(p_empresa) + 1 then
    raise exception 'La fecha de la venta no es válida.' using errcode = '22007';
  end if;

  v_metodo := lower(coalesce(nullif(trim(p_metodo_pago), ''), 'efectivo'));
  if v_metodo not in ('efectivo', 'transferencia', 'tarjeta', 'credito', 'otro') then
    raise exception 'La forma de cobro no es válida.' using errcode = '22023';
  end if;

  ------------------------------------------------ primera pasada: validar y normalizar
  for v_item in select * from jsonb_array_elements(p_items) loop
    if jsonb_typeof(v_item) <> 'object' then
      raise exception 'Cada línea de la venta tiene que ser un objeto.' using errcode = '22023';
    end if;

    begin
      v_cant := (v_item ->> 'cantidad')::numeric;
    exception when others then
      raise exception 'La cantidad tiene que ser un número.' using errcode = '22023';
    end;

    if v_cant is null or v_cant <= 0 then
      raise exception 'La cantidad tiene que ser mayor a cero.' using errcode = '22023';
    end if;
    if v_cant > 1000000 then
      raise exception 'La cantidad es demasiado grande.' using errcode = '22023';
    end if;

    v_pid := null;
    if nullif(trim(coalesce(v_item ->> 'producto_id', '')), '') is not null then
      begin
        v_pid := (v_item ->> 'producto_id')::uuid;
      exception when others then
        raise exception 'El identificador del producto no es válido.' using errcode = '22023';
      end;
    end if;

    if v_pid is not null then
      -- El producto tiene que existir Y ser de esta empresa.
      select * into v_prod from public.productos where id = v_pid and empresa_id = p_empresa;
      if not found then
        raise exception 'Ese producto no pertenece a esta empresa.' using errcode = '42501';
      end if;

      v_nombre  := v_prod.nombre;
      -- El precio SÍ puede ser distinto al del catálogo (rebaja puntual, acuerdo con el cliente).
      v_precio  := coalesce(nullif(v_item ->> 'precio_unitario', '')::numeric, v_prod.precio);
      -- El costo NO: siempre el del catálogo. Lo que mande el cliente se descarta.
      v_costo_u := v_prod.costo;
    else
      v_nombre := nullif(trim(coalesce(v_item ->> 'nombre', '')), '');
      if v_nombre is null then
        raise exception 'Cada producto suelto necesita un nombre.' using errcode = '22023';
      end if;
      v_nombre  := left(v_nombre, 120);
      v_precio  := coalesce(nullif(v_item ->> 'precio_unitario', '')::numeric, 0);
      v_costo_u := coalesce(nullif(v_item ->> 'costo_unitario', '')::numeric, 0);
    end if;

    if v_precio is null or v_precio < 0 then
      raise exception 'El precio no puede ser negativo.' using errcode = '22023';
    end if;
    if v_costo_u is null or v_costo_u < 0 then
      raise exception 'El costo no puede ser negativo.' using errcode = '22023';
    end if;

    v_subtotal := v_subtotal + (v_cant * v_precio);
    v_costo    := v_costo + (v_cant * v_costo_u);

    v_norm := v_norm || jsonb_build_object(
      'producto_id', v_pid,
      'nombre', v_nombre,
      'cantidad', v_cant,
      'precio_unitario', v_precio,
      'costo_unitario', v_costo_u,
      'controla_stock', coalesce(v_pid is not null and v_prod.controla_stock, false)
    );
  end loop;

  ------------------------------------------------ descuento
  v_desc := coalesce(p_descuento, 0);
  if v_desc < 0 then
    raise exception 'El descuento no puede ser negativo.' using errcode = '22023';
  end if;
  if v_desc > v_subtotal then
    raise exception 'El descuento no puede ser mayor que el subtotal de la venta.' using errcode = '22023';
  end if;

  ------------------------------------------------ el cliente
  -- Se valida ANTES de tocar el stock: si el cliente no es de esta cuenta,
  -- que la venta entera no llegue a existir.
  v_cliente := p_cliente;
  if v_cliente is not null
     and not exists (select 1 from public.clientes
                     where id = v_cliente and empresa_id = p_empresa) then
    raise exception 'Ese cliente no es de esta cuenta.' using errcode = 'P0002';
  end if;

  -- Fiar sin saber a quién es anotar en la pared. Se puede vender fiado sin
  -- cliente en otros sistemas; acá no, porque el resultado sería una deuda
  -- que nadie puede cobrar y un número que infla los ingresos para siempre.
  if v_metodo = 'credito' and v_cliente is null then
    raise exception 'Para vender fiado hay que decir a quién: elegí o creá el cliente.'
      using errcode = '22023';
  end if;

  -- Decir a qué cuenta entró es administrar la billetera: el que vende no
  -- decide dónde queda la plata del dueño (lo mismo que el fiado, 084). Y lo
  -- fiado no entra en ninguna: todavía no te lo pagaron.
  if p_cuenta is not null then
    if not public.es_admin(p_empresa) then
      raise exception 'Solo el dueño de la cuenta puede elegir en qué cuenta entra.' using errcode = '42501';
    end if;
    if v_metodo = 'credito' then
      raise exception 'Lo fiado no entra en ninguna cuenta hasta que te lo paguen.' using errcode = '22023';
    end if;
    if not exists (select 1 from public.cuentas_dinero c
                   where c.id = p_cuenta and c.empresa_id = p_empresa and c.activa) then
      raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
    end if;
  end if;

  ------------------------------------------------ cabecera
  insert into public.movimientos (
    empresa_id, tipo, estado, fecha, descripcion, categoria,
    subtotal, descuento, monto, costo_total,
    metodo_pago, contraparte, notas, origen, creado_por, cliente_id, cuenta_id
  )
  values (
    p_empresa, 'venta', 'activo', v_fecha,
    left(coalesce(trim(p_descripcion), ''), 200), 'Ventas',
    v_subtotal, v_desc, v_subtotal - v_desc, v_costo,
    v_metodo, left(coalesce(trim(p_contraparte), ''), 80), left(coalesce(p_notas, ''), 500),
    coalesce(p_origen, 'manual'), auth.uid(), v_cliente, p_cuenta
  )
  returning id into v_mov;

  ------------------------------------------------ items y stock
  for v_item in select * from jsonb_elements_ordenados(v_norm) loop
    v_cant := (v_item ->> 'cantidad')::numeric;
    v_pid  := nullif(v_item ->> 'producto_id', '')::uuid;

    if v_pid is not null and (v_item ->> 'controla_stock')::boolean then
      -- Aritmética relativa: dos ventas simultáneas no se pisan.
      update public.productos
        set stock = stock - v_cant
        where id = v_pid
        returning stock into v_stock;

      if not v_permitir and v_stock < 0 then
        raise exception 'No hay stock suficiente de %.', v_item ->> 'nombre' using errcode = '23514';
      end if;
    end if;

    insert into public.movimiento_items (
      movimiento_id, empresa_id, producto_id, nombre, cantidad,
      precio_unitario, costo_unitario, afecto_stock
    )
    values (
      v_mov, p_empresa, v_pid, v_item ->> 'nombre', v_cant,
      (v_item ->> 'precio_unitario')::numeric,
      (v_item ->> 'costo_unitario')::numeric,
      coalesce(v_pid is not null and (v_item ->> 'controla_stock')::boolean, false)
    );
  end loop;

  ------------------------------------------------ descripción automática
  update public.movimientos
  set descripcion = (
    select string_agg(nombre || ' x' || trim(to_char(cantidad, 'FM999999990.##')), ', ')
    from public.movimiento_items where movimiento_id = v_mov
  )
  where id = v_mov and coalesce(trim(descripcion), '') = '';

  ------------------------------------------------ si fue fiada, se anota
  --
  -- Acá está el arreglo. Hasta ahora «Fiado» era una etiqueta: la venta
  -- sumaba como ingreso igual que si te hubieran pagado en efectivo, y no
  -- quedaba escrito quién debía.
  --
  -- Va al final, después del stock y de los items: si algo de eso falla, la
  -- transacción se va entera y no queda una deuda por una venta que no pasó.
  if v_metodo = 'credito' then
    insert into public.fiado (
      empresa_id, cliente_id, tipo, monto, fecha, concepto, venta_id, creado_por
    )
    select p_empresa, v_cliente, 'fio', v_subtotal - v_desc, v_fecha,
           left(coalesce((
             select string_agg(nombre || ' x' || trim(to_char(cantidad, 'FM999999990.##')), ', ')
             from public.movimiento_items where movimiento_id = v_mov
           ), 'Venta fiada'), 200),
           v_mov, auth.uid();
  end if;

  return v_mov;
end $$;

revoke all on function public.registrar_venta(
  uuid, jsonb, date, text, text, text, text, origen_captura, numeric, uuid, uuid) from public, anon;
grant execute on function public.registrar_venta(
  uuid, jsonb, date, text, text, text, text, origen_captura, numeric, uuid, uuid) to authenticated;


-- ############################################################
-- ##  097_personal_trainer.sql
-- ############################################################

-- ============================================================
-- 097 · PERSONAL TRAINER
-- ============================================================
--
-- Matías: «ponete en el lugar de un personal trainer: ¿qué necesitaría
-- para trabajar?». La respuesta, mirándolo de cerca, es casi todo lo que
-- ya tiene el profe (087-094): clientes que vuelven todas las semanas con
-- un horario fijo, el mes cobrado por adelantado, y cada sesión que se
-- marca como dada o no. Un profe de inglés y un trainer resuelven el mismo
-- problema con distinta ropa.
--
-- Así que el trainer no es un motor nuevo: es un rubro más, «entrenamiento»,
-- que usa el mismo. Lo que decidió Matías para arrancar:
--   · uno a uno (sin dúos ni grupos todavía);
--   · la rutina es una nota simple por cliente, como la materia del profe;
--   · las faltas, como el profe: se decide en cada una si se descuenta.
--
-- Lo único nuevo de verdad es que el trainer tiene que ver las lesiones de
-- cada cliente antes de entrenarlo. Esas notas ya existen (clientes.notas),
-- así que la agenda del día y el panel ahora las traen junto a cada sesión.
--
-- Todo lo demás se engancha solo: el link público se apaga porque
-- `rubro_de_alumnos()` lo dice, el cierre de caja no aplica porque
-- `rubro_cierra_el_dia()` solo nombra a comercio y servicios, y el cheque
-- de `empresas.rubro` lee `rubros_validos()`.
--
-- Cada función es copia exacta de su versión viva (087, 089, 094; la huella
-- del cuerpo coincide) con lo nuevo agregado. Ninguna cambia de firma: se
-- reemplazan sin crear otra al lado.



-- ------------------------------------------------------------
-- 1. EL RUBRO EXISTE
-- ------------------------------------------------------------
create or replace function public.rubros_validos()
returns text[] language sql immutable set search_path = public as $fn$
  select array['comercio', 'ganaderia', 'agricultura', 'servicios', 'clases', 'entrenamiento'];
$fn$;

-- ------------------------------------------------------------
-- 2. SU AGENDA ES DE A UNO, SIN LINK PÚBLICO
-- ------------------------------------------------------------
create or replace function public.rubro_de_alumnos(p_rubro text)
returns boolean language sql immutable set search_path = public as $fn$
  select coalesce(p_rubro, '') in ('clases', 'entrenamiento');
$fn$;

-- ------------------------------------------------------------
-- 3. EN QUÉ GASTA UN TRAINER
-- ------------------------------------------------------------
create or replace function public.categorias_de_rubro(
  p_rubro text,
  p_tipo_cuenta text default 'emprendedor'
)
returns jsonb language sql immutable set search_path = public as $fn$
  select case
    when coalesce(p_tipo_cuenta, 'emprendedor') = 'personal' then jsonb_build_array(
      jsonb_build_object('nombre','Comida','pistas','supermercado, almacén, verdulería, carnicería, despensa, panadería'),
      jsonb_build_object('nombre','Alquiler','pistas','alquiler, expensas, condominio'),
      jsonb_build_object('nombre','Servicios','pistas','luz, agua, internet, teléfono, cable, gas'),
      jsonb_build_object('nombre','Transporte','pistas','colectivo, nafta, combustible, pasaje, taxi, uber, peaje'),
      jsonb_build_object('nombre','Salud','pistas','farmacia, remedios, médico, dentista, seguro médico, análisis'),
      jsonb_build_object('nombre','Educación','pistas','colegio, cuota, universidad, útiles, curso, libros'),
      jsonb_build_object('nombre','Ropa','pistas','ropa, calzado, zapatillas, campera'),
      jsonb_build_object('nombre','Cuidado personal','pistas','peluquería, uñas, barbería, cosmética, gimnasio, perfume'),
      jsonb_build_object('nombre','Ocio','pistas','salida, restaurante, cine, streaming, viaje, cerveza, cumpleaños'),
      jsonb_build_object('nombre','Hogar','pistas','limpieza, muebles, arreglos, electrodomésticos, ferretería'),
      jsonb_build_object('nombre','Cuotas y deudas','pistas','tarjeta, préstamo, cuota, financiera'),
      jsonb_build_object('nombre','Otros','pistas',''))

    when coalesce(p_rubro, 'comercio') = 'ganaderia' then jsonb_build_array(
      jsonb_build_object('nombre','Alimentación','pistas','maíz, balanceado, ración, fardos, sal, pasto'),
      jsonb_build_object('nombre','Sanidad','pistas','vacunas, antiparasitarios, veterinario, remedios'),
      jsonb_build_object('nombre','Personal','pistas','peón, capataz, jornales, sueldos'),
      jsonb_build_object('nombre','Combustible','pistas','gasoil, nafta'),
      jsonb_build_object('nombre','Arrendamiento','pistas','alquiler de campo, pastaje'),
      jsonb_build_object('nombre','Fletes','pistas','transporte de hacienda, camión jaula'),
      jsonb_build_object('nombre','Mantenimiento','pistas','alambrado, aguadas, maquinaria, herramientas'),
      jsonb_build_object('nombre','Impuestos','pistas',''),
      jsonb_build_object('nombre','Otros','pistas',''))

    when coalesce(p_rubro, 'comercio') = 'agricultura' then jsonb_build_array(
      jsonb_build_object('nombre','Semilla','pistas','semilla, plantines'),
      jsonb_build_object('nombre','Fertilizante','pistas','urea, fosfato, abono'),
      jsonb_build_object('nombre','Agroquímicos','pistas','herbicida, fungicida, insecticida'),
      jsonb_build_object('nombre','Combustible','pistas','gasoil, nafta'),
      jsonb_build_object('nombre','Cosecha','pistas','cosechadora, trilla, secado'),
      jsonb_build_object('nombre','Fletes','pistas','transporte de granos'),
      jsonb_build_object('nombre','Arrendamiento','pistas','alquiler de campo'),
      jsonb_build_object('nombre','Personal','pistas','jornales, tractorista, peón'),
      jsonb_build_object('nombre','Otros','pistas',''))

    when coalesce(p_rubro, 'comercio') = 'servicios' then jsonb_build_array(
      jsonb_build_object('nombre','Materiales','pistas','cemento, arena, cables, pintura, insumos'),
      jsonb_build_object('nombre','Repuestos','pistas','piezas, filtros, aceite'),
      jsonb_build_object('nombre','Herramientas','pistas',''),
      jsonb_build_object('nombre','Combustible','pistas','gasoil, nafta'),
      jsonb_build_object('nombre','Personal','pistas','ayudante, jornales, sueldos'),
      jsonb_build_object('nombre','Transporte','pistas','flete, viaje, delivery'),
      jsonb_build_object('nombre','Impuestos','pistas',''),
      jsonb_build_object('nombre','Otros','pistas',''))

    when coalesce(p_rubro, 'comercio') = 'clases' then jsonb_build_array(
      jsonb_build_object('nombre','Internet y plataformas','pistas','internet, wifi, Zoom, Meet, plan del celular, hosting'),
      jsonb_build_object('nombre','Comisiones','pistas','Preply, Italki, Superprof, lo que se lleva la plataforma, comisión de cobro'),
      jsonb_build_object('nombre','Material','pistas','libros, licencias, PDF, impresiones, fotocopias, cuadernos'),
      jsonb_build_object('nombre','Equipo','pistas','notebook, micrófono, cámara, auriculares, tablet, pizarra, luz'),
      jsonb_build_object('nombre','Publicidad','pistas','anuncios, Instagram, Facebook, volantes'),
      jsonb_build_object('nombre','Capacitación','pistas','cursos propios, certificaciones, exámenes, membresías'),
      jsonb_build_object('nombre','Alquiler','pistas','aula, salón, espacio de trabajo'),
      jsonb_build_object('nombre','Impuestos','pistas',''),
      jsonb_build_object('nombre','Otros','pistas',''))

    -- Lo que gasta un personal trainer (097): el equipo que lleva, el lugar
    -- donde entrena, y moverse hasta cada cliente.
    when coalesce(p_rubro, 'comercio') = 'entrenamiento' then jsonb_build_array(
      jsonb_build_object('nombre','Equipamiento','pistas','pesas, mancuernas, bandas, colchonetas, kettlebell, TRX, soga, conos'),
      jsonb_build_object('nombre','Gimnasio y espacio','pistas','cuota del gimnasio, alquiler del espacio, box, cancha, derecho de uso'),
      jsonb_build_object('nombre','Transporte','pistas','nafta, combustible, colectivo, uber, ir a domicilio'),
      jsonb_build_object('nombre','Ropa deportiva','pistas','ropa, zapatillas, calzas, uniforme'),
      jsonb_build_object('nombre','Internet y aplicaciones','pistas','internet, plan del celular, app de rutinas, Zoom'),
      jsonb_build_object('nombre','Publicidad','pistas','anuncios, Instagram, Facebook, TikTok, volantes'),
      jsonb_build_object('nombre','Capacitación','pistas','cursos, certificaciones, workshops, membresías'),
      jsonb_build_object('nombre','Impuestos','pistas',''),
      jsonb_build_object('nombre','Otros','pistas',''))

    else jsonb_build_array(
      jsonb_build_object('nombre','Mercadería','pistas','lo que comprás para revender'),
      jsonb_build_object('nombre','Transporte','pistas','combustible, flete, delivery'),
      jsonb_build_object('nombre','Comida','pistas',''),
      jsonb_build_object('nombre','Publicidad','pistas',''),
      jsonb_build_object('nombre','Servicios','pistas','luz, agua, internet, teléfono'),
      jsonb_build_object('nombre','Alquiler','pistas',''),
      jsonb_build_object('nombre','Sueldos','pistas','empleados, jornales'),
      jsonb_build_object('nombre','Impuestos','pistas',''),
      jsonb_build_object('nombre','Otros','pistas',''))
  end;
$fn$;

-- ------------------------------------------------------------
-- 4. LA AGENDA DEL DÍA TRAE LAS NOTAS DE CADA CLIENTE
-- ------------------------------------------------------------
create or replace function public.agenda_del_dia(
  p_empresa uuid,
  p_fecha   date default null
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_zona  text;
  v_fecha date;
  v_res   jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select coalesce(zona_horaria, 'America/Asuncion') into v_zona
  from public.empresas where id = p_empresa;
  v_fecha := coalesce(p_fecha, public.hoy_empresa(p_empresa));

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',          r.id,
    'inicia',      r.inicia,
    'termina',     r.termina,
    'profesional', p.nombre,
    'profesional_id', r.profesional_id,
    'servicio',    pr.nombre,
    'producto_id', r.producto_id,
    'cliente',     r.cliente_nombre,
    'telefono',    r.cliente_telefono,
    'estado',      r.estado,
    'origen',      r.origen,
    'token',       r.token,
    'avisado',     (r.avisado_at is not null),
    'paquete_id',  r.paquete_id,
    'materia',     pq.materia,
    -- Lo que hay que saber de la persona antes de empezar (097): para un
    -- trainer, sus lesiones. Null si no hay nada anotado.
    'notas',       nullif(trim(cl.notas), '')
  ) order by r.inicia), '[]'::jsonb)
  into v_res
  from public.turnos_reserva r
  join public.turnos_profesional p on p.id = r.profesional_id
  join public.productos pr on pr.id = r.producto_id
  left join public.paquetes pq on pq.id = r.paquete_id
  left join public.clientes cl on cl.id = r.cliente_id and cl.empresa_id = r.empresa_id
  where r.empresa_id = p_empresa
    and (r.inicia at time zone v_zona)::date = v_fecha
    and r.estado <> 'cancelada';

  return v_res;
end $fn$;

-- ------------------------------------------------------------
-- 5. Y EL PANEL, EN LAS SESIONES DE HOY
-- ------------------------------------------------------------
create or replace function public.panel_profe(p_empresa uuid, p_desde date, p_hasta date)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_zona text;
  v_hoy  date;
  v_res  jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select coalesce(zona_horaria, 'America/Asuncion') into v_zona from public.empresas where id = p_empresa;
  v_hoy := public.hoy_empresa(p_empresa);

  select jsonb_build_object(
    'hoy', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', r.id, 'hora', to_char(r.inicia at time zone v_zona, 'HH24:MI'),
        'alumno', r.cliente_nombre, 'estado', r.estado, 'materia', pq.materia,
        'notas', nullif(trim(cl.notas), '')) order by r.inicia)
      from public.turnos_reserva r
      left join public.paquetes pq on pq.id = r.paquete_id
      left join public.clientes cl on cl.id = r.cliente_id and cl.empresa_id = r.empresa_id
      where r.empresa_id = p_empresa and r.estado <> 'cancelada'
        and (r.inicia at time zone v_zona)::date = v_hoy), '[]'::jsonb),
    'clases_periodo', (
      select count(*)::int from public.turnos_reserva r
      where r.empresa_id = p_empresa and r.estado = 'atendida'
        and (r.inicia at time zone v_zona)::date between p_desde and p_hasta),
    'cobrado', coalesce((
      select sum(m.monto) from public.movimientos m
      where m.empresa_id = p_empresa and m.estado = 'activo' and m.tipo in ('venta', 'ingreso')
        and m.fecha between p_desde and p_hasta), 0),
    'gastado', coalesce((
      select sum(m.monto) from public.movimientos m
      where m.empresa_id = p_empresa and m.estado = 'activo' and m.tipo = 'gasto'
        and m.fecha between p_desde and p_hasta), 0),
    'por_cobrar', coalesce((
      select sum(p.precio) from public.paquetes p
      where p.empresa_id = p_empresa and p.movimiento_id is null and p.precio > 0 and not p.cerrado), 0),
    'deben', (
      select count(distinct p.cliente_id)::int from public.paquetes p
      where p.empresa_id = p_empresa and p.movimiento_id is null and p.precio > 0 and not p.cerrado),
    'alumnos_activos', (
      select count(distinct p.cliente_id)::int from public.paquetes p
      where p.empresa_id = p_empresa and not p.cerrado
        and (public.estado_paquete(p.id)->>'estado') = 'activo')
  ) into v_res;

  return v_res;
end $fn$;

-- Los permisos, los mismos de siempre (087, 089, 094). `create or replace`
-- ya los conserva; se escriben igual para que esta migración se lea sola.
grant execute on function public.rubros_validos() to anon, authenticated;
grant execute on function public.rubro_de_alumnos(text) to anon, authenticated;
grant execute on function public.categorias_de_rubro(text, text) to anon, authenticated;
revoke all on function public.agenda_del_dia(uuid, date) from public, anon;
grant execute on function public.agenda_del_dia(uuid, date) to authenticated;
revoke all on function public.panel_profe(uuid, date, date) from public, anon;
grant execute on function public.panel_profe(uuid, date, date) to authenticated;


-- ############################################################
-- ##  098_rutinas_y_medidas.sql
-- ############################################################

-- ============================================================
-- 098 · RUTINAS, MEDIDAS Y PROGRESO DEL PERSONAL TRAINER
-- ============================================================
--
-- La 097 le dio al trainer el motor del profe con una rutina que era una
-- nota suelta («Qué están trabajando»). Matías lo dio vuelta: «ponete en el
-- lugar de un personal trainer: ¿qué necesitaría para trabajar?», y la
-- respuesta es lo que hace todo el día y Orden no tenía: rutinas de verdad
-- (ejercicio, series, repeticiones, carga, descanso, nota), mandárselas al
-- cliente, y anotar cómo va.
--
-- LO QUE DECIDIÓ MATÍAS, Y QUÉ SIGNIFICA ACÁ
--
--   · «Anotar los pesos» es, en esta vuelta, el peso, la altura y las
--     medidas del cuerpo con fecha, MÁS la carga de cada ejercicio con su
--     historia: «Sentadilla: de 40 a 50 kg desde el 15/08». Lo que se
--     levantó serie por serie en cada sesión queda para la fase 2.
--   · Si la cuenta del trainer vence, el link de rutina de sus clientes
--     sigue andando 30 días; después dice «Tu entrenador tiene que renovar
--     su cuenta». Un cliente en el gimnasio no tiene la culpa de un pago
--     atrasado, pero la prueba gratis tampoco puede servir para alojar
--     rutinas para siempre.
--   · Uno a uno, faltas como el profe, se gana al cobrar: eso ya estaba.
--
-- CÓMO ESTÁ ARMADO
--
-- Una biblioteca de ejercicios por negocio, que se arma sola: el trainer
-- escribe «Sentadilla» en una rutina y la próxima vez ya está. Todo apunta
-- a esa biblioteca, así que el «cómo se hace» y el video salen de un solo
-- lugar, y el historial de cargas se sigue por ejercicio y no por renglón.
--
-- Una rutina es una plantilla (sin cliente) o la de un cliente, que está en
-- preparación (borrador), vigente, o ya pasó (anterior). El cliente tiene UN
-- link, no uno por rutina: guarda un solo mensaje de WhatsApp y siempre ve
-- la vigente.
--
-- Las medidas del cuerpo son datos de salud: las anota y las ve solo el
-- dueño o un administrador, con el consentimiento del cliente, y nunca
-- viajan por el link.
--
-- LAS REGLAS DE SIEMPRE
--
-- Todas las tablas cuelgan de la empresa con borrado en cascada (así
-- `borrar_cuenta` se lleva todo) y apuntan a clientes y ejercicios con
-- claves compuestas (x_id, empresa_id), el candado de la 052: una fila de un
-- negocio no puede referirse a la de otro ni con un UPDATE a mano. Ninguna
-- se lee ni se escribe directo: todo pasa por funciones.
--
-- Las claves a clientes y ejercicios son NO ACTION y no RESTRICT: NO ACTION
-- se controla al final de la sentencia, así que el borrado en cascada de una
-- empresa no depende del orden en que PostgreSQL recorre las tablas, y un
-- borrado directo de un cliente con historia sigue frenado. Para eso
-- `eliminar_cliente` ahora archiva a quien tiene rutinas o medidas.
--
-- Los tokens son `gen_random_uuid()` y no `gen_random_bytes()`: las pruebas
-- corren en PGlite, que no tiene pgcrypto (igual que turnos_reserva.token).

-- ------------------------------------------------------------
-- 0. LA CLAVE DE UN NOMBRE DE EJERCICIO
--
--    «Sentadilla búlgara», «SENTADILLA BULGARA» y «sentadilla  búlgara»
--    son el mismo ejercicio. Sin esto la biblioteca se llena de repetidos
--    que no se ven como repetidos, y el historial de cargas queda partido.
--    `translate` y no `unaccent`: PGlite no tiene esa extensión.
-- ------------------------------------------------------------
create or replace function public.clave_ejercicio(p text)
returns text language sql immutable set search_path = public as $fn$
  select translate(lower(regexp_replace(btrim(coalesce(p, '')), '\s+', ' ', 'g')),
                   'áàâãäéèêëíìîïóòôõöúùûüñç', 'aaaaaeeeeiiiiooooouuuunc');
$fn$;

revoke all on function public.clave_ejercicio(text) from public, anon, authenticated;

-- Un id que llega en un JSON puede venir roto: se toma solo si es un uuid.
-- Un id que no es un uuid es, para quien guarda, un renglón nuevo.
create or replace function public.uuid_o_null(p text)
returns uuid language sql immutable set search_path = public as $fn$
  select case when p ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              then p::uuid end;
$fn$;

revoke all on function public.uuid_o_null(text) from public, anon, authenticated;

-- ------------------------------------------------------------
-- 1. LA BIBLIOTECA DE EJERCICIOS
--
--    Empieza vacía. La lista base de unos cien ejercicios vive en el código
--    (src/lib/ejercicios-base.ts) y solo se sugiere: un ejercicio entra acá
--    la primera vez que se usa. No se borra el que está en una rutina: se
--    apaga, deja de sugerirse y las rutinas que lo tienen lo siguen viendo.
-- ------------------------------------------------------------
create table if not exists public.ejercicios (
  id           uuid primary key default gen_random_uuid(),
  empresa_id   uuid not null references public.empresas (id) on delete cascade,
  nombre       text not null check (char_length(trim(nombre)) between 1 and 80),
  clave        text generated always as (public.clave_ejercicio(nombre)) stored,
  grupo        text check (grupo in ('piernas', 'gluteos', 'pecho', 'espalda', 'hombros',
                                     'brazos', 'core', 'cardio', 'movilidad', 'otro')),
  -- «Cómo se hace». LO VE EL CLIENTE en su link.
  indicaciones text not null default '' check (char_length(indicaciones) <= 500),
  -- YouTube, Instagram, TikTok: lo que el trainer ya usa. Solo https.
  video_url    text check (video_url ~ '^https://\S+$' and char_length(video_url) <= 300),
  activo       boolean not null default true,
  created_at   timestamptz not null default now(),
  constraint ejercicios_id_empresa unique (id, empresa_id)
);

create unique index if not exists ejercicios_clave_unica on public.ejercicios (empresa_id, clave);

alter table public.ejercicios enable row level security;
revoke all on public.ejercicios from anon, authenticated;

-- ------------------------------------------------------------
-- 2. LAS RUTINAS
--
--    plantilla → sin cliente, para reusar.
--    borrador  → «la próxima»: el trainer la arma sin tocar lo que el
--                cliente ve.
--    vigente   → la que ve el cliente en su link. Una por cliente.
--    anterior  → la historia. Las rutinas de un cliente no se borran.
--
--    `version` es para dos celulares editando a la vez: el que guarda con
--    una versión vieja se entera, en vez de pisar al otro sin saberlo.
-- ------------------------------------------------------------
create table if not exists public.rutinas (
  id          uuid primary key default gen_random_uuid(),
  empresa_id  uuid not null references public.empresas (id) on delete cascade,
  cliente_id  uuid,
  estado      text not null check (estado in ('plantilla', 'borrador', 'vigente', 'anterior')),
  -- «Fuerza base». LO VE EL CLIENTE.
  nombre      text not null check (char_length(trim(nombre)) between 1 and 60),
  -- Las indicaciones generales. LAS VE EL CLIENTE.
  notas       text not null default '' check (char_length(notas) <= 1000),
  desde       date,
  hasta       date,
  -- «Cambiarla en N semanas»: es solo un aviso para el trainer.
  semanas     smallint check (semanas between 1 and 52),
  -- De qué plantilla o rutina salió.
  origen_id   uuid references public.rutinas (id) on delete set null,
  version     integer not null default 1,
  creado_por  uuid references auth.users (id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  constraint rutinas_id_empresa unique (id, empresa_id),
  -- NO ACTION. Con cliente en null (plantilla) la clave no se controla.
  constraint rutinas_cliente foreign key (cliente_id, empresa_id)
    references public.clientes (id, empresa_id),
  constraint rutinas_plantilla_sin_cliente check ((cliente_id is null) = (estado = 'plantilla')),
  constraint rutinas_con_fecha check (estado not in ('vigente', 'anterior') or desde is not null),
  constraint rutinas_fechas check (hasta is null or hasta >= desde)
);

create unique index if not exists rutinas_una_vigente on public.rutinas (cliente_id) where estado = 'vigente';
create unique index if not exists rutinas_un_borrador on public.rutinas (cliente_id) where estado = 'borrador';
create index if not exists rutinas_empresa_idx on public.rutinas (empresa_id, estado);
create index if not exists rutinas_cliente_idx on public.rutinas (cliente_id);

alter table public.rutinas enable row level security;
revoke all on public.rutinas from anon, authenticated;

-- ------------------------------------------------------------
-- 3. LOS DÍAS («Día A · Piernas»)
--
--    El orden es único pero DIFERIDO: al reordenar, el día 2 pasa a ser el
--    1 y el 1 el 2, y en el medio los dos son el 1 un instante. Se controla
--    al terminar la transacción, cuando ya quedó cada uno en su lugar.
-- ------------------------------------------------------------
create table if not exists public.rutina_dias (
  id          uuid primary key default gen_random_uuid(),
  empresa_id  uuid not null references public.empresas (id) on delete cascade,
  rutina_id   uuid not null,
  orden       smallint not null check (orden between 1 and 10),
  nombre      text not null check (char_length(trim(nombre)) between 1 and 40),
  -- Entrada en calor, vuelta a la calma. LO VE EL CLIENTE.
  notas       text not null default '' check (char_length(notas) <= 500),
  constraint rutina_dias_id_empresa unique (id, empresa_id),
  constraint rutina_dias_rutina foreign key (rutina_id, empresa_id)
    references public.rutinas (id, empresa_id) on delete cascade,
  constraint rutina_dias_orden unique (rutina_id, orden) deferrable initially deferred
);

alter table public.rutina_dias enable row level security;
revoke all on public.rutina_dias from anon, authenticated;

-- ------------------------------------------------------------
-- 4. LOS EJERCICIOS DE CADA DÍA
--
--    Lo que el trainer indica es texto corto, no número: «8-12», «12-10-8»,
--    «45 s», «al fallo»; «40 kg», «25 lb», «placa 7», «banda roja». La base
--    NUNCA le agrega una unidad a la carga: en muchos gimnasios los discos
--    vienen en libras, y leer «25 kg» donde el trainer pensó «25 lb» es el
--    único error de pantalla que puede lastimar a alguien.
--
--    Lo que se mide sí es número (las medidas, más abajo).
-- ------------------------------------------------------------
create table if not exists public.rutina_ejercicios (
  id                uuid primary key default gen_random_uuid(),
  empresa_id        uuid not null references public.empresas (id) on delete cascade,
  dia_id            uuid not null,
  orden             smallint not null check (orden between 1 and 30),
  ejercicio_id      uuid not null,
  -- En null para el cardio o lo que va por tiempo.
  series            smallint check (series between 1 and 20),
  reps              text not null default '' check (char_length(reps) <= 20),
  carga             text not null default '' check (char_length(carga) <= 24),
  descanso_seg      smallint check (descanso_seg between 0 and 900),
  -- «Codos pegados», «no cargar la rodilla». LA VE EL CLIENTE.
  nota              text not null default '' check (char_length(nota) <= 200),
  -- Superserie: el cliente lo ve como 2a / 2b.
  junto_al_anterior boolean not null default false,
  constraint rutina_ejercicios_id_empresa unique (id, empresa_id),
  constraint rutina_ej_dia foreign key (dia_id, empresa_id)
    references public.rutina_dias (id, empresa_id) on delete cascade,
  -- NO ACTION: un ejercicio que está en una rutina se apaga, no se borra.
  constraint rutina_ej_ejercicio foreign key (ejercicio_id, empresa_id)
    references public.ejercicios (id, empresa_id),
  constraint rutina_ej_orden unique (dia_id, orden) deferrable initially deferred,
  constraint rutina_ej_primero_suelto check (orden > 1 or not junto_al_anterior)
);

create index if not exists rutina_ej_ejercicio_idx on public.rutina_ejercicios (ejercicio_id);

alter table public.rutina_ejercicios enable row level security;
revoke all on public.rutina_ejercicios from anon, authenticated;

-- ------------------------------------------------------------
-- 5. EL LINK DEL CLIENTE
--
--    Uno por persona, no por rutina: siempre muestra la vigente. El token
--    ES la credencial. Cambiarlo deja al viejo igual que uno inexistente.
-- ------------------------------------------------------------
create table if not exists public.rutina_enlaces (
  cliente_id  uuid primary key,
  empresa_id  uuid not null references public.empresas (id) on delete cascade,
  token       uuid not null default gen_random_uuid(),
  activo      boolean not null default true,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  constraint rutina_enlaces_cliente foreign key (cliente_id, empresa_id)
    references public.clientes (id, empresa_id) on delete cascade
);

create unique index if not exists rutina_enlaces_token on public.rutina_enlaces (token);

alter table public.rutina_enlaces enable row level security;
revoke all on public.rutina_enlaces from anon, authenticated;

-- ------------------------------------------------------------
-- 6. LA FICHA DE ENTRENAMIENTO (mínima; crece en la fase 3)
--
--    Por ahora guarda una sola cosa: que el cliente (o su madre, padre o
--    tutor, si es menor) está de acuerdo con que se guarden sus medidas.
--    Son datos de salud (Ley 7593/2025 en Paraguay, LGPD en Brasil): sin
--    ese sí, no se anota ninguna.
-- ------------------------------------------------------------
create table if not exists public.fichas_entreno (
  cliente_id           uuid primary key,
  empresa_id           uuid not null references public.empresas (id) on delete cascade,
  consiente_medidas_at timestamptz,
  consiente_por        uuid references auth.users (id) on delete set null,
  updated_at           timestamptz not null default now(),
  constraint fichas_entreno_cliente foreign key (cliente_id, empresa_id)
    references public.clientes (id, empresa_id) on delete cascade
);

alter table public.fichas_entreno enable row level security;
revoke all on public.fichas_entreno from anon, authenticated;

-- ------------------------------------------------------------
-- 7. LAS MEDICIONES
--
--    Una fila es «el control del 22/09», como lo piensa el trainer, y no
--    una fila por valor: así los rangos los controla la base, como en todo
--    Orden. Los rangos frenan dedazos («8,5» en vez de «85»), no
--    diagnostican nada, y son los mismos de src/lib/medidas.ts.
--
--    No se guarda nada calculado (IMC, cintura/altura): se calcula en
--    medidas.ts, y así se puede corregir sin migrar.
--
--    Los nombres de todos los check empiezan con `mediciones_`: la regla
--    de src/lib/errores.ts los traduce a «Ese valor está fuera de rango».
-- ------------------------------------------------------------
create table if not exists public.mediciones (
  id             uuid primary key default gen_random_uuid(),
  empresa_id     uuid not null references public.empresas (id) on delete cascade,
  cliente_id     uuid not null,
  fecha          date not null,
  peso_kg        numeric(4, 1) check (peso_kg between 20 and 300),
  altura_cm      numeric(4, 1) check (altura_cm between 100 and 230),
  cintura_cm     numeric(4, 1) check (cintura_cm between 40 and 200),
  cadera_cm      numeric(4, 1) check (cadera_cm between 50 and 200),
  pecho_cm       numeric(4, 1) check (pecho_cm between 50 and 180),
  -- Contraído.
  brazo_cm       numeric(4, 1) check (brazo_cm between 15 and 75),
  muslo_cm       numeric(4, 1) check (muslo_cm between 30 and 110),
  grasa_pct      numeric(3, 1) check (grasa_pct between 3 and 70),
  -- Una balanza y un plicómetro no se comparan: el % de grasa va siempre
  -- con su método.
  grasa_metodo   text check (grasa_metodo in ('balanza', 'plicometro', 'cinta', 'otro')),
  pantorrilla_cm numeric(4, 1) check (pantorrilla_cm between 20 and 70),
  cuello_cm      numeric(4, 1) check (cuello_cm between 25 and 65),
  nota           text not null default '' check (char_length(nota) <= 300),
  creado_por     uuid references auth.users (id) on delete set null,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  -- NO ACTION.
  constraint mediciones_cliente foreign key (cliente_id, empresa_id)
    references public.clientes (id, empresa_id),
  constraint mediciones_un_control_por_dia unique (cliente_id, fecha),
  constraint mediciones_con_algo check (num_nonnulls(peso_kg, altura_cm, cintura_cm, cadera_cm,
    pecho_cm, brazo_cm, muslo_cm, grasa_pct, pantorrilla_cm, cuello_cm) >= 1),
  constraint mediciones_grasa_con_metodo check ((grasa_pct is null) = (grasa_metodo is null))
);

create index if not exists mediciones_cliente_idx on public.mediciones (cliente_id, fecha desc);

alter table public.mediciones enable row level security;
revoke all on public.mediciones from anon, authenticated;

-- ------------------------------------------------------------
-- 8. CÓMO SUBIERON LAS CARGAS
--
--    Cada vez que cambia la carga o las repeticiones de un ejercicio de la
--    rutina VIGENTE, queda una fila. Es lo que el cliente festeja y lo que
--    lo hace renovar: «Sentadilla: de 40 a 50 kg desde el 15/08».
-- ------------------------------------------------------------
create table if not exists public.cargas_historial (
  id            uuid primary key default gen_random_uuid(),
  empresa_id    uuid not null references public.empresas (id) on delete cascade,
  cliente_id    uuid not null,
  ejercicio_id  uuid not null,
  rutina_id     uuid references public.rutinas (id) on delete set null,
  fecha         date not null,
  carga_antes   text,
  carga_despues text,
  reps_antes    text,
  reps_despues  text,
  creado_por    uuid references auth.users (id) on delete set null,
  created_at    timestamptz not null default now(),
  -- NO ACTION las dos.
  constraint cargas_historial_cliente foreign key (cliente_id, empresa_id)
    references public.clientes (id, empresa_id),
  constraint cargas_historial_ejercicio foreign key (ejercicio_id, empresa_id)
    references public.ejercicios (id, empresa_id)
);

create index if not exists cargas_historial_idx on public.cargas_historial (cliente_id, ejercicio_id, fecha);

alter table public.cargas_historial enable row level security;
revoke all on public.cargas_historial from anon, authenticated;

-- ------------------------------------------------------------
-- 9. CON LA CUENTA VENCIDA NO SE CARGA (018, 069)
--
--    En todas las tablas nuevas MENOS `rutina_enlaces`. Apagar o cambiar un
--    link que se reenvió a quien no debía es seguridad, no carga: tiene que
--    poder hacerse justo cuando la cuenta está vencida y Orden cerrado.
-- ------------------------------------------------------------
drop trigger if exists cuenta_activa_ejercicios on public.ejercicios;
create trigger cuenta_activa_ejercicios
  before insert or update on public.ejercicios
  for each row execute function public.exigir_cuenta_activa();

drop trigger if exists cuenta_activa_rutinas on public.rutinas;
create trigger cuenta_activa_rutinas
  before insert or update on public.rutinas
  for each row execute function public.exigir_cuenta_activa();

drop trigger if exists cuenta_activa_rutina_dias on public.rutina_dias;
create trigger cuenta_activa_rutina_dias
  before insert or update on public.rutina_dias
  for each row execute function public.exigir_cuenta_activa();

drop trigger if exists cuenta_activa_rutina_ejercicios on public.rutina_ejercicios;
create trigger cuenta_activa_rutina_ejercicios
  before insert or update on public.rutina_ejercicios
  for each row execute function public.exigir_cuenta_activa();

drop trigger if exists cuenta_activa_fichas_entreno on public.fichas_entreno;
create trigger cuenta_activa_fichas_entreno
  before insert or update on public.fichas_entreno
  for each row execute function public.exigir_cuenta_activa();

drop trigger if exists cuenta_activa_mediciones on public.mediciones;
create trigger cuenta_activa_mediciones
  before insert or update on public.mediciones
  for each row execute function public.exigir_cuenta_activa();

drop trigger if exists cuenta_activa_cargas_historial on public.cargas_historial;
create trigger cuenta_activa_cargas_historial
  before insert or update on public.cargas_historial
  for each row execute function public.exigir_cuenta_activa();

-- ============================================================
-- LAS FUNCIONES
--
-- Todas reciben la empresa primero, arrancan preguntando si quien llama es
-- de esa empresa, y controlan que la fila que tocan sea de ella: un id de
-- otro negocio es, para esta, un id que no existe.
--
-- Los datos de salud (medidas, consentimiento, «Salud y lesiones») son del
-- dueño o de un administrador. Un vendedor que cobra en el mostrador arma
-- rutinas si hace falta, pero no ve cuánto pesa nadie.
-- ============================================================

-- ------------------------------------------------------------
-- 10. AYUDANTES (no se llaman desde afuera)
-- ------------------------------------------------------------

-- ¿Está entrenando? Un cliente activo con un plan que se puede usar, o con
-- una sesión cerca (un mes para atrás o para adelante), o con una rutina
-- vigente o en preparación. El que dejó de venir no se archiva —se le
-- cierra el plan o no renueva—, y sin esto «sin rutina» listaría para
-- siempre a cada cliente viejo o de prueba.
create or replace function public.cliente_entrenando(p_cliente uuid)
returns boolean language sql stable security definer set search_path = public as $fn$
  select coalesce((
    select c.activo and (
      exists (
        select 1 from public.paquetes p
        where p.cliente_id = c.id and not p.cerrado
          and (public.estado_paquete(p.id)->>'estado') = 'activo')
      or exists (
        select 1 from public.turnos_reserva r
        where r.cliente_id = c.id and r.empresa_id = c.empresa_id and r.estado <> 'cancelada'
          and (r.inicia at time zone coalesce(e.zona_horaria, 'America/Asuncion'))::date
              between public.hoy_empresa(c.empresa_id) - 30 and public.hoy_empresa(c.empresa_id) + 30)
      or exists (
        select 1 from public.rutinas ru
        where ru.cliente_id = c.id and ru.estado in ('vigente', 'borrador')))
    from public.clientes c
    join public.empresas e on e.id = c.empresa_id
    where c.id = p_cliente
  ), false);
$fn$;

revoke all on function public.cliente_entrenando(uuid) from public, anon, authenticated;

-- Una rutina entera, con cada ejercicio completado desde la biblioteca.
-- `p_con_notas`: si trae «Salud y lesiones» del cliente, para el aviso en
-- ámbar. Lo ve todo el equipo (ver rutinas_del_cliente).
create or replace function public.rutina_json(p_rutina uuid, p_con_notas boolean)
returns jsonb language sql stable security definer set search_path = public as $fn$
  select jsonb_build_object(
    'id',             r.id,
    'cliente_id',     r.cliente_id,
    'cliente_nombre', c.nombre,
    'cliente_notas',  case when p_con_notas and r.cliente_id is not null then c.notas end,
    'estado',         r.estado,
    'nombre',         r.nombre,
    'notas',          r.notas,
    'desde',          r.desde,
    'hasta',          r.hasta,
    'semanas',        r.semanas,
    'version',        r.version,
    'updated_at',     r.updated_at,
    'dias', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',     d.id,
        'orden',  d.orden,
        'nombre', d.nombre,
        'notas',  d.notas,
        'ejercicios', coalesce((
          select jsonb_agg(jsonb_build_object(
            'id',                re.id,
            'orden',             re.orden,
            'ejercicio_id',      re.ejercicio_id,
            'nombre',            e.nombre,
            'grupo',             e.grupo,
            'indicaciones',      e.indicaciones,
            'video_url',         e.video_url,
            'series',            re.series,
            'reps',              re.reps,
            'carga',             re.carga,
            'descanso_seg',      re.descanso_seg,
            'nota',              re.nota,
            'junto_al_anterior', re.junto_al_anterior
          ) order by re.orden)
          from public.rutina_ejercicios re
          join public.ejercicios e on e.id = re.ejercicio_id
          where re.dia_id = d.id
        ), '[]'::jsonb)
      ) order by d.orden)
      from public.rutina_dias d
      where d.rutina_id = r.id
    ), '[]'::jsonb)
  )
  from public.rutinas r
  left join public.clientes c on c.id = r.cliente_id and c.empresa_id = r.empresa_id
  where r.id = p_rutina;
$fn$;

revoke all on function public.rutina_json(uuid, boolean) from public, anon, authenticated;

-- Un ejercicio por su nombre: el que ya está (aunque cambien mayúsculas,
-- tildes o espacios), y si estaba apagado se prende; si no está, se crea.
-- `on conflict`: dos celulares guardando a la vez el mismo nombre nuevo
-- terminan en el mismo ejercicio, no en un error.
create or replace function public.ejercicio_por_nombre(p_empresa uuid, p_nombre text)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_nombre text;
  v_id     uuid;
  v_activo boolean;
begin
  v_nombre := btrim(left(btrim(regexp_replace(coalesce(p_nombre, ''), '\s+', ' ', 'g')), 80));
  if v_nombre = '' then
    raise exception 'A un ejercicio le falta el nombre.' using errcode = '22023';
  end if;

  select id, activo into v_id, v_activo
  from public.ejercicios
  where empresa_id = p_empresa and clave = public.clave_ejercicio(v_nombre);

  if v_id is null then
    insert into public.ejercicios (empresa_id, nombre)
    values (p_empresa, v_nombre)
    on conflict (empresa_id, clave) do nothing
    returning id into v_id;

    if v_id is null then
      select id into v_id from public.ejercicios
      where empresa_id = p_empresa and clave = public.clave_ejercicio(v_nombre);
    end if;
  elsif not v_activo then
    update public.ejercicios set activo = true where id = v_id;
  end if;

  return v_id;
end $fn$;

revoke all on function public.ejercicio_por_nombre(uuid, text) from public, anon, authenticated;

-- En qué estado nace una rutina nueva. Sin cliente, plantilla. Con cliente:
-- vigente si no tiene ninguna, «la próxima» si ya tiene una vigente, y si
-- ya hay una próxima en preparación, no se arma otra al lado: dos
-- borradores del mismo cliente terminan con uno pisando al otro.
--
-- Primero se pregunta por la vigente y recién después por la próxima: el
-- que tocó «Terminar» con una próxima ya armada queda sin vigente y con un
-- borrador. La pantalla le muestra «Sin rutina» (Armar desde cero · Usar
-- una plantilla · Copiar la de otro cliente), y esos tres botones no
-- pueden chocar con un borrador que para él no está a la vista: la nueva
-- nace vigente, como dice el contrato.
--
-- El cliente queda bloqueado hasta el final de la transacción: dos toques
-- casi juntos no pueden crear las dos una vigente.
create or replace function public.destino_nueva_rutina(p_empresa uuid, p_cliente uuid)
returns text language plpgsql security definer set search_path = public as $fn$
begin
  if p_cliente is null then
    return 'plantilla';
  end if;

  perform 1 from public.clientes
  where id = p_cliente and empresa_id = p_empresa and activo
  for update;
  if not found then
    raise exception 'Ese cliente no es de esta cuenta.' using errcode = 'P0002';
  end if;

  if not exists (select 1 from public.rutinas where cliente_id = p_cliente and estado = 'vigente') then
    return 'vigente';
  end if;

  if exists (select 1 from public.rutinas where cliente_id = p_cliente and estado = 'borrador') then
    raise exception 'Este cliente ya tiene una próxima rutina en preparación: seguí con esa.'
      using errcode = '22023';
  end if;
  return 'borrador';
end $fn$;

revoke all on function public.destino_nueva_rutina(uuid, uuid) from public, anon, authenticated;

-- El link del cliente: lo crea si no existe y devuelve el token. Se llama
-- cada vez que una rutina queda vigente, así el botón de WhatsApp es un
-- link común, sin esperar nada antes de abrir (el Safari del iPhone
-- bloquea las ventanas que se abren después de un await).
create or replace function public.asegurar_enlace_rutina(p_empresa uuid, p_cliente uuid)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_token uuid;
begin
  insert into public.rutina_enlaces (cliente_id, empresa_id)
  values (p_cliente, p_empresa)
  on conflict (cliente_id) do nothing;

  select token into v_token from public.rutina_enlaces
  where cliente_id = p_cliente and empresa_id = p_empresa;
  return v_token;
end $fn$;

revoke all on function public.asegurar_enlace_rutina(uuid, uuid) from public, anon, authenticated;

-- Un texto sin ninguna palabra del nombre de una persona. Lo usa
-- `copiar_rutina` entre personas distintas: el trainer que tiene dos «Ana»
-- escribe el nombre entero («Rutina de Ana Ruiz», «Gabi Medina · fuerza»),
-- y sacar solo la primera palabra dejaría el apellido en el link de otro.
--
-- Se saca cada palabra del nombre con dos letras o más que no sea una
-- partícula («de», «da», «dos»…: sacarlas rompería «Rutina de fuerza»),
-- entera, sin mayúsculas ni tildes: «ANA» y «Ána» son «Ana», y «Ana» no
-- rompe «Semana» ni «Mariana».
--
-- Las letras se escriben a mano, sin \w ni \m: en PGlite (idioma C) la «é»
-- no es una letra para las expresiones regulares y en producción (ICU) sí,
-- y «José» se sacaría en un lado y en el otro no. El espacio duro (U+00A0)
-- que llega pegando desde WhatsApp o desde los contactos tampoco une dos
-- palabras: no es una letra.
create or replace function public.sin_nombre_de_persona(p_texto text, p_persona text)
returns text language plpgsql immutable set search_path = public as $fn$
declare
  c_con    constant text := 'ÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÑÇáàâãäéèêëíìîïóòôõöúùûüñç';
  c_sin    constant text := 'aaaaaeeeeiiiiooooouuuuncaaaaaeeeeiiiiooooouuuunc';
  c_letras constant text := '0-9A-Za-zÀ-ÖØ-öø-ɏ';
  v_nombre text[] := '{}';
  v_trozo  text;
  v_res    text := '';
begin
  for v_trozo in
    select m[1] from regexp_matches(coalesce(p_persona, ''), '([' || c_letras || ']+)', 'g') m
  loop
    v_trozo := translate(lower(v_trozo), c_con, c_sin);
    if char_length(v_trozo) >= 2
       and v_trozo <> all (array['de', 'del', 'la', 'las', 'los', 'da', 'das', 'do', 'dos',
                                 'di', 'du', 'van', 'von', 'y', 'e']) then
      v_nombre := v_nombre || v_trozo;
    end if;
  end loop;

  -- El texto en pedazos que son palabras o lo que va entre ellas, en orden:
  -- se deja todo tal cual salvo las palabras del nombre.
  for v_trozo in
    select m[1] from regexp_matches(coalesce(p_texto, ''),
                                    '([' || c_letras || ']+|[^' || c_letras || ']+)', 'g') m
  loop
    if not (translate(lower(v_trozo), c_con, c_sin) = any (v_nombre)) then
      v_res := v_res || v_trozo;
    end if;
  end loop;
  return v_res;
end $fn$;

revoke all on function public.sin_nombre_de_persona(text, text) from public, anon, authenticated;

-- ------------------------------------------------------------
-- 11. LA BIBLIOTECA
-- ------------------------------------------------------------
create or replace function public.ejercicios_de(p_empresa uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_lista jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  -- Los más usados primero: son los que el trainer va a buscar.
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',           e.id,
    'nombre',       e.nombre,
    'grupo',        e.grupo,
    'indicaciones', e.indicaciones,
    'video_url',    e.video_url,
    'activo',       e.activo,
    'usos',         u.usos
  ) order by u.usos desc, e.clave, e.nombre), '[]'::jsonb)
  into v_lista
  from public.ejercicios e
  cross join lateral (
    select count(*)::int as usos from public.rutina_ejercicios re where re.ejercicio_id = e.id
  ) u
  where e.empresa_id = p_empresa;

  return v_lista;
end $fn$;

revoke all on function public.ejercicios_de(uuid) from public, anon;
grant execute on function public.ejercicios_de(uuid) to authenticated;

-- Crear o editar un ejercicio de la biblioteca.
--
-- Renombrar uno al nombre de OTRO que ya existe es unirlos: «Sentadila»
-- pasa a ser «Sentadilla» en todas las rutinas y en el historial de cargas,
-- y el repetido desaparece. Es la única forma de arreglar un duplicado, y
-- como cambia rutinas de muchos clientes, es del dueño o de un admin.
create or replace function public.guardar_ejercicio(
  p_empresa       uuid,
  p_nombre        text,
  p_grupo         text default null,
  p_indicaciones  text default '',
  p_video         text default null,
  p_activo        boolean default true,
  p_id            uuid default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_nombre text;
  v_grupo  text;
  v_ind    text;
  v_video  text;
  v_otro   uuid;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  v_nombre := btrim(left(btrim(regexp_replace(coalesce(p_nombre, ''), '\s+', ' ', 'g')), 80));
  if v_nombre = '' then
    raise exception 'A un ejercicio le falta el nombre.' using errcode = '22023';
  end if;

  v_grupo := nullif(btrim(coalesce(p_grupo, '')), '');
  if v_grupo is not null and v_grupo not in ('piernas', 'gluteos', 'pecho', 'espalda', 'hombros',
                                             'brazos', 'core', 'cardio', 'movilidad', 'otro') then
    raise exception 'Ese grupo de ejercicios no existe.' using errcode = '22023';
  end if;

  v_ind := left(coalesce(p_indicaciones, ''), 500);

  v_video := nullif(btrim(coalesce(p_video, '')), '');
  if v_video is not null and v_video !~ '^https://\S+$' then
    raise exception 'El video tiene que ser un link que empiece con https://.' using errcode = '22023';
  end if;
  if char_length(v_video) > 300 then
    raise exception 'El link del video es demasiado largo.' using errcode = '22023';
  end if;

  -- Nuevo.
  if p_id is null then
    if exists (select 1 from public.ejercicios
               where empresa_id = p_empresa and clave = public.clave_ejercicio(v_nombre)) then
      raise exception 'Ya tenés un ejercicio que se llama así.' using errcode = '22023';
    end if;

    insert into public.ejercicios (empresa_id, nombre, grupo, indicaciones, video_url, activo)
    values (p_empresa, v_nombre, v_grupo, v_ind, v_video, coalesce(p_activo, true))
    returning id into v_otro;

    return jsonb_build_object('id', v_otro, 'unido', false);
  end if;

  -- Editar.
  perform 1 from public.ejercicios where id = p_id and empresa_id = p_empresa for update;
  if not found then
    raise exception 'Ese ejercicio no existe.' using errcode = 'P0002';
  end if;

  select id into v_otro from public.ejercicios
  where empresa_id = p_empresa and clave = public.clave_ejercicio(v_nombre) and id <> p_id;

  if v_otro is not null then
    if not public.es_admin(p_empresa) then
      raise exception 'Unir dos ejercicios es del dueño o de un administrador.' using errcode = '42501';
    end if;

    update public.rutina_ejercicios set ejercicio_id = v_otro where ejercicio_id = p_id;
    update public.cargas_historial  set ejercicio_id = v_otro where ejercicio_id = p_id;

    -- El que queda conserva lo suyo y completa lo que le faltaba con lo que
    -- traía el otro: unir no puede borrar un video o un «cómo se hace».
    update public.ejercicios
    set grupo        = coalesce(grupo, v_grupo),
        indicaciones = case when indicaciones = '' then v_ind else indicaciones end,
        video_url    = coalesce(video_url, v_video),
        activo       = activo or coalesce(p_activo, true)
    where id = v_otro;

    delete from public.ejercicios where id = p_id;

    return jsonb_build_object('id', v_otro, 'unido', true);
  end if;

  update public.ejercicios
  set nombre = v_nombre, grupo = v_grupo, indicaciones = v_ind,
      video_url = v_video, activo = coalesce(p_activo, true)
  where id = p_id;

  return jsonb_build_object('id', p_id, 'unido', false);
end $fn$;

revoke all on function public.guardar_ejercicio(uuid, text, text, text, text, boolean, uuid) from public, anon;
grant execute on function public.guardar_ejercicio(uuid, text, text, text, text, boolean, uuid) to authenticated;

-- Borrar de verdad solo lo que no se usó: lo escrito mal y nunca usado.
create or replace function public.borrar_ejercicio(p_empresa uuid, p_id uuid)
returns void language plpgsql security definer set search_path = public as $fn$
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if not public.es_admin(p_empresa) then
    raise exception 'Borrar un ejercicio es del dueño o de un administrador.' using errcode = '42501';
  end if;

  perform 1 from public.ejercicios where id = p_id and empresa_id = p_empresa for update;
  if not found then
    raise exception 'Ese ejercicio no existe.' using errcode = 'P0002';
  end if;

  if exists (select 1 from public.rutina_ejercicios where ejercicio_id = p_id)
     or exists (select 1 from public.cargas_historial where ejercicio_id = p_id) then
    raise exception 'Ese ejercicio está en rutinas: apagalo en vez de borrarlo.' using errcode = '22023';
  end if;

  delete from public.ejercicios where id = p_id;
end $fn$;

revoke all on function public.borrar_ejercicio(uuid, uuid) from public, anon;
grant execute on function public.borrar_ejercicio(uuid, uuid) to authenticated;

-- ------------------------------------------------------------
-- 12. LA PANTALLA /rutinas
--
--    «Para atender» es lo que el trainer tiene que hacer hoy: el que entrena
--    y no tiene rutina, el que ya cumplió las semanas que se dijo, y (solo
--    para quien ve la salud) el que hace más de un mes que no se mide.
-- ------------------------------------------------------------
create or replace function public.rutinas_de(p_empresa uuid, p_todos boolean default false)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_admin boolean;
  v_hoy   date;
  v_res   jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  v_admin := public.es_admin(p_empresa);
  v_hoy   := public.hoy_empresa(p_empresa);

  with base as (
    select c.id as cli, c.nombre as cli_nombre, c.telefono as cli_tel,
           public.cliente_entrenando(c.id) as entrena,
           vg.id as vig_id, vg.nombre as vig_nombre, vg.desde as vig_desde,
           vg.semanas as vig_semanas, vg.updated_at as vig_upd,
           (select b.id from public.rutinas b
            where b.cliente_id = c.id and b.estado = 'borrador') as borr_id,
           en.cliente_id as en_cli, en.token as en_token, en.activo as en_activo,
           case when v_admin then (select max(m.fecha) from public.mediciones m
                                   where m.cliente_id = c.id) end as ult_med
    from public.clientes c
    left join public.rutinas vg on vg.cliente_id = c.id and vg.estado = 'vigente'
    left join public.rutina_enlaces en on en.cliente_id = c.id
    where c.empresa_id = p_empresa and c.activo
  )
  select jsonb_build_object(
    'clientes', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',          b.cli,
        'nombre',      b.cli_nombre,
        'telefono',    b.cli_tel,
        'vigente',     case when b.vig_id is null then null else jsonb_build_object(
                         'id',         b.vig_id,
                         'nombre',     b.vig_nombre,
                         'desde',      b.vig_desde,
                         'semanas',    b.vig_semanas,
                         'cambia_el',  case when b.vig_semanas is not null
                                            then b.vig_desde + b.vig_semanas * 7 end,
                         'updated_at', b.vig_upd) end,
        'borrador_id', b.borr_id,
        'enlace',      case when b.en_cli is null then null
                            else jsonb_build_object('token', b.en_token, 'activo', b.en_activo) end,
        'ultima_medicion', b.ult_med,
        'entrenando',  b.entrena
      ) order by lower(b.cli_nombre), b.cli_nombre, b.cli)
      from base b
      where b.entrena or coalesce(p_todos, false)
    ), '[]'::jsonb),
    'para_atender', coalesce((
      select jsonb_agg(jsonb_build_object(
        'cliente_id', a.cli, 'nombre', a.cli_nombre, 'motivo', a.motivo
      ) order by lower(a.cli_nombre), a.cli, a.prioridad)
      from (
        select b.cli, b.cli_nombre, 'sin_rutina' as motivo, 1 as prioridad
        from base b where b.entrena and b.vig_id is null
        union all
        select b.cli, b.cli_nombre, 'cambiar', 2
        from base b where b.entrena and b.vig_semanas is not null
          and b.vig_desde + b.vig_semanas * 7 <= v_hoy
        union all
        select b.cli, b.cli_nombre, 'medir', 3
        from base b where b.entrena and v_admin and b.ult_med is not null
          and b.ult_med < v_hoy - 30
      ) a
    ), '[]'::jsonb),
    'plantillas', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',         p.id,
        'nombre',     p.nombre,
        'semanas',    p.semanas,
        'dias',       (select count(*)::int from public.rutina_dias d where d.rutina_id = p.id),
        'ejercicios', (select count(*)::int from public.rutina_ejercicios re
                       join public.rutina_dias d on d.id = re.dia_id where d.rutina_id = p.id),
        'updated_at', p.updated_at
      ) order by lower(p.nombre), p.nombre, p.id)
      from public.rutinas p
      where p.empresa_id = p_empresa and p.estado = 'plantilla'
    ), '[]'::jsonb)
  ) into v_res;

  return v_res;
end $fn$;

revoke all on function public.rutinas_de(uuid, boolean) from public, anon;
grant execute on function public.rutinas_de(uuid, boolean) to authenticated;

-- ------------------------------------------------------------
-- 13. LA CARPETA DE UNA PERSONA, Y UNA RUTINA ENTERA
-- ------------------------------------------------------------
create or replace function public.rutinas_del_cliente(p_empresa uuid, p_cliente uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_admin boolean;
  v_cli   public.clientes;
  v_vig   uuid;
  v_res   jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select * into v_cli from public.clientes where id = p_cliente and empresa_id = p_empresa;
  if v_cli.id is null then
    raise exception 'Ese cliente no es de esta cuenta.' using errcode = 'P0002';
  end if;

  v_admin := public.es_admin(p_empresa);
  select id into v_vig from public.rutinas where cliente_id = p_cliente and estado = 'vigente';

  select jsonb_build_object(
    'cliente', jsonb_build_object(
      'id',       v_cli.id,
      'nombre',   v_cli.nombre,
      'telefono', v_cli.telefono,
      -- «Salud y lesiones» la ve TODO el equipo, no solo el dueño: un
      -- trainer que trabaja para otro tiene que saber de la rodilla operada
      -- antes de entrenar a esa persona. Ya era así en la agenda y en
      -- Clientes (052, 097). Lo que es solo del dueño son las medidas.
      'notas',    v_cli.notas),
    'vigente', case when v_vig is null then null else public.rutina_json(v_vig, true) end,
    'borrador', (
      select jsonb_build_object('id', b.id, 'nombre', b.nombre, 'updated_at', b.updated_at)
      from public.rutinas b where b.cliente_id = p_cliente and b.estado = 'borrador'),
    'anteriores', coalesce((
      select jsonb_agg(jsonb_build_object('id', a.id, 'nombre', a.nombre, 'desde', a.desde, 'hasta', a.hasta)
                       order by a.desde desc, a.created_at desc)
      from public.rutinas a where a.cliente_id = p_cliente and a.estado = 'anterior'
    ), '[]'::jsonb),
    'enlace', (
      select jsonb_build_object('token', en.token, 'activo', en.activo)
      from public.rutina_enlaces en where en.cliente_id = p_cliente),
    'entrenando', public.cliente_entrenando(p_cliente)
  ) into v_res;

  return v_res;
end $fn$;

revoke all on function public.rutinas_del_cliente(uuid, uuid) from public, anon;
grant execute on function public.rutinas_del_cliente(uuid, uuid) to authenticated;

-- La usan el editor y la hoja de la agenda. Las lesiones van aparte, en
-- `cliente_notas`, para el aviso en ámbar del editor: nunca se copian a la
-- rutina, que es lo que ve el cliente.
create or replace function public.rutina(p_empresa uuid, p_rutina uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if not exists (select 1 from public.rutinas where id = p_rutina and empresa_id = p_empresa) then
    raise exception 'Esa rutina no existe.' using errcode = 'P0002';
  end if;

  return public.rutina_json(p_rutina, true);
end $fn$;

revoke all on function public.rutina(uuid, uuid) from public, anon;
grant execute on function public.rutina(uuid, uuid) to authenticated;

-- ------------------------------------------------------------
-- 14. GUARDAR UNA RUTINA
--
--    Todo de una vez, con una sola llamada: el editor no autoguarda, porque
--    si no el cliente vería una rutina a medio editar.
--
--    Los días y los ejercicios CONSERVAN SU ID: los tildes que el cliente
--    hizo en su celular están guardados por id, y el historial de cargas
--    necesita saber que «el mismo renglón» pasó de 40 a 50. Lo que llega
--    con un id de esta rutina se actualiza, lo nuevo se inserta, y lo que
--    no llegó se borra.
-- ------------------------------------------------------------
create or replace function public.guardar_rutina(
  p_empresa uuid,
  p_datos   jsonb,
  p_id      uuid default null,
  p_cliente uuid default null,
  p_version integer default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_hoy      date;
  v_r        public.rutinas;
  v_id       uuid;
  v_estado   text;
  v_version  integer;
  v_cliente  uuid;
  v_nombre   text;
  v_notas    text;
  v_semanas  numeric;
  v_desde    date;
  v_dias     jsonb;
  v_dia      jsonb;
  v_ejs      jsonb;
  v_ej       jsonb;
  v_i        integer;
  v_j        integer;
  v_num      numeric;
  v_texto    text;
  v_dia_id   uuid;
  v_ren_id   uuid;
  v_ejer_id  uuid;
  v_series   smallint;
  v_desc     smallint;
  v_reps     text;
  v_carga    text;
  v_viejo    public.rutina_ejercicios;
  v_dias_ant uuid[];
  v_ejs_ant  uuid[];
  v_dias_ok  uuid[] := '{}';
  v_ejs_ok   uuid[] := '{}';
  v_token    uuid;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  v_hoy := public.hoy_empresa(p_empresa);

  -- ---- 1. Lo que llega, entero, antes de escribir nada ----
  v_dias := case when jsonb_typeof(p_datos->'dias') = 'array' then p_datos->'dias' else '[]'::jsonb end;
  if jsonb_array_length(v_dias) not between 1 and 10 then
    raise exception 'Una rutina tiene entre 1 y 10 días.' using errcode = '22023';
  end if;

  v_nombre := btrim(left(btrim(coalesce(p_datos->>'nombre', '')), 60));
  if v_nombre = '' then
    raise exception 'Ponele un nombre a la rutina.' using errcode = '22023';
  end if;
  v_notas := left(coalesce(p_datos->>'notas', ''), 1000);

  v_semanas := nullif(btrim(coalesce(p_datos->>'semanas', '')), '')::numeric;
  if v_semanas is not null and (v_semanas <> trunc(v_semanas) or v_semanas not between 1 and 52) then
    raise exception 'Las semanas van de 1 a 52.' using errcode = '22023';
  end if;
  v_desde := nullif(btrim(coalesce(p_datos->>'desde', '')), '')::date;

  for v_dia in select value from jsonb_array_elements(v_dias) loop
    if btrim(coalesce(v_dia->>'nombre', '')) = '' then
      raise exception 'Cada día de la rutina necesita un nombre.' using errcode = '22023';
    end if;
    v_ejs := case when jsonb_typeof(v_dia->'ejercicios') = 'array' then v_dia->'ejercicios' else '[]'::jsonb end;
    if jsonb_array_length(v_ejs) > 30 then
      raise exception 'Un día tiene como máximo 30 ejercicios.' using errcode = '22023';
    end if;

    for v_ej in select value from jsonb_array_elements(v_ejs) loop
      if nullif(btrim(coalesce(v_ej->>'ejercicio_id', '')), '') is null
         and btrim(coalesce(v_ej->>'nombre', '')) = '' then
        raise exception 'A un ejercicio le falta el nombre.' using errcode = '22023';
      end if;

      v_num := nullif(btrim(coalesce(v_ej->>'series', '')), '')::numeric;
      if v_num is not null and (v_num <> trunc(v_num) or v_num not between 1 and 20) then
        raise exception 'Las series van de 1 a 20.' using errcode = '22023';
      end if;

      v_num := nullif(btrim(coalesce(v_ej->>'descanso_seg', '')), '')::numeric;
      if v_num is not null and (v_num <> trunc(v_num) or v_num not between 0 and 900) then
        raise exception 'El descanso va de 0 a 15 minutos.' using errcode = '22023';
      end if;

      -- La carga y las repeticiones no se recortan en silencio: «25 lb por
      -- lado» cortado a la mitad puede decir otra cosa.
      if char_length(btrim(coalesce(v_ej->>'carga', ''))) > 24 then
        raise exception 'La carga se escribe corta: hasta 24 letras.' using errcode = '22023';
      end if;
      if char_length(btrim(coalesce(v_ej->>'reps', ''))) > 20 then
        raise exception 'Las repeticiones se escriben cortas: hasta 20 letras.' using errcode = '22023';
      end if;
    end loop;
  end loop;

  -- ---- 2. La rutina ----
  if p_id is null then
    v_estado := public.destino_nueva_rutina(p_empresa, p_cliente);
    v_cliente := case when v_estado = 'plantilla' then null else p_cliente end;

    insert into public.rutinas (empresa_id, cliente_id, estado, nombre, notas, desde, semanas, creado_por)
    values (p_empresa, v_cliente, v_estado, v_nombre, v_notas,
            case when v_estado = 'vigente' then coalesce(v_desde, v_hoy) end,
            v_semanas::smallint, auth.uid())
    returning id, version into v_id, v_version;
  else
    select * into v_r from public.rutinas where id = p_id for update;
    if v_r.id is null or v_r.empresa_id <> p_empresa then
      raise exception 'Esa rutina no existe.' using errcode = 'P0002';
    end if;

    if v_r.estado = 'anterior' then
      raise exception 'Esa rutina ya terminó: armá la próxima a partir de ella.' using errcode = '22023';
    end if;

    if p_version is not null and p_version <> v_r.version then
      raise exception 'Alguien cambió esta rutina mientras la editabas. Recargá para ver la última.'
        using errcode = '22023';
    end if;

    v_id := v_r.id;
    v_estado := v_r.estado;
    v_cliente := v_r.cliente_id;

    update public.rutinas
    set nombre = v_nombre,
        notas = v_notas,
        semanas = v_semanas::smallint,
        -- Solo la vigente tiene «desde» (la próxima lo toma al activarse).
        desde = case when v_estado = 'vigente' then coalesce(v_desde, desde) else desde end,
        version = version + 1,
        updated_at = now()
    where id = v_id
    returning version into v_version;
  end if;

  -- ---- 3. Los días y sus ejercicios ----
  select coalesce(array_agg(d.id), '{}') into v_dias_ant
  from public.rutina_dias d where d.rutina_id = v_id;

  select coalesce(array_agg(re.id), '{}') into v_ejs_ant
  from public.rutina_ejercicios re
  join public.rutina_dias d on d.id = re.dia_id
  where d.rutina_id = v_id;

  for v_dia, v_i in select value, ordinality::int from jsonb_array_elements(v_dias) with ordinality loop
    v_dia_id := public.uuid_o_null(v_dia->>'id');

    -- Un id que no es de esta rutina, o que ya se usó arriba, es un día nuevo.
    if v_dia_id is not null and v_dia_id = any (v_dias_ant) and not (v_dia_id = any (v_dias_ok)) then
      update public.rutina_dias
      set orden = v_i,
          nombre = btrim(left(btrim(v_dia->>'nombre'), 40)),
          notas = left(coalesce(v_dia->>'notas', ''), 500)
      where id = v_dia_id;
    else
      insert into public.rutina_dias (empresa_id, rutina_id, orden, nombre, notas)
      values (p_empresa, v_id, v_i, btrim(left(btrim(v_dia->>'nombre'), 40)),
              left(coalesce(v_dia->>'notas', ''), 500))
      returning id into v_dia_id;
    end if;
    v_dias_ok := v_dias_ok || v_dia_id;

    v_ejs := case when jsonb_typeof(v_dia->'ejercicios') = 'array' then v_dia->'ejercicios' else '[]'::jsonb end;

    for v_ej, v_j in select value, ordinality::int from jsonb_array_elements(v_ejs) with ordinality loop
      -- El ejercicio de la biblioteca: por id (tiene que ser de esta
      -- empresa; la clave compuesta lo frenaría igual, pero así se dice
      -- con palabras) o por nombre.
      v_texto := nullif(btrim(coalesce(v_ej->>'ejercicio_id', '')), '');
      if v_texto is not null then
        v_ejer_id := public.uuid_o_null(v_texto);
        if v_ejer_id is null
           or not exists (select 1 from public.ejercicios where id = v_ejer_id and empresa_id = p_empresa) then
          raise exception 'Ese ejercicio no existe.' using errcode = 'P0002';
        end if;
      else
        v_ejer_id := public.ejercicio_por_nombre(p_empresa, v_ej->>'nombre');
      end if;

      v_series := nullif(btrim(coalesce(v_ej->>'series', '')), '')::numeric::smallint;
      v_desc   := nullif(btrim(coalesce(v_ej->>'descanso_seg', '')), '')::numeric::smallint;
      v_reps   := btrim(coalesce(v_ej->>'reps', ''));
      v_carga  := btrim(coalesce(v_ej->>'carga', ''));

      v_ren_id := public.uuid_o_null(v_ej->>'id');
      if v_ren_id is not null and v_ren_id = any (v_ejs_ant) and not (v_ren_id = any (v_ejs_ok)) then
        select * into v_viejo from public.rutina_ejercicios where id = v_ren_id;

        update public.rutina_ejercicios
        set dia_id = v_dia_id,
            orden = v_j,
            ejercicio_id = v_ejer_id,
            series = v_series,
            reps = v_reps,
            carga = v_carga,
            descanso_seg = v_desc,
            nota = left(coalesce(v_ej->>'nota', ''), 200),
            -- El primero de un día no puede ir «junto al anterior».
            junto_al_anterior = (v_j > 1 and coalesce((v_ej->>'junto_al_anterior')::boolean, false))
        where id = v_ren_id;

        -- Subir la carga editando la rutina vigente también es avance. Si
        -- se cambió el ejercicio por otro, no: «de 40 en sentadilla a 100
        -- en prensa» no es progreso de nada.
        if v_estado = 'vigente' and v_viejo.ejercicio_id = v_ejer_id
           and (v_viejo.carga is distinct from v_carga or v_viejo.reps is distinct from v_reps) then
          insert into public.cargas_historial (empresa_id, cliente_id, ejercicio_id, rutina_id, fecha,
                                               carga_antes, carga_despues, reps_antes, reps_despues, creado_por)
          values (p_empresa, v_cliente, v_ejer_id, v_id, v_hoy,
                  v_viejo.carga, v_carga, v_viejo.reps, v_reps, auth.uid());
        end if;
      else
        insert into public.rutina_ejercicios (empresa_id, dia_id, orden, ejercicio_id, series, reps, carga,
                                              descanso_seg, nota, junto_al_anterior)
        values (p_empresa, v_dia_id, v_j, v_ejer_id, v_series, v_reps, v_carga, v_desc,
                left(coalesce(v_ej->>'nota', ''), 200),
                (v_j > 1 and coalesce((v_ej->>'junto_al_anterior')::boolean, false)))
        returning id into v_ren_id;
      end if;
      v_ejs_ok := v_ejs_ok || v_ren_id;
    end loop;
  end loop;

  -- Lo que no llegó, se va. Primero los días (sus ejercicios caen en
  -- cascada, salvo los que ya se mudaron a otro día), después los
  -- ejercicios que quedaron sueltos en los días que siguen.
  delete from public.rutina_dias where rutina_id = v_id and not (id = any (v_dias_ok));

  delete from public.rutina_ejercicios re
  using public.rutina_dias d
  where d.id = re.dia_id and d.rutina_id = v_id and not (re.id = any (v_ejs_ok));

  -- ---- 4. El link, si quedó vigente ----
  if v_estado = 'vigente' then
    v_token := public.asegurar_enlace_rutina(p_empresa, v_cliente);
  end if;

  return jsonb_build_object('id', v_id, 'estado', v_estado, 'version', v_version, 'token', v_token);
end $fn$;

revoke all on function public.guardar_rutina(uuid, jsonb, uuid, uuid, integer) from public, anon;
grant execute on function public.guardar_rutina(uuid, jsonb, uuid, uuid, integer) to authenticated;

-- ------------------------------------------------------------
-- 15. COPIAR UNA RUTINA
--
--    Una sola función para cuatro botones: «Usar para Ana» (de una
--    plantilla), «Copiar la de otro cliente», «Armar la próxima» (la
--    vigente de Ana a un borrador de Ana) y «Guardar como plantilla».
--
--    Entre personas distintas no viaja nada de la persona: el nombre del
--    cliente de origen, palabra por palabra, se saca del nombre de la rutina
--    («Rutina de Ana Ruiz» no puede aparecer en el link de Pedro, ni como
--    «Rutina de Ruiz»), y con «Copiar sin las notas» se vacían las notas,
--    que pueden tener lesiones de la otra persona.
-- ------------------------------------------------------------
create or replace function public.copiar_rutina(
  p_empresa   uuid,
  p_origen    uuid,
  p_cliente   uuid default null,
  p_con_notas boolean default true
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_o         public.rutinas;
  v_estado    text;
  v_cliente   uuid;
  v_mismo     boolean;
  v_sin_notas boolean;
  v_pila      text;
  v_nombre    text;
  v_id        uuid;
  v_dia       public.rutina_dias;
  v_dia_id    uuid;
  v_token     uuid;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select * into v_o from public.rutinas where id = p_origen and empresa_id = p_empresa;
  if v_o.id is null then
    raise exception 'Esa rutina no existe.' using errcode = 'P0002';
  end if;

  v_estado := public.destino_nueva_rutina(p_empresa, p_cliente);
  v_cliente := case when v_estado = 'plantilla' then null else p_cliente end;

  -- «Armar la próxima» (el mismo cliente) conserva todo.
  v_mismo := v_o.cliente_id is not null and v_cliente is not null and v_o.cliente_id = v_cliente;
  v_sin_notas := not v_mismo and not coalesce(p_con_notas, true);

  v_nombre := v_o.nombre;
  if v_o.cliente_id is not null and not v_mismo then
    -- El nombre ENTERO de la persona, no solo el de pila: «Rutina de Ana
    -- Ruiz» sin «Ana» dejaría «Rutina de Ruiz» en el link de Pedro.
    select nombre into v_pila from public.clientes where id = v_o.cliente_id;
    v_nombre := public.sin_nombre_de_persona(v_nombre, v_pila);
    -- Lo que quedó suelto: «Rutina ()», «Rutina ·  · piernas», «· fuerza»,
    -- y un «de» que se quedó sin la persona antes de un separador.
    v_nombre := regexp_replace(v_nombre, '\(\s*\)|\[\s*\]', ' ', 'g');
    -- Los espacios raros van escritos como códigos (E'\u00A0') y no pegados:
    -- pegados, se volvían espacios comunes al aplicar la migración.
    v_nombre := regexp_replace(v_nombre, E'[[:space:]\u00A0]+', ' ', 'g');
    v_nombre := regexp_replace(v_nombre, '\s*([·•|/,:;–—-])(\s*[·•|/,:;–—-])+\s*', ' \1 ', 'g');
    v_nombre := regexp_replace(v_nombre, '(^|\s)(de|del|da|do|das|dos|para|pra)\s+(?=[·•|/,:;–—-])', '\1', 'gi');
    v_nombre := btrim(v_nombre, ' ·•|/,:;–—-');
    -- Vacío, o colgando de una partícula («Fuerza de», «Treino da»): «Rutina».
    if v_nombre = '' or lower(v_nombre) ~ '(^|\s)(de|del|da|do|das|dos|para|pra)$' then
      v_nombre := 'Rutina';
    end if;
  end if;

  insert into public.rutinas (empresa_id, cliente_id, estado, nombre, notas, desde, semanas, origen_id, creado_por)
  values (p_empresa, v_cliente, v_estado, v_nombre,
          case when v_sin_notas then '' else v_o.notas end,
          case when v_estado = 'vigente' then public.hoy_empresa(p_empresa) end,
          v_o.semanas, v_o.id, auth.uid())
  returning id into v_id;

  for v_dia in select * from public.rutina_dias where rutina_id = v_o.id order by orden loop
    insert into public.rutina_dias (empresa_id, rutina_id, orden, nombre, notas)
    values (p_empresa, v_id, v_dia.orden, v_dia.nombre, case when v_sin_notas then '' else v_dia.notas end)
    returning id into v_dia_id;

    insert into public.rutina_ejercicios (empresa_id, dia_id, orden, ejercicio_id, series, reps, carga,
                                          descanso_seg, nota, junto_al_anterior)
    select p_empresa, v_dia_id, re.orden, re.ejercicio_id, re.series, re.reps, re.carga,
           re.descanso_seg, case when v_sin_notas then '' else re.nota end, re.junto_al_anterior
    from public.rutina_ejercicios re
    where re.dia_id = v_dia.id
    order by re.orden;
  end loop;

  if v_estado = 'vigente' then
    v_token := public.asegurar_enlace_rutina(p_empresa, v_cliente);
  end if;

  return jsonb_build_object('id', v_id, 'estado', v_estado, 'token', v_token);
end $fn$;

revoke all on function public.copiar_rutina(uuid, uuid, uuid, boolean) from public, anon;
grant execute on function public.copiar_rutina(uuid, uuid, uuid, boolean) to authenticated;

-- ------------------------------------------------------------
-- 16. ACTIVAR LA PRÓXIMA, TERMINAR, BORRAR
--
--    `hasta` nunca queda antes de `desde`: una rutina que se puso a
--    arrancar el lunes y se termina el viernes anterior termina el día que
--    arrancaba.
-- ------------------------------------------------------------
create or replace function public.activar_rutina(p_empresa uuid, p_rutina uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_r   public.rutinas;
  v_hoy date;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select * into v_r from public.rutinas where id = p_rutina and empresa_id = p_empresa for update;
  if v_r.id is null then
    raise exception 'Esa rutina no existe.' using errcode = 'P0002';
  end if;

  if v_r.estado <> 'borrador' then
    raise exception 'Solo se puede activar una rutina en preparación.' using errcode = '22023';
  end if;

  perform 1 from public.clientes where id = v_r.cliente_id for update;
  v_hoy := public.hoy_empresa(p_empresa);

  -- Primero la vieja pasa a la historia: hay una sola vigente por cliente.
  update public.rutinas
  set estado = 'anterior', hasta = greatest(v_hoy, desde), updated_at = now()
  where cliente_id = v_r.cliente_id and estado = 'vigente';

  update public.rutinas
  set estado = 'vigente', desde = v_hoy, hasta = null, updated_at = now()
  where id = p_rutina;

  return jsonb_build_object('id', p_rutina,
                            'token', public.asegurar_enlace_rutina(p_empresa, v_r.cliente_id));
end $fn$;

revoke all on function public.activar_rutina(uuid, uuid) from public, anon;
grant execute on function public.activar_rutina(uuid, uuid) to authenticated;

-- El cliente queda sin rutina y su link dice «Tu entrenador está preparando
-- tu rutina». El link no se apaga: eso es otro botón.
create or replace function public.terminar_rutina(p_empresa uuid, p_rutina uuid)
returns void language plpgsql security definer set search_path = public as $fn$
declare
  v_r public.rutinas;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select * into v_r from public.rutinas where id = p_rutina and empresa_id = p_empresa for update;
  if v_r.id is null then
    raise exception 'Esa rutina no existe.' using errcode = 'P0002';
  end if;

  if v_r.estado <> 'vigente' then
    raise exception 'Esa rutina no está vigente.' using errcode = '22023';
  end if;

  update public.rutinas
  set estado = 'anterior', hasta = greatest(public.hoy_empresa(p_empresa), desde), updated_at = now()
  where id = p_rutina;
end $fn$;

revoke all on function public.terminar_rutina(uuid, uuid) from public, anon;
grant execute on function public.terminar_rutina(uuid, uuid) to authenticated;

-- Se borra lo que nunca vio nadie: una próxima que no se usó (cualquiera
-- del equipo) o una plantilla (dueño o admin: la usa todo el negocio). Lo
-- que un cliente ya tuvo es su historia.
create or replace function public.borrar_rutina(p_empresa uuid, p_rutina uuid)
returns void language plpgsql security definer set search_path = public as $fn$
declare
  v_r public.rutinas;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select * into v_r from public.rutinas where id = p_rutina and empresa_id = p_empresa for update;
  if v_r.id is null then
    raise exception 'Esa rutina no existe.' using errcode = 'P0002';
  end if;

  if v_r.estado in ('vigente', 'anterior') then
    raise exception 'Las rutinas de un cliente no se borran: quedan como historia.' using errcode = '22023';
  end if;

  if v_r.estado = 'plantilla' and not public.es_admin(p_empresa) then
    raise exception 'Borrar una plantilla es del dueño o de un administrador.' using errcode = '42501';
  end if;

  delete from public.rutinas where id = p_rutina;
end $fn$;

revoke all on function public.borrar_rutina(uuid, uuid) from public, anon;
grant execute on function public.borrar_rutina(uuid, uuid) to authenticated;

-- ------------------------------------------------------------
-- 17. SUBIR LA CARGA DESDE LA AGENDA
--
--    El trainer que entrena en persona sube las cargas en la sesión, con el
--    celular en la mano: no va a abrir el editor para cambiar un número.
--    Solo en la vigente, que es la que se está entrenando. Suma una versión:
--    si alguien tenía el editor abierto, al guardar se entera en vez de
--    pisar la carga nueva con la vieja.
-- ------------------------------------------------------------
create or replace function public.cambiar_carga(
  p_empresa          uuid,
  p_rutina_ejercicio uuid,
  p_carga            text,
  p_reps             text default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_rid   uuid;
  v_re    public.rutina_ejercicios;
  v_r     public.rutinas;
  v_carga text;
  v_reps  text;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  -- Los candados en el MISMO orden que `guardar_rutina`: primero la
  -- rutina, después el renglón. Al revés, un celular que guarda en el
  -- editor mientras otro sube la carga desde la agenda se quedarían
  -- esperando uno al otro, y PostgreSQL cortaría a uno con «deadlock
  -- detected», que nadie entiende. Así el segundo espera, y choca limpio
  -- con el control de versión.
  select d.rutina_id into v_rid
  from public.rutina_ejercicios re
  join public.rutina_dias d on d.id = re.dia_id
  where re.id = p_rutina_ejercicio and re.empresa_id = p_empresa;
  if v_rid is null then
    raise exception 'Ese ejercicio no existe.' using errcode = 'P0002';
  end if;

  select * into v_r from public.rutinas where id = v_rid and empresa_id = p_empresa for update;

  select * into v_re from public.rutina_ejercicios
  where id = p_rutina_ejercicio and empresa_id = p_empresa
  for update;
  -- Mientras esperaba, el editor pudo sacarlo de la rutina.
  if v_re.id is null or v_r.id is null then
    raise exception 'Ese ejercicio no existe.' using errcode = 'P0002';
  end if;

  if v_r.estado <> 'vigente' then
    raise exception 'Solo se cambia la carga de la rutina vigente.' using errcode = '22023';
  end if;

  v_carga := btrim(coalesce(p_carga, ''));
  v_reps  := case when p_reps is null then v_re.reps else btrim(p_reps) end;

  if char_length(v_carga) > 24 then
    raise exception 'La carga se escribe corta: hasta 24 letras.' using errcode = '22023';
  end if;
  if char_length(v_reps) > 20 then
    raise exception 'Las repeticiones se escriben cortas: hasta 20 letras.' using errcode = '22023';
  end if;

  if v_carga is distinct from v_re.carga or v_reps is distinct from v_re.reps then
    update public.rutina_ejercicios set carga = v_carga, reps = v_reps where id = v_re.id;

    insert into public.cargas_historial (empresa_id, cliente_id, ejercicio_id, rutina_id, fecha,
                                         carga_antes, carga_despues, reps_antes, reps_despues, creado_por)
    values (p_empresa, v_r.cliente_id, v_re.ejercicio_id, v_r.id, public.hoy_empresa(p_empresa),
            v_re.carga, v_carga, v_re.reps, v_reps, auth.uid());

    update public.rutinas set version = version + 1, updated_at = now() where id = v_r.id;
  end if;

  return jsonb_build_object('carga', v_carga, 'reps', v_reps);
end $fn$;

revoke all on function public.cambiar_carga(uuid, uuid, text, text) from public, anon;
grant execute on function public.cambiar_carga(uuid, uuid, text, text) to authenticated;

-- ------------------------------------------------------------
-- 18. EL LINK DEL CLIENTE
--
--    Ninguna de estas escribe en una tabla con el candado de cuenta
--    vencida: apagar o cambiar un link que se reenvió a quien no debía
--    tiene que andar siempre.
-- ------------------------------------------------------------
create or replace function public.enlace_rutina(p_empresa uuid, p_cliente uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_res jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if not exists (select 1 from public.clientes where id = p_cliente and empresa_id = p_empresa) then
    raise exception 'Ese cliente no es de esta cuenta.' using errcode = 'P0002';
  end if;

  perform public.asegurar_enlace_rutina(p_empresa, p_cliente);

  select jsonb_build_object('token', token, 'activo', activo) into v_res
  from public.rutina_enlaces where cliente_id = p_cliente;
  return v_res;
end $fn$;

revoke all on function public.enlace_rutina(uuid, uuid) from public, anon;
grant execute on function public.enlace_rutina(uuid, uuid) to authenticated;

-- «Cambiar link»: el viejo deja de existir, y quien lo tenga ve lo mismo que
-- con uno inventado.
create or replace function public.renovar_enlace_rutina(p_empresa uuid, p_cliente uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_res jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if not exists (select 1 from public.clientes where id = p_cliente and empresa_id = p_empresa) then
    raise exception 'Ese cliente no es de esta cuenta.' using errcode = 'P0002';
  end if;

  insert into public.rutina_enlaces (cliente_id, empresa_id, token, activo)
  values (p_cliente, p_empresa, gen_random_uuid(), true)
  on conflict (cliente_id) do update
    set token = excluded.token, activo = true, updated_at = now();

  select jsonb_build_object('token', token, 'activo', activo) into v_res
  from public.rutina_enlaces where cliente_id = p_cliente;
  return v_res;
end $fn$;

revoke all on function public.renovar_enlace_rutina(uuid, uuid) from public, anon;
grant execute on function public.renovar_enlace_rutina(uuid, uuid) to authenticated;

-- Prender o apagar el link de una persona.
create or replace function public.activar_enlace_rutina(p_empresa uuid, p_cliente uuid, p_activo boolean)
returns void language plpgsql security definer set search_path = public as $fn$
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if not exists (select 1 from public.clientes where id = p_cliente and empresa_id = p_empresa) then
    raise exception 'Ese cliente no es de esta cuenta.' using errcode = 'P0002';
  end if;

  insert into public.rutina_enlaces (cliente_id, empresa_id, activo)
  values (p_cliente, p_empresa, coalesce(p_activo, true))
  on conflict (cliente_id) do update
    set activo = excluded.activo, updated_at = now();
end $fn$;

revoke all on function public.activar_enlace_rutina(uuid, uuid, boolean) from public, anon;
grant execute on function public.activar_enlace_rutina(uuid, uuid, boolean) to authenticated;

-- «Apagar mis links de rutina», desde la pantalla del candado: el dueño que
-- se va, o que no va a renovar, corta todos de una vez. Devuelve cuántos.
create or replace function public.apagar_enlaces_rutina(p_empresa uuid)
returns integer language plpgsql security definer set search_path = public as $fn$
declare
  v_n integer;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if not public.es_admin(p_empresa) then
    raise exception 'Apagar todos los links es del dueño o de un administrador.' using errcode = '42501';
  end if;

  update public.rutina_enlaces set activo = false, updated_at = now()
  where empresa_id = p_empresa and activo;
  get diagnostics v_n = row_count;
  return v_n;
end $fn$;

revoke all on function public.apagar_enlaces_rutina(uuid) from public, anon;
grant execute on function public.apagar_enlaces_rutina(uuid) to authenticated;

-- ------------------------------------------------------------
-- 19. LO QUE VE EL CLIENTE (pública, sin sesión)
--
--    El patrón de `reserva_por_token` (038): el token ES la credencial, así
--    que se devuelve lo justo. El nombre de pila, el negocio y la rutina
--    vigente. NUNCA el teléfono, el apellido, «Salud y lesiones», medidas,
--    paquetes, plata, borradores, rutinas anteriores ni ids (salvo el de
--    cada renglón, que es con lo que el celular guarda sus tildes).
--
--    Un token que no existe, un link apagado o cambiado, un cliente
--    archivado o un negocio que ya no es de entrenamiento dan EXACTAMENTE
--    lo mismo: `{"existe": false}`. Distinguirlos le diría a quien prueba
--    tokens cuál existió.
--
--    La cuenta vencida (decisión de Matías): 30 días de gracia; después, en
--    vez de la rutina, «Tu entrenador tiene que renovar su cuenta».
-- ------------------------------------------------------------
create or replace function public.rutina_por_token(p_token uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_en      public.rutina_enlaces;
  v_cli     public.clientes;
  v_emp     public.empresas;
  v_r       public.rutinas;
  v_nombre  text;
  v_renovar boolean;
begin
  select * into v_en from public.rutina_enlaces where token = p_token;
  if v_en.cliente_id is null or not v_en.activo then
    return jsonb_build_object('existe', false);
  end if;

  select * into v_cli from public.clientes where id = v_en.cliente_id and empresa_id = v_en.empresa_id;
  if v_cli.id is null or not v_cli.activo then
    return jsonb_build_object('existe', false);
  end if;

  select * into v_emp from public.empresas where id = v_en.empresa_id;
  if v_emp.id is null or v_emp.rubro is distinct from 'entrenamiento' then
    return jsonb_build_object('existe', false);
  end if;

  -- El nombre de pila: lo que va hasta el primer espacio de CUALQUIER tipo.
  -- `guardar_cliente` solo recorta los espacios comunes, y un nombre pegado
  -- desde WhatsApp o desde los contactos trae espacios duros (U+00A0 y
  -- parientes), tabuladores o saltos: cortar solo en « » mostraría el
  -- apellido. Las mismas clases en PGlite (idioma C) y en producción (ICU).
  -- El espacio duro de WhatsApp (U+00A0) y sus parientes, escritos como
  -- códigos y no pegados: pegados, se volvían espacios comunes al aplicar la
  -- migración, y el link mostraba el apellido.
  v_nombre := coalesce(substring(v_cli.nombre from E'[^[:space:]\u00A0\u2007\u202F\u2060\uFEFF]+'), '');

  v_renovar := not public.puede_cargar(v_emp.id)
    and coalesce((
      select s.periodo_fin is null or s.periodo_fin <= now() - interval '30 days'
      from public.suscripciones s where s.empresa_id = v_emp.id
    ), true);

  if v_renovar then
    return jsonb_build_object(
      'existe', true, 'negocio', v_emp.nombre, 'nombre', v_nombre,
      'renovar', true, 'actualizada', null, 'rutina', null);
  end if;

  select * into v_r from public.rutinas
  where cliente_id = v_cli.id and empresa_id = v_emp.id and estado = 'vigente';

  return jsonb_build_object(
    'existe',      true,
    'negocio',     v_emp.nombre,
    'nombre',      v_nombre,
    'renovar',     false,
    'actualizada', v_r.updated_at,
    'rutina', case when v_r.id is null then null else jsonb_build_object(
      'nombre', v_r.nombre,
      'notas',  v_r.notas,
      'desde',  v_r.desde,
      'dias', coalesce((
        select jsonb_agg(jsonb_build_object(
          'orden',  d.orden,
          'nombre', d.nombre,
          'notas',  d.notas,
          'ejercicios', coalesce((
            select jsonb_agg(jsonb_build_object(
              'id',           re.id,
              'orden',        re.orden,
              'nombre',       e.nombre,
              'series',       re.series,
              'reps',         re.reps,
              'carga',        re.carga,
              'descanso_seg', re.descanso_seg,
              'nota',         re.nota,
              'junto',        re.junto_al_anterior,
              'video',        e.video_url,
              'como',         e.indicaciones
            ) order by re.orden)
            from public.rutina_ejercicios re
            join public.ejercicios e on e.id = re.ejercicio_id
            where re.dia_id = d.id
          ), '[]'::jsonb)
        ) order by d.orden)
        from public.rutina_dias d
        where d.rutina_id = v_r.id
      ), '[]'::jsonb)
    ) end
  );
end $fn$;

revoke all on function public.rutina_por_token(uuid) from public;
grant execute on function public.rutina_por_token(uuid) to anon, authenticated;

-- ------------------------------------------------------------
-- 20. ANOTAR UN CONTROL DE MEDIDAS
--
--    Solo el dueño o un admin, y con el sí del cliente (una sola vez: queda
--    en su ficha con la fecha y quién lo registró).
--
--    Si ese día ya hay un control, se COMPLETA en vez de duplicarlo: lo que
--    llega pisa, lo que no llega queda. Y se devuelve qué cambió de lo que
--    ya tenía valor, para que la pantalla lo muestre antes de que alguien
--    pise sin querer el peso de la mañana con el de la tarde.
--
--    Los rangos los controlan los check de la tabla. Arriba de 1000 (o de
--    100 en la grasa) el número ni entra en la columna, y PostgreSQL diría
--    «numeric field overflow»: se frena antes, con el mismo mensaje.
-- ------------------------------------------------------------
create or replace function public.anotar_medicion(
  p_empresa   uuid,
  p_cliente   uuid,
  p_fecha     date,
  p_datos     jsonb,
  p_consiente boolean default false,
  p_id        uuid default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_medidas constant text[] := array['peso_kg', 'altura_cm', 'cintura_cm', 'cadera_cm', 'pecho_cm',
                                      'brazo_cm', 'muslo_cm', 'grasa_pct', 'pantorrilla_cm', 'cuello_cm'];
  v_orden   constant text[] := array['peso_kg', 'altura_cm', 'cintura_cm', 'cadera_cm', 'pecho_cm',
                                      'brazo_cm', 'muslo_cm', 'grasa_pct', 'grasa_metodo',
                                      'pantorrilla_cm', 'cuello_cm', 'nota'];
  v_hoy       date;
  v_fecha     date;
  v_clave     text;
  v_valor     jsonb;
  v_texto     text;
  v_num       numeric;
  v_limpio    jsonb := '{}'::jsonb;
  v_previa    public.mediciones;
  v_antes     jsonb;
  v_fila      jsonb;
  v_fusion    boolean := false;
  v_cambios   jsonb := '[]'::jsonb;
  v_consintio timestamptz;
  v_id        uuid;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if not public.es_admin(p_empresa) then
    raise exception 'Las medidas y el progreso son del dueño o de un administrador.' using errcode = '42501';
  end if;

  if not exists (select 1 from public.clientes where id = p_cliente and empresa_id = p_empresa) then
    raise exception 'Ese cliente no es de esta cuenta.' using errcode = 'P0002';
  end if;

  -- El control que se edita, si es una edición.
  if p_id is not null then
    select * into v_previa from public.mediciones
    where id = p_id and empresa_id = p_empresa and cliente_id = p_cliente
    for update;
    if v_previa.id is null then
      raise exception 'Ese control no existe.' using errcode = 'P0002';
    end if;
  end if;

  v_hoy := public.hoy_empresa(p_empresa);
  -- Editar sin mandar la fecha no la mueve a hoy.
  v_fecha := coalesce(p_fecha, v_previa.fecha, v_hoy);
  if v_fecha > v_hoy then
    raise exception 'La fecha del control no puede ser futura.' using errcode = '22023';
  end if;
  if v_fecha < date '2000-01-01' then
    raise exception 'Esa fecha no es válida.' using errcode = '22023';
  end if;

  -- Solo las claves conocidas; lo demás se ignora. Un número puede venir
  -- con coma («72,5»), como lo escribe cualquiera.
  for v_clave, v_valor in
    select key, value from jsonb_each(case when jsonb_typeof(p_datos) = 'object' then p_datos else '{}'::jsonb end)
  loop
    if v_clave = any (v_medidas) then
      v_texto := btrim(v_valor #>> '{}');
      if v_texto is null or v_texto = '' then
        v_limpio := v_limpio || jsonb_build_object(v_clave, null);
      elsif v_texto ~ '^-?[0-9]+([.,][0-9]+)?$' then
        v_num := round(replace(v_texto, ',', '.')::numeric, 1);
        if abs(v_num) >= 1000 or (v_clave = 'grasa_pct' and abs(v_num) >= 100) then
          raise exception 'Ese valor está fuera de rango. Revisalo.' using errcode = '23514';
        end if;
        v_limpio := v_limpio || jsonb_build_object(v_clave, v_num);
      else
        raise exception 'Cada medida tiene que ser un número.' using errcode = '22023';
      end if;
    elsif v_clave = 'grasa_metodo' then
      v_limpio := v_limpio || jsonb_build_object(v_clave, nullif(btrim(coalesce(v_valor #>> '{}', '')), ''));
    elsif v_clave = 'nota' then
      v_limpio := v_limpio || jsonb_build_object(v_clave, left(coalesce(v_valor #>> '{}', ''), 300));
    end if;
  end loop;

  select consiente_medidas_at into v_consintio from public.fichas_entreno where cliente_id = p_cliente;
  if v_consintio is null and not coalesce(p_consiente, false) then
    raise exception 'Antes de anotar medidas, confirmá que el cliente está de acuerdo.' using errcode = '22023';
  end if;

  if p_id is not null then
    if v_fecha <> v_previa.fecha
       and exists (select 1 from public.mediciones
                   where cliente_id = p_cliente and fecha = v_fecha and id <> p_id) then
      raise exception 'Ya hay un control ese día: editá ese.' using errcode = '22023';
    end if;
  else
    select * into v_previa from public.mediciones
    where cliente_id = p_cliente and fecha = v_fecha
    for update;
    v_fusion := v_previa.id is not null;
  end if;

  v_antes := case when v_previa.id is null then '{}'::jsonb else to_jsonb(v_previa) end;
  v_fila  := v_antes || v_limpio;

  if not exists (select 1 from unnest(v_medidas) k where v_fila->>k is not null) then
    raise exception 'Anotá al menos una medida.' using errcode = '22023';
  end if;

  if (v_fila->>'grasa_pct' is null) <> (v_fila->>'grasa_metodo' is null) then
    raise exception 'La grasa corporal va con su método: balanza, plicómetro, cinta u otro.' using errcode = '22023';
  end if;

  if v_fusion then
    select coalesce(jsonb_agg(jsonb_build_object('campo', k, 'antes', v_antes->k, 'despues', v_limpio->k)
                              order by array_position(v_orden, k)), '[]'::jsonb)
    into v_cambios
    from jsonb_object_keys(v_limpio) k
    where coalesce(v_antes->k, 'null'::jsonb) <> 'null'::jsonb
      and not (k = 'nota' and v_antes->>k = '')
      and (v_antes->k) is distinct from (v_limpio->k);
  end if;

  if v_previa.id is null then
    insert into public.mediciones (
      empresa_id, cliente_id, fecha, peso_kg, altura_cm, cintura_cm, cadera_cm, pecho_cm, brazo_cm,
      muslo_cm, grasa_pct, grasa_metodo, pantorrilla_cm, cuello_cm, nota, creado_por)
    values (
      p_empresa, p_cliente, v_fecha,
      (v_fila->>'peso_kg')::numeric, (v_fila->>'altura_cm')::numeric, (v_fila->>'cintura_cm')::numeric,
      (v_fila->>'cadera_cm')::numeric, (v_fila->>'pecho_cm')::numeric, (v_fila->>'brazo_cm')::numeric,
      (v_fila->>'muslo_cm')::numeric, (v_fila->>'grasa_pct')::numeric, v_fila->>'grasa_metodo',
      (v_fila->>'pantorrilla_cm')::numeric, (v_fila->>'cuello_cm')::numeric,
      coalesce(v_fila->>'nota', ''), auth.uid())
    returning id into v_id;
  else
    update public.mediciones
    set fecha          = v_fecha,
        peso_kg        = (v_fila->>'peso_kg')::numeric,
        altura_cm      = (v_fila->>'altura_cm')::numeric,
        cintura_cm     = (v_fila->>'cintura_cm')::numeric,
        cadera_cm      = (v_fila->>'cadera_cm')::numeric,
        pecho_cm       = (v_fila->>'pecho_cm')::numeric,
        brazo_cm       = (v_fila->>'brazo_cm')::numeric,
        muslo_cm       = (v_fila->>'muslo_cm')::numeric,
        grasa_pct      = (v_fila->>'grasa_pct')::numeric,
        grasa_metodo   = v_fila->>'grasa_metodo',
        pantorrilla_cm = (v_fila->>'pantorrilla_cm')::numeric,
        cuello_cm      = (v_fila->>'cuello_cm')::numeric,
        nota           = coalesce(v_fila->>'nota', ''),
        updated_at     = now()
    where id = v_previa.id;
    v_id := v_previa.id;
  end if;

  -- El sí del cliente, la primera vez. Si ya estaba, se conserva el
  -- original: lo que importa es desde cuándo y quién lo registró.
  if coalesce(p_consiente, false) then
    insert into public.fichas_entreno (cliente_id, empresa_id, consiente_medidas_at, consiente_por, updated_at)
    values (p_cliente, p_empresa, now(), auth.uid(), now())
    on conflict (cliente_id) do update
      set consiente_medidas_at = coalesce(fichas_entreno.consiente_medidas_at, excluded.consiente_medidas_at),
          consiente_por = case when fichas_entreno.consiente_medidas_at is null
                               then excluded.consiente_por else fichas_entreno.consiente_por end,
          updated_at = now();
  end if;

  return jsonb_build_object('id', v_id, 'fusionada', v_fusion, 'cambios', v_cambios);
end $fn$;

revoke all on function public.anotar_medicion(uuid, uuid, date, jsonb, boolean, uuid) from public, anon;
grant execute on function public.anotar_medicion(uuid, uuid, date, jsonb, boolean, uuid) to authenticated;

create or replace function public.borrar_medicion(p_empresa uuid, p_id uuid)
returns void language plpgsql security definer set search_path = public as $fn$
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if not public.es_admin(p_empresa) then
    raise exception 'Las medidas y el progreso son del dueño o de un administrador.' using errcode = '42501';
  end if;

  delete from public.mediciones where id = p_id and empresa_id = p_empresa;
  if not found then
    raise exception 'Ese control no existe.' using errcode = 'P0002';
  end if;
end $fn$;

revoke all on function public.borrar_medicion(uuid, uuid) from public, anon;
grant execute on function public.borrar_medicion(uuid, uuid) to authenticated;

-- ------------------------------------------------------------
-- 21. EL PROGRESO DE UNA PERSONA
--
--    Los números, en orden de fecha; los cálculos (IMC, cintura/altura,
--    diferencias) los hace src/lib/medidas.ts. Y cómo subieron las cargas,
--    ejercicio por ejercicio.
-- ------------------------------------------------------------
create or replace function public.progreso_de(p_empresa uuid, p_cliente uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_cli public.clientes;
  v_res jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if not public.es_admin(p_empresa) then
    raise exception 'Las medidas y el progreso son del dueño o de un administrador.' using errcode = '42501';
  end if;

  select * into v_cli from public.clientes where id = p_cliente and empresa_id = p_empresa;
  if v_cli.id is null then
    raise exception 'Ese cliente no es de esta cuenta.' using errcode = 'P0002';
  end if;

  select jsonb_build_object(
    'cliente', jsonb_build_object('id', v_cli.id, 'nombre', v_cli.nombre, 'telefono', v_cli.telefono),
    'consiente_medidas_at', (select f.consiente_medidas_at from public.fichas_entreno f
                             where f.cliente_id = p_cliente),
    'mediciones', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',             m.id,
        'fecha',          m.fecha,
        'peso_kg',        m.peso_kg,
        'altura_cm',      m.altura_cm,
        'cintura_cm',     m.cintura_cm,
        'cadera_cm',      m.cadera_cm,
        'pecho_cm',       m.pecho_cm,
        'brazo_cm',       m.brazo_cm,
        'muslo_cm',       m.muslo_cm,
        'grasa_pct',      m.grasa_pct,
        'grasa_metodo',   m.grasa_metodo,
        'pantorrilla_cm', m.pantorrilla_cm,
        'cuello_cm',      m.cuello_cm,
        'nota',           m.nota
      ) order by m.fecha)
      from public.mediciones m where m.cliente_id = p_cliente
    ), '[]'::jsonb),
    'rutina_vigente', (
      select jsonb_build_object('nombre', r.nombre, 'desde', r.desde)
      from public.rutinas r where r.cliente_id = p_cliente and r.estado = 'vigente'),
    'cargas', coalesce((
      select jsonb_agg(jsonb_build_object(
        'ejercicio_id', g.ejercicio_id,
        'nombre',       g.nombre,
        'cambios',      g.cambios
      ) order by g.clave, g.nombre)
      from (
        select e.id as ejercicio_id, e.nombre, e.clave,
               jsonb_agg(jsonb_build_object(
                 'fecha',         h.fecha,
                 'carga_antes',   h.carga_antes,
                 'carga_despues', h.carga_despues,
                 'reps_antes',    h.reps_antes,
                 'reps_despues',  h.reps_despues
               ) order by h.fecha, h.created_at) as cambios
        from public.cargas_historial h
        join public.ejercicios e on e.id = h.ejercicio_id
        where h.cliente_id = p_cliente
        group by e.id, e.nombre, e.clave
      ) g
    ), '[]'::jsonb)
  ) into v_res;

  return v_res;
end $fn$;

revoke all on function public.progreso_de(uuid, uuid) from public, anon;
grant execute on function public.progreso_de(uuid, uuid) to authenticated;

-- ------------------------------------------------------------
-- 22. LA RUTINA DE CADA SESIÓN DE LA AGENDA
--
--    Aparte, y no dentro de `agenda_del_dia` o `panel_profe`: esas ya van
--    por su quinta copia, y cada copia es una oportunidad de perder algo.
--    La pantalla llama las dos y junta por id de reserva.
-- ------------------------------------------------------------
create or replace function public.rutinas_de_la_agenda(p_empresa uuid, p_fecha date default null)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_zona  text;
  v_fecha date;
  v_res   jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select coalesce(zona_horaria, 'America/Asuncion') into v_zona from public.empresas where id = p_empresa;
  v_fecha := coalesce(p_fecha, public.hoy_empresa(p_empresa));

  select coalesce(jsonb_object_agg(r.id::text, jsonb_build_object('rutina_id', ru.id, 'nombre', ru.nombre)),
                  '{}'::jsonb)
  into v_res
  from public.turnos_reserva r
  join public.rutinas ru on ru.cliente_id = r.cliente_id and ru.empresa_id = r.empresa_id
                        and ru.estado = 'vigente'
  where r.empresa_id = p_empresa
    and r.estado <> 'cancelada'
    and (r.inicia at time zone v_zona)::date = v_fecha;

  return v_res;
end $fn$;

revoke all on function public.rutinas_de_la_agenda(uuid, date) from public, anon;
grant execute on function public.rutinas_de_la_agenda(uuid, date) to authenticated;

-- ------------------------------------------------------------
-- 23. ELIMINAR UN CLIENTE (058), AHORA CON SU HISTORIA DE ENTRENAMIENTO
--
--    Copia exacta de la 058 —la versión viva; su cuerpo, sin comentarios,
--    da la misma huella— con lo marcado (098). Misma firma: se reemplaza
--    sin crear otra al lado.
--
--    Quien tiene rutinas, medidas o cargas anotadas se ARCHIVA. Sin esto el
--    DELETE chocaría con las claves NO ACTION de esas tablas y la persona
--    leería el engañoso «Eso hace referencia a algo que ya no existe». El
--    link y la ficha caen en cascada solo cuando se borra de verdad; al
--    archivar, el link se apaga y cambia de token (ver abajo por qué).
-- ------------------------------------------------------------
create or replace function public.eliminar_cliente(p_cliente uuid)
returns text language plpgsql security definer set search_path = public as $fn$
declare
  v       public.clientes;
  v_saldo numeric;
  v_debe  text;
begin
  select * into v from public.clientes where id = p_cliente;
  if v.id is null then
    raise exception 'Ese cliente ya no existe.' using errcode = 'P0002';
  end if;

  if not public.es_miembro(v.empresa_id) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if not public.es_admin(v.empresa_id) then
    raise exception 'Eliminar clientes es del dueño o de un administrador.' using errcode = '42501';
  end if;

  -- El mismo candado que al cobrar (056): mientras se decide, nadie le fía
  -- ni le cobra a este cliente.
  perform 1 from public.clientes where id = p_cliente for update;

  v_saldo := public.saldo_fiado(p_cliente);
  if v_saldo > 0 then
    -- «80.000» y no «80000.00»: esto lo lee una persona.
    v_debe := case when v_saldo = trunc(v_saldo)
                   then replace(to_char(v_saldo, 'FM999,999,999,990'), ',', '.')
                   else v_saldo::text end;
    raise exception '% todavía te debe %. Cobrale o borrá esa deuda desde Fiado, y después lo eliminás.',
      v.nombre, v_debe using errcode = '22023';
  end if;

  -- Sin nada atado se borra de verdad: no hay nada que conservar.
  if not exists (select 1 from public.fiado where cliente_id = p_cliente)
     and not exists (select 1 from public.movimientos where cliente_id = p_cliente)
     and not exists (select 1 from public.turnos_reserva where cliente_id = p_cliente)
     -- (098) Sus rutinas, sus medidas y cómo subieron sus cargas son su
     -- historia: con cualquiera de las tres, se archiva.
     and not exists (select 1 from public.rutinas where cliente_id = p_cliente)
     and not exists (select 1 from public.mediciones where cliente_id = p_cliente)
     and not exists (select 1 from public.cargas_historial where cliente_id = p_cliente) then
    delete from public.clientes where id = p_cliente;
    return 'borrado';
  end if;

  -- Con historia se archiva. La lista y el buscador ya dejan afuera a los
  -- archivados (052, 053); «lo que te deben» no, así que si alguna vez
  -- vuelve a deber algo, aparece ahí igual.
  update public.clientes set activo = false, updated_at = now() where id = p_cliente;

  -- (098) Su link se apaga y cambia de token. Apagado solo por estar
  -- archivado no alcanza: `guardar_cliente` (052) toma un teléfono repetido
  -- como la misma persona y reactiva la ficha, y con un teléfono compartido
  -- (madre e hijo, una pareja) el link que la otra persona tiene en su
  -- celular volvería a andar, a nombre de otra. Si vuelve la misma persona,
  -- el trainer prende el link y le manda el nuevo. `rutina_enlaces` no
  -- tiene el candado de cuenta vencida: esto anda siempre.
  update public.rutina_enlaces
  set activo = false, token = gen_random_uuid(), updated_at = now()
  where cliente_id = p_cliente;

  return 'archivado';
end $fn$;

revoke all on function public.eliminar_cliente(uuid) from public, anon;
grant execute on function public.eliminar_cliente(uuid) to authenticated;


-- ############################################################
-- ##  099_persona_por_telefono_y_borradores.sql
-- ############################################################

-- ============================================================
-- 099 · UNA PERSONA POR TELÉFONO, COPIAS EN PREPARACIÓN, Y LOS DATOS
--       DE SALUD AL ARCHIVAR
-- ============================================================
--
-- Sale de la revisión de las pantallas del módulo de rutinas (098), que
-- destapó tres cosas que la base hacía mal, o dejaba hacer.
--
-- 1. COPIAR A ALGUIEN SIN RUTINA LA DEJABA VIGENTE AL INSTANTE
--
--    «Usar para un cliente» desde una plantilla, «Copiar la de otro
--    cliente» o «Armar una nueva a partir de esta» desde las anteriores de
--    otro iban derecho a vigente si la persona no tenía rutina. Y si ya
--    tenía link —después de «Terminar», por ejemplo—, la veía antes de que
--    el trainer la revisara, con las notas de la otra persona adentro.
--    Ahora `copiar_rutina` acepta `p_borrador`: con él, la copia nace en
--    preparación («Próxima» en su carpeta) y nada llega al link hasta
--    «Activar la próxima». Sin cliente (una plantilla) no dice nada.
--    Y cuando al sacarle el nombre de la otra persona no queda nada
--    («Treino da Ana» → nada), el nombre de respaldo lo manda la pantalla
--    en su idioma (`p_nombre_vacio`): «Rutina» llegaba al link de un
--    cliente brasileño.
--
-- 2. AGENDAR A «LAURA» CON EL TELÉFONO DE «ANA» LE PISABA LA FICHA A ANA
--
--    Desde la 052 el teléfono es la identidad: un número repetido es la
--    misma persona, y la ficha se renombra y se reactiva. En un almacén o
--    una barbería está bien y no cambia. Con datos de entrenamiento no:
--    Laura heredaba las medidas, las lesiones, la rutina, la historia de
--    cargas y el consentimiento de Ana. Es una mezcla de datos de salud.
--    Ahora, si el nombre es otro y esa ficha tiene algo de entrenamiento
--    (rutinas, medidas, ficha o cargas), `guardar_cliente` se frena y dice
--    de quién es el número. Con el mismo nombre escrito de otra manera, o
--    sin nada de entrenamiento, todo sigue exactamente igual que hoy.
--    Si esa ficha está archivada no está en ninguna lista para elegirla:
--    el número queda libre, como en la rama con id de la 058, y la persona
--    nueva nace con su propia ficha sin heredar nada; la archivada conserva
--    sus rutinas y sus cargas por id.
--
-- 3. ARCHIVAR DEJABA LAS MEDIDAS Y LAS LESIONES SIN FORMA DE BORRARLAS
--
--    Una vez archivado, ninguna pantalla llega a su Progreso ni a su
--    ficha, así que sus medidas, su consentimiento y «Salud y lesiones»
--    quedaban guardados para siempre, sin manera de sacarlos (Ley
--    7593/2025). Ahora `eliminar_cliente`, al archivar, los borra en la
--    misma transacción. Las rutinas y cómo subieron sus cargas se
--    conservan: son el trabajo del trainer, no datos de salud, y no se ven
--    en ningún link (el link ya se apaga y cambia de token al archivar, por
--    la 098). Si la persona vuelve con el mismo nombre y el mismo teléfono,
--    vuelve a dar su consentimiento. Es para todos los rubros: en «Notas»
--    de una barbería también puede ir «es alérgica a…», y la pantalla lo
--    dice al eliminar («sus notas se borran»).
--
-- Cada función es copia exacta de su versión viva —leída de producción con
-- pg_get_functiondef y cotejada con la 052/058 (guardar_cliente) y la 098
-- (copiar_rutina, eliminar_cliente)— con lo marcado (099). `copiar_rutina`
-- cambia de firma, así que la vieja se borra antes: con las dos, la llamada
-- de cuatro argumentos sería ambigua. Las otras dos conservan la suya y se
-- reemplazan sin crear otra al lado. `activar_rutina` ya funciona sin una
-- vigente previa (pasa el borrador a vigente desde hoy y asegura el link):
-- no se toca, y se comprueba en pruebas/rutinas.test.js.
--
-- Los espacios raros de las expresiones regulares van escritos como
-- códigos (E'\u00A0') y no pegados: pegados, se volvían espacios comunes al
-- aplicar la migración (098).

-- ------------------------------------------------------------
-- 1. COPIAR UNA RUTINA, EN PREPARACIÓN SI SE PIDE
--
--    La firma vieja se va: si quedara, `copiar_rutina(e, o, c, true)`
--    coincidiría con las dos y PostgreSQL no sabría cuál llamar.
-- ------------------------------------------------------------
drop function if exists public.copiar_rutina(uuid, uuid, uuid, boolean);
drop function if exists public.copiar_rutina(uuid, uuid, uuid, boolean, boolean);

create or replace function public.copiar_rutina(
  p_empresa      uuid,
  p_origen       uuid,
  p_cliente      uuid default null,
  p_con_notas    boolean default true,
  p_borrador     boolean default false,
  p_nombre_vacio text default 'Rutina'
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_o         public.rutinas;
  v_estado    text;
  v_cliente   uuid;
  v_mismo     boolean;
  v_sin_notas boolean;
  v_pila      text;
  v_nombre    text;
  v_id        uuid;
  v_dia       public.rutina_dias;
  v_dia_id    uuid;
  v_token     uuid;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select * into v_o from public.rutinas where id = p_origen and empresa_id = p_empresa;
  if v_o.id is null then
    raise exception 'Esa rutina no existe.' using errcode = 'P0002';
  end if;

  v_estado := public.destino_nueva_rutina(p_empresa, p_cliente);

  -- (099) Si la persona no tiene rutina, la copia iba derecho a vigente y,
  -- con el link ya en su celular, la veía antes de que el trainer la
  -- revisara, con las notas de la otra persona. Con p_borrador nace en
  -- preparación y se activa desde su carpeta. Una plantilla no tiene link
  -- ni preparación: ahí p_borrador no dice nada. Y `destino_nueva_rutina`
  -- no mira si ya hay una en preparación cuando no hay vigente (ahí la
  -- nueva iba a ser la vigente), así que se mira acá, con el mensaje de
  -- siempre, antes de chocar con el índice de un borrador por cliente.
  if coalesce(p_borrador, false) and v_estado = 'vigente' then
    if exists (select 1 from public.rutinas where cliente_id = p_cliente and estado = 'borrador') then
      raise exception 'Este cliente ya tiene una próxima rutina en preparación: seguí con esa.'
        using errcode = '22023';
    end if;
    v_estado := 'borrador';
  end if;

  v_cliente := case when v_estado = 'plantilla' then null else p_cliente end;

  -- «Armar la próxima» (el mismo cliente) conserva todo.
  v_mismo := v_o.cliente_id is not null and v_cliente is not null and v_o.cliente_id = v_cliente;
  v_sin_notas := not v_mismo and not coalesce(p_con_notas, true);

  v_nombre := v_o.nombre;
  if v_o.cliente_id is not null and not v_mismo then
    -- El nombre ENTERO de la persona, no solo el de pila: «Rutina de Ana
    -- Ruiz» sin «Ana» dejaría «Rutina de Ruiz» en el link de Pedro.
    select nombre into v_pila from public.clientes where id = v_o.cliente_id;
    v_nombre := public.sin_nombre_de_persona(v_nombre, v_pila);
    -- Lo que quedó suelto: «Rutina ()», «Rutina ·  · piernas», «· fuerza»,
    -- y un «de» que se quedó sin la persona antes de un separador.
    v_nombre := regexp_replace(v_nombre, '\(\s*\)|\[\s*\]', ' ', 'g');
    -- Los espacios raros van escritos como códigos (E'\u00A0') y no pegados:
    -- pegados, se volvían espacios comunes al aplicar la migración.
    v_nombre := regexp_replace(v_nombre, E'[[:space:]\u00A0]+', ' ', 'g');
    v_nombre := regexp_replace(v_nombre, '\s*([·•|/,:;–—-])(\s*[·•|/,:;–—-])+\s*', ' \1 ', 'g');
    v_nombre := regexp_replace(v_nombre, '(^|\s)(de|del|da|do|das|dos|para|pra)\s+(?=[·•|/,:;–—-])', '\1', 'gi');
    v_nombre := btrim(v_nombre, ' ·•|/,:;–—-');
    -- Vacío, o colgando de una partícula («Fuerza de», «Treino da»): el
    -- nombre de respaldo. (099) Lo manda la pantalla en su idioma («Treino»
    -- en una cuenta en portugués): «Rutina» llegaba al link de un cliente
    -- brasileño. En blanco, «Rutina» como siempre; largo de más, se recorta.
    if v_nombre = '' or lower(v_nombre) ~ '(^|\s)(de|del|da|do|das|dos|para|pra)$' then
      v_nombre := btrim(left(btrim(coalesce(p_nombre_vacio, '')), 60));
      if v_nombre = '' then
        v_nombre := 'Rutina';
      end if;
    end if;
  end if;

  insert into public.rutinas (empresa_id, cliente_id, estado, nombre, notas, desde, semanas, origen_id, creado_por)
  values (p_empresa, v_cliente, v_estado, v_nombre,
          case when v_sin_notas then '' else v_o.notas end,
          case when v_estado = 'vigente' then public.hoy_empresa(p_empresa) end,
          v_o.semanas, v_o.id, auth.uid())
  returning id into v_id;

  for v_dia in select * from public.rutina_dias where rutina_id = v_o.id order by orden loop
    insert into public.rutina_dias (empresa_id, rutina_id, orden, nombre, notas)
    values (p_empresa, v_id, v_dia.orden, v_dia.nombre, case when v_sin_notas then '' else v_dia.notas end)
    returning id into v_dia_id;

    insert into public.rutina_ejercicios (empresa_id, dia_id, orden, ejercicio_id, series, reps, carga,
                                          descanso_seg, nota, junto_al_anterior)
    select p_empresa, v_dia_id, re.orden, re.ejercicio_id, re.series, re.reps, re.carga,
           re.descanso_seg, case when v_sin_notas then '' else re.nota end, re.junto_al_anterior
    from public.rutina_ejercicios re
    where re.dia_id = v_dia.id
    order by re.orden;
  end loop;

  if v_estado = 'vigente' then
    v_token := public.asegurar_enlace_rutina(p_empresa, v_cliente);
  end if;

  return jsonb_build_object('id', v_id, 'estado', v_estado, 'token', v_token);
end $fn$;

revoke all on function public.copiar_rutina(uuid, uuid, uuid, boolean, boolean, text) from public, anon;
grant execute on function public.copiar_rutina(uuid, uuid, uuid, boolean, boolean, text) to authenticated;

-- ------------------------------------------------------------
-- 2. GUARDAR UN CLIENTE: UN TELÉFONO ES DE UNA PERSONA
--
--    Misma firma que en la 052 y la 058: se reemplaza sin tocar a quien
--    ya la llama. El cuerpo es el de la 058 (la versión viva es esa, sin
--    los comentarios) con lo marcado (099).
-- ------------------------------------------------------------
create or replace function public.guardar_cliente(
  p_empresa  uuid,
  p_nombre   text,
  p_telefono text default '',
  p_notas    text default '',
  p_id       uuid default null
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_id     uuid;
  v_nombre text;
  v_tel    text;
  v_norm   text;
  v_otro   public.clientes;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  v_nombre := trim(coalesce(p_nombre, ''));
  if char_length(v_nombre) = 0 then
    raise exception 'Ponele un nombre, para saber de quién estamos hablando.' using errcode = '22023';
  end if;
  v_nombre := left(v_nombre, 80);

  v_tel  := left(trim(coalesce(p_telefono, '')), 40);
  v_norm := regexp_replace(v_tel, '\D', '', 'g');

  -- Un teléfono de dos dígitos no es un teléfono: es un dedazo. Se guarda
  -- vacío antes que guardar algo que después va a hacer chocar a dos
  -- personas distintas en el mismo índice.
  if v_norm <> '' and char_length(v_norm) < 6 then
    v_tel := '';
    v_norm := '';
  end if;

  if p_id is not null then
    -- (058) El número nuevo puede ser de otra ficha. Si esa ficha se
    -- eliminó, el número quedó libre: se le saca a la vieja, que conserva
    -- su historial por id. Si está activa, se dice de quién es, en vez del
    -- «ya existe algo con ese nombre» del índice único, que encima hablaba
    -- del nombre cuando el problema era el teléfono.
    if v_norm <> '' then
      select * into v_otro
      from public.clientes c
      where c.empresa_id = p_empresa and c.telefono_norm = v_norm and c.id <> p_id;

      if v_otro.id is not null then
        if v_otro.activo then
          raise exception 'Ese teléfono ya es de «%». Si son la misma persona, eliminá la ficha que sobra.',
            v_otro.nombre using errcode = '22023';
        end if;
        update public.clientes set telefono = '', updated_at = now() where id = v_otro.id;
      end if;
    end if;

    update public.clientes
    set nombre = v_nombre,
        telefono = v_tel,
        notas = left(coalesce(p_notas, ''), 1000),
        updated_at = now()
    where id = p_id and empresa_id = p_empresa
    returning id into v_id;

    if v_id is null then
      raise exception 'Ese cliente no es de esta cuenta.' using errcode = 'P0002';
    end if;
    return v_id;
  end if;

  -- Sin id: si el teléfono ya está, es la misma persona.
  if v_norm <> '' then
    select c.id into v_id
    from public.clientes c
    where c.empresa_id = p_empresa and c.telefono_norm = v_norm;

    if v_id is not null then
      -- (099) Salvo que sea OTRA persona y la ficha tenga datos de
      -- entrenamiento. «Laura» con el número de «Ana» renombraba la ficha
      -- de Ana, y Laura heredaba sus medidas, sus lesiones, su rutina, la
      -- historia de sus cargas y su consentimiento: una mezcla de datos de
      -- salud. Se comparan los nombres normalizados —minúsculas, sin
      -- tildes, espacios colapsados; `clave_ejercicio` (098) hace justo
      -- eso con cualquier texto— y, si son distintos y la ficha tiene
      -- rutinas, medidas, ficha de entrenamiento o cargas anotadas, se
      -- frena y se dice de quién es el número. Con el mismo nombre escrito
      -- de otra manera («ANA RUIZ», «Ana  Ruiz»), o sin nada de
      -- entrenamiento (la barbería, el almacén), sigue todo igual que
      -- siempre: se renombra, se reactiva, se conservan las notas.
      select * into v_otro from public.clientes where id = v_id;
      if public.clave_ejercicio(v_otro.nombre) <> public.clave_ejercicio(v_nombre)
         and (exists (select 1 from public.rutinas where cliente_id = v_id)
              or exists (select 1 from public.mediciones where cliente_id = v_id)
              or exists (select 1 from public.fichas_entreno where cliente_id = v_id)
              or exists (select 1 from public.cargas_historial where cliente_id = v_id)) then
        if v_otro.activo then
          raise exception 'Ese teléfono ya es de «%». Si es otra persona, dejá el teléfono vacío o elegila de la lista.',
            v_otro.nombre using errcode = '22023';
        end if;
        -- Archivada, no está en ninguna lista para «elegirla», y el número
        -- quedó libre, como en la rama con id (058): se le saca a la ficha
        -- archivada —que conserva sus rutinas y sus cargas por id— y la
        -- persona nueva nace abajo con su propia ficha, sin heredar nada.
        update public.clientes set telefono = '', updated_at = now() where id = v_otro.id;
      else
        update public.clientes
        set nombre = v_nombre,
            notas = case when trim(coalesce(p_notas, '')) = '' then notas
                         else left(p_notas, 1000) end,
            activo = true,
            updated_at = now()
        where id = v_id;
        return v_id;
      end if;
    end if;
  end if;

  insert into public.clientes (empresa_id, nombre, telefono, notas, creado_por)
  values (p_empresa, v_nombre, v_tel, left(coalesce(p_notas, ''), 1000), auth.uid())
  returning id into v_id;

  return v_id;
end $fn$;

revoke all on function public.guardar_cliente(uuid, text, text, text, uuid) from public, anon;
grant execute on function public.guardar_cliente(uuid, text, text, text, uuid) to authenticated;

-- ------------------------------------------------------------
-- 3. ELIMINAR UN CLIENTE: ARCHIVAR SE LLEVA SUS DATOS DE SALUD
--
--    Copia exacta de la 098 (la versión viva) con lo marcado (099), en la
--    rama que archiva. Devuelve lo mismo de siempre: 'borrado' o
--    'archivado'.
-- ------------------------------------------------------------
create or replace function public.eliminar_cliente(p_cliente uuid)
returns text language plpgsql security definer set search_path = public as $fn$
declare
  v       public.clientes;
  v_saldo numeric;
  v_debe  text;
begin
  select * into v from public.clientes where id = p_cliente;
  if v.id is null then
    raise exception 'Ese cliente ya no existe.' using errcode = 'P0002';
  end if;

  if not public.es_miembro(v.empresa_id) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if not public.es_admin(v.empresa_id) then
    raise exception 'Eliminar clientes es del dueño o de un administrador.' using errcode = '42501';
  end if;

  -- El mismo candado que al cobrar (056): mientras se decide, nadie le fía
  -- ni le cobra a este cliente.
  perform 1 from public.clientes where id = p_cliente for update;

  v_saldo := public.saldo_fiado(p_cliente);
  if v_saldo > 0 then
    -- «80.000» y no «80000.00»: esto lo lee una persona.
    v_debe := case when v_saldo = trunc(v_saldo)
                   then replace(to_char(v_saldo, 'FM999,999,999,990'), ',', '.')
                   else v_saldo::text end;
    raise exception '% todavía te debe %. Cobrale o borrá esa deuda desde Fiado, y después lo eliminás.',
      v.nombre, v_debe using errcode = '22023';
  end if;

  -- Sin nada atado se borra de verdad: no hay nada que conservar.
  if not exists (select 1 from public.fiado where cliente_id = p_cliente)
     and not exists (select 1 from public.movimientos where cliente_id = p_cliente)
     and not exists (select 1 from public.turnos_reserva where cliente_id = p_cliente)
     -- (098) Sus rutinas, sus medidas y cómo subieron sus cargas son su
     -- historia: con cualquiera de las tres, se archiva.
     and not exists (select 1 from public.rutinas where cliente_id = p_cliente)
     and not exists (select 1 from public.mediciones where cliente_id = p_cliente)
     and not exists (select 1 from public.cargas_historial where cliente_id = p_cliente) then
    delete from public.clientes where id = p_cliente;
    return 'borrado';
  end if;

  -- Con historia se archiva. La lista y el buscador ya dejan afuera a los
  -- archivados (052, 053); «lo que te deben» no, así que si alguna vez
  -- vuelve a deber algo, aparece ahí igual.
  update public.clientes set activo = false, updated_at = now() where id = p_cliente;

  -- (099) Archivado, ninguna pantalla llega a su Progreso ni a su ficha,
  -- así que sus medidas, su consentimiento y «Salud y lesiones» quedaban
  -- guardados sin forma de borrarlos (Ley 7593/2025). Se van acá, en la
  -- misma transacción. Las rutinas y cómo subieron sus cargas se quedan:
  -- son el trabajo del trainer, no datos de salud, y no se ven en ningún
  -- link. Si la persona vuelve con el mismo nombre y teléfono, vuelve a dar
  -- su consentimiento. Los candados de cuenta vencida (098) son de insert
  -- y update, y `clientes` no tiene uno: esto anda siempre, como el link.
  delete from public.mediciones where cliente_id = p_cliente;
  delete from public.fichas_entreno where cliente_id = p_cliente;
  update public.clientes set notas = '' where id = p_cliente;

  -- (098) Su link se apaga y cambia de token. Apagado solo por estar
  -- archivado no alcanza: `guardar_cliente` (052) toma un teléfono repetido
  -- como la misma persona y reactiva la ficha, y con un teléfono compartido
  -- (madre e hijo, una pareja) el link que la otra persona tiene en su
  -- celular volvería a andar, a nombre de otra. Si vuelve la misma persona,
  -- el trainer prende el link y le manda el nuevo. `rutina_enlaces` no
  -- tiene el candado de cuenta vencida: esto anda siempre.
  update public.rutina_enlaces
  set activo = false, token = gen_random_uuid(), updated_at = now()
  where cliente_id = p_cliente;

  return 'archivado';
end $fn$;

revoke all on function public.eliminar_cliente(uuid) from public, anon;
grant execute on function public.eliminar_cliente(uuid) to authenticated;


-- ############################################################
-- ##  100_campanas.sql
-- ############################################################

-- ============================================================
-- 100 · CAMPAÑAS, COSECHAS Y LIQUIDACIONES: AGRICULTURA, FASE 1
-- ============================================================
--
-- La 044 dejó el lote: algo que se abre, junta plata durante meses y recién
-- al cerrar dice si ganaste. Para el ganadero alcanzaba. Para el sojero
-- —el que mira Orden desde la camioneta, entre el silo y la cooperativa—
-- faltaban tres cosas que la plata sola no cuenta:
--
--   · CUÁNTO SEMBRÓ. Sin hectáreas no hay «cuánto me sale la hectárea» ni
--     «cuántos kilos necesito para cubrir», que son las dos preguntas que
--     se hace todos los días de la campaña.
--   · CUÁNTO COSECHÓ. Los kilos entran al silo semanas antes de que haya
--     un peso. Un ticket de balanza no es una venta: es un camión.
--   · CÓMO LE PAGARON. La cooperativa liquida en UN papel: bruto por los
--     kilos, menos secado, menos flete, menos lo que le fió a cosecha, menos
--     el alquiler en kilos del dueño del campo… y el banco acredita el neto.
--     Ese papel toca la caja, la campaña y las deudas al mismo tiempo, y
--     tiene que cuadrar peso por peso o no sirve.
--
-- LAS DECISIONES (CONTRATO-100, §1; no se re-discuten)
--
--   1. La caja sigue siendo de caja. Un insumo «a cosecha» nace como DEUDA
--      atada a la campaña, sin gasto. El gasto nace cuando se paga —a mano
--      o porque el silo lo compensó en la liquidación— con la categoría y la
--      campaña de la deuda. `billetera()`, `resumen_financiero`, el año y el
--      Excel no cambian.
--   2. Una sola moneda de datos por negocio (`empresas.moneda`). Si pagó o
--      cobró en otra, `monto` va convertido y se guardan `monto_original`,
--      `moneda_original` y `cambio` (cuántas unidades de la moneda propia
--      vale 1 de la original). Sin valuación histórica ni dólar de
--      referencia: la vista de la 051 sigue siendo la forma de mirar todo al
--      cambio de hoy.
--   3. Un solo «Resultado»: `cobrado − puesto`, la regla de la 045. El
--      renglón «si pagás lo que debés a cosecha» es `resultado − a_cosecha`
--      y se dibuja en la pantalla; acá nunca hay dos números con el mismo
--      nombre.
--   4. Nada sin señal. `registrar_cosecha` y `registrar_liquidacion`
--      aceptan un id (o un `grupo_id`) generado en el celular: el reintento
--      devuelve lo mismo y no duplica.
--   5. La liquidación es por socio: un papel puede juntar kilos de dos
--      campañas. `p_partes` trae una parte por campaña; cada parte es una
--      fila de `liquidaciones` con el mismo `grupo_id`, en UNA transacción.
--      Anular es anular el grupo entero.
--   6. Vínculo por columna: `movimientos.liquidacion_id` y
--      `pagos_deuda.liquidacion_id`. El historial dice «parte de la
--      liquidación del 12/04» y no deja editar ni anular suelto.
--   7. Un pago parcial de una deuda con campaña NO corre `vence_el`: el
--      «a cosecha» vence cuando vence la cosecha, no un mes después de cada
--      compensación.
--   8. Un ingreso «Préstamo» o «Aporte» colgado de una campaña no cuenta en
--      `cobrado`: es plata prestada, no plata que la campaña dio.
--   9. `kg_netos` = «kilos que te acreditaron»; `kg_brutos` = «peso de
--      balanza». Sin tabla de merma.
--  10. Neto cero sin cuenta está permitido (canje puro: entregué kilos para
--      pagar el alquiler). Neto negativo se rechaza: la pantalla topa lo
--      compensado al bruto y lo que falte sigue como deuda.
--  11. `borrar_lote` no cambia su conteo de anulados (la FK sin `on delete`
--      frenaría el delete igual); lo que sí frena son cosechas,
--      liquidaciones y deudas, con un mensaje que se entiende.
--  12. `registrar_venta` no cambia de firma: desde Vender, la campaña se
--      asigna después con `asignar_a_lote`.
--
-- QUIÉN VE QUÉ (015, 045 y 047, juntas)
--
-- La 045 decidió que `puesto`, `cobrado` y `resultado` los ve todo miembro:
-- son sumas de montos que la 003 ya le deja ver de a uno, y `lotes.test.js`
-- lo comprueba («el peón que carga el balanceado ve lo mismo»). Esa regla
-- se mantiene tal cual. Lo que ESTA migración agrega —cuánto se debe a
-- cosecha y todo lo que se deriva de eso— es de administración, como las
-- deudas desde la 015: para un miembro que no es admin, `numeros_de_lote`
-- devuelve null en `a_cosecha`, `costo`, `costo_ha`, `costo_ton`,
-- `kg_ha_para_cubrir`, `falta_cubrir` y `kg_para_cubrir`; `resumen_lote` le
-- da `deudas = null` y `estructura = null`, filtra los movimientos con la
-- regla de la 047 (`v_admin or tipo = 'venta' or creado_por = auth.uid()`)
-- y en cada liquidación le tapa `descuentos`, `compensado` y
-- `pagado_con_grano`. Kilos, rendimiento, vendido y precio promedio sí se
-- ven: las ventas son de todos.
--
-- CÓMO ESTÁ ARMADO
--
-- `lotes` gana cultivo, campaña, hectáreas y precio esperado; una fila
-- sigue siendo UNA campaña de un lote físico (comparar zafra contra zafra =
-- agrupar por nombre). `cosechas` es un ticket por camión, kilos sin plata.
-- `liquidaciones` es una venta de grano de UNA campaña: apunta a la venta
-- (por el bruto) y guarda cómo se repartió el papel. Las fórmulas viven en
-- un solo lugar, `numeros_de_lote`, que llaman `listar_lotes` y
-- `resumen_lote`.
--
-- La venta de una liquidación se inserta DIRECTO y no con
-- `registrar_venta`: sus items redondean el precio unitario a 2 decimales,
-- y US$ 0,415 el kilo se volvería 0,42. Se rellenan todas las columnas que
-- `registrar_venta` rellena; los triggers de la 074 (cuenta) y
-- `exigir_cuenta_activa` corren solos.
--
-- LAS REGLAS DE SIEMPRE
--
-- Todo idempotente (`pruebas/migracion.test.js` aplica dos veces). Toda
-- función `security definer set search_path = public`, primera línea
-- `es_miembro`/`es_admin`. Claves compuestas `(x_id, empresa_id)` en toda
-- FK que cruce tablas, el candado de la 044/052: una fila de un negocio no
-- puede apuntar a la de otro ni con un UPDATE a mano. Nadie escribe lotes,
-- cosechas, liquidaciones, deudas ni pagos directo. Las funciones
-- redefinidas son copia exacta de su definición viva en producción
-- (verificada con `pg_get_functiondef` el 23/09/2026) más lo nuevo; las que
-- cambian de firma borran la vieja antes (patrón 096).

-- ------------------------------------------------------------
-- 1. LA CAMPAÑA: QUÉ SE SEMBRÓ, CUÁNTO Y A QUÉ PRECIO SE ESPERA
--
--    `unidad`/`cantidad` quedan como están (ganadería: cabezas). Cuando se
--    abre con hectáreas y sin unidad, `guardar_lote` escribe `unidad = 'ha'`
--    y `cantidad = hectareas`, así el `por_unidad` de siempre es «por
--    hectárea» y ganadería no cambia. `precio_esperado` es por TONELADA, en
--    `empresas.moneda`, sin valor por defecto: envejece en un mes.
-- ------------------------------------------------------------
alter table public.lotes
  add column if not exists cultivo         text not null default '' check (char_length(cultivo) <= 40),
  add column if not exists campana         text not null default '' check (char_length(campana) <= 40),
  add column if not exists hectareas       numeric(10,2) check (hectareas is null or (hectareas > 0 and hectareas <= 50000)),
  add column if not exists precio_esperado numeric(14,2) check (precio_esperado is null or precio_esperado >= 0);

create index if not exists lotes_cultivo_idx on public.lotes (empresa_id, lower(cultivo));

-- La 044 dio `grant select` sobre la tabla entera: las columnas nuevas
-- entran solas.

-- ------------------------------------------------------------
-- 2. EL MOVIMIENTO: EN QUÉ MONEDA VINO, CON QUIÉN SE REPARTE, DE QUÉ PAPEL ES
--
--    `cambio` son unidades de la moneda propia por 1 de la original;
--    `monto = round(monto_original × cambio, 2)`. Los tres van juntos o
--    ninguno. `reparto_id`: un gasto repartido entre campañas por hectáreas
--    son N inserts con el mismo id, y se anulan juntos. `liquidacion_id`:
--    la venta o el gasto que nació dentro de una liquidación; su FK se
--    agrega en 6, después de crear la tabla.
-- ------------------------------------------------------------
alter table public.movimientos
  add column if not exists monto_original  numeric(14,2)  check (monto_original is null or monto_original >= 0),
  add column if not exists moneda_original text           check (moneda_original is null or moneda_original in ('PYG','USD','BRL','ARS','EUR')),
  add column if not exists cambio          numeric(24,10) check (cambio is null or cambio > 0),
  add column if not exists reparto_id      uuid,
  add column if not exists liquidacion_id  uuid;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'movimiento_original_coherente') then
    alter table public.movimientos
      add constraint movimiento_original_coherente check (
        (monto_original is null) = (moneda_original is null)
        and (moneda_original is null) = (cambio is null));
  end if;
end $$;

-- La clave que permite que `liquidaciones` apunte a la venta con la llave
-- compuesta. No existía: el único unique de `movimientos` era el `id`.
create unique index if not exists movimientos_id_empresa_idx on public.movimientos (id, empresa_id);
create index if not exists movimientos_reparto_idx     on public.movimientos (reparto_id)     where reparto_id is not null;
create index if not exists movimientos_liquidacion_idx on public.movimientos (liquidacion_id) where liquidacion_id is not null;

-- La 003 revocó el select total y lo devolvió columna por columna: columna
-- nueva = grant nuevo (como la 044 con `lote_id`).
grant select (monto_original, moneda_original, cambio, reparto_id, liquidacion_id) on public.movimientos to authenticated;

-- La policy de insert, EXACTA como está viva (032) más `liquidacion_id is
-- null`: nadie se inventa desde el celular una venta «parte de una
-- liquidación». `reparto_id`, `monto_original`, `moneda_original` y
-- `cambio` sí los manda la pantalla en el insert directo.
drop policy if exists movimientos_insert on public.movimientos;
create policy movimientos_insert on public.movimientos
  for insert with check (
    public.es_miembro(empresa_id)
    and tipo <> 'venta'
    and estado = 'activo'
    and creado_por = auth.uid()
    and descuento = 0
    and costo_total = 0
    and subtotal = monto
    and anulado_por is null
    and anulado_at is null
    and fecha >= date '2000-01-01'
    and fecha <= (public.hoy_empresa(empresa_id) + 1)
    and liquidacion_id is null
  );

-- ------------------------------------------------------------
-- 3. LA DEUDA «A COSECHA»: QUÉ CAMPAÑA LA PAGA Y QUÉ GASTO NACE AL PAGARLA
--
--    `categoria` es la del gasto que nace al pagarla ('' = 'Deudas', como
--    siempre). `pagos_deuda.liquidacion_id`: el pago que hizo el silo al
--    compensar; su FK va en 6. La columna de «activa/archivada» de `deudas`
--    se llama `activa` (015) y se usa igual en todas las consultas nuevas.
-- ------------------------------------------------------------
alter table public.deudas
  add column if not exists lote_id   uuid,
  add column if not exists categoria text not null default '' check (char_length(categoria) <= 60);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'deudas_lote_fk') then
    alter table public.deudas
      add constraint deudas_lote_fk
      foreign key (lote_id, empresa_id) references public.lotes (id, empresa_id);
  end if;
end $$;

create index if not exists deudas_lote_idx on public.deudas (lote_id) where lote_id is not null;

alter table public.pagos_deuda
  add column if not exists liquidacion_id uuid;

-- `deudas` y `pagos_deuda` tienen `grant select` sobre la tabla entera
-- (015): las columnas nuevas entran solas.

-- ------------------------------------------------------------
-- 4. LA COSECHA: UN TICKET DE BALANZA POR CAMIÓN, KILOS SIN PLATA
--
--    No se valida el rendimiento en SQL (la caña da 56.000 kg/ha); los
--    avisos de rango son de pantalla. Se escribe solo por funciones.
-- ------------------------------------------------------------
create table if not exists public.cosechas (
  id         uuid primary key default gen_random_uuid(),
  empresa_id uuid not null references public.empresas (id) on delete cascade,
  lote_id    uuid not null,
  fecha      date not null,
  -- Kilos que le acreditaron.
  kg_netos   numeric(12,0) not null check (kg_netos > 0 and kg_netos <= 5000000),
  -- Peso de balanza (camión − tara).
  kg_brutos  numeric(12,0) check (kg_brutos is null or kg_brutos >= kg_netos),
  humedad    numeric(4,1) check (humedad is null or humedad between 5 and 40),
  destino    text not null default '' check (char_length(destino) <= 80),
  ticket     text not null default '' check (char_length(ticket) <= 40),
  notas      text not null default '' check (char_length(notas) <= 300),
  creado_por uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  constraint cosechas_lote_fk foreign key (lote_id, empresa_id) references public.lotes (id, empresa_id),
  constraint cosechas_id_empresa unique (id, empresa_id)
);

create index if not exists cosechas_lote_idx on public.cosechas (lote_id, fecha desc);

alter table public.cosechas enable row level security;

drop policy if exists cosechas_select on public.cosechas;
create policy cosechas_select on public.cosechas
  for select to authenticated using (public.es_miembro(empresa_id));

revoke all on public.cosechas from anon, authenticated;
grant select on public.cosechas to authenticated;

drop trigger if exists cuenta_activa_cosechas on public.cosechas;
create trigger cuenta_activa_cosechas
  before insert or update on public.cosechas
  for each row execute function public.exigir_cuenta_activa();

-- ------------------------------------------------------------
-- 5. LA LIQUIDACIÓN: UNA VENTA DE GRANO DE UNA CAMPAÑA
--
--    Un papel = un `grupo_id` con 1..10 filas. `movimiento_id` es la venta,
--    por el BRUTO. `descuentos` es la suma de los gastos que creó (secado,
--    flete, retención…), `compensado` la de los pagos de deudas que el silo
--    se cobró, `pagado_con_grano` el alquiler en kilos u otro gasto que
--    pagó el grano, y `neto` lo que acreditó el banco (0 en un canje puro).
--    `liquidacion_cuadra` no deja guardar un papel que no cierra.
-- ------------------------------------------------------------
create table if not exists public.liquidaciones (
  id               uuid primary key default gen_random_uuid(),
  empresa_id       uuid not null references public.empresas (id) on delete cascade,
  -- El papel; lo genera el celular (idempotencia).
  grupo_id         uuid not null,
  lote_id          uuid not null,
  fecha            date not null,
  movimiento_id    uuid not null,
  comprador        text not null default '' check (char_length(comprador) <= 80),
  kg               numeric(12,0) not null check (kg > 0),
  -- En empresas.moneda, por tonelada.
  precio_tonelada  numeric(14,4) not null check (precio_tonelada >= 0),
  -- round(kg × precio_tonelada / 1000, 2)
  bruto            numeric(14,2) not null check (bruto >= 0),
  descuentos       numeric(14,2) not null default 0 check (descuentos >= 0),
  compensado       numeric(14,2) not null default 0 check (compensado >= 0),
  pagado_con_grano numeric(14,2) not null default 0 check (pagado_con_grano >= 0),
  neto             numeric(14,2) not null check (neto >= 0),
  cuenta_id        uuid references public.cuentas_dinero (id) on delete set null,
  moneda_original  text check (moneda_original is null or moneda_original in ('PYG','USD','BRL','ARS','EUR')),
  -- Como venía en el papel.
  precio_original  numeric(14,4) check (precio_original is null or precio_original >= 0),
  cambio           numeric(24,10) check (cambio is null or cambio > 0),
  estado           text not null default 'activa' check (estado in ('activa', 'anulada')),
  anulada_por      uuid references auth.users (id) on delete set null,
  anulada_at       timestamptz,
  notas            text not null default '' check (char_length(notas) <= 300),
  creado_por       uuid references auth.users (id) on delete set null,
  created_at       timestamptz not null default now(),
  constraint liquidacion_original_coherente check (
    (moneda_original is null) = (precio_original is null)
    and (moneda_original is null) = (cambio is null)),
  constraint liquidaciones_lote_fk foreign key (lote_id, empresa_id) references public.lotes (id, empresa_id),
  constraint liquidaciones_mov_fk  foreign key (movimiento_id, empresa_id) references public.movimientos (id, empresa_id),
  constraint liquidaciones_id_empresa unique (id, empresa_id),
  constraint liquidacion_cuadra check (abs(bruto - descuentos - compensado - pagado_con_grano - neto) < 0.01),
  constraint liquidacion_anulada_coherente check ((estado = 'anulada') = (anulada_at is not null))
);

create index if not exists liquidaciones_lote_idx on public.liquidaciones (lote_id, fecha desc);
-- ÚNICO por (grupo, campaña): «cada campaña una sola vez en el papel» lo
-- hace cumplir la base, y de paso frena el doble toque sin señal. Dos
-- llamadas a `registrar_liquidacion` con el mismo `p_grupo` que llegan al
-- mismo tiempo pasan las dos el `exists` de la idempotencia; con este
-- índice la segunda espera a la primera y falla con unique_violation en
-- vez de insertar el papel dos veces, y el reintento siguiente ya entra por
-- la rama idempotente. Sirve también para buscar por grupo.
drop index if exists public.liquidaciones_grupo_idx;
create unique index if not exists liquidaciones_grupo_lote_idx on public.liquidaciones (grupo_id, lote_id);

alter table public.liquidaciones enable row level security;

drop policy if exists liquidaciones_select on public.liquidaciones;
create policy liquidaciones_select on public.liquidaciones
  for select to authenticated using (public.es_miembro(empresa_id));

-- Grant por columnas, como hace la 003 con `movimientos`: la policy deja
-- leer la fila a todo miembro, pero `descuentos`, `compensado` y
-- `pagado_con_grano` son de administración (decisión 6) y por PostgREST
-- no se pueden pedir. `resumen_lote` es definer: las lee y las tapa según
-- el rol.
revoke all on public.liquidaciones from anon, authenticated;
grant select (
  id, empresa_id, grupo_id, lote_id, fecha, movimiento_id, comprador, kg, precio_tonelada, bruto, neto,
  cuenta_id, moneda_original, precio_original, cambio, estado, anulada_por, anulada_at, notas, creado_por, created_at
) on public.liquidaciones to authenticated;

drop trigger if exists cuenta_activa_liquidaciones on public.liquidaciones;
create trigger cuenta_activa_liquidaciones
  before insert or update on public.liquidaciones
  for each row execute function public.exigir_cuenta_activa();

-- ------------------------------------------------------------
-- 6. LAS LLAVES DE VUELTA: DEL MOVIMIENTO Y DEL PAGO A SU LIQUIDACIÓN
--
--    Compuestas y sin `on delete`: una liquidación con plata colgada no se
--    borra, se anula. Borrar la empresa entera sigue andando: las llaves
--    son NO ACTION, se controlan al final de la sentencia y para entonces
--    ya no queda ninguna de las dos puntas.
-- ------------------------------------------------------------
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'movimientos_liquidacion_fk') then
    alter table public.movimientos
      add constraint movimientos_liquidacion_fk
      foreign key (liquidacion_id, empresa_id) references public.liquidaciones (id, empresa_id);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'pagos_deuda_liquidacion_fk') then
    alter table public.pagos_deuda
      add constraint pagos_deuda_liquidacion_fk
      foreign key (liquidacion_id, empresa_id) references public.liquidaciones (id, empresa_id);
  end if;
end $$;

create index if not exists pagos_deuda_liquidacion_idx on public.pagos_deuda (liquidacion_id) where liquidacion_id is not null;

-- ------------------------------------------------------------
-- 7. LA COTIZACIÓN CON MÁS DECIMALES
--
--    Un negocio en dólares que mira en guaraníes guarda 1/6000: con seis
--    decimales (051) pierde un 0,2 %. `guardar_vista_moneda` no cambia de
--    firma; se verificó en producción que ninguna vista ni regla depende
--    del tipo (la constraint `vista_con_cotizacion` se reevalúa sola).
-- ------------------------------------------------------------
do $$
begin
  if exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'empresas' and column_name = 'cotizacion'
      and numeric_scale is distinct from 10
  ) then
    alter table public.empresas alter column cotizacion type numeric(24,10);
  end if;
end $$;

-- ------------------------------------------------------------
-- 8. LOS NÚMEROS DE UNA CAMPAÑA, EN UN SOLO LUGAR
--
--    Interna: la llaman `listar_lotes` y `resumen_lote`, que ya miraron el
--    rol. Todas las claves están siempre; null donde no aplica o donde no
--    corresponde verlo (ver la cabecera). Montos a 2 decimales, kilos a 0,
--    kg/ha y precios por tonelada a 2.
--
--    `kg_vendidos` cuenta solo liquidaciones activas cuya venta sigue
--    activa: si alguien anuló la venta desde el historial, los kilos vuelven
--    al silo solos, igual que la plata.
-- ------------------------------------------------------------
create or replace function public.numeros_de_lote(p_lote uuid, p_admin boolean)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_l           public.lotes;
  v_admin       boolean := coalesce(p_admin, false);
  v_movs        integer;
  v_puesto      numeric;
  v_cobrado     numeric;
  v_a_cosecha   numeric;
  v_kg_cos      numeric;
  v_kg_vend     numeric;
  v_vendido     numeric;
  v_resultado   numeric;
  v_costo       numeric;
  v_costo_ha    numeric;
  v_precio_prom numeric;
  v_precio_ref  numeric;
  v_falta       numeric;
begin
  select * into v_l from public.lotes where id = p_lote;

  select count(*)::int,
         coalesce(sum(m.monto) filter (where m.tipo = 'gasto'), 0),
         -- Un préstamo o un aporte colgado de la campaña es plata prestada,
         -- no plata que la campaña dio (decisión 8). Son los nombres exactos
         -- que guarda PantallaGastos en sus chips de ingreso.
         coalesce(sum(m.monto) filter (where m.tipo = 'venta'
                                          or (m.tipo = 'ingreso' and m.categoria not in ('Préstamo', 'Aporte'))), 0)
  into v_movs, v_puesto, v_cobrado
  from public.movimientos m
  where m.lote_id = p_lote and m.estado = 'activo';

  select coalesce(sum(d.saldo), 0) into v_a_cosecha
  from public.deudas d
  where d.lote_id = p_lote and d.activa and d.saldo > 0;

  select coalesce(sum(c.kg_netos), 0) into v_kg_cos
  from public.cosechas c where c.lote_id = p_lote;

  select coalesce(sum(q.kg), 0), coalesce(sum(q.bruto), 0) into v_kg_vend, v_vendido
  from public.liquidaciones q
  join public.movimientos m on m.id = q.movimiento_id
  where q.lote_id = p_lote and q.estado = 'activa' and m.estado = 'activo';

  v_resultado   := v_cobrado - v_puesto;
  v_costo       := v_puesto + v_a_cosecha;
  v_costo_ha    := case when v_l.hectareas > 0 then round(v_costo / v_l.hectareas, 2) end;
  v_precio_prom := case when v_kg_vend > 0 then round(v_vendido / v_kg_vend * 1000, 2) end;
  v_precio_ref  := coalesce(v_precio_prom, v_l.precio_esperado);
  v_falta       := greatest(v_costo - v_cobrado, 0);

  return jsonb_build_object(
    'movimientos',      v_movs,
    'puesto',           v_puesto,
    'cobrado',          v_cobrado,
    'resultado',        v_resultado,
    'por_unidad',       case when v_l.cantidad > 0 then round(v_resultado / v_l.cantidad, 2) end,
    'a_cosecha',        case when v_admin then v_a_cosecha end,
    'costo',            case when v_admin then v_costo end,
    'costo_ha',         case when v_admin then v_costo_ha end,
    'resultado_ha',     case when v_l.hectareas > 0 then round(v_resultado / v_l.hectareas, 2) end,
    'kg_cosechados',    v_kg_cos,
    'kg_vendidos',      v_kg_vend,
    -- Puede ser negativo (vendió más de lo que cargó como cosecha): la
    -- pantalla lo dice.
    'kg_sin_vender',    v_kg_cos - v_kg_vend,
    'vendido',          v_vendido,
    'precio_promedio',  v_precio_prom,
    'precio_ref',       v_precio_ref,
    'rendimiento',      case when v_l.hectareas > 0 and v_kg_cos > 0 then round(v_kg_cos / v_l.hectareas, 2) end,
    'costo_ton',        case when v_admin and v_kg_cos > 0 then round(v_costo / (v_kg_cos / 1000), 2) end,
    'kg_ha_para_cubrir', case when v_admin and v_costo_ha is not null and v_precio_ref > 0
                              then round(v_costo_ha / v_precio_ref * 1000, 2) end,
    'falta_cubrir',     case when v_admin then v_falta end,
    'kg_para_cubrir',   case when v_admin and v_precio_ref > 0 then round(v_falta / v_precio_ref * 1000, 0) end
  );
end $fn$;

revoke all on function public.numeros_de_lote(uuid, boolean) from public, anon, authenticated;

-- ------------------------------------------------------------
-- 9. ABRIR Y EDITAR, AHORA CON CULTIVO, CAMPAÑA, HECTÁREAS Y PRECIO
--
--    Copia exacta de la 044 más las cuatro columnas. Con un parámetro más,
--    `create or replace` dejaría la vieja al lado y toda llamada sería
--    ambigua: se borra antes (096).
-- ------------------------------------------------------------
drop function if exists public.guardar_lote(uuid, text, text, numeric, text, uuid, date);

create or replace function public.guardar_lote(
  p_empresa         uuid,
  p_nombre          text,
  p_unidad          text default '',
  p_cantidad        numeric default 0,
  p_notas           text default '',
  p_id              uuid default null,
  p_abierto         date default null,
  p_cultivo         text default '',
  p_campana         text default '',
  p_hectareas       numeric default null,
  p_precio_esperado numeric default null
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_id       uuid;
  v_rubro    text;
  v_unidad   text;
  v_cantidad numeric;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo administración maneja los lotes.' using errcode = '42501';
  end if;

  if char_length(trim(coalesce(p_nombre, ''))) = 0 then
    raise exception 'El lote necesita un nombre.' using errcode = '22023';
  end if;
  if coalesce(p_cantidad, 0) < 0 then
    raise exception 'La cantidad no puede ser negativa.' using errcode = '22023';
  end if;
  if p_hectareas is not null and p_hectareas <= 0 then
    raise exception 'Las hectáreas tienen que ser más que cero.' using errcode = '22023';
  end if;
  if p_precio_esperado is not null and p_precio_esperado < 0 then
    raise exception 'El precio esperado no puede ser negativo.' using errcode = '22023';
  end if;

  -- Sin hectáreas no hay costo por hectárea ni kilos para cubrir: en
  -- agricultura son obligatorias. Ganadería y el resto siguen como siempre.
  select rubro into v_rubro from public.empresas where id = p_empresa;
  if v_rubro = 'agricultura' and p_hectareas is null then
    raise exception 'Decinos cuántas hectáreas tiene.' using errcode = '22023';
  end if;

  -- Con hectáreas y sin unidad, la unidad ES la hectárea: así `por_unidad`
  -- de siempre es «por hectárea» sin tocar ganadería.
  v_unidad   := left(trim(coalesce(p_unidad, '')), 20);
  v_cantidad := coalesce(p_cantidad, 0);
  if p_hectareas is not null and v_unidad = '' and v_cantidad = 0 then
    v_unidad   := 'ha';
    v_cantidad := p_hectareas;
  end if;

  if p_id is null then
    insert into public.lotes (empresa_id, nombre, unidad, cantidad, notas, abierto_el, creado_por,
                              cultivo, campana, hectareas, precio_esperado)
    values (
      p_empresa, trim(p_nombre), v_unidad,
      v_cantidad, left(coalesce(p_notas, ''), 500),
      coalesce(p_abierto, public.hoy_empresa(p_empresa)), auth.uid(),
      left(trim(coalesce(p_cultivo, '')), 40), left(trim(coalesce(p_campana, '')), 40),
      p_hectareas, p_precio_esperado
    )
    returning id into v_id;
  else
    update public.lotes set
      nombre          = trim(p_nombre),
      unidad          = v_unidad,
      cantidad        = v_cantidad,
      notas           = left(coalesce(p_notas, ''), 500),
      abierto_el      = coalesce(p_abierto, abierto_el),
      cultivo         = left(trim(coalesce(p_cultivo, '')), 40),
      campana         = left(trim(coalesce(p_campana, '')), 40),
      hectareas       = p_hectareas,
      precio_esperado = p_precio_esperado
    where id = p_id and empresa_id = p_empresa
    returning id into v_id;

    if v_id is null then
      raise exception 'Ese lote no existe.' using errcode = 'P0002';
    end if;
  end if;

  return v_id;
end $fn$;

-- ------------------------------------------------------------
-- 10. LA LISTA
--
--    Copia exacta de la 045 más las columnas nuevas y los números de
--    `numeros_de_lote`, que pisan puesto/cobrado/resultado/por_unidad con
--    los mismos valores (o con el rol mirado, para lo nuevo).
-- ------------------------------------------------------------
create or replace function public.listar_lotes(
  p_empresa           uuid,
  p_incluir_cerrados  boolean default false
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_res jsonb; v_hoy date; v_admin boolean;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  v_hoy   := public.hoy_empresa(p_empresa);
  v_admin := public.es_admin(p_empresa);

  select coalesce(jsonb_agg(x order by x->>'estado', (x->>'abierto_el') desc), '[]'::jsonb)
  into v_res
  from (
    select jsonb_build_object(
      'id',         l.id,
      'nombre',     l.nombre,
      'unidad',     l.unidad,
      'cantidad',   l.cantidad,
      'estado',     l.estado,
      'abierto_el', l.abierto_el,
      'cerrado_el', l.cerrado_el,
      'notas',      l.notas,
      -- Cuánto lleva en curso, o cuánto duró si ya cerró.
      'dias',        (coalesce(l.cerrado_el, v_hoy) - l.abierto_el),
      'movimientos', coalesce(c.movimientos, 0),
      'puesto',      coalesce(c.puesto, 0),
      'cobrado',     coalesce(c.cobrado, 0),
      'resultado',   coalesce(c.cobrado, 0) - coalesce(c.puesto, 0),
      -- Lo que de verdad mira un ganadero: cuánto por cabeza.
      'por_unidad',  case
                       when l.cantidad > 0
                       then round((coalesce(c.cobrado, 0) - coalesce(c.puesto, 0)) / l.cantidad, 2)
                       else null
                     end,
      'cultivo',         l.cultivo,
      'campana',         l.campana,
      'hectareas',       l.hectareas,
      'precio_esperado', l.precio_esperado
    ) || public.numeros_de_lote(l.id, v_admin) as x
    from public.lotes l
    left join lateral (
      select
        count(*)::int as movimientos,
        sum(m.monto) filter (where m.tipo = 'gasto')              as puesto,
        sum(m.monto) filter (where m.tipo in ('venta', 'ingreso')) as cobrado
      from public.movimientos m
      where m.lote_id = l.id and m.estado = 'activo'
    ) c on true
    where l.empresa_id = p_empresa
      and (coalesce(p_incluir_cerrados, false) or l.estado = 'abierto')
  ) s;

  return v_res;
end $fn$;

-- ------------------------------------------------------------
-- 11. UNA CAMPAÑA, CON TODO LO QUE TIENE ADENTRO
--
--    Copia exacta de la 045 más: los números, las cosechas, las
--    liquidaciones, las deudas a cosecha y la estructura de costos por
--    categoría. Los movimientos siguen sin `costo_total` y ahora se filtran
--    con la regla de la 047 para quien no es admin.
-- ------------------------------------------------------------
create or replace function public.resumen_lote(p_empresa uuid, p_lote uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_lote  jsonb; v_movs jsonb; v_hoy date; v_admin boolean;
  v_cosechas jsonb; v_liqs jsonb; v_deudas jsonb; v_estructura jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  v_hoy   := public.hoy_empresa(p_empresa);
  v_admin := public.es_admin(p_empresa);

  select jsonb_build_object(
    'id', l.id, 'nombre', l.nombre, 'unidad', l.unidad, 'cantidad', l.cantidad,
    'estado', l.estado, 'abierto_el', l.abierto_el, 'cerrado_el', l.cerrado_el,
    'notas', l.notas,
    'dias', (coalesce(l.cerrado_el, v_hoy) - l.abierto_el),
    'cultivo', l.cultivo, 'campana', l.campana,
    'hectareas', l.hectareas, 'precio_esperado', l.precio_esperado
  ) into v_lote
  from public.lotes l where l.id = p_lote and l.empresa_id = p_empresa;

  if v_lote is null then
    raise exception 'Ese lote no existe.' using errcode = 'P0002';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',              m.id,
    'tipo',            m.tipo,
    'estado',          m.estado,
    'fecha',           m.fecha,
    'descripcion',     m.descripcion,
    'categoria',       m.categoria,
    'monto',           m.monto,
    'liquidacion_id',  m.liquidacion_id,
    'reparto_id',      m.reparto_id,
    'monto_original',  m.monto_original,
    'moneda_original', m.moneda_original,
    'cambio',          m.cambio,
    'metodo_pago',     m.metodo_pago
  ) order by m.fecha desc, m.created_at desc), '[]'::jsonb)
  into v_movs
  from public.movimientos m
  where m.lote_id = p_lote and m.empresa_id = p_empresa
    -- La regla de la 047: las ventas son de todos; lo demás, de su autor y
    -- del admin.
    and (v_admin or m.tipo = 'venta' or m.creado_por = auth.uid());

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', c.id, 'fecha', c.fecha, 'kg_netos', c.kg_netos, 'kg_brutos', c.kg_brutos,
    'humedad', c.humedad, 'destino', c.destino, 'ticket', c.ticket, 'notas', c.notas,
    'creado_por', c.creado_por
  ) order by c.fecha desc, c.created_at desc), '[]'::jsonb)
  into v_cosechas
  from public.cosechas c
  where c.lote_id = p_lote and c.empresa_id = p_empresa;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', q.id, 'grupo_id', q.grupo_id, 'fecha', q.fecha, 'comprador', q.comprador,
    'kg', q.kg, 'precio_tonelada', q.precio_tonelada,
    'precio_original', q.precio_original, 'moneda_original', q.moneda_original, 'cambio', q.cambio,
    'bruto', q.bruto,
    -- Lo que el silo descontó y compensó cuenta cuánto se debía: de
    -- administración, como las deudas (015).
    'descuentos',       case when v_admin then q.descuentos end,
    'compensado',       case when v_admin then q.compensado end,
    'pagado_con_grano', case when v_admin then q.pagado_con_grano end,
    'neto', q.neto, 'cuenta_id', q.cuenta_id, 'estado', q.estado,
    'movimiento_id', q.movimiento_id, 'notas', q.notas
  ) order by q.fecha desc, q.created_at desc), '[]'::jsonb)
  into v_liqs
  from public.liquidaciones q
  where q.lote_id = p_lote and q.empresa_id = p_empresa;

  if v_admin then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', d.id, 'nombre', d.nombre, 'acreedor', d.acreedor, 'categoria', d.categoria,
      'saldo', d.saldo, 'vence_el', d.vence_el
    ) order by d.vence_el nulls last, d.created_at), '[]'::jsonb)
    into v_deudas
    from public.deudas d
    where d.lote_id = p_lote and d.empresa_id = p_empresa and d.activa and d.saldo > 0;

    select coalesce(jsonb_agg(jsonb_build_object('categoria', s.categoria, 'monto', s.monto)
                              order by s.monto desc, s.categoria), '[]'::jsonb)
    into v_estructura
    from (
      select m.categoria, sum(m.monto) as monto
      from public.movimientos m
      where m.lote_id = p_lote and m.empresa_id = p_empresa
        and m.estado = 'activo' and m.tipo = 'gasto'
      group by m.categoria
    ) s;
  end if;

  return v_lote
    || public.numeros_de_lote(p_lote, v_admin)
    || jsonb_build_object(
         'movimientos',   v_movs,
         'cosechas',      v_cosechas,
         'liquidaciones', v_liqs,
         'deudas',        v_deudas,
         'estructura',    v_estructura
       );
end $fn$;

-- ------------------------------------------------------------
-- 12. BORRAR: SOLO LO QUE NO TIENE HISTORIA
--
--    Copia exacta de la 044 más el freno por cosechas, liquidaciones (de
--    cualquier estado) y deudas (de cualquier estado). El conteo de
--    movimientos queda como está (decisión 11).
-- ------------------------------------------------------------
create or replace function public.borrar_lote(p_empresa uuid, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare v_cuantos integer;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo administración maneja los lotes.' using errcode = '42501';
  end if;

  if not exists (select 1 from public.lotes where id = p_id and empresa_id = p_empresa) then
    raise exception 'Ese lote no existe.' using errcode = 'P0002';
  end if;

  if exists (select 1 from public.cosechas      where lote_id = p_id)
     or exists (select 1 from public.liquidaciones where lote_id = p_id)
     or exists (select 1 from public.deudas        where lote_id = p_id) then
    raise exception 'Ese lote tiene cosechas, liquidaciones o deudas cargadas. Sacáselas antes de borrarlo.'
      using errcode = '23503';
  end if;

  select count(*)::int into v_cuantos
  from public.movimientos where lote_id = p_id;

  if v_cuantos > 0 then
    raise exception 'Ese lote tiene % movimientos cargados. Sacáselos antes de borrarlo.', v_cuantos
      using errcode = '23503';
  end if;

  delete from public.lotes where id = p_id and empresa_id = p_empresa;
  return jsonb_build_object('borrado', true);
end $fn$;

-- ------------------------------------------------------------
-- 13. PONERLE UN MOVIMIENTO, O SACÁRSELO
--
--    Copia exacta de la 044 más: lo que nació dentro de una liquidación no
--    se mueve de campaña suelto, porque dejaría el papel repartido en dos.
-- ------------------------------------------------------------
create or replace function public.asignar_a_lote(
  p_movimiento uuid,
  p_lote       uuid default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare v_emp uuid; v_estado text; v_liq uuid;
begin
  select empresa_id, estado, liquidacion_id into v_emp, v_estado, v_liq
  from public.movimientos where id = p_movimiento;

  if v_emp is null then
    raise exception 'Ese movimiento no existe.' using errcode = 'P0002';
  end if;
  if not public.es_miembro(v_emp) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if v_estado <> 'activo' then
    raise exception 'Ese movimiento está anulado.' using errcode = '22023';
  end if;
  if v_liq is not null then
    raise exception 'Ese movimiento es parte de una liquidación: se maneja desde la campaña.' using errcode = '22023';
  end if;

  -- Que el lote sea de la misma empresa lo garantiza la llave compuesta,
  -- pero un error de llave foránea no le explica nada a nadie.
  if p_lote is not null
     and not exists (select 1 from public.lotes where id = p_lote and empresa_id = v_emp) then
    raise exception 'Ese lote no es de esta cuenta.' using errcode = '42501';
  end if;

  update public.movimientos set lote_id = p_lote where id = p_movimiento;

  return jsonb_build_object('lote', p_lote);
end $fn$;

-- ------------------------------------------------------------
-- 14. CREAR UNA DEUDA, AHORA «A COSECHA» DE UNA CAMPAÑA
--
--    Copia exacta de la 015 más `p_lote` y `p_categoria`. La firma de 10
--    se borra antes (096).
-- ------------------------------------------------------------
drop function if exists public.crear_deuda(uuid, text, text, text, numeric, numeric, integer, numeric, date, text);

create or replace function public.crear_deuda(
  p_empresa         uuid,
  p_nombre          text,
  p_tipo            text default 'otro',
  p_acreedor        text default '',
  p_monto           numeric default 0,
  p_saldo           numeric default null,
  p_cuotas_totales  integer default null,
  p_monto_cuota     numeric default null,
  p_vence_el        date default null,
  p_notas           text default '',
  -- La campaña que va a pagar esta deuda («a cosecha»).
  p_lote            uuid default null,
  -- La categoría del gasto que nace al pagarla; '' = 'Deudas'.
  p_categoria       text default ''
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_id    uuid;
  v_saldo numeric;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el propietario o un administrador puede cargar deudas.' using errcode = '42501';
  end if;
  if p_tipo not in ('tarjeta', 'prestamo', 'proveedor', 'otro') then
    raise exception 'Tipo de deuda no reconocido.' using errcode = '22023';
  end if;
  if coalesce(p_monto, 0) <= 0 then
    raise exception 'La deuda tiene que tener un monto.' using errcode = '22023';
  end if;

  -- Sin saldo explícito se asume que todavía no se pagó nada. Es lo normal
  -- al cargar una deuda nueva, y evita que alguien la deje en cero sin querer.
  v_saldo := coalesce(p_saldo, p_monto);
  if v_saldo > p_monto then
    raise exception 'El saldo no puede ser mayor que el monto original.' using errcode = '22023';
  end if;

  -- La llave compuesta ya lo frenaría, pero con un error que nadie entiende.
  if p_lote is not null
     and not exists (select 1 from public.lotes where id = p_lote and empresa_id = p_empresa) then
    raise exception 'Ese lote no es de esta cuenta.' using errcode = '42501';
  end if;

  insert into public.deudas (
    empresa_id, tipo, nombre, acreedor, monto_original, saldo,
    cuotas_totales, monto_cuota, vence_el, notas, creada_por,
    lote_id, categoria
  ) values (
    p_empresa, p_tipo::tipo_deuda, trim(p_nombre), coalesce(trim(p_acreedor), ''),
    p_monto, v_saldo, p_cuotas_totales, p_monto_cuota, p_vence_el,
    coalesce(left(p_notas, 500), ''), auth.uid(),
    p_lote, left(trim(coalesce(p_categoria, '')), 60)
  )
  returning id into v_id;

  return v_id;
end $fn$;

-- ------------------------------------------------------------
-- 15. REGISTRAR UN PAGO, DICIENDO CON QUÉ CUENTA, DE QUÉ CAMPAÑA Y DE QUÉ PAPEL
--
--    Copia exacta de la 082 más `p_cuenta`, `p_lote` y `p_liquidacion`. El
--    gasto que crea lleva la categoría y la campaña de la deuda, y el
--    vencimiento de una deuda con campaña no se corre (decisión 7).
--    `anular_pago_deuda` (082) no cambia: deshace este pago igual que
--    cualquier otro. La firma de 6 se borra antes (096).
-- ------------------------------------------------------------
drop function if exists public.registrar_pago_deuda(uuid, numeric, date, boolean, text, text);

create or replace function public.registrar_pago_deuda(
  p_deuda       uuid,
  p_monto       numeric,
  p_fecha       date default null,
  p_crear_gasto boolean default true,
  p_metodo      text default 'efectivo',
  p_nota        text default '',
  -- De qué cuenta salió (095/096). Null = la de su forma de pago (074).
  p_cuenta      uuid default null,
  -- A qué campaña va el gasto, si la deuda no tiene la suya.
  p_lote        uuid default null,
  -- El papel del silo que se cobró esta deuda, si fue así.
  p_liquidacion uuid default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_deuda      public.deudas;
  v_fecha      date;
  v_aplicado   numeric;
  v_movimiento uuid;
  v_pago       uuid;
  v_cuenta     boolean;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  select * into v_deuda from public.deudas where id = p_deuda;
  if v_deuda.id is null then
    raise exception 'Esa deuda no existe.' using errcode = 'P0002';
  end if;
  if not public.es_admin(v_deuda.empresa_id) then
    raise exception 'Solo el propietario o un administrador puede registrar pagos.' using errcode = '42501';
  end if;
  if coalesce(p_monto, 0) <= 0 then
    raise exception 'El pago tiene que ser mayor que cero.' using errcode = '22023';
  end if;
  if v_deuda.saldo <= 0 then
    raise exception 'Esa deuda ya está saldada.' using errcode = '22023';
  end if;

  -- Una cuenta, una campaña o un papel de OTRO negocio no se aceptan: las
  -- llaves lo frenarían igual, pero sin explicar nada.
  if p_cuenta is not null
     and not exists (select 1 from public.cuentas_dinero c
                     where c.id = p_cuenta and c.empresa_id = v_deuda.empresa_id and c.activa) then
    raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
  end if;
  if p_lote is not null
     and not exists (select 1 from public.lotes where id = p_lote and empresa_id = v_deuda.empresa_id) then
    raise exception 'Ese lote no es de esta cuenta.' using errcode = '42501';
  end if;
  if p_liquidacion is not null
     and not exists (select 1 from public.liquidaciones
                     where id = p_liquidacion and empresa_id = v_deuda.empresa_id) then
    raise exception 'Esa liquidación no existe.' using errcode = 'P0002';
  end if;

  v_fecha := coalesce(p_fecha, public.hoy_empresa(v_deuda.empresa_id));

  -- Nunca más de lo que falta.
  v_aplicado := least(p_monto, v_deuda.saldo);

  -- La misma condición que usa el update de abajo: se decide una vez y se
  -- guarda, para que deshacerlo no tenga que adivinarla.
  v_cuenta := v_deuda.cuotas_totales is not null
              and v_deuda.cuotas_pagadas < v_deuda.cuotas_totales;

  -- El gasto primero: si falla, no queremos haber bajado el saldo. Lleva la
  -- categoría y la campaña de la deuda: así el insumo «a cosecha» cae como
  -- Agroquímicos de Norte el día que se paga, y no como «Deudas» suelto.
  if p_crear_gasto then
    insert into public.movimientos (
      empresa_id, tipo, fecha, descripcion, categoria,
      subtotal, descuento, monto, costo_total, metodo_pago, creado_por,
      lote_id, cuenta_id, liquidacion_id
    ) values (
      v_deuda.empresa_id, 'gasto', v_fecha,
      'Pago ' || v_deuda.nombre, coalesce(nullif(v_deuda.categoria, ''), 'Deudas'),
      v_aplicado, 0, v_aplicado, 0, coalesce(p_metodo, 'efectivo'), auth.uid(),
      coalesce(v_deuda.lote_id, p_lote), p_cuenta, p_liquidacion
    )
    returning id into v_movimiento;
  end if;

  insert into public.pagos_deuda (
    deuda_id, empresa_id, monto, fecha, movimiento_id, nota, creado_por,
    vence_antes, cuota_contada, liquidacion_id
  )
  values (p_deuda, v_deuda.empresa_id, v_aplicado, v_fecha, v_movimiento,
          coalesce(left(p_nota, 300), ''), auth.uid(),
          v_deuda.vence_el, v_cuenta, p_liquidacion)
  returning id into v_pago;

  update public.deudas
  set saldo = saldo - v_aplicado,
      cuotas_pagadas = case when v_cuenta then cuotas_pagadas + 1 else cuotas_pagadas end,
      vence_el = case
        when saldo - v_aplicado <= 0 then null
        -- Una deuda con campaña vence cuando vence la cosecha: un pago
        -- parcial no la corre (decisión 7).
        when v_deuda.lote_id is not null then vence_el
        when vence_el is not null then vence_el + interval '1 month'
        else null
      end,
      updated_at = now()
  where id = p_deuda;

  return jsonb_build_object(
    'pago_id', v_pago,
    'aplicado', v_aplicado,
    'sobrante', greatest(p_monto - v_aplicado, 0),
    'saldo', v_deuda.saldo - v_aplicado,
    'saldada', (v_deuda.saldo - v_aplicado) <= 0,
    'movimiento_id', v_movimiento
  );
end $fn$;

-- ------------------------------------------------------------
-- 16. CARGAR UN TICKET DE BALANZA
--
--    Cualquier miembro: el que pesa el camión puede ser el peón. `p_id` lo
--    genera el celular; un reintento sin señal devuelve el mismo id sin
--    insertar. Se puede cargar en una campaña cerrada: el resultado se
--    corrige igual, como manda la 044.
-- ------------------------------------------------------------
create or replace function public.registrar_cosecha(
  p_empresa   uuid,
  p_lote      uuid,
  p_fecha     date,
  p_kg_netos  numeric,
  p_kg_brutos numeric default null,
  p_humedad   numeric default null,
  p_destino   text default '',
  p_ticket    text default '',
  p_notas     text default '',
  p_id        uuid default null
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_lote  public.lotes;
  v_emp   uuid;
  v_fecha date;
  v_hoy   date;
  v_id    uuid;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  -- El reintento: mismo id, misma empresa, nada que hacer. En otra
  -- empresa, no existe.
  if p_id is not null then
    select empresa_id into v_emp from public.cosechas where id = p_id;
    if v_emp is not null then
      if v_emp <> p_empresa then
        raise exception 'Esa cosecha no existe.' using errcode = 'P0002';
      end if;
      return p_id;
    end if;
  end if;

  select * into v_lote from public.lotes where id = p_lote and empresa_id = p_empresa;
  if v_lote.id is null then
    raise exception 'Ese lote no es de esta cuenta.' using errcode = '42501';
  end if;

  if coalesce(p_kg_netos, 0) <= 0 then
    raise exception 'Los kilos tienen que ser más que cero.' using errcode = '22023';
  end if;
  if p_kg_brutos is not null and p_kg_brutos < p_kg_netos then
    raise exception 'Los kilos acreditados no pueden ser más que el peso de balanza.' using errcode = '22023';
  end if;
  if p_humedad is not null and (p_humedad < 5 or p_humedad > 40) then
    raise exception 'La humedad tiene que estar entre 5 y 40.' using errcode = '22023';
  end if;

  v_hoy   := public.hoy_empresa(p_empresa);
  v_fecha := coalesce(p_fecha, v_hoy);
  if v_fecha < v_lote.abierto_el or v_fecha > v_hoy + 1 then
    raise exception 'Esa fecha no es válida.' using errcode = '22023';
  end if;

  insert into public.cosechas (
    id, empresa_id, lote_id, fecha, kg_netos, kg_brutos, humedad, destino, ticket, notas, creado_por
  ) values (
    coalesce(p_id, gen_random_uuid()), p_empresa, p_lote, v_fecha,
    round(p_kg_netos, 0), round(p_kg_brutos, 0), p_humedad,
    left(trim(coalesce(p_destino, '')), 80), left(trim(coalesce(p_ticket, '')), 40),
    left(coalesce(p_notas, ''), 300), auth.uid()
  )
  returning id into v_id;

  return v_id;
end $fn$;

-- ------------------------------------------------------------
-- 17. BORRAR UN TICKET
--
--    Delete físico: no guarda plata. Lo borra administración o quien lo
--    cargó (un peón que se equivocó de campaña lo arregla solo).
-- ------------------------------------------------------------
create or replace function public.borrar_cosecha(p_empresa uuid, p_id uuid)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare v_c public.cosechas;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select * into v_c from public.cosechas where id = p_id and empresa_id = p_empresa;
  if v_c.id is null then
    raise exception 'Esa cosecha no existe.' using errcode = 'P0002';
  end if;

  if not public.es_admin(p_empresa) and v_c.creado_por is distinct from auth.uid() then
    raise exception 'Solo quien la cargó o administración puede borrar una cosecha.' using errcode = '42501';
  end if;

  delete from public.cosechas where id = v_c.id;

  return jsonb_build_object('id', v_c.id, 'lote_id', v_c.lote_id);
end $fn$;

-- ------------------------------------------------------------
-- 18. CARGAR EL PAPEL DE LA COOPERATIVA
--
--    UNA transacción para todo el papel. `p_partes` = [{lote_id, kg,
--    descuentos: [{categoria, monto}], deudas: [{deuda_id, monto}],
--    grano: [{categoria, monto, descripcion}]}], 1 a 10 partes, lotes
--    distintos. El prorrateo de descuentos por kilos entre partes lo hace
--    la pantalla (src/lib/liquidacion.ts): acá cada parte ya viene con lo
--    suyo.
--
--    Por parte: `bruto = round(kg × precio / 1000, 2)`; `neto = bruto −
--    Σdescuentos − Σdeudas − Σgrano`, y si da negativo el papel no cuadra.
--    Efecto en la cuenta elegida: +bruto − descuentos − deudas − grano =
--    +neto, lo que dice el papel. En la campaña: cobrado +bruto, puesto
--    +descuentos +grano +deudas compensadas, a_cosecha −deudas. Nada cuenta
--    dos veces.
--
--    Idempotente por `p_grupo`: si el papel ya está, devuelve la misma
--    respuesta reconstruida de las filas y no inserta nada.
-- ------------------------------------------------------------
create or replace function public.registrar_liquidacion(
  p_empresa         uuid,
  p_grupo           uuid,
  p_fecha           date,
  p_comprador       text,
  p_precio_tonelada numeric,
  p_partes          jsonb,
  p_cuenta          uuid default null,
  p_metodo          text default 'transferencia',
  p_notas           text default '',
  p_moneda_original text default null,
  p_precio_original numeric default null,
  p_cambio          numeric default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_grupo       uuid;
  v_hoy         date;
  v_fecha       date;
  v_metodo      text;
  v_comprador   text;
  v_moneda      text;
  v_parte       jsonb;
  v_item        jsonb;
  v_lote        public.lotes;
  v_deuda       public.deudas;
  v_lotes       uuid[] := '{}';
  v_acumulado   jsonb  := '{}'::jsonb;
  v_min_abierto date;
  v_kg          numeric;
  v_monto       numeric;
  v_acum        numeric;
  v_bruto       numeric;
  v_desc        numeric;
  v_comp        numeric;
  v_grano       numeric;
  v_neto        numeric;
  v_cat         text;
  v_venta       uuid;
  v_liq         uuid;
  v_res         jsonb;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo administración carga liquidaciones.' using errcode = '42501';
  end if;

  v_grupo := coalesce(p_grupo, gen_random_uuid());

  -- El reintento sin señal: el papel ya está, se devuelve lo mismo. En otra
  -- empresa, no existe.
  if exists (select 1 from public.liquidaciones where grupo_id = v_grupo) then
    if not exists (select 1 from public.liquidaciones where grupo_id = v_grupo and empresa_id = p_empresa) then
      raise exception 'Esa liquidación no existe.' using errcode = 'P0002';
    end if;
  else
    ---------------------------------------------- lo general del papel
    if p_partes is null or jsonb_typeof(p_partes) <> 'array' or jsonb_array_length(p_partes) = 0 then
      raise exception 'La liquidación necesita al menos una campaña con kilos.' using errcode = '22023';
    end if;
    if jsonb_array_length(p_partes) > 10 then
      raise exception 'Una liquidación no puede tener más de 10 campañas.' using errcode = '22023';
    end if;
    if p_precio_tonelada is null or p_precio_tonelada < 0 then
      raise exception 'El precio no puede ser negativo.' using errcode = '22023';
    end if;

    -- Los mismos métodos que acepta `registrar_venta` menos 'credito': la
    -- coop no paga el día que liquida, pero eso no es un fiado (decisión 18
    -- del contrato: «cargala cuando te acrediten»).
    v_metodo := lower(coalesce(nullif(trim(p_metodo), ''), 'transferencia'));
    if v_metodo not in ('efectivo', 'transferencia', 'tarjeta', 'otro') then
      raise exception 'La forma de cobro no es válida.' using errcode = '22023';
    end if;

    if p_cuenta is not null
       and not exists (select 1 from public.cuentas_dinero c
                       where c.id = p_cuenta and c.empresa_id = p_empresa and c.activa) then
      raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
    end if;

    -- El precio en la otra moneda: los tres datos juntos o ninguno.
    if (p_moneda_original is null) <> (p_precio_original is null)
       or (p_moneda_original is null) <> (p_cambio is null) then
      raise exception 'Para guardar el precio en otra moneda hacen falta la moneda, el precio y el cambio.'
        using errcode = '22023';
    end if;
    if p_moneda_original is not null then
      v_moneda := upper(trim(p_moneda_original));
      if v_moneda not in ('PYG', 'USD', 'ARS', 'BRL', 'EUR') then
        raise exception 'No conocemos esa moneda.' using errcode = '22023';
      end if;
      if p_cambio <= 0 then
        raise exception 'Poné a cuánto está el cambio: sin eso no se puede convertir nada.'
          using errcode = '22023';
      end if;
      if p_precio_original < 0 then
        raise exception 'El precio no puede ser negativo.' using errcode = '22023';
      end if;
    end if;

    v_comprador := left(coalesce(trim(p_comprador), ''), 80);

    ---------------------------------------------- las campañas, y la fecha
    for v_parte in select * from jsonb_array_elements(p_partes) loop
      if jsonb_typeof(v_parte) <> 'object' then
        raise exception 'La liquidación necesita al menos una campaña con kilos.' using errcode = '22023';
      end if;
      select * into v_lote from public.lotes
      where id = nullif(trim(coalesce(v_parte ->> 'lote_id', '')), '')::uuid and empresa_id = p_empresa;
      if v_lote.id is null then
        raise exception 'Ese lote no es de esta cuenta.' using errcode = '42501';
      end if;
      if v_lote.id = any (v_lotes) then
        raise exception 'Cada campaña va una sola vez en la liquidación.' using errcode = '22023';
      end if;
      v_lotes := v_lotes || v_lote.id;
      v_min_abierto := least(coalesce(v_min_abierto, v_lote.abierto_el), v_lote.abierto_el);

      -- Las deudas se validan TODAS acá, antes de escribir nada. Si se
      -- validaran parte por parte, la parte 2 vería el saldo ya rebajado
      -- por el pago de la parte 1 y una deuda repartida entre dos campañas
      -- (3.000 + 1.800 sobre 4.800) se rechazaría aunque cierre. Lo que se
      -- le descuenta a una deuda en todo el papel no puede pasar su saldo;
      -- `for update` la deja trabada hasta que el papel entero esté escrito.
      if jsonb_typeof(v_parte -> 'deudas') = 'array' then
        for v_item in select * from jsonb_array_elements(v_parte -> 'deudas') loop
          select * into v_deuda from public.deudas
          where id = nullif(trim(coalesce(v_item ->> 'deuda_id', '')), '')::uuid
            and empresa_id = p_empresa and activa
          for update;
          if v_deuda.id is null then
            raise exception 'Esa deuda no existe.' using errcode = 'P0002';
          end if;
          v_monto := round(coalesce(nullif(trim(coalesce(v_item ->> 'monto', '')), '')::numeric, 0), 2);
          if v_monto <= 0 then
            raise exception 'El pago tiene que ser mayor que cero.' using errcode = '22023';
          end if;
          v_acum := coalesce((v_acumulado ->> v_deuda.id::text)::numeric, 0) + v_monto;
          if v_acum > v_deuda.saldo then
            raise exception 'Le estás descontando a esa deuda más de lo que debe.' using errcode = '22023';
          end if;
          v_acumulado := v_acumulado || jsonb_build_object(v_deuda.id::text, v_acum);
        end loop;
      end if;
    end loop;

    v_hoy   := public.hoy_empresa(p_empresa);
    v_fecha := coalesce(p_fecha, v_hoy);
    if v_fecha < v_min_abierto or v_fecha > v_hoy + 1 then
      raise exception 'Esa fecha no es válida.' using errcode = '22023';
    end if;

    ---------------------------------------------- parte por parte
    for v_parte in select * from jsonb_array_elements(p_partes) loop
      select * into v_lote from public.lotes
      where id = (v_parte ->> 'lote_id')::uuid and empresa_id = p_empresa;

      v_kg := round(coalesce(nullif(trim(coalesce(v_parte ->> 'kg', '')), '')::numeric, 0), 0);
      if v_kg <= 0 then
        raise exception 'Los kilos tienen que ser más que cero.' using errcode = '22023';
      end if;

      -- Primero se suma y se valida todo lo de la parte; recién después se
      -- escribe. Si algo no cierra, la transacción entera se va.
      v_desc := 0;
      if jsonb_typeof(v_parte -> 'descuentos') = 'array' then
        if jsonb_array_length(v_parte -> 'descuentos') > 12 then
          raise exception 'Una liquidación no puede tener más de 12 descuentos por campaña.' using errcode = '22023';
        end if;
        for v_item in select * from jsonb_array_elements(v_parte -> 'descuentos') loop
          v_monto := round(coalesce(nullif(trim(coalesce(v_item ->> 'monto', '')), '')::numeric, 0), 2);
          if trim(coalesce(v_item ->> 'categoria', '')) = '' or v_monto <= 0 then
            raise exception 'Cada descuento necesita una categoría y un monto mayor que cero.' using errcode = '22023';
          end if;
          v_desc := v_desc + v_monto;
        end loop;
      end if;

      -- Las deudas ya se validaron todas juntas, antes de escribir nada (ver
      -- arriba): acá solo se suma lo que se compensa en esta parte.
      v_comp := 0;
      if jsonb_typeof(v_parte -> 'deudas') = 'array' then
        for v_item in select * from jsonb_array_elements(v_parte -> 'deudas') loop
          v_comp := v_comp + round((v_item ->> 'monto')::numeric, 2);
        end loop;
      end if;

      v_grano := 0;
      if jsonb_typeof(v_parte -> 'grano') = 'array' then
        for v_item in select * from jsonb_array_elements(v_parte -> 'grano') loop
          v_monto := round(coalesce(nullif(trim(coalesce(v_item ->> 'monto', '')), '')::numeric, 0), 2);
          if trim(coalesce(v_item ->> 'categoria', '')) = '' or v_monto <= 0 then
            raise exception 'Cada descuento necesita una categoría y un monto mayor que cero.' using errcode = '22023';
          end if;
          v_grano := v_grano + v_monto;
        end loop;
      end if;

      v_bruto := round(v_kg * p_precio_tonelada / 1000, 2);
      v_neto  := v_bruto - v_desc - v_comp - v_grano;
      if v_neto < 0 then
        raise exception 'La liquidación no cuadra: lo que el silo descontó suma más que el bruto. Bajá lo que compensás de las deudas; lo que falte sigue como deuda.'
          using errcode = '22023';
      end if;

      -- La venta, por el bruto. Directo y no con `registrar_venta` (ver la
      -- cabecera); todas las columnas que ella rellena, más la campaña y la
      -- moneda original.
      insert into public.movimientos (
        empresa_id, tipo, estado, fecha, descripcion, categoria,
        subtotal, descuento, monto, costo_total,
        metodo_pago, contraparte, notas, origen, creado_por, cliente_id, cuenta_id,
        lote_id, monto_original, moneda_original, cambio
      )
      values (
        p_empresa, 'venta', 'activo', v_fecha,
        left(coalesce(nullif(v_lote.cultivo, ''), 'Granos') || ' · ' || v_kg::text || ' kg · ' || v_comprador, 200),
        'Granos',
        v_bruto, 0, v_bruto, 0,
        v_metodo, v_comprador, '', 'manual', auth.uid(), null, p_cuenta,
        v_lote.id,
        case when v_moneda is not null then round(v_kg * p_precio_original / 1000, 2) end,
        v_moneda, p_cambio
      )
      returning id into v_venta;

      insert into public.liquidaciones (
        empresa_id, grupo_id, lote_id, fecha, movimiento_id, comprador,
        kg, precio_tonelada, bruto, descuentos, compensado, pagado_con_grano, neto,
        cuenta_id, moneda_original, precio_original, cambio, notas, creado_por
      ) values (
        p_empresa, v_grupo, v_lote.id, v_fecha, v_venta, v_comprador,
        v_kg, p_precio_tonelada, v_bruto, v_desc, v_comp, v_grano, v_neto,
        p_cuenta, v_moneda, p_precio_original, p_cambio, left(coalesce(p_notas, ''), 300), auth.uid()
      )
      returning id into v_liq;

      update public.movimientos set liquidacion_id = v_liq where id = v_venta;

      -- Lo que el silo descontó: un gasto de la campaña por cada renglón,
      -- con la misma fecha, cuenta y forma de pago que la venta.
      if jsonb_typeof(v_parte -> 'descuentos') = 'array' then
        for v_item in select * from jsonb_array_elements(v_parte -> 'descuentos') loop
          v_cat   := left(trim(v_item ->> 'categoria'), 60);
          v_monto := round((v_item ->> 'monto')::numeric, 2);
          insert into public.movimientos (
            empresa_id, tipo, estado, fecha, descripcion, categoria,
            subtotal, descuento, monto, costo_total,
            metodo_pago, contraparte, notas, origen, creado_por, cuenta_id,
            lote_id, liquidacion_id
          ) values (
            p_empresa, 'gasto', 'activo', v_fecha,
            left(v_cat || ' · liquidación ' || v_comprador, 200), v_cat,
            v_monto, 0, v_monto, 0,
            v_metodo, v_comprador, '', 'manual', auth.uid(), p_cuenta,
            v_lote.id, v_liq
          );
        end loop;
      end if;

      -- Lo que se cobró de las deudas a cosecha: un pago por deuda, que
      -- crea su gasto con la categoría y la campaña de la deuda.
      if jsonb_typeof(v_parte -> 'deudas') = 'array' then
        for v_item in select * from jsonb_array_elements(v_parte -> 'deudas') loop
          perform public.registrar_pago_deuda(
            (v_item ->> 'deuda_id')::uuid,
            round((v_item ->> 'monto')::numeric, 2),
            v_fecha, true, v_metodo,
            'Descontado en la liquidación de ' || v_comprador,
            p_cuenta, v_lote.id, v_liq
          );
        end loop;
      end if;

      -- Lo que el grano pagó (el alquiler en kilos del dueño del campo).
      if jsonb_typeof(v_parte -> 'grano') = 'array' then
        for v_item in select * from jsonb_array_elements(v_parte -> 'grano') loop
          v_cat   := left(trim(v_item ->> 'categoria'), 60);
          v_monto := round((v_item ->> 'monto')::numeric, 2);
          insert into public.movimientos (
            empresa_id, tipo, estado, fecha, descripcion, categoria,
            subtotal, descuento, monto, costo_total,
            metodo_pago, contraparte, notas, origen, creado_por, cuenta_id,
            lote_id, liquidacion_id
          ) values (
            p_empresa, 'gasto', 'activo', v_fecha,
            left(coalesce(nullif(trim(coalesce(v_item ->> 'descripcion', '')), ''), v_cat), 200), v_cat,
            v_monto, 0, v_monto, 0,
            v_metodo, v_comprador, '', 'manual', auth.uid(), p_cuenta,
            v_lote.id, v_liq
          );
        end loop;
      end if;
    end loop;
  end if;

  -- La respuesta sale siempre de las filas: así el reintento devuelve
  -- exactamente lo mismo que la primera vez.
  select jsonb_build_object(
    'grupo_id', v_grupo,
    'bruto',    coalesce(sum(q.bruto), 0),
    'neto',     coalesce(sum(q.neto), 0),
    'liquidaciones', coalesce(jsonb_agg(jsonb_build_object(
      'id', q.id, 'lote_id', q.lote_id, 'movimiento_id', q.movimiento_id,
      'kg', q.kg, 'bruto', q.bruto, 'neto', q.neto
    ) order by q.created_at, q.id), '[]'::jsonb)
  ) into v_res
  from public.liquidaciones q
  where q.grupo_id = v_grupo and q.empresa_id = p_empresa;

  return v_res;
end $fn$;

-- ------------------------------------------------------------
-- 19. ANULAR EL PAPEL ENTERO
--
--    Todo o nada: la venta, los gastos que nacieron adentro y los pagos de
--    deudas que el silo se cobró (con `anular_pago_deuda`, que devuelve el
--    saldo y anula su gasto). Nada se borra: queda el rastro, y la
--    billetera vuelve sola porque solo suma lo activo.
--
--    Si la venta ya estaba anulada desde el historial, se saltea: el
--    código 23505 es exactamente el que `anular_movimiento` usa para «ya
--    estaba anulado», y no se tapa ningún otro error.
-- ------------------------------------------------------------
create or replace function public.anular_liquidacion(
  p_empresa uuid,
  p_grupo   uuid,
  p_motivo  text default ''
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_q       record;
  v_g       record;
  v_p       record;
  v_total   integer;
  v_activas integer;
  v_n       integer := 0;
  v_motivo  text;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo administración carga liquidaciones.' using errcode = '42501';
  end if;

  select count(*)::int, (count(*) filter (where estado = 'activa'))::int
  into v_total, v_activas
  from public.liquidaciones
  where grupo_id = p_grupo and empresa_id = p_empresa;

  if v_total = 0 then
    raise exception 'Esa liquidación no existe.' using errcode = 'P0002';
  end if;
  if v_activas = 0 then
    raise exception 'Esa liquidación ya estaba anulada.' using errcode = '22023';
  end if;

  v_motivo := nullif(trim(coalesce(p_motivo, '')), '');

  for v_q in
    select * from public.liquidaciones
    where grupo_id = p_grupo and empresa_id = p_empresa and estado = 'activa'
    for update
  loop
    begin
      perform public.anular_movimiento(v_q.movimiento_id, v_motivo);
    exception when unique_violation then
      null;
    end;

    -- Los gastos del papel (descuentos y grano). Los de los pagos de
    -- deudas los anula `anular_pago_deuda`, abajo.
    for v_g in
      select m.id from public.movimientos m
      where m.liquidacion_id = v_q.id and m.tipo = 'gasto' and m.estado = 'activo'
        and not exists (select 1 from public.pagos_deuda p where p.movimiento_id = m.id)
    loop
      perform public.anular_movimiento(v_g.id, v_motivo);
    end loop;

    -- Un pago anulado se borra (082): el que sigue estando, sigue vivo.
    for v_p in select p.id from public.pagos_deuda p where p.liquidacion_id = v_q.id loop
      perform public.anular_pago_deuda(v_p.id);
    end loop;

    update public.liquidaciones
    set estado = 'anulada', anulada_por = auth.uid(), anulada_at = now()
    where id = v_q.id;

    v_n := v_n + 1;
  end loop;

  return jsonb_build_object('grupo_id', p_grupo, 'anuladas', v_n);
end $fn$;

-- ------------------------------------------------------------
-- 20. PERMISOS
--
--    Cada firma nueva: nada para public ni anon, ejecutar para quien inició
--    sesión. `numeros_de_lote` es interna (ver 8). Las que no cambiaron de
--    firma conservan sus permisos con `create or replace`; se reescriben
--    igual para que esta migración se lea sola.
-- ------------------------------------------------------------
revoke all on function public.guardar_lote(uuid, text, text, numeric, text, uuid, date, text, text, numeric, numeric) from public, anon;
grant execute on function public.guardar_lote(uuid, text, text, numeric, text, uuid, date, text, text, numeric, numeric) to authenticated;

revoke all on function public.listar_lotes(uuid, boolean) from public, anon;
grant execute on function public.listar_lotes(uuid, boolean) to authenticated;

revoke all on function public.resumen_lote(uuid, uuid) from public, anon;
grant execute on function public.resumen_lote(uuid, uuid) to authenticated;

revoke all on function public.borrar_lote(uuid, uuid) from public, anon;
grant execute on function public.borrar_lote(uuid, uuid) to authenticated;

revoke all on function public.asignar_a_lote(uuid, uuid) from public, anon;
grant execute on function public.asignar_a_lote(uuid, uuid) to authenticated;

revoke all on function public.crear_deuda(uuid, text, text, text, numeric, numeric, integer, numeric, date, text, uuid, text) from public, anon;
grant execute on function public.crear_deuda(uuid, text, text, text, numeric, numeric, integer, numeric, date, text, uuid, text) to authenticated;

revoke all on function public.registrar_pago_deuda(uuid, numeric, date, boolean, text, text, uuid, uuid, uuid) from public, anon;
grant execute on function public.registrar_pago_deuda(uuid, numeric, date, boolean, text, text, uuid, uuid, uuid) to authenticated;

revoke all on function public.registrar_cosecha(uuid, uuid, date, numeric, numeric, numeric, text, text, text, uuid) from public, anon;
grant execute on function public.registrar_cosecha(uuid, uuid, date, numeric, numeric, numeric, text, text, text, uuid) to authenticated;

revoke all on function public.borrar_cosecha(uuid, uuid) from public, anon;
grant execute on function public.borrar_cosecha(uuid, uuid) to authenticated;

revoke all on function public.registrar_liquidacion(uuid, uuid, date, text, numeric, jsonb, uuid, text, text, text, numeric, numeric) from public, anon;
grant execute on function public.registrar_liquidacion(uuid, uuid, date, text, numeric, jsonb, uuid, text, text, text, numeric, numeric) to authenticated;

revoke all on function public.anular_liquidacion(uuid, uuid, text) from public, anon;
grant execute on function public.anular_liquidacion(uuid, uuid, text) to authenticated;


-- ############################################################
-- ##  101_categorias_agricultura.sql
-- ############################################################

-- ============================================================
-- 101 · EN QUÉ GASTA UN AGRICULTOR
-- ============================================================
--
-- La lista de agricultura de la 021 tenía nueve categorías y pistas de una
-- palabra. Con la 100 la campaña se paga con el papel de la cooperativa, y
-- ese papel descuenta cosas que no tenían dónde caer: el secado y la
-- comisión del acopio, la retención de IVA, los intereses del banco que
-- financió la semilla, el repuesto del tractor. Caían en «Otros», que es
-- donde se pierde la estructura de costos.
--
-- Se conservan los nueve nombres que ya existen (Semilla, Fertilizante,
-- Agroquímicos, Combustible, Cosecha, Fletes, Arrendamiento, Personal,
-- Otros) para no dejar huérfano ningún gasto ya cargado, se les suman
-- pistas, y se agregan cinco: Siembra y pulverización, Secado y acopio,
-- Maquinaria y repuestos, Intereses y bancos, Retención de IVA. Catorce en
-- este orden, que es el orden del calendario de la campaña: primero lo que
-- se pone, después lo que descuenta el silo, al final lo del banco.
--
-- Las pistas van en los dos idiomas en la misma lista («urea, cal, abono,
-- adubo, ureia, calcário»): van al prompt de la captura por voz, y el
-- sojero de Canindeyú dicta en portugués tan seguido como en español.
--
-- Copia EXACTA de la versión viva (097, verificada con `pg_get_functiondef`
-- el 23/09/2026) tocando SOLO la rama 'agricultura'. Va aparte de la 100
-- para poder aplicarla sola.

create or replace function public.categorias_de_rubro(
  p_rubro text,
  p_tipo_cuenta text default 'emprendedor'
)
returns jsonb language sql immutable set search_path = public as $fn$
  select case
    when coalesce(p_tipo_cuenta, 'emprendedor') = 'personal' then jsonb_build_array(
      jsonb_build_object('nombre','Comida','pistas','supermercado, almacén, verdulería, carnicería, despensa, panadería'),
      jsonb_build_object('nombre','Alquiler','pistas','alquiler, expensas, condominio'),
      jsonb_build_object('nombre','Servicios','pistas','luz, agua, internet, teléfono, cable, gas'),
      jsonb_build_object('nombre','Transporte','pistas','colectivo, nafta, combustible, pasaje, taxi, uber, peaje'),
      jsonb_build_object('nombre','Salud','pistas','farmacia, remedios, médico, dentista, seguro médico, análisis'),
      jsonb_build_object('nombre','Educación','pistas','colegio, cuota, universidad, útiles, curso, libros'),
      jsonb_build_object('nombre','Ropa','pistas','ropa, calzado, zapatillas, campera'),
      jsonb_build_object('nombre','Cuidado personal','pistas','peluquería, uñas, barbería, cosmética, gimnasio, perfume'),
      jsonb_build_object('nombre','Ocio','pistas','salida, restaurante, cine, streaming, viaje, cerveza, cumpleaños'),
      jsonb_build_object('nombre','Hogar','pistas','limpieza, muebles, arreglos, electrodomésticos, ferretería'),
      jsonb_build_object('nombre','Cuotas y deudas','pistas','tarjeta, préstamo, cuota, financiera'),
      jsonb_build_object('nombre','Otros','pistas',''))

    when coalesce(p_rubro, 'comercio') = 'ganaderia' then jsonb_build_array(
      jsonb_build_object('nombre','Alimentación','pistas','maíz, balanceado, ración, fardos, sal, pasto'),
      jsonb_build_object('nombre','Sanidad','pistas','vacunas, antiparasitarios, veterinario, remedios'),
      jsonb_build_object('nombre','Personal','pistas','peón, capataz, jornales, sueldos'),
      jsonb_build_object('nombre','Combustible','pistas','gasoil, nafta'),
      jsonb_build_object('nombre','Arrendamiento','pistas','alquiler de campo, pastaje'),
      jsonb_build_object('nombre','Fletes','pistas','transporte de hacienda, camión jaula'),
      jsonb_build_object('nombre','Mantenimiento','pistas','alambrado, aguadas, maquinaria, herramientas'),
      jsonb_build_object('nombre','Impuestos','pistas',''),
      jsonb_build_object('nombre','Otros','pistas',''))

    -- Lo que gasta una campaña agrícola (101), en el orden del calendario:
    -- lo que se pone, lo que descuenta el silo, lo del banco.
    when coalesce(p_rubro, 'comercio') = 'agricultura' then jsonb_build_array(
      jsonb_build_object('nombre','Semilla','pistas','semilla, plantines, bolsa, semente, mudas, saco'),
      jsonb_build_object('nombre','Fertilizante','pistas','urea, fosfato, cloruro, cal, abono, adubo, ureia, calcário'),
      jsonb_build_object('nombre','Agroquímicos','pistas','herbicida, fungicida, insecticida, glifosato, veneno, defensivo, inseticida'),
      jsonb_build_object('nombre','Combustible','pistas','gasoil, nafta, diésel, aceite, diesel, óleo'),
      jsonb_build_object('nombre','Siembra y pulverización','pistas','siembra, pulverizada, pasada, servicio, plantio, pulverização'),
      jsonb_build_object('nombre','Cosecha','pistas','cosechadora, trilla, colheitadeira'),
      jsonb_build_object('nombre','Fletes','pistas','flete, camión, transporte, frete, caminhão'),
      jsonb_build_object('nombre','Secado y acopio','pistas','secado, comisión, acopio, silo, secagem, armazenagem, armazém'),
      jsonb_build_object('nombre','Arrendamiento','pistas','alquiler de campo, alquiler en kilos, arrendamento, aluguel de terra'),
      jsonb_build_object('nombre','Personal','pistas','jornal, peón, tractorista, sueldo, diária, peão, tratorista, salário'),
      jsonb_build_object('nombre','Maquinaria y repuestos','pistas','repuesto, taller, tractor, cubierta, peça, oficina, pneu'),
      jsonb_build_object('nombre','Intereses y bancos','pistas','interés, banco, comisión bancaria, juros'),
      jsonb_build_object('nombre','Retención de IVA','pistas','retención, IVA, retenção'),
      jsonb_build_object('nombre','Otros','pistas',''))

    when coalesce(p_rubro, 'comercio') = 'servicios' then jsonb_build_array(
      jsonb_build_object('nombre','Materiales','pistas','cemento, arena, cables, pintura, insumos'),
      jsonb_build_object('nombre','Repuestos','pistas','piezas, filtros, aceite'),
      jsonb_build_object('nombre','Herramientas','pistas',''),
      jsonb_build_object('nombre','Combustible','pistas','gasoil, nafta'),
      jsonb_build_object('nombre','Personal','pistas','ayudante, jornales, sueldos'),
      jsonb_build_object('nombre','Transporte','pistas','flete, viaje, delivery'),
      jsonb_build_object('nombre','Impuestos','pistas',''),
      jsonb_build_object('nombre','Otros','pistas',''))

    when coalesce(p_rubro, 'comercio') = 'clases' then jsonb_build_array(
      jsonb_build_object('nombre','Internet y plataformas','pistas','internet, wifi, Zoom, Meet, plan del celular, hosting'),
      jsonb_build_object('nombre','Comisiones','pistas','Preply, Italki, Superprof, lo que se lleva la plataforma, comisión de cobro'),
      jsonb_build_object('nombre','Material','pistas','libros, licencias, PDF, impresiones, fotocopias, cuadernos'),
      jsonb_build_object('nombre','Equipo','pistas','notebook, micrófono, cámara, auriculares, tablet, pizarra, luz'),
      jsonb_build_object('nombre','Publicidad','pistas','anuncios, Instagram, Facebook, volantes'),
      jsonb_build_object('nombre','Capacitación','pistas','cursos propios, certificaciones, exámenes, membresías'),
      jsonb_build_object('nombre','Alquiler','pistas','aula, salón, espacio de trabajo'),
      jsonb_build_object('nombre','Impuestos','pistas',''),
      jsonb_build_object('nombre','Otros','pistas',''))

    -- Lo que gasta un personal trainer (097): el equipo que lleva, el lugar
    -- donde entrena, y moverse hasta cada cliente.
    when coalesce(p_rubro, 'comercio') = 'entrenamiento' then jsonb_build_array(
      jsonb_build_object('nombre','Equipamiento','pistas','pesas, mancuernas, bandas, colchonetas, kettlebell, TRX, soga, conos'),
      jsonb_build_object('nombre','Gimnasio y espacio','pistas','cuota del gimnasio, alquiler del espacio, box, cancha, derecho de uso'),
      jsonb_build_object('nombre','Transporte','pistas','nafta, combustible, colectivo, uber, ir a domicilio'),
      jsonb_build_object('nombre','Ropa deportiva','pistas','ropa, zapatillas, calzas, uniforme'),
      jsonb_build_object('nombre','Internet y aplicaciones','pistas','internet, plan del celular, app de rutinas, Zoom'),
      jsonb_build_object('nombre','Publicidad','pistas','anuncios, Instagram, Facebook, TikTok, volantes'),
      jsonb_build_object('nombre','Capacitación','pistas','cursos, certificaciones, workshops, membresías'),
      jsonb_build_object('nombre','Impuestos','pistas',''),
      jsonb_build_object('nombre','Otros','pistas',''))

    else jsonb_build_array(
      jsonb_build_object('nombre','Mercadería','pistas','lo que comprás para revender'),
      jsonb_build_object('nombre','Transporte','pistas','combustible, flete, delivery'),
      jsonb_build_object('nombre','Comida','pistas',''),
      jsonb_build_object('nombre','Publicidad','pistas',''),
      jsonb_build_object('nombre','Servicios','pistas','luz, agua, internet, teléfono'),
      jsonb_build_object('nombre','Alquiler','pistas',''),
      jsonb_build_object('nombre','Sueldos','pistas','empleados, jornales'),
      jsonb_build_object('nombre','Impuestos','pistas',''),
      jsonb_build_object('nombre','Otros','pistas',''))
  end;
$fn$;

-- Los permisos, los mismos de siempre (021, 097): la lista la lee también
-- quien todavía no tiene cuenta, al elegir rubro. `create or replace` ya
-- los conserva; se escriben igual para que esta migración se lea sola.
grant execute on function public.categorias_de_rubro(text, text) to anon, authenticated;


-- ############################################################
-- ##  102_planes_por_rubro_y_comision.sql
-- ############################################################

-- ============================================================
-- 102 · CADA RUBRO CON SUS PLANES, Y LA COMISIÓN SOBRE EL PRECIO DE LISTA
-- ============================================================
--
-- Dos decisiones de Matías del 23/09/2026 (CONTRATO-102, §1 y §3). No se
-- re-discuten; acá queda el porqué para quien venga después.
--
-- 1. CADA RUBRO OFRECE SOLO LOS PLANES QUE LE SIRVEN
--
-- Hasta hoy todo negocio veía Básico, Pro y Premium. Pro y Premium venden
-- GENTE cargando a la vez —vendedores, cajeros, encargados—. Un profe de
-- inglés o un personal trainer trabajan solos: ofrecerles pagar por
-- vendedores que nunca van a tener es venderles aire, y lo único que logra
-- es que el precio que sí les sirve parezca el «barato», el de segunda.
--
--     comercio, servicios        básico, pro, premium (negocio)
--     clases, entrenamiento      básico
--     agricultura, ganadería     básico, pro  (el dueño y un par de encargados)
--     cuenta personal            pro, como hoy (su único plan pago)
--
-- Lo que NO cambia, y es a propósito: el sistema de planes sigue siendo UNO.
-- Los mismos precios (`precios`), los mismos topes (`limites_plan`), las
-- mismas sillas (048). Esta migración no toca un solo precio ni un solo
-- tope: solo dice cuáles se ofrecen a quién.
--
-- La tabla vive dos veces, en `planes_de_rubro()` acá y en `FichaRubro.planes`
-- de src/lib/rubros.ts, igual que `dias_de_prueba()` y `DIAS_DE_PRUEBA`. Una
-- prueba compara las dos, rubro por rubro, y falla si se separan.
--
-- LA PRUEBA ARRANCA EN UN PLAN QUE SE PUEDE COMPRAR
--
-- Desde la 009 toda cuenta nace en prueba de Pro. Con la tabla nueva eso
-- sería una trampa para el profe: ocho días con tres personas y 600
-- capturas, y el día nueve le ofrecemos un plan de una persona y 300. Lo
-- que probó no existe para él. Por eso `plan_de_prueba()`: Pro si su rubro
-- lo ofrece —el más completo que se vende por igual a casi todos—, y si no,
-- el más alto de su lista (clases y entrenamiento → básico). La cuenta
-- personal sigue con lo de hoy: Pro.
--
-- `crear_empresa` y `cambiar_rubro` son copia EXACTA de su versión viva
-- (verificada en producción con pg_get_functiondef) con UNA diferencia cada
-- una:
--
--   · `crear_empresa`: la suscripción de prueba nace en
--     `plan_de_prueba(v_rubro, v_tipo)` en vez de 'pro'. `empresas.plan`
--     sigue diciendo 'pro': es el campo viejo de «tiene acceso», y
--     `cambiar_plan_cuenta` también escribe 'pro' ahí para cualquier plan
--     pago. El plan de verdad sale de `suscripciones` (plan_efectivo).
--   · `cambiar_rubro`: si la cuenta está EN PRUEBA, la prueba pasa al plan
--     de prueba del rubro nuevo. Un comercio que se da cuenta de que es un
--     profe no puede seguir probando algo que no se le va a vender. Una
--     suscripción paga NUNCA se toca: el que pagó Pro lo sigue teniendo,
--     aunque su rubro nuevo no lo ofrezca (la pantalla lo muestra como su
--     plan actual). No se le cambian las fechas a la prueba: el rubro cambia
--     qué se prueba, no cuánto dura.
--
-- 2. LA COMISIÓN DEL SOCIO: LA MITAD DEL PRECIO DE LISTA DE UN MES
--
-- Hasta hoy (060, 063, 068) la comisión era la mitad de LO QUE ENTRÓ en el
-- primer pago. Dos bordes que Matías no quiere:
--
--   · El que pagó con el descuento de la prueba (078) dejaba al socio con la
--     mitad de un precio rebajado: el socio pagaba un descuento que no dio.
--   · El que pagó el año entero de una le dejaba al socio la mitad de once
--     meses. Había que ajustarla a mano, y a mano se olvida.
--
-- La regla nueva es un número que el socio puede saber de antemano: la
-- mitad del precio de lista MENSUAL del plan que se activó, del tipo de
-- cuenta de la empresa, en la moneda del cobro. Sin sillas extra: el
-- precio de lista del plan. Si pagó el año, la base igual es UN mes.
--
-- LA MONEDA DEL COBRO: `suscripciones.moneda`; si es null, LA DE LA
-- EMPRESA (`empresas.moneda`); recién después, guaraníes. El contrato
-- decía «null = guaraníes», pero en producción `suscripciones.moneda` es
-- null en TODAS las suscripciones: solo la escribe el webhook de la
-- pasarela (009), que hoy no se usa, y `cambiar_plan_cuenta` (el cobro por
-- transferencia, el único camino real) nunca la toca. Con «null =
-- guaraníes» a secas, una cuenta argentina que paga Premium con 60.000 ARS
-- tomaba de base el precio en guaraníes (250.000); la mitad, 125.000,
-- quedaba topada en 60.000 y el socio se llevaba EL 100 % de lo que entró.
-- Un cliente en dólares que paga 32 dejaba 32 en vez de 16. La empresa sí
-- sabe en qué moneda trabaja: el que factura en pesos paga en pesos. Una
-- moneda sin precio de lista (ARS hoy) cae en la regla de antes: base =
-- importe, la mitad de lo que entró.
--
-- Lo que NO cambia:
--
--   · Cuándo nace: con el primer pago, una sola vez por negocio (el índice
--     único de `comisiones`), y se cae si el cobro se anula (063).
--   · La salvaguarda, ahora explícita: nunca más de lo que entró. Un cobro
--     de prueba de 1.000 no genera una comisión de 55.000.
--   · Si no hay precio de lista para ese plan en esa moneda, la base es el
--     importe, como hasta hoy. Mejor una comisión como la de antes que
--     ninguna.
--
-- `base` guarda el precio de lista (lo que se tomó de base); `monto`, lo
-- calculado. El redondeo sigue la moneda: guaraníes sin decimales, el resto
-- con dos. `precios.activo` no se mira a propósito: un precio que se dejó
-- de ofrecer sigue siendo el precio de lista del que ya lo compró.
--
-- La regla vive en dos helpers internos —`base_de_comision` y
-- `monto_de_comision`— porque la comisión nace en DOS lugares:
-- `cambiar_plan_cuenta` (el cobro, 063) y `asignar_referido` (el código que
-- se había perdido, 068). Se verificó en producción que no hay otra función
-- que inserte en `comisiones` (pg_proc, prosrc). Las dos se redefinen como
-- copia exacta de lo vivo usando los helpers, que nadie de afuera puede
-- llamar (revocados a public, anon y authenticated). `asignar_referido`
-- saca el plan del primer pago del mismo renglón de `registro_admin` de
-- donde ya sacaba el importe (`plan_despues`).
--
-- UNA CORRECCIÓN QUE VA DE PASO: `cambiar_plan_cuenta` NO CONOCÍA EL BÁSICO
--
-- La 077 creó el plan Básico y el panel de administración lo ofrece, pero
-- `cambiar_plan_cuenta` (063, viva) seguía aceptando solo gratis, pro y
-- negocio: activar un Básico por transferencia terminaba en «Plan
-- desconocido: basico». Con esta migración un profe o un trainer SOLO
-- pueden comprar Básico, así que dejarlo así era dejarlos sin forma de
-- pagar. Es la única línea que cambia en esa función además de la comisión.
-- ============================================================

-- ------------------------------------------------------------
-- 1. QUÉ PLANES SE LE OFRECEN A CADA RUBRO
--
--    Espejo de `FichaRubro.planes` en src/lib/rubros.ts, en el mismo orden
--    (de menor a mayor). Un rubro desconocido o null cae en comercio, igual
--    que `fichaDe()`. `immutable` y sin leer tablas, como `dias_de_prueba`:
--    la pantalla de planes la puede preguntar antes de iniciar sesión.
-- ------------------------------------------------------------
create or replace function public.planes_de_rubro(
  p_rubro text,
  p_tipo_cuenta text default 'emprendedor'
)
returns text[] language sql immutable set search_path = public as $fn$
  select case
    -- La cuenta personal ya es de una sola persona y tiene su propio precio.
    when coalesce(p_tipo_cuenta, 'emprendedor') = 'personal' then array['pro']
    -- Trabajan solos: pagar por vendedores sería pagar por aire.
    when p_rubro in ('clases', 'entrenamiento') then array['basico']
    -- El dueño y un par de encargados; nadie tiene quince en el campo.
    when p_rubro in ('agricultura', 'ganaderia') then array['basico', 'pro']
    else array['basico', 'pro', 'negocio']
  end;
$fn$;

grant execute on function public.planes_de_rubro(text, text) to anon, authenticated;

-- ------------------------------------------------------------
-- 2. EN QUÉ PLAN ARRANCA LA PRUEBA
--
--    Pro si el rubro lo ofrece; si no, el más alto de su lista. Nunca un
--    plan que después no se le pueda vender.
-- ------------------------------------------------------------
create or replace function public.plan_de_prueba(
  p_rubro text,
  p_tipo_cuenta text default 'emprendedor'
)
returns text language sql immutable set search_path = public as $fn$
  select case
    when 'pro' = any (l) then 'pro'
    else l[array_length(l, 1)]
  end
  from (select public.planes_de_rubro(p_rubro, p_tipo_cuenta) as l) x;
$fn$;

grant execute on function public.plan_de_prueba(text, text) to anon, authenticated;

-- ------------------------------------------------------------
-- 3. CREAR LA EMPRESA: LA PRUEBA EN EL PLAN DE SU RUBRO
--
--    Copia exacta de la viva (087) con una sola línea cambiada: el plan de
--    la suscripción de prueba.
-- ------------------------------------------------------------
create or replace function public.crear_empresa(
  p_nombre text,
  p_moneda text default 'PYG',
  p_nombre_usuario text default null,
  p_zona text default 'America/Asuncion',
  p_tipo_cuenta text default 'emprendedor',
  p_rubro text default 'comercio',
  p_como_nos_conocio text default '',
  p_telefono text default '',
  p_se_dedica text default ''
)
returns uuid language plpgsql security definer set search_path = public as $fn$
declare
  v_id uuid;
  v_codigo text;
  v_intentos int := 0;
  v_fin timestamptz;
  v_tipo text;
  v_rubro text;
  v_contacto text;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;

  if char_length(trim(coalesce(p_nombre, ''))) < 2 then
    raise exception 'El nombre del negocio es muy corto.' using errcode = '22023';
  end if;

  v_tipo := case when p_tipo_cuenta = 'personal' then 'personal' else 'emprendedor' end;
  v_rubro := case
    when v_tipo = 'personal' then 'comercio'
    when p_rubro = any (public.rubros_validos()) then p_rubro
    else 'comercio' end;

  loop
    v_codigo := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
    exit when not exists (select 1 from public.empresa_accesos where codigo = v_codigo);
    v_intentos := v_intentos + 1;
    if v_intentos > 12 then
      raise exception 'No se pudo generar un código de acceso.' using errcode = '55000';
    end if;
  end loop;

  insert into public.empresas (
    nombre, moneda, creada_por, zona_horaria, tipo_cuenta, rubro, como_nos_conocio)
  values (trim(p_nombre), coalesce(p_moneda, 'PYG'), auth.uid(),
          coalesce(nullif(trim(p_zona), ''), 'America/Asuncion'), v_tipo, v_rubro,
          left(coalesce(p_como_nos_conocio, ''), 80))
  returning id into v_id;

  v_contacto := nullif(trim(coalesce(p_nombre_usuario, '')), '');

  insert into public.miembros (empresa_id, user_id, nombre, rol)
  values (v_id, auth.uid(), coalesce(v_contacto, 'Propietario'), 'propietario');

  insert into public.empresa_accesos (empresa_id, codigo) values (v_id, v_codigo);

  if v_contacto is not null
     or nullif(trim(coalesce(p_telefono, '')), '') is not null
     or nullif(trim(coalesce(p_se_dedica, '')), '') is not null then
    insert into public.ficha_cliente (empresa_id, contacto, telefono, se_dedica, updated_at)
    values (v_id,
            left(coalesce(v_contacto, ''), 120),
            left(regexp_replace(coalesce(p_telefono, ''), '[^0-9+]', '', 'g'), 40),
            left(coalesce(trim(p_se_dedica), ''), 200),
            now())
    on conflict (empresa_id) do nothing;
  end if;

  v_fin := now() + make_interval(days => public.dias_de_prueba(v_tipo));
  insert into public.suscripciones (empresa_id, plan, estado, periodo_inicio, periodo_fin, prueba_fin)
  values (v_id, public.plan_de_prueba(v_rubro, v_tipo), 'prueba', now(), v_fin, v_fin);

  perform set_config('orden.suscripcion_confiable', '1', true);
  update public.empresas set plan = 'pro' where id = v_id;
  perform set_config('orden.suscripcion_confiable', '0', true);

  return v_id;
end $fn$;

revoke all on function public.crear_empresa(text, text, text, text, text, text, text, text, text)
  from public, anon;
grant execute on function public.crear_empresa(text, text, text, text, text, text, text, text, text)
  to authenticated;

-- ------------------------------------------------------------
-- 4. CAMBIAR DE RUBRO: LA PRUEBA SE MUDA CON ÉL
--
--    Copia exacta de la viva (087) más el ajuste de la prueba. Solo
--    `estado = 'prueba'`: una suscripción paga no se toca nunca.
-- ------------------------------------------------------------
create or replace function public.cambiar_rubro(p_empresa uuid, p_rubro text)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_antes text;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el propietario o un administrador puede cambiar el rubro.'
      using errcode = '42501';
  end if;

  if not (p_rubro = any (public.rubros_validos())) then
    raise exception 'Rubro desconocido: %', p_rubro using errcode = '22023';
  end if;

  select rubro into v_antes from public.empresas where id = p_empresa;
  if v_antes is null then
    raise exception 'Esa empresa no existe.' using errcode = 'P0002';
  end if;

  update public.empresas set rubro = p_rubro where id = p_empresa;

  -- La prueba se muda con el rubro: nadie prueba un plan que después no se
  -- le va a ofrecer. Lo pago no se toca nunca.
  update public.suscripciones s
  set plan = public.plan_de_prueba(p_rubro, e.tipo_cuenta),
      updated_at = now()
  from public.empresas e
  where s.empresa_id = p_empresa
    and e.id = p_empresa
    and s.estado = 'prueba';

  return jsonb_build_object('rubro', p_rubro, 'antes', v_antes);
end $fn$;

revoke all on function public.cambiar_rubro(uuid, text) from public, anon;
grant execute on function public.cambiar_rubro(uuid, text) to authenticated;

-- ------------------------------------------------------------
-- 5. LA BASE DE LA COMISIÓN: EL PRECIO DE LISTA DE UN MES
--
--    El precio mensual del plan, del tipo de cuenta de la empresa, en la
--    moneda del cobro: la de la suscripción; si es null, la de la empresa;
--    si no, guaraníes (ver la cabecera: la de la suscripción hoy es siempre
--    null). Si no hay precio de lista para esa combinación, el importe: la
--    regla de antes.
--
--    `security definer` porque la llaman funciones que ya lo son y tiene
--    que leer `suscripciones` sin depender de quién mira; revocada a todos
--    porque no es una puerta: es una cuenta interna.
-- ------------------------------------------------------------
create or replace function public.base_de_comision(
  p_empresa uuid,
  p_plan    text,
  p_importe numeric
)
returns numeric language sql stable security definer set search_path = public as $fn$
  select coalesce((
    select pr.importe
    from public.empresas e
    left join public.suscripciones s on s.empresa_id = e.id
    join public.precios pr
      on pr.tipo_cuenta = e.tipo_cuenta
     and pr.plan = p_plan
     and pr.moneda = coalesce(s.moneda, e.moneda, 'PYG')
     and pr.periodo = 'mensual'
    where e.id = p_empresa
    limit 1
  ), p_importe);
$fn$;

-- ------------------------------------------------------------
-- 6. EL MONTO: EL PORCENTAJE DE LA BASE, NUNCA MÁS DE LO QUE ENTRÓ
--
--    Guaraníes sin decimales (como siempre); el resto con dos, porque la
--    mitad de 19 dólares son 9,50 y no 10. La moneda sale igual que en
--    `base_de_comision`: la de la suscripción, la de la empresa, guaraníes.
-- ------------------------------------------------------------
create or replace function public.monto_de_comision(
  p_empresa uuid,
  p_base    numeric,
  p_pct     numeric,
  p_importe numeric
)
returns numeric language sql stable security definer set search_path = public as $fn$
  select least(
    round(p_base * p_pct / 100,
      case when coalesce((select coalesce(s.moneda, e.moneda)
                          from public.empresas e
                          left join public.suscripciones s on s.empresa_id = e.id
                          where e.id = p_empresa), 'PYG') = 'PYG'
           then 0 else 2 end),
    p_importe
  );
$fn$;

revoke all on function public.base_de_comision(uuid, text, numeric) from public, anon, authenticated;
revoke all on function public.monto_de_comision(uuid, numeric, numeric, numeric) from public, anon, authenticated;

-- ------------------------------------------------------------
-- 7. EL COBRO (063): LA COMISIÓN SOBRE EL PRECIO DE LISTA
--
--    Copia exacta de la viva. Cambian dos cosas: acepta 'basico' (ver la
--    cabecera) y la comisión usa los helpers de arriba.
-- ------------------------------------------------------------
create or replace function public.cambiar_plan_cuenta(
  p_empresa    uuid,
  p_plan       text,
  p_meses      integer default 1,
  p_nota       text default '',
  p_importe    numeric default null,
  p_vendedores integer default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_antes    public.suscripciones;
  v_fin      timestamptz;
  v_estado   text;
  v_orden    uuid;
  v_cliente  text;
  v_ingreso  uuid;
  v_aviso    text := null;
  v_tope     integer;
  v_personas integer;
  v_socio    uuid;
  v_pct      numeric;
  v_comision boolean := false;
  v_base     numeric;
begin
  if not public.es_superadmin() then
    raise exception 'Este panel es solo para la administración de Orden.' using errcode = '42501';
  end if;

  -- 'basico' faltaba desde la 077 (ver la cabecera de la 102).
  if p_plan not in ('gratis', 'basico', 'pro', 'negocio') then
    raise exception 'Plan desconocido: %', p_plan using errcode = '22023';
  end if;

  if p_vendedores is not null and p_vendedores < -1 then
    raise exception 'El tope de vendedores no puede ser negativo.' using errcode = '22023';
  end if;

  select * into v_antes from public.suscripciones where empresa_id = p_empresa;
  if v_antes.empresa_id is null then
    raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
  end if;

  select nombre into v_cliente from public.empresas where id = p_empresa;

  if p_plan = 'gratis' then
    v_estado := 'vencida';
    v_fin := now();
    -- Cortar el servicio borra el trato: si vuelve, se negocia de nuevo.
    v_tope := null;
  else
    v_estado := 'activa';
    -- Si todavía le queda tiempo pago, se le suma; si no, arranca hoy.
    v_fin := greatest(coalesce(v_antes.periodo_fin, now()), now())
             + make_interval(months => greatest(1, coalesce(p_meses, 1)));
    v_tope := case
      when p_vendedores is null then v_antes.tope_vendedores  -- no se toca
      when p_vendedores = -1    then null                     -- volver al plan
      else p_vendedores
    end;
  end if;

  update public.suscripciones
  set plan = p_plan,
      estado = v_estado,
      periodo_inicio = case when p_plan = 'gratis' then periodo_inicio else now() end,
      periodo_fin = v_fin,
      tope_vendedores = v_tope,
      proveedor_pago = case when p_plan = 'gratis' then proveedor_pago else 'transferencia' end,
      updated_at = now()
  where empresa_id = p_empresa;

  perform set_config('orden.suscripcion_confiable', '1', true);
  update public.empresas
  set plan = case when p_plan = 'gratis' then 'gratis' else 'pro' end
  where id = p_empresa;
  perform set_config('orden.suscripcion_confiable', '0', true);

  -- ---- ¿le queda gente afuera del tope nuevo? ----
  --
  -- No se echa a nadie: bajar un número en un panel no puede sacarle el
  -- acceso a una persona que hoy está trabajando. Pero hay que decirlo, o
  -- el que lo bajó se entera cuando el cliente reclama.
  if v_tope is not null then
    select count(*)::int into v_personas from public.miembros where empresa_id = p_empresa;
    if v_personas > v_tope + 1 then
      v_aviso := 'Ojo: este negocio ya tiene ' || v_personas || ' personas y le habilitaste '
              || v_tope || ' vendedores (' || (v_tope + 1) || ' con el dueño). '
              || 'No se sacó a nadie, pero no va a poder sumar a nadie más.';
    end if;
  end if;

  -- ---- el cobro, como ingreso de Orden ----
  if p_plan <> 'gratis' and coalesce(p_importe, 0) > 0 then
    select empresa_id into v_orden from public.ajustes_orden where unica;

    if v_orden is null then
      v_aviso := coalesce(v_aviso || ' ', '')
              || 'No hay una empresa de Orden elegida, así que el cobro no se anotó en tus finanzas.';
    elsif v_orden = p_empresa then
      v_aviso := coalesce(v_aviso || ' ', '')
              || 'Esta ES tu empresa, así que no se anotó ningún ingreso.';
    else
      begin
        insert into public.movimientos (
          empresa_id, tipo, estado, fecha, descripcion, categoria,
          subtotal, descuento, monto, costo_total, metodo_pago, contraparte, creado_por
        ) values (
          v_orden, 'ingreso', 'activo', public.hoy_empresa(v_orden),
          'Suscripción ' || coalesce(v_cliente, 'cliente'), 'Suscripciones',
          p_importe, 0, p_importe, 0, 'transferencia',
          left(coalesce(v_cliente, ''), 80), auth.uid()
        )
        returning id into v_ingreso;
      exception when others then
        v_aviso := coalesce(v_aviso || ' ', '')
                || 'La cuenta se activó, pero el ingreso no se pudo anotar: ' || sqlerrm;
      end;
    end if;
  end if;

  -- ---- la comisión de quien trajo al cliente (060, corregida acá) ----
  -- Nace cuando se cobra, una sola vez por negocio, y eso lo garantiza el
  -- índice único de comisiones y no el acordarse.
  --
  -- Antes colgaba de que el ingreso se hubiera podido anotar, y eso costó
  -- una comisión de verdad: la empresa que representaba a Orden estaba
  -- borrada, el ingreso no se pudo escribir, y el socio se quedó sin nada
  -- por un problema de contabilidad que no tenía nada que ver con él.
  --
  -- La señal de que entró plata no es la fila del libro: es que una
  -- persona escribió un importe porque vio la transferencia. Eso es lo
  -- que se mira. El movimiento se guarda si existe, y puede ser null.
  if p_plan <> 'gratis' and coalesce(p_importe, 0) > 0 then
    select r.socio_id into v_socio
    from public.referidos r
    join public.socios s on s.id = r.socio_id
    where r.empresa_id = p_empresa and s.activo;

    if v_socio is not null then
      select coalesce(a.comision_porcentaje, 50) into v_pct
      from public.ajustes_orden a where a.unica;

      -- Desde la 102: la mitad del precio de lista de un mes del plan que
      -- se activó, nunca más de lo que entró.
      v_base := public.base_de_comision(p_empresa, p_plan, p_importe);

      begin
        insert into public.comisiones (
          socio_id, empresa_id, movimiento_id, base, porcentaje, monto
        ) values (
          v_socio, p_empresa, v_ingreso, v_base, coalesce(v_pct, 50),
          public.monto_de_comision(p_empresa, v_base, coalesce(v_pct, 50), p_importe)
        );
        v_comision := true;
      exception when unique_violation then
        -- Ya cobró por este negocio. Se paga una sola vez: el primer pago.
        null;
      end;
    end if;
  end if;

  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (auth.uid(), p_empresa, 'cambiar_plan', jsonb_build_object(
    'plan_antes', v_antes.plan, 'plan_despues', p_plan,
    'estado_antes', v_antes.estado, 'estado_despues', v_estado,
    'vence_antes', v_antes.periodo_fin, 'vence_despues', v_fin,
    'meses', greatest(1, coalesce(p_meses, 1)),
    'importe', p_importe,
    'tope_antes', v_antes.tope_vendedores,
    'tope_despues', v_tope,
    'ingreso_id', v_ingreso,
    'nota', left(coalesce(p_nota, ''), 300)
  ));

  return jsonb_build_object(
    'plan', p_plan, 'estado', v_estado, 'periodo_fin', v_fin,
    'tope_vendedores', v_tope,
    'personas_permitidas', public.tope_de_miembros(p_empresa),
    'ingreso_anotado', v_ingreso is not null,
    'comision_generada', v_comision,
    'aviso', v_aviso
  );
end $fn$;

revoke all on function public.cambiar_plan_cuenta(uuid, text, integer, text, numeric, integer) from public, anon;
grant execute on function public.cambiar_plan_cuenta(uuid, text, integer, text, numeric, integer) to authenticated;

-- ------------------------------------------------------------
-- 8. EL CÓDIGO QUE SE HABÍA PERDIDO (068): LA MISMA REGLA
--
--    Copia exacta de la viva. La comisión del primer pago sale del plan de
--    ese pago (`plan_despues` del mismo renglón del registro) y de los
--    helpers de arriba.
-- ------------------------------------------------------------
create or replace function public.asignar_referido(
  p_empresa uuid,
  p_codigo  text,
  p_nota    text default ''
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_socio      public.socios;
  v_ya         uuid;
  v_pagos      integer;
  v_aviso      text := null;
  v_rechazo    public.codigos_rechazados;
  v_por_enlace boolean := false;
  v_primero    record;
  v_pct        numeric;
  v_comision   boolean := false;
  v_base       numeric;
begin
  if not public.es_superadmin() then
    raise exception 'Esto es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select * into v_socio from public.socios
  where codigo = upper(trim(coalesce(p_codigo, '')));

  if v_socio.id is null then
    raise exception 'No hay ningún socio con ese código.' using errcode = '22023';
  end if;

  if not v_socio.activo then
    raise exception '% está desactivado como socio. Activalo en «Socios» y volvé a anotarlo.',
      v_socio.nombre using errcode = '22023';
  end if;

  if not exists (select 1 from public.empresas where id = p_empresa) then
    raise exception 'Ese negocio no existe.' using errcode = '22023';
  end if;

  if v_socio.user_id is not null and exists (
    select 1 from public.miembros m
    where m.empresa_id = p_empresa and m.user_id = v_socio.user_id
  ) then
    raise exception
      '% trabaja en ese negocio: no se cobra comisión por traerse a uno mismo.',
      v_socio.nombre using errcode = '22023';
  end if;

  select socio_id into v_ya from public.referidos where empresa_id = p_empresa;

  if v_ya is not null then
    if v_ya = v_socio.id then
      return jsonb_build_object(
        'ok', true, 'socio', v_socio.nombre,
        'aviso', 'Ya estaba anotado a nombre de ' || v_socio.nombre || '.'
      );
    end if;
    raise exception
      'Ese negocio ya está anotado a nombre de %. Se cuenta una sola vez y no se cambia.',
      coalesce((select nombre from public.socios where id = v_ya), 'otra persona')
      using errcode = '22023';
  end if;

  -- ¿Esta cuenta intentó entrar con ESTE código y se lo rechazaron?
  select * into v_rechazo from public.codigos_rechazados where empresa_id = p_empresa;
  v_por_enlace := v_rechazo.empresa_id is not null and v_rechazo.codigo = v_socio.codigo;

  -- «Ya pagó» se mide por el importe, no por el asiento (ver arriba).
  select count(*)::int into v_pagos
  from public.registro_admin r
  where r.empresa_id = p_empresa
    and r.accion = 'cambiar_plan'
    and coalesce(r.detalle->>'importe', '') ~ '^[0-9]+(\.[0-9]+)?$'
    and (r.detalle->>'importe')::numeric > 0;

  insert into public.referidos (empresa_id, socio_id, origen, nota, creado_por)
  values (
    p_empresa, v_socio.id,
    case when v_por_enlace then 'link' else 'a_mano' end,
    left(coalesce(p_nota, ''), 300), auth.uid()
  );

  if v_por_enlace and v_pagos > 0 then
    -- Entró con el enlace antes de pagar: la comisión del primer pago es
    -- suya, igual que si el código no se hubiera perdido. El primero y no
    -- el último, por la misma razón que en la 063.
    select (ra.detalle->>'importe')::numeric as importe,
           nullif(ra.detalle->>'ingreso_id', '')::uuid as ingreso,
           ra.detalle->>'plan_despues' as plan,
           ra.created_at
    into v_primero
    from public.registro_admin ra
    where ra.empresa_id = p_empresa
      and ra.accion = 'cambiar_plan'
      and coalesce(ra.detalle->>'importe', '') ~ '^[0-9]+(\.[0-9]+)?$'
      and (ra.detalle->>'importe')::numeric > 0
    order by ra.created_at
    limit 1;

    select coalesce(a.comision_porcentaje, 50) into v_pct from public.ajustes_orden a where a.unica;
    v_pct := coalesce(v_pct, 50);

    -- Desde la 102: el precio de lista del plan de ESE primer pago.
    v_base := public.base_de_comision(p_empresa, v_primero.plan, v_primero.importe);

    begin
      insert into public.comisiones (
        socio_id, empresa_id, movimiento_id, base, porcentaje, monto, nota
      ) values (
        v_socio.id, p_empresa, v_primero.ingreso, v_base, v_pct,
        public.monto_de_comision(p_empresa, v_base, v_pct, v_primero.importe),
        'Entró con el enlace el ' || to_char(v_rechazo.intentado_at at time zone 'America/Asuncion', 'DD/MM/YYYY')
          || ', pero el código fue rechazado (' || coalesce(nullif(v_rechazo.motivo, ''), 'sin motivo') || ') y se anotó después.'
      );
      v_comision := true;
      v_aviso := 'Entró con este código y se había perdido. Se generó la comisión por su primer pago.';
    exception when unique_violation then
      v_aviso := 'Entró con este código y se había perdido. Ya tenía una comisión, así que no se generó otra.';
    end;
  elsif v_por_enlace then
    v_aviso := 'Entró con este código y se había perdido. Cuando pague, la comisión sale sola.';
  elsif v_pagos > 0 then
    v_aviso := 'Ojo: este negocio ya pagó ' || v_pagos
            || (case when v_pagos = 1 then ' vez' else ' veces' end)
            || ' antes de anotarlo. La comisión no se genera por esos pagos, sino con el próximo cobro. Revisá el monto antes de pagarla.';
  end if;

  -- Resuelto: el rechazo deja de figurar.
  delete from public.codigos_rechazados where empresa_id = p_empresa;

  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (auth.uid(), p_empresa, 'asignar_referido', jsonb_build_object(
    'socio_id', v_socio.id, 'socio', v_socio.nombre, 'codigo', v_socio.codigo,
    'pagos_previos', v_pagos, 'por_enlace', v_por_enlace, 'comision_generada', v_comision
  ));

  return jsonb_build_object(
    'ok', true, 'socio', v_socio.nombre, 'aviso', v_aviso,
    'por_enlace', v_por_enlace, 'comision_generada', v_comision
  );
end $fn$;

revoke all on function public.asignar_referido(uuid, text, text) from public, anon;
grant execute on function public.asignar_referido(uuid, text, text) to authenticated;


-- ############################################################
-- ##  103_la_comision_guarda_lo_que_entro.sql
-- ############################################################

-- ============================================================
-- 103 · LA COMISIÓN GUARDA LO QUE ENTRÓ
-- ============================================================
--
-- La 102 cambió de dónde sale la comisión del socio: la mitad del precio de
-- lista de UN mes del plan, y no de lo que entró. Para eso `comisiones.base`
-- pasó a guardar el precio de lista, y `monto` = least(base × % / 100,
-- importe). La regla está bien y no se toca. Lo que se perdió en el camino
-- es otro número: cuánta plata entró de verdad.
--
-- HASTA LA 102, `base` ERA LO QUE PAGÓ EL CLIENTE
--
-- Desde la 060 `base` era el importe del cobro, y el panel de la
-- administración (src/components/PanelSocios.tsx) lo usaba así: «pagó
-- {base}» y, al lado de la comisión, «te queda {base − monto}», lo que le
-- queda a Orden de ese pago. Con la 102 esas dos líneas empezaron a mentir
-- sin que nada fallara:
--
--     Básico con el descuento de la prueba (078)
--       entró              90.200
--       base (la lista)   110.000
--       comisión           55.000
--       el panel decía    «pagó 110.000 · te queda 55.000»
--       la verdad          pagó 90.200 · te quedan 35.200
--
-- Con el año pagado de una miente al revés: entran 1.210.000, el panel
-- dice «pagó 110.000 · te queda 55.000», y a Orden le quedan 1.155.000.
--
-- Y la tabla ya no tenía de dónde sacarlo: el importe no se guardaba en
-- ningún otro lado de `comisiones`, porque hasta la 102 ERA `base`.
--
-- UNA COLUMNA MÁS, NO OTRA CUENTA
--
-- `importe` guarda lo que entró en el cobro que generó la comisión: el
-- mismo número que alguien escribió en el panel porque vio la
-- transferencia (`p_importe`). Quedan tres números, cada uno con su nombre:
--
--     importe   lo que entró                    (esta migración)
--     base      el precio de lista de un mes    (102)
--     monto     lo que se lleva el socio        (060, 102)
--
-- No se recalcula nada: ni la base ni el monto de ninguna comisión cambian.
--
-- Nace en los mismos dos lugares que la comisión (la 102 verificó en
-- producción que no hay un tercero): `cambiar_plan_cuenta` guarda
-- `p_importe`, y `asignar_referido` el importe del primer pago
-- (`v_primero.importe`, del mismo renglón del registro del que ya sacaba el
-- plan y el ingreso). Las dos son copia EXACTA de la versión viva (la de la
-- 102, verificada en producción con pg_get_functiondef) con esa sola columna
-- de más en el insert. `listar_comisiones` (066, viva, también verificada)
-- devuelve `importe` al lado de `base`, y nada más cambia.
--
-- LAS QUE YA EXISTEN
--
-- En producción hoy hay cero comisiones, pero una migración sirve para
-- cualquier base. El importe se reconstruye así, del dato más seguro al
-- menos:
--
--   1. El renglón de `registro_admin` de ESE cobro: el 'cambiar_plan' de la
--      misma empresa cuyo `ingreso_id` es el `movimiento_id` de la
--      comisión, o el que se escribió en la misma transacción (misma
--      `created_at`: `cambiar_plan_cuenta` escribe la comisión y el
--      registro en la misma llamada, y `now()` es el de la transacción).
--      El registro no se edita nunca: es el número que se escribió.
--   2. Si la comisión nació en `asignar_referido` (hay un renglón
--      'asignar_referido' de esa empresa con `comision_generada`), el
--      primer 'cambiar_plan' con importe > 0: el mismo criterio con el que
--      esa función eligió el pago (068, 102).
--   3. El `monto` del ingreso de Orden que la originó (`movimiento_id`).
--      Va último porque un movimiento se puede editar y el registro no.
--
-- El criterio 2 NO se usa para cualquier comisión: una que nació en
-- `cambiar_plan_cuenta` pudo nacer en el segundo o el tercer pago (el
-- socio se anotó tarde: grupo 4 de pruebas/comisiones.test.js), y el primer
-- pago sería otro número. Mejor null que un número equivocado con cara de
-- cierto.
--
-- Lo que no se puede reconstruir queda en null, y el panel cae en `base`,
-- como hasta hoy. Para una comisión anterior a la 102 eso es exacto (ahí
-- `base` ERA lo que entró); para una posterior es lo mismo que ya mostraba.
-- El relleno solo toca las que tienen `importe` null: correrlo dos veces
-- no cambia nada.
--
-- QUIÉN VE ESTO: LOS MISMOS DE HOY
--
-- `comisiones` no tiene ningún permiso para anon ni authenticated: la 060
-- hizo `revoke all` y nunca hubo grants por columna (verificado en
-- producción con information_schema.column_privileges). La columna nueva
-- no se abre a nadie; se lee solo por función, y `listar_comisiones` es
-- solo de la administración (`es_superadmin`).
--
-- El socio NO ve cuánto pagó el negocio que trajo, y sigue sin verlo:
-- `mi_panel_socio` (070, viva) le devuelve el monto de SU comisión y ni
-- siquiera la base, así que no se toca. `listar_referidos` devuelve `base`,
-- también solo a la administración, y el panel no la muestra: tampoco se
-- toca.
-- ============================================================

-- ------------------------------------------------------------
-- 1. LA COLUMNA
--
--    Null en las viejas que no se puedan reconstruir (ver la cabecera).
--    Misma precisión y misma regla que `base` y `monto`: nunca negativa.
-- ------------------------------------------------------------
alter table public.comisiones
  add column if not exists importe numeric(14,2) check (importe >= 0);

comment on column public.comisiones.importe is
  'Lo que entró en el cobro que generó la comisión (103). base = precio de lista de un mes (102); monto = lo del socio.';

-- ------------------------------------------------------------
-- 2. EL RELLENO DE LAS QUE YA EXISTEN
--
--    En el orden de la cabecera: el registro de ESE cobro, el primer pago
--    si nació en `asignar_referido`, el ingreso de Orden. Solo las que
--    tienen `importe` null.
-- ------------------------------------------------------------
update public.comisiones c
set importe = coalesce(
  -- 1. El renglón del registro de ese mismo cobro.
  (select (ra.detalle->>'importe')::numeric
   from public.registro_admin ra
   where ra.empresa_id = c.empresa_id
     and ra.accion = 'cambiar_plan'
     and coalesce(ra.detalle->>'importe', '') ~ '^[0-9]+(\.[0-9]+)?$'
     and (ra.detalle->>'importe')::numeric > 0
     and ((c.movimiento_id is not null
           and ra.detalle->>'ingreso_id' = c.movimiento_id::text)
          or ra.created_at = c.created_at)
   order by ra.created_at
   limit 1),
  -- 2. Nació al anotar un código perdido: el primer pago, como en la 068.
  (select (ra.detalle->>'importe')::numeric
   from public.registro_admin ra
   where ra.empresa_id = c.empresa_id
     and ra.accion = 'cambiar_plan'
     and coalesce(ra.detalle->>'importe', '') ~ '^[0-9]+(\.[0-9]+)?$'
     and (ra.detalle->>'importe')::numeric > 0
     and exists (
       select 1 from public.registro_admin rr
       where rr.empresa_id = c.empresa_id
         and rr.accion = 'asignar_referido'
         and rr.detalle->>'comision_generada' = 'true'
     )
   order by ra.created_at
   limit 1),
  -- 3. El ingreso de Orden que la originó.
  (select mv.monto from public.movimientos mv where mv.id = c.movimiento_id)
)
where c.importe is null;

-- ------------------------------------------------------------
-- 3. EL COBRO (063, 102): LA COMISIÓN GUARDA LO QUE ENTRÓ
--
--    Copia exacta de la viva (102). Cambia solo el insert de la comisión:
--    una columna más, `importe`, con `p_importe`.
-- ------------------------------------------------------------
create or replace function public.cambiar_plan_cuenta(
  p_empresa    uuid,
  p_plan       text,
  p_meses      integer default 1,
  p_nota       text default '',
  p_importe    numeric default null,
  p_vendedores integer default null
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_antes    public.suscripciones;
  v_fin      timestamptz;
  v_estado   text;
  v_orden    uuid;
  v_cliente  text;
  v_ingreso  uuid;
  v_aviso    text := null;
  v_tope     integer;
  v_personas integer;
  v_socio    uuid;
  v_pct      numeric;
  v_comision boolean := false;
  v_base     numeric;
begin
  if not public.es_superadmin() then
    raise exception 'Este panel es solo para la administración de Orden.' using errcode = '42501';
  end if;

  -- 'basico' faltaba desde la 077 (ver la cabecera de la 102).
  if p_plan not in ('gratis', 'basico', 'pro', 'negocio') then
    raise exception 'Plan desconocido: %', p_plan using errcode = '22023';
  end if;

  if p_vendedores is not null and p_vendedores < -1 then
    raise exception 'El tope de vendedores no puede ser negativo.' using errcode = '22023';
  end if;

  select * into v_antes from public.suscripciones where empresa_id = p_empresa;
  if v_antes.empresa_id is null then
    raise exception 'Esa cuenta no existe.' using errcode = 'P0002';
  end if;

  select nombre into v_cliente from public.empresas where id = p_empresa;

  if p_plan = 'gratis' then
    v_estado := 'vencida';
    v_fin := now();
    -- Cortar el servicio borra el trato: si vuelve, se negocia de nuevo.
    v_tope := null;
  else
    v_estado := 'activa';
    -- Si todavía le queda tiempo pago, se le suma; si no, arranca hoy.
    v_fin := greatest(coalesce(v_antes.periodo_fin, now()), now())
             + make_interval(months => greatest(1, coalesce(p_meses, 1)));
    v_tope := case
      when p_vendedores is null then v_antes.tope_vendedores  -- no se toca
      when p_vendedores = -1    then null                     -- volver al plan
      else p_vendedores
    end;
  end if;

  update public.suscripciones
  set plan = p_plan,
      estado = v_estado,
      periodo_inicio = case when p_plan = 'gratis' then periodo_inicio else now() end,
      periodo_fin = v_fin,
      tope_vendedores = v_tope,
      proveedor_pago = case when p_plan = 'gratis' then proveedor_pago else 'transferencia' end,
      updated_at = now()
  where empresa_id = p_empresa;

  perform set_config('orden.suscripcion_confiable', '1', true);
  update public.empresas
  set plan = case when p_plan = 'gratis' then 'gratis' else 'pro' end
  where id = p_empresa;
  perform set_config('orden.suscripcion_confiable', '0', true);

  -- ---- ¿le queda gente afuera del tope nuevo? ----
  --
  -- No se echa a nadie: bajar un número en un panel no puede sacarle el
  -- acceso a una persona que hoy está trabajando. Pero hay que decirlo, o
  -- el que lo bajó se entera cuando el cliente reclama.
  if v_tope is not null then
    select count(*)::int into v_personas from public.miembros where empresa_id = p_empresa;
    if v_personas > v_tope + 1 then
      v_aviso := 'Ojo: este negocio ya tiene ' || v_personas || ' personas y le habilitaste '
              || v_tope || ' vendedores (' || (v_tope + 1) || ' con el dueño). '
              || 'No se sacó a nadie, pero no va a poder sumar a nadie más.';
    end if;
  end if;

  -- ---- el cobro, como ingreso de Orden ----
  if p_plan <> 'gratis' and coalesce(p_importe, 0) > 0 then
    select empresa_id into v_orden from public.ajustes_orden where unica;

    if v_orden is null then
      v_aviso := coalesce(v_aviso || ' ', '')
              || 'No hay una empresa de Orden elegida, así que el cobro no se anotó en tus finanzas.';
    elsif v_orden = p_empresa then
      v_aviso := coalesce(v_aviso || ' ', '')
              || 'Esta ES tu empresa, así que no se anotó ningún ingreso.';
    else
      begin
        insert into public.movimientos (
          empresa_id, tipo, estado, fecha, descripcion, categoria,
          subtotal, descuento, monto, costo_total, metodo_pago, contraparte, creado_por
        ) values (
          v_orden, 'ingreso', 'activo', public.hoy_empresa(v_orden),
          'Suscripción ' || coalesce(v_cliente, 'cliente'), 'Suscripciones',
          p_importe, 0, p_importe, 0, 'transferencia',
          left(coalesce(v_cliente, ''), 80), auth.uid()
        )
        returning id into v_ingreso;
      exception when others then
        v_aviso := coalesce(v_aviso || ' ', '')
                || 'La cuenta se activó, pero el ingreso no se pudo anotar: ' || sqlerrm;
      end;
    end if;
  end if;

  -- ---- la comisión de quien trajo al cliente (060, corregida acá) ----
  -- Nace cuando se cobra, una sola vez por negocio, y eso lo garantiza el
  -- índice único de comisiones y no el acordarse.
  --
  -- Antes colgaba de que el ingreso se hubiera podido anotar, y eso costó
  -- una comisión de verdad: la empresa que representaba a Orden estaba
  -- borrada, el ingreso no se pudo escribir, y el socio se quedó sin nada
  -- por un problema de contabilidad que no tenía nada que ver con él.
  --
  -- La señal de que entró plata no es la fila del libro: es que una
  -- persona escribió un importe porque vio la transferencia. Eso es lo
  -- que se mira. El movimiento se guarda si existe, y puede ser null.
  if p_plan <> 'gratis' and coalesce(p_importe, 0) > 0 then
    select r.socio_id into v_socio
    from public.referidos r
    join public.socios s on s.id = r.socio_id
    where r.empresa_id = p_empresa and s.activo;

    if v_socio is not null then
      select coalesce(a.comision_porcentaje, 50) into v_pct
      from public.ajustes_orden a where a.unica;

      -- Desde la 102: la mitad del precio de lista de un mes del plan que
      -- se activó, nunca más de lo que entró.
      v_base := public.base_de_comision(p_empresa, p_plan, p_importe);

      begin
        -- Desde la 103: y lo que entró de verdad, que ya no es la base.
        insert into public.comisiones (
          socio_id, empresa_id, movimiento_id, base, porcentaje, monto, importe
        ) values (
          v_socio, p_empresa, v_ingreso, v_base, coalesce(v_pct, 50),
          public.monto_de_comision(p_empresa, v_base, coalesce(v_pct, 50), p_importe),
          p_importe
        );
        v_comision := true;
      exception when unique_violation then
        -- Ya cobró por este negocio. Se paga una sola vez: el primer pago.
        null;
      end;
    end if;
  end if;

  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (auth.uid(), p_empresa, 'cambiar_plan', jsonb_build_object(
    'plan_antes', v_antes.plan, 'plan_despues', p_plan,
    'estado_antes', v_antes.estado, 'estado_despues', v_estado,
    'vence_antes', v_antes.periodo_fin, 'vence_despues', v_fin,
    'meses', greatest(1, coalesce(p_meses, 1)),
    'importe', p_importe,
    'tope_antes', v_antes.tope_vendedores,
    'tope_despues', v_tope,
    'ingreso_id', v_ingreso,
    'nota', left(coalesce(p_nota, ''), 300)
  ));

  return jsonb_build_object(
    'plan', p_plan, 'estado', v_estado, 'periodo_fin', v_fin,
    'tope_vendedores', v_tope,
    'personas_permitidas', public.tope_de_miembros(p_empresa),
    'ingreso_anotado', v_ingreso is not null,
    'comision_generada', v_comision,
    'aviso', v_aviso
  );
end $fn$;

-- ------------------------------------------------------------
-- 4. EL CÓDIGO QUE SE HABÍA PERDIDO (068, 102): LO MISMO
--
--    Copia exacta de la viva (102). Cambia solo el insert de la comisión:
--    `importe` es el del primer pago, del mismo renglón del registro del
--    que ya salen el plan y el ingreso (`v_primero.importe`).
-- ------------------------------------------------------------
create or replace function public.asignar_referido(
  p_empresa uuid,
  p_codigo  text,
  p_nota    text default ''
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_socio      public.socios;
  v_ya         uuid;
  v_pagos      integer;
  v_aviso      text := null;
  v_rechazo    public.codigos_rechazados;
  v_por_enlace boolean := false;
  v_primero    record;
  v_pct        numeric;
  v_comision   boolean := false;
  v_base       numeric;
begin
  if not public.es_superadmin() then
    raise exception 'Esto es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select * into v_socio from public.socios
  where codigo = upper(trim(coalesce(p_codigo, '')));

  if v_socio.id is null then
    raise exception 'No hay ningún socio con ese código.' using errcode = '22023';
  end if;

  if not v_socio.activo then
    raise exception '% está desactivado como socio. Activalo en «Socios» y volvé a anotarlo.',
      v_socio.nombre using errcode = '22023';
  end if;

  if not exists (select 1 from public.empresas where id = p_empresa) then
    raise exception 'Ese negocio no existe.' using errcode = '22023';
  end if;

  if v_socio.user_id is not null and exists (
    select 1 from public.miembros m
    where m.empresa_id = p_empresa and m.user_id = v_socio.user_id
  ) then
    raise exception
      '% trabaja en ese negocio: no se cobra comisión por traerse a uno mismo.',
      v_socio.nombre using errcode = '22023';
  end if;

  select socio_id into v_ya from public.referidos where empresa_id = p_empresa;

  if v_ya is not null then
    if v_ya = v_socio.id then
      return jsonb_build_object(
        'ok', true, 'socio', v_socio.nombre,
        'aviso', 'Ya estaba anotado a nombre de ' || v_socio.nombre || '.'
      );
    end if;
    raise exception
      'Ese negocio ya está anotado a nombre de %. Se cuenta una sola vez y no se cambia.',
      coalesce((select nombre from public.socios where id = v_ya), 'otra persona')
      using errcode = '22023';
  end if;

  -- ¿Esta cuenta intentó entrar con ESTE código y se lo rechazaron?
  select * into v_rechazo from public.codigos_rechazados where empresa_id = p_empresa;
  v_por_enlace := v_rechazo.empresa_id is not null and v_rechazo.codigo = v_socio.codigo;

  -- «Ya pagó» se mide por el importe, no por el asiento (ver arriba).
  select count(*)::int into v_pagos
  from public.registro_admin r
  where r.empresa_id = p_empresa
    and r.accion = 'cambiar_plan'
    and coalesce(r.detalle->>'importe', '') ~ '^[0-9]+(\.[0-9]+)?$'
    and (r.detalle->>'importe')::numeric > 0;

  insert into public.referidos (empresa_id, socio_id, origen, nota, creado_por)
  values (
    p_empresa, v_socio.id,
    case when v_por_enlace then 'link' else 'a_mano' end,
    left(coalesce(p_nota, ''), 300), auth.uid()
  );

  if v_por_enlace and v_pagos > 0 then
    -- Entró con el enlace antes de pagar: la comisión del primer pago es
    -- suya, igual que si el código no se hubiera perdido. El primero y no
    -- el último, por la misma razón que en la 063.
    select (ra.detalle->>'importe')::numeric as importe,
           nullif(ra.detalle->>'ingreso_id', '')::uuid as ingreso,
           ra.detalle->>'plan_despues' as plan,
           ra.created_at
    into v_primero
    from public.registro_admin ra
    where ra.empresa_id = p_empresa
      and ra.accion = 'cambiar_plan'
      and coalesce(ra.detalle->>'importe', '') ~ '^[0-9]+(\.[0-9]+)?$'
      and (ra.detalle->>'importe')::numeric > 0
    order by ra.created_at
    limit 1;

    select coalesce(a.comision_porcentaje, 50) into v_pct from public.ajustes_orden a where a.unica;
    v_pct := coalesce(v_pct, 50);

    -- Desde la 102: el precio de lista del plan de ESE primer pago.
    v_base := public.base_de_comision(p_empresa, v_primero.plan, v_primero.importe);

    begin
      -- Desde la 103: y lo que entró en ese primer pago.
      insert into public.comisiones (
        socio_id, empresa_id, movimiento_id, base, porcentaje, monto, importe, nota
      ) values (
        v_socio.id, p_empresa, v_primero.ingreso, v_base, v_pct,
        public.monto_de_comision(p_empresa, v_base, v_pct, v_primero.importe),
        v_primero.importe,
        'Entró con el enlace el ' || to_char(v_rechazo.intentado_at at time zone 'America/Asuncion', 'DD/MM/YYYY')
          || ', pero el código fue rechazado (' || coalesce(nullif(v_rechazo.motivo, ''), 'sin motivo') || ') y se anotó después.'
      );
      v_comision := true;
      v_aviso := 'Entró con este código y se había perdido. Se generó la comisión por su primer pago.';
    exception when unique_violation then
      v_aviso := 'Entró con este código y se había perdido. Ya tenía una comisión, así que no se generó otra.';
    end;
  elsif v_por_enlace then
    v_aviso := 'Entró con este código y se había perdido. Cuando pague, la comisión sale sola.';
  elsif v_pagos > 0 then
    v_aviso := 'Ojo: este negocio ya pagó ' || v_pagos
            || (case when v_pagos = 1 then ' vez' else ' veces' end)
            || ' antes de anotarlo. La comisión no se genera por esos pagos, sino con el próximo cobro. Revisá el monto antes de pagarla.';
  end if;

  -- Resuelto: el rechazo deja de figurar.
  delete from public.codigos_rechazados where empresa_id = p_empresa;

  insert into public.registro_admin (actor_id, empresa_id, accion, detalle)
  values (auth.uid(), p_empresa, 'asignar_referido', jsonb_build_object(
    'socio_id', v_socio.id, 'socio', v_socio.nombre, 'codigo', v_socio.codigo,
    'pagos_previos', v_pagos, 'por_enlace', v_por_enlace, 'comision_generada', v_comision
  ));

  return jsonb_build_object(
    'ok', true, 'socio', v_socio.nombre, 'aviso', v_aviso,
    'por_enlace', v_por_enlace, 'comision_generada', v_comision
  );
end $fn$;

-- ------------------------------------------------------------
-- 5. LA LISTA DE LA ADMINISTRACIÓN (066): TAMBIÉN EL IMPORTE
--
--    Copia exacta de la viva (066) sumando 'importe' al lado de 'base'. Es
--    lo que el panel necesita para decir cuánto pagó el cliente y cuánto le
--    queda a Orden sin confundirlo con el precio de lista.
-- ------------------------------------------------------------
create or replace function public.listar_comisiones(
  p_estado text default null,
  p_socio  uuid default null,
  p_limite integer default 200
)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_res jsonb;
begin
  if not public.es_superadmin() then
    raise exception 'Esto es solo para la administración de Orden.' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(x order by x->>'creado' desc), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'id',         c.id,
      'socio_id',   c.socio_id,
      'socio',      s.nombre,
      'telefono',   s.telefono,
      'cobra_en',   s.cobra_en,
      'banco',      s.banco,
      'titular',    s.titular,
      'cuenta',     s.cuenta,
      'documento',  s.documento,
      'empresa_id', c.empresa_id,
      'negocio',    coalesce(e.nombre, 'Negocio borrado'),
      'base',       c.base,
      'importe',    c.importe,
      'porcentaje', c.porcentaje,
      'monto',      c.monto,
      'estado',     c.estado,
      'creado',     c.created_at,
      'pagada_at',  c.pagada_at,
      'solicitada_at', c.solicitada_at,
      'medio',      c.medio,
      'nota',       c.nota,
      'ingreso_anulado', coalesce(mv.estado::text, '') = 'anulado'
    ) as x
    from public.comisiones c
    join public.socios s on s.id = c.socio_id
    left join public.empresas e on e.id = c.empresa_id
    left join public.movimientos mv on mv.id = c.movimiento_id
    where (p_estado is null or trim(p_estado) = '' or c.estado = p_estado)
      and (p_socio is null or c.socio_id = p_socio)
    order by c.created_at desc
    limit greatest(1, least(coalesce(p_limite, 200), 500))
  ) t;

  return v_res;
end $fn$;

-- ------------------------------------------------------------
-- 6. PERMISOS
--
--    Las mismas firmas: `create or replace` conserva los permisos, pero se
--    reescriben igual, como en la 102 y la 066, para que este archivo diga
--    por sí solo quién puede llamar cada una.
-- ------------------------------------------------------------
revoke all on function public.cambiar_plan_cuenta(uuid, text, integer, text, numeric, integer) from public, anon;
grant execute on function public.cambiar_plan_cuenta(uuid, text, integer, text, numeric, integer) to authenticated;

revoke all on function public.asignar_referido(uuid, text, text) from public, anon;
grant execute on function public.asignar_referido(uuid, text, text) to authenticated;

revoke all on function public.listar_comisiones(text, uuid, integer) from public, anon;
grant execute on function public.listar_comisiones(text, uuid, integer) to authenticated;


-- ############################################################
-- ##  104_la_tarjeta_conoce_el_basico.sql
-- ############################################################

-- ============================================================
-- 104 · LA TARJETA CONOCE EL BÁSICO
-- ============================================================
--
-- `aplicar_suscripcion` es la única puerta por la que un pago con tarjeta
-- cambia el plan de una cuenta: la llama el webhook de la pasarela
-- (src/app/api/pagos/webhook/route.ts) con el rol service_role, nunca el
-- navegador. Hoy la pasarela está apagada y se cobra por transferencia
-- (`cambiar_plan_cuenta`, desde el panel de la administración). Esta
-- migración deja la puerta de la tarjeta a la par de la de la
-- transferencia en dos cosas que se le habían quedado atrás.
--
-- 1. EL BÁSICO ERA UN «PLAN DESCONOCIDO»
--
-- La versión viva (la de la 009, verificada en producción el 23/09 con
-- pg_get_functiondef) dice:
--
--     if p_plan not in ('gratis', 'pro', 'negocio') then
--       raise exception 'Plan desconocido: %' ...
--
-- El Básico nació en la 077, que se lo enseñó a las tablas; a
-- `cambiar_plan_cuenta` se lo enseñó la 102, y esta función quedó con la
-- lista vieja (la 009 es la última que la redefinió). Desde la 102 hay
-- rubros que SOLO pueden tener Básico (docentes y trainers), así que el día
-- que se prenda la pasarela un profe que paga con tarjeta rebotaría con un
-- error, después de que Stripe le cobró. Stripe reintentaría el evento
-- durante días y todos rebotarían igual: el error no es de red, es de la
-- lista.
--
-- Se agrega 'basico' a la lista y nada más. Las tres constraints que tienen
-- la palabra —empresas_plan_check, suscripciones_plan_check y
-- precios_plan_check— se verificaron en producción el 23/09 y ya aceptan
-- 'basico' (lo hizo la 077): no se tocan.
--
-- Un detalle que queda como estaba, a propósito: esta función escribe en
-- `empresas.plan` el plan tal cual (Básico queda 'basico'), mientras que
-- `cambiar_plan_cuenta` escribe 'pro' para cualquier plan pago. Lo que
-- manda de verdad es `suscripciones.plan` (plan_efectivo_calculado,
-- tope_de_miembros, limites_plan), y ahí las dos escriben el plan real. No
-- es trabajo de esta migración emparejar esa columna vieja.
--
-- 2. LA COMISIÓN DEL SOCIO SOLO NACÍA POR TRANSFERENCIA
--
-- Desde la 060 la comisión de quien trajo al cliente nace en dos lugares:
-- `cambiar_plan_cuenta` (cuando se cobra) y `asignar_referido` (cuando el
-- código se había perdido y se anota después del primer pago). Por tarjeta
-- no nacía nunca: un negocio que un socio trajo y que pagó con tarjeta le
-- dejaba cero al socio, sin error y sin aviso. Lo mismo que la 063 corrigió
-- para la transferencia, con otra causa.
--
-- Acá nace con las MISMAS reglas que `cambiar_plan_cuenta` en la 103
-- (versión viva, verificada en producción con pg_get_functiondef):
--
--   · Solo si entró plata: plan distinto de 'gratis' e importe > 0. Y, como
--     esta puerta también recibe estados que no son un cobro, solo con
--     estado 'activa'. Una 'prueba' (trialing de Stripe), una 'morosa' (la
--     tarjeta rebotó), una 'cancelada' o una 'vencida' no son plata que
--     entró. Cuando termina la prueba y Stripe cobra de verdad, el evento
--     llega con 'activa' y ahí nace.
--
--   · Solo si la empresa tiene un referido con un socio activo.
--
--   · base   = base_de_comision(empresa, plan, importe): el precio de lista
--              de UN mes del plan (102).
--     monto  = monto_de_comision(empresa, base, %, importe): el porcentaje
--              de la base, nunca más de lo que entró (102).
--     importe = lo que entró en este cobro (103).
--
--     Las dos funciones miran la moneda de la suscripción antes que la de
--     la empresa. Por eso el bloque va DESPUÉS del upsert: para cuando se
--     calcula, `suscripciones.moneda` ya es la moneda del pago (`p_moneda`).
--     Un negocio en guaraníes que paga en dólares con tarjeta recibe una
--     base de 19 (la lista en USD) y un monto de 9,50, y no una base de
--     110.000 comparada contra un importe de 19.
--
--   · Una sola vez por negocio, y eso lo garantiza el índice único de
--     `comisiones` sobre `empresa_id`, no el acordarse. Esto importa más
--     acá que en la transferencia: Stripe manda un
--     `customer.subscription.updated` en cada renovación, cada cambio de
--     plan y cada cambio de tarjeta, todos con estado 'activa' y el importe
--     del precio. El primero que llega con plata crea la comisión; los
--     demás chocan con el índice y no pasa nada. Si el negocio ya había
--     pagado por transferencia y generado la suya, la tarjeta tampoco crea
--     otra.
--
-- Una diferencia con `cambiar_plan_cuenta`, y es a propósito: allá solo se
-- ataja el choque con el índice (`unique_violation`); cualquier otro error
-- tira abajo todo el cambio de plan, y eso está bien porque del otro lado
-- hay una persona mirando el panel que ve el error y lo arregla. Acá del
-- otro lado hay un webhook: si la comisión fallara por cualquier otra cosa,
-- el cliente que YA pagó se quedaría sin su plan, y Stripe reintentaría el
-- mismo evento durante días con el mismo resultado. El que pagó no puede
-- quedar afuera por un problema entre Orden y el socio. Entonces otro
-- error en la comisión no frena la activación: deja un WARNING en el log
-- de Postgres con la empresa y el motivo, para que se pague a mano.
--
-- 3. EL COBRO NO SE ANOTA COMO INGRESO DE ORDEN, TODAVÍA
--
-- `cambiar_plan_cuenta` además anota el cobro como un ingreso en la
-- empresa de Orden (`ajustes_orden.empresa_id`), y la comisión guarda ese
-- movimiento. `aplicar_suscripcion` no lo hizo nunca, y esta migración NO
-- lo agrega: es otra decisión (con qué método de pago, si el importe es
-- bruto o neto de lo que se queda Stripe, qué pasa con los reembolsos y
-- con cada renovación, que sí es un ingreso cada mes) y merece su propia
-- migración con sus propias pruebas. Por eso la comisión que nace acá
-- lleva `movimiento_id` en null, como las que nacen por transferencia
-- cuando no hay empresa de Orden elegida (063): listar_comisiones y el
-- panel ya saben mostrarla.
--
-- La consecuencia, para que nadie se sorprenda: una comisión nacida por
-- tarjeta no se cae sola si el cobro se anula (eso cuelga del movimiento,
-- 060) y hay que anularla a mano si hay un reembolso.
--
-- LO QUE NO CAMBIA
--
-- Todo lo demás es copia EXACTA de la versión viva: la firma de 11
-- argumentos, los estados, el upsert, `orden.suscripcion_confiable`, que
-- no devuelve nada, y que es exclusiva de service_role. Los permisos se
-- reescriben igual (misma firma: `create or replace` los conserva), para
-- que este archivo diga por sí solo quién puede llamarla.
--
-- No hay mensajes nuevos: 'Plan desconocido: %' y 'Estado desconocido: %'
-- ya tienen su portugués en src/lib/mensajes-base.ts.
--
-- Idempotente: son un `create or replace` y un revoke/grant.
-- ============================================================

create or replace function public.aplicar_suscripcion(
  p_empresa uuid,
  p_plan text,
  p_estado text default 'activa',
  p_periodo_inicio timestamptz default null,
  p_periodo_fin timestamptz default null,
  p_proveedor text default null,
  p_customer_id text default null,
  p_subscription_id text default null,
  p_periodo text default 'mensual',
  p_moneda text default null,
  p_importe numeric default null
)
returns void language plpgsql security definer set search_path = public as $fn$
declare
  v_socio uuid;
  v_pct   numeric;
  v_base  numeric;
begin
  -- 'basico' faltaba desde la 077 (ver la cabecera de la 104).
  if p_plan not in ('gratis', 'basico', 'pro', 'negocio') then
    raise exception 'Plan desconocido: %', p_plan using errcode = '22023';
  end if;
  if p_estado not in ('activa', 'prueba', 'vencida', 'cancelada', 'morosa') then
    raise exception 'Estado desconocido: %', p_estado using errcode = '22023';
  end if;

  insert into public.suscripciones (
    empresa_id, plan, estado, periodo_inicio, periodo_fin,
    proveedor_pago, customer_id_externo, subscription_id_externo,
    periodo, moneda, importe, updated_at
  )
  values (p_empresa, p_plan, p_estado, p_periodo_inicio, p_periodo_fin,
          p_proveedor, p_customer_id, p_subscription_id,
          coalesce(p_periodo, 'mensual'), p_moneda, p_importe, now())
  on conflict (empresa_id) do update set
    plan = excluded.plan,
    estado = excluded.estado,
    periodo_inicio = excluded.periodo_inicio,
    periodo_fin = excluded.periodo_fin,
    proveedor_pago = coalesce(excluded.proveedor_pago, public.suscripciones.proveedor_pago),
    customer_id_externo = coalesce(excluded.customer_id_externo, public.suscripciones.customer_id_externo),
    subscription_id_externo = coalesce(excluded.subscription_id_externo, public.suscripciones.subscription_id_externo),
    periodo = coalesce(excluded.periodo, public.suscripciones.periodo),
    moneda = coalesce(excluded.moneda, public.suscripciones.moneda),
    importe = coalesce(excluded.importe, public.suscripciones.importe),
    cancela_al_vencer = (excluded.estado = 'cancelada'),
    updated_at = now();

  perform set_config('orden.suscripcion_confiable', '1', true);
  update public.empresas set plan = p_plan where id = p_empresa;
  perform set_config('orden.suscripcion_confiable', '0', true);

  -- ---- la comisión de quien trajo al cliente (104) ----
  -- Las mismas reglas que cambiar_plan_cuenta (103): solo si entró plata,
  -- la mitad del precio de lista de un mes, nunca más de lo que entró, y
  -- una sola vez por negocio por el índice único. Va después del upsert
  -- para que base y monto usen la moneda del pago.
  if p_estado = 'activa' and p_plan <> 'gratis' and coalesce(p_importe, 0) > 0 then
    select r.socio_id into v_socio
    from public.referidos r
    join public.socios s on s.id = r.socio_id
    where r.empresa_id = p_empresa and s.activo;

    if v_socio is not null then
      select coalesce(a.comision_porcentaje, 50) into v_pct
      from public.ajustes_orden a where a.unica;

      begin
        v_base := public.base_de_comision(p_empresa, p_plan, p_importe);

        -- Sin movimiento: la tarjeta todavía no anota el ingreso de Orden.
        insert into public.comisiones (
          socio_id, empresa_id, movimiento_id, base, porcentaje, monto, importe
        ) values (
          v_socio, p_empresa, null, v_base, coalesce(v_pct, 50),
          public.monto_de_comision(p_empresa, v_base, coalesce(v_pct, 50), p_importe),
          p_importe
        );
      exception
        when unique_violation then
          -- Ya cobró por este negocio (una renovación, o pagó antes por
          -- transferencia). Se paga una sola vez: el primer pago.
          null;
        when others then
          -- El que pagó no se queda sin su plan por la comisión: se avisa
          -- en el log y se paga a mano.
          raise warning 'aplicar_suscripcion: la comisión de la empresa % no se pudo generar: %',
            p_empresa, sqlerrm;
      end;
    end if;
  end if;
end $fn$;

revoke all on function public.aplicar_suscripcion(
  uuid, text, text, timestamptz, timestamptz, text, text, text, text, text, numeric)
  from public, anon, authenticated;
grant execute on function public.aplicar_suscripcion(
  uuid, text, text, timestamptz, timestamptz, text, text, text, text, text, numeric)
  to service_role;


-- ############################################################
-- ##  105_la_comision_en_guaranies.sql
-- ############################################################

-- ============================================================
-- 105 · LA COMISIÓN EN GUARANÍES
-- ============================================================
--
-- Decisión de Matías del 23/09/2026 (no se re-discute): la suscripción de
-- Orden se cobra SIEMPRE en guaraníes. Bancard le permite una sola moneda
-- y eligió guaraníes. En pantalla el precio grande va en guaraníes, con un
-- «≈ US$ 19» chico de referencia que no se cobra, y el que tiene una
-- tarjeta de otro país deja que su banco convierta. Los precios no
-- cambian: las filas en USD de `precios` siguen ahí, como referencia.
--
-- Esta migración lleva esa decisión a la comisión del socio. La regla de
-- la 102 no cambia —la mitad del precio de lista de UN mes del plan, nunca
-- más de lo que entró (103)—; cambia de qué moneda se toma esa lista.
--
-- LO QUE HACÍA LA 102, Y POR QUÉ ESTABA BIEN EN SU MOMENTO
--
-- `base_de_comision` y `monto_de_comision` elegían la moneda así:
--
--     coalesce(suscripciones.moneda, empresas.moneda, 'PYG')
--
-- En producción `suscripciones.moneda` es null en TODAS las suscripciones
-- (verificado el 23/09: 7 de 7). Solo la escribe `aplicar_suscripcion`, la
-- puerta de la pasarela, que hoy está apagada; `cambiar_plan_cuenta`, el
-- cobro por transferencia —el único camino real—, nunca la toca. Con
-- «null = guaraníes» a secas, la 102 temía esto: una cuenta argentina que
-- paga Premium con 60.000 ARS tomaba de base la lista en guaraníes
-- (250.000); la mitad, 125.000, quedaba topada en los 60.000 que entraron y
-- el socio se llevaba EL 100 % del cobro. Para evitarlo, la 102 supuso que
-- el que lleva su negocio en pesos paga en pesos, y cayó en
-- `empresas.moneda`.
--
-- POR QUÉ YA NO APLICA
--
-- Desde el 23/09 esa suposición es falsa: nadie paga en su moneda, todos
-- pagan en guaraníes. `empresas.moneda` dice en qué moneda LLEVA SUS
-- CUENTAS el negocio, no en qué moneda le paga a Orden. Y caer en ella
-- ahora da el error al revés, que es peor:
--
--     un sojero que lleva el campo en dólares paga Básico por transferencia
--       entró              90.200 Gs (con el descuento de la prueba, 078)
--       moneda elegida     USD (la de la empresa: suscripciones.moneda null)
--       base               19        (la lista de Básico en USD)
--       monto              9,50      (la mitad, con centavos)
--       y el monto se guarda sin moneda, al lado de un importe en guaraníes:
--       el socio cobraría 9,50 GUARANÍES por un cliente que pagó 90.200.
--
-- Lo correcto es base 110.000 y monto 55.000: la lista de Básico en la
-- moneda en que entró la plata.
--
-- LA REGLA NUEVA: `coalesce(suscripciones.moneda, 'PYG')`
--
--   · null —todo cobro por transferencia, que es hoy el 100 %— es
--     guaraníes, porque así se cobra.
--   · Si algún día un cobro llega en otra moneda, lo dice
--     `suscripciones.moneda`, y la escribe la pasarela: `aplicar_suscripcion`
--     (104, verificada en producción el 23/09 con pg_get_functiondef) hace
--     el upsert con `moneda = coalesce(p_moneda, la de antes)` ANTES de
--     calcular base y monto, así que la comisión usa la moneda del pago que
--     la generó. Una suscripción con moneda USD explícita sigue tomando la
--     lista en USD (19, 32, 42) y redondeando con centavos.
--   · `empresas.moneda` ya no se mira. El caso que la 102 cuidaba (un
--     argentino que paga 60.000 PESOS) no puede pasar por transferencia:
--     paga en guaraníes. Y si pagara 60.000 guaraníes por un Premium de
--     250.000 —un cobro parcial o de prueba—, la base es 250.000, la mitad
--     125.000 y el monto queda topado en los 60.000 que entraron: es la
--     salvaguarda de siempre (102), la misma que con 1.000 de prueba en una
--     cuenta en guaraníes, y no depende de la moneda de la empresa.
--
-- Si no hay precio de lista para esa moneda (BRL, ARS hoy), la base sigue
-- siendo el importe, como desde la 102. El redondeo sigue la moneda
-- elegida: guaraníes sin decimales, el resto con dos.
--
-- LOS QUE LLAMAN A ESTAS FUNCIONES NO CAMBIAN
--
-- Se verificó en producción (pg_proc, prosrc) que solo las llaman tres
-- funciones, y ninguna necesita tocarse:
--
--   · `cambiar_plan_cuenta` (103): no escribe `suscripciones.moneda`; con
--     la regla nueva, null = guaraníes, que es como se cobró.
--   · `asignar_referido` (103): mismo caso; el primer pago salió de
--     `registro_admin`, es decir, de una transferencia.
--   · `aplicar_suscripcion` (104): escribe la moneda del pago antes de
--     calcular (ver arriba).
--
-- NADA QUE CORREGIR HACIA ATRÁS
--
-- En producción la tabla `comisiones` está vacía (verificado el 23/09): no
-- hay ninguna comisión calculada con la moneda de la empresa que haya que
-- rehacer.
--
-- LO QUE NO CAMBIA
--
-- Todo lo demás es copia EXACTA de lo vivo (la 102, verificada en
-- producción el 23/09 con pg_get_functiondef): las firmas, `language sql
-- stable security definer`, el `search_path`, el left join a
-- `suscripciones` (una empresa sin fila de suscripción cae en guaraníes),
-- el tipo de cuenta, el período mensual, `precios.activo` sin mirar, el
-- `least(..., p_importe)`, y que son internas: revocadas a public, anon y
-- authenticated. Los permisos se reescriben igual (mismas firmas:
-- `create or replace` los conserva) para que este archivo diga por sí solo
-- quién puede llamarlas.
--
-- No hay mensajes nuevos: estas funciones no lanzan errores.
--
-- Idempotente: son dos `create or replace` y dos revoke.
-- ============================================================

-- ------------------------------------------------------------
-- 1. LA BASE: EL PRECIO DE LISTA DE UN MES, EN LA MONEDA DEL COBRO
--
--    La moneda del cobro es la de la suscripción; si es null, guaraníes
--    (105: antes caía en la de la empresa). Si no hay precio de lista para
--    esa combinación, el importe: la regla de antes.
-- ------------------------------------------------------------
create or replace function public.base_de_comision(
  p_empresa uuid,
  p_plan    text,
  p_importe numeric
)
returns numeric language sql stable security definer set search_path = public as $fn$
  select coalesce((
    select pr.importe
    from public.empresas e
    left join public.suscripciones s on s.empresa_id = e.id
    join public.precios pr
      on pr.tipo_cuenta = e.tipo_cuenta
     and pr.plan = p_plan
     and pr.moneda = coalesce(s.moneda, 'PYG')
     and pr.periodo = 'mensual'
    where e.id = p_empresa
    limit 1
  ), p_importe);
$fn$;

-- ------------------------------------------------------------
-- 2. EL MONTO: EL PORCENTAJE DE LA BASE, NUNCA MÁS DE LO QUE ENTRÓ
--
--    Guaraníes sin decimales; el resto con dos. La moneda sale igual que
--    en `base_de_comision`: la de la suscripción, y si no, guaraníes.
-- ------------------------------------------------------------
create or replace function public.monto_de_comision(
  p_empresa uuid,
  p_base    numeric,
  p_pct     numeric,
  p_importe numeric
)
returns numeric language sql stable security definer set search_path = public as $fn$
  select least(
    round(p_base * p_pct / 100,
      case when coalesce((select s.moneda
                          from public.empresas e
                          left join public.suscripciones s on s.empresa_id = e.id
                          where e.id = p_empresa), 'PYG') = 'PYG'
           then 0 else 2 end),
    p_importe
  );
$fn$;

revoke all on function public.base_de_comision(uuid, text, numeric) from public, anon, authenticated;
revoke all on function public.monto_de_comision(uuid, numeric, numeric, numeric) from public, anon, authenticated;


-- ############################################################
-- ##  106_reportes_por_rubro.sql
-- ############################################################

-- ============================================================
-- 106 · REPORTES POR RUBRO: PRIMERO, QUE LA PLATA NO MIENTA
-- ============================================================
--
-- Los reportes van a adaptarse a cada rubro (comercio, servicios, alumnos,
-- campo y la cuenta personal). Antes de dibujar nada nuevo, tres números de
-- la base estaban mal, y los tres salían también en el panel. Cada uno se
-- probó ANTES de arreglarlo (la primera parte de pruebas/reportes.test.js
-- falla contra la base sin esta migración: 27 de 44 comprobaciones; se
-- repite con REPORTES_SIN_106=1) y cada arreglo es copia
-- EXACTA de la versión viva (verificada en producción el 23/09/2026 con
-- pg_get_functiondef) más lo nuevo. Ninguna firma cambia.
--
-- 1. LA COMPRA DE MERCADERÍA RESTABA DOS VECES (decisión de Matías, 23/09)
--
--    `resumen_financiero` calcula  ventas − costo + otros ingresos − gastos,
--    y `gastos` sumaba también la categoría «Mercadería», que es la primera
--    que ofrece la pantalla de Gastos. Un almacén que compra 1.000.000 de
--    mercadería, la anota como gasto y la vende en 1.500.000 con el costo
--    cargado, ganó 500.000; el reporte decía −500.000: la mercadería restaba
--    como gasto el día de la compra Y como costo el día de la venta.
--
--    La regla (no se re-discute): en un período en que las ventas tienen
--    costo cargado, los gastos de la categoría «Mercadería» NO restan de la
--    ganancia; se devuelven aparte en `compras_mercaderia`, con
--    `mercaderia_aparte = true`. Si en el período no hay costo cargado,
--    siguen restando como siempre (si no, la mercadería no restaría nunca).
--
--    Qué cuenta como «costo cargado»: el costo de las ventas que NO son un
--    servicio del reparto (033). En una barbería a comisión la parte del
--    barbero se guarda como costo de la venta (034); eso no es mercadería, y
--    si contara, las ceras que compra el local dejarían de restar aunque las
--    venda sin costo. Así que el costo de un corte no enciende la regla.
--
--    La categoría se reconoce sin mayúsculas ni tilde: «Mercadería»,
--    «mercaderia» y la de portugués, «Mercadoria». La misma regla vive en
--    `src/lib/calculos.ts` (el espejo en TypeScript) y en la serie diaria:
--    la bandera es DEL PERÍODO, no de cada día, para que la suma de la serie
--    dé la misma ganancia que el resumen.
--
-- 2. EL PAGO AL PROFESIONAL A COMISIÓN RESTABA DOS VECES
--
--    Al cobrar un corte, la parte del barbero se guarda como costo de la
--    venta (034:285, 'costo_unitario' = su parte). Al pagarle,
--    `pagar_profesional` (035) crea además un gasto «Sueldos» por el mismo
--    monto. Un corte de 30.000 al 50 %, ya pagado, daba ganancia neta 0
--    cuando al local le quedaron 15.000.
--
--    El arreglo: el pago queda MARCADO, de forma explícita, en
--    `turnos_pago.de_comision` (columna nueva). No en `movimientos`, porque
--    ahí cualquier miembro inserta gastos a mano (policy de la 047) y podría
--    esconder un gasto de verdad; `turnos_pago` solo la escribe
--    `pagar_profesional`. Los pagos marcados:
--      · no entran en `gastos` de `resumen_financiero`, de la serie ni de
--        `gastos_por_categoria` (así la lista por categoría suma lo mismo
--        que el total);
--      · se devuelven aparte en `pagado_a_profesionales` (solo a
--        administración, como todo lo que es sueldo, 047);
--      · SÍ siguen siendo un gasto en el historial y en la billetera: la
--        plata sale de la caja igual.
--    Se marca el pago a quien cobra A COMISIÓN en el momento de pagar. El
--    sueldo fijo no es costo de ninguna venta: sigue restando. Los pagos que
--    ya existían se marcan una sola vez, al crear la columna, según el
--    arreglo que tiene hoy cada profesional (en producción hay cero pagos).
--
-- 3. EL QUE ALQUILA LA SILLA APARECÍA CON UNA DEUDA QUE NO EXISTE
--
--    En `registrar_servicio` el que alquila la silla se queda con el 100 %
--    y no se crea ninguna venta: la plata nunca pasó por el local. Aun así
--    `liquidacion` sumaba esos cortes en `le_toca`, y `le_debe` salía como
--    todo lo que facturó; la pantalla lo pintaba en rojo con un botón para
--    pagarle. Ahora `le_toca` (y `le_debe`) cuentan solo los cortes que
--    pasaron por la caja del local; lo que el que alquila cobró directo va
--    aparte en `cobro_directo`. Lo mismo en `mis_servicios`, la vista del
--    propio profesional, que le decía «te deben» por la misma plata.
--
-- LECTURAS NUEVAS POR PERÍODO (todas stable, security definer, sin anon)
--
--   · `pagina_movimientos`: copia exacta + cuenta, cliente, quién lo cargó,
--     lote y moneda original de cada movimiento (el Excel los pedía aparte).
--   · `reporte_turnos`: turnos del período por estado, origen, profesional,
--     servicio, y los clientes que más vuelven.
--   · `reporte_alumnos`: clases dadas y faltas desde `clases_dadas` (NO desde
--     turnos: `dar_clase` guarda clases sin turno), por semana, activos,
--     nuevos, paquetes vendidos/terminados/vencidos y cuántos renovaron,
--     por alumno, por paquete y por materia.
--   · `progreso_clientes`: el resumen de medidas del trainer (admin, como
--     las medidas, 098).
--   · `ventas_por_vendedor`: por quien cargó la venta (admin).
--   · `fiado_del_periodo`: lo que se fió y se cobró en el período.
--
-- Y EL AVISO DEL DÍA (080): el push de la mañana y el de la noche calculaban
-- la ganancia a mano y, con los arreglos 1 y 2, iban a decir otro número que
-- el panel. Ahora aplican la misma regla (sección 13).
--
-- Permisos, los de la 047: primera línea `es_miembro`/`es_admin`; costo,
-- margen y sueldos le llegan en null a un vendedor; nada abierto a anon.
-- Lo que te deben los alumnos (`reporte_alumnos`: por cobrar y fiado) lo
-- ve cualquier miembro, igual que en `por_cobrar_alumnos` y `resumen_fiado`
-- vivas: es plata que entra, no una deuda del negocio ni un sueldo.
-- Idempotente: se puede aplicar dos veces (pruebas/migracion.test.js).
-- ============================================================


-- ------------------------------------------------------------
-- 0. AYUDANTES Y LA MARCA DEL PAGO A COMISIÓN
-- ------------------------------------------------------------

-- ¿Es la categoría «Mercadería»? Sin mayúsculas, sin espacios de más, con o
-- sin tilde, y la palabra en portugués. La misma lista está en calculos.ts.
create or replace function public.es_categoria_mercaderia(p_categoria text)
returns boolean language sql immutable set search_path = public as $fn$
  select lower(trim(coalesce(p_categoria, ''))) in ('mercadería', 'mercaderia', 'mercadoria');
$fn$;

revoke all on function public.es_categoria_mercaderia(text) from public, anon;
grant execute on function public.es_categoria_mercaderia(text) to authenticated;

-- La columna y su relleno van juntos y UNA sola vez: si se aplicara el
-- relleno de nuevo, marcaría pagos hechos a alguien que en ese momento
-- cobraba a sueldo y después pasó a comisión.
do $$
begin
  if not exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'turnos_pago' and column_name = 'de_comision'
  ) then
    alter table public.turnos_pago add column de_comision boolean not null default false;

    update public.turnos_pago tp
       set de_comision = true
      from public.turnos_profesional p
     where p.id = tp.profesional_id
       and p.reparto = 'comision';
  end if;
end $$;

comment on column public.turnos_pago.de_comision is
  'El pago liquida la parte a comisión, que ya es costo de la venta (034): no vuelve a restar de la ganancia (106).';

-- Los resúmenes preguntan «¿este gasto es un pago de comisión?» por cada
-- gasto del período: con este índice es una búsqueda, no un recorrido.
create index if not exists turnos_pago_de_comision_idx
  on public.turnos_pago (movimiento_id) where de_comision;


-- ------------------------------------------------------------
-- 1. RESUMEN FINANCIERO (047) + mercadería aparte + pagos de comisión
-- ------------------------------------------------------------
create or replace function public.resumen_financiero(p_empresa uuid, p_desde date, p_hasta date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_admin boolean;
  v_res   jsonb;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  v_admin := public.es_admin(p_empresa);

  with base as (
    select m.tipo, m.estado, m.monto, m.subtotal, m.costo_total, m.id,
           -- 106: la compra de mercadería, el pago de una comisión y la venta
           -- de un servicio del reparto se reconocen acá una sola vez.
           (m.tipo = 'gasto' and public.es_categoria_mercaderia(m.categoria)) as es_mercaderia,
           (m.tipo = 'gasto' and exists (
              select 1 from public.turnos_pago tp
              where tp.movimiento_id = m.id and tp.de_comision)) as es_comision,
           (m.tipo = 'venta' and exists (
              select 1 from public.turnos_atribucion a
              where a.movimiento_id = m.id)) as es_servicio
    from public.movimientos m
    where m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
      and (v_admin or m.tipo = 'venta' or m.creado_por = auth.uid())
  ),
  totales as (
    select
      coalesce(sum(monto)       filter (where estado = 'activo' and tipo = 'venta'),   0)::numeric as ventas,
      coalesce(sum(subtotal)    filter (where estado = 'activo' and tipo = 'venta'),   0)::numeric as ventas_brutas,
      coalesce(sum(costo_total) filter (where estado = 'activo' and tipo = 'venta'),   0)::numeric as costo_mercaderia,
      coalesce(sum(monto)       filter (where estado = 'activo' and tipo = 'ingreso'), 0)::numeric as otros_ingresos,
      coalesce(sum(monto)       filter (where estado = 'activo' and tipo = 'gasto'),   0)::numeric as gastos_todos,
      coalesce(count(*)         filter (where estado = 'activo' and tipo = 'venta'),   0)::bigint  as cantidad_ventas,
      coalesce(count(*)         filter (where estado = 'anulado' and tipo = 'venta'),  0)::bigint  as ventas_anuladas,
      coalesce(sum(monto)       filter (where estado = 'anulado' and tipo = 'venta'),  0)::numeric as monto_ventas_anuladas,
      coalesce(count(*)         filter (where estado = 'anulado'),                     0)::bigint  as movimientos_anulados,
      coalesce(sum(monto)       filter (where estado = 'anulado'),                     0)::numeric as monto_movimientos_anulados,
      -- 106
      coalesce(sum(costo_total) filter (where estado = 'activo' and tipo = 'venta' and not es_servicio), 0)::numeric
        as costo_de_productos,
      coalesce(sum(monto) filter (where estado = 'activo' and es_mercaderia and not es_comision), 0)::numeric
        as compras_mercaderia,
      coalesce(sum(monto) filter (where estado = 'activo' and es_comision), 0)::numeric
        as pagado_a_profesionales
    from base
  ),
  regla as (
    -- La decisión 2: con costo de mercadería cargado en el período, la
    -- compra va aparte. Sin costo cargado, resta como siempre.
    select t.*,
           (t.costo_de_productos > 0) as mercaderia_aparte,
           (t.gastos_todos - t.pagado_a_profesionales
              - case when t.costo_de_productos > 0 then t.compras_mercaderia else 0 end) as gastos
    from totales t
  ),
  unidades as (
    select coalesce(sum(i.cantidad), 0)::numeric as unidades
    from public.movimiento_items i
    join public.movimientos m on m.id = i.movimiento_id
    where i.empresa_id = p_empresa
      and m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
      and m.estado = 'activo'
      and m.tipo = 'venta'
  ),
  derivados as (
    select
      t.*,
      u.unidades,
      (t.ventas + t.otros_ingresos) as ingresos_totales,
      (t.ventas - t.costo_mercaderia) as ganancia_bruta,
      (t.ventas - t.costo_mercaderia + t.otros_ingresos - t.gastos) as ganancia_neta
    from regla t cross join unidades u
  )
  select jsonb_build_object(
    'ventas',                     d.ventas,
    'ventas_brutas',              d.ventas_brutas,
    'descuentos',                 d.ventas_brutas - d.ventas,
    'otros_ingresos',             d.otros_ingresos,
    'ingresos_totales',           d.ingresos_totales,
    'gastos',                     d.gastos,
    'cantidad_ventas',            d.cantidad_ventas,
    'unidades_vendidas',          d.unidades,
    'ticket_promedio',            case when d.cantidad_ventas > 0 then d.ventas / d.cantidad_ventas else 0 end,
    'ventas_anuladas',            d.ventas_anuladas,
    'monto_ventas_anuladas',      d.monto_ventas_anuladas,
    'movimientos_anulados',       d.movimientos_anulados,
    'monto_movimientos_anulados', d.monto_movimientos_anulados,
    'costo_mercaderia', case when v_admin then d.costo_mercaderia else null end,
    'ganancia_bruta',   case when v_admin then d.ganancia_bruta   else null end,
    'ganancia_neta',    case when v_admin then d.ganancia_neta    else null end,
    'margen_bruto',     case when v_admin and d.ventas > 0
                             then (d.ganancia_bruta / d.ventas) * 100 else null end,
    'margen_neto',      case when v_admin and d.ingresos_totales > 0
                             then (d.ganancia_neta / d.ingresos_totales) * 100 else null end,
    'con_costos',       v_admin,
    -- 106
    'compras_mercaderia',     d.compras_mercaderia,
    'mercaderia_aparte',      d.mercaderia_aparte,
    'pagado_a_profesionales', case when v_admin then d.pagado_a_profesionales else null end
  ) into v_res
  from derivados d;

  return v_res;
end $function$;

revoke all on function public.resumen_financiero(uuid, date, date) from public, anon;
grant execute on function public.resumen_financiero(uuid, date, date) to authenticated;


-- ------------------------------------------------------------
-- 2. SERIE DIARIA (047) con la misma regla, decidida para el PERÍODO
-- ------------------------------------------------------------
create or replace function public.serie_financiera_diaria(p_empresa uuid, p_desde date, p_hasta date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_admin  boolean;
  v_dias   integer;
  v_res    jsonb;
  v_aparte boolean;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  v_dias := (p_hasta - p_desde) + 1;
  if v_dias > 1100 then
    raise exception 'El rango no puede superar los 3 años para la serie diaria.' using errcode = '22023';
  end if;

  v_admin := public.es_admin(p_empresa);

  -- 106: la bandera es del período entero, igual que en el resumen. Si se
  -- decidiera día por día, la suma de la serie no daría la ganancia neta.
  select coalesce(sum(m.costo_total), 0) > 0 into v_aparte
  from public.movimientos m
  where m.empresa_id = p_empresa
    and m.fecha between p_desde and p_hasta
    and m.estado = 'activo'
    and m.tipo = 'venta'
    and not exists (select 1 from public.turnos_atribucion a where a.movimiento_id = m.id);

  with dias as (
    select generate_series(p_desde, p_hasta, interval '1 day')::date as fecha
  ),
  marcados as (
    select m.fecha, m.tipo, m.monto, m.costo_total,
           (m.tipo = 'gasto' and public.es_categoria_mercaderia(m.categoria)) as es_mercaderia,
           (m.tipo = 'gasto' and exists (
              select 1 from public.turnos_pago tp
              where tp.movimiento_id = m.id and tp.de_comision)) as es_comision
    from public.movimientos m
    where m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
      and m.estado = 'activo'
      and (v_admin or m.tipo = 'venta' or m.creado_por = auth.uid())
  ),
  porDia as (
    select
      m.fecha,
      coalesce(sum(m.monto)       filter (where m.tipo = 'venta'), 0)::numeric   as ventas,
      coalesce(sum(m.monto)       filter (where m.tipo = 'gasto' and not m.es_comision
                                            and not (v_aparte and m.es_mercaderia)), 0)::numeric as gastos,
      coalesce(sum(m.monto)       filter (where m.tipo = 'ingreso'), 0)::numeric as otros_ingresos,
      coalesce(sum(m.costo_total) filter (where m.tipo = 'venta'), 0)::numeric   as costo,
      coalesce(sum(m.monto)       filter (where m.es_mercaderia and not m.es_comision), 0)::numeric as compras,
      coalesce(sum(m.monto)       filter (where m.es_comision), 0)::numeric      as comisiones
    from marcados m
    group by m.fecha
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'fecha',          to_char(d.fecha, 'YYYY-MM-DD'),
      'ventas',         coalesce(p.ventas, 0),
      'gastos',         coalesce(p.gastos, 0),
      'otros_ingresos', coalesce(p.otros_ingresos, 0),
      'ganancia', case
        when v_admin then coalesce(p.ventas, 0) - coalesce(p.costo, 0)
                        + coalesce(p.otros_ingresos, 0) - coalesce(p.gastos, 0)
        else null
      end,
      -- 106
      'compras_mercaderia',     coalesce(p.compras, 0),
      'mercaderia_aparte',      v_aparte,
      'pagado_a_profesionales', case when v_admin then coalesce(p.comisiones, 0) else null end
    ) order by d.fecha
  ), '[]'::jsonb) into v_res
  from dias d
  left join porDia p on p.fecha = d.fecha;

  return v_res;
end $function$;

revoke all on function public.serie_financiera_diaria(uuid, date, date) from public, anon;
grant execute on function public.serie_financiera_diaria(uuid, date, date) to authenticated;


-- ------------------------------------------------------------
-- 3. GASTOS POR CATEGORÍA (047) sin los pagos de comisión
--
--    Si el total de gastos los deja afuera y la lista por categoría no, la
--    lista suma más que el total y el reporte se contradice solo. La
--    Mercadería SÍ queda en la lista: se reconoce por su nombre y la pantalla
--    la muestra aparte cuando `mercaderia_aparte` (contrato, 2.1).
-- ------------------------------------------------------------
create or replace function public.gastos_por_categoria(p_empresa uuid, p_desde date, p_hasta date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_admin boolean;
  v_res   jsonb;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  v_admin := public.es_admin(p_empresa);

  with porCategoria as (
    select
      trim(coalesce(nullif(trim(m.categoria), ''), 'General')) as nombre,
      sum(m.monto)::numeric as monto,
      count(*)::bigint      as operaciones
    from public.movimientos m
    where m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
      and m.estado = 'activo'
      and m.tipo = 'gasto'
      and (v_admin or m.creado_por = auth.uid())
      -- 106
      and not exists (select 1 from public.turnos_pago tp
                      where tp.movimiento_id = m.id and tp.de_comision)
    group by 1
  ),
  con_total as (
    select c.*, sum(c.monto) over () as total from porCategoria c
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'nombre',        c.nombre,
      'monto',         c.monto,
      'operaciones',   c.operaciones,
      'participacion', case when c.total > 0 then (c.monto / c.total) * 100 else 0 end
    ) order by c.monto desc
  ), '[]'::jsonb) into v_res
  from con_total c;

  return v_res;
end $function$;

revoke all on function public.gastos_por_categoria(uuid, date, date) from public, anon;
grant execute on function public.gastos_por_categoria(uuid, date, date) to authenticated;


-- ------------------------------------------------------------
-- 4. PAGAR AL PROFESIONAL (035) marcando si liquida una comisión
-- ------------------------------------------------------------
create or replace function public.pagar_profesional(p_empresa uuid, p_profesional uuid, p_monto numeric, p_fecha date DEFAULT NULL::date, p_notas text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_nombre  text;
  v_fecha   date;
  v_mov     uuid;
  v_id      uuid;
  v_reparto text;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'Solo el dueño de la cuenta puede pagar al equipo.' using errcode = '42501';
  end if;

  select nombre, reparto into v_nombre, v_reparto from public.turnos_profesional
  where id = p_profesional and empresa_id = p_empresa;
  if v_nombre is null then
    raise exception 'Esa persona no está en el equipo de esta cuenta.' using errcode = 'P0002';
  end if;

  if coalesce(p_monto, 0) <= 0 then
    raise exception 'El pago tiene que ser mayor que cero.' using errcode = '22023';
  end if;

  v_fecha := coalesce(p_fecha, public.hoy_empresa(p_empresa));

  insert into public.movimientos (
    empresa_id, tipo, estado, fecha, descripcion, categoria,
    subtotal, descuento, monto, costo_total, metodo_pago, contraparte, origen, creado_por
  )
  values (
    p_empresa, 'gasto', 'activo', v_fecha,
    'Pago a ' || v_nombre, 'Sueldos',
    p_monto, 0, p_monto, 0, 'efectivo', v_nombre, 'manual', auth.uid()
  )
  returning id into v_mov;

  -- 106: a comisión, su parte ya es el costo de cada corte (034). El pago
  -- queda marcado para que no vuelva a restar de la ganancia.
  insert into public.turnos_pago (empresa_id, profesional_id, movimiento_id, monto, fecha, notas, creado_por, de_comision)
  values (p_empresa, p_profesional, v_mov, p_monto, v_fecha, left(coalesce(p_notas, ''), 200), auth.uid(),
          v_reparto = 'comision')
  returning id into v_id;

  return jsonb_build_object('pago', v_id, 'movimiento', v_mov);
end $function$;

revoke all on function public.pagar_profesional(uuid, uuid, numeric, date, text) from public, anon;
grant execute on function public.pagar_profesional(uuid, uuid, numeric, date, text) to authenticated;


-- ------------------------------------------------------------
-- 5. LIQUIDACIÓN (035) sin la deuda falsa del alquiler de silla
-- ------------------------------------------------------------
create or replace function public.liquidacion(p_empresa uuid, p_desde date, p_hasta date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_res jsonb;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'No tenés acceso a estos números.' using errcode = '42501';
  end if;

  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  select coalesce(jsonb_agg(x order by (x->>'le_toca')::numeric desc), '[]'::jsonb)
  into v_res
  from (
    select jsonb_build_object(
      'id',         p.id,
      'nombre',     p.nombre,
      'reparto',    p.reparto,
      'porcentaje', p.porcentaje,
      'activo',     p.activo,
      'cortes',     coalesce(c.cortes, 0),
      'cobrado',    coalesce(c.cobrado, 0),
      'le_toca',    coalesce(c.suyo, 0),
      'del_local',  coalesce(c.local, 0),
      'pagado',     coalesce(g.pagado, 0),
      'le_debe',    coalesce(c.suyo, 0) - coalesce(g.pagado, 0),
      -- 106: lo que el que alquila la silla cobró directo. Es suyo y ya lo
      -- tiene: no es plata que el local le deba.
      'cobro_directo', coalesce(c.directo, 0)
    ) as x
    from public.turnos_profesional p
    left join lateral (
      select count(*)::int              as cortes,
             sum(a.monto_cobrado)       as cobrado,
             -- 106: solo lo que pasó por la caja del local le toca cobrar.
             sum(a.parte_profesional) filter (where a.reparto <> 'alquiler') as suyo,
             sum(a.parte_profesional) filter (where a.reparto = 'alquiler')  as directo,
             sum(a.parte_local)         as local
      from public.turnos_atribucion a
      where a.profesional_id = p.id
        and a.fecha between p_desde and p_hasta
        and (a.movimiento_id is null
             or exists (select 1 from public.movimientos m
                        where m.id = a.movimiento_id and m.estado = 'activo'))
    ) c on true
    left join lateral (
      select sum(t.monto) as pagado
      from public.turnos_pago t
      where t.profesional_id = p.id and t.fecha between p_desde and p_hasta
    ) g on true
    where p.empresa_id = p_empresa
      and (p.activo or coalesce(c.cortes, 0) > 0 or coalesce(g.pagado, 0) > 0)
  ) t;

  return v_res;
end $function$;

revoke all on function public.liquidacion(uuid, date, date) from public, anon;
grant execute on function public.liquidacion(uuid, date, date) to authenticated;


-- ------------------------------------------------------------
-- 6. MIS SERVICIOS (035): la misma regla en la vista del profesional
-- ------------------------------------------------------------
create or replace function public.mis_servicios(p_empresa uuid, p_desde date, p_hasta date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_prof    uuid;
  v_cortes  jsonb;
  v_total   numeric := 0;
  v_pagado  numeric := 0;
  v_directo numeric := 0;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  select id into v_prof from public.turnos_profesional
  where empresa_id = p_empresa and user_id = auth.uid();

  if v_prof is null then
    return jsonb_build_object('es_profesional', false, 'cortes', '[]'::jsonb,
                              'le_toca', 0, 'pagado', 0, 'le_deben', 0, 'cobro_directo', 0);
  end if;

  select
    coalesce(jsonb_agg(jsonb_build_object(
      'fecha',    a.fecha,
      'servicio', a.servicio,
      'monto',    a.monto_cobrado,
      'tuyo',     a.parte_profesional
    ) order by a.fecha desc, a.created_at desc), '[]'::jsonb),
    -- 106: con alquiler de silla el corte ya lo cobró él; no se lo deben.
    coalesce(sum(a.parte_profesional) filter (where a.reparto <> 'alquiler'), 0),
    coalesce(sum(a.parte_profesional) filter (where a.reparto = 'alquiler'), 0)
  into v_cortes, v_total, v_directo
  from public.turnos_atribucion a
  where a.profesional_id = v_prof
    and a.fecha between p_desde and p_hasta
    and (a.movimiento_id is null
         or exists (select 1 from public.movimientos m
                    where m.id = a.movimiento_id and m.estado = 'activo'));

  select coalesce(sum(t.monto), 0) into v_pagado
  from public.turnos_pago t
  where t.profesional_id = v_prof and t.fecha between p_desde and p_hasta;

  return jsonb_build_object(
    'es_profesional', true,
    'cortes',   v_cortes,
    'le_toca',  v_total,
    'pagado',   v_pagado,
    'le_deben', v_total - v_pagado,
    'cobro_directo', v_directo
  );
end $function$;

revoke all on function public.mis_servicios(uuid, date, date) from public, anon;
grant execute on function public.mis_servicios(uuid, date, date) to authenticated;


-- ------------------------------------------------------------
-- 7. PÁGINA DE MOVIMIENTOS (047) + cuenta, cliente, quién, lote y moneda
--
--    Copia exacta; cada dato nuevo es una subconsulta por id (con índice de
--    clave primaria), así el orden, el cursor y la búsqueda no cambian.
--    `creado_por` ya venía; se le suma el nombre.
-- ------------------------------------------------------------
create or replace function public.pagina_movimientos(p_empresa uuid, p_desde date, p_hasta date, p_tamano integer DEFAULT 100, p_cursor_fecha date DEFAULT NULL::date, p_cursor_created timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_id uuid DEFAULT NULL::uuid, p_tipo tipo_movimiento DEFAULT NULL::tipo_movimiento, p_incluir_anuladas boolean DEFAULT true, p_busqueda text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_admin   boolean;
  v_tamano  integer;
  v_busca   text;
  v_filas   jsonb;
  v_cuantas integer;
  v_ultima  jsonb;
begin
  if auth.uid() is null then
    raise exception 'Necesitás iniciar sesión.' using errcode = '42501';
  end if;
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  v_tamano := least(greatest(coalesce(p_tamano, 100), 1), 500);
  v_admin  := public.es_admin(p_empresa);
  v_busca  := nullif(lower(trim(coalesce(p_busqueda, ''))), '');

  select coalesce(jsonb_agg(to_jsonb(x) order by x.fecha desc, x.created_at desc, x.id desc), '[]'::jsonb)
  into v_filas
  from (
    select
      m.id, m.empresa_id, m.tipo, m.estado, m.fecha, m.descripcion, m.categoria,
      m.subtotal, m.descuento, m.monto,
      case when v_admin then m.costo_total else null end as costo_total,
      m.metodo_pago, m.contraparte, m.notas, m.origen, m.creado_por, m.created_at,
      m.anulado_por, m.anulado_at, m.motivo_anulacion, m.actualizado_por, m.updated_at,
      -- 106
      m.cuenta_id,
      (select cd.nombre from public.cuentas_dinero cd where cd.id = m.cuenta_id) as cuenta_nombre,
      m.cliente_id,
      (select cl.nombre from public.clientes cl where cl.id = m.cliente_id) as cliente_nombre,
      (select mi.nombre from public.miembros mi
        where mi.empresa_id = m.empresa_id and mi.user_id = m.creado_por) as creado_por_nombre,
      m.lote_id,
      (select l.nombre from public.lotes l where l.id = m.lote_id) as lote_nombre,
      m.moneda_original,
      m.monto_original,
      -- El cambio va con la moneda (100 exige los tres juntos): sin él, el
      -- Excel no podría explicar cómo 3 dólares se volvieron 20.000.
      m.cambio,
      coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id', i.id,
            'movimiento_id', i.movimiento_id,
            'empresa_id', i.empresa_id,
            'producto_id', i.producto_id,
            'nombre', i.nombre,
            'cantidad', i.cantidad,
            'precio_unitario', i.precio_unitario,
            'costo_unitario', case when v_admin then i.costo_unitario else null end,
            'afecto_stock', i.afecto_stock
          ) order by i.nombre
        )
        from public.movimiento_items i where i.movimiento_id = m.id
      ), '[]'::jsonb) as movimiento_items
    from public.movimientos m
    where m.empresa_id = p_empresa
      and m.fecha between p_desde and p_hasta
      and (v_admin or m.tipo = 'venta' or m.creado_por = auth.uid())
      and (p_tipo is null or m.tipo = p_tipo)
      and (p_incluir_anuladas or m.estado = 'activo')
      and (
        p_cursor_id is null
        or (m.fecha, m.created_at, m.id) < (p_cursor_fecha, p_cursor_created, p_cursor_id)
      )
      and (
        v_busca is null
        or lower(m.descripcion) like '%' || v_busca || '%'
        or lower(m.categoria)   like '%' || v_busca || '%'
        or lower(coalesce(m.contraparte, '')) like '%' || v_busca || '%'
        or exists (
          select 1 from public.movimiento_items i2
          where i2.movimiento_id = m.id and lower(i2.nombre) like '%' || v_busca || '%'
        )
      )
    order by m.fecha desc, m.created_at desc, m.id desc
    limit v_tamano
  ) x;

  v_cuantas := jsonb_array_length(v_filas);
  v_ultima  := case when v_cuantas > 0 then v_filas -> (v_cuantas - 1) else null end;

  return jsonb_build_object(
    'movimientos', v_filas,
    'siguiente', case
      when v_cuantas = v_tamano and v_ultima is not null then jsonb_build_object(
        'fecha',      v_ultima ->> 'fecha',
        'created_at', v_ultima ->> 'created_at',
        'id',         v_ultima ->> 'id'
      )
      else null
    end,
    'tamano', v_tamano
  );
end $function$;

revoke all on function public.pagina_movimientos(uuid, date, date, integer, date, timestamptz, uuid, tipo_movimiento, boolean, text) from public, anon;
grant execute on function public.pagina_movimientos(uuid, date, date, integer, date, timestamptz, uuid, tipo_movimiento, boolean, text) to authenticated;


-- ------------------------------------------------------------
-- 8. TURNOS DEL PERÍODO (servicios, clases y entrenamiento)
--
--    El día de un turno es el de la zona horaria del negocio, como en la
--    agenda. Estados reales (turnos_reserva_estado_check): pendiente,
--    confirmada, atendida, cancelada, no_vino. Orígenes: local, publico.
--    Cancelar solo cambia el estado, sin fecha (041): un turno cancelado
--    cuenta en el período de la fecha del turno, no del día que se canceló.
-- ------------------------------------------------------------
create or replace function public.reporte_turnos(p_empresa uuid, p_desde date, p_hasta date)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_zona text;
  v_res  jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  select coalesce(zona_horaria, 'America/Asuncion') into v_zona from public.empresas where id = p_empresa;

  with t as (
    select r.*, (r.inicia at time zone v_zona)::date as dia
    from public.turnos_reserva r
    where r.empresa_id = p_empresa
      and (r.inicia at time zone v_zona)::date between p_desde and p_hasta
  )
  select jsonb_build_object(
    'total', (select count(*)::int from t),
    'por_estado', jsonb_build_object(
      'pendiente',  (select count(*)::int from t where estado = 'pendiente'),
      'confirmada', (select count(*)::int from t where estado = 'confirmada'),
      'atendida',   (select count(*)::int from t where estado = 'atendida'),
      'no_vino',    (select count(*)::int from t where estado = 'no_vino'),
      'cancelada',  (select count(*)::int from t where estado = 'cancelada')),
    'por_origen', jsonb_build_object(
      'local',   (select count(*)::int from t where origen = 'local'),
      'publico', (select count(*)::int from t where origen = 'publico')),
    'por_profesional', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', x.profesional_id, 'nombre', x.nombre, 'total', x.total,
               'atendidas', x.atendidas, 'no_vino', x.no_vino,
               'canceladas', x.canceladas, 'pendientes', x.pendientes)
             order by x.total desc, x.nombre)
      from (
        select t.profesional_id, p.nombre,
               count(*)::int as total,
               count(*) filter (where t.estado = 'atendida')::int  as atendidas,
               count(*) filter (where t.estado = 'no_vino')::int   as no_vino,
               count(*) filter (where t.estado = 'cancelada')::int as canceladas,
               count(*) filter (where t.estado in ('pendiente', 'confirmada'))::int as pendientes
        from t join public.turnos_profesional p on p.id = t.profesional_id
        group by t.profesional_id, p.nombre
      ) x), '[]'::jsonb),
    'por_servicio', coalesce((
      select jsonb_agg(jsonb_build_object(
               'producto_id', x.producto_id, 'nombre', x.nombre,
               'total', x.total, 'atendidas', x.atendidas)
             order by x.total desc, x.nombre)
      from (
        select t.producto_id, pr.nombre,
               count(*)::int as total,
               count(*) filter (where t.estado = 'atendida')::int as atendidas
        from t join public.productos pr on pr.id = t.producto_id
        group by t.producto_id, pr.nombre
      ) x), '[]'::jsonb),
    -- Los que más vuelven: solo turnos atendidos y con cliente de la agenda
    -- (cliente_id, 053). Un nombre escrito a mano no alcanza para saber que
    -- dos turnos son de la misma persona.
    'clientes', coalesce((
      select jsonb_agg(jsonb_build_object(
               'cliente_id', x.cliente_id, 'nombre', x.nombre,
               'visitas', x.visitas, 'ultima', x.ultima)
             order by x.visitas desc, x.ultima desc)
      from (
        select t.cliente_id, c.nombre, count(*)::int as visitas, max(t.dia) as ultima
        from t join public.clientes c on c.id = t.cliente_id
        where t.estado = 'atendida'
        group by t.cliente_id, c.nombre
        order by count(*) desc, max(t.dia) desc
        limit 20
      ) x), '[]'::jsonb)
  ) into v_res;

  return v_res;
end $fn$;

revoke all on function public.reporte_turnos(uuid, date, date) from public, anon;
grant execute on function public.reporte_turnos(uuid, date, date) to authenticated;


-- ------------------------------------------------------------
-- 9. ALUMNOS DEL PERÍODO (clases y entrenamiento)
--
--    Todo sale de `paquetes` y `clases_dadas` (088), las mismas tablas que
--    usa `estado_paquete`, con las mismas palabras:
--      · dada / falta: `clases_dadas.motivo`, sumando `cantidad`;
--      · activo: lo que dice `estado_paquete` HOY (es una foto);
--      · nuevo: el primer paquete del alumno se creó en el período;
--      · terminado en el período: usó todas sus clases y la última se dio
--        en el período;
--      · vencido en el período: le quedaban clases y `vence_el` cayó en el
--        período (y ya pasó);
--      · renovó: tiene un paquete creado después de ese.
--    Los paquetes cerrados a mano no cuentan como terminados ni vencidos.
--    Lo cobrado es lo vendido (ventas activas), la misma base que el
--    «Cobrado» del resumen; la deuda es la de hoy: inscripciones sin cobrar
--    (la regla de `por_cobrar_alumnos`, 094) más el saldo de fiado.
-- ------------------------------------------------------------
create or replace function public.reporte_alumnos(p_empresa uuid, p_desde date, p_hasta date)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_zona text;
  v_hoy  date;
  v_res  jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  select coalesce(zona_horaria, 'America/Asuncion') into v_zona from public.empresas where id = p_empresa;
  v_hoy := public.hoy_empresa(p_empresa);

  with
  paq as (
    select p.*,
           (p.created_at at time zone v_zona)::date as creado_el,
           coalesce(u.usadas, 0) as usadas,
           u.ultima,
           case
             when p.cerrado then 'cerrado'
             when coalesce(u.usadas, 0) >= p.clases then 'terminado'
             when p.vence_el is not null and p.vence_el < v_hoy then 'vencido'
             else 'activo' end as estado
    from public.paquetes p
    left join lateral (
      select sum(c.cantidad) as usadas, max(c.fecha) as ultima
      from public.clases_dadas c where c.paquete_id = p.id
    ) u on true
    where p.empresa_id = p_empresa
  ),
  clases as (
    select c.* from public.clases_dadas c
    where c.empresa_id = p_empresa and c.fecha between p_desde and p_hasta
  ),
  cierres as (
    -- Los paquetes que terminaron o vencieron DENTRO del período.
    select q.*,
           case when q.usadas >= q.clases then 'terminado' else 'vencido' end as como,
           exists (select 1 from public.paquetes n
                   where n.empresa_id = p_empresa and n.cliente_id = q.cliente_id
                     and n.id <> q.id and n.created_at > q.created_at) as renovo
    from paq q
    where not q.cerrado
      and (
        (q.usadas >= q.clases and q.ultima between p_desde and p_hasta)
        or (q.usadas < q.clases and q.vence_el between p_desde and p_hasta and q.vence_el < v_hoy)
      )
  ),
  ventas as (
    select m.* from public.movimientos m
    where m.empresa_id = p_empresa and m.tipo = 'venta' and m.estado = 'activo'
      and m.fecha between p_desde and p_hasta
  ),
  fiado as (
    select f.cliente_id, sum(case when f.tipo = 'fio' then f.monto else -f.monto end) as saldo
    from public.fiado f where f.empresa_id = p_empresa
    group by f.cliente_id
  ),
  por_alumno as (
    select c.id as cliente_id, c.nombre,
           coalesce((select sum(k.cantidad) from clases k join paq q on q.id = k.paquete_id
                     where q.cliente_id = c.id and k.motivo = 'dada'), 0) as clases,
           coalesce((select sum(k.cantidad) from clases k join paq q on q.id = k.paquete_id
                     where q.cliente_id = c.id and k.motivo = 'falta'), 0) as faltas,
           coalesce((select sum(v.monto) from ventas v where v.cliente_id = c.id), 0) as cobrado,
           coalesce((select sum(q.precio) from paq q
                     where q.cliente_id = c.id and q.movimiento_id is null
                       and q.precio > 0 and not q.cerrado), 0) as debe_inscripciones,
           greatest(coalesce((select f.saldo from fiado f where f.cliente_id = c.id), 0), 0) as debe_fiado,
           (select jsonb_build_object('id', q.id, 'nombre', q.nombre, 'materia', q.materia,
                                      'clases', q.clases, 'usadas', q.usadas,
                                      'quedan', greatest(0, q.clases - q.usadas),
                                      'vence_el', q.vence_el)
              from paq q where q.cliente_id = c.id and q.estado = 'activo'
              order by q.created_at desc limit 1) as vigente,
           (select max(k.fecha) from public.clases_dadas k join paq q on q.id = k.paquete_id
             where q.cliente_id = c.id and k.motivo = 'dada' and k.fecha <= v_hoy) as ultima_clase
    from public.clientes c
    where c.empresa_id = p_empresa
      and exists (select 1 from paq q where q.cliente_id = c.id)
  ),
  materias as (
    select count(distinct q.materia) as n from paq q where q.materia is not null
  )
  select jsonb_build_object(
    'clases_dadas', coalesce((select sum(cantidad) from clases where motivo = 'dada'), 0),
    'faltas',       coalesce((select sum(cantidad) from clases where motivo = 'falta'), 0),
    'por_semana', coalesce((
      select jsonb_agg(jsonb_build_object('semana', s.semana, 'dadas', s.dadas, 'faltas', s.faltas)
             order by s.semana)
      from (
        select date_trunc('week', k.fecha)::date as semana,
               coalesce(sum(k.cantidad) filter (where k.motivo = 'dada'), 0)  as dadas,
               coalesce(sum(k.cantidad) filter (where k.motivo = 'falta'), 0) as faltas
        from clases k group by 1
      ) s), '[]'::jsonb),
    'cobrado', coalesce((select sum(monto) from ventas), 0),
    -- Sin clases dadas no hay «por clase»: null, no un cero que parece dato.
    'cobrado_por_clase', (
      select case when coalesce(sum(k.cantidad), 0) > 0
                  then coalesce((select sum(monto) from ventas), 0) / sum(k.cantidad)
                  else null end
      from clases k where k.motivo = 'dada'),
    'por_cobrar', coalesce((select sum(q.precio) from paq q
                            where q.movimiento_id is null and q.precio > 0 and not q.cerrado), 0),
    -- El fiado va aparte de las inscripciones: así «por cobrar» es el mismo
    -- número que `por_cobrar_alumnos` y la suma de `alumnos[].debe` es
    -- por_cobrar + fiado_pendiente, sin contar nada dos veces.
    'fiado_pendiente', coalesce((select sum(a.debe_fiado) from por_alumno a), 0),
    'activos', (select count(distinct q.cliente_id)::int from paq q where q.estado = 'activo'),
    'nuevos', (
      select count(*)::int from (
        select q.cliente_id from paq q group by q.cliente_id
        having min(q.creado_el) between p_desde and p_hasta) n),
    'paquetes', jsonb_build_object(
      'vendidos',   (select count(*)::int from paq q where q.creado_el between p_desde and p_hasta),
      'terminados', (select count(*)::int from cierres where como = 'terminado'),
      'vencidos',   (select count(*)::int from cierres where como = 'vencido'),
      'renovaron',  (select count(*)::int from cierres where renovo)),
    -- A quién llamar: paquetes activos con 2 clases o menos, o que vencen
    -- en la próxima semana.
    'por_terminar', coalesce((
      select jsonb_agg(jsonb_build_object(
               'paquete', q.id, 'cliente_id', q.cliente_id, 'alumno', c.nombre,
               'nombre', q.nombre, 'quedan', greatest(0, q.clases - q.usadas),
               'vence_el', q.vence_el)
             order by greatest(0, q.clases - q.usadas), q.vence_el nulls last, c.nombre)
      from paq q join public.clientes c on c.id = q.cliente_id
      where q.estado = 'activo'
        and (q.clases - q.usadas <= 2 or (q.vence_el is not null and q.vence_el <= v_hoy + 7))), '[]'::jsonb),
    'alumnos', coalesce((
      select jsonb_agg(jsonb_build_object(
               'cliente_id', a.cliente_id, 'nombre', a.nombre,
               'clases', a.clases, 'faltas', a.faltas, 'cobrado', a.cobrado,
               'debe', a.debe_inscripciones + a.debe_fiado,
               'debe_inscripciones', a.debe_inscripciones, 'debe_fiado', a.debe_fiado,
               'paquete', a.vigente->>'nombre',
               'materia', a.vigente->>'materia',
               'usadas', (a.vigente->>'usadas')::numeric,
               'quedan', (a.vigente->>'quedan')::numeric,
               'vence_el', a.vigente->>'vence_el',
               'ultima_clase', a.ultima_clase)
             order by a.nombre)
      from por_alumno a
      where a.clases > 0 or a.faltas > 0 or a.cobrado > 0
         or a.debe_inscripciones > 0 or a.debe_fiado > 0 or a.vigente is not null), '[]'::jsonb),
    -- Cobrado por paquete o plan: sin costo ni margen, que acá no existen.
    'por_paquete', coalesce((
      select jsonb_agg(jsonb_build_object('nombre', x.nombre, 'vendidos', x.vendidos, 'cobrado', x.cobrado)
             order by x.cobrado desc, x.nombre)
      from (
        select q.nombre, count(*)::int as vendidos, sum(v.monto) as cobrado
        from paq q join ventas v on v.id = q.movimiento_id
        group by q.nombre
      ) x), '[]'::jsonb),
    -- Por materia, solo si el profe enseña dos o más (094).
    'por_materia', case when (select n from materias) >= 2 then coalesce((
      select jsonb_agg(jsonb_build_object('materia', x.materia, 'alumnos', x.alumnos, 'cobrado', x.cobrado)
             order by x.cobrado desc)
      from (
        select q.materia, count(distinct q.cliente_id)::int as alumnos, sum(v.monto) as cobrado
        from paq q join ventas v on v.id = q.movimiento_id
        group by q.materia
      ) x), '[]'::jsonb) else '[]'::jsonb end
  ) into v_res;

  return v_res;
end $fn$;

revoke all on function public.reporte_alumnos(uuid, date, date) from public, anon;
grant execute on function public.reporte_alumnos(uuid, date, date) to authenticated;


-- ------------------------------------------------------------
-- 10. PROGRESO DE LOS CLIENTES DEL TRAINER (admin, como las medidas, 098)
--
--    Por cliente, primera contra última medición DEL PERÍODO que tenga ese
--    dato (hacen falta dos). La grasa solo se compara si las dos se
--    midieron con el mismo método: balanza contra plicómetro no es un cambio,
--    es otro aparato. Los promedios son de los clientes que se pueden
--    comparar; si ninguno, null.
--    «Sin medir» y «sin rutina» miran a los clientes con un plan activo hoy.
-- ------------------------------------------------------------
create or replace function public.progreso_clientes(p_empresa uuid, p_desde date, p_hasta date)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare
  v_hoy date;
  v_res jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if not public.es_admin(p_empresa) then
    raise exception 'Las medidas y el progreso son del dueño o de un administrador.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  v_hoy := public.hoy_empresa(p_empresa);

  with
  activos as (
    select distinct p.cliente_id from public.paquetes p
    where p.empresa_id = p_empresa and (public.estado_paquete(p.id)->>'estado') = 'activo'
  ),
  med as (
    select m.*, row_number() over (partition by m.cliente_id order by m.fecha, m.created_at) as n
    from public.mediciones m
    where m.empresa_id = p_empresa and m.fecha between p_desde and p_hasta
  ),
  universo as (
    select c.id, c.nombre from public.clientes c
    where c.empresa_id = p_empresa
      and (c.id in (select cliente_id from activos) or c.id in (select cliente_id from med))
  ),
  fila as (
    select u.id as cliente_id, u.nombre,
           (select count(*)::int from med where med.cliente_id = u.id) as mediciones,
           (select m.peso_kg from med m where m.cliente_id = u.id and m.peso_kg is not null order by m.n limit 1) as peso_ini,
           (select m.peso_kg from med m where m.cliente_id = u.id and m.peso_kg is not null order by m.n desc limit 1) as peso_fin,
           (select count(*) from med m where m.cliente_id = u.id and m.peso_kg is not null) as n_peso,
           (select m.cintura_cm from med m where m.cliente_id = u.id and m.cintura_cm is not null order by m.n limit 1) as cint_ini,
           (select m.cintura_cm from med m where m.cliente_id = u.id and m.cintura_cm is not null order by m.n desc limit 1) as cint_fin,
           (select count(*) from med m where m.cliente_id = u.id and m.cintura_cm is not null) as n_cint,
           (select m.grasa_pct from med m where m.cliente_id = u.id and m.grasa_pct is not null order by m.n limit 1) as grasa_ini,
           (select m.grasa_metodo from med m where m.cliente_id = u.id and m.grasa_pct is not null order by m.n limit 1) as met_ini,
           (select m.grasa_pct from med m where m.cliente_id = u.id and m.grasa_pct is not null order by m.n desc limit 1) as grasa_fin,
           (select m.grasa_metodo from med m where m.cliente_id = u.id and m.grasa_pct is not null order by m.n desc limit 1) as met_fin,
           (select count(*) from med m where m.cliente_id = u.id and m.grasa_pct is not null) as n_grasa,
           (select max(m.fecha) from public.mediciones m
             where m.cliente_id = u.id and m.empresa_id = p_empresa and m.fecha <= v_hoy) as ultima,
           (select r.nombre from public.rutinas r
             where r.cliente_id = u.id and r.empresa_id = p_empresa and r.estado = 'vigente'
             order by r.desde desc limit 1) as rutina,
           u.id in (select cliente_id from activos) as activo
    from universo u
  ),
  calc as (
    select f.*,
           case when f.n_peso >= 2 then f.peso_fin - f.peso_ini end as peso_cambio,
           case when f.n_cint >= 2 then f.cint_fin - f.cint_ini end as cintura_cambio,
           case when f.n_grasa >= 2 and f.met_ini = f.met_fin then f.grasa_fin - f.grasa_ini end as grasa_cambio,
           case when f.ultima is null then null else v_hoy - f.ultima end as dias_sin_medir
    from fila f
  )
  select jsonb_build_object(
    'medidos',            (select count(*)::int from calc where mediciones > 0),
    'con_peso',           (select count(*)::int from calc where peso_cambio is not null),
    'cambio_peso',        (select round(avg(peso_cambio), 2) from calc where peso_cambio is not null),
    'con_cintura',        (select count(*)::int from calc where cintura_cambio is not null),
    'cambio_cintura',     (select round(avg(cintura_cambio), 2) from calc where cintura_cambio is not null),
    'con_grasa',          (select count(*)::int from calc where grasa_cambio is not null),
    'cambio_grasa',       (select round(avg(grasa_cambio), 2) from calc where grasa_cambio is not null),
    'sin_medir_30',       (select count(*)::int from calc where activo and (ultima is null or ultima < v_hoy - 30)),
    'sin_rutina',         (select count(*)::int from calc where activo and rutina is null),
    'clientes', coalesce((
      select jsonb_agg(jsonb_build_object(
               'cliente_id', c.cliente_id, 'nombre', c.nombre, 'activo', c.activo,
               'mediciones', c.mediciones,
               'peso_inicial',   case when c.peso_cambio is not null then c.peso_ini end,
               'peso_final',     case when c.peso_cambio is not null then c.peso_fin end,
               'peso_cambio',    c.peso_cambio,
               'cintura_inicial', case when c.cintura_cambio is not null then c.cint_ini end,
               'cintura_final',   case when c.cintura_cambio is not null then c.cint_fin end,
               'cintura_cambio', c.cintura_cambio,
               'grasa_inicial',  case when c.grasa_cambio is not null then c.grasa_ini end,
               'grasa_final',    case when c.grasa_cambio is not null then c.grasa_fin end,
               'grasa_cambio',   c.grasa_cambio,
               'grasa_metodo',   case when c.grasa_cambio is not null then c.met_ini end,
               'ultima_medicion', c.ultima,
               'dias_sin_medir', c.dias_sin_medir,
               'sin_medir_30',   c.activo and (c.ultima is null or c.ultima < v_hoy - 30),
               'rutina_vigente', c.rutina)
             order by c.nombre)
      from calc c), '[]'::jsonb)
  ) into v_res;

  return v_res;
end $fn$;

revoke all on function public.progreso_clientes(uuid, date, date) from public, anon;
grant execute on function public.progreso_clientes(uuid, date, date) to authenticated;


-- ------------------------------------------------------------
-- 11. VENTAS POR VENDEDOR (admin)
--
--    Por quien la cargó (`creado_por`). El nombre es el del miembro; si ya
--    no está en el negocio, o la venta no tiene autor (una migración vieja),
--    va null y la pantalla dice «sin dato»: no se inventa un nombre.
-- ------------------------------------------------------------
create or replace function public.ventas_por_vendedor(p_empresa uuid, p_desde date, p_hasta date)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_res jsonb;
begin
  if not public.es_admin(p_empresa) then
    raise exception 'No tenés acceso a estos números.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'user_id', x.creado_por, 'nombre', x.nombre, 'rol', x.rol,
           'vendido', x.vendido, 'cantidad', x.cantidad,
           'ticket_promedio', case when x.cantidad > 0 then x.vendido / x.cantidad else null end,
           'anuladas', x.anuladas, 'monto_anulado', x.monto_anulado)
         order by x.vendido desc, x.nombre), '[]'::jsonb)
  into v_res
  from (
    select m.creado_por, mi.nombre, mi.rol::text as rol,
           coalesce(sum(m.monto) filter (where m.estado = 'activo'), 0)  as vendido,
           count(*) filter (where m.estado = 'activo')::int              as cantidad,
           count(*) filter (where m.estado = 'anulado')::int             as anuladas,
           coalesce(sum(m.monto) filter (where m.estado = 'anulado'), 0) as monto_anulado
    from public.movimientos m
    left join public.miembros mi on mi.empresa_id = m.empresa_id and mi.user_id = m.creado_por
    where m.empresa_id = p_empresa and m.tipo = 'venta'
      and m.fecha between p_desde and p_hasta
    group by m.creado_por, mi.nombre, mi.rol
  ) x;

  return v_res;
end $fn$;

revoke all on function public.ventas_por_vendedor(uuid, date, date) from public, anon;
grant execute on function public.ventas_por_vendedor(uuid, date, date) to authenticated;


-- ------------------------------------------------------------
-- 12. FIADO DEL PERÍODO
--
--    `resumen_fiado` (054) es la foto de hoy; esto es lo que pasó en el
--    período: cuánto se fió y cuánto se cobró, por cliente. El saldo de hoy
--    se calcula igual que allá (todo lo fiado menos todo lo cobrado).
-- ------------------------------------------------------------
create or replace function public.fiado_del_periodo(p_empresa uuid, p_desde date, p_hasta date)
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_res jsonb;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;
  if p_desde is null or p_hasta is null or p_desde > p_hasta then
    raise exception 'El rango de fechas no es válido.' using errcode = '22007';
  end if;

  with periodo as (
    select f.cliente_id,
           coalesce(sum(f.monto) filter (where f.tipo = 'fio'), 0)   as otorgado,
           coalesce(sum(f.monto) filter (where f.tipo = 'cobro'), 0) as cobrado
    from public.fiado f
    where f.empresa_id = p_empresa and f.fecha between p_desde and p_hasta
    group by f.cliente_id
  ),
  saldos as (
    select f.cliente_id, sum(case when f.tipo = 'fio' then f.monto else -f.monto end) as saldo
    from public.fiado f
    where f.empresa_id = p_empresa and f.cliente_id in (select cliente_id from periodo)
    group by f.cliente_id
  )
  select jsonb_build_object(
    'otorgado', coalesce((select sum(otorgado) from periodo), 0),
    'cobrado',  coalesce((select sum(cobrado) from periodo), 0),
    'clientes', coalesce((
      select jsonb_agg(jsonb_build_object(
               'cliente_id', p.cliente_id, 'nombre', c.nombre,
               'otorgado', p.otorgado, 'cobrado', p.cobrado, 'saldo_hoy', coalesce(s.saldo, 0))
             order by p.otorgado desc, c.nombre)
      from periodo p
      join public.clientes c on c.id = p.cliente_id
      left join saldos s on s.cliente_id = p.cliente_id), '[]'::jsonb)
  ) into v_res;

  return v_res;
end $fn$;

revoke all on function public.fiado_del_periodo(uuid, date, date) from public, anon;
grant execute on function public.fiado_del_periodo(uuid, date, date) to authenticated;


-- ------------------------------------------------------------
-- 13. EL AVISO DEL DÍA (080) CON LA MISMA GANANCIA QUE EL PANEL
--
--    El push de la mañana («ayer ganaste X») y el de la noche calculan la
--    ganancia a mano: ventas + ingresos − costo − TODOS los gastos. Con los
--    arreglos 1 y 2 de arriba eso dejaba de coincidir con `/panel`: el día
--    que el almacén compra mercadería (con el costo cargado) o que la
--    barbería le paga a un barbero a comisión, el aviso decía «perdiste»
--    mientras el panel del mismo día decía que ganó.
--
--    No se puede llamar a `resumen_financiero` desde acá: la corrida es del
--    service_role, sin usuario, y el resumen pide sesión. Así que se aplica
--    la misma regla, con la bandera decidida para ESE día (el panel de «hoy»
--    y el de «ayer» son un período de un día):
--      · los pagos marcados `de_comision` no restan;
--      · la «Mercadería» no resta si ese día hubo costo cargado en ventas
--        que no son servicios del reparto.
--    `gastos` del aviso es el mismo número que muestra el panel ese día. Una
--    cuenta personal no tiene ventas con costo: ahí no cambia nada.
--    Copia EXACTA de la viva (080, verificada en producción el 24/09/2026
--    con pg_get_functiondef) salvo el bloque `a`. Misma firma y mismos
--    permisos (solo service_role).
-- ------------------------------------------------------------
create or replace function public.avisos_del_dia()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_res jsonb;
begin
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'empresa_id',  e.id,
      'nombre',      e.nombre,
      'moneda',      e.moneda,
      'tipo_cuenta', coalesce(e.tipo_cuenta, 'emprendedor'),
      'fecha',       z.hoy,
      'hoy', jsonb_build_object(
        'ventas', a.ventas_hoy, 'ingresos', a.ingresos_hoy, 'gastos', a.gastos_hoy,
        'ganancia', a.ventas_hoy + a.ingresos_hoy - a.costo_hoy - a.gastos_hoy,
        'cargados', a.n_hoy,
        'ahorros', h.n_ahorro_hoy),
      'ayer', jsonb_build_object(
        'ventas', a.ventas_ayer, 'ingresos', a.ingresos_ayer, 'gastos', a.gastos_ayer,
        'ganancia', a.ventas_ayer + a.ingresos_ayer - a.costo_ayer - a.gastos_ayer,
        'cargados', a.n_ayer),
      'racha', jsonb_build_object('dias', r.dias, 'en_riesgo', r.en_riesgo),
      'destinatarios', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'user_id', mi.user_id, 'idioma', coalesce(p.idioma, 'es'))), '[]'::jsonb)
        from public.miembros mi
        left join public.preferencias p on p.user_id = mi.user_id
        where mi.empresa_id = e.id
          and mi.rol in ('propietario', 'admin')
          and coalesce(p.aviso_diario, true)
      )
    ) as x
    from public.empresas e
    cross join lateral (
      select (now() at time zone coalesce(e.zona_horaria, 'America/Asuncion'))::date as hoy
    ) z
    cross join lateral (
      -- 106: los gastos de cada día con la regla del resumen (ver arriba).
      select b.*,
             b.gastos_todos_hoy - b.comision_hoy
               - case when b.costo_productos_hoy > 0 then b.mercaderia_hoy else 0 end   as gastos_hoy,
             b.gastos_todos_ayer - b.comision_ayer
               - case when b.costo_productos_ayer > 0 then b.mercaderia_ayer else 0 end as gastos_ayer
      from (
        select
          coalesce(sum(m.monto) filter (where m.fecha = z.hoy and m.tipo = 'venta'), 0)       as ventas_hoy,
          coalesce(sum(m.monto) filter (where m.fecha = z.hoy and m.tipo = 'ingreso'), 0)     as ingresos_hoy,
          coalesce(sum(m.monto) filter (where m.fecha = z.hoy and m.tipo = 'gasto'), 0)       as gastos_todos_hoy,
          coalesce(sum(coalesce(m.costo_total, 0)) filter (where m.fecha = z.hoy and m.tipo = 'venta'), 0) as costo_hoy,
          count(*) filter (where m.fecha = z.hoy)::int                                       as n_hoy,
          coalesce(sum(m.monto) filter (where m.fecha = z.hoy - 1 and m.tipo = 'venta'), 0)   as ventas_ayer,
          coalesce(sum(m.monto) filter (where m.fecha = z.hoy - 1 and m.tipo = 'ingreso'), 0) as ingresos_ayer,
          coalesce(sum(m.monto) filter (where m.fecha = z.hoy - 1 and m.tipo = 'gasto'), 0)   as gastos_todos_ayer,
          coalesce(sum(coalesce(m.costo_total, 0)) filter (where m.fecha = z.hoy - 1 and m.tipo = 'venta'), 0) as costo_ayer,
          count(*) filter (where m.fecha = z.hoy - 1)::int                                   as n_ayer,
          -- 106
          coalesce(sum(m.monto) filter (where m.fecha = z.hoy and m.es_comision), 0)         as comision_hoy,
          coalesce(sum(m.monto) filter (where m.fecha = z.hoy - 1 and m.es_comision), 0)     as comision_ayer,
          coalesce(sum(m.monto) filter (where m.fecha = z.hoy
                                          and m.es_mercaderia and not m.es_comision), 0)     as mercaderia_hoy,
          coalesce(sum(m.monto) filter (where m.fecha = z.hoy - 1
                                          and m.es_mercaderia and not m.es_comision), 0)     as mercaderia_ayer,
          coalesce(sum(coalesce(m.costo_total, 0)) filter (where m.fecha = z.hoy
                                          and m.tipo = 'venta' and not m.es_servicio), 0)    as costo_productos_hoy,
          coalesce(sum(coalesce(m.costo_total, 0)) filter (where m.fecha = z.hoy - 1
                                          and m.tipo = 'venta' and not m.es_servicio), 0)    as costo_productos_ayer
        from (
          select m.fecha, m.tipo, m.monto, m.costo_total,
                 (m.tipo = 'gasto' and public.es_categoria_mercaderia(m.categoria)) as es_mercaderia,
                 (m.tipo = 'gasto' and exists (
                    select 1 from public.turnos_pago tp
                    where tp.movimiento_id = m.id and tp.de_comision)) as es_comision,
                 (m.tipo = 'venta' and exists (
                    select 1 from public.turnos_atribucion ta
                    where ta.movimiento_id = m.id)) as es_servicio
          from public.movimientos m
          where m.empresa_id = e.id and m.estado = 'activo'
            and m.fecha between z.hoy - 1 and z.hoy
        ) m
      ) b
    ) a
    cross join lateral (
      select count(*)::int as n_ahorro_hoy
      from public.movimientos_ahorro ma
      where ma.empresa_id = e.id and ma.fecha = z.hoy
    ) h
    cross join lateral (
      with dias as (
        select d.fecha from public.dias_cargados(e.id, z.hoy) d(fecha)
      ),
      numeradas as (
        select fecha, (fecha - (row_number() over (order by fecha))::int) as isla
        from dias
      ),
      rachas as (
        select isla, count(*)::int as largo, max(fecha) as hasta
        from numeradas group by isla
      ),
      vigente as (
        select * from rachas where hasta in (z.hoy, z.hoy - 1) order by hasta desc limit 1
      )
      select
        coalesce((select largo from vigente), 0) as dias,
        coalesce((select hasta from vigente), z.hoy - 2) = z.hoy - 1 as en_riesgo
    ) r
    where (
        coalesce(e.tipo_cuenta, 'emprendedor') = 'personal'
        or public.rubro_cierra_el_dia(e.rubro, e.tipo_cuenta)
      )
      and public.puede_cargar(e.id)
      and (
        e.created_at > now() - interval '7 days'
        or exists (select 1 from public.movimientos m2
                   where m2.empresa_id = e.id and m2.created_at > now() - interval '30 days')
        or exists (select 1 from public.movimientos_ahorro a2
                   where a2.empresa_id = e.id and a2.created_at > now() - interval '30 days')
      )
  ) s;

  return v_res;
end $function$;

revoke all on function public.avisos_del_dia() from public, anon, authenticated;
grant execute on function public.avisos_del_dia() to service_role;


-- ############################################################
-- ##  107_aviso_de_vencimiento.sql
-- ############################################################

-- ============================================================
-- 107 · EL AVISO DE QUE SE VENCE EL PLAN
-- ============================================================
--
-- QUÉ PASABA
--
-- Orden avisaba una sola cosa sobre la plata de la suscripción: que la
-- PRUEBA se termina (`pruebas_por_terminar`, 071), y solo por push. Al que
-- ya PAGA no le decía nada: el día que se le vence el período, la cuenta se
-- corta (ver CandadoCuenta) y la persona se entera cuando ya no puede
-- cargar. Es el peor momento para enterarse, y es el cliente que más
-- cuidamos: el que ya confió y pagó.
--
-- Y el push, solo, no alcanza para algo que corta la cuenta: en iPhone llega
-- únicamente si Orden está en la pantalla de inicio (ver lib/avisos.ts,
-- «nunca puede ser el único canal de algo importante»).
--
-- QUÉ SE HACE
--
-- Una lectura nueva, `vencimientos_por_avisar()`, que contesta quién vence y
-- cuándo, con dos clases de vencimiento en la misma lista:
--
--   · 'periodo' → suscripción ACTIVA (paga) cuyo período termina en 3 días,
--     en 1 o hoy. Recibe push Y correo.
--   · 'prueba'  → suscripción en PRUEBA que termina en 3 días, en 1 o hoy.
--     El push ya lo manda `pruebas_por_terminar` (071, no se toca); acá se
--     suma el correo, que era lo que faltaba.
--
-- Los mismos tres momentos que la prueba (3, 1, 0): el primero da tiempo a
-- transferir, el segundo recuerda, el tercero es la última oportunidad. Dos
-- días antes no, para no escribirle todos los días.
--
-- Trae lo que hace falta para escribir el aviso sin otra consulta: el plan,
-- el período, la fecha de fin EN LA ZONA DEL NEGOCIO («vence mañana» tiene
-- que ser mañana para él), el precio y a quién escribirle (dueño y
-- administradores, con su idioma, su nombre y su correo).
--
-- EL PRECIO: EL DE LISTA, EN GUARANÍES
--
-- La suscripción se cobra siempre en guaraníes (decisión del 23/09, ver
-- 105), así que el precio sale de `precios` en PYG, para el tipo de cuenta,
-- el plan y el período de la suscripción (null → mensual). Es el precio de
-- lista: el descuento por constancia (079, 093) depende de la racha del día
-- en que paga y lo calcula la administración al cobrar, así que prometerlo
-- en un correo tres días antes podría ser mentira. Si no hay precio de lista
-- para esa combinación, `precio` es null y el aviso no dice ningún número:
-- nunca un «Gs. 0» que parezca dato.
--
-- A QUIÉN NO
--
--   · Plan 'gratis': no hay nada que pagar.
--   · `cancela_al_vencer`: la persona ya dijo que no renueva; pedirle que
--     pague contradice lo que eligió.
--   · Vendedores: el aviso trae precio y plan, que son cosas del dueño.
--   · La prueba ya vencida (`periodo_fin <= now()`): igual que la 071, para
--     que el push y el correo de la prueba salgan a las mismas cuentas. Al
--     período pago no se le pide eso: si vence hoy a las 6 y el aviso corre
--     a las 9, «vence hoy» sigue siendo verdad y es justo cuando más sirve.
--
-- EL RELOJ NO CAMBIA
--
-- No hace falta un trabajo nuevo de pg_cron: esto se lee en la corrida de
-- la mañana (`orden-avisos-manana`, 081 → /api/tareas/avisos-manana), la
-- misma que ya avisa las pruebas. Cada envío pasa por `reservar_envio`
-- (010), así que si Vercel y pg_cron disparan los dos, sale uno.
--
-- PERMISOS
--
-- Son los datos de todas las cuentas, con correos: solo service_role, como
-- `pruebas_por_terminar` y `avisos_del_dia`. Revocada a public, anon y
-- authenticated.
--
-- No hay mensajes nuevos: la función no lanza errores.
--
-- Idempotente: un `create or replace`, un revoke y un grant.
-- ============================================================

create or replace function public.vencimientos_por_avisar()
returns jsonb language plpgsql stable security definer set search_path = public as $fn$
declare v_res jsonb;
begin
  select coalesce(jsonb_agg(x order by (x->>'dias')::int, x->>'nombre'), '[]'::jsonb) into v_res
  from (
    select jsonb_build_object(
      'tipo',        case when s.estado = 'prueba' then 'prueba' else 'periodo' end,
      'empresa_id',  e.id,
      'nombre',      e.nombre,
      'tipo_cuenta', coalesce(e.tipo_cuenta, 'emprendedor'),
      'plan',        s.plan,
      'periodo',     coalesce(s.periodo, 'mensual'),
      'fin',         s.periodo_fin,
      -- La fecha en la zona del negocio: es la que se escribe en el aviso y
      -- la que arma la clave de «una vez por vencimiento».
      'fecha_fin',   (s.periodo_fin at time zone z.zona)::date,
      'dias',        d.dias,
      'moneda',      'PYG',
      'precio', (
        select pr.importe
        from public.precios pr
        where pr.tipo_cuenta = coalesce(e.tipo_cuenta, 'emprendedor')
          and pr.plan = s.plan
          and pr.periodo = coalesce(s.periodo, 'mensual')
          and pr.moneda = 'PYG'
          and pr.activo
        limit 1
      ),
      'destinatarios', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'user_id', mi.user_id,
          'idioma',  coalesce(p.idioma, 'es'),
          'nombre',  coalesce(mi.nombre, ''),
          'email',   u.email
        ) order by mi.rol desc, mi.created_at), '[]'::jsonb)
        from public.miembros mi
        left join public.preferencias p on p.user_id = mi.user_id
        left join auth.users u on u.id = mi.user_id
        where mi.empresa_id = e.id and mi.rol in ('propietario', 'admin')
      )
    ) as x
    from public.suscripciones s
    join public.empresas e on e.id = s.empresa_id
    cross join lateral (
      select coalesce(e.zona_horaria, 'America/Asuncion') as zona
    ) z
    cross join lateral (
      select (s.periodo_fin at time zone z.zona)::date
             - (now() at time zone z.zona)::date as dias
    ) d
    where s.periodo_fin is not null
      and d.dias in (0, 1, 3)
      and (
        (s.estado = 'prueba' and s.periodo_fin > now())
        or (s.estado = 'activa'
            and s.plan <> 'gratis'
            and not coalesce(s.cancela_al_vencer, false))
      )
  ) t;

  return v_res;
end $fn$;

revoke all on function public.vencimientos_por_avisar() from public, anon, authenticated;
grant execute on function public.vencimientos_por_avisar() to service_role;


-- ############################################################
-- ##  108_clases_en_grupo.sql
-- ############################################################

-- ============================================================
-- 108 · LA CLASE EN GRUPO
-- ============================================================
--
-- Matías (24/09): «una clase de tenis tiene varios alumnos en el mismo
-- horario. Yo quiero agregar a un alumno en el mismo horario de otra persona
-- y no me permite».
--
-- QUÉ PASABA
--
-- `inscribir_alumno` (091, 094, 095) rechaza cualquier inscripción que se
-- pise con una clase pendiente o confirmada de la cuenta: «El 05/10 a las
-- 18:00 ya tenés a Ana». Para un profe particular está bien —da una clase a
-- la vez, y el aviso le evita anotar dos alumnos a la misma hora sin
-- querer—. Para una clase de tenis, de natación, de baile o un grupo de
-- entrenamiento es justo al revés: van varios a la misma hora.
--
-- QUÉ SE HACE
--
-- El choque sigue avisándose igual (la vista previa no cambia), pero deja de
-- ser un muro: `inscribir_alumno` suma `p_en_grupo`. Con `true`, el profe
-- ya vio con quién coincide y dijo «van juntos»; cada alumno queda con su
-- propia clase en la agenda a la misma hora, con su inscripción, su cobro y
-- su asistencia, como hasta ahora. Sin él (o con `false`), todo sigue
-- como antes: un horario ocupado frena la inscripción entera.
--
-- No hay cupo: el profe sabe cuántos entran en su cancha. Si algún día lo
-- pide, va en otra migración.
--
-- El resto de la función es copia exacta de la 095. Se borra la versión de
-- 14 parámetros para que PostgREST no quede con dos candidatas; las
-- llamadas de 12, 13 y 14 parámetros siguen andando por los defaults.

drop function if exists public.inscribir_alumno(uuid, uuid, smallint[], time, time, date, date, numeric, numeric, boolean, text, text, text, uuid);

create or replace function public.inscribir_alumno(
  p_empresa     uuid,
  p_cliente     uuid,
  p_dias        smallint[],
  p_hora_desde  time,
  p_hora_hasta  time,
  p_desde       date,
  p_hasta       date,
  p_precio_hora numeric default null,
  p_total       numeric default null,
  p_pagado      boolean default false,
  p_metodo      text default 'efectivo',
  p_nombre      text default null,
  p_materia     text default null,
  p_cuenta      uuid default null,
  -- La clase en grupo (108): el profe ya vio con quién coincide y dijo que
  -- van juntos. Sin esto, un horario ocupado sigue frenando todo.
  p_en_grupo    boolean default false
)
returns jsonb language plpgsql security definer set search_path = public as $fn$
declare
  v_alumno   record;
  v_zona     text;
  v_previa   jsonb;
  v_choque   jsonb;
  v_base     jsonb;
  v_id       uuid;
  v_mov      uuid;
  v_total    numeric;
begin
  if not public.es_miembro(p_empresa) then
    raise exception 'No pertenecés a esta empresa.' using errcode = '42501';
  end if;

  select id, nombre, coalesce(telefono, '') as telefono into v_alumno
  from public.clientes where id = p_cliente and empresa_id = p_empresa;
  if v_alumno.id is null then
    raise exception 'Ese alumno no es de esta cuenta.' using errcode = 'P0002';
  end if;

  if p_dias is null or cardinality(p_dias) = 0
     or exists (select 1 from unnest(p_dias) d where d not between 0 and 6) then
    raise exception 'Elegí al menos un día de la semana.' using errcode = '22023';
  end if;

  if p_hora_desde is null or p_hora_hasta is null or p_hora_hasta <= p_hora_desde then
    raise exception 'La clase tiene que terminar después de empezar.' using errcode = '22023';
  end if;

  if p_desde is null or p_hasta is null or p_hasta < p_desde then
    raise exception 'El período tiene que terminar después de empezar.' using errcode = '22023';
  end if;

  if p_hasta > p_desde + 366 then
    raise exception 'Se puede inscribir hasta un año de una vez.' using errcode = '22023';
  end if;

  if p_total is null and p_precio_hora is null then
    raise exception 'Poné cuánto cobrás: por hora o un precio cerrado.' using errcode = '22023';
  end if;

  if coalesce(p_total, 0) < 0 or coalesce(p_precio_hora, 0) < 0 then
    raise exception 'El precio no puede ser negativo.' using errcode = '22023';
  end if;

  v_previa := public.vista_previa_inscripcion(
    p_empresa, p_dias, p_hora_desde, p_hora_hasta, p_desde, p_hasta, p_precio_hora, p_total);

  if (v_previa->>'clases')::int = 0 then
    raise exception 'En ese período no cae ningún día de los que elegiste.' using errcode = '22023';
  end if;

  v_choque := v_previa->'choques'->0;
  if v_choque is not null and not coalesce(p_en_grupo, false) then
    raise exception 'El % a las % ya tenés a %.',
      to_char((v_choque->>'fecha')::date, 'DD/MM'), v_choque->>'hora', v_choque->>'alumno'
      using errcode = '23P01';
  end if;

  v_total := (v_previa->>'total')::numeric;
  v_base  := public.profe_y_clase(p_empresa);
  select coalesce(zona_horaria, 'America/Asuncion') into v_zona from public.empresas where id = p_empresa;

  insert into public.paquetes (
    empresa_id, cliente_id, nombre, clases, precio, vence_el, creado_por,
    dias, hora_desde, hora_hasta, desde, precio_hora, materia)
  values (
    p_empresa, p_cliente,
    left(coalesce(nullif(trim(p_nombre), ''), 'Clases'), 80),
    (v_previa->>'clases')::numeric, v_total, p_hasta, auth.uid(),
    (select array_agg(distinct d order by d) from unnest(p_dias) d),
    p_hora_desde, p_hora_hasta, p_desde,
    case when p_total is null then p_precio_hora end,
    nullif(left(trim(coalesce(p_materia, '')), 60), ''))
  returning id into v_id;

  insert into public.turnos_reserva (
    empresa_id, profesional_id, producto_id, inicia, termina,
    cliente_nombre, cliente_telefono, cliente_id, paquete_id, estado, origen, creada_por)
  select
    p_empresa, (v_base->>'profesional')::uuid, (v_base->>'producto')::uuid,
    (f.d + p_hora_desde) at time zone v_zona,
    (f.d + p_hora_hasta) at time zone v_zona,
    v_alumno.nombre, v_alumno.telefono, p_cliente, v_id, 'confirmada', 'local', auth.uid()
  from public.fechas_de_horario(p_dias, p_desde, p_hasta) f(d);

  if coalesce(p_pagado, false) and v_total > 0 then
    v_mov := (public.cobrar_inscripcion(v_id, p_metodo, null, p_cuenta)->>'movimiento')::uuid;
  end if;

  return jsonb_build_object(
    'paquete', v_id, 'clases', (v_previa->>'clases')::int, 'total', v_total, 'movimiento', v_mov);
end $fn$;

revoke all on function public.inscribir_alumno(uuid, uuid, smallint[], time, time, date, date, numeric, numeric, boolean, text, text, text, uuid, boolean) from public, anon;
grant execute on function public.inscribir_alumno(uuid, uuid, smallint[], time, time, date, date, numeric, numeric, boolean, text, text, text, uuid, boolean) to authenticated;
